          }

          /* --- 其他元素的样式 --- */

          /* 正常显示的日期部分的样式 */
          .task-deadline-wrapper {
          }

          /* 日期值的样式 */
          .task-date-value {
            margin-right: 4px;
            margin-left: 4px;
          }

          .codespan:not(.pseudo-node) {
            background-color: #ebecec;
            color: #bc4e3a !important;
            font-size: calc(1em - 2px);
            border-radius: 4px;
            padding: 2px 6px;
            margin: 0 2px;
            font-family: SourceCodePro, monospace;
          }

          .codespan:not(.pseudo-node).highlight-red,
          .codespan:not(.pseudo-node).highlight-yellow,
          .codespan:not(.pseudo-node).highlight-pink,
          .codespan:not(.pseudo-node).highlight-blue,
          .codespan:not(.pseudo-node).highlight-cyan,
          .codespan:not(.pseudo-node).highlight-olive,
          .codespan:not(.pseudo-node).highlight-grey {
            background-color: #ebecec;
          }

          .codespan:not(.pseudo-node).text-color-red,
          .codespan:not(.pseudo-node).text-color-green,
          .codespan:not(.pseudo-node).text-color-blue,
          .codespan:not(.pseudo-node).text-color-purple,
          .codespan:not(.pseudo-node).text-color-yellow {
            color: #bc4e3a !important;
          }

          @media print {
            body {
              margin-top: 0;
              margin-bottom: 0;
            }
          }

          @page {
            margin-left: 0.25in;
            margin-right: 0.25in;
            margin-top: 0.5in;
            margin-bottom: 0.5in;
          }
        </style>
