INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000003', 'source-doc-4c784a84a66adf221597', 'source-node-000002', '2', '2', 'text', '杀虫剂', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000004', 'source-doc-4c784a84a66adf221597', 'source-node-000003', '3', '3', 'text', '1. 苏云金杆菌（Bacillus thuringiensis，简称Bt）：（革兰氏阳性细菌，通过产生伴孢晶体毒素（Cry蛋白）破坏害虫肠道黏膜，导致幼虫麻痹死亡；专一性强，仅对鳞翅目幼虫（如菜青虫、玉米螟、棉铃虫）有效，对蜜蜂、鸟类、天敌及人类安全；适用于蔬菜、玉米、棉花、果树等作物，需在害虫低龄幼虫期施用，对家蚕高毒，禁止在桑园周边使用）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000005', 'source-doc-4c784a84a66adf221597', 'source-node-000003', '3', '4', 'text', '2. 白僵菌（Beauveria bassiana）：（丝状真菌，通过孢子附着害虫体表萌发侵入体内，分泌毒素破坏体液和器官，使害虫僵死（体表覆白色菌丝）；防治谱广，对鳞翅目（如斜纹夜蛾）、鞘翅目（如蚜虫、金龟子）、同翅目害虫及地下害虫（如蛴螬）有效；适用于蔬菜、果树、林业，需在20-28℃、湿度80%以上环境使用，对蜜蜂低毒，与化学农药间隔7天使用以避免杀真菌作用）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000006', 'source-doc-4c784a84a66adf221597', 'source-node-000003', '3', '5', 'text', '3. 绿僵菌（Metarhizium anisopliae）：（丝状真菌，作用机制同白僵菌，孢子侵入后在害虫体内繁殖并产生绿僵菌素；对鞘翅目害虫（如叩头虫、天牛）、半翅目（如飞虱）及地下害虫（如地老虎）特效；适用于花生、大豆、林业，耐高温能力优于白僵菌，持效期15-20天，对水生生物低毒，避免污染水域）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000007', 'source-doc-4c784a84a66adf221597', 'source-node-000003', '3', '6', 'text', '4. 棉铃虫核型多角体病毒（Helicoverpa armigera Nucleopolyhedrovirus，简称HaNPV）：（杆状病毒，专一寄生棉铃虫幼虫，病毒粒子通过口器进入肠道后复制，破坏细胞导致害虫死亡；仅对棉铃虫有效，无交叉抗性，持效期长（20-30天），可在棉铃虫产卵高峰期施用；适用于棉花、番茄、辣椒，对天敌、蜜蜂及人类完全安全，低温（15℃以下）会降低病毒活性）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000008', 'source-doc-4c784a84a66adf221597', 'source-node-000003', '3', '7', 'text', '5. 斜纹夜蛾核型多角体病毒（Spodoptera litura Nucleopolyhedrovirus，简称SpltNPV）：（杆状病毒，专一寄生斜纹夜蛾幼虫，作用机制同HaNPV；对斜纹夜蛾各龄幼虫均有效，尤其低龄幼虫致死率高，施药后害虫会停止取食（24小时内），3-5天死亡；适用于蔬菜（白菜、甘蓝）、花生，对其他生物无毒性，可与Bt混用增强防效）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000009', 'source-doc-4c784a84a66adf221597', 'source-node-000003', '3', '8', 'text', '6. 印楝素（Azadirachtin）：（从印楝树种子中提取的植物源活性成分，通过干扰害虫内分泌系统，抑制蜕皮激素合成，导致幼虫蜕皮失败、成虫不育；广谱高效，对鳞翅目（如小菜蛾）、半翅目（如蚜虫）、缨翅目（如蓟马）及螨类有效；适用于蔬菜、果树、茶叶，持效期10-15天，对蜜蜂、天敌安全，强光会加速降解，建议傍晚施用）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000010', 'source-doc-4c784a84a66adf221597', 'source-node-000003', '3', '9', 'text', '7. 苦参碱（Matrine）：（从豆科植物苦参、苦豆子中提取的生物碱，兼具触杀、胃毒作用，通过破坏害虫细胞膜通透性、抑制神经传导导致死亡；广谱性，对蚜虫、粉虱、红蜘蛛、菜青虫、地下害虫（如根结线虫）均有效；适用于蔬菜、果树、中药材，低毒无残留，可在采收前7天使用，对鱼类低毒但避免大量流入水域）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000011', 'source-doc-4c784a84a66adf221597', 'source-node-000003', '3', '10', 'text', '8. 鱼藤酮（Rotenone）：（从豆科植物鱼藤根中提取的异黄酮类化合物，作用于害虫线粒体电子传递链，阻断能量代谢导致死亡；触杀、胃毒作用强，对蚜虫、蓟马、跳甲、菜青虫特效；适用于蔬菜、果树、观赏植物，持效期短（5-7天），易被光和空气分解，对鱼类、蜜蜂高毒，禁止在鱼塘、蜂场周边使用）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000012', 'source-doc-4c784a84a66adf221597', 'source-node-000003', '3', '11', 'text', '9. 除虫菊素（Pyrethrins）：（从除虫菊花朵中提取的酯类化合物，作用于害虫钠离子通道，导致神经传导紊乱、麻痹死亡；触杀作用极强，对蚜虫、粉虱、叶蝉、蚊蝇等卫生害虫及农业害虫均有效；适用于蔬菜、果树、茶叶及卫生领域，持效期短（3-5天），对蜜蜂、家蚕高毒，高温下易分解，建议低温时段施用）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000013', 'source-doc-4c784a84a66adf221597', 'source-node-000003', '3', '12', 'text', '10. 阿维菌素（Abamectin）：（由链霉菌（Streptomyces avermitilis）发酵产生的大环内酯类化合物，作用于害虫γ-氨基丁酸（GABA）受体，抑制神经信号传递；对螨类（如红蜘蛛、锈壁虱）、鳞翅目幼虫（如小菜蛾）、根结线虫特效，兼具触杀、胃毒作用；适用于蔬菜、果树、棉花，对鱼类、蜜蜂高毒，禁止污染水域和花期作物，长期使用易产生抗性需轮换）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000014', 'source-doc-4c784a84a66adf221597', 'source-node-000003', '3', '13', 'text', '11. 多杀霉素（Spinosad）：（由刺糖多孢菌（Saccharopolyspora spinosa）发酵产生的大环内酯类化合物，作用于害虫烟碱乙酰胆碱受体和GABA受体，导致神经兴奋过度死亡；对鳞翅目幼虫（如甜菜夜蛾、棉铃虫）、蓟马、果蝇特效；适用于蔬菜、果树、棉花，对蜜蜂低毒（接触毒性低，摄入需注意），对鱼类中等毒性，持效期10-14天，与阿维菌素无交互抗性）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000015', 'source-doc-4c784a84a66adf221597', 'source-node-000003', '3', '14', 'text', '12. 弥拜菌素（Milbemectin）：（阿维菌素类衍生物，由链霉菌发酵产生，作用机制同阿维菌素，对螨类（如红蜘蛛）、粉虱、蚜虫及小型鳞翅目幼虫有效；适用于果树、蔬菜，安全性优于阿维菌素，对蜜蜂低毒，对鱼类中等毒性，持效期15天左右，可用于抗性螨类防治）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000016', 'source-doc-4c784a84a66adf221597', 'source-node-000003', '3', '15', 'text', '13. 赤眼蜂（Trichogramma）：（寄生性天敌昆虫，通过将卵产在鳞翅目害虫（如玉米螟、稻纵卷叶螟、棉铃虫）卵内，幼虫以害虫卵液为食，导致害虫卵不能孵化；专一性寄生卵期害虫，防治效率高，一次释放持效期20-30天；适用于玉米、水稻、棉花、果树，需在害虫产卵初期释放，避免与广谱杀虫剂同时使用，低温（10℃以下）会影响成虫活动）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000017', 'source-doc-4c784a84a66adf221597', 'source-node-000003', '3', '16', 'text', '14. 瓢虫（如七星瓢虫、异色瓢虫）：（捕食性天敌昆虫，成虫和幼虫均以蚜虫、粉虱、介壳虫、叶螨等小型刺吸式害虫为食，一只七星瓢虫成虫每天可捕食蚜虫50-100头；适用于蔬菜、果树、小麦、棉花，可人工释放或通过种植蜜源植物（如波斯菊）吸引自然繁殖；对化学农药敏感，释放后需避免使用触杀性农药）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000018', 'source-doc-4c784a84a66adf221597', 'source-node-000003', '3', '17', 'text', '15. 斜纹夜蛾性信息素（Spodoptera litura Sex Pheromone）：（人工合成的模仿斜纹夜蛾雌蛾分泌的性引诱物质，通过干扰雄蛾寻找雌蛾，阻断交配过程，降低害虫种群密度；专一性极强，仅对斜纹夜蛾雄蛾有效，无毒性、无残留；适用于蔬菜、花生、大豆，需配合诱捕器使用，在害虫发生初期开始设置，连片使用防效更佳，对其他生物无任何影响）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000019', 'source-doc-4c784a84a66adf221597', 'source-node-000003', '3', '18', 'text', '16. 小菜蛾性信息素（Plutella xylostella Sex Pheromone）：（人工合成的小菜蛾雌蛾性引诱剂，作用机制同斜纹夜蛾性信息素，针对小菜蛾雄蛾；适用于十字花科蔬菜（白菜、甘蓝、萝卜），持效期30-45天，可减少化学农药使用量50%以上，与Bt、多杀霉素等生物制剂混用可实现“诱杀+毒杀”协同防效）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000020', 'source-doc-4c784a84a66adf221597', 'source-node-000003', '3', '19', 'text', '17. 春雷霉素（Kasugamycin）：（虽主要为杀菌剂，但兼具一定杀虫活性，由链霉菌发酵产生，对蓟马、粉虱等刺吸式害虫有抑制取食作用，通过干扰害虫肠道菌群和代谢实现防效；适用于水稻、蔬菜、果树，对蜜蜂、天敌安全，可与苦参碱混用增强杀虫效果，对鱼类低毒）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000021', 'source-doc-4c784a84a66adf221597', 'source-node-000003', '3', '20', 'text', '18. 蜡质芽孢杆菌（Bacillus cereus）：（革兰氏阳性细菌，通过分泌抗菌物质和竞争营养，抑制害虫肠道内有益菌群，同时可诱导作物产生抗性；对地下害虫（如蛴螬、根腐线虫）及地上刺吸式害虫（如蚜虫）有效；适用于花生、大豆、蔬菜，可沟施或灌根，持效期25-30天，对环境和有益生物无危害）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000022', 'source-doc-4c784a84a66adf221597', 'source-node-000002', '2', '21', 'text', '杀菌剂', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000023', 'source-doc-4c784a84a66adf221597', 'source-node-000022', '3', '22', 'text', '中生菌素制剂：（由放线菌 “淡紫灰链霉菌海南变种” 发酵产生的氨基糖苷类抗生素，通过抑制病原菌蛋白质合成，破坏细菌细胞膜完整性），主打防治细菌性病害，如白菜软腐病、黄瓜细菌性角斑病、水稻白叶枯病、番茄青枯病、柑橘溃疡病，对部分低等真菌病害（如马铃薯晚疫病）也有辅助防效，适用于蔬菜、果树、大田作物，需避免与碱性药剂混用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000024', 'source-doc-4c784a84a66adf221597', 'source-node-000022', '3', '23', 'text', '侧孢短芽孢杆菌制剂：（源自土壤中的短芽孢杆菌属细菌，通过竞争病原菌营养空间、分泌抗菌活性物质（如短芽孢杆菌素），同时能诱导作物产生系统抗性，兼具促生根系作用），主要防治土传真菌病害，如番茄枯萎病、黄瓜根腐病、辣椒疫病、花生根腐病，对大豆根腐病、西瓜蔓枯病也有良好防效，适合连作障碍田块 “拌种 + 灌根” 使用，对作物安全性极高。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000025', 'source-doc-4c784a84a66adf221597', 'source-node-000022', '3', '24', 'text', '枯草芽孢杆菌制剂：（核心来源为土壤及植物体表益生菌，通过竞争营养、分泌抗菌肽 / 几丁质酶抑制病原菌，且能促生作物根系），主要防治黄瓜白粉病、葡萄霜霉病、番茄根腐病、西瓜枯萎病等，适用于各类瓜果、蔬菜及大田作物，可叶面喷雾或土壤处理。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000026', 'source-doc-4c784a84a66adf221597', 'source-node-000022', '3', '25', 'text', '解淀粉芽孢杆菌制剂：（与枯草芽孢杆菌同属芽孢杆菌属，但抗菌谱更侧重真菌性叶部病害，可诱导作物系统抗性），重点防治草莓灰霉病、辣椒疫病、水稻稻曲病、小麦白粉病，对作物安全性高，适合绿色农产品种植。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000027', 'source-doc-4c784a84a66adf221597', 'source-node-000022', '3', '26', 'text', '蜡质芽孢杆菌制剂：（源自植物根际共生细菌，核心作用是激活作物免疫应答、分泌抑菌物质），适用于防治西瓜细菌性角斑病、水稻纹枯病、玉米大斑病、油菜菌核病，尤其对细菌性病害防效突出。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000028', 'source-doc-4c784a84a66adf221597', 'source-node-000022', '3', '27', 'text', '荧光假单胞杆菌制剂：（根际促生细菌，通过分泌嗜铁素争夺铁元素、产生 2,4 - 二乙酰基间苯三酚等抗生素），主打防治土传病害，如花生青枯病、黄瓜枯萎病、甜瓜蔓枯病、烟草黑胫病，同时可改善土壤微环境。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000029', 'source-doc-4c784a84a66adf221597', 'source-node-000022', '3', '28', 'text', '哈茨木霉菌制剂：（真菌类生防制剂，通过重寄生作用缠绕病原菌菌丝、分泌溶菌酶及抗菌蛋白），主要防治黄瓜枯萎病、番茄灰霉病、草莓根腐病、花卉白粉病，对连作田土传病害有显著改良效果。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000030', 'source-doc-4c784a84a66adf221597', 'source-node-000022', '3', '29', 'text', '绿色木霉菌制剂：（与哈茨木霉菌功能相近，但更适配高湿环境，可抑制病原菌孢子萌发），适用于温室大棚作物，如辣椒疫病、茄子黄萎病、芹菜斑枯病，以及大田作物水稻恶苗病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000031', 'source-doc-4c784a84a66adf221597', 'source-node-000022', '3', '30', 'text', '淡紫拟青霉制剂：（虽以防治线虫为主，但可分泌抑菌物质抑制土传病原菌，形成 “杀线 + 防病” 协同作用），辅助防治大豆根腐病、黄瓜枯萎病、西瓜蔓枯病，尤其适合线虫与土传病害混发田块。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000032', 'source-doc-4c784a84a66adf221597', 'source-node-000022', '3', '31', 'text', '黏帚霉制剂：（从健康植株根际分离的真菌，核心功能是降解病原菌毒素、抑制菌核萌发），主要用于防治油菜菌核病、大豆灰斑病、蔬菜灰霉病、苹果腐烂病，对病原菌的 “休眠体”（如菌核）防效显著。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000033', 'source-doc-4c784a84a66adf221597', 'source-node-000022', '3', '32', 'text', '春雷霉素制剂：（放线菌 “小金色链霉菌” 发酵产生的抗生素，作用于病原菌核糖体，抑制蛋白质合成），专一防治细菌性病害（如水稻稻瘟病、番茄青枯病、柑橘溃疡病）及部分低等真菌病害（如马铃薯晚疫病）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000034', 'source-doc-4c784a84a66adf221597', 'source-node-000022', '3', '33', 'text', '井冈霉素制剂：（放线菌 “吸水链霉菌井冈变种” 代谢产物，抑制病原菌细胞壁合成），是水稻纹枯病、玉米纹枯病的特效制剂，对小麦纹枯病、甘蔗凤梨病也有良好防效，持效期可达 15-20 天。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000035', 'source-doc-4c784a84a66adf221597', 'source-node-000022', '3', '34', 'text', '多抗霉素制剂：（放线菌 “可可链霉菌阿苏亚种” 产生的肽类抗生素，破坏病原菌细胞膜完整性），主要防治苹果斑点落叶病、黄瓜霜霉病、烟草赤星病、葡萄白腐病，对叶部细嫩组织安全性高。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000036', 'source-doc-4c784a84a66adf221597', 'source-node-000022', '3', '35', 'text', '农用链霉素制剂：（放线菌 “灰色链霉菌” 发酵产物，针对细菌细胞壁合成起效），用于防治细菌性病害，如黄瓜细菌性角斑病、白菜软腐病、水稻白叶枯病、番茄溃疡病，需严格遵守安全间隔期，避免滥用导致抗药性。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000037', 'source-doc-4c784a84a66adf221597', 'source-node-000022', '3', '36', 'text', '嘧啶核苷类抗生素（农抗 120）制剂：（放线菌 “吸水链霉菌北京变种” 代谢产物，抑制病原菌黑色素合成及酶活性），主要防治真菌性病害，如西瓜炭疽病、番茄早疫病、小麦锈病、花卉炭疽病，同时可促进作物生长。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000038', 'source-doc-4c784a84a66adf221597', 'source-node-000022', '3', '37', 'text', '蛭弧菌制剂：（寄生并裂解有害细菌的 “细菌天敌”，对革兰氏阴性菌特效），用于防治细菌性土传病害，如番茄青枯病、辣椒青枯病、马铃薯环腐病，适合连作障碍严重的棚室作物。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000039', 'source-doc-4c784a84a66adf221597', 'source-node-000022', '3', '38', 'text', '地衣芽孢杆菌制剂：（芽孢杆菌属中抗逆性较强的品种，通过分泌几丁质酶、抗菌脂肽抑制病原菌，且能耐受极端温湿度），主要防治黄瓜白粉病、番茄灰霉病、小麦纹枯病、花生叶斑病，适用于高海拔、高温高湿等特殊气候区域作物。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000040', 'source-doc-4c784a84a66adf221597', 'source-node-000022', '3', '39', 'text', '寡雄腐霉菌M1：寄生降解疫霉菌、腐霉菌，防烟草黑胫病、番茄晚疫病，诱导植物抗性。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000041', 'source-doc-4c784a84a66adf221597', 'source-node-000022', '3', '40', 'text', '贝莱斯芽孢杆菌BJ-2：分泌脂肽类抗生素，防辣椒疫病、番茄晚疫病，促根系发育。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000042', 'source-doc-4c784a84a66adf221597', 'source-node-000022', '3', '41', 'text', '绿色木霉菌LTR-2：降解病原菌细胞壁，防猝倒病、根腐病，适用于设施农业。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000043', 'source-doc-4c784a84a66adf221597', 'source-node-000001', '1', '42', 'text', '化学制剂', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000044', 'source-doc-4c784a84a66adf221597', 'source-node-000043', '2', '43', 'text', '保护性', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000045', 'source-doc-4c784a84a66adf221597', 'source-node-000044', '3', '44', 'text', '抑菌剂', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000046', 'source-doc-4c784a84a66adf221597', 'source-node-000044', '3', '45', 'text', '病毒抑制剂', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000047', 'source-doc-4c784a84a66adf221597', 'source-node-000043', '2', '46', 'text', '治疗性', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000048', 'source-doc-4c784a84a66adf221597', 'source-node-000047', '3', '47', 'text', '杀菌剂', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000049', 'source-doc-4c784a84a66adf221597', 'source-node-000048', '4', '48', 'text', '真菌', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000050', 'source-doc-4c784a84a66adf221597', 'source-node-000049', '5', '49', 'text', '高等真菌', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000051', 'source-doc-4c784a84a66adf221597', 'source-node-000050', '6', '50', 'text', '三唑类', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000052', 'source-doc-4c784a84a66adf221597', 'source-node-000051', '7', '51', 'text', '戊唑醇：抑制麦角甾醇合成，内吸性强，防治小麦白粉病、苹果轮纹病，瓜类苗期敏感。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000053', 'source-doc-4c784a84a66adf221597', 'source-node-000051', '7', '52', 'text', '苯醚甲环唑：保护兼治疗，适用于葡萄白粉病、番茄早疫病，安全性高。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000054', 'source-doc-4c784a84a66adf221597', 'source-node-000051', '7', '53', 'text', '丙环唑：向上传导性强，防治水稻纹枯病、香蕉叶斑病，抑制植株徒长。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000055', 'source-doc-4c784a84a66adf221597', 'source-node-000051', '7', '54', 'text', '氟硅唑：速效治疗梨黑星病、番茄叶霉病，幼果期慎用防畸形。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000056', 'source-doc-4c784a84a66adf221597', 'source-node-000051', '7', '55', 'text', '己唑醇：抑制生长作用较弱，主治水稻纹枯病、小麦锈病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000057', 'source-doc-4c784a84a66adf221597', 'source-node-000051', '7', '56', 'text', '三唑酮：双向传导，防治白粉病、锈病，拌种可能延迟出苗。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000058', 'source-doc-4c784a84a66adf221597', 'source-node-000051', '7', '57', 'text', '烯唑醇：高效广谱，防治白粉病、锈病、黑星病，可能抑制植物生长。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000059', 'source-doc-4c784a84a66adf221597', 'source-node-000050', '6', '58', 'text', '甲氧基丙烯酸酯类', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000060', 'source-doc-4c784a84a66adf221597', 'source-node-000059', '7', '59', 'text', '嘧菌酯：广谱内吸，防治小麦锈病、水稻稻瘟病，抗药性风险高。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000061', 'source-doc-4c784a84a66adf221597', 'source-node-000059', '7', '60', 'text', '吡唑醚菌酯：渗透性强，防治黄瓜白粉病、香蕉叶斑病，需控制使用次数。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000062', 'source-doc-4c784a84a66adf221597', 'source-node-000059', '7', '61', 'text', '啶氧菌酯：木质部传导，专治小麦叶枯病、葡萄霜霉病，需复配延缓抗性。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000063', 'source-doc-4c784a84a66adf221597', 'source-node-000050', '6', '62', 'text', 'SDHI 类（琥珀酸脱氢酶抑制剂）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000064', 'source-doc-4c784a84a66adf221597', 'source-node-000063', '7', '63', 'text', '氟唑菌酰胺：防治大豆锈病、小麦赤霉病，需严格控量防药害。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000065', 'source-doc-4c784a84a66adf221597', 'source-node-000063', '7', '64', 'text', '氟吡菌酰胺：内吸治疗土传病，主治西瓜蔓枯病、黄瓜靶斑病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000066', 'source-doc-4c784a84a66adf221597', 'source-node-000063', '7', '65', 'text', '啶酰菌胺：灰霉病、菌核病特效，作用于线粒体呼吸链。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000067', 'source-doc-4c784a84a66adf221597', 'source-node-000063', '7', '66', 'text', '氟唑菌酰羟胺（ADEPIDYN® 技术）：防治小麦赤霉病、叶枯病，持效期长达 35 天，全球 55 国登记Syngenta Group。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000068', 'source-doc-4c784a84a66adf221597', 'source-node-000050', '6', '67', 'text', '其他作用机制', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000069', 'source-doc-4c784a84a66adf221597', 'source-node-000068', '7', '68', 'text', '噻呋酰胺：噻唑酰胺类，强内吸传导，主治水稻纹枯病、立枯病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000070', 'source-doc-4c784a84a66adf221597', 'source-node-000068', '7', '69', 'text', '咪鲜胺：咪唑类，防治炭疽病、白粉病，兼具保护和铲除作用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000071', 'source-doc-4c784a84a66adf221597', 'source-node-000068', '7', '70', 'text', '菌核净：防治菌核病、灰霉病，有一定内吸治疗作用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000072', 'source-doc-4c784a84a66adf221597', 'source-node-000068', '7', '71', 'text', '噁唑菌酮：兼具保护和治疗，防治白粉病、锈病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000073', 'source-doc-4c784a84a66adf221597', 'source-node-000068', '7', '72', 'text', '乙嘧酚：白粉病特效，抑制黑色素合成，花期可用且安全性高。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000074', 'source-doc-4c784a84a66adf221597', 'source-node-000068', '7', '73', 'text', '腐霉利：灰霉病、菌核病特效，作用于菌丝分裂阶段。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000075', 'source-doc-4c784a84a66adf221597', 'source-node-000068', '7', '74', 'text', '异菌脲：广谱防治灰霉病、菌核病，干扰病原菌能量代谢。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000076', 'source-doc-4c784a84a66adf221597', 'source-node-000049', '5', '75', 'text', '低等真菌', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000077', 'source-doc-4c784a84a66adf221597', 'source-node-000076', '6', '76', 'text', '氨基甲酸酯类', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000078', 'source-doc-4c784a84a66adf221597', 'source-node-000077', '7', '77', 'text', '霜霉威：局部内吸，抑制病原菌细胞膜合成，防黄瓜霜霉病、番茄晚疫病，促根系发育，常与氟吡菌胺复配，安全间隔期2-3天。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000079', 'source-doc-4c784a84a66adf221597', 'source-node-000076', '6', '78', 'text', '噁唑类', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000080', 'source-doc-4c784a84a66adf221597', 'source-node-000079', '7', '79', 'text', '恶霉灵：内吸性土壤消毒杀菌剂，通过抑制低等真菌（卵菌纲）DNA/RNA合成起效，对猝倒病、立枯病、根腐病等土传病害特效，兼具促进作物根系发育作用；幼苗期需高倍稀释，忌与碱性药剂混用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000081', 'source-doc-4c784a84a66adf221597', 'source-node-000079', '7', '80', 'text', '精甲·恶霉灵：精甲霜灵干扰RNA合成、恶霉灵内吸传导，兼具保护与治疗作用；防治辣椒猝倒病、草坪枯萎病，可促根系发育；稀释750-1000倍喷雾或灌根，安全间隔期3天。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000082', 'source-doc-4c784a84a66adf221597', 'source-node-000079', '7', '81', 'text', '恶霉·福美双：恶霉灵抑制病原菌核酸合成，福美双干扰能量代谢；防治黄瓜枯萎病、西瓜根腐病，800-1000倍液灌根（每株300毫升），安全间隔期15天，忌与碱性药剂混用，福美双不能和含金属离子的农药混配。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000083', 'source-doc-4c784a84a66adf221597', 'source-node-000079', '7', '82', 'text', '甲霜·恶霉灵：甲霜灵双向传导、恶霉灵内吸性强，协同防治根腐病、猝倒病、疫病；兼具促根作用，稀释800-1000倍灌根或1500倍叶面喷雾，可与非碱性农药混用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000084', 'source-doc-4c784a84a66adf221597', 'source-node-000079', '7', '83', 'text', '恶霉·络氨铜：恶霉灵抑制病原菌DNA合成，络氨铜以铜离子凝固病菌蛋白质；防治烟草黑胫病、瓜类枯萎病，19%水剂稀释500-600倍灌根或喷雾，对铜敏感作物禁用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000085', 'source-doc-4c784a84a66adf221597', 'source-node-000079', '7', '84', 'text', '代森锰锌·恶霉灵：代森锰锌提供保护作用，恶霉灵发挥治疗传导作用；防治番茄晚疫病、黄瓜根腐病（复配比例多为4:4），稀释600-800倍喷雾，持效期7-10天。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000086', 'source-doc-4c784a84a66adf221597', 'source-node-000079', '7', '85', 'text', '恶霉灵·多菌灵：恶霉灵针对性防控卵菌纲，多菌灵广谱杀菌；适用于土壤消毒和拌种，防治苗期立枯病、猝倒病，稀释500-800倍泼浇或拌种，忌与碱性药剂混用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000087', 'source-doc-4c784a84a66adf221597', 'source-node-000076', '6', '86', 'text', '线粒体呼吸抑制剂', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000088', 'source-doc-4c784a84a66adf221597', 'source-node-000087', '7', '87', 'text', '氰霜唑：抑制细胞色素bc1复合体，对霜霉病、疫病特效，与甲霜灵无交互抗性，持效期长。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000089', 'source-doc-4c784a84a66adf221597', 'source-node-000087', '7', '88', 'text', '噁唑菌酮：抑制线粒体复合体Ⅲ，兼具保护治疗，防霜霉病、疫病及高等真菌病害，耐雨水冲刷。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000090', 'source-doc-4c784a84a66adf221597', 'source-node-000087', '7', '89', 'text', '代森锰锌：二硫代氨基甲酸盐类，通过抑制低等真菌（卵菌纲）线粒体呼吸复合体 Ⅲ 起效，保护性杀菌剂；对霜霉病、疫病、猝倒病有效，持效期 7-10 天，忌与碱性药剂混用，避免在高温强光下使用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000091', 'source-doc-4c784a84a66adf221597', 'source-node-000087', '7', '90', 'text', '代森锌：作用机制同代森锰锌（抑制线粒体呼吸复合体 Ⅲ），针对卵菌引起的霜霉病、疫病，保护性为主；杀菌谱较窄但速效性好，对作物安全性高，适合苗期使用，安全间隔期 5-7 天。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000092', 'source-doc-4c784a84a66adf221597', 'source-node-000087', '7', '91', 'text', '代森联：抑制低等真菌线粒体呼吸链，保护性强；防治黄瓜霜霉病、番茄晚疫病，耐雨水冲刷性优于代森锰锌，对蜜蜂低毒，可与内吸性药剂（如烯酰吗啉）复配提升防效。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000093', 'source-doc-4c784a84a66adf221597', 'source-node-000087', '7', '92', 'text', '氟啶胺：吡啶酰胺类，抑制线粒体呼吸复合体 Ⅲ，对卵菌（霜霉、疫病）特效，兼具杀螨活性；治疗性较强，对十字花科作物敏感，避免与有机磷农药混用，安全间隔期 10-15 天。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000094', 'source-doc-4c784a84a66adf221597', 'source-node-000087', '7', '93', 'text', '克菌丹：酞酰亚胺类，抑制低等真菌线粒体呼吸复合体 Ⅲ，保护兼一定治疗作用；防治马铃薯晚疫病、葡萄霜霉病，对土壤病原菌也有抑制作用，可拌种或喷雾，对蜜蜂安全。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000095', 'source-doc-4c784a84a66adf221597', 'source-node-000087', '7', '94', 'text', '氟吡菌胺：吡啶酰胺类，抑制低等真菌线粒体呼吸复合体 Ⅱ，内吸性较强；常与霜霉威复配（如氟吡・霜霉威），防治霜霉病、疫病，能渗透叶片表层，耐雨水冲刷，对作物安全性高。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000096', 'source-doc-4c784a84a66adf221597', 'source-node-000076', '6', '95', 'text', '细胞壁合成抑制剂', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000097', 'source-doc-4c784a84a66adf221597', 'source-node-000096', '7', '96', 'text', '烯酰吗啉：羧酸酰胺类，通过抑制低等真菌（卵菌纲）细胞壁关键成分 β-1,3 - 葡聚糖的合成起效；内吸性强、治疗作用突出，对霜霉病、疫病特效，常与代森锰锌等保护性药剂复配延缓抗药性；对作物安全性高，稀释 1000-1500 倍喷雾，安全间隔期 7-10 天。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000098', 'source-doc-4c784a84a66adf221597', 'source-node-000096', '7', '97', 'text', '氟吗啉：同属羧酸酰胺类，作用机制为抑制卵菌细胞壁 β-1,3 - 葡聚糖合成；兼具保护与治疗作用，广谱防控霜霉病、疫病、猝倒病，对葡萄、黄瓜、番茄等作物适配性好；耐雨水冲刷，可与恶霉灵复配增强土传病害防效，忌与碱性药剂混用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000099', 'source-doc-4c784a84a66adf221597', 'source-node-000096', '7', '98', 'text', '氰霜唑：咪唑类，靶向抑制卵菌细胞壁 β-1,3 - 葡聚糖合成酶；高效低毒，对霜霉病（尤其抗药性种群）特效，持效期达 14 天以上；对水生生物敏感，避免污染水体，可稀释 2000-3000 倍叶面喷雾，安全间隔期 10 天。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000100', 'source-doc-4c784a84a66adf221597', 'source-node-000096', '7', '99', 'text', '苯噻菌胺：羧酸酰胺类，通过抑制卵菌细胞壁合成发挥作用；内吸传导性优异（可双向传导），防治霜霉病、疫病同时能促进作物根系发育；常与代森锰锌复配提升防效，对十字花科作物无药害，稀释 800-1200 倍喷雾，安全间隔期 5-7 天。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000101', 'source-doc-4c784a84a66adf221597', 'source-node-000076', '6', '100', 'text', '核酸合成抑制剂', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000102', 'source-doc-4c784a84a66adf221597', 'source-node-000101', '7', '101', 'text', '甲霜灵：双向传导，防霜霉病、疫病，但抗药性严重，需与代森锰锌复配（如甲霜灵·锰锌）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000103', 'source-doc-4c784a84a66adf221597', 'source-node-000101', '7', '102', 'text', '霜脲氰：干扰RNA合成，治疗活性高但内吸弱，需喷透防黄瓜霜霉病，常与烯酰吗啉复配。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000104', 'source-doc-4c784a84a66adf221597', 'source-node-000101', '7', '103', 'text', '恶霉灵：内吸性杀菌剂，通过抑制低等真菌（卵菌纲为主）核酸（DNA/RNA）合成阻断病原菌繁殖；对猝倒病、立枯病、根腐病等土传病害特效，兼具促进作物根系发育作用；可灌根或喷雾，幼苗期需高倍稀释（1500-2000倍），忌与碱性药剂混用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000105', 'source-doc-4c784a84a66adf221597', 'source-node-000101', '7', '104', 'text', '霜霉威盐酸盐：抑制低等真菌RNA聚合酶活性，阻碍RNA合成，内吸传导性强（可双向传导）；以保护作用为主、兼具治疗效果，防治霜霉病、疫病、猝倒病，对作物安全性高（适合苗期使用）；稀释800-1200倍喷雾或灌根，安全间隔期5-7天，可与烯酰吗啉复配提升防效。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000106', 'source-doc-4c784a84a66adf221597', 'source-node-000101', '7', '105', 'text', '甲霜灵：苯基酰胺类，抑制低等真菌RNA合成，内吸性强、治疗作用突出；对霜霉病、疫病、根腐病有效，尤其适用于葡萄、蔬菜等作物；长期单用过易产生抗药性，常与代森锰锌、福美双等复配使用；稀释1000-1500倍喷雾，安全间隔期7-10天。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000107', 'source-doc-4c784a84a66adf221597', 'source-node-000101', '7', '106', 'text', '精甲霜灵：甲霜灵的活性光学异构体，作用机制同甲霜灵（抑制RNA合成），但杀菌活性更高、用量更少；对卵菌病害（霜霉、疫病）防效优异，对作物安全性优于甲霜灵；常复配成精甲·恶霉灵、精甲·代森锰锌等制剂，灌根或喷雾均可，安全间隔期5-7天。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000108', 'source-doc-4c784a84a66adf221597', 'source-node-000101', '7', '107', 'text', '噁霜灵：苯基酰胺类，通过抑制低等真菌RNA合成发挥作用，内吸性强、持效期长；防治马铃薯晚疫病、番茄疫病、黄瓜霜霉病，可用于叶面喷雾或种子处理；对部分作物（如十字花科）较敏感，需控制用量，忌与碱性农药混用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000109', 'source-doc-4c784a84a66adf221597', 'source-node-000076', '6', '108', 'text', '细胞膜破坏剂', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000110', 'source-doc-4c784a84a66adf221597', 'source-node-000109', '7', '109', 'text', '氟吡菌胺：作用于细胞膜类血红蛋白，与霜霉威复配（如银法利），防马铃薯晚疫病、葡萄霜霉病，耐雨水冲刷。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000111', 'source-doc-4c784a84a66adf221597', 'source-node-000109', '7', '110', 'text', '氢氧化铜：铜离子通过渗透作用破坏低等真菌（卵菌纲）细胞膜，使内容物泄漏；以保护性为主，可防治霜霉病、疫病，兼防细菌性角斑病，对铜敏感作物（如桃、李）慎用；忌与强酸、强碱药剂混用，安全间隔期7-10天，主要用于叶面喷雾。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000112', 'source-doc-4c784a84a66adf221597', 'source-node-000109', '7', '111', 'text', '氧化亚铜：铜离子破坏细胞膜结构，保护性强且耐雨水冲刷；针对马铃薯晚疫病、黄瓜霜霉病、番茄疫病，对作物安全性高于氢氧化铜；可用于叶面喷雾或种子处理（防治苗期猝倒病），避免在高温高湿环境下使用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000113', 'source-doc-4c784a84a66adf221597', 'source-node-000109', '7', '112', 'text', '噻唑锌：噻唑基团协同铜离子破坏细胞膜，兼具保护与治疗作用，可同时防治卵菌病害（如霜霉病、疫病）和细菌性病害；对黄瓜、葡萄、柑橘等作物安全，忌与碱性药剂混用，安全间隔期5-7天，以叶面喷雾为主。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000114', 'source-doc-4c784a84a66adf221597', 'source-node-000109', '7', '113', 'text', '氟吡菌胺：吡啶酰胺类，通过作用于细胞膜上的类血红蛋白，破坏膜完整性与功能；内吸性强，对霜霉病、疫病特效，常与霜霉威复配（如氟菌·霜霉威）增强防效；能渗透叶片表层，耐雨水冲刷，对作物安全性高，安全间隔期3-5天，主要用于叶面喷雾。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000115', 'source-doc-4c784a84a66adf221597', 'source-node-000109', '7', '114', 'text', '氟菌·霜霉威（氟吡菌胺+霜霉威盐酸盐）：氟吡菌胺破坏细胞膜，霜霉威辅助抑制核酸合成，协同防治霜霉病、马铃薯晚疫病、番茄疫病；内吸传导性优异，适用于设施农业，对蜜蜂低毒，安全间隔期2-3天，以叶面喷雾为主。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000116', 'source-doc-4c784a84a66adf221597', 'source-node-000109', '7', '115', 'text', '乙蒜素：有机硫类，通过释放大蒜素破坏细胞膜，兼具熏蒸与触杀作用；防治土传卵菌病害（如根腐病、猝倒病）和叶面霜霉病，对病原菌速效性强；刺激性较大，避免与种子直接接触，安全间隔期7天，可用于叶面喷雾或灌根（防治土传病害）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000117', 'source-doc-4c784a84a66adf221597', 'source-node-000076', '6', '116', 'text', '有机磷类', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000118', 'source-doc-4c784a84a66adf221597', 'source-node-000117', '7', '117', 'text', '乙磷铝：双向传导，防霜霉病、疫病，持效期7-10天，常与代森锰锌复配（如杀毒矾），抗性发展较快。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000119', 'source-doc-4c784a84a66adf221597', 'source-node-000117', '7', '118', 'text', '三乙膦酸铝：有机磷类低等真菌专用防治药，内吸传导性强（可双向传导至植株各部位），通过干扰病原菌代谢发挥作用；对卵菌纲病害（霜霉病、疫病、猝倒病、晚疫病）特效，兼防部分高等真菌病害（如白粉病）；可采用叶面喷雾、灌根或种子处理，对多数作物安全，但高湿环境下对黄瓜、白菜等易产生轻微药害；长期单用易诱发抗药性，常与烯酰吗啉、代森锰锌等复配使用，安全间隔期 7-10 天。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000120', 'source-doc-4c784a84a66adf221597', 'source-node-000117', '7', '119', 'text', '甲基立枯磷：有机磷类杀菌剂，虽对高等真菌（如立枯丝核菌）防效突出，也可防治低等真菌（卵菌）引起的猝倒病；作用机制为抑制病原菌细胞膜合成，以保护性为主、兼具一定治疗作用；内吸性较弱但持效期长，适用于土传病害防控，可通过叶面喷雾、灌根或种子拌种使用；对作物安全性高，极少产生药害，可用于蔬菜、果树、花卉等多种作物，忌与碱性药剂混用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000121', 'source-doc-4c784a84a66adf221597', 'source-node-000076', '6', '120', 'text', '新型作用机制类', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000122', 'source-doc-4c784a84a66adf221597', 'source-node-000121', '7', '121', 'text', '氟噻唑吡乙酮：靶向卵菌Oxysterol结合蛋白（OSBP），干扰细胞膜脂质合成；内吸性强且能双向传导，持效期15-20天，对霜霉病、疫病特效，发病前或初期施用防效最佳，抗药性风险低。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000123', 'source-doc-4c784a84a66adf221597', 'source-node-000121', '7', '122', 'text', '双炔酰菌胺：抑制卵菌线粒体呼吸链复合体Ⅲ（独特作用位点）；以保护作用为主，叶片渗透力强可直达叶背，耐雨水冲刷，对马铃薯晚疫病、黄瓜霜霉病高效，对葡萄、草莓等敏感作物安全。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000124', 'source-doc-4c784a84a66adf221597', 'source-node-000121', '7', '123', 'text', '氰霜唑：抑制卵菌线粒体呼吸链复合体Ⅱ，阻断能量代谢；保护作用突出，持效期10-14天且耐雨水，防治霜霉病、疫病、猝倒病效果好，抗药性风险低，适用于多种作物。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000125', 'source-doc-4c784a84a66adf221597', 'source-node-000121', '7', '124', 'text', '氟啶胺：作用于卵菌线粒体呼吸链复合体Ⅲ/Ⅴ，还能破坏细胞膜；触杀性强、渗透深，可叶面喷雾防晚疫病，也能土壤处理防土传卵菌病，广谱高效，但对蜜蜂、家蚕有毒。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000126', 'source-doc-4c784a84a66adf221597', 'source-node-000121', '7', '125', 'text', '唑嘧菌胺：抑制卵菌线粒体呼吸链复合体Ⅱ；中等内吸（局部传导），持效期8-12天，防治霜霉病、腐霉病效果佳，建议与代森锰锌等保护性药剂复配，延缓抗药性。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000127', 'source-doc-4c784a84a66adf221597', 'source-node-000076', '6', '126', 'text', '复配制剂', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000128', 'source-doc-4c784a84a66adf221597', 'source-node-000127', '7', '127', 'text', '烯酰吗啉·霜脲氰：协同防黄瓜霜霉病、马铃薯晚疫病，延缓抗药性。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000129', 'source-doc-4c784a84a66adf221597', 'source-node-000127', '7', '128', 'text', '氟菌·霜霉威：防黄瓜霜霉病，安全间隔期2天，适用于设施农业。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000130', 'source-doc-4c784a84a66adf221597', 'source-node-000127', '7', '129', 'text', '杀毒矾：保护兼治疗，防马铃薯晚疫病，耐雨水冲刷。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000131', 'source-doc-4c784a84a66adf221597', 'source-node-000127', '7', '130', 'text', '氟菌・霜霉威：氟吡菌胺破坏细胞膜，霜霉威干扰核酸合成；内吸传导优异，防霜霉病、晚疫病，耐雨水，设施农业常用，安全间隔期 2-3 天。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000132', 'source-doc-4c784a84a66adf221597', 'source-node-000127', '7', '131', 'text', '烯酰・锰锌：烯酰吗啉抑制卵菌细胞壁合成（治疗），代森锰锌保护细胞膜（保护）；保护 + 治疗协同，防霜霉病、疫病，延缓抗药性，适用于多数作物。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000133', 'source-doc-4c784a84a66adf221597', 'source-node-000127', '7', '132', 'text', '霜脲・锰锌：霜脲氰抑制卵菌能量代谢（治疗），代森锰锌保护性杀菌；速效性好，防霜霉病、晚疫病，持效期 7-10 天，对作物安全性高。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000134', 'source-doc-4c784a84a66adf221597', 'source-node-000127', '7', '133', 'text', '甲霜・锰锌：甲霜灵内吸治疗（干扰核酸），代森锰锌保护；防霜霉病、猝倒病、根腐病，可喷雾或灌根，忌长期单一使用（甲霜灵易诱抗药）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000135', 'source-doc-4c784a84a66adf221597', 'source-node-000127', '7', '134', 'text', '恶酮・霜脲氰：恶唑菌酮抑制线粒体复合体 Ⅲ（保护），霜脲氰治疗；渗透力强，防霜霉病、疫病，耐雨水，适用于葡萄、蔬菜等敏感作物。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000136', 'source-doc-4c784a84a66adf221597', 'source-node-000127', '7', '135', 'text', '唑醚・代森联：吡唑醚菌酯抑制线粒体复合体 Ⅲ（治疗 + 保护），代森联强化保护；广谱防霜霉病、晚疫病，兼防部分高等真菌病，提升作物抗逆性。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000137', 'source-doc-4c784a84a66adf221597', 'source-node-000127', '7', '136', 'text', '氟噻唑吡乙酮・代森锰锌：氟噻唑吡乙酮靶向 OSBP 蛋白（治疗），代森锰锌保护；抗药性风险极低，持效期长（15 天以上），防霜霉病、疫病，发病前预防效果佳。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000138', 'source-doc-4c784a84a66adf221597', 'source-node-000127', '7', '137', 'text', '氰霜唑・代森锰锌：氰霜唑抑制复合体 Ⅱ（治疗），代森锰锌保护；防霜霉病、猝倒病，持效期 10-14 天，对铜敏感作物（如桃）可替代铜制剂。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000139', 'source-doc-4c784a84a66adf221597', 'source-node-000048', '4', '138', 'text', '细菌', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000140', 'source-doc-4c784a84a66adf221597', 'source-node-000139', '5', '139', 'text', '铜制剂类（细菌性病害防治核心类别，通过释放铜离子破坏细菌细胞膜，兼具一定真菌防效）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000141', 'source-doc-4c784a84a66adf221597', 'source-node-000140', '6', '140', 'text', '氢氧化铜：广谱杀菌，铜离子直接破坏细菌细胞膜；防细菌性角斑病、溃疡病、软腐病，兼防真菌性霜霉病；对铜敏感作物（如桃、李、梨）易产生药害，忌与强酸/碱性药剂混用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000142', 'source-doc-4c784a84a66adf221597', 'source-node-000140', '6', '141', 'text', '氧化亚铜：保护性强，铜离子释放缓慢且持效期长（10-15天）；防柑橘溃疡病、番茄青枯病、黄瓜细菌性角斑病；适合发病前预防，高温高湿环境需降低用量避免药害。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000143', 'source-doc-4c784a84a66adf221597', 'source-node-000140', '6', '142', 'text', '噻唑锌：兼具噻唑环内吸性与铜离子触杀性；内吸后干扰细菌代谢，触杀破坏细胞膜；防水稻细菌性条斑病、白菜软腐病、柑橘溃疡病，对作物安全性高，可混配性好。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000144', 'source-doc-4c784a84a66adf221597', 'source-node-000140', '6', '143', 'text', '琥胶肥酸铜（DT）：有机铜制剂，刺激性低于无机铜；通过铜离子与细菌酶结合抑制活性；防黄瓜细菌性角斑病、番茄细菌性斑点病、棉花角斑病，适合敏感作物苗期使用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000145', 'source-doc-4c784a84a66adf221597', 'source-node-000140', '6', '144', 'text', '络氨铜：络合态铜，稳定性强、药害风险低；兼具内吸传导与触杀，可叶面喷雾或灌根；防蔬菜软腐病、果树溃疡病、水稻白叶枯病，灌根可治土传细菌性病害（如青枯病）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000146', 'source-doc-4c784a84a66adf221597', 'source-node-000140', '6', '145', 'text', '壬菌铜：新型有机铜，渗透性强，能穿透细菌生物膜；防西瓜细菌性果斑病、辣椒细菌性疮痂病、葡萄霜霉病（兼防）；对蜜蜂低毒，适合设施农业与绿色防控。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000147', 'source-doc-4c784a84a66adf221597', 'source-node-000140', '6', '146', 'text', '壬菌铜：有机铜制剂，渗透性优异；能穿透植物表层组织，直接作用于病灶细菌，破坏细胞膜与酶系统；防治西瓜细菌性角斑病、辣椒疮痂病、葡萄霜霉病（兼防）；低温环境下仍保持较好活性，对多数作物安全性高，不易产生药害。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000148', 'source-doc-4c784a84a66adf221597', 'source-node-000140', '6', '147', 'text', '松脂酸铜：有机铜制剂，兼营养作用；铜离子缓慢释放，对作物刺激小，同时能补充微量营养；防治柑橘溃疡病、番茄晚疫病（兼防）、白菜软腐病；适合果树、蔬菜全生育期使用，可与多数非碱性药剂混用，不影响作物光合作用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000149', 'source-doc-4c784a84a66adf221597', 'source-node-000140', '6', '148', 'text', '喹啉铜：有机铜与喹啉类复配型（核心含铜）；兼具触杀与内吸，铜离子破坏细胞膜，喹啉类抑制细菌DNA复制；防治葡萄霜霉病（兼防）、番茄青枯病、白菜软腐病；对苹果、梨等铜敏感作物安全性较高，发病初期使用防效更佳。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000150', 'source-doc-4c784a84a66adf221597', 'source-node-000140', '6', '149', 'text', '噻唑锌·春雷霉素：含铜复配制剂（噻唑锌为有机铜）；噻唑锌触杀破坏细菌结构，春雷霉素内吸抑制蛋白质合成；防水稻细菌性条斑病、柑橘溃疡病；双重作用机制互补，延缓抗性产生，对作物安全性优于单一无机铜，适合发病中期使用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000151', 'source-doc-4c784a84a66adf221597', 'source-node-000140', '6', '150', 'text', '噻唑锌·喹啉铜：含铜复配制剂（噻唑锌、喹啉铜均含铜）；噻唑锌内吸抑菌，喹啉铜触杀杀菌，铜离子协同增强防效；防治柑橘溃疡病、黄瓜细菌性角斑病；抗性风险低，能同时应对细菌性病害与部分真菌病害（如霜霉病），喷雾后耐雨水冲刷。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000152', 'source-doc-4c784a84a66adf221597', 'source-node-000140', '6', '151', 'text', '春雷霉素·王铜：含铜复配制剂（王铜为无机铜）；春雷霉素内吸干扰细菌代谢，王铜触杀释放铜离子破坏细胞膜；防治番茄青枯病、柑橘溃疡病；作用机制互补，快速控制病害扩散，注意王铜对桃、李等敏感作物的药害风险，需严格控制用量。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000153', 'source-doc-4c784a84a66adf221597', 'source-node-000140', '6', '152', 'text', '硫酸铜钙：无机铜复配制剂（硫酸铜+钙）；铜离子杀菌，钙元素增强作物抗逆性；防治苹果斑点落叶病（兼防）、黄瓜细菌性角斑病、葡萄霜霉病（兼防）；对土壤和作物污染小，适合果园、菜园长期使用，避免与磷酸二氢钾等含磷药剂混用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000154', 'source-doc-4c784a84a66adf221597', 'source-node-000140', '6', '153', 'text', '噻森铜：有机铜制剂，内吸性强；铜离子与噻唑基团协同，干扰细菌呼吸作用与代谢；防治水稻细菌性条斑病、番茄细菌性斑点病、白菜软腐病；持效期长（12-15天），对有益昆虫安全性高，适合绿色农业生产，可用于出口蔬菜防治。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000155', 'source-doc-4c784a84a66adf221597', 'source-node-000140', '6', '154', 'text', '氢氧化铜·春雷霉素：含铜复配制剂（氢氧化铜为无机铜）；氢氧化铜触杀杀菌，春雷霉素内吸抑菌；防治黄瓜细菌性角斑病、番茄细菌性斑点病；快速起效，适合病害突发期使用，注意氢氧化铜对敏感作物的药害，苗期需稀释使用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000156', 'source-doc-4c784a84a66adf221597', 'source-node-000140', '6', '155', 'text', '噻菌铜：有机铜制剂，兼具触杀与一定内吸性；通过释放铜离子破坏细菌细胞膜，同时干扰细菌体内代谢过程，对细菌性病害防效专一；可防治水稻细菌性条斑病、水稻白叶枯病、番茄青枯病、辣椒细菌性疮痂病、柑橘溃疡病等；对作物安全性较高，即使在作物苗期或花期使用，药害风险也较低，持效期约 7-10 天，忌与强碱性药剂混用，可与多数非碱性杀菌剂、杀虫剂混配使用，适合发病前预防及发病初期治疗。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000157', 'source-doc-4c784a84a66adf221597', 'source-node-000139', '5', '156', 'text', '抗生素类（农用抗生素，通过抑制细菌蛋白质合成或代谢发挥作用，针对性强）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000158', 'source-doc-4c784a84a66adf221597', 'source-node-000157', '6', '157', 'text', '中生菌素：多组分农用抗生素，通过破坏细菌细胞膜完整性、干扰核酸合成发挥作用；内吸传导性好，兼具保护与治疗效果；可防治苹果轮纹病（细菌性）、黄瓜细菌性角斑病、白菜软腐病、水稻白叶枯病，抗药性风险低，对作物安全性高，适合与保护性药剂轮换或混配使用，全生育期均可施用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000159', 'source-doc-4c784a84a66adf221597', 'source-node-000157', '6', '158', 'text', '春雷霉素：内吸性农用抗生素，主要抑制细菌蛋白质合成，兼对部分真菌（如稻瘟病菌）有效；防治番茄青枯病、柑橘溃疡病、水稻细菌性条斑病、黄瓜细菌性角斑病；持效期约7-10天，苗期、花期使用安全性高，忌与碱性药剂混用，长期单一使用易诱发抗性，建议搭配铜制剂复配。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000160', 'source-doc-4c784a84a66adf221597', 'source-node-000157', '6', '159', 'text', '农用链霉素：氨基糖苷类抗生素，通过干扰细菌核糖体功能阻止蛋白质合成；曾广泛防治黄瓜细菌性角斑病、白菜软腐病、水稻白叶枯病、烟草青枯病；因长期使用导致抗性问题，部分地区已限制或禁止在蔬菜、果树作物上使用，需选择合规登记产品，避免与酸性强的药剂混配，敏感作物苗期慎用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000161', 'source-doc-4c784a84a66adf221597', 'source-node-000157', '6', '160', 'text', '硫酸链霉素：与农用链霉素作用机制一致，抑制细菌蛋白质合成；水溶性好，可叶面喷雾或灌根；防治马铃薯环腐病、芹菜软腐病、辣椒细菌性疮痂病；需严格控制用量，避免污染水体，安全间隔期7-10天，不建议与有机磷类杀虫剂混用（易降低药效）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000162', 'source-doc-4c784a84a66adf221597', 'source-node-000157', '6', '161', 'text', '噻唑锌·春雷霉素：复配抗生素类药剂（春雷霉素+噻唑锌）；春雷霉素内吸抑菌，噻唑锌（有机铜）触杀破坏细菌细胞膜，作用机制互补；高效防治水稻细菌性条斑病、柑橘溃疡病、番茄细菌性斑点病；延缓抗性产生，对作物的药害风险低于单一无机铜制剂，发病初期至中期施用防效最佳，忌与强碱性药剂混用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000163', 'source-doc-4c784a84a66adf221597', 'source-node-000157', '6', '162', 'text', '春雷霉素·王铜：复配抗生素类药剂（春雷霉素+王铜）；春雷霉素内吸抑制细菌代谢，王铜（无机铜）释放铜离子触杀细菌；防治番茄青枯病、柑橘溃疡病、黄瓜细菌性角斑病；快速控制病害扩散，适合病害突发期使用；注意王铜对桃、李、梨等铜敏感作物易产生药害，需严格按推荐剂量施用，避免高温高湿环境使用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000164', 'source-doc-4c784a84a66adf221597', 'source-node-000157', '6', '163', 'text', '中生菌素·噻唑锌：复配抗生素类药剂（中生菌素+噻唑锌）；中生菌素内吸干扰细菌核酸合成，噻唑锌触杀兼内吸抑菌；防治白菜软腐病、水稻细菌性条斑病、葡萄细菌性角斑病；抗性风险极低，对作物安全性高，可用于绿色食品生产，喷雾后耐雨水冲刷，持效期约10-12天。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000165', 'source-doc-4c784a84a66adf221597', 'source-node-000157', '6', '164', 'text', '春雷霉素·喹啉铜：复配抗生素类药剂（春雷霉素+喹啉铜）；春雷霉素内吸抑制蛋白质合成，喹啉铜（有机铜）破坏细菌细胞膜并抑制DNA复制；防治柑橘溃疡病、苹果细菌性斑点病、番茄青枯病；兼具防真菌效果（如葡萄霜霉病），对铜敏感作物（如苹果）安全性优于传统铜制剂，适合果树全生育期使用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000166', 'source-doc-4c784a84a66adf221597', 'source-node-000157', '6', '165', 'text', '多抗霉素：广谱农用抗生素，虽主要针对真菌病害，但其组分对细菌性病害（如番茄细菌性斑点病、白菜软腐病）有辅助防治作用；通过抑制细菌细胞壁合成发挥弱抑菌效果；常与其他细菌性病害专用药剂混配，提升综合防效，对作物无药害，可用于苗期至采收期。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000167', 'source-doc-4c784a84a66adf221597', 'source-node-000139', '5', '166', 'text', '噻唑类（含噻唑环结构，内吸性强，干扰细菌代谢或酶活性）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000168', 'source-doc-4c784a84a66adf221597', 'source-node-000167', '6', '167', 'text', '噻唑锌：（同铜制剂类，因兼具噻唑环特性单独归类）内吸后抑制细菌丙酮酸脱氢酶活性，触杀靠铜离子；防多种细菌性病害，可与保护性杀菌剂复配提升防效。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000169', 'source-doc-4c784a84a66adf221597', 'source-node-000167', '6', '168', 'text', '叶枯唑（噻枯唑）：专一性防治细菌性病害，内吸传导快；抑制细菌蛋白质合成，对水稻白叶枯病、细菌性条斑病特效；也可防白菜软腐病、番茄青枯病，持效期8-12天。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000170', 'source-doc-4c784a84a66adf221597', 'source-node-000167', '6', '169', 'text', '噻唑菌胺：新型噻唑类，干扰细菌细胞壁合成；内吸性优异，防柑橘溃疡病、苹果斑点落叶病（细菌性）、葡萄细菌性角斑病；对环境友好，适合无公害果园使用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000171', 'source-doc-4c784a84a66adf221597', 'source-node-000167', '6', '170', 'text', '噻唑锌・春雷霉素：噻唑类与抗生素复配；噻唑锌触杀 + 内吸抑菌，春雷霉素内吸抑制细菌蛋白质合成，双重机制互补；防治水稻细菌性条斑病、柑橘溃疡病、番茄细菌性斑点病；延缓抗性产生，对作物安全性高于无机铜复配剂，发病初期至中期使用防效最佳，忌与强碱性药剂混用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000172', 'source-doc-4c784a84a66adf221597', 'source-node-000167', '6', '171', 'text', '中生菌素・噻唑锌：噻唑类与抗生素复配；噻唑锌破坏细菌细胞膜，中生菌素干扰核酸合成，协同增强抑菌效果；防治白菜软腐病、水稻细菌性条斑病、辣椒疮痂病；抗性风险极低，对作物安全性高，可用于绿色食品生产，喷雾后耐雨水冲刷，持效期 10-12 天。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000173', 'source-doc-4c784a84a66adf221597', 'source-node-000167', '6', '172', 'text', '噻唑锌・喹啉铜：噻唑类与有机铜复配；噻唑锌内吸干扰代谢，喹啉铜触杀破坏细胞膜并抑制 DNA 复制；防治柑橘溃疡病、黄瓜细菌性角斑病、西瓜细菌性果斑病；兼具防真菌效果（如霜霉病），对铜敏感作物（如苹果）安全性高，适合发病前预防及初期治疗，持效期 10 天左右。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000174', 'source-doc-4c784a84a66adf221597', 'source-node-000167', '6', '173', 'text', '噻唑锌・乙蒜素：噻唑类与有机硫复配；噻唑锌内吸抑菌，乙蒜素触杀 + 熏蒸破坏细菌酶系统；防治土传细菌性病害（如番茄青枯病、茄子黄萎病）及叶部细菌性病害（如白菜软腐病）；速效性强，适合连作地块病害防控，乙蒜素刺激性大，避免接触皮肤，敏感作物苗期慎用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000175', 'source-doc-4c784a84a66adf221597', 'source-node-000139', '5', '174', 'text', '有机磷类（部分有机磷药剂兼具防细菌作用，通过抑制细菌胆碱酯酶或代谢发挥作用）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000176', 'source-doc-4c784a84a66adf221597', 'source-node-000175', '6', '175', 'text', '乙蒜素：有机硫类（近有机磷作用特性），释放大蒜素破坏细菌细胞膜与酶系统；兼具熏蒸、触杀，防土传细菌性病害（如番茄青枯病、茄子黄萎病（细菌性））和叶面霜斑病；刺激性强，需避免接触皮肤，敏感作物苗期慎用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000177', 'source-doc-4c784a84a66adf221597', 'source-node-000175', '6', '176', 'text', '三乙膦酸铝：有机磷类杀菌剂，主要通过干扰病原菌代谢发挥作用，对细菌性病害有一定兼防效果；可防治水稻细菌性条斑病、白菜细菌性软腐病，兼防低等真菌病害（霜霉病、疫病）；内吸传导性强，可叶面喷雾或灌根，长期单一使用易诱发抗药性，对多数作物安全但高湿环境下对黄瓜、白菜可能产生轻微药害，忌与碱性药剂混用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000178', 'source-doc-4c784a84a66adf221597', 'source-node-000175', '6', '177', 'text', '乙蒜素：有机硫类（作用特性近有机磷），通过释放大蒜素破坏细菌细胞膜与酶系统，兼具熏蒸、触杀作用；专性防治细菌性病害，如番茄青枯病、茄子细菌性黄萎病、白菜软腐病、棉花角斑病；速效性强，持效期5-7天，对土传细菌性病害防效突出，可灌根或喷雾；刺激性大，避免接触皮肤和黏膜，敏感作物苗期需降低用量，忌与碱性药剂混用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000179', 'source-doc-4c784a84a66adf221597', 'source-node-000175', '6', '178', 'text', '甲基立枯磷：有机磷类杀菌剂，主要抑制病原菌细胞膜合成，对细菌性病害有辅助防治作用；兼防土传细菌性病害（如马铃薯环腐病、番茄细菌性青枯病）及高等真菌病害（立枯病）；内吸性较弱但持效期长（10-15天），适合土壤处理或灌根；对作物安全性高，极少产生药害，可与铜制剂复配提升细菌性病害防效，忌与碱性药剂混用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000180', 'source-doc-4c784a84a66adf221597', 'source-node-000175', '6', '179', 'text', '三乙膦酸铝·百菌清：有机磷与取代苯类复配（三乙膦酸铝+百菌清）；三乙膦酸铝内吸干扰细菌代谢，百菌清保护性防真菌，协同防治细菌性与真菌性病害混发；主治黄瓜细菌性角斑病与霜霉病、葡萄细菌性角斑病与霜霉病；耐雨水冲刷，适合高湿环境使用，避免在十字花科作物苗期过量使用，安全间隔期7-10天。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000181', 'source-doc-4c784a84a66adf221597', 'source-node-000175', '6', '180', 'text', '乙蒜素·噻唑锌：有机磷特性药剂与噻唑类复配（乙蒜素+噻唑锌）；乙蒜素触杀+熏蒸破坏细菌结构，噻唑锌内吸干扰细菌代谢，双重机制增强防效；防治番茄青枯病、白菜软腐病、水稻细菌性条斑病，对连作地块土传细菌性病害防效突出；速效性与持效性结合（持效期8-10天），乙蒜素刺激性强，需避免在花期使用，敏感作物苗期慎用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000182', 'source-doc-4c784a84a66adf221597', 'source-node-000175', '6', '181', 'text', '甲基立枯磷·硫酸铜：有机磷与无机铜复配（甲基立枯磷+硫酸铜）；甲基立枯磷抑制细菌细胞膜，硫酸铜释放铜离子破坏细菌结构，协同防治细菌性与真菌性土传病害；主治马铃薯环腐病、辣椒细菌性疮痂病、苗期猝倒病（细菌性）；适合拌种或土壤消毒，硫酸铜对铜敏感作物（如桃、李）有药害风险，需严格控制用量，忌与碱性肥料混用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000183', 'source-doc-4c784a84a66adf221597', 'source-node-000175', '6', '182', 'text', '三乙膦酸铝·春雷霉素：有机磷与抗生素复配（三乙膦酸铝+春雷霉素）；三乙膦酸铝内吸兼防细菌与真菌，春雷霉素专一抑制细菌蛋白质合成，强化细菌性病害防效；防治水稻细菌性条斑病与霜霉病、柑橘溃疡病；内吸传导性优异，发病初期使用防效最佳，避免长期单一使用以延缓抗性，安全间隔期5-7天。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000184', 'source-doc-4c784a84a66adf221597', 'source-node-000139', '5', '183', 'text', '微生物制剂类（通过有益微生物竞争营养、分泌拮抗物质抑制或杀灭细菌，绿色安全）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000185', 'source-doc-4c784a84a66adf221597', 'source-node-000184', '6', '184', 'text', '枯草芽孢杆菌：有益菌占据生态位，分泌抗菌肽抑制细菌生长；防番茄青枯病、黄瓜细菌性角斑病、白菜软腐病；适合发病前预防，可与化学药剂间隔使用（避免杀菌药杀灭有益菌），提升土壤微生态。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000186', 'source-doc-4c784a84a66adf221597', 'source-node-000184', '6', '185', 'text', '荧光假单胞杆菌：分泌嗜铁素、抗生素抑制细菌，诱导作物抗病性；灌根防土传细菌性病害（如辣椒青枯病、西瓜细菌性果斑病），叶面喷雾防叶部细菌性病害；对作物无药害，适合绿色农业。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000187', 'source-doc-4c784a84a66adf221597', 'source-node-000184', '6', '186', 'text', '蜡质芽孢杆菌：竞争营养与空间，分泌酶类分解细菌细胞壁；防水稻细菌性条斑病、玉米细菌性茎基腐病、番茄细菌性斑点病；可拌种、喷雾或灌根，增强作物抗逆性。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000188', 'source-doc-4c784a84a66adf221597', 'source-node-000184', '6', '187', 'text', '多粘类芽孢杆菌：产生多粘菌素破坏细菌细胞膜，专性抑制革兰氏阴性细菌；防黄瓜细菌性角斑病、水稻白叶枯病、柑橘溃疡病；对蜜蜂、家蚕低毒，适合生态果园与设施蔬菜。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000189', 'source-doc-4c784a84a66adf221597', 'source-node-000184', '6', '188', 'text', '地衣芽孢杆菌：分泌抗菌肽破坏细菌细胞膜，改良土壤；主治土传细菌性病害（茄子黄萎病、辣椒青枯病）；土壤定殖力强，持效25-30天；可拌种、灌根，安全无药害。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000190', 'source-doc-4c784a84a66adf221597', 'source-node-000184', '6', '189', 'text', '解淀粉芽孢杆菌：产抗菌蛋白抑制细菌代谢，诱导作物抗病；防水稻条斑病、草莓角斑病；速效性好（3-5天显效），持效18-22天；耐雨水，忌与乳油类农药混用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000191', 'source-doc-4c784a84a66adf221597', 'source-node-000184', '6', '190', 'text', '枯草芽孢杆菌·地衣芽孢杆菌：协同竞争营养、分泌抗菌物质，兼顾叶面与土传细菌性病害；防白菜软腐病、辣椒青枯病；持效20-25天，适合连作地块，忌与杀菌剂混用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000192', 'source-doc-4c784a84a66adf221597', 'source-node-000184', '6', '191', 'text', '解淀粉芽孢杆菌·荧光假单胞菌：解淀粉芽孢杆菌防叶部病害，荧光假单胞菌防土传病害；主治葡萄溃疡病、西瓜果斑病；速效+持效（15-20天），耐高湿环境。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000193', 'source-doc-4c784a84a66adf221597', 'source-node-000184', '6', '192', 'text', '蜡质芽孢杆菌·多粘类芽孢杆菌：蜡质芽孢杆菌促生，多粘类芽孢杆菌针对性抑菌；防柑橘溃疡病、马铃薯环腐病；安全性高，可用于绿色食品生产，持效15天左右。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000194', 'source-doc-4c784a84a66adf221597', 'source-node-000139', '5', '193', 'text', '其他化学制剂类（作用机制独特，涵盖不同结构类型，补充上述类别的防治空白）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000195', 'source-doc-4c784a84a66adf221597', 'source-node-000194', '6', '194', 'text', '氯溴异氰尿酸：强氧化性杀菌剂，遇水释放次氯酸、溴酸，破坏细菌蛋白质与核酸；广谱防细菌性病害（如水稻白叶枯病、蔬菜软腐病、果树溃疡病），兼防真菌、病毒病；速效性强，但持效期短（5-7天），避免与有机磷、氨基糖苷类抗生素混用（易分解失效）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000196', 'source-doc-4c784a84a66adf221597', 'source-node-000194', '6', '195', 'text', '辛菌胺醋酸盐：破坏细菌细胞膜，促进作物伤口愈合；内吸性好，防苹果腐烂病（细菌性）、柑橘溃疡病、番茄青枯病；可用于果树清园（冬季喷雾），减少病原菌基数，对作物安全性高。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000197', 'source-doc-4c784a84a66adf221597', 'source-node-000194', '6', '196', 'text', '噻霉酮：抑制细菌细胞壁合成与能量代谢，兼具保护与治疗；防黄瓜细菌性角斑病、葡萄细菌性霜霉病（兼防）、番茄细菌性斑点病；低毒低残留，适合蔬菜、果树生长期使用，可混配性广。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000198', 'source-doc-4c784a84a66adf221597', 'source-node-000194', '6', '197', 'text', '代森铵：有机硫类，兼具杀菌、补锌作用，破坏细菌酶系统；防棉花角斑病、水稻白叶枯病、白菜软腐病；可叶面喷雾或土壤消毒（灌根），高温时易产生药害，需控制用量。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000199', 'source-doc-4c784a84a66adf221597', 'source-node-000194', '6', '198', 'text', '氯吡菌酰胺：新型酰胺类，干扰细菌呼吸链；专防细菌性斑点病（番茄、辣椒）、柑橘溃疡病；内吸性强，持效期12-15天，对蜜蜂低毒。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000200', 'source-doc-4c784a84a66adf221597', 'source-node-000194', '6', '199', 'text', '氯溴异氰尿酸·噻唑锌：氯溴异氰尿酸速效杀菌，噻唑锌内吸抑菌；防治白菜软腐病、水稻条斑病；双重机制，抗药性风险低，适合病害爆发期使用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000201', 'source-doc-4c784a84a66adf221597', 'source-node-000194', '6', '200', 'text', '辛菌胺醋酸盐·春雷霉素：辛菌胺破坏细胞膜，春雷霉素抑制蛋白质合成；防柑橘溃疡病、番茄细菌性斑点病；内吸+触杀协同，持效期10天左右，安全性高。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000202', 'source-doc-4c784a84a66adf221597', 'source-node-000194', '6', '201', 'text', '噻霉酮·喹啉铜：噻霉酮抑制细胞壁，喹啉铜（有机铜）破坏细胞膜；防治黄瓜角斑病、葡萄细菌性角斑病；兼防真菌病害，对铜敏感作物安全，耐雨水冲刷。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000203', 'source-doc-4c784a84a66adf221597', 'source-node-000194', '6', '202', 'text', '代森铵·硫酸铜：代森铵抑制酶系统，硫酸铜释放铜离子触杀；防马铃薯环腐病、辣椒疮痂病；适合土壤消毒或喷雾，注意硫酸铜对敏感作物药害风险。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000204', 'source-doc-4c784a84a66adf221597', 'source-node-000194', '6', '203', 'text', '氯吡菌酰胺·中生菌素：氯吡菌酰胺干扰呼吸，中生菌素破坏细胞膜；防苹果细菌性斑点病、水稻白叶枯病；长效+内吸，适合绿色防控，持效期15天以上。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000205', 'source-doc-4c784a84a66adf221597', 'source-node-000047', '3', '204', 'text', '杀虫剂', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000206', 'source-doc-4c784a84a66adf221597', 'source-node-000205', '4', '205', 'text', '作用机制分类', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000207', 'source-doc-4c784a84a66adf221597', 'source-node-000206', '5', '206', 'text', '胃毒剂', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000208', 'source-doc-4c784a84a66adf221597', 'source-node-000207', '6', '207', 'text', '作用原理：害虫取食后，药剂进入消化系统，通过肠道吸收发挥毒杀作用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000209', 'source-doc-4c784a84a66adf221597', 'source-node-000207', '6', '208', 'text', '适用场景：主要用于防治咀嚼式口器害虫（如菜青虫、毛毛虫、甲虫等）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000210', 'source-doc-4c784a84a66adf221597', 'source-node-000207', '6', '209', 'text', '代表药剂：敌百虫、辛硫磷、氯虫苯甲酰胺等：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000211', 'source-doc-4c784a84a66adf221597', 'source-node-000210', '7', '210', 'text', '有机磷类', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000212', 'source-doc-4c784a84a66adf221597', 'source-node-000211', '8', '211', 'text', '敌百虫：具有胃毒和触杀作用，是广谱杀虫剂。可用于防治多种作物上的害虫，如蔬菜上的菜青虫、小菜蛾、豆荚螟、蚜虫、斜纹夜蛾等，果树中的食心虫、潜叶蛾等，以及地下害虫蛴螬等。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000213', 'source-doc-4c784a84a66adf221597', 'source-node-000211', '8', '212', 'text', '毒死蜱（在蔬菜、果树、茶叶、中草药材上不得使用）：具有触杀、胃毒和熏蒸作用，是广谱杀虫、杀螨剂。可用于防治稻、麦、棉、菜、果、茶等多种作物上的害虫，如蔬菜上的菜青虫、小菜蛾、蚜虫、斑潜蝇等，果树上的蚜虫、食心虫、潜叶蛾、卷叶蛾等，以及地下害虫根蛆、蛴螬等。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000214', 'source-doc-4c784a84a66adf221597', 'source-node-000211', '8', '213', 'text', '辛硫磷：具有胃毒和触杀作用，是广谱杀虫剂。可用于防治多种作物上的害虫，如蔬菜上的菜青虫、蚜虫等，以及地下害虫蛴螬、金针虫等。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000215', 'source-doc-4c784a84a66adf221597', 'source-node-000210', '7', '214', 'text', '氨基甲酸酯类', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000216', 'source-doc-4c784a84a66adf221597', 'source-node-000215', '8', '215', 'text', '西维因：具有触杀和胃毒作用，是广谱杀虫剂。可用于防治果树、蔬菜、棉花等作物上的多种害虫，如蚜虫、食心虫、卷叶蛾等。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000217', 'source-doc-4c784a84a66adf221597', 'source-node-000215', '8', '216', 'text', '恶虫威：具有触杀和胃毒作用，兼具植物内吸性。主要用于防治蟑螂、蟋蟀、蚂蚁、臭虫等卫生害虫，也可用作土壤处理防治地下害虫，还可用于防治蔬菜、瓜类、柑桔、马铃薯、水稻、玉米及高粱等作物上的甲虫、蓟马和叶蝉等害虫。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000218', 'source-doc-4c784a84a66adf221597', 'source-node-000210', '7', '217', 'text', '拟除虫菊酯类', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000219', 'source-doc-4c784a84a66adf221597', 'source-node-000218', '8', '218', 'text', '氯氰菊酯：具有强烈的触杀和胃毒作用，是广谱杀虫剂。可用于防治多种作物上的害虫，如棉花上的棉铃虫、蚜虫等，蔬菜上的菜青虫、小菜蛾等。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000220', 'source-doc-4c784a84a66adf221597', 'source-node-000218', '8', '219', 'text', '溴氰菊酯：具有触杀和胃毒作用，杀虫谱广，击倒速度快。可用于防治多种害虫，如鳞翅目害虫的幼虫、蚜虫等。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000221', 'source-doc-4c784a84a66adf221597', 'source-node-000210', '7', '220', 'text', '苯甲酰脲类', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000222', 'source-doc-4c784a84a66adf221597', 'source-node-000221', '8', '221', 'text', '灭幼脲：以胃毒作用为主，兼有触杀作用。对鳞翅目及蚊蝇幼虫活性高，可用于防治桃树潜叶蛾、茶黑毒蛾、茶尺蠖、菜青虫、甘蓝夜蛾、小麦粘虫、玉米螟及毒蛾类、夜蛾类等鳞翅目害虫。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000223', 'source-doc-4c784a84a66adf221597', 'source-node-000221', '8', '222', 'text', '氟铃脲：具触杀、胃毒作用和拒食作用。对鳞翅目、直翅目、鞘翅目、膜翅目和双翅目多种害虫有效，如棉铃虫、甜菜夜蛾、豆荚螟等。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000224', 'source-doc-4c784a84a66adf221597', 'source-node-000210', '7', '223', 'text', '生物源类', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000225', 'source-doc-4c784a84a66adf221597', 'source-node-000224', '8', '224', 'text', '苏云金芽孢杆菌：是一种低毒的细菌性杀虫剂，以胃毒作用为主。对多种鳞翅目害虫有效，如棉铃虫、菜青虫、小菜蛾、斜纹夜蛾、甜菜夜蛾等。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000226', 'source-doc-4c784a84a66adf221597', 'source-node-000224', '8', '225', 'text', '苦参碱：具触杀和胃毒作用，是广谱杀虫杀螨剂。对各种作物上的黏虫、菜青虫、蚜虫、红蜘蛛、绿叶蝉、白粉虱等有较好的防治效果。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000227', 'source-doc-4c784a84a66adf221597', 'source-node-000224', '8', '226', 'text', '鱼藤酮：具触杀、胃毒、生长发育抑制和拒食作用。对昆虫、尤其是蚜虫、蓟马和跳甲有很强的杀除作用，对菜粉蝶幼虫、小菜蛾等幼虫有强烈的触杀和胃毒作用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000228', 'source-doc-4c784a84a66adf221597', 'source-node-000210', '7', '227', 'text', '其他', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000229', 'source-doc-4c784a84a66adf221597', 'source-node-000228', '8', '228', 'text', '氟虫腈：以胃毒为主，兼有触杀作用和一定的内吸作用，是广谱杀虫剂。可用于防治多种害虫，如蓟马、椿象、象甲、蚜虫、飞虱等。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000230', 'source-doc-4c784a84a66adf221597', 'source-node-000228', '8', '229', 'text', '茚虫威：具触杀和胃毒作用，几乎对所有的鳞翅目害虫都有效。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000231', 'source-doc-4c784a84a66adf221597', 'source-node-000228', '8', '230', 'text', '印楝素：具拒食、忌避、触杀、胃毒、内吸和拟制昆虫生长的作用，是高效广谱杀虫剂。可防治棉铃虫、小菜蛾、潜叶蝇、蝗虫、玉米螟、蓟马、金龟子等。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000232', 'source-doc-4c784a84a66adf221597', 'source-node-000206', '5', '231', 'text', '触杀剂', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000233', 'source-doc-4c784a84a66adf221597', 'source-node-000232', '6', '232', 'text', '作用原理：药剂接触害虫体表后，通过体壁渗透进入体内，破坏生理机能导致死亡。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000234', 'source-doc-4c784a84a66adf221597', 'source-node-000232', '6', '233', 'text', '适用场景：对咀嚼式和刺吸式口器害虫均有效（如蚜虫、飞虱、蟑螂等），但需直接接触虫体。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000235', 'source-doc-4c784a84a66adf221597', 'source-node-000232', '6', '234', 'text', '代表药剂：氯氰菊酯、溴氰菊酯（拟除虫菊酯类）、马拉硫磷等：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000236', 'source-doc-4c784a84a66adf221597', 'source-node-000235', '7', '235', 'text', '有机磷类', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000237', 'source-doc-4c784a84a66adf221597', 'source-node-000236', '8', '236', 'text', '敌敌畏：具有熏蒸、胃毒和触杀作用，广谱速效，对咀嚼式口器和刺吸式口器害虫防效好，击倒力强，易分解，持效期短。可用于防治蚊、蝇、蟑螂等卫生害虫，以及蔬菜、果树、粮食作物上的多种害虫。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000238', 'source-doc-4c784a84a66adf221597', 'source-node-000236', '8', '237', 'text', '丙溴磷：中等毒性，具有触杀、胃毒、熏蒸和渗透作用，是广谱杀虫剂、杀螨剂。可用于防治棉花、果树、蔬菜等作物上的棉铃虫、钻心虫、潜叶蝇、飞虱、食心虫、蚜虫、叶螨等害虫。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000239', 'source-doc-4c784a84a66adf221597', 'source-node-000236', '8', '238', 'text', '马拉硫磷：具有良好的触杀、胃毒和微弱的熏蒸作用。可用于防治多种作物上的咀嚼式口器和刺吸式口器害虫，如蔬菜上的蚜虫、菜青虫，果树中的蚜虫等。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000240', 'source-doc-4c784a84a66adf221597', 'source-node-000236', '8', '239', 'text', '喹硫磷：具有胃毒和触杀作用，无内吸和熏蒸性能，有良好的渗透性，有一定杀卵作用。可用于防治咀嚼式和吮吸式害虫，如蔬菜上的菜青虫、蚜虫等。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000241', 'source-doc-4c784a84a66adf221597', 'source-node-000236', '8', '240', 'text', '杀扑磷（已禁用）：具有触杀、胃毒和渗透作用，对咀嚼式和刺吸式口器害虫均有效，对介壳虫有特效，对螨类有一定的控制作用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000242', 'source-doc-4c784a84a66adf221597', 'source-node-000235', '7', '241', 'text', '氨基甲酸酯类', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000243', 'source-doc-4c784a84a66adf221597', 'source-node-000242', '8', '242', 'text', '异丙威：中等毒性，触杀作用强，有一定的渗透和传导活性，速效性强。主要用于防治水稻飞虱和叶蝉，也能兼治蓟马。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000244', 'source-doc-4c784a84a66adf221597', 'source-node-000242', '8', '243', 'text', '灭多威（已禁用）：具有触杀和胃毒作用，无内吸、熏蒸作用，具有一定的杀卵效果，对有机磷已经产生抗性的害虫也有较好防效。可用于防治多种害虫，如棉铃虫、蚜虫等。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000245', 'source-doc-4c784a84a66adf221597', 'source-node-000242', '8', '244', 'text', '硫双威：属氨基甲酰肟类杀虫剂，具有一定的触杀作用和胃毒作用，对主要的鳞翅目、鞘翅目和双翅目害虫有效。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000246', 'source-doc-4c784a84a66adf221597', 'source-node-000235', '7', '245', 'text', '拟除虫菊酯类', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000247', 'source-doc-4c784a84a66adf221597', 'source-node-000246', '8', '246', 'text', '溴氰菊酯：具强触杀作用、胃毒作用与忌避活性，击倒快，无内吸活性及熏蒸作用。可用于防治多种害虫，如鳞翅目害虫的幼虫、蚜虫等。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000248', 'source-doc-4c784a84a66adf221597', 'source-node-000246', '8', '247', 'text', '氯氰菊酯：高效、广谱触杀性拟除虫菊酯类杀虫剂，有一定胃毒作用与忌避活性，无内吸活性及熏蒸作用。可用于防治棉花、蔬菜、果树等作物上的多种害虫，如棉铃虫、菜青虫、蚜虫等。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000249', 'source-doc-4c784a84a66adf221597', 'source-node-000246', '8', '248', 'text', '氰戊菊酯：高效、广谱触杀性拟除虫菊酯类杀虫剂，有一定胃毒作用与忌避活性，无内吸活性及熏蒸作用。可用于防治多种草坪害虫及果树、蔬菜等作物上的害虫。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000250', 'source-doc-4c784a84a66adf221597', 'source-node-000246', '8', '249', 'text', '联苯菊酯：具有触杀、胃毒作用，兼有驱避和拒食作用，是广谱杀虫杀螨剂。可用于防治棉铃虫、棉红蜘蛛、桃小食心虫、梨小食心虫、山楂叶螨、红蜘蛛、菜青虫、小菜蛾、蚜虫等多种害虫。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000251', 'source-doc-4c784a84a66adf221597', 'source-node-000235', '7', '250', 'text', '有机氮类', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000252', 'source-doc-4c784a84a66adf221597', 'source-node-000251', '8', '251', 'text', '唑虫酰胺：中等毒性，以触杀作用为主。主要用于防治蓟马、蝽象、蚜虫、粉虱、甲虫等害虫。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000253', 'source-doc-4c784a84a66adf221597', 'source-node-000251', '8', '252', 'text', '烟碱：高等毒性，具有触杀、胃毒和熏蒸作用。可用于防治蚜虫、蓟马、椿象、卷叶虫、菜青虫、飞虱、叶跳虫、大豆食心虫、潜叶蝇、潜叶蛾、食心虫、叶蝉、跳甲、螨等害虫。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000254', 'source-doc-4c784a84a66adf221597', 'source-node-000235', '7', '253', 'text', '杂环类', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000255', 'source-doc-4c784a84a66adf221597', 'source-node-000254', '8', '254', 'text', '噻虫嗪：低毒广谱，具有胃毒、触杀和强内吸作用。可防治蚜虫、叶蝉、飞虱、蓟马、粉蚧、蛴螬、叶甲、潜叶蝇、线虫等害虫。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000256', 'source-doc-4c784a84a66adf221597', 'source-node-000254', '8', '255', 'text', '吡蚜酮：低毒，具有触杀和内吸作用。主要防治蚜虫、叶蝉、飞虱、粉虱等害虫。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000257', 'source-doc-4c784a84a66adf221597', 'source-node-000254', '8', '256', 'text', '灭蝇胺：低毒，具有内吸传导作用，对双翅目害虫有特殊活性，主要用于防治苍蝇、蚊子等卫生害虫，以及蔬菜、花卉等作物上的斑潜蝇等害虫。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000258', 'source-doc-4c784a84a66adf221597', 'source-node-000235', '7', '257', 'text', '生物源类', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000259', 'source-doc-4c784a84a66adf221597', 'source-node-000258', '8', '258', 'text', '阿维菌素：高毒，广谱，具有触杀、胃毒和微弱的熏蒸作用。可用于防治多种害虫和螨类，如蔬菜上的菜青虫、蚜虫、螨类等，果树上的红蜘蛛、锈壁虱等。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000260', 'source-doc-4c784a84a66adf221597', 'source-node-000258', '8', '259', 'text', '多杀菌素：低毒，广谱杀虫剂，具有触杀和胃毒作用，有较强的渗透作用，杀虫迅速，对一些害虫还有杀卵作用。可用于防治鳞翅目、双翅目、缨翅目害虫和一些直翅目、鞘翅目害虫。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000261', 'source-doc-4c784a84a66adf221597', 'source-node-000258', '8', '260', 'text', '苦参碱：低毒，具触杀和胃毒作用，是广谱杀虫杀螨剂。对各种作物上的黏虫、菜青虫、蚜虫、红蜘蛛、绿叶蝉、白粉虱等有较好的防治效果。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000262', 'source-doc-4c784a84a66adf221597', 'source-node-000235', '7', '261', 'text', '杀螨剂类', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000263', 'source-doc-4c784a84a66adf221597', 'source-node-000262', '8', '262', 'text', '哒螨灵：低毒，触杀作用强，广谱，在 20-30℃使用效果好。对红蜘蛛卵、若螨、成螨均有效。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000264', 'source-doc-4c784a84a66adf221597', 'source-node-000262', '8', '263', 'text', '唑螨酯：中等毒性，广谱，具触杀、胃毒作用，速效性好，对各个生育期的螨类都有效。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000265', 'source-doc-4c784a84a66adf221597', 'source-node-000262', '8', '264', 'text', '联苯肼酯：防治谱广、安全，击倒性强、性能稳定，不受光、热等的影响，耐雨水冲刷、持效性好，能迅速降低害螨的基数，既杀卵又杀成螨。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000266', 'source-doc-4c784a84a66adf221597', 'source-node-000262', '8', '265', 'text', '螺螨酯：卵虫幼虫兼杀，杀卵的效果特别好，同时对幼若螨也有较好的触杀作用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000267', 'source-doc-4c784a84a66adf221597', 'source-node-000262', '8', '266', 'text', '乙唑螨腈：对不同生育阶段的害螨（卵、幼螨、若螨、成螨）均有效，受温度影响小，具有作用速度快、持效期长、对非靶标生物安全等特点。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000268', 'source-doc-4c784a84a66adf221597', 'source-node-000235', '7', '267', 'text', '其他', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000269', 'source-doc-4c784a84a66adf221597', 'source-node-000268', '8', '268', 'text', '杀虫双：对害虫具有较强的触杀、胃毒作用，并兼有一定的熏蒸作用。可用于防治水稻二化螟、三化螟、大螟、潜叶蛾、茶细蛾、小叶绿蝉、风蝶、菜青虫、小菜蛾、茶尺蠖等害虫。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000270', 'source-doc-4c784a84a66adf221597', 'source-node-000268', '8', '269', 'text', '四聚乙醛：中等毒性，具触杀和胃毒作用。主要用于防治蜗牛、蛞蝓等软体动物。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000271', 'source-doc-4c784a84a66adf221597', 'source-node-000206', '5', '270', 'text', '内吸剂', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000272', 'source-doc-4c784a84a66adf221597', 'source-node-000271', '6', '271', 'text', '作用原理：药剂被植物吸收后，在植物体内传导（如叶片、茎秆、根系），害虫取食植物组织时摄入药剂中毒。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000273', 'source-doc-4c784a84a66adf221597', 'source-node-000271', '6', '272', 'text', '适用场景：防治刺吸式口器害虫（如蚜虫、叶蝉、红蜘蛛等），尤其适用于隐蔽性害虫。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000274', 'source-doc-4c784a84a66adf221597', 'source-node-000271', '6', '273', 'text', '代表药剂：乐果、吡虫啉、噻虫嗪等：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000275', 'source-doc-4c784a84a66adf221597', 'source-node-000274', '7', '274', 'text', '有机磷类', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000276', 'source-doc-4c784a84a66adf221597', 'source-node-000275', '8', '275', 'text', '氧乐果（已禁用）：具有较强的内吸性、触杀和胃毒作用。主要用于防治刺吸式口器害虫，如棉花、果树、蔬菜上的蚜虫、红蜘蛛等。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000277', 'source-doc-4c784a84a66adf221597', 'source-node-000275', '8', '276', 'text', '甲拌磷：高毒，具有内吸、触杀和胃毒作用。主要用于防治棉花、大豆、花生等作物上的地下害虫和苗期害虫，如蚜虫、蓟马、地老虎等。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000278', 'source-doc-4c784a84a66adf221597', 'source-node-000275', '8', '277', 'text', '甲基异柳磷：高毒，具有内吸、触杀和胃毒作用。主要用于防治地下害虫，如蛴螬、蝼蛄、金针虫等，也可用于防治蚜虫、飞虱等地上害虫。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000279', 'source-doc-4c784a84a66adf221597', 'source-node-000275', '8', '278', 'text', '乐果：具有内吸、触杀和胃毒作用。主要用于防治多种作物上的刺吸式口器害虫，如蚜虫、叶蝉、飞虱等，也可用于防治一些咀嚼式口器害虫。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000280', 'source-doc-4c784a84a66adf221597', 'source-node-000274', '7', '279', 'text', '氨基甲酸酯类', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000281', 'source-doc-4c784a84a66adf221597', 'source-node-000280', '8', '280', 'text', '克百威（已禁用）：高毒，具有内吸、触杀和胃毒作用。主要用于防治水稻、棉花、蔬菜、果树等作物上的多种害虫，如蚜虫、飞虱、蓟马、螟虫等。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000282', 'source-doc-4c784a84a66adf221597', 'source-node-000280', '8', '281', 'text', '丁硫克百威（已禁用）：中等毒性，具有内吸、触杀和胃毒作用。主要用于防治蚜虫、飞虱、蓟马、叶蝉等刺吸式口器害虫，以及一些鳞翅目害虫。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000283', 'source-doc-4c784a84a66adf221597', 'source-node-000280', '8', '282', 'text', '残杀威：具有内吸、触杀和胃毒作用，高效低毒、击倒快，持效期长，杀虫广谱。主要用于防治家庭卫生害虫，如蚊、蝇、蟑螂等。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000284', 'source-doc-4c784a84a66adf221597', 'source-node-000280', '8', '283', 'text', '涕灭威（已禁用）：高毒，具有触杀、胃毒、内吸作用。主要用于防治棉花害虫如棉蚜、棉红蜘蛛、棉蓟马等，也可防治甜菜、麻类及花卉害虫。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000285', 'source-doc-4c784a84a66adf221597', 'source-node-000274', '7', '284', 'text', '新烟碱类', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000286', 'source-doc-4c784a84a66adf221597', 'source-node-000285', '8', '285', 'text', '吡虫啉：具有内吸、触杀和胃毒作用，是烟酸乙酰胆碱酯酶受体的作用体，干扰害虫运动神经系统使化学信号传递失灵。主要用于防治水稻、棉花等作物上的刺吸式口器害虫，如蚜虫、叶蝉、蓟马、白粉虱等。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000287', 'source-doc-4c784a84a66adf221597', 'source-node-000285', '8', '286', 'text', '噻虫嗪：第二代新烟碱类杀虫剂，对害虫具有胃毒、触杀、内吸作用，作用速度快、持效期长。可有效防治鳞翅目、鞘翅目、缨翅目以及同翅目害虫，如蚜虫、叶蝉、粉虱、飞虱等。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000288', 'source-doc-4c784a84a66adf221597', 'source-node-000285', '8', '287', 'text', '啶虫脒：具有内吸、触杀和胃毒作用。主要用于防治半翅目害虫，如蚜虫、叶蝉、粉虱、蓟马等，也可用于防治鳞翅目、鞘翅目害虫。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000289', 'source-doc-4c784a84a66adf221597', 'source-node-000285', '8', '288', 'text', '烯啶虫胺：具有内吸、触杀和胃毒作用。主要用于防治刺吸式口器害虫，如蚜虫、飞虱、蓟马、粉虱等。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000290', 'source-doc-4c784a84a66adf221597', 'source-node-000274', '7', '289', 'text', '其他类', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000291', 'source-doc-4c784a84a66adf221597', 'source-node-000290', '8', '290', 'text', '杀虫双：沙蚕毒素类杀虫剂，有很强的内吸作用，能被作物的叶、根等吸收和传导。可用于防治水稻螟虫、纵卷叶螟、稻苞虫、蓟马、叶蝉、飞虱，蔬菜菜青虫、小菜蛾等害虫。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000292', 'source-doc-4c784a84a66adf221597', 'source-node-000290', '8', '291', 'text', '氟虫腈：苯基吡唑类杀虫剂，具有触杀、胃毒和内吸作用，杀虫谱广。对鳞翅目、蝇类和鞘翅目等一系列重要害虫有很高的杀虫活性。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000293', 'source-doc-4c784a84a66adf221597', 'source-node-000290', '8', '292', 'text', '双甲脒：广谱杀螨剂，具有触杀、拒食、驱避作用，也有一定的胃毒、熏蒸和内吸作用。主要用于防治螨类害虫。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000294', 'source-doc-4c784a84a66adf221597', 'source-node-000290', '8', '293', 'text', '螺虫乙酯：具有内吸性，能在植物体内双向传导。主要用于防治刺吸式口器害虫，如蚜虫、粉虱、介壳虫等。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000295', 'source-doc-4c784a84a66adf221597', 'source-node-000206', '5', '294', 'text', '熏蒸剂', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000296', 'source-doc-4c784a84a66adf221597', 'source-node-000295', '6', '295', 'text', '作用原理：药剂挥发为气体，通过害虫呼吸系统进入体内，抑制呼吸酶或破坏代谢。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000297', 'source-doc-4c784a84a66adf221597', 'source-node-000295', '6', '296', 'text', '适用场景：用于密闭空间（如仓库、温室、土壤），防治仓储害虫（如米虫）、地下害虫或熏蒸消毒。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000298', 'source-doc-4c784a84a66adf221597', 'source-node-000295', '6', '297', 'text', '代表药剂：磷化铝、溴甲烷（已禁用，仅可用于检疫熏蒸处理）、敌敌畏（兼具熏蒸作用）等：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000299', 'source-doc-4c784a84a66adf221597', 'source-node-000298', '7', '298', 'text', '磷化铝：属于熏蒸杀虫剂，仅用于熏杀谷物的储粮害虫。吸水后产生有毒的磷化氢气体，通过昆虫的呼吸系统进入虫体，抑制昆虫的正常呼吸使昆虫致死。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000300', 'source-doc-4c784a84a66adf221597', 'source-node-000298', '7', '299', 'text', '硫酰氟：常温下是无色无味气体，具有杀虫广谱、扩散渗透性强等特点。可广泛应用于仓库、船舶、车厢、集装箱等货物杀虫、灭鼠，也可作为土壤熏蒸剂防治根结线虫病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000301', 'source-doc-4c784a84a66adf221597', 'source-node-000298', '7', '300', 'text', '溴甲烷（已禁用，仅可用于检疫熏蒸处理）：曾是广泛使用的熏蒸剂，但因破坏大气臭氧层，在《蒙特利尔议定书》中被列为淘汰产品。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000302', 'source-doc-4c784a84a66adf221597', 'source-node-000298', '7', '301', 'text', '氯化苦：是一种熏蒸性杀虫剂，具有强烈的刺激性气味，能通过害虫的呼吸系统进入虫体，使其中毒死亡，常用于土壤熏蒸和仓库熏蒸。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000303', 'source-doc-4c784a84a66adf221597', 'source-node-000298', '7', '302', 'text', '棉隆：是一种低毒的土壤消毒剂，施用于潮湿的土壤中时，会产生异硫氰酸甲酯气体，能有效地杀死各种线虫及防治根腐病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000304', 'source-doc-4c784a84a66adf221597', 'source-node-000298', '7', '303', 'text', '威百亩：通常被划为具有熏蒸作用的二硫代氨基甲酸酯类杀线虫剂，在土壤中降解成异硫氰酸甲酯发挥熏蒸作用，能有效杀灭根结线虫、杂草等有害生物。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000305', 'source-doc-4c784a84a66adf221597', 'source-node-000298', '7', '304', 'text', '1,3 - 二氯丙烯：是一种有机氯化合物，主要用作种植前的熏蒸剂和杀线虫剂，可有效防治土壤中的线虫等有害生物，但在 34 个国家（包括欧盟）被禁止使用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000306', 'source-doc-4c784a84a66adf221597', 'source-node-000298', '7', '305', 'text', '敌敌畏：中等毒性，具有熏蒸、胃毒和触杀作用，广谱速效，对咀嚼式口器和刺吸式口器防效好，击倒力强，易分解持效期短。可用于防治蔬菜、果树、林业、茶叶、棉花及临近收获作物的害虫，也可用于防治蚊、蝇等卫生害虫和仓库害虫。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000307', 'source-doc-4c784a84a66adf221597', 'source-node-000206', '5', '306', 'text', '特异性杀虫剂', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000308', 'source-doc-4c784a84a66adf221597', 'source-node-000307', '6', '307', 'text', '作用原理：不直接毒杀害虫，而是干扰其生长发育、繁殖或行为（如抑制蜕皮、破坏生殖、引诱 / 驱避）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000309', 'source-doc-4c784a84a66adf221597', 'source-node-000307', '6', '308', 'text', '细分类型：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000310', 'source-doc-4c784a84a66adf221597', 'source-node-000309', '7', '309', 'text', '昆虫生长调节剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000311', 'source-doc-4c784a84a66adf221597', 'source-node-000310', '8', '310', 'text', '几丁质合成抑制剂：如灭幼脲、除虫脲、氟虫脲、氟铃脲、噻嗪酮等。灭幼脲能抑制害虫的卵壳、蛹皮、幼虫的表皮几丁质的合成，主要用于防治鳞翅目害虫；噻嗪酮对飞虱、叶蝉、蚧类等同翅目和半翅目害虫有高度选择性，通过抑制若虫脱皮而导致死亡。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000312', 'source-doc-4c784a84a66adf221597', 'source-node-000310', '8', '311', 'text', '保幼激素类似物：如保幼炔、哒嗪酮类似物等，可控制害虫的生长发育，使虫态间变态受阻，形成超龄幼（若）虫，或形成蛹至成虫的中间体。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000313', 'source-doc-4c784a84a66adf221597', 'source-node-000310', '8', '312', 'text', '脱皮激素：如虫酰肼，具有胃毒、触杀作用，能抑制害虫产卵，对鳞翅目及某些同翅目和双翅目害虫有高效。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000314', 'source-doc-4c784a84a66adf221597', 'source-node-000309', '7', '313', 'text', '引诱剂：主要有性引诱剂，如桃小食心虫性诱剂、葡萄透翅蛾性诱剂等，以微量的气态分子将害虫引诱在一起集中歼灭。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000315', 'source-doc-4c784a84a66adf221597', 'source-node-000309', '7', '314', 'text', '趋避剂：如驱蚊油、樟脑等，作用于保护对象，使害虫不愿意接近或发生转移、潜逃，达到保护作物的目的。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000316', 'source-doc-4c784a84a66adf221597', 'source-node-000309', '7', '315', 'text', '拒食剂：如印楝素、拒食胺等，药剂被害虫取食后，破坏害虫的正常生理功能，使其取食量减少或者很快停止取食，最后引起害虫饥饿死亡。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000317', 'source-doc-4c784a84a66adf221597', 'source-node-000309', '7', '316', 'text', '病毒类杀虫剂：主要包含杆状病毒科的核型多角体病毒（NPV）、颗粒体病毒（GV）以及质型多角体病毒（CPV）三大类。常见的有棉铃虫核型多角体病毒、甘蓝夜蛾核型多角体病毒、小菜蛾颗粒体病毒等，这些病毒杀虫剂通过感染靶标害虫使其患病死亡，具备高度专一性、环境安全性和持久防控效果。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000318', 'source-doc-4c784a84a66adf221597', 'source-node-000205', '4', '317', 'text', '化学结构分类', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000319', 'source-doc-4c784a84a66adf221597', 'source-node-000318', '5', '318', 'text', '有机磷类', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000320', 'source-doc-4c784a84a66adf221597', 'source-node-000319', '6', '319', 'text', '特点：高效、广谱，但毒性较高（部分为高毒），易分解，残留期较短。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000321', 'source-doc-4c784a84a66adf221597', 'source-node-000319', '6', '320', 'text', '代表药剂：敌敌畏、乐果、辛硫磷、毒死蜱（在蔬菜、果树、茶叶、中草药材上不得使用）（已限制使用）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000322', 'source-doc-4c784a84a66adf221597', 'source-node-000321', '7', '321', 'text', '有机磷类杀虫剂是一类通过抑制害虫胆碱酯酶活性发挥作用的广谱性农药，其品种繁多但部分高毒类型已被禁用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000323', 'source-doc-4c784a84a66adf221597', 'source-node-000321', '7', '322', 'text', '一、磷酸酯类', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000324', 'source-doc-4c784a84a66adf221597', 'source-node-000323', '8', '323', 'text', '1. 敌敌畏（DDVP）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000325', 'source-doc-4c784a84a66adf221597', 'source-node-000324', '9', '324', 'text', '通用名：敌敌畏', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000326', 'source-doc-4c784a84a66adf221597', 'source-node-000324', '9', '325', 'text', '毒性：中等毒（大鼠经口LD₅₀ 50-80 mg/kg）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000327', 'source-doc-4c784a84a66adf221597', 'source-node-000324', '9', '326', 'text', '特点：兼具触杀、胃毒和熏蒸作用，速效性强，残效期短（1-2天），适合蔬菜、果树及卫生害虫防治。但对鱼类和蜜蜂高毒，需远离水源和花期使用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000328', 'source-doc-4c784a84a66adf221597', 'source-node-000324', '9', '327', 'text', '禁用情况：未被全面禁用，但禁止在蔬菜、瓜果等作物上使用高毒有机磷农药的地区需严格遵守当地规定。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000329', 'source-doc-4c784a84a66adf221597', 'source-node-000323', '8', '328', 'text', '2. 敌百虫', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000330', 'source-doc-4c784a84a66adf221597', 'source-node-000329', '9', '329', 'text', '通用名：敌百虫', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000331', 'source-doc-4c784a84a66adf221597', 'source-node-000329', '9', '330', 'text', '毒性：低毒（大鼠经口LD₅₀ 630 mg/kg）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000332', 'source-doc-4c784a84a66adf221597', 'source-node-000329', '9', '331', 'text', '特点：广谱胃毒剂，对咀嚼式口器害虫（如菜青虫、地下蛴螬）特效，在碱性条件下可转化为高毒的敌敌畏，需避免与碱性药剂混用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000333', 'source-doc-4c784a84a66adf221597', 'source-node-000329', '9', '332', 'text', '禁用情况：未被全面禁用，但部分地区限制在蔬菜上使用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000334', 'source-doc-4c784a84a66adf221597', 'source-node-000321', '7', '333', 'text', '二、硫代磷酸酯类', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000335', 'source-doc-4c784a84a66adf221597', 'source-node-000334', '8', '334', 'text', '1. 毒死蜱（在蔬菜、果树、茶叶、中草药材上不得使用）（Chlorpyrifos）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000336', 'source-doc-4c784a84a66adf221597', 'source-node-000335', '9', '335', 'text', '通用名：毒死蜱（在蔬菜、果树、茶叶、中草药材上不得使用）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000337', 'source-doc-4c784a84a66adf221597', 'source-node-000335', '9', '336', 'text', '毒性：中等毒（大鼠经口LD₅₀ 163 mg/kg）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000338', 'source-doc-4c784a84a66adf221597', 'source-node-000335', '9', '337', 'text', '特点：广谱触杀剂，对地下害虫（如蛴螬）和叶面害虫（如蚜虫）均有效，持效期较长（7-10天）。自2020年起禁止在蔬菜上使用，仅限用于大豆、玉米等大田作物。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000339', 'source-doc-4c784a84a66adf221597', 'source-node-000335', '9', '338', 'text', '商品名：乐斯本、新农宝。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000340', 'source-doc-4c784a84a66adf221597', 'source-node-000334', '8', '339', 'text', '2. 辛硫磷（Phoxim）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000341', 'source-doc-4c784a84a66adf221597', 'source-node-000340', '9', '340', 'text', '通用名：辛硫磷', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000342', 'source-doc-4c784a84a66adf221597', 'source-node-000340', '9', '341', 'text', '毒性：低毒（大鼠经口LD₅₀ 2170 mg/kg）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000343', 'source-doc-4c784a84a66adf221597', 'source-node-000340', '9', '342', 'text', '特点：触杀和胃毒作用强，对鳞翅目幼虫（如棉铃虫）和地下害虫（如蝼蛄）特效，但光解速度快，适合傍晚或土壤处理。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000344', 'source-doc-4c784a84a66adf221597', 'source-node-000340', '9', '343', 'text', '禁用情况：未被全面禁用，但部分地区限制在蔬菜上使用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000345', 'source-doc-4c784a84a66adf221597', 'source-node-000334', '8', '344', 'text', '3. 丙溴磷（Profenofos）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000346', 'source-doc-4c784a84a66adf221597', 'source-node-000345', '9', '345', 'text', '通用名：丙溴磷', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000347', 'source-doc-4c784a84a66adf221597', 'source-node-000345', '9', '346', 'text', '毒性：中等毒（大鼠经口LD₅₀ 358 mg/kg）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000348', 'source-doc-4c784a84a66adf221597', 'source-node-000345', '9', '347', 'text', '特点：兼具触杀和胃毒作用，对棉铃虫、潜叶蛾等害虫特效，与其他有机磷类无交互抗性，可用于抗性治理。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000349', 'source-doc-4c784a84a66adf221597', 'source-node-000345', '9', '348', 'text', '禁用情况：未被全面禁用，但需注意作物安全间隔期。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000350', 'source-doc-4c784a84a66adf221597', 'source-node-000321', '7', '349', 'text', '三、二硫代磷酸酯类', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000351', 'source-doc-4c784a84a66adf221597', 'source-node-000350', '8', '350', 'text', '1. 马拉硫磷（Malathion）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000352', 'source-doc-4c784a84a66adf221597', 'source-node-000351', '9', '351', 'text', '通用名：马拉硫磷', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000353', 'source-doc-4c784a84a66adf221597', 'source-node-000351', '9', '352', 'text', '毒性：低毒（大鼠经口LD₅₀ 2800 mg/kg）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000354', 'source-doc-4c784a84a66adf221597', 'source-node-000351', '9', '353', 'text', '特点：广谱触杀剂，对蚜虫、叶蝉等刺吸式口器害虫有效，对蜜蜂低毒，适合果园和蔬菜使用。但对鱼类高毒，需避免污染水源。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000355', 'source-doc-4c784a84a66adf221597', 'source-node-000351', '9', '354', 'text', '商品名：马拉松、防虫磷。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000356', 'source-doc-4c784a84a66adf221597', 'source-node-000350', '8', '355', 'text', '2. 乐果（Dimethoate）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000357', 'source-doc-4c784a84a66adf221597', 'source-node-000356', '9', '356', 'text', '通用名：乐果', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000358', 'source-doc-4c784a84a66adf221597', 'source-node-000356', '9', '357', 'text', '毒性：中等毒（大鼠经口LD₅₀ 245 mg/kg）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000359', 'source-doc-4c784a84a66adf221597', 'source-node-000356', '9', '358', 'text', '特点：内吸性强，对蚜虫、红蜘蛛等刺吸式害虫特效，但对家禽毒性高，需谨慎使用。自2026年6月1日起全面禁止在蔬菜、瓜果等作物上使用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000360', 'source-doc-4c784a84a66adf221597', 'source-node-000356', '9', '359', 'text', '禁用情况：过渡期至2026年6月1日，过渡期内禁止在蔬菜、瓜果、茶叶、菌类、中草药材上使用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000361', 'source-doc-4c784a84a66adf221597', 'source-node-000350', '8', '360', 'text', '3. 氧化乐果（Omethoate）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000362', 'source-doc-4c784a84a66adf221597', 'source-node-000361', '9', '361', 'text', '通用名：氧化乐果', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000363', 'source-doc-4c784a84a66adf221597', 'source-node-000361', '9', '362', 'text', '毒性：高毒（大鼠经口LD₅₀ 50 mg/kg）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000364', 'source-doc-4c784a84a66adf221597', 'source-node-000361', '9', '363', 'text', '特点：内吸性极强，对蚜虫、蓟马等害虫速效，但毒性较高，自2026年6月1日起全面禁止销售和使用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000365', 'source-doc-4c784a84a66adf221597', 'source-node-000361', '9', '364', 'text', '禁用情况：过渡期至2026年6月1日，过渡期内禁止在蔬菜、瓜果、茶叶、菌类、中草药材上使用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000366', 'source-doc-4c784a84a66adf221597', 'source-node-000321', '7', '365', 'text', '四、磷酰胺酯类', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000367', 'source-doc-4c784a84a66adf221597', 'source-node-000366', '8', '366', 'text', '1. 乙酰甲胺磷（Acephate）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000368', 'source-doc-4c784a84a66adf221597', 'source-node-000367', '9', '367', 'text', '通用名：乙酰甲胺磷', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000369', 'source-doc-4c784a84a66adf221597', 'source-node-000367', '9', '368', 'text', '毒性：低毒（大鼠经口LD₅₀ 823 mg/kg）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000370', 'source-doc-4c784a84a66adf221597', 'source-node-000367', '9', '369', 'text', '特点：内吸性杀虫剂，对咀嚼式和刺吸式口器害虫均有效，是甲胺磷的替代品种。自2019年起禁止在蔬菜、瓜果、茶叶、菌类和中草药材作物上使用，仅限用于水稻、小麦等粮食作物。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000371', 'source-doc-4c784a84a66adf221597', 'source-node-000367', '9', '370', 'text', '禁用情况：禁止在蔬菜、瓜果、茶叶、菌类和中草药材作物上使用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000372', 'source-doc-4c784a84a66adf221597', 'source-node-000321', '7', '371', 'text', '五、含杂环的有机磷类', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000373', 'source-doc-4c784a84a66adf221597', 'source-node-000372', '8', '372', 'text', '1. 三唑磷（在蔬菜、果树、茶叶、中草药材上不得使用）（Triazophos）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000374', 'source-doc-4c784a84a66adf221597', 'source-node-000373', '9', '373', 'text', '通用名：三唑磷（在蔬菜、果树、茶叶、中草药材上不得使用）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000375', 'source-doc-4c784a84a66adf221597', 'source-node-000373', '9', '374', 'text', '毒性：中等毒（大鼠经口LD₅₀ 82 mg/kg）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000376', 'source-doc-4c784a84a66adf221597', 'source-node-000373', '9', '375', 'text', '特点：广谱杀虫剂，对水稻螟虫、棉铃虫等害虫有效，但对蜜蜂高毒，需避免花期使用。自2025年起禁止在蔬菜上使用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000377', 'source-doc-4c784a84a66adf221597', 'source-node-000373', '9', '376', 'text', '禁用情况：禁止在蔬菜上使用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000378', 'source-doc-4c784a84a66adf221597', 'source-node-000372', '8', '377', 'text', '2. 喹硫磷（Quinalphos）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000379', 'source-doc-4c784a84a66adf221597', 'source-node-000378', '9', '378', 'text', '通用名：喹硫磷', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000380', 'source-doc-4c784a84a66adf221597', 'source-node-000378', '9', '379', 'text', '毒性：中等毒（大鼠经口LD₅₀ 71 mg/kg）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000381', 'source-doc-4c784a84a66adf221597', 'source-node-000378', '9', '380', 'text', '特点：触杀和胃毒作用强，对水稻飞虱、蔬菜菜青虫等害虫有效，但对鱼类高毒，需远离水源使用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000382', 'source-doc-4c784a84a66adf221597', 'source-node-000378', '9', '381', 'text', '禁用情况：未被全面禁用，但需注意作物安全间隔期。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000383', 'source-doc-4c784a84a66adf221597', 'source-node-000321', '7', '382', 'text', '六、其他类型', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000384', 'source-doc-4c784a84a66adf221597', 'source-node-000383', '8', '383', 'text', '1. 杀扑磷（已禁用）（Methidathion）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000385', 'source-doc-4c784a84a66adf221597', 'source-node-000384', '9', '384', 'text', '通用名：杀扑磷', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000386', 'source-doc-4c784a84a66adf221597', 'source-node-000384', '9', '385', 'text', '毒性：高毒（大鼠经口LD₅₀ 33 mg/kg）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000387', 'source-doc-4c784a84a66adf221597', 'source-node-000384', '9', '386', 'text', '特点：专杀介壳虫的有机磷类药剂，具有触杀和胃毒作用，但毒性较高，自2025年起被列入禁限用名录，禁止在果树、蔬菜等作物上使用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000388', 'source-doc-4c784a84a66adf221597', 'source-node-000384', '9', '387', 'text', '禁用情况：禁止在果树、蔬菜等作物上使用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000389', 'source-doc-4c784a84a66adf221597', 'source-node-000321', '7', '388', 'text', '七、已禁用的高毒有机磷类杀虫剂', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000390', 'source-doc-4c784a84a66adf221597', 'source-node-000389', '8', '389', 'text', '以下品种已被中国全面禁止在农业上使用，仅作历史参考：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000391', 'source-doc-4c784a84a66adf221597', 'source-node-000389', '8', '390', 'text', '甲胺磷、对硫磷（1605）、甲基对硫磷（甲基1605）、久效磷、磷胺（均于2007年全面禁用）；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000392', 'source-doc-4c784a84a66adf221597', 'source-node-000389', '8', '391', 'text', '甲拌磷（3911）、甲基异柳磷、水胺硫磷（均自2024年9月1日起禁止销售和使用）；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000393', 'source-doc-4c784a84a66adf221597', 'source-node-000389', '8', '392', 'text', '内吸磷、硫环磷、氯唑磷（禁止在蔬菜、瓜果、茶叶、中草药材上使用）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000394', 'source-doc-4c784a84a66adf221597', 'source-node-000318', '5', '393', 'text', '拟除虫菊酯类', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000395', 'source-doc-4c784a84a66adf221597', 'source-node-000394', '6', '394', 'text', '特点：低毒、高效、速效，对鳞翅目害虫效果好，但长期使用易导致害虫抗药性。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000396', 'source-doc-4c784a84a66adf221597', 'source-node-000394', '6', '395', 'text', '代表药剂：氯氰菊酯、溴氰菊酯、氰戊菊酯：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000397', 'source-doc-4c784a84a66adf221597', 'source-node-000396', '7', '396', 'text', '溴氰菊酯（Deltamethrin）：高效广谱，对鳞翅目、鞘翅目害虫特效，常用于蔬菜、果树及卫生领域。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000398', 'source-doc-4c784a84a66adf221597', 'source-node-000396', '7', '397', 'text', '氯氰菊酯（Cypermethrin）：触杀胃毒作用强，用于防治棉铃虫、蚜虫等，存在多种异构体（如 alpha-、beta-、zeta - 氯氰菊酯）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000399', 'source-doc-4c784a84a66adf221597', 'source-node-000396', '7', '398', 'text', '高效氯氟氰菊酯（Lambda-Cyhalothrin）：杀虫速度快，兼具杀螨活性，俗称 “功夫菊酯”，广泛用于蔬菜、棉花等作物。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000400', 'source-doc-4c784a84a66adf221597', 'source-node-000396', '7', '399', 'text', '联苯菊酯（Bifenthrin）：杀虫杀螨双效，对蚜虫、红蜘蛛有效，常用于果树和大田作物。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000401', 'source-doc-4c784a84a66adf221597', 'source-node-000396', '7', '400', 'text', '氟氯氰菊酯（Cyfluthrin）：对刺吸式和咀嚼式害虫均有效，持效期长，适用于小麦、玉米等。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000402', 'source-doc-4c784a84a66adf221597', 'source-node-000396', '7', '401', 'text', '氰戊菊酯（Fenvalerate）：对鳞翅目幼虫高效，曾广泛用于棉花、果树，但因抗性问题应用减少。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000403', 'source-doc-4c784a84a66adf221597', 'source-node-000396', '7', '402', 'text', '甲氰菊酯（Fenpropathrin）：杀虫杀螨活性高，对叶螨、蚜虫特效，常用于柑橘、蔬菜。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000404', 'source-doc-4c784a84a66adf221597', 'source-node-000396', '7', '403', 'text', '氯菊酯（Permethrin）：低毒广谱，常用于卫生害虫防治（如驱蚊），农业上用于蔬菜、茶叶。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000405', 'source-doc-4c784a84a66adf221597', 'source-node-000396', '7', '404', 'text', '氟氰戊菊酯（Flucythrinate）：对蚜虫、叶蝉高效，曾用于小麦、果树，但近年应用受限。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000406', 'source-doc-4c784a84a66adf221597', 'source-node-000396', '7', '405', 'text', '氯氟氰菊酯（Cyhalothrin）：与高效氯氟氰菊酯类似，杀虫谱广，适用于多种作物。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000407', 'source-doc-4c784a84a66adf221597', 'source-node-000318', '5', '406', 'text', '氨基甲酸酯类', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000408', 'source-doc-4c784a84a66adf221597', 'source-node-000407', '6', '407', 'text', '特点：毒性中等，作用机制与有机磷类似（抑制胆碱酯酶），但降解快，残留低。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000409', 'source-doc-4c784a84a66adf221597', 'source-node-000407', '6', '408', 'text', '代表药剂： carbaryl（西维因）、灭多威（已禁用）、异丙威。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000410', 'source-doc-4c784a84a66adf221597', 'source-node-000409', '7', '409', 'text', '1. 西维因（Carbaryl）：广谱触杀/胃毒型，曾广泛用于果树、蔬菜防治多种害虫，现因抗性问题应用减少', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000411', 'source-doc-4c784a84a66adf221597', 'source-node-000409', '7', '410', 'text', '2. 仲丁威（Fenobucarb）：触杀为主，对稻飞虱、叶蝉特效，持效期短，主要用于水稻田', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000412', 'source-doc-4c784a84a66adf221597', 'source-node-000409', '7', '411', 'text', '3. 残杀威（Propoxur）：兼具触杀、胃毒、熏蒸作用，农业上用于防治仓储害虫及部分作物叶面害虫', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000413', 'source-doc-4c784a84a66adf221597', 'source-node-000409', '7', '412', 'text', '4. 速灭威（Metolcarb）：击倒速度快，低温环境下仍有效，主打防治水稻飞虱、茶小绿叶蝉', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000414', 'source-doc-4c784a84a66adf221597', 'source-node-000409', '7', '413', 'text', '5. 叶蝉散（Isoprocarb）：选择性强，仅对稻叶蝉高效，持效期短（3-4天），水稻田专用', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000415', 'source-doc-4c784a84a66adf221597', 'source-node-000409', '7', '414', 'text', '6. 克百威（已禁用）（Carbofuran）：内吸性极强，剧毒，过渡期（至2026年6月）内仅限用于甘蔗，之后禁止农业使用', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000416', 'source-doc-4c784a84a66adf221597', 'source-node-000409', '7', '415', 'text', '7. 抗蚜威（Pirimicarb）：选择性杀蚜剂，对蚜虫天敌安全，适用于蔬菜、烟草、果树防治蚜虫', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000417', 'source-doc-4c784a84a66adf221597', 'source-node-000409', '7', '416', 'text', '8. 异索威（Isolan）：中等毒性，用于果树防治蚜虫、食心虫等害虫，农业应用范围较窄', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000418', 'source-doc-4c784a84a66adf221597', 'source-node-000409', '7', '417', 'text', '9. 地麦威（Dimetan）：早期开发品种，具触杀/胃毒作用，曾用于防治作物蚜虫、螨类，现因药效问题应用较少', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000419', 'source-doc-4c784a84a66adf221597', 'source-node-000409', '7', '418', 'text', '10. 灭多威（已禁用）（Methomyl）：高效广谱，高毒，过渡期（至2026年6月）内仅限特定作物（如棉花）使用，之后禁止农业使用', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000420', 'source-doc-4c784a84a66adf221597', 'source-node-000409', '7', '419', 'text', '11. 涕灭威（已禁用）（Aldicarb）：内吸性突出，剧毒，过渡期（至2026年6月）内仅限用于棉花、花生，之后禁止农业使用', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000421', 'source-doc-4c784a84a66adf221597', 'source-node-000409', '7', '420', 'text', '12. 硫双威（Thiodicarb）：灭多威（已禁用）的低毒化改进品种，触杀/胃毒作用，用于防治棉花、蔬菜等作物的鳞翅目幼虫', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000422', 'source-doc-4c784a84a66adf221597', 'source-node-000409', '7', '421', 'text', '13. 呋线威（Furathiocarb）：低毒，兼具杀虫、杀线虫作用，农业上用于防治作物地下害虫及根际线虫', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000423', 'source-doc-4c784a84a66adf221597', 'source-node-000409', '7', '422', 'text', '14. 棉铃威（Alanycarb）：内吸性，主打防治棉铃虫、棉花蚜虫，对蜜蜂相对安全，适用于棉花产区', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000424', 'source-doc-4c784a84a66adf221597', 'source-node-000409', '7', '423', 'text', '15. 丁酮威（Butocarboxim）：中等毒性，具触杀/内吸作用，用于果树防治螨类、蚜虫及部分鳞翅目害虫', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000425', 'source-doc-4c784a84a66adf221597', 'source-node-000409', '7', '424', 'text', '16. 唑蚜威（Triazamate）：内吸性强，对抗性蚜虫、蓟马特效，适用于蔬菜、果树等作物', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000426', 'source-doc-4c784a84a66adf221597', 'source-node-000409', '7', '425', 'text', '17. 蜱虱威（Promacyl）：中等毒性，农业上用于防治家畜体外寄生虫（如蜱、虱）及作物上的刺吸式害虫', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000427', 'source-doc-4c784a84a66adf221597', 'source-node-000409', '7', '426', 'text', '18. 涕灭砜威（Aldoxycarb）：涕灭威（已禁用）衍生物，毒性较原药降低，用于作物防治根线虫及叶面蚜虫', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000428', 'source-doc-4c784a84a66adf221597', 'source-node-000409', '7', '427', 'text', '19. 戊氰威（Nitrilacarb）：高毒，曾用于棉花防治棉铃虫、红铃虫，现因毒性问题农业应用受限', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000429', 'source-doc-4c784a84a66adf221597', 'source-node-000409', '7', '428', 'text', '20. 丁酮砜威（Butoxycarboxim）：低毒，具触杀/胃毒作用，用于蔬菜、豆类防治蚜虫、菜青虫等害虫', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000430', 'source-doc-4c784a84a66adf221597', 'source-node-000318', '5', '429', 'text', '新烟碱类', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000431', 'source-doc-4c784a84a66adf221597', 'source-node-000430', '6', '430', 'text', '特点：内吸性强、低毒、持效期长，对刺吸式害虫特效，但部分药剂对蜜蜂有毒性。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000432', 'source-doc-4c784a84a66adf221597', 'source-node-000430', '6', '431', 'text', '代表药剂：吡虫啉、噻虫嗪、啶虫脒：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000433', 'source-doc-4c784a84a66adf221597', 'source-node-000432', '7', '432', 'text', '吡虫啉（Imidacloprid）：首个商业化品种，强内吸性，广谱防治蚜虫、飞虱、蓟马等刺吸式害虫，适用于种子处理和叶面喷雾。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000434', 'source-doc-4c784a84a66adf221597', 'source-node-000432', '7', '433', 'text', '啶虫脒（Acetamiprid）：对蚜虫、叶蝉、粉虱高效，兼具杀螨活性，低温下仍有效，与传统农药无交互抗性。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000435', 'source-doc-4c784a84a66adf221597', 'source-node-000432', '7', '434', 'text', '噻虫啉（Thiacloprid）：干扰乙酰胆碱传导，对刺吸式和咀嚼式害虫均有效，尤其对梨木虱、苹果绵蚜特效，适合抗性治理。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000436', 'source-doc-4c784a84a66adf221597', 'source-node-000432', '7', '435', 'text', '氯噻啉（Imidaclothiz）：活性是吡虫啉的 20 倍，不受温度影响，对水稻二化螟、三化螟毒力高，适合低温季节防治蚜虫、飞虱。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000437', 'source-doc-4c784a84a66adf221597', 'source-node-000432', '7', '436', 'text', '噻虫嗪（Thiamethoxam）：第二代新烟碱类，内吸传导性强，持效期 4-8 周，常用于种子处理防治地下害虫和苗期蚜虫。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000438', 'source-doc-4c784a84a66adf221597', 'source-node-000432', '7', '437', 'text', '噻虫胺（Clothianidin）：与噻虫嗪同属吡啶类，具触杀、胃毒和内吸活性，对水稻飞虱、小麦蚜虫防效优异，常与拟除虫菊酯复配。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000439', 'source-doc-4c784a84a66adf221597', 'source-node-000432', '7', '438', 'text', '呋虫胺（Dinotefuran）：唯一含四氢呋喃结构，水溶性高，渗透力强，对卫生害虫也有效，适合蔬菜、果树防治蓟马、粉虱。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000440', 'source-doc-4c784a84a66adf221597', 'source-node-000432', '7', '439', 'text', '烯啶虫胺（Nitenpyram）：卓越内吸和渗透作用，对水稻飞虱、蔬菜白粉虱特效，与有机磷类混配可增效，持效期约 14 天。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000441', 'source-doc-4c784a84a66adf221597', 'source-node-000432', '7', '440', 'text', '环氧虫啶（Cycloxaprid）：中国创制品种，对抗性褐飞虱、蚜虫活性优于吡虫啉，可茎叶处理或种子处理，对蜜蜂低风险。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000442', 'source-doc-4c784a84a66adf221597', 'source-node-000432', '7', '441', 'text', '哌虫啶（Paichongding）：中国创制品种，独特顺式构型，内吸传导性强，对刺吸式害虫速效性好，持效期长，尤其适合防治抗性蚜虫和蓟马。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000443', 'source-doc-4c784a84a66adf221597', 'source-node-000432', '7', '442', 'text', '氟啶虫胺腈（Sulfoxaflor）：作用于 nAChR 独特位点，对吡虫啉抗性害虫有效，兼具触杀、胃毒和渗透作用，2 小时内快速抑制取食，持效期 14 天以上。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000444', 'source-doc-4c784a84a66adf221597', 'source-node-000432', '7', '443', 'text', '氟吡呋喃酮（Flupyradifurone）：新型吡啶甲酰胺类，化学结构与传统新烟碱类不同，对蜜蜂相对安全，可快速控制蚜虫、粉虱，适合抗性治理和花期使用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000445', 'source-doc-4c784a84a66adf221597', 'source-node-000318', '5', '444', 'text', '苯甲酰脲类', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000446', 'source-doc-4c784a84a66adf221597', 'source-node-000445', '6', '445', 'text', '特点：特异性杀虫剂，低毒，干扰害虫蜕皮和繁殖，对环境友好。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000447', 'source-doc-4c784a84a66adf221597', 'source-node-000445', '6', '446', 'text', '代表药剂：灭幼脲、氟铃脲。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000448', 'source-doc-4c784a84a66adf221597', 'source-node-000447', '7', '447', 'text', '灭幼脲（Chlorbenzuron）：首个商业化苯甲酰脲类药剂，通过抑制几丁质合成阻止害虫蜕皮，对鳞翅目幼虫（如菜青虫、黏虫、松毛虫）特效，持效期长达 15-20 天，低毒且对天敌安全，适用于蔬菜、果树、林业等作物。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000449', 'source-doc-4c784a84a66adf221597', 'source-node-000447', '7', '448', 'text', '除虫脲（Diflubenzuron）：广谱几丁质合成抑制剂，主要防治鳞翅目害虫（如苹果卷叶蛾、棉铃虫、玉米螟），兼具一定杀卵作用，叶面喷雾后耐雨水冲刷，适合水稻、棉花、果树等多种作物。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000450', 'source-doc-4c784a84a66adf221597', 'source-node-000447', '7', '449', 'text', '氟铃脲（Hexaflumuron）：对夜蛾科害虫（如棉铃虫、斜纹夜蛾、烟青虫）活性极高，速效性优于同类其他品种，兼具触杀和胃毒作用，可用于棉花、蔬菜、果树，对蜜蜂和鸟类低毒。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000451', 'source-doc-4c784a84a66adf221597', 'source-node-000447', '7', '450', 'text', '氟虫脲（Flufenoxuron）：兼具杀虫和杀螨活性，对鳞翅目幼虫（如菜粉蝶）及叶螨（如红蜘蛛）均有效，持效期 20 天以上，适合蔬菜、果树、棉花，低温下仍能保持稳定活性。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000452', 'source-doc-4c784a84a66adf221597', 'source-node-000447', '7', '451', 'text', '虱螨脲（Lufenuron）：具有强杀卵活性，可通过卵壳或雌虫体壁进入卵内杀灭卵粒，同时防治低龄幼虫（如小菜蛾、甜菜夜蛾），适用于蔬菜、棉花、果树，对蜜蜂安全，适合花期使用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000453', 'source-doc-4c784a84a66adf221597', 'source-node-000447', '7', '452', 'text', '氟啶脲（Chlorfluazuron）：对鳞翅目害虫（如菜青虫、豆荚螟、茶尺蠖）特效，胃毒作用为主，施药后害虫因无法蜕皮而死亡，持效期 14-21 天，适合十字花科蔬菜、豆类、茶树。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000454', 'source-doc-4c784a84a66adf221597', 'source-node-000447', '7', '453', 'text', '杀铃脲（Triflumuron）：广谱性药剂，对棉铃虫、苹果蠹蛾、梨小食心虫等钻蛀性害虫防效突出，可渗透至果实表皮，阻止幼虫蛀果，适用于棉花、果树，对益虫影响小。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000455', 'source-doc-4c784a84a66adf221597', 'source-node-000447', '7', '454', 'text', '噻嗪酮（Buprofezin）：虽属噻二嗪类，但作用机制与苯甲酰脲类相似（抑制几丁质合成），主要防治刺吸式害虫（如水稻飞虱、叶蝉、白粉虱），成虫接触后产卵量下降，持效期 30 天左右，适用于水稻、蔬菜、棉花。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000456', 'source-doc-4c784a84a66adf221597', 'source-node-000447', '7', '455', 'text', '双苯氟脲（Bistrifluron）：新型苯甲酰脲类，对鳞翅目幼虫（如小菜蛾、菜青虫）活性高，且对部分抗性种群有效，胃毒作用显著，施药后 2-3 天害虫停止取食，适用于十字花科蔬菜、果树。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000457', 'source-doc-4c784a84a66adf221597', 'source-node-000318', '5', '456', 'text', '沙蚕毒素类', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000458', 'source-doc-4c784a84a66adf221597', 'source-node-000457', '6', '457', 'text', '特点：阻断神经递质，中等毒，广谱，触杀 / 胃毒 / 内吸兼具。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000459', 'source-doc-4c784a84a66adf221597', 'source-node-000457', '6', '458', 'text', '代表药剂：杀虫双、杀螟丹、杀虫单：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000460', 'source-doc-4c784a84a66adf221597', 'source-node-000459', '7', '459', 'text', '杀虫双（Bisultap）：沙蚕毒素类代表性品种，具触杀、胃毒、内吸及一定熏蒸作用，通过干扰害虫神经递质传导发挥作用；对水稻二化螟、三化螟、稻纵卷叶螟特效，也可防治蔬菜菜青虫、小菜蛾，适用于水稻、蔬菜、甘蔗等作物；剂型多为水剂，使用时需注意对家蚕高毒，避免靠近桑园。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000461', 'source-doc-4c784a84a66adf221597', 'source-node-000459', '7', '460', 'text', '杀虫单（Monosultap）：杀虫双的衍生物，水溶性优于杀虫双，以胃毒和内吸作用为主，触杀活性较弱；核心防治水稻螟虫（二化螟、三化螟）、稻飞虱，兼治玉米螟、菜青虫，适合水稻喷雾或毒土撒施；对鱼类中等毒性，使用时需避免污染稻田水域。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000462', 'source-doc-4c784a84a66adf221597', 'source-node-000459', '7', '461', 'text', '杀螟丹（Cartap）：广谱沙蚕毒素类药剂，触杀、胃毒、内吸作用均强，还能渗透至植物组织；除防治水稻螟虫、稻苞虫外，对蔬菜蚜虫、叶蝉、小菜蛾，果树桃小食心虫、梨小食心虫也有效，适用于水稻、蔬菜、果树、茶树；对蜜蜂低毒，但对家蚕、虾蟹高毒，禁止在桑园及稻田养虾区域使用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000463', 'source-doc-4c784a84a66adf221597', 'source-node-000459', '7', '462', 'text', '杀虫环（Thiocyclam）：内吸传导性突出，能通过根部或叶片吸收并输送至植株各部位，以胃毒作用为主；主要防治水稻稻纵卷叶螟、二化螟，兼治蔬菜蚜虫、蓟马及果树潜叶蛾，对蜜蜂相对安全，适合花期作物使用；剂型多为盐酸盐可溶性粉剂，使用时需注意避免与碱性农药混用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000464', 'source-doc-4c784a84a66adf221597', 'source-node-000459', '7', '463', 'text', '杀虫磺（Bensultap）：作用机制与同类一致，触杀和胃毒活性较强，内吸性较弱；对水稻螟虫、稻飞虱，甘蔗二点螟，蔬菜菜青虫防效优异，在甘蔗产区应用较广；国内登记应用相对较少，使用时需严格遵循标签，避免过量导致作物药害（尤其苗期作物）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000465', 'source-doc-4c784a84a66adf221597', 'source-node-000318', '5', '464', 'text', '杂环类', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000466', 'source-doc-4c784a84a66adf221597', 'source-node-000465', '6', '465', 'text', '特点：结构多样，作用机制各异，低毒，针对性强。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000467', 'source-doc-4c784a84a66adf221597', 'source-node-000465', '6', '466', 'text', '代表药剂：氟虫腈（部分场景限用）、茚虫威（鳞翅目特效）、螺虫乙酯（双向内吸）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000468', 'source-doc-4c784a84a66adf221597', 'source-node-000467', '7', '467', 'text', '吡蚜酮（Pymetrozine）：吡啶类杀虫剂，通过干扰害虫取食行为，导致其停止吸食植物汁液而死亡，对刺吸式害虫（如蚜虫、飞虱、叶蝉）特效，持效期长（20-30 天），内吸传导性强，适合水稻、小麦、蔬菜等作物，对蜜蜂和天敌安全，但对蚕高毒。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000469', 'source-doc-4c784a84a66adf221597', 'source-node-000467', '7', '468', 'text', '氟啶虫胺腈（Sulfoxaflor）：砜亚胺类杀虫剂，作用于烟碱乙酰胆碱受体，兼具触杀和胃毒作用，对蚜虫、粉虱、蓟马等多种刺吸式害虫高效，尤其对新烟碱类抗性种群有效，适用于棉花、蔬菜、果树，对蜜蜂低毒，但对水生生物有毒。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000470', 'source-doc-4c784a84a66adf221597', 'source-node-000467', '7', '469', 'text', '氯虫苯甲酰胺（Chlorantraniliprole）：邻甲酰氨基苯甲酰胺类，激活害虫鱼尼丁受体，导致肌肉过度收缩而死亡，对鳞翅目害虫（如棉铃虫、小菜蛾、玉米螟）特效，持效期长（15-20 天），内吸性强，可用于水稻、玉米、蔬菜、果树，对鸟类和鱼类低毒。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000471', 'source-doc-4c784a84a66adf221597', 'source-node-000467', '7', '470', 'text', '四唑虫酰胺（Tetraniliprole）：同属邻甲酰氨基苯甲酰胺类，作用机制相同，对鳞翅目和鞘翅目害虫（如甲虫）有效，尤其对水稻二化螟、稻纵卷叶螟防效优异，持效期长，适合水稻、玉米、蔬菜，对蜜蜂安全。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000472', 'source-doc-4c784a84a66adf221597', 'source-node-000467', '7', '471', 'text', '溴氰虫酰胺（Cyantraniliprole）：同属该类，作用于鱼尼丁受体，广谱高效，对鳞翅目、半翅目、鞘翅目害虫均有效，兼具胃毒和触杀作用，适用于多种作物，对蜜蜂低风险，但对水生生物有毒。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000473', 'source-doc-4c784a84a66adf221597', 'source-node-000467', '7', '472', 'text', '唑虫酰胺（Tolfenpyrad）：吡唑类杀虫剂，线粒体电子传递链抑制剂，通过干扰能量代谢导致害虫死亡，对鳞翅目、半翅目、螨类有效，尤其对蓟马、叶蝉、红蜘蛛防效突出，持效期 10-15 天，适合果树、蔬菜、茶叶，对蜜蜂低毒。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000474', 'source-doc-4c784a84a66adf221597', 'source-node-000467', '7', '473', 'text', '乙虫腈（Ethiprole）：吡唑类杀虫剂，作用于 GABA 受体，抑制神经传导，对鳞翅目、鞘翅目、双翅目害虫有效，尤其对蚂蚁、白蚁等社会性昆虫特效，可用于土壤处理防治地下害虫，对鱼类高毒，需避免污染水域。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000475', 'source-doc-4c784a84a66adf221597', 'source-node-000467', '7', '474', 'text', '茚虫威（Indoxacarb）：恶二嗪类杀虫剂，钠离子通道抑制剂，通过阻断神经信号传导导致害虫麻痹死亡，对鳞翅目害虫（如小菜蛾、棉铃虫）高效，兼具触杀和胃毒作用，持效期 7-10 天，适合蔬菜、果树、棉花，对蜜蜂低毒。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000476', 'source-doc-4c784a84a66adf221597', 'source-node-000467', '7', '475', 'text', '氰氟虫腙（Metaflumizone）：缩氨基脲类杀虫剂，作用于钠离子通道，导致害虫过度兴奋而死亡，对鳞翅目害虫（如甜菜夜蛾、斜纹夜蛾）特效，与茚虫威有协同作用，适合蔬菜、果树，对蜜蜂和天敌安全。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000477', 'source-doc-4c784a84a66adf221597', 'source-node-000467', '7', '476', 'text', '氟虫双酰胺（Flubendiamide）：邻甲酰氨基苯甲酰胺类，激活鱼尼丁受体，对鳞翅目害虫（如稻纵卷叶螟、二化螟）高效，持效期长（14-21 天），内吸性强，可用于水稻、玉米、蔬菜，对鸟类和鱼类低毒。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000478', 'source-doc-4c784a84a66adf221597', 'source-node-000467', '7', '477', 'text', '环虫酰肼（Chromafenozide）：双酰肼类昆虫生长调节剂，模拟蜕皮激素，诱导害虫提前蜕皮而死亡，对鳞翅目幼虫（如苹果蠹蛾、菜青虫）有效，持效期 10-15 天，适合果树、蔬菜，对天敌安全。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000479', 'source-doc-4c784a84a66adf221597', 'source-node-000467', '7', '478', 'text', '甲氧虫酰肼（Methoxyfenozide）：同属双酰肼类，作用机制相同，对鳞翅目害虫（如棉铃虫、甜菜夜蛾）特效，持效期长，适合棉花、蔬菜、果树，对益虫和环境友好。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000480', 'source-doc-4c784a84a66adf221597', 'source-node-000467', '7', '479', 'text', '三氟苯嘧啶（Triflumezopyrim）：嘧啶类杀虫剂，作用于乙酰胆碱受体，抑制神经传导，对飞虱、叶蝉等刺吸式害虫高效，内吸传导性强，持效期 20 天以上，适合水稻、小麦，对蜜蜂和天敌安全。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000481', 'source-doc-4c784a84a66adf221597', 'source-node-000467', '7', '480', 'text', '氟啶虫酰胺（Flonicamid）：吡啶酰胺类杀虫剂，通过抑制害虫取食行为，导致其饥饿死亡，对蚜虫、粉虱、蓟马等刺吸式害虫有效，持效期 10-15 天，适合蔬菜、果树、茶叶，对蜜蜂低毒。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000482', 'source-doc-4c784a84a66adf221597', 'source-node-000467', '7', '481', 'text', '乙螨唑（Etoxazole）：恶唑啉类杀螨剂，抑制螨类几丁质合成，对卵和幼螨高效，持效期长达 40-50 天，适合果树、蔬菜、棉花，对成螨无效，需与其他杀螨剂混用，对鱼类低毒。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000483', 'source-doc-4c784a84a66adf221597', 'source-node-000467', '7', '482', 'text', '吡丙醚（Pyriproxyfen）：吡啶类昆虫生长调节剂，抑制害虫蜕皮和繁殖，对卵和幼虫有效，尤其对粉虱、介壳虫、蚊子幼虫特效，持效期长，适合蔬菜、果树、卫生害虫防治，对蜜蜂和天敌安全。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000484', 'source-doc-4c784a84a66adf221597', 'source-node-000467', '7', '483', 'text', '氟吡呋喃酮（Flupyradifurone）：吡啶类杀虫剂，作用于烟碱乙酰胆碱受体，对蚜虫、粉虱、蓟马等刺吸式害虫高效，兼具触杀和内吸作用，适合蔬菜、果树，对蜜蜂低毒，但对水生生物有毒。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000485', 'source-doc-4c784a84a66adf221597', 'source-node-000467', '7', '484', 'text', '丁氟螨酯（Cyflumetofen）：吡唑类杀螨剂，线粒体电子传递抑制剂，对红蜘蛛、锈壁虱等螨类高效，持效期 15-20 天，适合果树、蔬菜，对蜜蜂和天敌安全。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000486', 'source-doc-4c784a84a66adf221597', 'source-node-000467', '7', '485', 'text', '噻嗪酮（Buprofezin）：噻二嗪类杀虫剂，抑制几丁质合成，导致害虫蜕皮失败而死亡，对飞虱、叶蝉、介壳虫特效，持效期 30 天以上，适合水稻、蔬菜、果树，对甲壳类水生生物高毒，禁止在稻田养鱼区域使用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000487', 'source-doc-4c784a84a66adf221597', 'source-node-000467', '7', '486', 'text', '虫螨腈（Chlorfenapyr）：吡咯类杀虫剂，作用于线粒体电子传递链，兼具触杀和胃毒作用，对鳞翅目、半翅目、缨翅目害虫及螨类有效，持效期 10-15 天，适合蔬菜、果树、棉花，对蜜蜂低毒，但对鱼类高毒。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000488', 'source-doc-4c784a84a66adf221597', 'source-node-000318', '5', '487', 'text', '其他化学类别', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000489', 'source-doc-4c784a84a66adf221597', 'source-node-000488', '6', '488', 'text', '如甲脒类（双甲脒，杀螨兼杀虫）、有机氯类（如六六六、DDT，因高残留已禁用）等。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000490', 'source-doc-4c784a84a66adf221597', 'source-node-000205', '4', '489', 'text', '来源分类', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000491', 'source-doc-4c784a84a66adf221597', 'source-node-000490', '5', '490', 'text', '化学合成杀虫剂', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000492', 'source-doc-4c784a84a66adf221597', 'source-node-000491', '6', '491', 'text', '上述有机磷、拟除虫菊酯等均属于此类，由人工化学合成，是目前应用最广泛的类型。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000493', 'source-doc-4c784a84a66adf221597', 'source-node-000490', '5', '492', 'text', '生物源杀虫剂', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000494', 'source-doc-4c784a84a66adf221597', 'source-node-000493', '6', '493', 'text', '来源于天然生物（植物、微生物、动物），安全性高，对环境友好。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000495', 'source-doc-4c784a84a66adf221597', 'source-node-000493', '6', '494', 'text', '细分类型：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000496', 'source-doc-4c784a84a66adf221597', 'source-node-000495', '7', '495', 'text', '植物源：如除虫菊素（从除虫菊中提取）、印楝素（印楝树提取物）；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000497', 'source-doc-4c784a84a66adf221597', 'source-node-000495', '7', '496', 'text', '微生物源：如苏云金杆菌（Bt，产生毒蛋白杀鳞翅目幼虫）、白僵菌（真菌寄生害虫）；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000498', 'source-doc-4c784a84a66adf221597', 'source-node-000495', '7', '497', 'text', '动物源：如昆虫病毒（核型多角体病毒，NPV）、捕食性天敌（如赤眼蜂，非药剂但属生物防治范畴）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000499', 'source-doc-4c784a84a66adf221597', 'source-node-000043', '2', '498', 'text', '铲除性', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000500', 'source-doc-4c784a84a66adf221597', 'source-node-000043', '2', '499', 'text', '植物生长调节剂', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000501', 'source-doc-4c784a84a66adf221597', 'source-node-000500', '3', '500', 'text', '植物生长调节剂类型', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000502', 'source-doc-4c784a84a66adf221597', 'source-node-000500', '3', '501', 'text', '控旺药的复配性', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000503', 'source-doc-4c784a84a66adf221597', 'source-node-000502', '4', '502', 'text', '一、控旺药的核心类型，决定复配基础', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000504', 'source-doc-4c784a84a66adf221597', 'source-node-000503', '5', '503', 'text', '控旺剂类型代表产品作用机理复配兼容性特点三唑类（抑制赤霉素）多效唑、烯效唑抑制植物体内赤霉素合成，延缓细胞伸长复配时易因 “抑制作用叠加” 导致药害，需严格控制浓度季铵盐类（延缓生长）甲哌鎓（缩节胺）抑制细胞伸长，不抑制细胞分裂安全性高，复配范围较广，不易过度控旺环己烷羧酸类调环酸钙抑制赤霉素合成，促进茎秆粗壮安全性优于三唑类，可与多数常规药剂复配其他（天然提取物）矮壮素（氯化胆碱）促进叶绿素合成，抑制徒长温和型控旺，复配兼容性较好', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000505', 'source-doc-4c784a84a66adf221597', 'source-node-000502', '4', '504', 'text', '二、控旺药常见复配场景：能配什么？需注意什么？', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000506', 'source-doc-4c784a84a66adf221597', 'source-node-000505', '5', '505', 'text', '1. 控旺药 + 叶面肥：最安全的复配组合，优先推荐', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000507', 'source-doc-4c784a84a66adf221597', 'source-node-000506', '6', '506', 'text', '推荐复配组合：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000508', 'source-doc-4c784a84a66adf221597', 'source-node-000507', '7', '507', 'text', '甲哌鎓 / 调环酸钙 + 磷酸二氢钾（补充磷钾，增强抗逆性，辅助控旺）；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000509', 'source-doc-4c784a84a66adf221597', 'source-node-000507', '7', '508', 'text', '多效唑（低浓度）+ 硼肥 / 锌肥（果树 / 蔬菜花期，控旺同时促进坐果）；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000510', 'source-doc-4c784a84a66adf221597', 'source-node-000507', '7', '509', 'text', '矮壮素 + 氨基酸叶面肥（小麦 / 玉米苗期，控旺 + 促根系）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000511', 'source-doc-4c784a84a66adf221597', 'source-node-000506', '6', '510', 'text', '注意：避免与 “高氮叶面肥” 复配（高氮会刺激徒长，抵消控旺效果）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000512', 'source-doc-4c784a84a66adf221597', 'source-node-000505', '5', '511', 'text', '2. 控旺药 + 杀菌剂 / 杀虫剂：需 “先看机理，再试小范围”', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000513', 'source-doc-4c784a84a66adf221597', 'source-node-000512', '6', '512', 'text', '相对安全的复配情况：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000514', 'source-doc-4c784a84a66adf221597', 'source-node-000513', '7', '513', 'text', '甲哌鎓 / 调环酸钙 + 常规保护性杀菌剂（如代森锰锌、百菌清）：这类杀菌剂作用温和，不抑制作物代谢，适合复配（如棉花蕾期，控旺 + 防炭疽病）；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000515', 'source-doc-4c784a84a66adf221597', 'source-node-000513', '7', '514', 'text', '矮壮素 + 低毒杀虫剂（如吡虫啉、噻虫嗪）：针对蚜虫、飞虱等刺吸式害虫，二者无明显冲突（如小麦蚜虫 + 旺长同期发生时）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000516', 'source-doc-4c784a84a66adf221597', 'source-node-000512', '6', '515', 'text', '严格禁止 / 谨慎的复配情况：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000517', 'source-doc-4c784a84a66adf221597', 'source-node-000516', '7', '516', 'text', '三唑类控旺药（多效唑、烯效唑）+ 三唑类杀菌剂（如苯醚甲环唑、戊唑醇）：二者均抑制真菌 / 植物的 “细胞色素 P450 酶系”，复配会显著增强抑制作用，导致作物叶片发黄、生长停滞（典型药害：小麦叶尖干枯、果树新梢不抽生）；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000518', 'source-doc-4c784a84a66adf221597', 'source-node-000516', '7', '517', 'text', '控旺药 + 有机磷类杀虫剂（如毒死蜱、辛硫磷）：有机磷农药易对作物产生轻微胁迫，与控旺药复配可能加重叶片卷曲、脱落（尤其蔬菜幼苗期）；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000519', 'source-doc-4c784a84a66adf221597', 'source-node-000516', '7', '518', 'text', '任何控旺药 + 强内吸性杀菌剂（如氟环唑）：内吸性药剂会增强控旺药在作物体内的传导，可能导致 “控旺过度”。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000520', 'source-doc-4c784a84a66adf221597', 'source-node-000505', '5', '519', 'text', '3. 控旺药 + 其他调节剂：风险最高，需专业指导', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000521', 'source-doc-4c784a84a66adf221597', 'source-node-000520', '6', '520', 'text', '可复配（协同）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000522', 'source-doc-4c784a84a66adf221597', 'source-node-000521', '7', '521', 'text', '控旺药 + 芸苔素内酯（低浓度）—— 芸苔素可缓解控旺药的抑制作用，避免控旺过度，同时增强作物抗逆性（如多效唑 + 芸苔素，用于果树控旺，减少叶片黄化）；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000523', 'source-doc-4c784a84a66adf221597', 'source-node-000520', '6', '522', 'text', '禁复配（拮抗 / 药害）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000524', 'source-doc-4c784a84a66adf221597', 'source-node-000523', '7', '523', 'text', '控旺药 + 赤霉素（920）：赤霉素促进生长，与控旺药作用完全相反，会直接抵消控旺效果；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000525', 'source-doc-4c784a84a66adf221597', 'source-node-000523', '7', '524', 'text', '控旺药 + 2,4-D（生长素类）：2,4-D 易导致作物畸形，与控旺药复配会加重叶片皱缩、果实畸形（尤其番茄、黄瓜等蔬菜）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000526', 'source-doc-4c784a84a66adf221597', 'source-node-000502', '4', '525', 'text', '三、控旺药复配的 3 个核心原则（避免药害的关键）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000527', 'source-doc-4c784a84a66adf221597', 'source-node-000526', '5', '526', 'text', '“机理不冲突” 是前提：优先选择 “作用靶点无叠加、无拮抗” 的组合：比如 “抑制生长” 的控旺药，不与 “同样抑制细胞代谢” 的药剂（如部分三唑类杀菌剂）复配；“温和型控旺药”（甲哌鎓）比 “强抑制型”（多效唑）更适合复配。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000528', 'source-doc-4c784a84a66adf221597', 'source-node-000526', '5', '527', 'text', '“先小范围试验” 是底线：无论何种组合，复配前必须在同一地块、同一作物的小面积区域（如 10-20 平方米）试用，观察 2-3 天：若叶片无发黄、卷曲，生长状态正常，再扩大面积使用；若出现药害，立即停止并调整配比或更换药剂。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000529', 'source-doc-4c784a84a66adf221597', 'source-node-000526', '5', '528', 'text', '“浓度不叠加” 是关键：复配时，控旺药和复配对象的浓度需单独按推荐剂量稀释，不可因 “复配” 而随意增加某一种药剂的用量（如多效唑推荐 1500 倍，复配时仍用 1500 倍，而非 1000 倍），避免 “浓度叠加” 导致药害。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000530', 'source-doc-4c784a84a66adf221597', 'source-node-000502', '4', '529', 'text', '四、总结：控旺药复配的 “能与不能”', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000531', 'source-doc-4c784a84a66adf221597', 'source-node-000530', '5', '530', 'text', '能做：优先与 “温和型叶面肥”（磷钾、中微量元素）复配，选择 “安全型控旺药”（甲哌鎓、调环酸钙）与常规杀菌剂 / 杀虫剂复配，且必须先小试；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000532', 'source-doc-4c784a84a66adf221597', 'source-node-000530', '5', '531', 'text', '不能做：禁止 “强抑制型控旺药”（多效唑、烯效唑）与 “同机理杀菌剂”（三唑类）、“生长素类调节剂”（2,4-D）复配，避免与 “高氮肥料” 复配；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000533', 'source-doc-4c784a84a66adf221597', 'source-node-000530', '5', '532', 'text', '核心参考：永远以产品说明书为首要依据（多数控旺药说明书会明确标注 “可复配类型” 和 “禁忌”），若说明书未提及，需咨询农技人员或进行小范围验证。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000534', 'source-doc-4c784a84a66adf221597', 'source-node-000001', '1', '533', 'text', '农药禁用清单', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000535', 'source-doc-4c784a84a66adf221597', 'source-node-000534', '2', '534', 'text', '一、国家明令禁止使用的农药（56 种）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000536', 'source-doc-4c784a84a66adf221597', 'source-node-000535', '3', '535', 'text', '药品名称：六六六、滴滴涕、毒杀芬、二溴氯丙烷、杀虫脒、二溴乙烷、除草醚、艾氏剂、狄氏剂、汞制剂、砷类、铅类、敌枯双、氟乙酰胺、甘氟、毒鼠强、氟乙酸钠、毒鼠硅、甲胺磷、对硫磷、甲基对硫磷、久效磷、磷胺、苯线磷、地虫硫磷、甲基硫环磷、磷化钙、磷化镁、磷化锌、硫线磷、蝇毒磷、治螟磷、特丁硫磷、氯磺隆、胺苯磺隆、甲磺隆、福美胂、福美甲胂、三氯杀螨醇、林丹、硫丹、氟虫胺、杀扑磷、百草枯、灭蚁灵、氯丹、2，4 - 滴丁酯、甲拌磷 、甲基异柳磷 、水胺硫磷 、灭线磷 、氧乐果 、克百威 、灭多威 、涕灭威 、溴甲烷 *', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000537', 'source-doc-4c784a84a66adf221597', 'source-node-000534', '2', '536', 'text', '二、在蔬菜、果树、茶叶、中草药材上不得使用的农药（12 种）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000538', 'source-doc-4c784a84a66adf221597', 'source-node-000537', '3', '537', 'text', '药品名称：内吸磷、硫环磷、蝇毒磷、乙拌甲胺磷、丁硫克百威、乐果、毒死蜱、三唑磷、丁酰肼（比久）、氟戊菊酯、氟虫腈、氟苯虫酰胺', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000539', 'source-doc-4c784a84a66adf221597', 'source-node-000534', '2', '538', 'text', '三、限制使用的农药（9 种）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000540', 'source-doc-4c784a84a66adf221597', 'source-node-000539', '3', '539', 'text', '药品名称：磷化铝、氯化苦、氟鼠灵、敌鼠钠盐、杀鼠灵、杀鼠醚、溴敌隆、溴鼠灵、乙酰甲胺磷', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000541', 'source-doc-4c784a84a66adf221597', 'source-node-000534', '2', '540', 'text', '四、注释', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000542', 'source-doc-4c784a84a66adf221597', 'source-node-000541', '3', '541', 'text', '甲拌磷、甲基异柳磷、水胺硫磷、灭线磷过渡期至 2024 年 9 月 1 日，氧乐果、克百威、灭多威、涕灭威过渡期至 2026 年 6 月 1 日，过渡期内禁止在蔬菜、瓜果、茶叶、菌类、中草药材上使用，禁止用于防治卫生害虫，禁止用于水生植物的病虫害防治。甲拌磷、甲基异柳磷、克百威过渡期内禁止在甘蔗上使用。过渡期后禁止销售和使用上述 8 种农药。溴甲烷仅可用于 “检疫熏蒸处理”。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000543', 'source-doc-4c784a84a66adf221597', 'source-node-000542', '4', '542', 'text', '任何农药产品都不得超出农药登记批准的使用范围使用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000544', 'source-doc-4c784a84a66adf221597', 'source-node-000542', '4', '543', 'text', '杀虫剂作用方式分为触杀（直接接触虫体致死）、胃毒（昆虫取食后致死）、熏蒸（气味杀虫）和内吸（植物吸收后昆虫取食植物致死），可根据需要选择与禁用农药作用方式相同的其他药品进行药物防治。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000545', 'source-doc-4c784a84a66adf221597', NULL, '0', '544', 'text', '2.1 果树', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000546', 'source-doc-4c784a84a66adf221597', 'source-node-000545', '1', '545', 'text', '2.1.1 柑橘橙柚', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000547', 'source-doc-4c784a84a66adf221597', 'source-node-000546', '2', '546', 'text', '细菌性病害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000548', 'source-doc-4c784a84a66adf221597', 'source-node-000547', '3', '547', 'text', '溃疡病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000549', 'source-doc-4c784a84a66adf221597', 'source-node-000548', '4', '548', 'text', '发病规律：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000550', 'source-doc-4c784a84a66adf221597', 'source-node-000549', '5', '549', 'text', '柑橘溃疡病（病原菌：Xanthomonas citri subsp. citri）是柑橘产业中最具毁灭性的细菌病害，被列为国内外植物检疫对象。该病可危害叶片、枝梢和果实，导致落叶、枯梢和落果，严重时可使果实商品价值降低30%-50%，甚至完全失去商品价值，通过气孔、皮孔或机械伤口侵入，尤其在高温多雨（25-30℃）季节高发。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000551', 'source-doc-4c784a84a66adf221597', 'source-node-000549', '5', '550', 'text', '传播途径：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000552', 'source-doc-4c784a84a66adf221597', 'source-node-000551', '6', '551', 'text', '风雨传播：雨水飞溅是主要传播方式，病菌可随气流扩散至 500 米外。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000553', 'source-doc-4c784a84a66adf221597', 'source-node-000551', '6', '552', 'text', '农事操作：修剪工具、采果人员接触带菌组织后传播。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000554', 'source-doc-4c784a84a66adf221597', 'source-node-000549', '5', '553', 'text', '症状表现：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000555', 'source-doc-4c784a84a66adf221597', 'source-node-000554', '6', '554', 'text', '叶片：初期水渍状小点，后扩大为火山口状病斑，边缘油渍状，周围有黄色晕圈。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000556', 'source-doc-4c784a84a66adf221597', 'source-node-000554', '6', '555', 'text', '果实：病斑木栓化隆起，严重时导致落果或品质下降。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000557', 'source-doc-4c784a84a66adf221597', 'source-node-000548', '4', '556', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000558', 'source-doc-4c784a84a66adf221597', 'source-node-000557', '5', '557', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000559', 'source-doc-4c784a84a66adf221597', 'source-node-000548', '4', '558', 'text', '预防方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000560', 'source-doc-4c784a84a66adf221597', 'source-node-000559', '5', '559', 'text', '农业措施：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000561', 'source-doc-4c784a84a66adf221597', 'source-node-000560', '6', '560', 'text', '修剪清园：冬季剪除病枝、病叶，集中烧毁；生长期及时摘除发病组织，减少菌源。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000562', 'source-doc-4c784a84a66adf221597', 'source-node-000560', '6', '561', 'text', '优化栽培：增施钙肥（如硝酸钙 20kg / 亩）和有机肥，增强叶片抗病力；合理密植（柚类建议 4×5m 株行距），改善通风透光条件。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000563', 'source-doc-4c784a84a66adf221597', 'source-node-000560', '6', '562', 'text', '关键用药时期：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000564', 'source-doc-4c784a84a66adf221597', 'source-node-000563', '7', '563', 'text', '春梢萌动期（萌芽前7天）：喷施77%氢氧化铜500倍液，杀灭越冬病菌', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000565', 'source-doc-4c784a84a66adf221597', 'source-node-000563', '7', '564', 'text', '新梢生长期（梢长1-3cm）：20%噻菌铜500倍+4%春雷霉素1000倍，7天1次，连用2次', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000566', 'source-doc-4c784a84a66adf221597', 'source-node-000563', '7', '565', 'text', '幼果期（谢花后20天）：47%春雷王铜800倍，隔15天喷施，连用3次', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000567', 'source-doc-4c784a84a66adf221597', 'source-node-000563', '7', '566', 'text', '台风暴雨后：立即喷施内吸性药剂（如春雷霉素或乙蒜素），阻断潜伏感染', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000568', 'source-doc-4c784a84a66adf221597', 'source-node-000563', '7', '567', 'text', '采后清园：喷施石硫合剂1波美度+10%吡丙醚2000倍，减少越冬菌源', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000569', 'source-doc-4c784a84a66adf221597', 'source-node-000559', '5', '568', 'text', '物理屏障：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000570', 'source-doc-4c784a84a66adf221597', 'source-node-000569', '6', '569', 'text', '台风或暴雨前，全园覆盖防虫网（孔径 0.6mm），减少病菌飞溅传播。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000571', 'source-doc-4c784a84a66adf221597', 'source-node-000548', '4', '570', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000572', 'source-doc-4c784a84a66adf221597', 'source-node-000571', '5', '571', 'text', '化学防治（按效果排序）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000573', 'source-doc-4c784a84a66adf221597', 'source-node-000572', '6', '572', 'text', '无机铜制剂（高频次使用）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000574', 'source-doc-4c784a84a66adf221597', 'source-node-000573', '7', '573', 'text', '氢氧化铜（77% 可湿性粉剂）：500-800 倍液，新梢展叶期、幼果期喷施，持效期 7-15 天，耐雨水冲刷。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000575', 'source-doc-4c784a84a66adf221597', 'source-node-000573', '7', '574', 'text', '波尔多液（1:1:100）：春梢萌发后、谢花 2/3 时使用，杀菌谱广，但需现配现用，避免花期敏感阶段。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000576', 'source-doc-4c784a84a66adf221597', 'source-node-000572', '6', '575', 'text', '有机铜制剂（安全性优先）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000577', 'source-doc-4c784a84a66adf221597', 'source-node-000576', '7', '576', 'text', '噻菌铜（20% 悬浮剂）：500-600 倍液，内吸性强，谢花后 10-15 天首次喷施，适合幼果期。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000578', 'source-doc-4c784a84a66adf221597', 'source-node-000576', '7', '577', 'text', '喹啉铜（33.5% 悬浮剂）：1500 倍液，中性 pH 值，可与多数药剂混用，秋梢抽发期推荐。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000579', 'source-doc-4c784a84a66adf221597', 'source-node-000572', '6', '578', 'text', '抗生素类（治疗性突出）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000580', 'source-doc-4c784a84a66adf221597', 'source-node-000579', '7', '579', 'text', '春雷霉素（2% 水剂）：600-800 倍液，发病初期与铜制剂复配（如春雷・王铜），可增效。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000581', 'source-doc-4c784a84a66adf221597', 'source-node-000579', '7', '580', 'text', '中生菌素（3% 可湿性粉剂）：800-1000 倍液，广谱抗菌，与氢氧化铜混用可延缓抗药性。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000582', 'source-doc-4c784a84a66adf221597', 'source-node-000572', '6', '581', 'text', '新型合成杀菌剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000583', 'source-doc-4c784a84a66adf221597', 'source-node-000582', '7', '582', 'text', '噻唑锌（20% 悬浮剂）：800 倍液，锌离子 + 噻唑基团双重作用，对维管束病害特效，可促根。、', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000584', 'source-doc-4c784a84a66adf221597', 'source-node-000572', '6', '583', 'text', '创新方案：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000585', 'source-doc-4c784a84a66adf221597', 'source-node-000584', '7', '584', 'text', '铜+抗生素：46%氢氧化铜1000倍+4%春雷霉素1000倍，增效30%以上。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000586', 'source-doc-4c784a84a66adf221597', 'source-node-000584', '7', '585', 'text', '铜+锌制剂：喹啉铜+代森锌，提高保护持效期。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000587', 'source-doc-4c784a84a66adf221597', 'source-node-000584', '7', '586', 'text', '生物复配：地衣芽孢杆菌1000倍+海藻素，增强树体免疫力。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000588', 'source-doc-4c784a84a66adf221597', 'source-node-000571', '5', '587', 'text', '药剂轮换：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000589', 'source-doc-4c784a84a66adf221597', 'source-node-000588', '6', '588', 'text', '无机铜（氢氧化铜）→有机铜（喹啉铜）→抗生素（春雷霉素）→生物制剂（枯草芽孢杆菌），每季度轮换 2-3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000590', 'source-doc-4c784a84a66adf221597', 'source-node-000588', '6', '589', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000591', 'source-doc-4c784a84a66adf221597', 'source-node-000588', '6', '590', 'text', '药剂类型代表药剂使用浓度特点有效频次有机铜制剂20%噻菌铜(龙克菌)300-500倍内吸性强，安全性高98%抗生素类4%春雷霉素1000倍内吸治疗效果好92%复合铜制剂47%春雷·王铜500倍保护治疗双效90%无机铜制剂77%氢氧化铜500倍保护性强，易引发螨害85%中草药制剂靓果安200-300倍修复伤口，复壮树势78%生物制剂地衣芽孢杆菌1000倍生态安全，持效期长70%', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000592', 'source-doc-4c784a84a66adf221597', 'source-node-000571', '5', '591', 'text', '地域化防治方案：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000593', 'source-doc-4c784a84a66adf221597', 'source-node-000592', '6', '592', 'text', '华南产区（广东、广西）：春梢期（氢氧化铜 500 倍液）+ 幼果期（噻菌铜 600 倍液）+ 秋梢期（喹啉铜 1500 倍液），台风后补喷春雷霉素 800 倍液 + 矿物油 200 倍液。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000594', 'source-doc-4c784a84a66adf221597', 'source-node-000571', '5', '593', 'text', '生物防治：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000595', 'source-doc-4c784a84a66adf221597', 'source-node-000594', '6', '594', 'text', '枯草芽孢杆菌（1000 亿 CFU/g）：稀释 1500 倍液喷雾，通过竞争营养抑制病菌繁殖，与低浓度铜制剂混用增效。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000596', 'source-doc-4c784a84a66adf221597', 'source-node-000594', '6', '595', 'text', '噬菌体 CCTCC NO: M 2023392：精准裂解溃疡病菌，田间防效达 70% 以上，可替代 50% 化学药剂。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000597', 'source-doc-4c784a84a66adf221597', 'source-node-000571', '5', '596', 'text', '新兴技术：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000598', 'source-doc-4c784a84a66adf221597', 'source-node-000597', '6', '597', 'text', '锰基纳米酶（MONPs）：叶面喷施后清除活性氧，病树生理指标改善率达 40%，与春雷霉素复配防效提升 50%。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000599', 'source-doc-4c784a84a66adf221597', 'source-node-000547', '3', '598', 'text', '柑橘黄龙病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000600', 'source-doc-4c784a84a66adf221597', 'source-node-000599', '4', '599', 'text', '发病规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000601', 'source-doc-4c784a84a66adf221597', 'source-node-000600', '5', '600', 'text', '病原菌：亚洲韧皮杆菌（Candidatus Liberibacter asiaticus），通过柑橘木虱传播，在树体内系统性侵染，导致叶片黄化、果实畸形。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000602', 'source-doc-4c784a84a66adf221597', 'source-node-000600', '5', '601', 'text', '传播途径：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000603', 'source-doc-4c784a84a66adf221597', 'source-node-000602', '6', '602', 'text', '木虱传播：成虫取食病树后终身带毒，迁飞距离可达 2 公里。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000604', 'source-doc-4c784a84a66adf221597', 'source-node-000602', '6', '603', 'text', '嫁接传播：使用带毒接穗或苗木是主要人为传播途径。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000605', 'source-doc-4c784a84a66adf221597', 'source-node-000600', '5', '604', 'text', '症状表现：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000606', 'source-doc-4c784a84a66adf221597', 'source-node-000605', '6', '605', 'text', '叶片：斑驳状黄化，叶脉肿大，叶片变硬变脆。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000607', 'source-doc-4c784a84a66adf221597', 'source-node-000605', '6', '606', 'text', '果实：果小畸形，着色不均，味酸无商品价值。开花早、花量大、坐果少，果小，着色差；出现“红鼻子”果；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000608', 'source-doc-4c784a84a66adf221597', 'source-node-000605', '6', '607', 'text', '树冠：发病初期树冠中出现一条或数条枝梢叶色褪绿和叶脉黄化；后期根部腐烂全株死亡', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000609', 'source-doc-4c784a84a66adf221597', 'source-node-000599', '4', '608', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000610', 'source-doc-4c784a84a66adf221597', 'source-node-000609', '5', '609', 'text', '有木虱，叶片脆，不对称的黄化，某些枝条黄化，红鼻子果', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000611', 'source-doc-4c784a84a66adf221597', 'source-node-000599', '4', '610', 'text', '预防方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000612', 'source-doc-4c784a84a66adf221597', 'source-node-000611', '5', '611', 'text', '木虱管控：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000613', 'source-doc-4c784a84a66adf221597', 'source-node-000612', '6', '612', 'text', '统一防控：以村为单位，在春梢萌芽前、新梢期、晚秋梢期统一施药，切断传播链。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000614', 'source-doc-4c784a84a66adf221597', 'source-node-000612', '6', '613', 'text', '物理隔离：新建果园周边种植 50 米宽的防护林（如桉树），降低木虱迁飞风险。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000615', 'source-doc-4c784a84a66adf221597', 'source-node-000612', '6', '614', 'text', '黄板监控：张贴黄板监控木虱', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000616', 'source-doc-4c784a84a66adf221597', 'source-node-000611', '5', '615', 'text', '苗木检疫：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000617', 'source-doc-4c784a84a66adf221597', 'source-node-000616', '6', '616', 'text', '种植经检疫的网棚假植大苗（1.5-2 年生），严禁使用带病苗木。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000618', 'source-doc-4c784a84a66adf221597', 'source-node-000599', '4', '617', 'text', '防治方法（实际只是控制不是治疗，无药可救）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000619', 'source-doc-4c784a84a66adf221597', 'source-node-000618', '5', '618', 'text', '核心防治药剂（木虱管控）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000620', 'source-doc-4c784a84a66adf221597', 'source-node-000619', '6', '619', 'text', '内吸性杀虫剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000621', 'source-doc-4c784a84a66adf221597', 'source-node-000620', '7', '620', 'text', '噻虫嗪（25% 水分散粒剂）：5000 倍液，新梢萌芽期（芽长 2-5mm）喷施，持效期 15-20 天。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000622', 'source-doc-4c784a84a66adf221597', 'source-node-000620', '7', '621', 'text', '螺虫乙酯（24% 悬浮剂）：3000 倍液，杀卵兼杀成虫，与触杀剂（如联苯菊酯）复配效果更佳。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000623', 'source-doc-4c784a84a66adf221597', 'source-node-000619', '6', '622', 'text', '触杀性药剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000624', 'source-doc-4c784a84a66adf221597', 'source-node-000623', '7', '623', 'text', '联苯菊酯（10% 乳油）：1500 倍液，冬季清园配合矿物油（200 倍液）杀灭越冬成虫。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000625', 'source-doc-4c784a84a66adf221597', 'source-node-000623', '7', '624', 'text', '高效氯氰菊酯（4.5% 乳油）：1000 倍液，与吡丙醚（10% 乳油）复配，抑制木虱卵孵化。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000626', 'source-doc-4c784a84a66adf221597', 'source-node-000623', '7', '625', 'text', '吡虫啉（70%）：3000-4000倍', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000627', 'source-doc-4c784a84a66adf221597', 'source-node-000619', '6', '626', 'text', '换药防治：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000628', 'source-doc-4c784a84a66adf221597', 'source-node-000627', '7', '627', 'text', '噻虫嗪（新烟碱类）→螺虫乙酯（季酮酸类）→呋虫胺（第三代烟碱类）→联苯菊酯（拟除虫菊酯类），避免连续使用同一作用机理药剂。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000629', 'source-doc-4c784a84a66adf221597', 'source-node-000619', '6', '628', 'text', '区域化方案：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000630', 'source-doc-4c784a84a66adf221597', 'source-node-000629', '7', '629', 'text', '华南产区（广东、广西）：统一防控木虱（噻虫嗪 + 螺虫乙酯），病树挖除后树桩用草甘膦 + 黑膜覆盖。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000631', 'source-doc-4c784a84a66adf221597', 'source-node-000618', '5', '630', 'text', '辅助杀菌与营养调控：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000632', 'source-doc-4c784a84a66adf221597', 'source-node-000631', '6', '631', 'text', '抗生素类（短期抑制）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000633', 'source-doc-4c784a84a66adf221597', 'source-node-000632', '7', '632', 'text', '春雷霉素（2% 水剂）：600 倍液，结合叶面肥（如氨基酸）喷施，延缓病情发展。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000634', 'source-doc-4c784a84a66adf221597', 'source-node-000631', '6', '633', 'text', '生物刺激剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000635', 'source-doc-4c784a84a66adf221597', 'source-node-000634', '7', '634', 'text', '纳米材料橘叶青：30-36 倍液，喷施后叶片含菌量降低 35 倍，田间试验防效显著。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000636', 'source-doc-4c784a84a66adf221597', 'source-node-000618', '5', '635', 'text', '新型技术：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000637', 'source-doc-4c784a84a66adf221597', 'source-node-000636', '6', '636', 'text', '治疗小肽 APP3-14：靶向稳定 MYC2 蛋白，田间试验单季防控效率达 80%，阻断病菌定殖。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000638', 'source-doc-4c784a84a66adf221597', 'source-node-000636', '6', '637', 'text', '耘眼 App：搭载 AI 识别系统，拍照即可精准诊断黄龙病，准确率 95%，指导及时防控。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000639', 'source-doc-4c784a84a66adf221597', 'source-node-000618', '5', '638', 'text', '发病后处理：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000640', 'source-doc-4c784a84a66adf221597', 'source-node-000639', '6', '639', 'text', '控不住就砍掉运走，最好树桩也挖走，用柴油把基坑高温消毒', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000641', 'source-doc-4c784a84a66adf221597', 'source-node-000547', '3', '640', 'text', '柑橘青枯病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000642', 'source-doc-4c784a84a66adf221597', 'source-node-000641', '4', '641', 'text', '发病规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000643', 'source-doc-4c784a84a66adf221597', 'source-node-000642', '5', '642', 'text', '病原菌：青枯雷尔氏菌（Ralstonia solanacearum），通过根系伤口侵入，在维管束内繁殖，堵塞导管导致植株萎蔫。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000644', 'source-doc-4c784a84a66adf221597', 'source-node-000642', '5', '643', 'text', '传播途径：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000645', 'source-doc-4c784a84a66adf221597', 'source-node-000644', '6', '644', 'text', '土壤传播：病菌在土壤中存活多年，通过灌溉水、农具传播。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000646', 'source-doc-4c784a84a66adf221597', 'source-node-000644', '6', '645', 'text', '线虫协同：根结线虫危害根系，为病菌入侵提供途径。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000647', 'source-doc-4c784a84a66adf221597', 'source-node-000642', '5', '646', 'text', '症状表现：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000648', 'source-doc-4c784a84a66adf221597', 'source-node-000647', '6', '647', 'text', '全株萎蔫：初期顶梢叶片失水萎蔫，后整株枯死，根系腐烂，木质部变褐。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000649', 'source-doc-4c784a84a66adf221597', 'source-node-000641', '4', '648', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000650', 'source-doc-4c784a84a66adf221597', 'source-node-000649', '5', '649', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000651', 'source-doc-4c784a84a66adf221597', 'source-node-000641', '4', '650', 'text', '预防方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000652', 'source-doc-4c784a84a66adf221597', 'source-node-000651', '5', '651', 'text', '土壤改良：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000653', 'source-doc-4c784a84a66adf221597', 'source-node-000652', '6', '652', 'text', '石灰调节：调节 pH 至 7.0 左右，降低酸性土壤中病菌活性，结合有机肥（如羊粪）施用效果更佳。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000654', 'source-doc-4c784a84a66adf221597', 'source-node-000652', '6', '653', 'text', '微生物菌肥：每亩施用 200kg 复合菌剂，增加有益菌群，抑制病原菌繁殖。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000655', 'source-doc-4c784a84a66adf221597', 'source-node-000651', '5', '654', 'text', '抗病砧木：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000656', 'source-doc-4c784a84a66adf221597', 'source-node-000655', '6', '655', 'text', '酸柚砧木 + 沙田柚接穗：在广东梅州等地推广，青枯病发生率降低 60%。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000657', 'source-doc-4c784a84a66adf221597', 'source-node-000641', '4', '656', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000658', 'source-doc-4c784a84a66adf221597', 'source-node-000657', '5', '657', 'text', '土壤消毒与灌根药剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000659', 'source-doc-4c784a84a66adf221597', 'source-node-000658', '6', '658', 'text', '化学药剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000660', 'source-doc-4c784a84a66adf221597', 'source-node-000659', '7', '659', 'text', '敌克松（50% 可湿性粉剂）：500 倍液，定植前淋施土壤，杀灭病原菌，需注意安全间隔期。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000661', 'source-doc-4c784a84a66adf221597', 'source-node-000659', '7', '660', 'text', '噻唑锌（20% 悬浮剂）：800 倍液，锌离子 + 噻唑基团双重作用，对维管束病害特效，可促根。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000662', 'source-doc-4c784a84a66adf221597', 'source-node-000658', '6', '661', 'text', '生物防治：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000663', 'source-doc-4c784a84a66adf221597', 'source-node-000662', '7', '662', 'text', '淡紫紫孢菌 ZJPL08（200 亿 CFU/g）：拌土或灌根，寄生线虫并抑制青枯病菌，防效达 60% 以上。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000664', 'source-doc-4c784a84a66adf221597', 'source-node-000662', '7', '663', 'text', '大蒜素（0.5% 乳油）：800 倍液，喷雾或灌根，抑制病菌呼吸作用，对根腐病特效。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000665', 'source-doc-4c784a84a66adf221597', 'source-node-000658', '6', '664', 'text', '区域化方案：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000666', 'source-doc-4c784a84a66adf221597', 'source-node-000665', '7', '665', 'text', '华中产区（江西、湖南）：土壤消毒（敌克松 500 倍液）+ 微生物菌肥（荧光假单胞杆菌 200 亿 CFU/g），起垄栽培降低积水风险。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000667', 'source-doc-4c784a84a66adf221597', 'source-node-000657', '5', '666', 'text', '农业措施：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000668', 'source-doc-4c784a84a66adf221597', 'source-node-000667', '6', '667', 'text', '起垄栽培：垄高 30-40cm，降低积水风险，减少根系缺氧导致的抗病力下降。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000669', 'source-doc-4c784a84a66adf221597', 'source-node-000547', '3', '668', 'text', '柑橘溃疡病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000670', 'source-doc-4c784a84a66adf221597', 'source-node-000669', '4', '669', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000671', 'source-doc-4c784a84a66adf221597', 'source-node-000670', '5', '670', 'text', '叶片：初期叶背生油浸状黄色小斑点，扩大后穿透叶肉，两面隆起成近圆形木栓化灰褐色病斑，中部凹陷如火山口，周围有黄色晕圈，部分品种晕圈外有褐色釉光边缘', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000672', 'source-doc-4c784a84a66adf221597', 'source-node-000670', '5', '671', 'text', '枝梢：病斑更凸起，木栓化重，圆形或椭圆形，常环侵枝茎，无黄色晕圈', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000673', 'source-doc-4c784a84a66adf221597', 'source-node-000670', '5', '672', 'text', '果实：病斑更大（5-12mm），初期油泡状半透', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000674', 'source-doc-4c784a84a66adf221597', 'source-node-000670', '5', '673', 'text', '明凸起，后期中部凹陷龟裂，木栓化显著，火山口状开裂更明显，坚硬粗糙，无黄色晕圈', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000675', 'source-doc-4c784a84a66adf221597', 'source-node-000669', '4', '674', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000676', 'source-doc-4c784a84a66adf221597', 'source-node-000675', '5', '675', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000677', 'source-doc-4c784a84a66adf221597', 'source-node-000669', '4', '676', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000678', 'source-doc-4c784a84a66adf221597', 'source-node-000677', '5', '677', 'text', '病原菌为地毯草黄单胞菌柑橘致病型', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000679', 'source-doc-4c784a84a66adf221597', 'source-node-000669', '4', '678', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000680', 'source-doc-4c784a84a66adf221597', 'source-node-000679', '5', '679', 'text', '病菌在病叶、枝梢、病果病斑中越冬，秋梢病斑是主要越冬场所，翌年春季温度适宜且多雨时，病菌从病斑溢出，借风雨、昆虫、枝叶接触等传播到幼嫩组织，有水膜时20 分钟即可从气孔、皮孔或伤口侵入。高温多雨季节可多次再侵染，远距离传播靠带菌苗木、接穗和果实', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000681', 'source-doc-4c784a84a66adf221597', 'source-node-000669', '4', '680', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000682', 'source-doc-4c784a84a66adf221597', 'source-node-000681', '5', '681', 'text', '①检疫：严格检疫繁殖材料和果实，建立无病苗圃', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000683', 'source-doc-4c784a84a66adf221597', 'source-node-000681', '5', '682', 'text', '②农业措施：冬季清园剪除病枝、清扫病残体销毁；合理施肥控氮增钾；抹除夏梢和早秋梢，统一放梢；果园布局防风林', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000684', 'source-doc-4c784a84a66adf221597', 'source-node-000681', '5', '683', 'text', '③抗病品种：选用宽皮橘类（如温州蜜柑系列）、杂柑系列等抗病品种', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000685', 'source-doc-4c784a84a66adf221597', 'source-node-000681', '5', '684', 'text', '④药剂防治：嫩梢期喷20% 噻菌铜悬浮剂 600倍液、70%氢氧化铜可湿性粉剂600 倍液等，间隔7-10 天喷1 次，交替用药', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000686', 'source-doc-4c784a84a66adf221597', 'source-node-000547', '3', '685', 'text', '柑橘脂点黄斑病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000687', 'source-doc-4c784a84a66adf221597', 'source-node-000686', '4', '686', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000688', 'source-doc-4c784a84a66adf221597', 'source-node-000687', '5', '687', 'text', '叶部：分黄斑型（叶背针头黄点→扩展为黄斑→疱疹状突起→褐色脂斑）、褐色小圆星型（赤褐芝麻点→圆形斑→灰白+黑粒）、混合型（同叶共存两种病斑）；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000689', 'source-doc-4c784a84a66adf221597', 'source-node-000687', '5', '688', 'text', '果部：向阳果面出现疱疹状污黄小突粒，扩展成大块脂斑', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000690', 'source-doc-4c784a84a66adf221597', 'source-node-000686', '4', '689', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000691', 'source-doc-4c784a84a66adf221597', 'source-node-000690', '5', '690', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000692', 'source-doc-4c784a84a66adf221597', 'source-node-000686', '4', '691', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000693', 'source-doc-4c784a84a66adf221597', 'source-node-000692', '5', '692', 'text', '有性阶段为柑橘球腔菌（Mycosphaerellacitri），无性阶段为柑橘灰色疣丝孢菌（Stenellacitri-grisea）等', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000694', 'source-doc-4c784a84a66adf221597', 'source-node-000686', '4', '693', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000695', 'source-doc-4c784a84a66adf221597', 'source-node-000694', '5', '694', 'text', '病菌以菌丝体在病叶/落叶越冬，翌年气温≥20℃时释放子囊孢子，借风雨传播；5-7月为侵染高峰，潜育期2-4个月', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000696', 'source-doc-4c784a84a66adf221597', 'source-node-000686', '4', '695', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000697', 'source-doc-4c784a84a66adf221597', 'source-node-000696', '5', '696', 'text', '增强树势：防螨害、施有机肥；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000698', 'source-doc-4c784a84a66adf221597', 'source-node-000696', '5', '697', 'text', '冬季清园：清除落叶烧毁，减少菌源；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000699', 'source-doc-4c784a84a66adf221597', 'source-node-000696', '5', '698', 'text', '药剂防治：谢花后/春梢展开后喷70%甲基硫菌灵800-1000倍液、70%代森锰锌600倍液等，连喷2-3次', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000700', 'source-doc-4c784a84a66adf221597', 'source-node-000546', '2', '699', 'text', '真菌性病害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000701', 'source-doc-4c784a84a66adf221597', 'source-node-000700', '3', '700', 'text', '柑橘炭疽病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000702', 'source-doc-4c784a84a66adf221597', 'source-node-000701', '4', '701', 'text', '发病规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000703', 'source-doc-4c784a84a66adf221597', 'source-node-000702', '5', '702', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000704', 'source-doc-4c784a84a66adf221597', 'source-node-000703', '6', '703', 'text', '叶片：急性型呈开水烫伤状，慢性型为边缘褐色、中央灰白色的圆形病斑。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000705', 'source-doc-4c784a84a66adf221597', 'source-node-000703', '6', '704', 'text', '叶片：急性型似开水烫伤，慢性型为近圆形凹陷病斑（中央灰白边缘褐，潮湿生朱红色液点）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000706', 'source-doc-4c784a84a66adf221597', 'source-node-000703', '6', '705', 'text', '果实：果蒂处出现褐色病斑，湿度大时腐烂并产生朱红色黏液。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000707', 'source-doc-4c784a84a66adf221597', 'source-node-000703', '6', '706', 'text', '果实：干斑（黄褐色凹陷革质）、果腐（深褐腐烂）、泪痕型（红褐色小凸点）、僵果（暗绿凹陷后变黑）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000708', 'source-doc-4c784a84a66adf221597', 'source-node-000703', '6', '707', 'text', '枝梢：急性型嫩梢似烫伤后生橘红色液点，慢性型从叶柄基部呈长梭形病斑', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000709', 'source-doc-4c784a84a66adf221597', 'source-node-000702', '5', '708', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000710', 'source-doc-4c784a84a66adf221597', 'source-node-000709', '6', '709', 'text', '病原菌：围小丛壳菌（Glomerella cingulata），通过气孔或伤口侵入，高温多雨（25-30℃）季节高发，台风后易暴发。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000711', 'source-doc-4c784a84a66adf221597', 'source-node-000709', '6', '710', 'text', '病原菌为半知菌亚门的盘长孢状刺盘孢菌（无性阶段）和子囊菌亚门的围小丛壳菌（有性阶段）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000712', 'source-doc-4c784a84a66adf221597', 'source-node-000702', '5', '711', 'text', '传播途径：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000713', 'source-doc-4c784a84a66adf221597', 'source-node-000712', '6', '712', 'text', '风雨传播：分生孢子随雨水飞溅扩散，可侵染新梢、叶片、果实。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000714', 'source-doc-4c784a84a66adf221597', 'source-node-000712', '6', '713', 'text', '潜伏侵染：病菌在嫩叶、幼果期侵入并潜伏，树势衰弱时显症。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000715', 'source-doc-4c784a84a66adf221597', 'source-node-000702', '5', '714', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000716', 'source-doc-4c784a84a66adf221597', 'source-node-000715', '6', '715', 'text', '病菌以菌丝体在病残体越冬，风雨传播，春、秋梢转绿期发病快；地势低洼、排水差、种植密的果园易发病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000717', 'source-doc-4c784a84a66adf221597', 'source-node-000701', '4', '716', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000718', 'source-doc-4c784a84a66adf221597', 'source-node-000717', '5', '717', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000719', 'source-doc-4c784a84a66adf221597', 'source-node-000717', '5', '718', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000720', 'source-doc-4c784a84a66adf221597', 'source-node-000701', '4', '719', 'text', '预防方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000721', 'source-doc-4c784a84a66adf221597', 'source-node-000720', '5', '720', 'text', '农业措施：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000722', 'source-doc-4c784a84a66adf221597', 'source-node-000721', '6', '721', 'text', '修剪清园：冬季剪除病枝，集中烧毁；生长期及时摘除病叶，减少菌源。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000723', 'source-doc-4c784a84a66adf221597', 'source-node-000721', '6', '722', 'text', '增强树势：增施有机肥（如羊粪 20kg / 株）和钙肥（硝酸钙 20kg / 亩），避免偏施氮肥。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000724', 'source-doc-4c784a84a66adf221597', 'source-node-000720', '5', '723', 'text', '物理屏障：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000725', 'source-doc-4c784a84a66adf221597', 'source-node-000724', '6', '724', 'text', '台风前全园覆盖防虫网（孔径 0.6mm），减少病菌飞溅传播。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000726', 'source-doc-4c784a84a66adf221597', 'source-node-000701', '4', '725', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000727', 'source-doc-4c784a84a66adf221597', 'source-node-000726', '5', '726', 'text', '化学防治（按效果排序）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000728', 'source-doc-4c784a84a66adf221597', 'source-node-000727', '6', '727', 'text', '化学防治：发病初期喷80% 炭疽福美600 倍液、10% 苯醚甲环唑、吡唑醚菌酯、咪鲜胺、溴菌腈等', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000729', 'source-doc-4c784a84a66adf221597', 'source-node-000727', '6', '728', 'text', '治疗性杀菌剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000730', 'source-doc-4c784a84a66adf221597', 'source-node-000729', '7', '729', 'text', '咪鲜胺（45% 水乳剂 1000 倍液）：发病初期喷施，抑制孢子萌发，持效期 7-10 天。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000731', 'source-doc-4c784a84a66adf221597', 'source-node-000729', '7', '730', 'text', '苯醚甲环唑（10% 水分散粒剂 1500 倍液）：内吸性强，对炭疽病特效，可兼治疮痂病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000732', 'source-doc-4c784a84a66adf221597', 'source-node-000729', '7', '731', 'text', '吡唑醚菌酯（25% 悬浮剂 2000 倍液）：预防 + 治疗，促进树体抗病力，延缓衰老。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000733', 'source-doc-4c784a84a66adf221597', 'source-node-000727', '6', '732', 'text', '保护性杀菌剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000734', 'source-doc-4c784a84a66adf221597', 'source-node-000733', '7', '733', 'text', '代森锰锌（80% 可湿性粉剂 600 倍液）：雨前喷施，形成保护膜，兼防真菌病害。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000735', 'source-doc-4c784a84a66adf221597', 'source-node-000733', '7', '734', 'text', '丙森锌（70% 可湿性粉剂 500 倍液）：锌离子增强抗病力，适合幼果期使用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000736', 'source-doc-4c784a84a66adf221597', 'source-node-000727', '6', '735', 'text', '复配药剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000737', 'source-doc-4c784a84a66adf221597', 'source-node-000736', '7', '736', 'text', '苯甲・嘧菌酯（32.5% 悬浮剂 1500 倍液）：内吸 + 保护，防效提升 30%，可兼治树脂病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000738', 'source-doc-4c784a84a66adf221597', 'source-node-000726', '5', '737', 'text', '农业措施：选高地势育苗，加强排灌、增施有机肥、清除病残体', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000739', 'source-doc-4c784a84a66adf221597', 'source-node-000726', '5', '738', 'text', '区域化方案：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000740', 'source-doc-4c784a84a66adf221597', 'source-node-000739', '6', '739', 'text', '华南产区（广东、广西）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000741', 'source-doc-4c784a84a66adf221597', 'source-node-000740', '7', '740', 'text', '炭疽病：春梢期（咪鲜胺 1000 倍液）+ 幼果期（苯醚甲环唑 1500 倍液）+ 秋梢期（吡唑醚菌酯 2000 倍液），台风后补喷代森锰锌 600 倍液 + 矿物油 200 倍液。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000742', 'source-doc-4c784a84a66adf221597', 'source-node-000726', '5', '741', 'text', '轮换原则：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000743', 'source-doc-4c784a84a66adf221597', 'source-node-000742', '6', '742', 'text', '咪鲜胺→苯醚甲环唑→吡唑醚菌酯→枯草芽孢杆菌，每季度轮换 2-3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000744', 'source-doc-4c784a84a66adf221597', 'source-node-000726', '5', '743', 'text', '生物防治：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000745', 'source-doc-4c784a84a66adf221597', 'source-node-000744', '6', '744', 'text', '枯草芽孢杆菌（1000 亿 CFU/g）：稀释 1500 倍液喷雾，通过竞争营养抑制病菌繁殖，与低浓度铜制剂混用增效。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000746', 'source-doc-4c784a84a66adf221597', 'source-node-000744', '6', '745', 'text', '木霉菌（2 亿 CFU/g）：拌土或灌根，降解病菌细胞壁，对炭疽病防效达 60% 以上。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000747', 'source-doc-4c784a84a66adf221597', 'source-node-000700', '3', '746', 'text', '柑橘疮痂病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000748', 'source-doc-4c784a84a66adf221597', 'source-node-000747', '4', '747', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000749', 'source-doc-4c784a84a66adf221597', 'source-node-000748', '5', '748', 'text', '叶片：嫩叶初为水渍状小斑点，后呈蜡黄色，叶背隆起木栓化，叶面凹陷呈圆锥状 / 漏斗状病斑，叶片扭曲畸形，早期脱落；初期油渍状小点，后扩大为蜡黄色圆锥状突起，严重时叶片扭曲畸形。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000750', 'source-doc-4c784a84a66adf221597', 'source-node-000748', '5', '749', 'text', '枝梢：病斑突起不明显，分散或连片，后期呈灰白色斑疤，梢短弱扭曲', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000751', 'source-doc-4c784a84a66adf221597', 'source-node-000748', '5', '750', 'text', '果实：幼果谢花后发病，初期为褐色小点，渐成黄褐色木栓化瘤状隆起，严重时密集连片，果实畸形早落；幼果表面形成瘤状突起，后期木栓化，影响果实外观。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000752', 'source-doc-4c784a84a66adf221597', 'source-node-000747', '4', '751', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000753', 'source-doc-4c784a84a66adf221597', 'source-node-000752', '5', '752', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000754', 'source-doc-4c784a84a66adf221597', 'source-node-000752', '5', '753', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000755', 'source-doc-4c784a84a66adf221597', 'source-node-000747', '4', '754', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000756', 'source-doc-4c784a84a66adf221597', 'source-node-000755', '5', '755', 'text', '无性阶段为柑橘痂圆孢菌 Sphaceloma fawcetti，仅侵染柑橘类植物；低温高湿（15-24℃）时活跃，春梢期和幼果期易感病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000757', 'source-doc-4c784a84a66adf221597', 'source-node-000747', '4', '756', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000758', 'source-doc-4c784a84a66adf221597', 'source-node-000757', '5', '757', 'text', '病菌以菌丝体在病组织越冬，翌年15℃以上阴雨时产生分生孢子，借风雨 / 昆虫传播到嫩梢、嫩叶、幼果，潜育期 3-10 天，反复侵染。春天雨水多春梢发病重，5-6 月中旬果实易发病，橘类、温州蜜柑最感病，远距离传播靠带病苗木/ 果实。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000759', 'source-doc-4c784a84a66adf221597', 'source-node-000757', '5', '758', 'text', '传播途径：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000760', 'source-doc-4c784a84a66adf221597', 'source-node-000759', '6', '759', 'text', '风雨传播：分生孢子借雨水飞溅至新梢、幼果。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000761', 'source-doc-4c784a84a66adf221597', 'source-node-000759', '6', '760', 'text', '农事操作：修剪工具接触带菌组织后传播。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000762', 'source-doc-4c784a84a66adf221597', 'source-node-000747', '4', '761', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000763', 'source-doc-4c784a84a66adf221597', 'source-node-000762', '5', '762', 'text', '①喷药保护：苗木 /幼树保梢石硫合剂或波尔多液等铜制剂（芽长 1-2mm 喷 1次，10-15天再喷）；结果树保果（花落 2~3 喷，夏/ 秋梢多雨补喷），药剂可选68.75% 唑菌酮・代森锰锌 1500 倍液等；春梢萌芽前，喷施矿物油（200 倍液）封闭越冬病菌。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000764', 'source-doc-4c784a84a66adf221597', 'source-node-000763', '6', '763', 'text', '化学防治（按效果排序）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000765', 'source-doc-4c784a84a66adf221597', 'source-node-000764', '7', '764', 'text', '内吸性杀菌剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000766', 'source-doc-4c784a84a66adf221597', 'source-node-000765', '8', '765', 'text', '戊唑醇（43% 悬浮剂 3000 倍液）：抑制病菌麦角甾醇合成，对疮痂病特效，持效期 15 天以上。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000767', 'source-doc-4c784a84a66adf221597', 'source-node-000765', '8', '766', 'text', '苯醚甲环唑（10% 水分散粒剂 1500 倍液）：新梢期和幼果期喷施，兼防炭疽病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000768', 'source-doc-4c784a84a66adf221597', 'source-node-000764', '7', '767', 'text', '保护性杀菌剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000769', 'source-doc-4c784a84a66adf221597', 'source-node-000768', '8', '768', 'text', '波尔多液（1:1:100）：春梢萌芽前和谢花 2/3 时使用，杀菌谱广，但需现配现用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000770', 'source-doc-4c784a84a66adf221597', 'source-node-000768', '8', '769', 'text', '代森锰锌（80% 可湿性粉剂 600 倍液）：雨前喷施，预防病菌侵染。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000771', 'source-doc-4c784a84a66adf221597', 'source-node-000764', '7', '770', 'text', '复配药剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000772', 'source-doc-4c784a84a66adf221597', 'source-node-000771', '8', '771', 'text', '唑醚・代森联（60% 水分散粒剂 750 倍液）：吡唑醚菌酯 + 代森联，保护 + 治疗，对疮痂病防效达 85% 以上。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000773', 'source-doc-4c784a84a66adf221597', 'source-node-000762', '5', '772', 'text', '②农业措施：冬季清园剪除病枝、清除病残体；合理修剪增强通风透光；合理密植（柚类 4×5m 株行距），改善通风透光条件；增施磷钾肥，促进新梢老熟。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000774', 'source-doc-4c784a84a66adf221597', 'source-node-000762', '5', '773', 'text', '③检疫：禁止从病区输入苗木 / 接穗/ 果实。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000775', 'source-doc-4c784a84a66adf221597', 'source-node-000700', '3', '774', 'text', '柑橘树脂病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000776', 'source-doc-4c784a84a66adf221597', 'source-node-000775', '4', '775', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000777', 'source-doc-4c784a84a66adf221597', 'source-node-000776', '5', '776', 'text', '流胶型：皮层坏死松软、裂纹水渍状，渗出褐色胶液（有酒糟味），高温干燥时病部干枯下陷、皮层剥落', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000778', 'source-doc-4c784a84a66adf221597', 'source-node-000776', '5', '777', 'text', '干枯型：皮层红褐色干枯下陷，病健交界处有隆起线，病菌侵害木质部（病部浅灰褐色，交界处有褐/ 黑褐色痕带）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000779', 'source-doc-4c784a84a66adf221597', 'source-node-000776', '5', '778', 'text', '沙皮与黑点：新梢、嫩叶、未成熟果实表面生散生 / 密集成片的褐/ 黑褐色硬胶质小粒点（似细沙）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000780', 'source-doc-4c784a84a66adf221597', 'source-node-000776', '5', '779', 'text', '蒂腐：贮藏期果蒂始发水渍状褐斑，革质有韧性，病斑边缘波纹状，菌丝蔓延果心致 “穿心烂”（褐色蒂腐病）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000781', 'source-doc-4c784a84a66adf221597', 'source-node-000775', '4', '780', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000782', 'source-doc-4c784a84a66adf221597', 'source-node-000781', '5', '781', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000783', 'source-doc-4c784a84a66adf221597', 'source-node-000781', '5', '782', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000784', 'source-doc-4c784a84a66adf221597', 'source-node-000775', '4', '783', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000785', 'source-doc-4c784a84a66adf221597', 'source-node-000784', '5', '784', 'text', '有性阶段：Diaporthe medusaea（柑橘间座壳，子囊菌亚门）；通过冻伤、虫伤等伤口侵入，高温多雨（25-30℃）季节高发。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000786', 'source-doc-4c784a84a66adf221597', 'source-node-000784', '5', '785', 'text', '无性阶段：Phomopsis cytosporella（柑橘拟茎点霉菌，半知菌亚门）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000787', 'source-doc-4c784a84a66adf221597', 'source-node-000775', '4', '786', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000788', 'source-doc-4c784a84a66adf221597', 'source-node-000787', '5', '787', 'text', '病菌以分生孢子器和分生孢子在病组织内越冬，借风雨、昆虫（天牛、吉丁虫等害虫携带病菌）传播，从伤口侵入；低温高湿 / 高温多雨、树势衰弱 / 冻害伤口、过熟果实易感病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000789', 'source-doc-4c784a84a66adf221597', 'source-node-000775', '4', '788', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000790', 'source-doc-4c784a84a66adf221597', 'source-node-000789', '5', '789', 'text', '农业措施：增施有机肥改良土壤，营造防风林改善生态，防寒防冻防伤保护枝干', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000791', 'source-doc-4c784a84a66adf221597', 'source-node-000790', '6', '790', 'text', '物理防治：修剪后及时涂抹伤口愈合剂（如 3% 腐殖酸钠水剂），防止病菌侵染。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000792', 'source-doc-4c784a84a66adf221597', 'source-node-000790', '6', '791', 'text', '虫害防控：重点防治天牛、吉丁虫，减少机械伤口。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000793', 'source-doc-4c784a84a66adf221597', 'source-node-000790', '6', '792', 'text', '防寒防冻：冬季主干涂白（硫酸铜：生石灰：水 = 1:20:80），培土 30cm 保护根颈。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000794', 'source-doc-4c784a84a66adf221597', 'source-node-000789', '5', '793', 'text', '化学防治：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000795', 'source-doc-4c784a84a66adf221597', 'source-node-000794', '6', '794', 'text', '喷药：春梢萌发期、花落 2/3、幼果期各喷1 次，可选0.5%-0.8% 石灰等量式波尔多液、50% 退菌特500-600 倍液、70%甲基硫菌灵 800 倍液等', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000796', 'source-doc-4c784a84a66adf221597', 'source-node-000794', '6', '795', 'text', '化学防治（按效果排序）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000797', 'source-doc-4c784a84a66adf221597', 'source-node-000796', '7', '796', 'text', '治疗性杀菌剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000798', 'source-doc-4c784a84a66adf221597', 'source-node-000797', '8', '797', 'text', '啶氧菌酯（22.5% 悬浮剂 2000 倍液）：穿透性强，抑制病菌呼吸作用，对树脂病特效。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000799', 'source-doc-4c784a84a66adf221597', 'source-node-000797', '8', '798', 'text', '氟唑菌酰胺・咪鲜胺（18% 微囊悬浮剂 2000 倍液）：德国进口专利复配，双效协同，持效期 21 天以上。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000800', 'source-doc-4c784a84a66adf221597', 'source-node-000796', '7', '799', 'text', '保护性杀菌剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000801', 'source-doc-4c784a84a66adf221597', 'source-node-000800', '8', '800', 'text', '代森锰锌（80% 可湿性粉剂 600 倍液）：春梢萌芽前和幼果期喷施，兼防炭疽病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000802', 'source-doc-4c784a84a66adf221597', 'source-node-000800', '8', '801', 'text', '丙森锌（70% 可湿性粉剂 500 倍液）：锌离子增强抗病力，适合果实膨大期使用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000803', 'source-doc-4c784a84a66adf221597', 'source-node-000796', '7', '802', 'text', '复配药剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000804', 'source-doc-4c784a84a66adf221597', 'source-node-000803', '8', '803', 'text', '苯甲・嘧菌酯（32.5% 悬浮剂 1500 倍液）：内吸 + 保护，对树脂病和炭疽病双重防控。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000805', 'source-doc-4c784a84a66adf221597', 'source-node-000796', '7', '804', 'text', '华南产区（广东、广西）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000806', 'source-doc-4c784a84a66adf221597', 'source-node-000805', '8', '805', 'text', '树脂病：谢花后（啶氧菌酯 2000 倍液）+ 果实膨大期（氟唑菌酰胺・咪鲜胺 2000 倍液），结合修剪清除枯枝。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000807', 'source-doc-4c784a84a66adf221597', 'source-node-000794', '6', '806', 'text', '枝干涂药：4-5月 /8-9 月纵刻病部后涂药（每期 3-4 次），药剂可选70% 甲基硫菌灵100 倍液、80% 大生M-45 100 倍液等，涂抹前用 1% 硫酸铜消毒', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000808', 'source-doc-4c784a84a66adf221597', 'source-node-000700', '3', '807', 'text', '柑橘流胶病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000809', 'source-doc-4c784a84a66adf221597', 'source-node-000808', '4', '808', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000810', 'source-doc-4c784a84a66adf221597', 'source-node-000809', '5', '809', 'text', '枝干：病斑不定形，初发病皮层出现红褐色小点，中央开裂流出胶液；老病斑可自然愈合或干燥翘裂；严重时病斑环绕树干，整株死亡', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000811', 'source-doc-4c784a84a66adf221597', 'source-node-000809', '5', '810', 'text', '叶片与果实：叶片中脉及侧脉深黄色易脱落，落叶枝梢干枯；病树开花多，幼果早落，残留果实小、提前转黄、味酸', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000812', 'source-doc-4c784a84a66adf221597', 'source-node-000809', '5', '811', 'text', '区别特征：流胶病不深入树干木质部为害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000813', 'source-doc-4c784a84a66adf221597', 'source-node-000808', '4', '812', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000814', 'source-doc-4c784a84a66adf221597', 'source-node-000813', '5', '813', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000815', 'source-doc-4c784a84a66adf221597', 'source-node-000808', '4', '814', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000816', 'source-doc-4c784a84a66adf221597', 'source-node-000815', '5', '815', 'text', '病原菌复杂，国内已知12种，常见的有壳囊孢属真菌、疫菌、金黄尖镰孢霉、亚疫霉、寄生疫霉烟草致病变种等；有时单一病原菌侵染，有时多种复合侵染，其中疫菌感染和病斑扩散最快', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000817', 'source-doc-4c784a84a66adf221597', 'source-node-000808', '4', '816', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000818', 'source-doc-4c784a84a66adf221597', 'source-node-000817', '5', '817', 'text', '季节与环境：高温多雨季节发病较重，菌核引起的流胶以冬季最盛；果园长期积水、土壤黏重、树冠郁闭、树干有伤口（虫害/人为）均利于发病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000819', 'source-doc-4c784a84a66adf221597', 'source-node-000817', '5', '818', 'text', '品种差异：四川地区柠檬、甜橙发病严重；浙江地区温州蜜柑（早熟品种更烈）、槾橘、早橘较重', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000820', 'source-doc-4c784a84a66adf221597', 'source-node-000808', '4', '819', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000821', 'source-doc-4c784a84a66adf221597', 'source-node-000820', '5', '820', 'text', '农业措施：选用耐病砧木（枳、红橘等）并提高嫁接口位置；开沟排水改良土壤，避免积水；树干刷白、刨土，加强蛀干害虫防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000822', 'source-doc-4c784a84a66adf221597', 'source-node-000820', '5', '821', 'text', '药剂防治：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000823', 'source-doc-4c784a84a66adf221597', 'source-node-000822', '6', '822', 'text', '病部处理：浅刮病部粗皮后纵切裂口（深达木质部），涂50%甲基硫菌灵/多菌灵100-200倍液、80%乙膦铝100-200倍液、25%甲霜灵400倍液等', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000824', 'source-doc-4c784a84a66adf221597', 'source-node-000822', '6', '823', 'text', '刮除涂药：刮除腐烂组织及周围健康组织后，涂25%瑞毒霉100-200倍液、1:1:10波尔多浆，或石硫合剂渣加牛粪和碎毛发敷病部，定期巡视补药', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000825', 'source-doc-4c784a84a66adf221597', 'source-node-000700', '3', '824', 'text', '柑橘脚腐病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000826', 'source-doc-4c784a84a66adf221597', 'source-node-000825', '4', '825', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000827', 'source-doc-4c784a84a66adf221597', 'source-node-000826', '5', '826', 'text', '主干基部：初为不规则油渍状，树皮黄褐色至黑褐色腐烂，潮湿多雨时渗出褐色黏液，扩展至形成层、木质部，沿主干上下蔓延（向上可达45 厘米，向下至根系），导致主根、侧根腐烂', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000828', 'source-doc-4c784a84a66adf221597', 'source-node-000826', '5', '827', 'text', '树冠表现：叶片失光泽、变黄脱落，病斑环绕根颈时整株枯死；幼树多从嫁接口发病，树势衰弱、开花多、落果早', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000829', 'source-doc-4c784a84a66adf221597', 'source-node-000826', '5', '828', 'text', '根颈：皮层腐烂，流出褐色胶液，有酒糟气味，严重时植株萎蔫枯死。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000830', 'source-doc-4c784a84a66adf221597', 'source-node-000826', '5', '829', 'text', '根系：须根腐烂，木质部变褐。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000831', 'source-doc-4c784a84a66adf221597', 'source-node-000825', '4', '830', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000832', 'source-doc-4c784a84a66adf221597', 'source-node-000831', '5', '831', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000833', 'source-doc-4c784a84a66adf221597', 'source-node-000831', '5', '832', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000834', 'source-doc-4c784a84a66adf221597', 'source-node-000825', '4', '833', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000835', 'source-doc-4c784a84a66adf221597', 'source-node-000834', '5', '834', 'text', '病原菌：寄生疫霉（Phytophthora parasitica），通过根系伤口侵入，高温高湿（25-30℃）季节高发，低洼积水果园易流行。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000836', 'source-doc-4c784a84a66adf221597', 'source-node-000834', '5', '835', 'text', '病原菌为多种真菌，常见的有腐皮镰孢、寄生疫霉、柑橘褐腐疫霉、德氏腐霉、逸见腐霉等', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000837', 'source-doc-4c784a84a66adf221597', 'source-node-000825', '4', '836', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000838', 'source-doc-4c784a84a66adf221597', 'source-node-000837', '5', '837', 'text', '传播途径：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000839', 'source-doc-4c784a84a66adf221597', 'source-node-000838', '6', '838', 'text', '土壤传播：病菌在土壤中存活多年，通过灌溉水传播。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000840', 'source-doc-4c784a84a66adf221597', 'source-node-000838', '6', '839', 'text', '农事操作：农具接触带菌土壤后传播。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000841', 'source-doc-4c784a84a66adf221597', 'source-node-000837', '5', '840', 'text', '病菌以菌丝体、厚垣孢子或卵孢子在病残体或土壤中越冬，借雨水传播，从伤口或植株衰弱处侵入；近地面果实也可被侵染，多雨潮湿环境利于发病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000842', 'source-doc-4c784a84a66adf221597', 'source-node-000825', '4', '841', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000843', 'source-doc-4c784a84a66adf221597', 'source-node-000842', '5', '842', 'text', '抗病砧木：选用枳、枸头橙等抗病砧木，提高嫁接口位置', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000844', 'source-doc-4c784a84a66adf221597', 'source-node-000842', '5', '843', 'text', '栽培管理：开沟排水防积水，避免间种高秆作物，定植时嫁接口露出土面，增施有机肥，防治树干害虫', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000845', 'source-doc-4c784a84a66adf221597', 'source-node-000842', '5', '844', 'text', '病树治疗：扒开根颈土壤，刮除病部后涂药（如 1:1:10 波尔多液、3%硫酸铜液、25%甲霜灵可湿性粉剂 500 倍液等）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000846', 'source-doc-4c784a84a66adf221597', 'source-node-000842', '5', '845', 'text', '靠接砧木：重病树靠接 3-4株抗病实生苗，增强根系活力', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000847', 'source-doc-4c784a84a66adf221597', 'source-node-000842', '5', '846', 'text', '农业措施：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000848', 'source-doc-4c784a84a66adf221597', 'source-node-000847', '6', '847', 'text', '选用抗病砧木：枳壳、枸头橙等砧木抗病性强，嫁接部位高于地面 10cm 以上。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000849', 'source-doc-4c784a84a66adf221597', 'source-node-000847', '6', '848', 'text', '起垄栽培：垄高 30-40cm，降低积水风险。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000850', 'source-doc-4c784a84a66adf221597', 'source-node-000842', '5', '849', 'text', '药剂防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000851', 'source-doc-4c784a84a66adf221597', 'source-node-000850', '6', '850', 'text', '内吸性杀菌剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000852', 'source-doc-4c784a84a66adf221597', 'source-node-000851', '7', '851', 'text', '甲霜灵（25% 可湿性粉剂 500 倍液）：灌根或涂抹病部，抑制病菌游动孢子萌发。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000853', 'source-doc-4c784a84a66adf221597', 'source-node-000851', '7', '852', 'text', '烯酰吗啉（80% 水分散粒剂 2000 倍液）：针对卵菌纲病菌，对脚腐病特效。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000854', 'source-doc-4c784a84a66adf221597', 'source-node-000850', '6', '853', 'text', '保护性杀菌剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000855', 'source-doc-4c784a84a66adf221597', 'source-node-000854', '7', '854', 'text', '波尔多浆（1:1:10）：刮除病皮后涂抹，形成保护膜。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000856', 'source-doc-4c784a84a66adf221597', 'source-node-000854', '7', '855', 'text', '硫酸铜（2% 溶液）：灌根或涂抹病部，杀灭土壤中病菌。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000857', 'source-doc-4c784a84a66adf221597', 'source-node-000850', '6', '856', 'text', '复配药剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000858', 'source-doc-4c784a84a66adf221597', 'source-node-000857', '7', '857', 'text', '唑醚・代森联（60% 水分散粒剂 750 倍液）：吡唑醚菌酯 + 代森联，保护 + 治疗，防效提升 40%。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000859', 'source-doc-4c784a84a66adf221597', 'source-node-000850', '6', '858', 'text', '华中产区（江西、湖南）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000860', 'source-doc-4c784a84a66adf221597', 'source-node-000859', '7', '859', 'text', '脚腐病：定植前土壤消毒（甲霜灵 500 倍液）+ 生长期灌根（烯酰吗啉 2000 倍液），起垄栽培降低积水风险。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000861', 'source-doc-4c784a84a66adf221597', 'source-node-000700', '3', '860', 'text', '柑橘黑斑病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000862', 'source-doc-4c784a84a66adf221597', 'source-node-000861', '4', '861', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000863', 'source-doc-4c784a84a66adf221597', 'source-node-000862', '5', '862', 'text', '黑斑型：果面初呈淡黄色或橙色斑点，后扩大为圆形/不规则形黑色或黑褐色大病斑（直径1~3cm），严重时多个病斑联合；贮藏期病果腐烂后瓤囊僵化呈黑色。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000864', 'source-doc-4c784a84a66adf221597', 'source-node-000862', '5', '863', 'text', '黑星型：近成熟果面出现红褐色圆形小斑，扩大后边缘稍隆起（红褐色至黑色）、中间灰褐色至灰白色略凹陷，其上生少量小黑粒点（分生孢子器）；一个果可生数个至数十个病斑，常导致落果，贮运期病害继续发生引致全果腐烂；枝梢和叶片症状与果实相似。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000865', 'source-doc-4c784a84a66adf221597', 'source-node-000861', '4', '864', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000866', 'source-doc-4c784a84a66adf221597', 'source-node-000865', '5', '865', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000867', 'source-doc-4c784a84a66adf221597', 'source-node-000861', '4', '866', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000868', 'source-doc-4c784a84a66adf221597', 'source-node-000867', '5', '867', 'text', '无性阶段：Phomaciricarpa（半知菌亚门茎点霉菌属）；有性阶段：Guignardiacitricarpa（子囊菌亚门柑果球座真菌）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000869', 'source-doc-4c784a84a66adf221597', 'source-node-000861', '4', '868', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000870', 'source-doc-4c784a84a66adf221597', 'source-node-000869', '5', '869', 'text', '病菌在病枝叶和病果上越冬，发育适宜温度25℃；春季温湿度适宜时释放子囊孢子和分生孢子，借风雨、昆虫传播至幼果、嫩叶；高温多湿、闷热天气发病重；7年以上中老龄树、栽培管理粗放树势衰弱、种植密度大的果园发病较重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000871', 'source-doc-4c784a84a66adf221597', 'source-node-000861', '4', '870', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000872', 'source-doc-4c784a84a66adf221597', 'source-node-000871', '5', '871', 'text', '加强管理增强树势，冬季剪除病枝病叶、收集落叶落果烧毁以减少菌源；谢花后半个月内开始喷药保护幼果，每隔10~15d喷1次连2~3次，果实膨大期7~8月每月喷杀菌剂1~2次；药剂可选70%甲基硫菌灵可湿性粉剂800~1000倍液、75%百菌清可湿性粉剂600~800倍液，或苯醚甲环唑类（如10%世高水分散粒剂1000~1200倍液等）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000873', 'source-doc-4c784a84a66adf221597', 'source-node-000700', '3', '872', 'text', '柑橘褐斑病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000874', 'source-doc-4c784a84a66adf221597', 'source-node-000873', '4', '873', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000875', 'source-doc-4c784a84a66adf221597', 'source-node-000874', '5', '874', 'text', '幼叶受害：未展开的幼叶出现针头状小病斑，随后扩大为黄褐色至深褐色病斑，幼叶枯死脱落；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000876', 'source-doc-4c784a84a66adf221597', 'source-node-000874', '5', '875', 'text', '成长叶片受害：病斑大小及形状不一，微凹陷，中央色较淡，边缘不规则（褐色至深褐色），外围常呈黄色晕圈，病斑常沿叶片主脉、侧脉扩展，呈散射状或“拖尾”状；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000877', 'source-doc-4c784a84a66adf221597', 'source-node-000874', '5', '876', 'text', '嫩枝受害：病斑大小不一、数量不等，凹陷，褐色至深褐色，沿枝梢向上下扩大，导致病斑上部枯梢、叶片干枯；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000878', 'source-doc-4c784a84a66adf221597', 'source-node-000874', '5', '877', 'text', '花蕾和花瓣受害：呈赤黄色斑块状，随后脱落或干枯；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000879', 'source-doc-4c784a84a66adf221597', 'source-node-000874', '5', '878', 'text', '幼果受害：谢花时即感病，初为针头状病斑，后渐扩大、凹陷、黑褐色，易脱落；不脱落的幼果，病斑随果实膨大而凸起，表面木栓化龟裂（疤斑状），或成熟后呈黑色斑易腐烂。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000880', 'source-doc-4c784a84a66adf221597', 'source-node-000873', '4', '879', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000881', 'source-doc-4c784a84a66adf221597', 'source-node-000880', '5', '880', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000882', 'source-doc-4c784a84a66adf221597', 'source-node-000873', '4', '881', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000883', 'source-doc-4c784a84a66adf221597', 'source-node-000882', '5', '882', 'text', '半知菌类，交链格孢真菌', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000884', 'source-doc-4c784a84a66adf221597', 'source-node-000873', '4', '883', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000885', 'source-doc-4c784a84a66adf221597', 'source-node-000884', '5', '884', 'text', '病菌在带病老叶上越冬，翌年春天环境适宜时产生分生孢子，随气流传播；在温度20~29℃、湿度大于80%的条件下，病菌产生毒素致寄主细胞死亡，并继续扩散，病斑扩大且周围呈放散状，导致叶落、枝秃、落花、落幼果；当相对湿度大于85%时，利于病害发展。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000886', 'source-doc-4c784a84a66adf221597', 'source-node-000873', '4', '885', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000887', 'source-doc-4c784a84a66adf221597', 'source-node-000886', '5', '886', 'text', '①及时喷药：感病品种当春芽显露0.5~1cm时，开始喷第一次药剂，相隔7~10d喷第二次，在下雨前后，抓紧时机补喷药剂。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000888', 'source-doc-4c784a84a66adf221597', 'source-node-000886', '5', '887', 'text', '②选准有效的药剂。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000889', 'source-doc-4c784a84a66adf221597', 'source-node-000886', '5', '888', 'text', '③轮换使用药剂和药剂混合使用。可选用的药剂有：45%咪鲜胺微乳剂1000~1200倍液、10%苯醚甲环唑水分散粒剂、80%大生M-45可湿性粉剂500~600倍液、25%戊唑醇水乳剂1000~1500倍液+70%丙森锌可湿性粉剂600~800倍液、25%吡唑醚菌酯1000~1500倍液，以及异菌脲、铜制剂等。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000890', 'source-doc-4c784a84a66adf221597', 'source-node-000886', '5', '889', 'text', '④加强栽培管理：做好冬季清园，增施有机质肥，疏通排灌系统，做好修剪工作。严重的病果园进行高接换种或改种抗病品种。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000891', 'source-doc-4c784a84a66adf221597', 'source-node-000700', '3', '890', 'text', '柑橘煤烟病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000892', 'source-doc-4c784a84a66adf221597', 'source-node-000891', '4', '891', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000893', 'source-doc-4c784a84a66adf221597', 'source-node-000892', '5', '892', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000894', 'source-doc-4c784a84a66adf221597', 'source-node-000891', '4', '893', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000895', 'source-doc-4c784a84a66adf221597', 'source-node-000894', '5', '894', 'text', '叶片、枝条、果实表面形成乌黑霉层，阻碍光合作用致树势衰退；初期为暗褐色小霉斑，后扩大成绒毛状黑色霉层', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000896', 'source-doc-4c784a84a66adf221597', 'source-node-000891', '4', '895', 'text', '发病规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000897', 'source-doc-4c784a84a66adf221597', 'source-node-000896', '5', '896', 'text', '病原菌：煤炱属（Capnodium）和小煤炱属（Meliola）真菌，以蚜虫、粉虱、蚧壳虫的分泌物为营养，高温高湿（25-30℃）季节高发。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000898', 'source-doc-4c784a84a66adf221597', 'source-node-000896', '5', '897', 'text', '核心诱因：蚜虫、粉虱、蚧壳虫等刺吸式害虫分泌的蜜露（含葡萄糖、果糖、氨基酸）是真菌繁殖的唯一营养源。例如，橘蚜（Toxoptera citricidus）每头若蚜日均分泌蜜露 0.05-0.12mg，可支持煤炱属真菌完成 3-5 个世代增殖。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000899', 'source-doc-4c784a84a66adf221597', 'source-node-000896', '5', '898', 'text', '传播途径：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000900', 'source-doc-4c784a84a66adf221597', 'source-node-000899', '6', '899', 'text', '风雨传播：分生孢子借雨水飞溅至叶片、果实。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000901', 'source-doc-4c784a84a66adf221597', 'source-node-000899', '6', '900', 'text', '昆虫传播：害虫活动携带病菌。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000902', 'source-doc-4c784a84a66adf221597', 'source-node-000896', '5', '901', 'text', '传播机制：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000903', 'source-doc-4c784a84a66adf221597', 'source-node-000902', '6', '902', 'text', '虫媒传播：蚜虫飞行或随风迁移时，体表携带的真菌孢子可扩散至 50 米外。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000904', 'source-doc-4c784a84a66adf221597', 'source-node-000902', '6', '903', 'text', '农事传播：修剪工具接触带菌组织后，若未消毒直接使用，孢子附着率可达 83%。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000905', 'source-doc-4c784a84a66adf221597', 'source-node-000896', '5', '904', 'text', '症状分级标准：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000906', 'source-doc-4c784a84a66adf221597', 'source-node-000905', '6', '905', 'text', '轻度：霉层覆盖面积＜10%，叶片光合效率下降 15%-20%。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000907', 'source-doc-4c784a84a66adf221597', 'source-node-000905', '6', '906', 'text', '中度：霉层覆盖 10%-30%，果实糖度降低 1.5-2.0°Brix，落果率增加 10%-15%。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000908', 'source-doc-4c784a84a66adf221597', 'source-node-000905', '6', '907', 'text', '重度：霉层覆盖＞30%，叶片气孔堵塞率＞60%，树势衰退显著，果实商品率＜30%。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000909', 'source-doc-4c784a84a66adf221597', 'source-node-000896', '5', '908', 'text', '症状表现：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000910', 'source-doc-4c784a84a66adf221597', 'source-node-000909', '6', '909', 'text', '叶片：表面覆盖黑色绒毛状霉层，影响光合作用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000911', 'source-doc-4c784a84a66adf221597', 'source-node-000909', '6', '910', 'text', '果实：果面形成黑色斑块，降低商品价值。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000912', 'source-doc-4c784a84a66adf221597', 'source-node-000891', '4', '911', 'text', '预防方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000913', 'source-doc-4c784a84a66adf221597', 'source-node-000912', '5', '912', 'text', '农业措施：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000914', 'source-doc-4c784a84a66adf221597', 'source-node-000913', '6', '913', 'text', '修剪清园：剪除过密枝、下垂枝，改善通风透光条件。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000915', 'source-doc-4c784a84a66adf221597', 'source-node-000913', '6', '914', 'text', '虫害防控：重点防治蚜虫、粉虱、蚧壳虫，切断病菌营养源。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000916', 'source-doc-4c784a84a66adf221597', 'source-node-000912', '5', '915', 'text', '物理防治：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000917', 'source-doc-4c784a84a66adf221597', 'source-node-000916', '6', '916', 'text', '喷施矿物油（200 倍液）+ 毒死蜱（在蔬菜、果树、茶叶、中草药材上不得使用）（48% 乳油 1000 倍液），杀灭害虫并冲刷霉层。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000918', 'source-doc-4c784a84a66adf221597', 'source-node-000916', '6', '917', 'text', '黄板诱捕：每亩悬挂 20×30cm 黄板 15-20 块，悬挂高度高于树冠 30cm，当单日诱蚜量＞50 头时启动防治。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000919', 'source-doc-4c784a84a66adf221597', 'source-node-000916', '6', '918', 'text', '性信息素监测：使用含 E-β- 法尼烯的诱芯，结合物联网传感器，实现蚜虫迁飞期预警（准确率 91%）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000920', 'source-doc-4c784a84a66adf221597', 'source-node-000916', '6', '919', 'text', '生草栽培：行间种植藿香蓟（Ageratum conyzoides），其挥发物可使蚜虫趋避率达 65%，同时促进天敌瓢虫种群增长 3 倍。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000921', 'source-doc-4c784a84a66adf221597', 'source-node-000916', '6', '920', 'text', '营养调控：春梢期增施硅肥（水溶性硅酸钾 5kg / 亩），使叶片硅含量＞1.2%，可降低蚜虫取食频率 40%。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000922', 'source-doc-4c784a84a66adf221597', 'source-node-000916', '6', '921', 'text', '物理屏障设置：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000923', 'source-doc-4c784a84a66adf221597', 'source-node-000922', '7', '922', 'text', '果园周边种植 50 米宽的防风林带（如柠檬桉），可使蚜虫迁飞量减少 70%。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000924', 'source-doc-4c784a84a66adf221597', 'source-node-000922', '7', '923', 'text', '新梢期覆盖 40 目防虫网，可完全阻隔蚜虫侵入，但需配合通风系统避免高温胁迫。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000925', 'source-doc-4c784a84a66adf221597', 'source-node-000891', '4', '924', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000926', 'source-doc-4c784a84a66adf221597', 'source-node-000925', '5', '925', 'text', '化学防治（按效果排序）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000927', 'source-doc-4c784a84a66adf221597', 'source-node-000926', '6', '926', 'text', '蚜虫靶向药剂（按持效期排序）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000928', 'source-doc-4c784a84a66adf221597', 'source-node-000927', '7', '927', 'text', '螺虫乙酯 + 吡丙醚（24%+10% 悬浮剂）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000929', 'source-doc-4c784a84a66adf221597', 'source-node-000928', '8', '928', 'text', '作用机制：抑制蚜虫卵孵化（LC50=0.02mg/L）和若虫蜕皮，持效期 25-30 天。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000930', 'source-doc-4c784a84a66adf221597', 'source-node-000928', '8', '929', 'text', '使用技术：春梢萌芽期（芽长 2-5mm）喷施 4000 倍液，重点喷淋叶背，亩用水量 40-50L。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000931', 'source-doc-4c784a84a66adf221597', 'source-node-000927', '7', '930', 'text', '氟啶虫酰胺 + 联苯菊酯（10%+2.5% 水分散粒剂）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000932', 'source-doc-4c784a84a66adf221597', 'source-node-000931', '8', '931', 'text', '作用机制：阻断蚜虫取食行为（拒食率＞95%），兼具触杀和内吸活性，持效期 15-20 天。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000933', 'source-doc-4c784a84a66adf221597', 'source-node-000931', '8', '932', 'text', '使用技术：夏梢抽发期（梢长 5-10cm）喷施 3000 倍液，可兼治粉虱、蓟马。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000934', 'source-doc-4c784a84a66adf221597', 'source-node-000927', '7', '933', 'text', '吡虫啉 + 矿物油（10%+99% 乳油）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000935', 'source-doc-4c784a84a66adf221597', 'source-node-000934', '8', '934', 'text', '作用机制：矿物油封闭蚜虫气孔（窒息率＞90%），吡虫啉干扰神经系统，持效期 7-10 天。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000936', 'source-doc-4c784a84a66adf221597', 'source-node-000934', '8', '935', 'text', '使用技术：秋梢转绿期喷施 1500 倍 + 200 倍混合液，可清除叶片霉层 30%-50%。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000937', 'source-doc-4c784a84a66adf221597', 'source-node-000926', '6', '936', 'text', '治疗性杀菌剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000938', 'source-doc-4c784a84a66adf221597', 'source-node-000937', '7', '937', 'text', '真菌抑制药剂（按清除效率排序）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000939', 'source-doc-4c784a84a66adf221597', 'source-node-000938', '8', '938', 'text', '乙蒜素（80% 乳油）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000940', 'source-doc-4c784a84a66adf221597', 'source-node-000939', '9', '939', 'text', '作用机制：破坏真菌细胞膜硫键，对煤炱属菌丝抑制率＞95%，72 小时内霉层脱落率＞80%。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000941', 'source-doc-4c784a84a66adf221597', 'source-node-000939', '9', '940', 'text', '使用技术：发病初期喷施 1500 倍液，配合 0.1% 中性洗衣粉增强展着性，间隔 7 天再喷 1 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000942', 'source-doc-4c784a84a66adf221597', 'source-node-000938', '8', '941', 'text', '苯甲・嘧菌酯（32.5% 悬浮剂）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000943', 'source-doc-4c784a84a66adf221597', 'source-node-000942', '9', '942', 'text', '作用机制：抑制真菌线粒体呼吸链，促进叶片气孔开放（开放率提升 40%），持效期 15-20 天。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000944', 'source-doc-4c784a84a66adf221597', 'source-node-000942', '9', '943', 'text', '使用技术：果实膨大期喷施 1500 倍液，可兼防炭疽病、树脂病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000945', 'source-doc-4c784a84a66adf221597', 'source-node-000938', '8', '944', 'text', '春雷霉素 + 代森锰锌（2%+80% 可湿性粉剂）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000946', 'source-doc-4c784a84a66adf221597', 'source-node-000945', '9', '945', 'text', '作用机制：春雷霉素抑制蛋白质合成，代森锰锌提供锌元素增强抗病力，协同增效系数达 1.8。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000947', 'source-doc-4c784a84a66adf221597', 'source-node-000945', '9', '946', 'text', '使用技术：采果后清园喷施 600 倍液，可降低越冬菌源基数 70%。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000948', 'source-doc-4c784a84a66adf221597', 'source-node-000938', '8', '947', 'text', '甲基托布津（70% 可湿性粉剂 800 倍液）：内吸性强，分解霉层并抑制病菌繁殖。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000949', 'source-doc-4c784a84a66adf221597', 'source-node-000938', '8', '948', 'text', '多菌灵（50% 可湿性粉剂 600 倍液）：广谱抗菌，兼防炭疽病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000950', 'source-doc-4c784a84a66adf221597', 'source-node-000926', '6', '949', 'text', '保护性杀菌剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000951', 'source-doc-4c784a84a66adf221597', 'source-node-000950', '7', '950', 'text', '代森锰锌（80% 可湿性粉剂 600 倍液）：雨前喷施，预防病菌侵染。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000952', 'source-doc-4c784a84a66adf221597', 'source-node-000950', '7', '951', 'text', '波尔多液（1:1:100）：春梢期和幼果期使用，杀菌兼保护。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000953', 'source-doc-4c784a84a66adf221597', 'source-node-000926', '6', '952', 'text', '生物防治技术：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000954', 'source-doc-4c784a84a66adf221597', 'source-node-000953', '7', '953', 'text', '球孢白僵菌（100 亿 CFU/g）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000955', 'source-doc-4c784a84a66adf221597', 'source-node-000954', '8', '954', 'text', '作用机制：孢子萌发产生芽管穿透蚜虫体壁，致死率＞85%，同时分泌几丁质酶分解真菌细胞壁。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000956', 'source-doc-4c784a84a66adf221597', 'source-node-000954', '8', '955', 'text', '使用技术：蚜虫发生初期喷施 200 倍液，配合 0.05% 红糖液增强孢子黏附性，持效期 10-15 天。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000957', 'source-doc-4c784a84a66adf221597', 'source-node-000953', '7', '956', 'text', '蚜茧蜂（Aphidius colemani）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000958', 'source-doc-4c784a84a66adf221597', 'source-node-000957', '8', '957', 'text', '作用机制：单雌产卵量 80-120 粒，寄生率＞60%，释放量 2000 头 / 亩，间隔 10 天释放 1 次，连续 3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000959', 'source-doc-4c784a84a66adf221597', 'source-node-000926', '6', '958', 'text', '复配药剂与轮换：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000960', 'source-doc-4c784a84a66adf221597', 'source-node-000959', '7', '959', 'text', '苯甲・嘧菌酯（32.5% 悬浮剂 1500 倍液）：内吸 + 保护，对煤烟病和树脂病双重防控。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000961', 'source-doc-4c784a84a66adf221597', 'source-node-000959', '7', '960', 'text', '轮换策略：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000962', 'source-doc-4c784a84a66adf221597', 'source-node-000961', '8', '961', 'text', '蚜虫防治：新烟碱类（吡虫啉）→吡啶类（氟啶虫酰胺）→季酮酸类（螺虫乙酯）→微生物制剂（球孢白僵菌），每季度轮换 2-3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000963', 'source-doc-4c784a84a66adf221597', 'source-node-000961', '8', '962', 'text', '真菌防治：甲氧基丙烯酸酯类（嘧菌酯）→三唑类（苯醚甲环唑）→有机硫类（代森锰锌）→生物源农药（春雷霉素），避免连续使用同一作用机理药剂。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000964', 'source-doc-4c784a84a66adf221597', 'source-node-000959', '7', '963', 'text', '增效技术：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000965', 'source-doc-4c784a84a66adf221597', 'source-node-000964', '8', '964', 'text', '纳米载体：负载螺虫乙酯的介孔二氧化硅纳米颗粒（粒径 50-80nm），可使药剂持效期延长至 45 天，用量减少 50%。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000966', 'source-doc-4c784a84a66adf221597', 'source-node-000964', '8', '965', 'text', '光活化农药：添加 0.01% 的卟啉类光敏剂，可使乙蒜素对真菌的抑制率提升 30%。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000967', 'source-doc-4c784a84a66adf221597', 'source-node-000926', '6', '966', 'text', '区域性方案：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000968', 'source-doc-4c784a84a66adf221597', 'source-node-000967', '7', '967', 'text', '华南湿热产区（广东、广西）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000969', 'source-doc-4c784a84a66adf221597', 'source-node-000968', '8', '968', 'text', '春梢期（3-4 月）：螺虫乙酯 + 吡丙醚 4000 倍液防治蚜虫，配合苯甲・嘧菌酯 1500 倍液预防真菌。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000970', 'source-doc-4c784a84a66adf221597', 'source-node-000968', '8', '969', 'text', '夏梢期（6-7 月）：氟啶虫酰胺 + 联苯菊酯 3000 倍液控制蚜虫，乙蒜素 1500 倍液清除霉层。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000971', 'source-doc-4c784a84a66adf221597', 'source-node-000968', '8', '970', 'text', '秋梢期（9-10 月）：吡虫啉 + 矿物油 1500+200 倍液，兼治蚜虫和煤烟病，采果后喷施春雷霉素 + 代森锰锌清园。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000972', 'source-doc-4c784a84a66adf221597', 'source-node-000967', '7', '971', 'text', '华中丘陵产区（江西、湖南）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000973', 'source-doc-4c784a84a66adf221597', 'source-node-000972', '8', '972', 'text', '煤烟病：重点防治蚜虫（噻虫嗪 5000 倍液）+ 喷施甲基托布津 800 倍液，结合矿物油冲刷霉层。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000974', 'source-doc-4c784a84a66adf221597', 'source-node-000972', '8', '973', 'text', '春梢期：球孢白僵菌 200 倍液 + 蚜茧蜂释放，降低化学药剂依赖。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000975', 'source-doc-4c784a84a66adf221597', 'source-node-000972', '8', '974', 'text', '夏梢期：氟啶虫酰胺 + 联苯菊酯 3000 倍液，配合 0.3% 磷酸二氢钾增强树势。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000976', 'source-doc-4c784a84a66adf221597', 'source-node-000972', '8', '975', 'text', '秋梢期：乙蒜素 1500 倍液 + 0.1% 中性洗衣粉，重点喷施内膛郁闭枝。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000977', 'source-doc-4c784a84a66adf221597', 'source-node-000700', '3', '976', 'text', '柑橘白粉病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000978', 'source-doc-4c784a84a66adf221597', 'source-node-000977', '4', '977', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000979', 'source-doc-4c784a84a66adf221597', 'source-node-000978', '5', '978', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000980', 'source-doc-4c784a84a66adf221597', 'source-node-000977', '4', '979', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000981', 'source-doc-4c784a84a66adf221597', 'source-node-000980', '5', '980', 'text', '主要为害嫩叶、新梢和幼果：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000982', 'source-doc-4c784a84a66adf221597', 'source-node-000980', '5', '981', 'text', '嫩叶：正背面（正面居多）产生近圆形疏松白粉状霉层，后期转为浅灰褐色；霉层下叶片初呈水渍状深暗，渐成黄斑，严重时枯萎扭曲。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000983', 'source-doc-4c784a84a66adf221597', 'source-node-000980', '5', '982', 'text', '新梢：覆盖白粉状菌丝层，叶片干缩贴附，重者枯死。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000984', 'source-doc-4c784a84a66adf221597', 'source-node-000980', '5', '983', 'text', '幼果：初期有白粉层，无明显黄斑，霉层扩展后覆盖表面', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000985', 'source-doc-4c784a84a66adf221597', 'source-node-000977', '4', '984', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000986', 'source-doc-4c784a84a66adf221597', 'source-node-000985', '5', '985', 'text', '病原菌为丹吉尔粉孢霉（Oidiumtingitaninum），属真菌界无性态子囊菌；菌丝白色半透明，附着胞圆形，分生孢子4~8个串生、无色', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000987', 'source-doc-4c784a84a66adf221597', 'source-node-000977', '4', '986', 'text', '发病规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000988', 'source-doc-4c784a84a66adf221597', 'source-node-000987', '5', '987', 'text', '温湿度：适温20~28℃，高湿+通风不良时爆发，春末夏初为主高峰410。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000989', 'source-doc-4c784a84a66adf221597', 'source-node-000987', '5', '988', 'text', '病菌以菌丝体在病组织越冬；翌年4~5月春梢抽长期产生分生孢子，借风雨传播，水滴中萌发侵染，重复为害春、夏、秋梢；适温18~23℃，多雨潮湿易流行；甜橙、温州蜜柑中晚熟品种等易感病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000990', 'source-doc-4c784a84a66adf221597', 'source-node-000977', '4', '989', 'text', '预防方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000991', 'source-doc-4c784a84a66adf221597', 'source-node-000990', '5', '990', 'text', '品种选择：纽荷尔脐橙、温州蜜柑等抗病品种4。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000992', 'source-doc-4c784a84a66adf221597', 'source-node-000990', '5', '991', 'text', '控湿修剪：疏除密枝，保持透光率＞30%，排水降湿10。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000993', 'source-doc-4c784a84a66adf221597', 'source-node-000990', '5', '992', 'text', '农业防治：剪除病枝梢、叶、果集中烧毁，合理修剪增强果园通透性。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000994', 'source-doc-4c784a84a66adf221597', 'source-node-000977', '4', '993', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000995', 'source-doc-4c784a84a66adf221597', 'source-node-000994', '5', '994', 'text', '关键期：春梢萌发期、发病初期（粉斑未扩散时）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000996', 'source-doc-4c784a84a66adf221597', 'source-node-000994', '5', '995', 'text', '药剂选择：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000997', 'source-doc-4c784a84a66adf221597', 'source-node-000996', '6', '996', 'text', '冬季喷1波石硫合剂清园；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000998', 'source-doc-4c784a84a66adf221597', 'source-node-000996', '6', '997', 'text', '春梢抽发期/发病初期：喷石硫合剂、50%硫黄悬浮剂400倍液、50%甲基硫菌灵可湿性粉剂1000倍液；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-000999', 'source-doc-4c784a84a66adf221597', 'source-node-000996', '6', '998', 'text', '嫩梢抽发3~6cm时：喷50%锰锌・腈菌唑可湿性粉剂600倍液等。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001000', 'source-doc-4c784a84a66adf221597', 'source-node-000994', '5', '999', 'text', '药剂​使用浓度​优势25%吡唑醚菌酯​2000倍​提升叶绿素，延缓衰老三唑酮​1500倍​速效性强，3天控粉层​腈菌唑​4000倍​内吸传导，持效期长​枯草芽孢杆菌​1000倍​生物防治，花期安全', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001001', 'source-doc-4c784a84a66adf221597', 'source-node-000994', '5', '1000', 'text', '避免高温时喷三唑酮（防药害），生物制剂需提前7天使用', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001002', 'source-doc-4c784a84a66adf221597', 'source-node-000700', '3', '1001', 'text', '柑橘棒孢霉褐斑病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001003', 'source-doc-4c784a84a66adf221597', 'source-node-001002', '4', '1002', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001004', 'source-doc-4c784a84a66adf221597', 'source-node-001003', '5', '1003', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001005', 'source-doc-4c784a84a66adf221597', 'source-node-001002', '4', '1004', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001006', 'source-doc-4c784a84a66adf221597', 'source-node-001005', '5', '1005', 'text', '又称柑橘褐斑病、柑橘棒孢霉叶斑病、柑橘棒孢霉斑病。病害主要发生在叶上，也侵染当年生成熟嫩梢和果实。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001007', 'source-doc-4c784a84a66adf221597', 'source-node-001005', '5', '1006', 'text', '症状表现：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001008', 'source-doc-4c784a84a66adf221597', 'source-node-001007', '6', '1007', 'text', '叶片：初期褐色圆形病斑，边缘隆起，中央凹陷，周围有黄色晕圈。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001009', 'source-doc-4c784a84a66adf221597', 'source-node-001007', '6', '1008', 'text', '果实：幼果期出现油渍状斑点，后期病斑木栓化。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001010', 'source-doc-4c784a84a66adf221597', 'source-node-001005', '5', '1009', 'text', '叶片病斑：圆形或不正圆形，大小 3～17mm，一般 5～8mm。发病初期叶面散生浅色小圆点，后渐扩大，形成穿透叶两面、边缘略隆起深褐色、中部凹陷黄褐至灰褐色的典型病斑，外缘具明显黄色晕环。一张叶上常出现病斑一至数个，少数叶多达十余个。天气潮湿多雨时，病部长出黄褐色霉丛（病原分生孢子梗和孢子），病部黑腐霉烂；气温高时，叶渐卷曲，重病叶大量焦枯脱落。因品种不同，症状表现程度有差异。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001011', 'source-doc-4c784a84a66adf221597', 'source-node-001005', '5', '1010', 'text', '果实和梢部病斑：近圆形，褐色内凹，大小 2～4mm，外缘微隆起，周围无明显黄色晕圈。果上病斑较光滑，木栓化龟裂程度小或不裂开，隆起度无溃疡病斑突出，中部凹区较宽坦。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001012', 'source-doc-4c784a84a66adf221597', 'source-node-001002', '4', '1011', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001013', 'source-doc-4c784a84a66adf221597', 'source-node-001012', '5', '1012', 'text', 'Corynespora citricola，属真菌界无性态子囊菌。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001014', 'source-doc-4c784a84a66adf221597', 'source-node-001012', '5', '1013', 'text', '分生孢子梗丛生于子座上，子座由假柔膜组织融结成，不规则圆形或球形，深褐色，大小 30～90μm。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001015', 'source-doc-4c784a84a66adf221597', 'source-node-001012', '5', '1014', 'text', '孢子梗顶端孔生出分生孢子，分生孢子脱落后孢梗之端部另长出一小节再孔生出孢子；在 PDA 培养基上菌丝埋生于基物内，外生菌丝分枝多。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001016', 'source-doc-4c784a84a66adf221597', 'source-node-001002', '4', '1015', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001017', 'source-doc-4c784a84a66adf221597', 'source-node-001016', '5', '1016', 'text', '越冬与侵染：病菌以菌丝体或分生孢子梗在坏死组织越冬，暖热地区分生孢子也可越冬。次年春季从叶面气孔侵入繁殖，8~9 月出现大量病斑，新病斑产生分生孢子重复侵染，叶内潜育或形成小病斑越冬，翌年 4~5 月再次形成为害高峰。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001018', 'source-doc-4c784a84a66adf221597', 'source-node-001016', '5', '1017', 'text', '发病影响因素：干燥气候发病轻，雨日多、橘园通风透光差、修剪不好则发病重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001019', 'source-doc-4c784a84a66adf221597', 'source-node-001016', '5', '1018', 'text', '品种与树龄差异：常见品种均会被侵染，橙类发病相对较重，橘类次之，柚类偶见；老年树重于幼树，春梢及成熟叶片重于夏、秋梢和嫩叶。一般不会造成严重灾害，但需关注监测。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001020', 'source-doc-4c784a84a66adf221597', 'source-node-001016', '5', '1019', 'text', '传播途径：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001021', 'source-doc-4c784a84a66adf221597', 'source-node-001020', '6', '1020', 'text', '风雨传播：雨水飞溅是主要传播方式，病菌可随气流扩散至邻近果园。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001022', 'source-doc-4c784a84a66adf221597', 'source-node-001020', '6', '1021', 'text', '农事操作：修剪工具、采摘人员接触带菌组织后传播。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001023', 'source-doc-4c784a84a66adf221597', 'source-node-001002', '4', '1022', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001024', 'source-doc-4c784a84a66adf221597', 'source-node-001023', '5', '1023', 'text', '一、农业防治（基础预防，减少病源）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001025', 'source-doc-4c784a84a66adf221597', 'source-node-001024', '6', '1024', 'text', '核心是通过田间管理培育壮树，从根本提升柑橘自身抗病能力，具体措施如下：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001026', 'source-doc-4c784a84a66adf221597', 'source-node-001024', '6', '1025', 'text', '日常管理：科学用水用肥，合理修剪枝条，保持橘园通风透光，避免病菌滋生环境。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001027', 'source-doc-4c784a84a66adf221597', 'source-node-001024', '6', '1026', 'text', '冬季清园：彻底清理园内病枝、落叶和残果，减少越冬的病菌与虫卵基数。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001028', 'source-doc-4c784a84a66adf221597', 'source-node-001024', '6', '1027', 'text', '土壤与排灌：增施有机质肥改善土壤肥力，同时疏通排灌系统，避免园内积水诱发病害。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001029', 'source-doc-4c784a84a66adf221597', 'source-node-001024', '6', '1028', 'text', '重病园处理：若果园病害严重，可采取高接换种或直接改种抗病品种的方式，从源头解决问题。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001030', 'source-doc-4c784a84a66adf221597', 'source-node-001023', '5', '1029', 'text', '二、化学防治（针对性控病，分药剂类型）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001031', 'source-doc-4c784a84a66adf221597', 'source-node-001030', '6', '1030', 'text', '1. 保护性杀菌剂（以预防为主，提前建立防护）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001032', 'source-doc-4c784a84a66adf221597', 'source-node-001031', '7', '1031', 'text', '80% 代森锰锌可湿性粉剂：使用浓度为 600 倍液，需在雨前喷施，能在叶片表面形成保护膜，持效期 10-15 天，还可兼防多种真菌病害。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001033', 'source-doc-4c784a84a66adf221597', 'source-node-001031', '7', '1032', 'text', '70% 丙森锌可湿性粉剂：使用浓度为 500 倍液，适合幼果期使用，其中的锌离子能增强叶片自身抗病力。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001034', 'source-doc-4c784a84a66adf221597', 'source-node-001030', '6', '1033', 'text', '2. 内吸性药剂（发病初期使用，侧重治疗）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001035', 'source-doc-4c784a84a66adf221597', 'source-node-001034', '7', '1034', 'text', '2% 春雷霉素水剂 + 77% 氢氧化铜可湿性粉剂：需在发病初期喷施，兼具内吸治疗和表面保护双重作用，对病害的防效可达 85% 以上。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001036', 'source-doc-4c784a84a66adf221597', 'source-node-001030', '6', '1035', 'text', '3. 其他推荐药剂（发病初期可选，按需使用）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001037', 'source-doc-4c784a84a66adf221597', 'source-node-001036', '7', '1036', 'text', '50% 异菌脲可湿性粉剂：1000 倍液，发病初期喷洒。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001038', 'source-doc-4c784a84a66adf221597', 'source-node-001036', '7', '1037', 'text', '60% 唑醚・代森联水分散粒剂：1000 倍液，发病初期喷洒。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001039', 'source-doc-4c784a84a66adf221597', 'source-node-001036', '7', '1038', 'text', '60% 戊唑醇・丙森锌可湿性粉剂：1500 倍液，发病初期喷洒。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001040', 'source-doc-4c784a84a66adf221597', 'source-node-001036', '7', '1039', 'text', '75% 肟菌・戊唑醇水分散粒剂：3000 倍液，发病初期喷洒。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001041', 'source-doc-4c784a84a66adf221597', 'source-node-001036', '7', '1040', 'text', '45% 咪鲜胺微乳剂：1000-1200 倍液，发病期使用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001042', 'source-doc-4c784a84a66adf221597', 'source-node-001036', '7', '1041', 'text', '10% 苯醚甲环唑水分散粒剂：按产品说明稀释，发病期使用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001043', 'source-doc-4c784a84a66adf221597', 'source-node-001036', '7', '1042', 'text', '80% 大生 M-45 可湿性粉剂：500-600 倍液，发病期使用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001044', 'source-doc-4c784a84a66adf221597', 'source-node-001036', '7', '1043', 'text', '25% 戊唑醇水乳剂 + 70% 丙森锌可湿性粉剂：前者 1000-1500 倍液与后者 600-800 倍液混合使用，可增强防效。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001045', 'source-doc-4c784a84a66adf221597', 'source-node-001036', '7', '1044', 'text', '25% 吡唑醚菌酯：1000-1500 倍液，发病期使用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001046', 'source-doc-4c784a84a66adf221597', 'source-node-001030', '6', '1045', 'text', '4. 喷药关键注意事项（核心原则，必须遵守）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001047', 'source-doc-4c784a84a66adf221597', 'source-node-001046', '7', '1046', 'text', '及时喷药：感病品种在春芽显露 0.5~1cm 时喷第一次药，间隔 7~10 天喷第二次；下雨前后需抓紧补喷，避免雨水冲刷降低药效。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001048', 'source-doc-4c784a84a66adf221597', 'source-node-001046', '7', '1047', 'text', '选准药剂：优先选择上述针对性药剂，不使用无效或低效药剂，避免浪费成本且延误防治时机。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001049', 'source-doc-4c784a84a66adf221597', 'source-node-001046', '7', '1048', 'text', '轮换与混合：不同类型药剂需轮换使用（防止病菌产生耐药性），必要时按说明混合使用（如戊唑醇搭配丙森锌），进一步提升防效。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001050', 'source-doc-4c784a84a66adf221597', 'source-node-001023', '5', '1049', 'text', '三、生物防治（绿色防控，减少化学药用量）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001051', 'source-doc-4c784a84a66adf221597', 'source-node-001050', '6', '1050', 'text', '核心采用特异性微生物制剂，安全环保且能降低农药残留：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001052', 'source-doc-4c784a84a66adf221597', 'source-node-001050', '6', '1051', 'text', '使用药剂：实验室筛选的特异性噬菌体 BBS-01。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001053', 'source-doc-4c784a84a66adf221597', 'source-node-001050', '6', '1052', 'text', '实际效果：田间试验显示，对斑点病菌的裂解率达 92%，可替代 30% 的化学药剂，适合绿色柑橘种植需求。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001054', 'source-doc-4c784a84a66adf221597', 'source-node-001023', '5', '1053', 'text', '四、虫害防治（减少伤口，降低病菌入侵机会）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001055', 'source-doc-4c784a84a66adf221597', 'source-node-001054', '6', '1054', 'text', '1. 主要防治对象', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001056', 'source-doc-4c784a84a66adf221597', 'source-node-001055', '7', '1055', 'text', '核心防控对象：潜叶蛾、蓟马（二者易啃食新梢，造成伤口，为病菌入侵提供通道）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001057', 'source-doc-4c784a84a66adf221597', 'source-node-001055', '7', '1056', 'text', '兼顾防治对象：矢尖介壳虫、柑橘红蜘蛛（二者会削弱树势，间接降低柑橘自身抗病能力）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001058', 'source-doc-4c784a84a66adf221597', 'source-node-001054', '6', '1057', 'text', '2. 推荐用药与使用时期', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001059', 'source-doc-4c784a84a66adf221597', 'source-node-001058', '7', '1058', 'text', '用药方案：25% 噻虫嗪水分散粒剂 5000 倍液 + 1.8% 阿维菌素乳油 1500 倍液（两种药剂混合使用，可扩大杀虫范围，同时防控多种害虫）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001060', 'source-doc-4c784a84a66adf221597', 'source-node-001058', '7', '1059', 'text', '使用时期：需在柑橘新梢抽发期喷施，此时是潜叶蛾、蓟马的活跃高峰期，防控效果最佳。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001061', 'source-doc-4c784a84a66adf221597', 'source-node-000700', '3', '1060', 'text', '柑橘灰霉病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001062', 'source-doc-4c784a84a66adf221597', 'source-node-001061', '4', '1061', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001063', 'source-doc-4c784a84a66adf221597', 'source-node-001062', '5', '1062', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001064', 'source-doc-4c784a84a66adf221597', 'source-node-001061', '4', '1063', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001065', 'source-doc-4c784a84a66adf221597', 'source-node-001064', '5', '1064', 'text', '花期：阴雨天花瓣现水渍状小圆点，后腐烂长灰黄色霉层，干燥时呈淡褐色干腐状。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001066', 'source-doc-4c784a84a66adf221597', 'source-node-001064', '5', '1065', 'text', '嫩叶：水渍状腐烂斑块，干燥后半透明淡黄褐色。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001067', 'source-doc-4c784a84a66adf221597', 'source-node-001064', '5', '1066', 'text', '幼果：病斑不规则易脱落，未脱落者木栓化形成"花斑果“', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001068', 'source-doc-4c784a84a66adf221597', 'source-node-001064', '5', '1067', 'text', '成熟果：发病部位褐色变软，生鼠灰色霉层，失水后干枯变硬有霉味', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001069', 'source-doc-4c784a84a66adf221597', 'source-node-001061', '4', '1068', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001070', 'source-doc-4c784a84a66adf221597', 'source-node-001069', '5', '1069', 'text', '病原菌为灰葡萄孢霉，属半知菌亚门丝孢纲真菌，病部霉层为分生孢子梗和分生孢子', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001071', 'source-doc-4c784a84a66adf221597', 'source-node-001061', '4', '1070', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001072', 'source-doc-4c784a84a66adf221597', 'source-node-001071', '5', '1071', 'text', '越冬：以菌核和分生孢子在病残体、土壤中越冬。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001073', 'source-doc-4c784a84a66adf221597', 'source-node-001071', '5', '1072', 'text', '传播：春季温湿度适宜时萌发，借风雨气流传播，病花产生分生孢子再侵染。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001074', 'source-doc-4c784a84a66adf221597', 'source-node-001071', '5', '1073', 'text', '发病条件：开花期/幼果期降雨多（尤其花期下雨）发病重；低温潮湿（20-24℃适宜菌丝发育）、果园荫蔽通风差易发病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001075', 'source-doc-4c784a84a66adf221597', 'source-node-001061', '4', '1074', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001076', 'source-doc-4c784a84a66adf221597', 'source-node-001075', '5', '1075', 'text', '冬季清园：清除枯枝落叶，冬剪后喷45%石硫合剂晶体50-100倍液。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001077', 'source-doc-4c784a84a66adf221597', 'source-node-001075', '5', '1076', 'text', '及时摇花：花期遇雨摇花，促进花瓣脱落减少侵染。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001078', 'source-doc-4c784a84a66adf221597', 'source-node-001075', '5', '1077', 'text', '药剂防治：适期为萌芽期、开花前、谢花后、幼果期，可用80%代森锰锌+25%异菌脲等配方喷雾，每个适期喷1-2次；或用50%腐霉利可湿性粉剂、嘧菌环胺、啶酰菌胺、噻菌铜等', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001079', 'source-doc-4c784a84a66adf221597', 'source-node-000700', '3', '1078', 'text', '柑橘疫霉果腐病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001080', 'source-doc-4c784a84a66adf221597', 'source-node-001079', '4', '1079', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001081', 'source-doc-4c784a84a66adf221597', 'source-node-001080', '5', '1080', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001082', 'source-doc-4c784a84a66adf221597', 'source-node-001079', '4', '1081', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001083', 'source-doc-4c784a84a66adf221597', 'source-node-001082', '5', '1082', 'text', '果实：近地面果实先发病，初为淡灰色圆斑，逐渐变暗，不凹陷、革质有韧性，指压不破；软腐后有刺鼻味道，高温高湿时病部生稀疏白霉层。或表皮出现污褐色至褐灰色圆形斑，迅速蔓延全果，有强烈皂臭味；干燥时质地坚韧，高温时长白色绒毛菌丝', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001084', 'source-doc-4c784a84a66adf221597', 'source-node-001082', '5', '1083', 'text', '树体：发病轻时叶色黄化、果实早黄皮厚；严重时枝干叶脉褪绿呈黄褐色，叶黄落、枝干枯，开花多落果早，残留果小早黄味酸苦；病斑环绕枝干则植株越冬后死亡。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001085', 'source-doc-4c784a84a66adf221597', 'source-node-001082', '5', '1084', 'text', '叶片：受害生浅色水渍状圆形斑，伴白色稀疏菌丝', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001086', 'source-doc-4c784a84a66adf221597', 'source-node-001079', '4', '1085', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001087', 'source-doc-4c784a84a66adf221597', 'source-node-001086', '5', '1086', 'text', '由多种疫霉菌引起，主要包括柑橘褐腐疫霉（Phytophthoracitriophthora）等，国内报道分离的病原真菌共12种，以前5种（腐皮镰孢、寄生疫霉、柑橘褐腐疫霉、德氏腐霉、逸见腐霉）最常见且为害重', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001088', 'source-doc-4c784a84a66adf221597', 'source-node-001079', '4', '1087', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001089', 'source-doc-4c784a84a66adf221597', 'source-node-001088', '5', '1088', 'text', '越冬：疫霉菌以菌丝体、厚垣孢子或卵孢子，镰孢霉菌以菌丝体或厚垣孢子在根颈部病组织或土壤病残体中越冬。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001090', 'source-doc-4c784a84a66adf221597', 'source-node-001088', '5', '1089', 'text', '传播：雨水传播孢子囊/游动孢子（疫霉）或分生孢子（镰孢霉），从伤口或衰弱处侵入根颈部或近地面果实；贮运期病果可接触传病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001091', 'source-doc-4c784a84a66adf221597', 'source-node-001088', '5', '1090', 'text', '发病条件：结果期阴雨连绵、偏施氮肥、树冠下部果实病重；越成熟果实越易感病；高温高湿（雨后暴晴）利于发病；地窖贮藏较通风库病重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001092', 'source-doc-4c784a84a66adf221597', 'source-node-001079', '4', '1091', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001093', 'source-doc-4c784a84a66adf221597', 'source-node-001092', '5', '1092', 'text', '农业防治：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001094', 'source-doc-4c784a84a66adf221597', 'source-node-001093', '6', '1093', 'text', '用枳、枸头橙等抗病砧木，提高嫁接口；避免甜橙/红橘作砧木（高水位/密植园）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001095', 'source-doc-4c784a84a66adf221597', 'source-node-001093', '6', '1094', 'text', '清园除病果，贮藏初期剔烂果。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001096', 'source-doc-4c784a84a66adf221597', 'source-node-001093', '6', '1095', 'text', '开沟排水，忌间种高秆作物；定植不深（嫁接口外露），增施有机肥，防树干受伤；及时治天牛。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001097', 'source-doc-4c784a84a66adf221597', 'source-node-001092', '5', '1096', 'text', '药剂防治：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001098', 'source-doc-4c784a84a66adf221597', 'source-node-001097', '6', '1097', 'text', '采收前1个月喷25%甲霜灵500倍液2次；采收后用25%甲霜灵600倍液或80%代森锰锌600-800倍液处理。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001099', 'source-doc-4c784a84a66adf221597', 'source-node-001097', '6', '1098', 'text', '病树刮除病组织（加0.5-1.0cm健康组织），涂1:1:10波尔多液/3%硫酸铜液/25%甲霜灵500倍液，包扎；重病树靠接抗病实生苗。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001100', 'source-doc-4c784a84a66adf221597', 'source-node-000546', '2', '1099', 'text', '柑橘其他病害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001101', 'source-doc-4c784a84a66adf221597', 'source-node-001100', '3', '1100', 'text', '柑橘黄脉病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001102', 'source-doc-4c784a84a66adf221597', 'source-node-001101', '4', '1101', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001103', 'source-doc-4c784a84a66adf221597', 'source-node-001101', '4', '1102', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001104', 'source-doc-4c784a84a66adf221597', 'source-node-001103', '5', '1103', 'text', '各梢期叶片叶脉发黄（鲜黄/明黄），可扩展至附近组织；嫩叶脉似水渍状，春梢下端叶脱落，叶片皱缩反卷畸形。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001105', 'source-doc-4c784a84a66adf221597', 'source-node-001100', '3', '1104', 'text', '柑橘裂皮病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001106', 'source-doc-4c784a84a66adf221597', 'source-node-001105', '4', '1105', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001107', 'source-doc-4c784a84a66adf221597', 'source-node-001106', '5', '1106', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001108', 'source-doc-4c784a84a66adf221597', 'source-node-001105', '4', '1107', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001109', 'source-doc-4c784a84a66adf221597', 'source-node-001108', '5', '1108', 'text', '砧木树皮纵向裂开、翘起剥落，木质部外露；树冠矮化，新梢纤细，叶片小畸形、叶脉附近绿叶肉黄化。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001110', 'source-doc-4c784a84a66adf221597', 'source-node-001100', '3', '1109', 'text', '柑橘衰退病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001111', 'source-doc-4c784a84a66adf221597', 'source-node-001110', '4', '1110', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001112', 'source-doc-4c784a84a66adf221597', 'source-node-001111', '5', '1111', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001113', 'source-doc-4c784a84a66adf221597', 'source-node-001110', '4', '1112', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001114', 'source-doc-4c784a84a66adf221597', 'source-node-001113', '5', '1113', 'text', '树势衰退，新梢短弱，叶片黄化脱落；严重时植株死亡', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001115', 'source-doc-4c784a84a66adf221597', 'source-node-001100', '3', '1114', 'text', '柑橘酸腐病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001116', 'source-doc-4c784a84a66adf221597', 'source-node-001115', '4', '1115', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001117', 'source-doc-4c784a84a66adf221597', 'source-node-001116', '5', '1116', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001118', 'source-doc-4c784a84a66adf221597', 'source-node-001115', '4', '1117', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001119', 'source-doc-4c784a84a66adf221597', 'source-node-001118', '5', '1118', 'text', '初期病果表面形成水渍状淡黄色至黄褐色圆形病斑，果皮软化易破，后期产生白色霉层并散发酸臭气味', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001120', 'source-doc-4c784a84a66adf221597', 'source-node-001100', '3', '1119', 'text', '柑橘黑腐病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001121', 'source-doc-4c784a84a66adf221597', 'source-node-001120', '4', '1120', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001122', 'source-doc-4c784a84a66adf221597', 'source-node-001121', '5', '1121', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001123', 'source-doc-4c784a84a66adf221597', 'source-node-001120', '4', '1122', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001124', 'source-doc-4c784a84a66adf221597', 'source-node-001123', '5', '1123', 'text', '一种是果脐部附近的果皮先发病，初时果皮上出现水渍状淡褐色病斑，病部扩大后稍凹陷，', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001125', 'source-doc-4c784a84a66adf221597', 'source-node-001123', '5', '1124', 'text', '另一种是果实外表不呈现症状，而果肉腐烂，果心内部长满墨绿色绒状霉。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001126', 'source-doc-4c784a84a66adf221597', 'source-node-001100', '3', '1125', 'text', '柑橘苗疫病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001127', 'source-doc-4c784a84a66adf221597', 'source-node-001126', '4', '1126', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001128', 'source-doc-4c784a84a66adf221597', 'source-node-001126', '4', '1127', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001129', 'source-doc-4c784a84a66adf221597', 'source-node-001128', '5', '1128', 'text', '幼苗嫩梢似开水烫伤状，后生橘红色小液点；苗圃低洼排水不良易发病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001130', 'source-doc-4c784a84a66adf221597', 'source-node-001100', '3', '1129', 'text', '柑橘水纹病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001131', 'source-doc-4c784a84a66adf221597', 'source-node-001130', '4', '1130', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001132', 'source-doc-4c784a84a66adf221597', 'source-node-001131', '5', '1131', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001133', 'source-doc-4c784a84a66adf221597', 'source-node-001130', '4', '1132', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001134', 'source-doc-4c784a84a66adf221597', 'source-node-001133', '5', '1133', 'text', '加强果园管理，增施有机肥及钾钙肥，均衡水分养分；7-8月傍晚/晨露干后喷20mg/kg赤霉素；7月喷2次2%硝酸钾；适时采果避免超期', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001135', 'source-doc-4c784a84a66adf221597', 'source-node-001100', '3', '1134', 'text', '柑橘根结线虫', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001136', 'source-doc-4c784a84a66adf221597', 'source-node-001135', '4', '1135', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001137', 'source-doc-4c784a84a66adf221597', 'source-node-001135', '4', '1136', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001138', 'source-doc-4c784a84a66adf221597', 'source-node-000546', '2', '1137', 'text', '柑橘病毒病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001139', 'source-doc-4c784a84a66adf221597', 'source-node-001138', '3', '1138', 'text', '柑橘碎叶病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001140', 'source-doc-4c784a84a66adf221597', 'source-node-001139', '4', '1139', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001141', 'source-doc-4c784a84a66adf221597', 'source-node-001140', '5', '1140', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001142', 'source-doc-4c784a84a66adf221597', 'source-node-001139', '4', '1141', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001143', 'source-doc-4c784a84a66adf221597', 'source-node-001142', '5', '1142', 'text', '砧穗接合部：接穗基部肿大，愈合口木质部黄褐色环缢，受外力易断裂（裂面光滑）；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001144', 'source-doc-4c784a84a66adf221597', 'source-node-001142', '5', '1143', 'text', '植株：矮化衰弱，后期叶片叶脉黄化脱落，严重全株枯死；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001145', 'source-doc-4c784a84a66adf221597', 'source-node-001142', '5', '1144', 'text', '指示植物：叶片缺刻似“碎叶”，叶面凹凸不平、有不规则黄斑。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001146', 'source-doc-4c784a84a66adf221597', 'source-node-001139', '4', '1145', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001147', 'source-doc-4c784a84a66adf221597', 'source-node-001146', '5', '1146', 'text', '由发形病毒属的柑橘碎叶病毒（CTLV）引起，病毒粒子呈长丝状。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001148', 'source-doc-4c784a84a66adf221597', 'source-node-001139', '4', '1147', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001149', 'source-doc-4c784a84a66adf221597', 'source-node-001148', '5', '1148', 'text', '传播：主要通过嫁接和污染的刀剪机械传播，未发现昆虫传毒；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001150', 'source-doc-4c784a84a66adf221597', 'source-node-001148', '5', '1149', 'text', '寄主：以枳及其杂种作砧木的柑橘树易感病，部分品种带毒隐症', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001151', 'source-doc-4c784a84a66adf221597', 'source-node-001139', '4', '1150', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001152', 'source-doc-4c784a84a66adf221597', 'source-node-001151', '5', '1151', 'text', '培育无病苗：选用无病母树，或热处理（白天40℃16h/夜间30℃8h，2-3个月）+茎尖嫁接脱毒；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001153', 'source-doc-4c784a84a66adf221597', 'source-node-001151', '5', '1152', 'text', '工具消毒：用1%次氯酸钠或20%漂白粉液消毒刀剪；严格检疫，及时挖除病树', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001154', 'source-doc-4c784a84a66adf221597', 'source-node-000546', '2', '1153', 'text', '生理病害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001155', 'source-doc-4c784a84a66adf221597', 'source-node-001154', '3', '1154', 'text', '柑橘日灼病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001156', 'source-doc-4c784a84a66adf221597', 'source-node-001155', '4', '1155', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001157', 'source-doc-4c784a84a66adf221597', 'source-node-001154', '3', '1156', 'text', '柑橘裂果', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001158', 'source-doc-4c784a84a66adf221597', 'source-node-001157', '4', '1157', 'text', '发病规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001159', 'source-doc-4c784a84a66adf221597', 'source-node-001158', '5', '1158', 'text', '生理机制：果肉膨大速度超过果皮生长速率，膨压导致果皮破裂。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001160', 'source-doc-4c784a84a66adf221597', 'source-node-001158', '5', '1159', 'text', '关键诱因：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001161', 'source-doc-4c784a84a66adf221597', 'source-node-001160', '6', '1160', 'text', '水分失衡：久旱骤雨或忽晴忽雨，果肉吸水膨胀率达 20%-30%，果皮拉伸极限仅 10%-15%。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001162', 'source-doc-4c784a84a66adf221597', 'source-node-001160', '6', '1161', 'text', '营养缺失：钙（Ca²⁺）含量＜0.2%、硼（B）含量＜20mg/kg 时，果皮韧性下降 50% 以上。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001163', 'source-doc-4c784a84a66adf221597', 'source-node-001160', '6', '1162', 'text', '品种特性：脐橙、贡柑等皮薄品种裂果率可达 30%-50%，枳壳砧木裂果率较红黎檬低 60%。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001164', 'source-doc-4c784a84a66adf221597', 'source-node-001157', '4', '1163', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001165', 'source-doc-4c784a84a66adf221597', 'source-node-001164', '5', '1164', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001166', 'source-doc-4c784a84a66adf221597', 'source-node-001157', '4', '1165', 'text', '预防方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001167', 'source-doc-4c784a84a66adf221597', 'source-node-001166', '5', '1166', 'text', '水分调控：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001168', 'source-doc-4c784a84a66adf221597', 'source-node-001167', '6', '1167', 'text', '滴灌系统：膨果期保持土壤含水量 60%-70%，干旱时每 3-5 天滴灌 1 次（20-30L / 株）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001169', 'source-doc-4c784a84a66adf221597', 'source-node-001167', '6', '1168', 'text', '覆盖保墒：树盘覆盖 10-15cm 厚秸秆，降低土壤水分波动幅度 40%。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001170', 'source-doc-4c784a84a66adf221597', 'source-node-001166', '5', '1169', 'text', '营养强化：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001171', 'source-doc-4c784a84a66adf221597', 'source-node-001170', '6', '1170', 'text', '土壤补钙：膨果前撒施生石灰 50-100kg / 亩，调节 pH 至 6.0-6.5，促进钙吸收。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001172', 'source-doc-4c784a84a66adf221597', 'source-node-001170', '6', '1171', 'text', '叶面补硼：春梢萌芽期和幼果期喷施硼源库（糖醇硼）1500 倍液，提升果皮弹性。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001173', 'source-doc-4c784a84a66adf221597', 'source-node-001157', '4', '1172', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001174', 'source-doc-4c784a84a66adf221597', 'source-node-001173', '5', '1173', 'text', '钙源库（糖醇钙）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001175', 'source-doc-4c784a84a66adf221597', 'source-node-001174', '6', '1174', 'text', '作用机制：螯合态钙快速渗透果皮，形成钙交联结构，增强细胞壁韧性。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001176', 'source-doc-4c784a84a66adf221597', 'source-node-001174', '6', '1175', 'text', '使用技术：膨果初期（果径 2-3cm）喷施 1000 倍液，间隔 10 天再喷 1 次，裂果率降低 40%-60%。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001177', 'source-doc-4c784a84a66adf221597', 'source-node-001173', '5', '1176', 'text', '赤霉素（GA₃）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001178', 'source-doc-4c784a84a66adf221597', 'source-node-001177', '6', '1177', 'text', '作用机制：促进果皮细胞分裂，使果肉与果皮生长速率同步。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001179', 'source-doc-4c784a84a66adf221597', 'source-node-001177', '6', '1178', 'text', '使用技术：久旱遇雨后喷施 20-30ppm 溶液，重点喷淋果实，持效期 15-20 天。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001180', 'source-doc-4c784a84a66adf221597', 'source-node-001173', '5', '1179', 'text', '硼源库（糖醇硼）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001181', 'source-doc-4c784a84a66adf221597', 'source-node-001180', '6', '1180', 'text', '作用机制：参与果胶合成，增强细胞间黏着力。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001182', 'source-doc-4c784a84a66adf221597', 'source-node-001180', '6', '1181', 'text', '使用技术：幼果期和膨大期各喷 1 次 1500 倍液，配合钙源库增效。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001183', 'source-doc-4c784a84a66adf221597', 'source-node-001154', '3', '1182', 'text', '柑橘缺钾', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001184', 'source-doc-4c784a84a66adf221597', 'source-node-001183', '4', '1183', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001185', 'source-doc-4c784a84a66adf221597', 'source-node-001154', '3', '1184', 'text', '柑橘缺氮', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001186', 'source-doc-4c784a84a66adf221597', 'source-node-001185', '4', '1185', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001187', 'source-doc-4c784a84a66adf221597', 'source-node-001154', '3', '1186', 'text', '柑橘缺磷', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001188', 'source-doc-4c784a84a66adf221597', 'source-node-001154', '3', '1187', 'text', '柑橘缺硼', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001189', 'source-doc-4c784a84a66adf221597', 'source-node-001188', '4', '1188', 'text', '发病规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001190', 'source-doc-4c784a84a66adf221597', 'source-node-001189', '5', '1189', 'text', '土壤因素：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001191', 'source-doc-4c784a84a66adf221597', 'source-node-001190', '6', '1190', 'text', '酸性红壤：有效硼含量＜0.5mg/kg，淋失率达 80% 以上。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001192', 'source-doc-4c784a84a66adf221597', 'source-node-001190', '6', '1191', 'text', '碱性土壤：硼以硼酸根形式被固定，根系吸收效率降低 70%。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001193', 'source-doc-4c784a84a66adf221597', 'source-node-001189', '5', '1192', 'text', '症状表现：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001194', 'source-doc-4c784a84a66adf221597', 'source-node-001193', '6', '1193', 'text', '新梢：叶片畸形、叶柄断裂，叶脉木栓化开裂。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001195', 'source-doc-4c784a84a66adf221597', 'source-node-001193', '6', '1194', 'text', '果实：幼果表皮出现乳白色微突斑，后期下陷变黑，中果皮充塞胶质，落果率增加 30%-50%。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001196', 'source-doc-4c784a84a66adf221597', 'source-node-001188', '4', '1195', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001197', 'source-doc-4c784a84a66adf221597', 'source-node-001196', '5', '1196', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001198', 'source-doc-4c784a84a66adf221597', 'source-node-001188', '4', '1197', 'text', '预防方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001199', 'source-doc-4c784a84a66adf221597', 'source-node-001198', '5', '1198', 'text', '土壤改良：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001200', 'source-doc-4c784a84a66adf221597', 'source-node-001199', '6', '1199', 'text', '增施有机肥：每亩年施羊粪 2000kg + 硼砂 2kg，提升土壤有机质至 2% 以上，有效硼含量提高至 0.8mg/kg。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001201', 'source-doc-4c784a84a66adf221597', 'source-node-001198', '5', '1200', 'text', '砧木选择：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001202', 'source-doc-4c784a84a66adf221597', 'source-node-001201', '6', '1201', 'text', '优先选用枳壳、枸头橙等耐缺硼砧木，嫁接部位高于地面 10cm 以上。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001203', 'source-doc-4c784a84a66adf221597', 'source-node-001188', '4', '1202', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001204', 'source-doc-4c784a84a66adf221597', 'source-node-001203', '5', '1203', 'text', '硼源库（糖醇硼）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001205', 'source-doc-4c784a84a66adf221597', 'source-node-001204', '6', '1204', 'text', '作用机制：糖醇载体促进硼在韧皮部运输，利用率较硼砂提升 3 倍。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001206', 'source-doc-4c784a84a66adf221597', 'source-node-001204', '6', '1205', 'text', '使用技术：春梢萌芽期、谢花 2/3 时、幼果期各喷 1 次 1500 倍液，矫正率达 90% 以上。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001207', 'source-doc-4c784a84a66adf221597', 'source-node-001203', '5', '1206', 'text', '硼砂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001208', 'source-doc-4c784a84a66adf221597', 'source-node-001207', '6', '1207', 'text', '作用机制：补充土壤有效硼，持效期 6-8 个月。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001209', 'source-doc-4c784a84a66adf221597', 'source-node-001207', '6', '1208', 'text', '使用技术：秋季基肥中每亩混施硼砂 1-2kg，与有机肥拌匀后沟施。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001210', 'source-doc-4c784a84a66adf221597', 'source-node-001203', '5', '1209', 'text', '螯合硼：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001211', 'source-doc-4c784a84a66adf221597', 'source-node-001210', '6', '1210', 'text', '作用机制：EDTA 螯合态硼不受土壤 pH 影响，吸收效率高。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001212', 'source-doc-4c784a84a66adf221597', 'source-node-001210', '6', '1211', 'text', '使用技术：叶面喷施 3000-4000 倍液，土壤灌根 500-1000 倍液，适合碱性土壤。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001213', 'source-doc-4c784a84a66adf221597', 'source-node-001154', '3', '1212', 'text', '柑橘缺钙', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001214', 'source-doc-4c784a84a66adf221597', 'source-node-001213', '4', '1213', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001215', 'source-doc-4c784a84a66adf221597', 'source-node-001154', '3', '1214', 'text', '柑橘缺镁症', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001216', 'source-doc-4c784a84a66adf221597', 'source-node-001215', '4', '1215', 'text', '规律：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001217', 'source-doc-4c784a84a66adf221597', 'source-node-001216', '5', '1216', 'text', '植株表现：镁是叶绿素核心成分，缺镁先从老叶开始（镁可移动，优先供应新叶），叶片沿中脉两侧出现黄化斑块，叶脉仍保持绿色，严重时黄化区扩大至全叶，仅叶尖、叶缘残留绿色，最终叶片脱落，新梢生长受抑制。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001218', 'source-doc-4c784a84a66adf221597', 'source-node-001216', '5', '1217', 'text', '土壤因素：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001219', 'source-doc-4c784a84a66adf221597', 'source-node-001218', '6', '1218', 'text', '酸性土壤（pH＜5.5）中，镁易被氢离子置换流失，或被铝、锰离子拮抗，导致根系吸收受阻（砂质土、红壤区常见）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001220', 'source-doc-4c784a84a66adf221597', 'source-node-001218', '6', '1219', 'text', '砂质土壤保肥能力差，多雨季节镁元素淋溶严重，易引发缺镁。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001221', 'source-doc-4c784a84a66adf221597', 'source-node-001218', '6', '1220', 'text', '过量施用钾肥、钙肥时，钾、钙离子与镁离子竞争吸收位点，抑制镁的吸收（如长期偏施氯化钾、过磷酸钙的果园）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001222', 'source-doc-4c784a84a66adf221597', 'source-node-001216', '5', '1221', 'text', '气候与管理：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001223', 'source-doc-4c784a84a66adf221597', 'source-node-001222', '6', '1222', 'text', '干旱时根系吸水吸肥能力下降，镁吸收受阻；积水时根系缺氧，吸收功能紊乱，加重缺镁。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001224', 'source-doc-4c784a84a66adf221597', 'source-node-001222', '6', '1223', 'text', '结果过多的树体，镁向果实转移量大，叶片中镁含量不足，易表现缺素症状（柚类、脐橙等结果量大的品种更敏感）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001225', 'source-doc-4c784a84a66adf221597', 'source-node-001215', '4', '1224', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001226', 'source-doc-4c784a84a66adf221597', 'source-node-001225', '5', '1225', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001227', 'source-doc-4c784a84a66adf221597', 'source-node-001215', '4', '1226', 'text', '预防方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001228', 'source-doc-4c784a84a66adf221597', 'source-node-001227', '5', '1227', 'text', '土壤改良：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001229', 'source-doc-4c784a84a66adf221597', 'source-node-001228', '6', '1228', 'text', '酸性土壤（pH＜5.5）每亩撒施生石灰 50-100 公斤或白云石粉（含镁碳酸盐）100-200 公斤，调节 pH 至 6.0-6.5，提高土壤镁的有效性。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001230', 'source-doc-4c784a84a66adf221597', 'source-node-001228', '6', '1229', 'text', '砂质土壤增施有机肥（如腐熟鸡粪、羊粪、秸秆堆肥等），每亩 2000-3000 公斤，改善土壤保肥保水能力，减少镁的淋溶。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001231', 'source-doc-4c784a84a66adf221597', 'source-node-001227', '5', '1230', 'text', '科学施肥：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001232', 'source-doc-4c784a84a66adf221597', 'source-node-001231', '6', '1231', 'text', '基肥中配合施用镁肥：每株成年树施硫酸镁 0.5-1 公斤（或氧化镁 0.3-0.5 公斤、硝酸镁 0.4-0.8 公斤），与有机肥混合施用，提高吸收效率。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001233', 'source-doc-4c784a84a66adf221597', 'source-node-001231', '6', '1232', 'text', '控制钾肥、钙肥用量：避免过量施用氯化钾、硫酸钾（每亩年用量不超过 50 公斤）和过磷酸钙，采用平衡肥（如 15-15-15 复合肥），减少离子竞争。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001234', 'source-doc-4c784a84a66adf221597', 'source-node-001227', '5', '1233', 'text', '水分管理：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001235', 'source-doc-4c784a84a66adf221597', 'source-node-001234', '6', '1234', 'text', '保持土壤湿润但不积水，干旱时及时灌水（采用滴灌、喷灌，避免大水漫灌），雨季及时排水，防止根系受损。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001236', 'source-doc-4c784a84a66adf221597', 'source-node-001215', '4', '1235', 'text', '防治：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001237', 'source-doc-4c784a84a66adf221597', 'source-node-001236', '5', '1236', 'text', '以 “叶面喷施快速补充 + 土壤基施长效维持” 为核心，优先叶面喷施（见效快，3-7 天可见效），结合土壤补肥巩固效果。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001238', 'source-doc-4c784a84a66adf221597', 'source-node-001236', '5', '1237', 'text', '1. 叶面喷施药剂（按效果及使用频次排序）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001239', 'source-doc-4c784a84a66adf221597', 'source-node-001238', '6', '1238', 'text', '硫酸镁：最常用且高效，浓度 0.5%-1%（即 100 斤水加 0.5-1 斤硫酸镁），叶片正反面均匀喷施，间隔 7-10 天 1 次，连续 2-3 次。可单独使用，或与 0.3% 尿素混合喷施（促进吸收），对老叶黄化修复效果显著。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001240', 'source-doc-4c784a84a66adf221597', 'source-node-001238', '6', '1239', 'text', '硝酸镁：含氮和镁，既能补镁又能补氮，适合缺镁伴随轻度缺氮的树体，浓度 0.4%-0.8%，用法同硫酸镁，在春梢、秋梢生长期喷施效果佳。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001241', 'source-doc-4c784a84a66adf221597', 'source-node-001238', '6', '1240', 'text', '螯合镁（EDTA 镁）：吸收率高于无机镁，尤其在酸性土壤中不易被拮抗，浓度 0.1%-0.2%，喷施后 1-2 天即可被叶片吸收，适合应急补充，成本较高，常用于严重缺镁树体。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001242', 'source-doc-4c784a84a66adf221597', 'source-node-001238', '6', '1241', 'text', '氯化镁：效果与硫酸镁接近，但含氯离子，对柑橘（尤其敏感品种如温州蜜柑）需控制浓度（≤0.5%），避免氯离子积累导致毒害，使用频次较低。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001243', 'source-doc-4c784a84a66adf221597', 'source-node-001238', '6', '1242', 'text', '氨基酸镁 / 腐植酸镁：有机螯合态镁，与氨基酸、腐植酸协同作用，提高镁的稳定性和吸收率，浓度 0.2%-0.3%，适合长期调理，改善树体营养状况。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001244', 'source-doc-4c784a84a66adf221597', 'source-node-001236', '5', '1243', 'text', '2. 土壤施用药剂', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001245', 'source-doc-4c784a84a66adf221597', 'source-node-001244', '6', '1244', 'text', '硫酸镁：成年树每株施 0.5-1.5 公斤，幼树 0.2-0.5 公斤，在树冠滴水线处开浅沟施入，覆土后浇水，结合雨季前施用，减少淋溶损失。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001246', 'source-doc-4c784a84a66adf221597', 'source-node-001244', '6', '1245', 'text', '白云石粉（碳酸镁钙）：缓慢释放镁元素，适合酸性土壤长期调理，每亩 150-200 公斤，与有机肥混合施入，有效期 1-2 年。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001247', 'source-doc-4c784a84a66adf221597', 'source-node-001244', '6', '1246', 'text', '镁肥复合肥：选用含镁的复合肥（如 16-8-16-2MgO），在春梢、秋梢期追肥，每株 0.5-1 公斤，平衡氮磷钾与镁的供应。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001248', 'source-doc-4c784a84a66adf221597', 'source-node-001154', '3', '1247', 'text', '柑橘缺锌症', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001249', 'source-doc-4c784a84a66adf221597', 'source-node-001248', '4', '1248', 'text', '发病规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001250', 'source-doc-4c784a84a66adf221597', 'source-node-001249', '5', '1249', 'text', '土壤因素：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001251', 'source-doc-4c784a84a66adf221597', 'source-node-001250', '6', '1250', 'text', '碱性土壤：锌以氢氧化物形式沉淀，有效锌含量＜0.5mg/kg。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001252', 'source-doc-4c784a84a66adf221597', 'source-node-001250', '6', '1251', 'text', '高磷土壤：磷酸锌溶解度降低，吸收受阻。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001253', 'source-doc-4c784a84a66adf221597', 'source-node-001249', '5', '1252', 'text', '症状表现：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001254', 'source-doc-4c784a84a66adf221597', 'source-node-001253', '6', '1253', 'text', '叶片：新梢叶尖出现肋骨状黄色斑块，主脉及附近保持绿色，称 “绿肋黄化症”。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001255', 'source-doc-4c784a84a66adf221597', 'source-node-001253', '6', '1254', 'text', '果实：果小皮厚，畸形果率增加 20%-30%。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001256', 'source-doc-4c784a84a66adf221597', 'source-node-001248', '4', '1255', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001257', 'source-doc-4c784a84a66adf221597', 'source-node-001256', '5', '1256', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001258', 'source-doc-4c784a84a66adf221597', 'source-node-001248', '4', '1257', 'text', '预防方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001259', 'source-doc-4c784a84a66adf221597', 'source-node-001258', '5', '1258', 'text', '土壤管理：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001260', 'source-doc-4c784a84a66adf221597', 'source-node-001259', '6', '1259', 'text', '调节 pH：酸性土壤撒施石灰 50-100kg / 亩，碱性土壤施用硫磺粉 20-30kg / 亩，使 pH 稳定在 6.0-6.5。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001261', 'source-doc-4c784a84a66adf221597', 'source-node-001258', '5', '1260', 'text', '合理施肥：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001262', 'source-doc-4c784a84a66adf221597', 'source-node-001261', '6', '1261', 'text', '控制磷肥用量，避免与锌肥拮抗，氮磷钾比例保持 1:0.5:0.8。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001263', 'source-doc-4c784a84a66adf221597', 'source-node-001248', '4', '1262', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001264', 'source-doc-4c784a84a66adf221597', 'source-node-001263', '5', '1263', 'text', '螯合锌：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001265', 'source-doc-4c784a84a66adf221597', 'source-node-001264', '6', '1264', 'text', '作用机制：EDTA 螯合态锌不受土壤 pH 影响，吸收效率是硫酸锌的 5 倍。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001266', 'source-doc-4c784a84a66adf221597', 'source-node-001264', '6', '1265', 'text', '使用技术：春梢停止伸长后喷施 3000-4000 倍液，间隔 10 天再喷 1 次，矫正率达 85%。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001267', 'source-doc-4c784a84a66adf221597', 'source-node-001263', '5', '1266', 'text', '硫酸锌：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001268', 'source-doc-4c784a84a66adf221597', 'source-node-001267', '6', '1267', 'text', '作用机制：补充土壤有效锌，持效期 4-6 个月。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001269', 'source-doc-4c784a84a66adf221597', 'source-node-001267', '6', '1268', 'text', '使用技术：秋季基肥中每亩混施硫酸锌 1-1.5kg，与有机肥拌匀后沟施。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001270', 'source-doc-4c784a84a66adf221597', 'source-node-001263', '5', '1269', 'text', '硫酸锌 + 石灰：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001271', 'source-doc-4c784a84a66adf221597', 'source-node-001270', '6', '1270', 'text', '作用机制：石灰调节土壤 pH 至微酸性，促进锌溶解。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001272', 'source-doc-4c784a84a66adf221597', 'source-node-001270', '6', '1271', 'text', '使用技术：叶面喷施 0.1%-0.3% 硫酸锌 + 等量石灰，降低药害风险。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001273', 'source-doc-4c784a84a66adf221597', 'source-node-001154', '3', '1272', 'text', '柑橘缺铁症', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001274', 'source-doc-4c784a84a66adf221597', 'source-node-001273', '4', '1273', 'text', '发病规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001275', 'source-doc-4c784a84a66adf221597', 'source-node-001274', '5', '1274', 'text', '土壤因素：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001276', 'source-doc-4c784a84a66adf221597', 'source-node-001275', '6', '1275', 'text', '石灰性土壤：铁以 Fe (OH)₃形式沉淀，有效铁含量＜4.5mg/kg。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001277', 'source-doc-4c784a84a66adf221597', 'source-node-001275', '6', '1276', 'text', '有机质缺乏：腐殖质不足，铁螯合能力下降 50%。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001278', 'source-doc-4c784a84a66adf221597', 'source-node-001274', '5', '1277', 'text', '症状表现：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001279', 'source-doc-4c784a84a66adf221597', 'source-node-001278', '6', '1278', 'text', '叶片：新梢叶脉间黄化，呈 “网目状”，严重时全叶白化，称 “黄叶病”。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001280', 'source-doc-4c784a84a66adf221597', 'source-node-001278', '6', '1279', 'text', '果实：果小味酸，可溶性固形物降低 1-2°Brix。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001281', 'source-doc-4c784a84a66adf221597', 'source-node-001273', '4', '1280', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001282', 'source-doc-4c784a84a66adf221597', 'source-node-001281', '5', '1281', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001283', 'source-doc-4c784a84a66adf221597', 'source-node-001273', '4', '1282', 'text', '预防方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001284', 'source-doc-4c784a84a66adf221597', 'source-node-001283', '5', '1283', 'text', '土壤改良：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001285', 'source-doc-4c784a84a66adf221597', 'source-node-001284', '6', '1284', 'text', '增施有机肥：每亩年施腐殖酸有机肥 1000kg，提升土壤有机质至 2% 以上，有效铁含量提高至 6mg/kg。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001286', 'source-doc-4c784a84a66adf221597', 'source-node-001283', '5', '1285', 'text', '水分管理：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001287', 'source-doc-4c784a84a66adf221597', 'source-node-001286', '6', '1286', 'text', '避免过量灌溉，保持土壤透气性，促进铁吸收。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001288', 'source-doc-4c784a84a66adf221597', 'source-node-001273', '4', '1287', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001289', 'source-doc-4c784a84a66adf221597', 'source-node-001288', '5', '1288', 'text', '螯合铁：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001290', 'source-doc-4c784a84a66adf221597', 'source-node-001289', '6', '1289', 'text', '作用机制：EDDHA 螯合态铁在碱性土壤中稳定性高，吸收效率是硫酸亚铁的 10 倍。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001291', 'source-doc-4c784a84a66adf221597', 'source-node-001289', '6', '1290', 'text', '使用技术：新梢生长期喷施 3000-4000 倍液，间隔 7-10 天喷 1 次，连喷 2-3 次，矫正率达 90%。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001292', 'source-doc-4c784a84a66adf221597', 'source-node-001288', '5', '1291', 'text', '硫酸亚铁：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001293', 'source-doc-4c784a84a66adf221597', 'source-node-001292', '6', '1292', 'text', '作用机制：补充土壤有效铁，持效期 3-4 个月。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001294', 'source-doc-4c784a84a66adf221597', 'source-node-001292', '6', '1293', 'text', '使用技术：秋季基肥中每亩混施硫酸亚铁 2-3kg，与有机肥拌匀后沟施。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001295', 'source-doc-4c784a84a66adf221597', 'source-node-001288', '5', '1294', 'text', '黄腐酸铁：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001296', 'source-doc-4c784a84a66adf221597', 'source-node-001295', '6', '1295', 'text', '作用机制：黄腐酸螯合铁促进根系吸收，同时改善土壤结构。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001297', 'source-doc-4c784a84a66adf221597', 'source-node-001295', '6', '1296', 'text', '使用技术：叶面喷施 800-1000 倍液，土壤灌根 500-800 倍液，适合酸性土壤。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001298', 'source-doc-4c784a84a66adf221597', 'source-node-001154', '3', '1297', 'text', '柑橘缺锰症', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001299', 'source-doc-4c784a84a66adf221597', 'source-node-001298', '4', '1298', 'text', '发病规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001300', 'source-doc-4c784a84a66adf221597', 'source-node-001299', '5', '1299', 'text', '土壤因素：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001301', 'source-doc-4c784a84a66adf221597', 'source-node-001300', '6', '1300', 'text', '碱性土壤：有效锰含量＜15mg/kg，易与铁、锌拮抗。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001302', 'source-doc-4c784a84a66adf221597', 'source-node-001300', '6', '1301', 'text', '酸性砂质土：锰淋失率达 60% 以上，根系吸收不足。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001303', 'source-doc-4c784a84a66adf221597', 'source-node-001299', '5', '1302', 'text', '症状表现：', '[]');
