INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001309', 'source-doc-4c784a84a66adf221597', 'source-node-001308', '5', '1308', 'text', '土壤改良：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001310', 'source-doc-4c784a84a66adf221597', 'source-node-001309', '6', '1309', 'text', '酸性土壤每亩施氧化镁 10-20kg，调节 pH 至 6.0-6.5。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001311', 'source-doc-4c784a84a66adf221597', 'source-node-001308', '5', '1310', 'text', '合理施肥：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001312', 'source-doc-4c784a84a66adf221597', 'source-node-001311', '6', '1311', 'text', '避免过量施用氮肥，氮锰比控制在 100:1 以内。', '[]');
