INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001314', 'source-doc-4c784a84a66adf221597', 'source-node-001313', '5', '1313', 'text', '螯合锰：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001315', 'source-doc-4c784a84a66adf221597', 'source-node-001314', '6', '1314', 'text', '作用机制：EDTA 螯合态锰吸收效率高，不受土壤 pH 影响。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001316', 'source-doc-4c784a84a66adf221597', 'source-node-001314', '6', '1315', 'text', '使用技术：新梢生长期喷施 3000-4000 倍液，间隔 7-10 天喷 1 次，矫正率达 85%。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001317', 'source-doc-4c784a84a66adf221597', 'source-node-001313', '5', '1316', 'text', '硫酸锰：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001318', 'source-doc-4c784a84a66adf221597', 'source-node-001317', '6', '1317', 'text', '作用机制：补充土壤有效锰，持效期 3-4 个月。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001319', 'source-doc-4c784a84a66adf221597', 'source-node-001317', '6', '1318', 'text', '使用技术：秋季基肥中每亩混施硫酸锰 1-1.5kg，与有机肥拌匀后沟施。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001320', 'source-doc-4c784a84a66adf221597', 'source-node-001313', '5', '1319', 'text', '硫酸锰 + 硫酸亚铁：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001321', 'source-doc-4c784a84a66adf221597', 'source-node-001320', '6', '1320', 'text', '作用机制：协同矫正缺锰和缺铁，适合复合缺素症。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001322', 'source-doc-4c784a84a66adf221597', 'source-node-001320', '6', '1321', 'text', '使用技术：叶面喷施 0.1% 硫酸锰 + 0.2% 硫酸亚铁，间隔 10 天喷 1 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001323', 'source-doc-4c784a84a66adf221597', 'source-node-001154', '3', '1322', 'text', '柑橘缺铜症', '[]');
