INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001332', 'source-doc-4c784a84a66adf221597', 'source-node-001331', '6', '1331', 'text', '温湿度：青霉病、绿霉病最适温度 15-25℃，湿度＞85%。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001333', 'source-doc-4c784a84a66adf221597', 'source-node-001331', '6', '1332', 'text', '气体成分：二氧化碳浓度＞2%、氧气浓度＜18% 时，水肿病发生率增加 30%。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001334', 'source-doc-4c784a84a66adf221597', 'source-node-001330', '5', '1333', 'text', '病原传播：', '[]');
