INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001348', 'source-doc-4c784a84a66adf221597', 'source-node-001347', '6', '1347', 'text', '作用机制：破坏真菌细胞膜，对酸腐病特效。', '[]');
