INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001356', 'source-doc-4c784a84a66adf221597', 'source-node-001355', '6', '1355', 'text', '高温干旱：气温＞35℃、空气湿度＜50% 时，果实表面温度可达 45℃以上，灼伤细胞。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001357', 'source-doc-4c784a84a66adf221597', 'source-node-001355', '6', '1356', 'text', '强紫外线：海拔＞500m 地区，紫外线强度增加 30%，加剧灼伤。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001358', 'source-doc-4c784a84a66adf221597', 'source-node-001354', '5', '1357', 'text', '品种特性：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001359', 'source-doc-4c784a84a66adf221597', 'source-node-001358', '6', '1358', 'text', '沃柑、茂谷柑等皮薄品种日灼率达 40%-60%，而蜜橘、金柑等厚皮品种仅 5%-10%。', '[]');
