INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001365', 'source-doc-4c784a84a66adf221597', 'source-node-001363', '6', '1364', 'text', '果实套袋：选用双层遮光纸袋，套袋前喷施钙源库 1000 倍液，防效达 80%。', '[]');
