INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001382', 'source-doc-4c784a84a66adf221597', 'source-node-001381', '6', '1381', 'text', '极端低温：气温＜-5℃持续 2 小时以上，柑橘树体发生冻害。', '[]');
