INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001389', 'source-doc-4c784a84a66adf221597', 'source-node-001388', '5', '1388', 'text', '物理防护：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001390', 'source-doc-4c784a84a66adf221597', 'source-node-001389', '6', '1389', 'text', '覆盖保温：树冠覆盖防寒布，根颈培土 30-40cm，减少热量散失。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001391', 'source-doc-4c784a84a66adf221597', 'source-node-001389', '6', '1390', 'text', '熏烟增温：每亩设置 5-8 个熏烟堆（杂草、木屑），气温降至 - 2℃时点火，提升果园温度 2-3℃。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001392', 'source-doc-4c784a84a66adf221597', 'source-node-001388', '5', '1391', 'text', '营养调控：', '[]');
