INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001394', 'source-doc-4c784a84a66adf221597', 'source-node-001379', '4', '1393', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001395', 'source-doc-4c784a84a66adf221597', 'source-node-001394', '5', '1394', 'text', '磷钾源库：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001396', 'source-doc-4c784a84a66adf221597', 'source-node-001395', '6', '1395', 'text', '作用机制：促进糖分积累，降低细胞冰点值。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001397', 'source-doc-4c784a84a66adf221597', 'source-node-001395', '6', '1396', 'text', '使用技术：冻前 10-15 天喷施 500 倍液，冻后恢复喷施 300 倍液，冻害指数降低 40%。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001398', 'source-doc-4c784a84a66adf221597', 'source-node-001394', '5', '1397', 'text', '海精灵生物刺激剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001399', 'source-doc-4c784a84a66adf221597', 'source-node-001398', '6', '1398', 'text', '作用机制：海藻多糖增强细胞膜稳定性，腐殖酸提升根系活力。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001400', 'source-doc-4c784a84a66adf221597', 'source-node-001398', '6', '1399', 'text', '使用技术：冻前灌根 800 倍液，冻后喷施 500 倍液，树势恢复率达 70%。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001401', 'source-doc-4c784a84a66adf221597', 'source-node-001394', '5', '1400', 'text', '天达 2116：', '[]');
