INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001404', 'source-doc-4c784a84a66adf221597', 'source-node-001154', '3', '1403', 'text', '柑橘涝害', '[]');
