INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001406', 'source-doc-4c784a84a66adf221597', 'source-node-001405', '5', '1405', 'text', '环境因素：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001407', 'source-doc-4c784a84a66adf221597', 'source-node-001406', '6', '1406', 'text', '连续降雨：日降雨量＞50mm 持续 3 天以上，根系缺氧时间超 24 小时即发生涝害。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001408', 'source-doc-4c784a84a66adf221597', 'source-node-001406', '6', '1407', 'text', '地形低洼：平地果园积水风险较山地高 3-5 倍。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001409', 'source-doc-4c784a84a66adf221597', 'source-node-001405', '5', '1408', 'text', '症状表现：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001410', 'source-doc-4c784a84a66adf221597', 'source-node-001409', '6', '1409', 'text', '根系：须根腐烂，木质部变褐，新根萌发受抑制。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001411', 'source-doc-4c784a84a66adf221597', 'source-node-001409', '6', '1410', 'text', '地上部：叶片黄化、萎蔫，严重时整株枯死。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001412', 'source-doc-4c784a84a66adf221597', 'source-node-001404', '4', '1411', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001413', 'source-doc-4c784a84a66adf221597', 'source-node-001412', '5', '1412', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001414', 'source-doc-4c784a84a66adf221597', 'source-node-001404', '4', '1413', 'text', '预防方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001415', 'source-doc-4c784a84a66adf221597', 'source-node-001414', '5', '1414', 'text', '排水系统：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001416', 'source-doc-4c784a84a66adf221597', 'source-node-001415', '6', '1415', 'text', '深沟高畦：垄高 30-40cm，排水沟深 50-60cm，排水速率＞10mm/h。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001417', 'source-doc-4c784a84a66adf221597', 'source-node-001415', '6', '1416', 'text', '暗管排水：埋设直径 10-15cm 波纹管，间距 8-10m，排水效率提升 50%。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001418', 'source-doc-4c784a84a66adf221597', 'source-node-001414', '5', '1417', 'text', '土壤改良：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001419', 'source-doc-4c784a84a66adf221597', 'source-node-001418', '6', '1418', 'text', '酸性土壤每亩撒施生石灰 50-100kg，调节 pH 至 6.0-6.5，促进根系呼吸。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001420', 'source-doc-4c784a84a66adf221597', 'source-node-001404', '4', '1419', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001421', 'source-doc-4c784a84a66adf221597', 'source-node-001420', '5', '1420', 'text', '恶霉灵：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001422', 'source-doc-4c784a84a66adf221597', 'source-node-001421', '6', '1421', 'text', '作用机制：抑制腐霉菌、疫霉菌等根部病害。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001423', 'source-doc-4c784a84a66adf221597', 'source-node-001421', '6', '1422', 'text', '使用技术：积水退去后立即灌根 800-1000 倍液，每株用量 5-10L，防根腐率达 80%。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001424', 'source-doc-4c784a84a66adf221597', 'source-node-001420', '5', '1423', 'text', '腐殖酸水溶肥：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001425', 'source-doc-4c784a84a66adf221597', 'source-node-001424', '6', '1424', 'text', '作用机制：促进新根萌发，提升根系活力。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001426', 'source-doc-4c784a84a66adf221597', 'source-node-001424', '6', '1425', 'text', '使用技术：涝后 1 周淋施 300-500 倍液，配合海精灵生物刺激剂增效。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001427', 'source-doc-4c784a84a66adf221597', 'source-node-001420', '5', '1426', 'text', '甲霜灵・锰锌：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001428', 'source-doc-4c784a84a66adf221597', 'source-node-001427', '6', '1427', 'text', '作用机制：内吸性杀菌剂，防治疫霉根腐病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001429', 'source-doc-4c784a84a66adf221597', 'source-node-001427', '6', '1428', 'text', '使用技术：涝后喷施 600-800 倍液，重点喷淋根颈部位。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001430', 'source-doc-4c784a84a66adf221597', 'source-node-001154', '3', '1429', 'text', '柑橘枯水病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001431', 'source-doc-4c784a84a66adf221597', 'source-node-001430', '4', '1430', 'text', '发病规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001432', 'source-doc-4c784a84a66adf221597', 'source-node-001431', '5', '1431', 'text', '环境因素：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001433', 'source-doc-4c784a84a66adf221597', 'source-node-001432', '6', '1432', 'text', '成熟期阴雨：连续降雨超 5 天，果皮二次生长导致白皮层崩溃。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001434', 'source-doc-4c784a84a66adf221597', 'source-node-001432', '6', '1433', 'text', '贮藏条件：温度＜5℃、湿度＞90% 时，枯水率增加 20%-30%。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001435', 'source-doc-4c784a84a66adf221597', 'source-node-001431', '5', '1434', 'text', '营养因素：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001436', 'source-doc-4c784a84a66adf221597', 'source-node-001435', '6', '1435', 'text', '锌含量＜15mg/kg、钙含量＜0.15% 时，枯水发生率提升 50%。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001437', 'source-doc-4c784a84a66adf221597', 'source-node-001430', '4', '1436', 'text', '图片', '[]');
