INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001440', 'source-doc-4c784a84a66adf221597', 'source-node-001439', '5', '1439', 'text', '栽培管理：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001441', 'source-doc-4c784a84a66adf221597', 'source-node-001440', '6', '1440', 'text', '适时采收：果实可溶性固形物达 12°Brix 时采收，避免挂树过久。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001442', 'source-doc-4c784a84a66adf221597', 'source-node-001440', '6', '1441', 'text', '控水管理：转色期适度控水，土壤含水量降至 50%-55%，减少果皮生长。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001443', 'source-doc-4c784a84a66adf221597', 'source-node-001439', '5', '1442', 'text', '贮藏调控：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001444', 'source-doc-4c784a84a66adf221597', 'source-node-001443', '6', '1443', 'text', '宽皮橘类贮藏湿度控制在 80%-85%，甜橙类控制在 85%-90%。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001445', 'source-doc-4c784a84a66adf221597', 'source-node-001430', '4', '1444', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001446', 'source-doc-4c784a84a66adf221597', 'source-node-001445', '5', '1445', 'text', '红库叶面肥：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001447', 'source-doc-4c784a84a66adf221597', 'source-node-001446', '6', '1446', 'text', '作用机制：零氮全营养配方，促进糖分积累和果皮成熟。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001448', 'source-doc-4c784a84a66adf221597', 'source-node-001446', '6', '1447', 'text', '使用技术：膨果后期喷施 500 倍液，采前 20 天再喷 1 次，枯水率降低 40%。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001449', 'source-doc-4c784a84a66adf221597', 'source-node-001445', '5', '1448', 'text', '2,4-D + 托布津：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001450', 'source-doc-4c784a84a66adf221597', 'source-node-001449', '6', '1449', 'text', '作用机制：2,4-D 延缓果皮衰老，托布津防治贮藏期病害。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001451', 'source-doc-4c784a84a66adf221597', 'source-node-001449', '6', '1450', 'text', '使用技术：采后浸果（200ppm 2,4-D+500 倍托布津），贮藏期延长至 60 天。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001452', 'source-doc-4c784a84a66adf221597', 'source-node-001445', '5', '1451', 'text', '异菌脲：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001453', 'source-doc-4c784a84a66adf221597', 'source-node-001452', '6', '1452', 'text', '作用机制：抑制真菌菌丝生长，延缓枯水进程。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001454', 'source-doc-4c784a84a66adf221597', 'source-node-001452', '6', '1453', 'text', '使用技术：采后浸果 500 倍液，配合薄膜单果包装，防效达 70%。', '[]');
