INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001459', 'source-doc-4c784a84a66adf221597', 'source-node-001456', '5', '1458', 'text', '生理因素：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001460', 'source-doc-4c784a84a66adf221597', 'source-node-001459', '6', '1459', 'text', '钙含量＜0.2%、硼含量＜20mg/kg 时，果皮细胞间隙增大，油胞易破裂。', '[]');
