INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001464', 'source-doc-4c784a84a66adf221597', 'source-node-001463', '5', '1463', 'text', '病虫害防治：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001465', 'source-doc-4c784a84a66adf221597', 'source-node-001464', '6', '1464', 'text', '重点防治锈壁虱、蓟马，减少机械损伤。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001466', 'source-doc-4c784a84a66adf221597', 'source-node-001463', '5', '1465', 'text', '采收管理：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001467', 'source-doc-4c784a84a66adf221597', 'source-node-001466', '6', '1466', 'text', '雨后 24 小时内不采果，避免油胞吸水膨胀破裂。', '[]');
