INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001471', 'source-doc-4c784a84a66adf221597', 'source-node-001469', '6', '1470', 'text', '使用技术：膨果初期喷施 1000 倍液，间隔 10 天再喷 1 次，油斑率降低 50%。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001472', 'source-doc-4c784a84a66adf221597', 'source-node-001468', '5', '1471', 'text', '代森锰锌：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001473', 'source-doc-4c784a84a66adf221597', 'source-node-001472', '6', '1472', 'text', '作用机制：锌元素增强果皮韧性，同时预防真菌病害。', '[]');
