INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001475', 'source-doc-4c784a84a66adf221597', 'source-node-001468', '5', '1474', 'text', '矿物油：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001476', 'source-doc-4c784a84a66adf221597', 'source-node-001475', '6', '1475', 'text', '作用机制：封闭油胞气孔，减少精油挥发。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001477', 'source-doc-4c784a84a66adf221597', 'source-node-001475', '6', '1476', 'text', '使用技术：采后喷施 200 倍液，配合咪鲜胺 1000 倍液防腐。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001478', 'source-doc-4c784a84a66adf221597', 'source-node-000546', '2', '1477', 'text', '药害/肥害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001479', 'source-doc-4c784a84a66adf221597', 'source-node-001478', '3', '1478', 'text', '柑橘药害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001480', 'source-doc-4c784a84a66adf221597', 'source-node-001479', '4', '1479', 'text', '发病规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001481', 'source-doc-4c784a84a66adf221597', 'source-node-001480', '5', '1480', 'text', '人为因素：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001482', 'source-doc-4c784a84a66adf221597', 'source-node-001481', '6', '1481', 'text', '高温喷药：气温＞30℃时喷药，药剂吸收速率增加 2-3 倍，易产生药害。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001483', 'source-doc-4c784a84a66adf221597', 'source-node-001481', '6', '1482', 'text', '浓度过高：红蜘蛛防治中，阿维菌素超量使用（＞2000 倍）导致叶片灼伤。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001484', 'source-doc-4c784a84a66adf221597', 'source-node-001480', '5', '1483', 'text', '症状表现：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001485', 'source-doc-4c784a84a66adf221597', 'source-node-001484', '6', '1484', 'text', '急性药害：喷施后 24 小时内出现叶片焦枯、畸形。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001486', 'source-doc-4c784a84a66adf221597', 'source-node-001484', '6', '1485', 'text', '慢性药害：生长缓慢、落花落果，持续 1-2 个月。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001487', 'source-doc-4c784a84a66adf221597', 'source-node-001479', '4', '1486', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001488', 'source-doc-4c784a84a66adf221597', 'source-node-001487', '5', '1487', 'text', '1', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001489', 'source-doc-4c784a84a66adf221597', 'source-node-001487', '5', '1488', 'text', '炔螨特药害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001490', 'source-doc-4c784a84a66adf221597', 'source-node-001489', '6', '1489', 'text', '1', '[]');
