INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001492', 'source-doc-4c784a84a66adf221597', 'source-node-001491', '6', '1491', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001493', 'source-doc-4c784a84a66adf221597', 'source-node-001487', '5', '1492', 'text', '赤霉素药害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001494', 'source-doc-4c784a84a66adf221597', 'source-node-001493', '6', '1493', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001495', 'source-doc-4c784a84a66adf221597', 'source-node-001487', '5', '1494', 'text', '2，4-D药害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001496', 'source-doc-4c784a84a66adf221597', 'source-node-001495', '6', '1495', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001497', 'source-doc-4c784a84a66adf221597', 'source-node-001487', '5', '1496', 'text', '氨气毒害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001498', 'source-doc-4c784a84a66adf221597', 'source-node-001497', '6', '1497', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001499', 'source-doc-4c784a84a66adf221597', 'source-node-001479', '4', '1498', 'text', '预防方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001500', 'source-doc-4c784a84a66adf221597', 'source-node-001499', '5', '1499', 'text', '科学用药：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001501', 'source-doc-4c784a84a66adf221597', 'source-node-001500', '6', '1500', 'text', '二次稀释：先在小容器中稀释药剂，再倒入喷雾器，混合均匀。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001502', 'source-doc-4c784a84a66adf221597', 'source-node-001500', '6', '1501', 'text', '避开高温：选择上午 9 点前或下午 4 点后喷药，风速＜3 级。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001503', 'source-doc-4c784a84a66adf221597', 'source-node-001499', '5', '1502', 'text', '药剂混配：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001504', 'source-doc-4c784a84a66adf221597', 'source-node-001503', '6', '1503', 'text', '遵循 “叶面肥→可湿性粉剂→悬浮剂→乳油” 顺序，混配种类不超过 3 种。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001505', 'source-doc-4c784a84a66adf221597', 'source-node-001479', '4', '1504', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001506', 'source-doc-4c784a84a66adf221597', 'source-node-001505', '5', '1505', 'text', '芸苔素内酯 + 复硝酚钠：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001507', 'source-doc-4c784a84a66adf221597', 'source-node-001506', '6', '1506', 'text', '作用机制：芸苔素调节内源激素，复硝酚钠促进细胞修复。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001508', 'source-doc-4c784a84a66adf221597', 'source-node-001506', '6', '1507', 'text', '使用技术：药害后 24 小时内喷施 0.01% 芸苔素 2000 倍液 + 1.8% 复硝酚钠 6000 倍液，恢复率达 85%。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001509', 'source-doc-4c784a84a66adf221597', 'source-node-001505', '5', '1508', 'text', '胺鲜酯（DA-6）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001510', 'source-doc-4c784a84a66adf221597', 'source-node-001509', '6', '1509', 'text', '作用机制：促进光合作用和养分吸收，增强抗逆性。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001511', 'source-doc-4c784a84a66adf221597', 'source-node-001509', '6', '1510', 'text', '使用技术：喷施 8-15mg/L 溶液，间隔 7 天再喷 1 次，适合低温期药害恢复。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001512', 'source-doc-4c784a84a66adf221597', 'source-node-001505', '5', '1511', 'text', '腐殖酸叶面肥：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001513', 'source-doc-4c784a84a66adf221597', 'source-node-001512', '6', '1512', 'text', '作用机制：吸附残留药剂，补充营养促进新叶生长。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001514', 'source-doc-4c784a84a66adf221597', 'source-node-001512', '6', '1513', 'text', '使用技术：喷施 300-500 倍液，配合清水冲洗叶面。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001515', 'source-doc-4c784a84a66adf221597', 'source-node-001478', '3', '1514', 'text', '柑橘肥害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001516', 'source-doc-4c784a84a66adf221597', 'source-node-001515', '4', '1515', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001517', 'source-doc-4c784a84a66adf221597', 'source-node-001516', '5', '1516', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001518', 'source-doc-4c784a84a66adf221597', 'source-node-001515', '4', '1517', 'text', '发病规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001519', 'source-doc-4c784a84a66adf221597', 'source-node-001518', '5', '1518', 'text', '生理机制：土壤溶液渗透压＞根细胞渗透压，导致根系脱水；高浓度离子（如 Cl⁻、NH₄⁺）直接损伤细胞膜。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001520', 'source-doc-4c784a84a66adf221597', 'source-node-001518', '5', '1519', 'text', '核心诱因：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001521', 'source-doc-4c784a84a66adf221597', 'source-node-001520', '6', '1520', 'text', '施肥过量：株产 50kg 果树单次施复合肥＞1.5kg，土壤 EC 值＞2.5mS/cm 时，烧根率达 70%。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001522', 'source-doc-4c784a84a66adf221597', 'source-node-001520', '6', '1521', 'text', '含氯肥料：氯化铵、氯化钾导致叶片 Cl⁻含量＞0.8%，出现急性落叶（24 小时内老叶脱光）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001523', 'source-doc-4c784a84a66adf221597', 'source-node-001520', '6', '1522', 'text', '未腐熟有机肥：新鲜鸡粪施后产生高温（＞50℃）和有机酸，根系褐变率＞60%。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001524', 'source-doc-4c784a84a66adf221597', 'source-node-001518', '5', '1523', 'text', '症状分级：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001525', 'source-doc-4c784a84a66adf221597', 'source-node-001524', '6', '1524', 'text', '轻度：老叶尖黄化，新梢抽发延迟，根系须根坏死率＜30%。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001526', 'source-doc-4c784a84a66adf221597', 'source-node-001524', '6', '1525', 'text', '中度：叶片卷曲焦枯，落果率 15%-30%，主根皮层剥离。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001527', 'source-doc-4c784a84a66adf221597', 'source-node-001524', '6', '1526', 'text', '重度：整株枯萎，根系腐烂呈 “麻布状”，死亡率＞50%。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001528', 'source-doc-4c784a84a66adf221597', 'source-node-001515', '4', '1527', 'text', '预防方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001529', 'source-doc-4c784a84a66adf221597', 'source-node-001528', '5', '1528', 'text', '精准施肥技术：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001530', 'source-doc-4c784a84a66adf221597', 'source-node-001529', '6', '1529', 'text', '土壤检测：每年采果后检测 pH、EC 值及全盐量，调整施肥方案。酸性土壤（pH＜5.5）需补钙镁磷肥 50kg / 亩。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001531', 'source-doc-4c784a84a66adf221597', 'source-node-001529', '6', '1530', 'text', '配方施肥：采用 “控氮、稳磷、增钾、补中微” 策略，氮磷钾比例 1:0.5:0.8，膨果期增施钾肥（硫酸钾 10kg / 亩）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001532', 'source-doc-4c784a84a66adf221597', 'source-node-001528', '5', '1531', 'text', '肥料安全管理：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001533', 'source-doc-4c784a84a66adf221597', 'source-node-001532', '6', '1532', 'text', '含氯肥料禁用：忌用氯化铵、氯化钾，改用硫酸钾、硝酸钾，Cl⁻敏感品种（如沙田柚）禁用含氯复合肥。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001534', 'source-doc-4c784a84a66adf221597', 'source-node-001532', '6', '1533', 'text', '有机肥腐熟：鸡粪需堆沤 60 天（加入 EM 菌剂），温度达 55℃后翻堆 3 次，使有机质含量＞30%。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001535', 'source-doc-4c784a84a66adf221597', 'source-node-001528', '5', '1534', 'text', '灌溉协同调控：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001536', 'source-doc-4c784a84a66adf221597', 'source-node-001535', '6', '1535', 'text', '水肥一体化：滴灌系统设置 EC 值上限 1.8mS/cm，施肥后冲洗管道 30 分钟，防止盐分积累。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001537', 'source-doc-4c784a84a66adf221597', 'source-node-001535', '6', '1536', 'text', '干旱期管理：土壤含水量＜60% 时，施肥前灌水 20-30L / 株，避免干施。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001538', 'source-doc-4c784a84a66adf221597', 'source-node-001515', '4', '1537', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001539', 'source-doc-4c784a84a66adf221597', 'source-node-001538', '5', '1538', 'text', '根系修复药剂（按复壮速度排序）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001540', 'source-doc-4c784a84a66adf221597', 'source-node-001539', '6', '1539', 'text', '腐殖酸水溶肥 + 微生物菌剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001541', 'source-doc-4c784a84a66adf221597', 'source-node-001540', '7', '1540', 'text', '作用机制：腐殖酸降低土壤溶液渗透压（降幅 40%），枯草芽孢杆菌促进新根萌发（日均生长量 0.8cm）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001542', 'source-doc-4c784a84a66adf221597', 'source-node-001540', '7', '1541', 'text', '使用技术：肥害后立即灌根，腐殖酸（500 倍液）+ 菌剂（1000 倍液），每株用量 10-15L，间隔 7 天再施 1 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001543', 'source-doc-4c784a84a66adf221597', 'source-node-001539', '6', '1542', 'text', '海藻酸 + 螯合钙：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001544', 'source-doc-4c784a84a66adf221597', 'source-node-001543', '7', '1543', 'text', '作用机制：海藻多糖修复细胞膜，螯合钙（糖醇钙）增强细胞壁韧性，根系活力恢复率达 75%。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001545', 'source-doc-4c784a84a66adf221597', 'source-node-001543', '7', '1544', 'text', '使用技术：叶面喷施海藻酸（800 倍液）+ 糖醇钙（1000 倍液），重点喷淋新梢，间隔 5 天喷 1 次，连续 3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001546', 'source-doc-4c784a84a66adf221597', 'source-node-001539', '6', '1545', 'text', '黄腐酸钾：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001547', 'source-doc-4c784a84a66adf221597', 'source-node-001546', '7', '1546', 'text', '作用机制：吸附土壤中过量离子（吸附率＞80%），促进根系呼吸酶活性提升 50%。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001548', 'source-doc-4c784a84a66adf221597', 'source-node-001546', '7', '1547', 'text', '使用技术：土壤撒施黄腐酸钾（2kg / 亩），结合中耕松土 15cm，7 天后根系褐变减轻。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001549', 'source-doc-4c784a84a66adf221597', 'source-node-001538', '5', '1548', 'text', '营养矫正药剂（按吸收效率排序）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001550', 'source-doc-4c784a84a66adf221597', 'source-node-001549', '6', '1549', 'text', 'EDTA 螯合铁：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001551', 'source-doc-4c784a84a66adf221597', 'source-node-001550', '7', '1550', 'text', '作用机制：在 pH 6.0-8.0 条件下稳定存在，铁吸收效率是硫酸亚铁的 10 倍，黄化矫正率＞90%。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001552', 'source-doc-4c784a84a66adf221597', 'source-node-001550', '7', '1551', 'text', '使用技术：新梢期喷施 3000 倍液，配合 0.1% 柠檬酸调节 pH 至 5.5，间隔 10 天喷 1 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001553', 'source-doc-4c784a84a66adf221597', 'source-node-001549', '6', '1552', 'text', '硼源库（糖醇硼）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001554', 'source-doc-4c784a84a66adf221597', 'source-node-001553', '7', '1553', 'text', '作用机制：糖醇载体促进硼在韧皮部运输，矫治缺硼导致的畸形果（畸形率降低 60%）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001555', 'source-doc-4c784a84a66adf221597', 'source-node-001553', '7', '1554', 'text', '使用技术：幼果期和膨大期各喷 1 次 1500 倍液，配合钙源库增效。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001556', 'source-doc-4c784a84a66adf221597', 'source-node-001549', '6', '1555', 'text', '硫酸锌 + 钼酸铵：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001557', 'source-doc-4c784a84a66adf221597', 'source-node-001556', '7', '1556', 'text', '作用机制：锌（Zn²⁺）促进生长素合成，钼（Mo）参与硝酸还原酶活性，协同矫治小叶簇生症。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001558', 'source-doc-4c784a84a66adf221597', 'source-node-001556', '7', '1557', 'text', '使用技术：春梢萌芽期喷施 0.3% 硫酸锌 + 0.05% 钼酸铵，连续 2 次，间隔 7 天。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001559', 'source-doc-4c784a84a66adf221597', 'source-node-000546', '2', '1558', 'text', '虫害（以后补）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001560', 'source-doc-4c784a84a66adf221597', 'source-node-001559', '3', '1559', 'text', '柑橘红蜘蛛', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001561', 'source-doc-4c784a84a66adf221597', 'source-node-001560', '4', '1560', 'text', '发病规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001562', 'source-doc-4c784a84a66adf221597', 'source-node-001561', '5', '1561', 'text', '为害特点：成螨、若螨群集叶背吸食汁液，初期叶片出现灰白色小点，严重时全叶灰白脱落，幼果受害后表面出现淡绿色斑点，成熟果呈淡黄色斑点，导致落果和品质下降。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001563', 'source-doc-4c784a84a66adf221597', 'source-node-001561', '5', '1562', 'text', '发生周期：1 年发生 16-22 代，世代重叠严重，以卵或成螨在叶背、枝条越冬。春梢期（3-5 月）和秋季（9-11 月）为两个爆发高峰，高温干旱（25-30℃）时繁殖最快，多雨季节虫口下降。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001564', 'source-doc-4c784a84a66adf221597', 'source-node-001561', '5', '1563', 'text', '环境影响：砂质土壤、树势衰弱、过度使用广谱农药（如有机磷类）的果园易爆发，天敌（捕食螨、多毛菌）被破坏后易失控。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001565', 'source-doc-4c784a84a66adf221597', 'source-node-001560', '4', '1564', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001566', 'source-doc-4c784a84a66adf221597', 'source-node-001565', '5', '1565', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001567', 'source-doc-4c784a84a66adf221597', 'source-node-001560', '4', '1566', 'text', '预防方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001568', 'source-doc-4c784a84a66adf221597', 'source-node-001567', '5', '1567', 'text', '农业调控：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001569', 'source-doc-4c784a84a66adf221597', 'source-node-001568', '6', '1568', 'text', '冬季清园：剪除枯枝、病虫枝，喷施 1-2 波美度石硫合剂或 99% 矿物油 100 倍液，杀灭越冬虫源', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001570', 'source-doc-4c784a84a66adf221597', 'source-node-001568', '6', '1569', 'text', '生草栽培：保留藿香蓟、三叶草等杂草，为捕食螨提供栖息场所，调节田间小气候。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001571', 'source-doc-4c784a84a66adf221597', 'source-node-001568', '6', '1570', 'text', '平衡施肥：增施有机肥（每亩 2000-3000 公斤），避免偏施氮肥，增强树势。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001572', 'source-doc-4c784a84a66adf221597', 'source-node-001567', '5', '1571', 'text', '生物防控：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001573', 'source-doc-4c784a84a66adf221597', 'source-node-001572', '6', '1572', 'text', '释放抗药性捕食螨（如巴氏新小绥螨）：在红蜘蛛低密度时（每叶≤2 头）释放，每株挂 1 袋（约 1000 头），7-10 天见效，持效期 2-3 个月。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001574', 'source-doc-4c784a84a66adf221597', 'source-node-001572', '6', '1573', 'text', '保护天敌：避免使用广谱杀虫剂，保留多毛菌等自然天敌。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001575', 'source-doc-4c784a84a66adf221597', 'source-node-001560', '4', '1574', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001576', 'source-doc-4c784a84a66adf221597', 'source-node-001575', '5', '1575', 'text', '核心策略：以 “杀卵 + 杀成螨” 复配药剂为主，结合温度和生育期选择配方。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001577', 'source-doc-4c784a84a66adf221597', 'source-node-001575', '5', '1576', 'text', '叶面喷施药剂（按效果排序）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001578', 'source-doc-4c784a84a66adf221597', 'source-node-001577', '6', '1577', 'text', '乙唑螨腈・螺螨酯（30% 悬浮剂）：复配药剂，同时杀卵和成螨，低温（15℃以下）仍高效，2000-4000 倍液喷雾，持效期 25-30 天。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001579', 'source-doc-4c784a84a66adf221597', 'source-node-001577', '6', '1578', 'text', '联苯肼酯・乙螨唑（43% 悬浮剂）：对各虫态均有效，安全性高，适合花期和幼果期，3000-4000 倍液，持效期 20-25 天nyncj.gxhz.gov.cn。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001580', 'source-doc-4c784a84a66adf221597', 'source-node-001577', '6', '1579', 'text', '阿维菌素・螺螨酯（20% 悬浮剂）：阿维菌素触杀成螨，螺螨酯长效杀卵，1500-2000 倍液，适合中等发生果园，注意轮换使用', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001581', 'source-doc-4c784a84a66adf221597', 'source-node-001577', '6', '1580', 'text', '矿物油（99% 乳油）：物理窒息作用，150-200 倍液可兼治蚧壳虫和煤烟病，高温（＞30℃）慎用，避免烧叶', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001582', 'source-doc-4c784a84a66adf221597', 'source-node-001577', '6', '1581', 'text', '炔螨特（73% 乳油）：高温（25℃以上）效果显著，1500-2000 倍液，对成螨杀伤力强，但对幼嫩组织敏感，需控制浓度。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001583', 'source-doc-4c784a84a66adf221597', 'source-node-001575', '5', '1582', 'text', '轮换策略：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001584', 'source-doc-4c784a84a66adf221597', 'source-node-001583', '6', '1583', 'text', '春梢期：乙唑螨腈・螺螨酯 → 联苯肼酯・乙螨唑', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001585', 'source-doc-4c784a84a66adf221597', 'source-node-001583', '6', '1584', 'text', '秋季：阿维菌素・螺螨酯 → 矿物油', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001586', 'source-doc-4c784a84a66adf221597', 'source-node-001583', '6', '1585', 'text', '严重爆发时：乙唑螨腈・螺螨酯 + 矿物油（1:1 混用），7 天后补喷一次', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001587', 'source-doc-4c784a84a66adf221597', 'source-node-001559', '3', '1586', 'text', '柑橘木虱（柑橘黄龙病中已经介绍）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001588', 'source-doc-4c784a84a66adf221597', 'source-node-001587', '4', '1587', 'text', '发病规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001589', 'source-doc-4c784a84a66adf221597', 'source-node-001588', '5', '1588', 'text', '为害特点：成虫、若虫群集新梢吸食汁液，导致嫩梢萎缩、畸形，分泌蜜露诱发煤烟病。更严重的是，木虱是柑橘黄龙病唯一田间传播媒介，叮咬 3-4 小时即可传毒尤溪县人民政府。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001590', 'source-doc-4c784a84a66adf221597', 'source-node-001588', '5', '1589', 'text', '发生周期：1 年发生 8-14 代，春梢（3-4 月）、夏梢（6-7 月）、秋梢（8-9 月）抽发期为三个高峰期，冬季以成虫在叶背越冬尤溪县人民政府。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001591', 'source-doc-4c784a84a66adf221597', 'source-node-001588', '5', '1590', 'text', '传播风险：在黄龙病疫区，木虱防控直接决定病害扩散速度，病树率每增加 1%，木虱密度上升 15%-20%。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001592', 'source-doc-4c784a84a66adf221597', 'source-node-001587', '4', '1591', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001593', 'source-doc-4c784a84a66adf221597', 'source-node-001592', '5', '1592', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001594', 'source-doc-4c784a84a66adf221597', 'source-node-001587', '4', '1593', 'text', '预防方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001595', 'source-doc-4c784a84a66adf221597', 'source-node-001594', '5', '1594', 'text', '农业防控：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001596', 'source-doc-4c784a84a66adf221597', 'source-node-001595', '6', '1595', 'text', '统一放梢：抹除零星抽发的新梢，集中在成虫低峰期（如 5 月底）放梢，减少产卵机会', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001597', 'source-doc-4c784a84a66adf221597', 'source-node-001595', '6', '1596', 'text', '清除病树：发现黄龙病树立即挖除，挖除前先喷药杀灭木虱，防止迁移传毒尤溪县人民政府。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001598', 'source-doc-4c784a84a66adf221597', 'source-node-001595', '6', '1597', 'text', '种植隔离带：在果园周边种植非芸香科植物（如杉树），阻隔木虱迁飞', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001599', 'source-doc-4c784a84a66adf221597', 'source-node-001594', '5', '1598', 'text', '物理诱杀：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001600', 'source-doc-4c784a84a66adf221597', 'source-node-001599', '6', '1599', 'text', '悬挂黄色粘虫板：每亩 20-25 张，高度与树冠中上部持平，诱杀成虫尤溪县人民政府。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001601', 'source-doc-4c784a84a66adf221597', 'source-node-001599', '6', '1600', 'text', '频振式杀虫灯：每 30-50 亩安装 1 盏，夜间诱杀成虫', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001602', 'source-doc-4c784a84a66adf221597', 'source-node-001587', '4', '1601', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001603', 'source-doc-4c784a84a66adf221597', 'source-node-001602', '5', '1602', 'text', '核心策略：以 “新梢期重点防控 + 全年压低虫口” 为原则，优先使用内吸性药剂。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001604', 'source-doc-4c784a84a66adf221597', 'source-node-001602', '5', '1603', 'text', '叶面喷施药剂（按效果排序）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001605', 'source-doc-4c784a84a66adf221597', 'source-node-001604', '6', '1604', 'text', '22% 氟啶虫胺腈悬浮剂：作用于昆虫神经系统，对成虫和若虫均高效，5000 倍液喷雾，持效期 15-20 天，对黄龙病传播阻断率达 90% 以上尤溪县人民政府。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001606', 'source-doc-4c784a84a66adf221597', 'source-node-001604', '6', '1605', 'text', '22.4% 螺虫乙酯悬浮剂：双向内吸传导，杀卵和若虫效果突出，5000 倍液，持效期 25-30 天，适合春梢和秋梢期使用尤溪县人民政府。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001607', 'source-doc-4c784a84a66adf221597', 'source-node-001604', '6', '1606', 'text', '20% 甲氰菊酯・噻虫胺（复配剂）：菊酯类快速击倒成虫，噻虫胺内吸持效，2000 倍液，在夏梢期成虫高峰期使用衢州市农业农村局 衢州农业农村信息网。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001608', 'source-doc-4c784a84a66adf221597', 'source-node-001604', '6', '1607', 'text', '10% 吡丙醚・吡虫啉悬浮剂：抑制若虫蜕皮和成虫产卵，1000 倍液，在新梢萌发前喷施，减少下一代虫口nyncj.gxhz.gov.cn。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001609', 'source-doc-4c784a84a66adf221597', 'source-node-001602', '5', '1608', 'text', '轮换策略：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001610', 'source-doc-4c784a84a66adf221597', 'source-node-001609', '6', '1609', 'text', '春梢期：氟啶虫胺腈 → 螺虫乙酯', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001611', 'source-doc-4c784a84a66adf221597', 'source-node-001609', '6', '1610', 'text', '夏梢期：甲氰菊酯・噻虫胺 → 吡丙醚・吡虫啉', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001612', 'source-doc-4c784a84a66adf221597', 'source-node-001609', '6', '1611', 'text', '秋梢期：螺虫乙酯 → 氟啶虫胺腈', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001613', 'source-doc-4c784a84a66adf221597', 'source-node-001559', '3', '1612', 'text', '柑橘潜叶蛾（鬼画符）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001614', 'source-doc-4c784a84a66adf221597', 'source-node-001613', '4', '1613', 'text', '发病规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001615', 'source-doc-4c784a84a66adf221597', 'source-node-001614', '5', '1614', 'text', '为害特点：幼虫潜入嫩叶表皮蛀食，形成弯曲虫道，导致叶片卷曲硬化、脱落，伤口易诱发溃疡病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001616', 'source-doc-4c784a84a66adf221597', 'source-node-001614', '5', '1615', 'text', '发生周期：1 年发生 9-15 代，以蛹在叶缘越冬。夏梢（6-7 月）和秋梢（8-9 月）抽发期为爆发高峰，高温多雨（24-28℃）时为害最重，苗木和幼树受害更严重', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001617', 'source-doc-4c784a84a66adf221597', 'source-node-001614', '5', '1616', 'text', '传播途径：成虫夜间活动，卵多产于嫩叶中脉两侧，幼虫孵化后立即蛀入叶片。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001618', 'source-doc-4c784a84a66adf221597', 'source-node-001613', '4', '1617', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001619', 'source-doc-4c784a84a66adf221597', 'source-node-001618', '5', '1618', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001620', 'source-doc-4c784a84a66adf221597', 'source-node-001613', '4', '1619', 'text', '预防方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001621', 'source-doc-4c784a84a66adf221597', 'source-node-001620', '5', '1620', 'text', '农业调控：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001622', 'source-doc-4c784a84a66adf221597', 'source-node-001621', '6', '1621', 'text', '统一放梢：抹除零星抽发的夏梢和秋梢，集中在成虫低峰期（如 7 月下旬）放梢，减少产卵机会', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001623', 'source-doc-4c784a84a66adf221597', 'source-node-001621', '6', '1622', 'text', '修剪清园：冬季剪除被害枝叶，减少越冬虫源。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001624', 'source-doc-4c784a84a66adf221597', 'source-node-001620', '5', '1623', 'text', '物理诱杀：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001625', 'source-doc-4c784a84a66adf221597', 'source-node-001624', '6', '1624', 'text', '悬挂性信息素诱捕器：每亩 3-5 个，监测成虫高峰期，指导喷药时机', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001626', 'source-doc-4c784a84a66adf221597', 'source-node-001613', '4', '1625', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001627', 'source-doc-4c784a84a66adf221597', 'source-node-001626', '5', '1626', 'text', '叶面喷施药剂（按效果排序）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001628', 'source-doc-4c784a84a66adf221597', 'source-node-001627', '6', '1627', 'text', '5% 虱螨脲乳油：抑制几丁质合成，杀卵和低龄幼虫效果显著，1500-2500 倍液，持效期 10-15 天，对潜叶蛾虫道修复效果最佳衢州市农业农村局 衢州农业农村信息网。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001629', 'source-doc-4c784a84a66adf221597', 'source-node-001627', '6', '1628', 'text', '2.5% 联苯菊酯水乳剂：触杀和胃毒作用，2500-3000 倍液，快速击倒成虫，适合成虫高峰期使用衢州市农业农村局 衢州农业农村信息网。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001630', 'source-doc-4c784a84a66adf221597', 'source-node-001627', '6', '1629', 'text', '1.8% 阿维菌素乳油：兼治红蜘蛛和潜叶蛾，2000-4000 倍液，在新梢萌发后 5-7 天喷施衢州市农业农村局 衢州农业农村信息网。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001631', 'source-doc-4c784a84a66adf221597', 'source-node-001627', '6', '1630', 'text', '20% 氯虫苯甲酰胺悬浮剂：作用于昆虫肌肉系统，内吸传导性强，3000 倍液，持效期 20 天以上，适合长期防控', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001632', 'source-doc-4c784a84a66adf221597', 'source-node-001626', '5', '1631', 'text', '轮换策略：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001633', 'source-doc-4c784a84a66adf221597', 'source-node-001632', '6', '1632', 'text', '夏梢期：虱螨脲 → 联苯菊酯', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001634', 'source-doc-4c784a84a66adf221597', 'source-node-001632', '6', '1633', 'text', '秋梢期：氯虫苯甲酰胺 → 阿维菌素', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001635', 'source-doc-4c784a84a66adf221597', 'source-node-001559', '3', '1634', 'text', '柑橘蚜虫', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001636', 'source-doc-4c784a84a66adf221597', 'source-node-001635', '4', '1635', 'text', '发病规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001637', 'source-doc-4c784a84a66adf221597', 'source-node-001636', '5', '1636', 'text', '为害特点：成虫、若虫群集新梢、嫩叶吸食汁液，导致叶片卷曲、新梢萎缩，分泌蜜露诱发煤烟病，同时传播柑橘衰退病毒衢州市农业农村局 衢州农业农村信息网。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001638', 'source-doc-4c784a84a66adf221597', 'source-node-001636', '5', '1637', 'text', '发生周期：1 年发生 20-30 代，以卵在枝条裂缝越冬。春梢（3-4 月）和秋梢（9-10 月）抽发期为两个高峰，温暖干旱（20-25℃）时繁殖最快衢州市农业农村局 衢州农业农村信息网。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001639', 'source-doc-4c784a84a66adf221597', 'source-node-001636', '5', '1638', 'text', '环境影响：树势衰弱、通风不良的果园易爆发，天敌（瓢虫、蚜茧蜂）数量不足时虫口激增。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001640', 'source-doc-4c784a84a66adf221597', 'source-node-001635', '4', '1639', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001641', 'source-doc-4c784a84a66adf221597', 'source-node-001640', '5', '1640', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001642', 'source-doc-4c784a84a66adf221597', 'source-node-001635', '4', '1641', 'text', '预防方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001643', 'source-doc-4c784a84a66adf221597', 'source-node-001642', '5', '1642', 'text', '农业调控：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001644', 'source-doc-4c784a84a66adf221597', 'source-node-001643', '6', '1643', 'text', '抹除零星梢：及时抹除夏梢和晚秋梢，减少蚜虫食物来源衢州市农业农村局 衢州农业农村信息网。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001645', 'source-doc-4c784a84a66adf221597', 'source-node-001643', '6', '1644', 'text', '增强树势：增施有机肥和磷钾肥，避免过量氮肥导致新梢徒长衢州市农业农村局 衢州农业农村信息网。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001646', 'source-doc-4c784a84a66adf221597', 'source-node-001642', '5', '1645', 'text', '生物防控：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001647', 'source-doc-4c784a84a66adf221597', 'source-node-001646', '6', '1646', 'text', '保护天敌：保留果园杂草（如苜蓿），为瓢虫、蚜茧蜂提供栖息地，蚜虫密度＜5 头 / 梢时可不施药', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001648', 'source-doc-4c784a84a66adf221597', 'source-node-001635', '4', '1647', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001649', 'source-doc-4c784a84a66adf221597', 'source-node-001648', '5', '1648', 'text', '核心策略：以 “新梢期早防 + 虫口上升初期用药” 为原则，优先使用内吸性药剂。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001650', 'source-doc-4c784a84a66adf221597', 'source-node-001648', '5', '1649', 'text', '叶面喷施药剂（按效果排序）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001651', 'source-doc-4c784a84a66adf221597', 'source-node-001650', '6', '1650', 'text', '25% 噻虫嗪水分散粒剂：内吸传导性强，作用于昆虫神经系统，5000-8000 倍液，持效期 15-20 天，对蚜虫和木虱有兼治作用衢州市农业农村局 衢州农业农村信息网。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001652', 'source-doc-4c784a84a66adf221597', 'source-node-001650', '6', '1651', 'text', '10% 吡虫啉可湿性粉剂：经典烟碱类药剂，2500-3000 倍液，快速控制虫口，成本低，但需注意轮换衢州市农业农村局 衢州农业农村信息网。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001653', 'source-doc-4c784a84a66adf221597', 'source-node-001650', '6', '1652', 'text', '5% 啶虫脒乳油：触杀和胃毒作用，2000 倍液，对蚜虫和蓟马有特效，高温（＞25℃）时效果更佳衢州市农业农村局 衢州农业农村信息网。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001654', 'source-doc-4c784a84a66adf221597', 'source-node-001650', '6', '1653', 'text', '50% 抗蚜威可湿性粉剂：选择性杀蚜虫，对天敌安全，1000-1500 倍液，适合蚜虫爆发初期应急使用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001655', 'source-doc-4c784a84a66adf221597', 'source-node-001648', '5', '1654', 'text', '轮换策略：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001656', 'source-doc-4c784a84a66adf221597', 'source-node-001655', '6', '1655', 'text', '春梢期：噻虫嗪 → 吡虫啉', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001657', 'source-doc-4c784a84a66adf221597', 'source-node-001655', '6', '1656', 'text', '秋梢期：啶虫脒 → 抗蚜威', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001658', 'source-doc-4c784a84a66adf221597', 'source-node-001559', '3', '1657', 'text', '柑橘蚧壳虫（矢尖蚧、红蜡蚧）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001659', 'source-doc-4c784a84a66adf221597', 'source-node-001658', '4', '1658', 'text', '发病规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001660', 'source-doc-4c784a84a66adf221597', 'source-node-001659', '5', '1659', 'text', '为害特点：若虫和成虫固定在叶片、枝条、果实上吸食汁液，导致树势衰弱、叶片黄化，果实表面形成斑点，降低商品价值。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001661', 'source-doc-4c784a84a66adf221597', 'source-node-001659', '5', '1660', 'text', '发生周期：1 年发生 2-4 代，以受精雌成虫在枝叶越冬。第一代若虫孵化高峰期在 5 月中旬，第二代在 7 月下旬，第三代在 9 月上旬。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001662', 'source-doc-4c784a84a66adf221597', 'source-node-001659', '5', '1661', 'text', '环境影响：密植果园、通风透光差、过度使用高毒农药的果园易爆发。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001663', 'source-doc-4c784a84a66adf221597', 'source-node-001658', '4', '1662', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001664', 'source-doc-4c784a84a66adf221597', 'source-node-001663', '5', '1663', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001665', 'source-doc-4c784a84a66adf221597', 'source-node-001658', '4', '1664', 'text', '预防方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001666', 'source-doc-4c784a84a66adf221597', 'source-node-001665', '5', '1665', 'text', '农业调控：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001667', 'source-doc-4c784a84a66adf221597', 'source-node-001666', '6', '1666', 'text', '修剪疏枝：剪除过密枝、荫蔽枝，增强通风透光，减少蚧壳虫藏匿场所nyncj.gxhz.gov.cn。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001668', 'source-doc-4c784a84a66adf221597', 'source-node-001666', '6', '1667', 'text', '冬季清园：喷施 99% 矿物油 100 倍液或 3-5 波美度石硫合剂，杀灭越冬成虫', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001669', 'source-doc-4c784a84a66adf221597', 'source-node-001665', '5', '1668', 'text', '生物防控：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001670', 'source-doc-4c784a84a66adf221597', 'source-node-001669', '6', '1669', 'text', '释放天敌：在 5 月若虫孵化期释放蚜小蜂（如金黄蚜小蜂），每亩 1-2 万头，寄生率可达 70% 以上。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001671', 'source-doc-4c784a84a66adf221597', 'source-node-001658', '4', '1670', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001672', 'source-doc-4c784a84a66adf221597', 'source-node-001671', '5', '1671', 'text', '核心策略：以 “若虫孵化高峰期用药 + 休眠期清园” 为关键，优先使用内吸性药剂。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001673', 'source-doc-4c784a84a66adf221597', 'source-node-001671', '5', '1672', 'text', '叶面喷施药剂（按效果排序）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001674', 'source-doc-4c784a84a66adf221597', 'source-node-001673', '6', '1673', 'text', '24% 螺虫乙酯悬浮剂：双向内吸传导，对若虫和成虫均有效，3000-4000 倍液，持效期 30 天以上，适合防治矢尖蚧和红蜡蚧nyncj.gxhz.gov.cn。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001675', 'source-doc-4c784a84a66adf221597', 'source-node-001673', '6', '1674', 'text', '48% 毒死蜱乳油（在蔬菜、果树、茶叶、中草药材上不得使用）：触杀和胃毒作用，1000-1500 倍液，对蚧壳虫蜡质层有溶解作用，在若虫分散转移期使用效果最佳nyncj.gxhz.gov.cn。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001676', 'source-doc-4c784a84a66adf221597', 'source-node-001673', '6', '1675', 'text', '25% 噻嗪酮可湿性粉剂：抑制若虫蜕皮，1000-1500 倍液，需在若虫孵化初期喷施，持效期 15-20 天nyncj.gxhz.gov.cn。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001677', 'source-doc-4c784a84a66adf221597', 'source-node-001673', '6', '1676', 'text', '99% 矿物油乳油：物理窒息作用，150-200 倍液，可兼治煤烟病，在春梢萌芽前和采果后使用', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001678', 'source-doc-4c784a84a66adf221597', 'source-node-001671', '5', '1677', 'text', '轮换策略：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001679', 'source-doc-4c784a84a66adf221597', 'source-node-001678', '6', '1678', 'text', '第一代若虫期：螺虫乙酯 → 毒死蜱（在蔬菜、果树、茶叶、中草药材上不得使用）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001680', 'source-doc-4c784a84a66adf221597', 'source-node-001678', '6', '1679', 'text', '第二代若虫期：噻嗪酮 → 矿物油', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001681', 'source-doc-4c784a84a66adf221597', 'source-node-001559', '3', '1680', 'text', '柑橘天牛（星天牛、褐天牛）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001682', 'source-doc-4c784a84a66adf221597', 'source-node-001681', '4', '1681', 'text', '发病规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001683', 'source-doc-4c784a84a66adf221597', 'source-node-001682', '5', '1682', 'text', '为害特点：成虫啃食嫩枝皮层，幼虫蛀食树干基部和主根，导致树势衰弱、整株枯死，成虫高峰期在 5-8 月定南县人民政府。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001684', 'source-doc-4c784a84a66adf221597', 'source-node-001682', '5', '1683', 'text', '发生周期：星天牛 1 年 1 代，褐天牛 2 年 1 代，以幼虫在树干内越冬，成虫羽化后需补充营养（啃食嫩枝）才能产卵定南县人民政府。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001685', 'source-doc-4c784a84a66adf221597', 'source-node-001682', '5', '1684', 'text', '传播途径：成虫飞行距离可达 500 米，主要通过伤口和树皮裂缝产卵。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001686', 'source-doc-4c784a84a66adf221597', 'source-node-001681', '4', '1685', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001687', 'source-doc-4c784a84a66adf221597', 'source-node-001686', '5', '1686', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001688', 'source-doc-4c784a84a66adf221597', 'source-node-001681', '4', '1687', 'text', '预防方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001689', 'source-doc-4c784a84a66adf221597', 'source-node-001688', '5', '1688', 'text', '农业调控：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001690', 'source-doc-4c784a84a66adf221597', 'source-node-001689', '6', '1689', 'text', '树干涂白：用生石灰 10 公斤 + 硫磺 1 公斤 + 水 40 公斤调成糊状，涂刷树干基部（离地 1 米内），防止成虫产卵定南县人民政府。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001691', 'source-doc-4c784a84a66adf221597', 'source-node-001689', '6', '1690', 'text', '清除虫源：及时挖除枯死树和严重受害树，减少虫口基数定南县人民政府。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001692', 'source-doc-4c784a84a66adf221597', 'source-node-001688', '5', '1691', 'text', '人工捕杀：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001693', 'source-doc-4c784a84a66adf221597', 'source-node-001692', '6', '1692', 'text', '成虫期（5-8 月）中午人工捕捉星天牛，夜间捕捉褐天牛定南县人民政府。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001694', 'source-doc-4c784a84a66adf221597', 'source-node-001681', '4', '1693', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001695', 'source-doc-4c784a84a66adf221597', 'source-node-001694', '5', '1694', 'text', '核心策略：以 “成虫期诱杀 + 幼虫期毒杀” 为重点，结合物理和化学手段。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001696', 'source-doc-4c784a84a66adf221597', 'source-node-001694', '5', '1695', 'text', '成虫防治药剂', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001697', 'source-doc-4c784a84a66adf221597', 'source-node-001696', '6', '1696', 'text', '48% 毒死蜱乳油（在蔬菜、果树、茶叶、中草药材上不得使用）：1500 倍液喷雾树干和树冠，触杀成虫，持效期 7-10 天定南。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001698', 'source-doc-4c784a84a66adf221597', 'source-node-001696', '6', '1697', 'text', '2.5% 溴氰菊酯乳油：2000-3000 倍液，快速击倒成虫，在成虫羽化高峰期喷施定。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001699', 'source-doc-4c784a84a66adf221597', 'source-node-001694', '5', '1698', 'text', '幼虫防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001700', 'source-doc-4c784a84a66adf221597', 'source-node-001699', '6', '1699', 'text', '药剂灌根：发现树干基部有虫粪排出时，用注射器向虫孔注入 40% 毒死蜱乳油（在蔬菜、果树、茶叶、中草药材上不得使用） 50 倍液，每孔 5-10 毫升，然后用湿泥封口。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001701', 'source-doc-4c784a84a66adf221597', 'source-node-001699', '6', '1700', 'text', '药棉堵塞：用棉球蘸取 80% 敌敌畏乳油 100 倍液，塞入虫孔，外用泥土封闭，熏杀幼虫', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001702', 'source-doc-4c784a84a66adf221597', 'source-node-001694', '5', '1701', 'text', '注意事项： 每年 4-5 月和 7-8 月检查树干基部，发现新鲜虫粪立即处理。 成虫羽化前（4 月）对树干基部周围土壤喷施毒死蜱（在蔬菜、果树、茶叶、中草药材上不得使用）颗粒剂（每亩 2 公斤），杀灭出土成虫。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001703', 'source-doc-4c784a84a66adf221597', 'source-node-001559', '3', '1702', 'text', '柑橘蓟马', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001704', 'source-doc-4c784a84a66adf221597', 'source-node-001703', '4', '1703', 'text', '发病规律：成虫和若虫锉吸花器和幼果汁液，导致花器脱落、果实畸形，高温干旱季节（6-8 月）为害最重衢州市农业农村局 衢州农业农村信息网', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001705', 'source-doc-4c784a84a66adf221597', 'source-node-001703', '4', '1704', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001706', 'source-doc-4c784a84a66adf221597', 'source-node-001705', '5', '1705', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001707', 'source-doc-4c784a84a66adf221597', 'source-node-001703', '4', '1706', 'text', '防治方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001708', 'source-doc-4c784a84a66adf221597', 'source-node-001707', '5', '1707', 'text', '叶面喷施：25% 噻虫嗪 5000 倍液或 6% 乙基多杀菌素 2000 倍液，重点喷施花和幼果鄂尔多斯市农牧局。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001709', 'source-doc-4c784a84a66adf221597', 'source-node-001707', '5', '1708', 'text', '物理诱杀：悬挂蓝色粘虫板，每亩 20-30 张，诱杀成虫鄂尔多斯市农牧局。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001710', 'source-doc-4c784a84a66adf221597', 'source-node-001559', '3', '1709', 'text', '柑橘花蕾蛆', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001711', 'source-doc-4c784a84a66adf221597', 'source-node-001710', '4', '1710', 'text', '发病规律：成虫在花蕾露白时产卵，幼虫蛀食花蕾，导致花蕾膨大呈灯笼状，无法开放尤溪县人民政府。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001712', 'source-doc-4c784a84a66adf221597', 'source-node-001710', '4', '1711', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001713', 'source-doc-4c784a84a66adf221597', 'source-node-001712', '5', '1712', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001714', 'source-doc-4c784a84a66adf221597', 'source-node-001710', '4', '1713', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001715', 'source-doc-4c784a84a66adf221597', 'source-node-001714', '5', '1714', 'text', '地面施药：花蕾露白前，每亩用 50% 辛硫磷乳油 200 毫升拌细土 15 公斤撒施地面，杀灭出土成虫尤溪县人民政府。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001716', 'source-doc-4c784a84a66adf221597', 'source-node-001714', '5', '1715', 'text', '树冠喷药：花蕾大部分现白时，喷施 48% 丙・敌乳油 1000 倍液或 10% 氯氰菊酯 1500 倍液尤溪县人民政府。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001717', 'source-doc-4c784a84a66adf221597', 'source-node-001559', '3', '1716', 'text', '柑橘线虫', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001718', 'source-doc-4c784a84a66adf221597', 'source-node-001717', '4', '1717', 'text', '20%噻唑磷1000-1500倍、50%辛硫磷1500倍、10亿g淡紫拟青霉1kg、3%阿维菌素1500倍、傲生微生物菌剂800-1000倍', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001719', 'source-doc-4c784a84a66adf221597', 'source-node-000545', '1', '1718', 'text', '2.1.2 百香果（资料较少）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001720', 'source-doc-4c784a84a66adf221597', 'source-node-001719', '2', '1719', 'text', '细菌性病害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001721', 'source-doc-4c784a84a66adf221597', 'source-node-001720', '3', '1720', 'text', '软腐病（欧氏杆菌）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001722', 'source-doc-4c784a84a66adf221597', 'source-node-001721', '4', '1721', 'text', '发病规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001723', 'source-doc-4c784a84a66adf221597', 'source-node-001722', '5', '1722', 'text', '为害特点：主要危害果实和茎蔓，初期水渍状病斑，后期软化腐烂，有恶臭味。高温多雨（25-30℃）季节易爆发，果实伤口（如虫咬、机械伤）是主要侵染途径。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001724', 'source-doc-4c784a84a66adf221597', 'source-node-001722', '5', '1723', 'text', '传播途径：病菌通过雨水、灌溉水及农事操作传播。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001725', 'source-doc-4c784a84a66adf221597', 'source-node-001721', '4', '1724', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001726', 'source-doc-4c784a84a66adf221597', 'source-node-001725', '5', '1725', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001727', 'source-doc-4c784a84a66adf221597', 'source-node-001721', '4', '1726', 'text', '预防方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001728', 'source-doc-4c784a84a66adf221597', 'source-node-001727', '5', '1727', 'text', '农业调控：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001729', 'source-doc-4c784a84a66adf221597', 'source-node-001728', '6', '1728', 'text', '果实套袋前喷施 20% 噻菌铜 500 倍液，晾干后套袋。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001730', 'source-doc-4c784a84a66adf221597', 'source-node-001728', '6', '1729', 'text', '防治果蝇、实蝇等害虫，减少果实伤口。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001731', 'source-doc-4c784a84a66adf221597', 'source-node-001727', '5', '1730', 'text', '物理防控：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001732', 'source-doc-4c784a84a66adf221597', 'source-node-001731', '6', '1731', 'text', '田间悬挂糖醋液（糖：醋: 酒：水 = 3:1:1:10）诱杀成虫。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001733', 'source-doc-4c784a84a66adf221597', 'source-node-001721', '4', '1732', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001734', 'source-doc-4c784a84a66adf221597', 'source-node-001733', '5', '1733', 'text', '47% 春雷・王铜可湿性粉剂：500 倍液，铜制剂 + 生物源杀菌剂，内吸性强，发病初期每隔 7 天喷一次，连续 2 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001735', 'source-doc-4c784a84a66adf221597', 'source-node-001733', '5', '1734', 'text', '20% 噻菌铜悬浮剂：600 倍液，对细菌性病害特效，可与中生菌素交替使用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001736', 'source-doc-4c784a84a66adf221597', 'source-node-001733', '5', '1735', 'text', '2% 春雷霉素水剂：800 倍液，配合有机硅助剂增强渗透性，重点喷施果实和茎蔓。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001737', 'source-doc-4c784a84a66adf221597', 'source-node-001733', '5', '1736', 'text', '注意事项：病果需及时摘除并带出果园销毁，避免交叉感染。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001738', 'source-doc-4c784a84a66adf221597', 'source-node-001720', '3', '1737', 'text', '溃疡病（黄单胞杆菌）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001739', 'source-doc-4c784a84a66adf221597', 'source-node-001738', '4', '1738', 'text', '发病规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001740', 'source-doc-4c784a84a66adf221597', 'source-node-001739', '5', '1739', 'text', '为害特点：主要危害叶片和果实，初期油渍状小斑点，后期中央凹陷呈火山口状，周围有黄色晕圈。高温多雨（28-32℃）季节易爆发，台风或暴雨后发病加重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001741', 'source-doc-4c784a84a66adf221597', 'source-node-001739', '5', '1740', 'text', '传播途径：病菌通过风雨、昆虫及修剪工具传播。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001742', 'source-doc-4c784a84a66adf221597', 'source-node-001738', '4', '1741', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001743', 'source-doc-4c784a84a66adf221597', 'source-node-001742', '5', '1742', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001744', 'source-doc-4c784a84a66adf221597', 'source-node-001738', '4', '1743', 'text', '预防方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001745', 'source-doc-4c784a84a66adf221597', 'source-node-001744', '5', '1744', 'text', '农业调控：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001746', 'source-doc-4c784a84a66adf221597', 'source-node-001745', '6', '1745', 'text', '修剪后及时喷施 1% 波尔多液，保护伤口。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001747', 'source-doc-4c784a84a66adf221597', 'source-node-001745', '6', '1746', 'text', '避免过度密植，保持通风透光。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001748', 'source-doc-4c784a84a66adf221597', 'source-node-001744', '5', '1747', 'text', '物理防控：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001749', 'source-doc-4c784a84a66adf221597', 'source-node-001748', '6', '1748', 'text', '修剪工具用 75% 酒精消毒，避免交叉传染。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001750', 'source-doc-4c784a84a66adf221597', 'source-node-001738', '4', '1749', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001751', 'source-doc-4c784a84a66adf221597', 'source-node-001750', '5', '1750', 'text', '20% 噻唑锌悬浮剂：500 倍液，内吸性强，对溃疡病特效，发病初期每隔 5 天喷一次，连续 2 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001752', 'source-doc-4c784a84a66adf221597', 'source-node-001750', '5', '1751', 'text', '33.5% 喹啉铜悬浮剂：800 倍液，铜制剂中安全性较高，可在幼果期使用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001753', 'source-doc-4c784a84a66adf221597', 'source-node-001750', '5', '1752', 'text', '2% 中生菌素水剂：1000 倍液，生物源杀菌剂，可与化学药剂轮换使用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001754', 'source-doc-4c784a84a66adf221597', 'source-node-001750', '5', '1753', 'text', '注意事项：高温（＞30℃）时避免使用无机铜制剂，防止烧叶。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001755', 'source-doc-4c784a84a66adf221597', 'source-node-001719', '2', '1754', 'text', '真菌性病害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001756', 'source-doc-4c784a84a66adf221597', 'source-node-001755', '3', '1755', 'text', '百香果茎基腐（刀菌 / 疫霉菌复合侵染）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001757', 'source-doc-4c784a84a66adf221597', 'source-node-001756', '4', '1756', 'text', '发病规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001758', 'source-doc-4c784a84a66adf221597', 'source-node-001757', '5', '1757', 'text', '为害特点：主要危害根颈部，初期水渍状褐斑，后期皮层腐烂，植株黄化枯死。5-8 月雨季为高发期，酸性土壤（pH＜5.5）、排水不良的果园发病率可达 30%-50%。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001759', 'source-doc-4c784a84a66adf221597', 'source-node-001757', '5', '1758', 'text', '传播途径：病菌通过土壤、灌溉水传播，农事操作或虫害造成的伤口是主要侵染途径。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001760', 'source-doc-4c784a84a66adf221597', 'source-node-001756', '4', '1759', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001761', 'source-doc-4c784a84a66adf221597', 'source-node-001760', '5', '1760', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001762', 'source-doc-4c784a84a66adf221597', 'source-node-001756', '4', '1761', 'text', '预防方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001763', 'source-doc-4c784a84a66adf221597', 'source-node-001762', '5', '1762', 'text', '农业调控：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001764', 'source-doc-4c784a84a66adf221597', 'source-node-001763', '6', '1763', 'text', '选用抗病品种（如黄金百香果），与水稻、玉米等非茄科作物轮作 2-3 年。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001765', 'source-doc-4c784a84a66adf221597', 'source-node-001763', '6', '1764', 'text', '起垄栽培（垄高 30-40cm），雨季及时排水，降低土壤湿度。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001766', 'source-doc-4c784a84a66adf221597', 'source-node-001763', '6', '1765', 'text', '定植前用 50% 多菌灵 500 倍液蘸根，或撒施生石灰（50kg / 亩）调节土壤 pH 至 6.0-6.5。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001767', 'source-doc-4c784a84a66adf221597', 'source-node-001762', '5', '1766', 'text', '生物防控：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001768', 'source-doc-4c784a84a66adf221597', 'source-node-001767', '6', '1767', 'text', '定植时穴施枯草芽孢杆菌（100 亿 CFU/g）20g / 株，抑制病原菌繁殖。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001769', 'source-doc-4c784a84a66adf221597', 'source-node-001756', '4', '1768', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001770', 'source-doc-4c784a84a66adf221597', 'source-node-001769', '5', '1769', 'text', '68% 精甲霜・锰锌水分散粒剂：1000 倍液，内吸性强，对疫霉菌特效，发病初期每株灌 200-300ml，持效期 15 天。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001771', 'source-doc-4c784a84a66adf221597', 'source-node-001769', '5', '1770', 'text', '30% 恶霉灵水剂：800 倍液，配合嘉美红利 1000 倍液淋根，促进新根生长，连续灌根 2 次（间隔 7 天）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001772', 'source-doc-4c784a84a66adf221597', 'source-node-001769', '5', '1771', 'text', '50% 敌克松可湿性粉剂：600 倍液，强氧化性杀灭镰刀菌，但需现配现用，避免与碱性药剂混用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001773', 'source-doc-4c784a84a66adf221597', 'source-node-001769', '5', '1772', 'text', '注意：病株需连根拔除，病穴撒生石灰消毒，周围健康植株预防性灌根。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001774', 'source-doc-4c784a84a66adf221597', 'source-node-001755', '3', '1773', 'text', '百香果炭疽病（胶孢炭疽菌）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001775', 'source-doc-4c784a84a66adf221597', 'source-node-001774', '4', '1774', 'text', '发病规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001776', 'source-doc-4c784a84a66adf221597', 'source-node-001775', '5', '1775', 'text', '为害特点：主要危害果实和叶片，幼果初期水浸状黑斑，后期凹陷坏死；叶片病斑呈轮纹状，严重时落叶落果。高温多雨（25-30℃）季节易爆发，树势衰弱或偏施氮肥的果园发病率高。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001777', 'source-doc-4c784a84a66adf221597', 'source-node-001775', '5', '1776', 'text', '传播途径：病菌以分生孢子借风雨传播，伤口或自然孔口侵入。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001778', 'source-doc-4c784a84a66adf221597', 'source-node-001774', '4', '1777', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001779', 'source-doc-4c784a84a66adf221597', 'source-node-001778', '5', '1778', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001780', 'source-doc-4c784a84a66adf221597', 'source-node-001774', '4', '1779', 'text', '预防方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001781', 'source-doc-4c784a84a66adf221597', 'source-node-001780', '5', '1780', 'text', '农业调控：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001782', 'source-doc-4c784a84a66adf221597', 'source-node-001781', '6', '1781', 'text', '冬季清园，剪除病枝病叶，喷施 3-5 波美度石硫合剂杀灭越冬菌源。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001783', 'source-doc-4c784a84a66adf221597', 'source-node-001781', '6', '1782', 'text', '合理修剪，保持通风透光，降低田间湿度。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001784', 'source-doc-4c784a84a66adf221597', 'source-node-001780', '5', '1783', 'text', '物理防控：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001785', 'source-doc-4c784a84a66adf221597', 'source-node-001784', '6', '1784', 'text', '果实套袋（无纺布袋），减少病菌侵染机会。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001786', 'source-doc-4c784a84a66adf221597', 'source-node-001774', '4', '1785', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001787', 'source-doc-4c784a84a66adf221597', 'source-node-001786', '5', '1786', 'text', '25% 咪鲜胺水乳剂：1000 倍液，快速抑制病菌扩展，发病初期每隔 7 天喷一次，连续 2 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001788', 'source-doc-4c784a84a66adf221597', 'source-node-001786', '5', '1787', 'text', '10% 苯醚甲环唑水分散粒剂：1500 倍液，内吸性强，对炭疽菌有特效，可兼治叶斑病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001789', 'source-doc-4c784a84a66adf221597', 'source-node-001786', '5', '1788', 'text', '60% 唑醚・代森联水分散粒剂：1500 倍液，保护 + 治疗双重作用，雨季前预防性喷施，持效期 20 天。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001790', 'source-doc-4c784a84a66adf221597', 'source-node-001786', '5', '1789', 'text', '吡唑醚菌酯·溴菌腈1500倍+氨基酸叶面肥，5-7天一次', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001791', 'source-doc-4c784a84a66adf221597', 'source-node-001786', '5', '1790', 'text', '轮换策略：咪鲜胺→苯醚甲环唑→唑醚・代森联，避免长期单一用药。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001792', 'source-doc-4c784a84a66adf221597', 'source-node-001755', '3', '1791', 'text', '百香果疫病（寄生疫霉）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001793', 'source-doc-4c784a84a66adf221597', 'source-node-001792', '4', '1792', 'text', '发病规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001794', 'source-doc-4c784a84a66adf221597', 'source-node-001793', '5', '1793', 'text', '为害特点：叶片从叶尖叶缘开始水渍状坏死，茎蔓形成环状病斑导致整株死亡，果实软化腐烂。高温高湿（28-32℃、湿度＞85%）条件下，3-5 天即可爆发成灾。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001795', 'source-doc-4c784a84a66adf221597', 'source-node-001793', '5', '1794', 'text', '传播途径：卵孢子在土壤中越冬，借雨水飞溅传播，灌溉水可远距离扩散。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001796', 'source-doc-4c784a84a66adf221597', 'source-node-001792', '4', '1795', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001797', 'source-doc-4c784a84a66adf221597', 'source-node-001796', '5', '1796', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001798', 'source-doc-4c784a84a66adf221597', 'source-node-001792', '4', '1797', 'text', '预防方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001799', 'source-doc-4c784a84a66adf221597', 'source-node-001798', '5', '1798', 'text', '农业调控：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001800', 'source-doc-4c784a84a66adf221597', 'source-node-001799', '6', '1799', 'text', '避免与瓜类、茄科作物连作，实行水旱轮作。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001801', 'source-doc-4c784a84a66adf221597', 'source-node-001799', '6', '1800', 'text', '雨季前铺设地膜，减少土壤病菌溅到果实。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001802', 'source-doc-4c784a84a66adf221597', 'source-node-001798', '5', '1801', 'text', '生物防控：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001803', 'source-doc-4c784a84a66adf221597', 'source-node-001802', '6', '1802', 'text', '喷施木霉菌（100 亿 CFU/g）500 倍液，竞争性抑制疫霉菌生长。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001804', 'source-doc-4c784a84a66adf221597', 'source-node-001792', '4', '1803', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001805', 'source-doc-4c784a84a66adf221597', 'source-node-001804', '5', '1804', 'text', '50% 烯酰・吡唑醚菌酯水分散粒剂：1500 倍液，兼具内吸和保护作用，对疫病特效，发病初期连喷 2 次（间隔 5 天）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001806', 'source-doc-4c784a84a66adf221597', 'source-node-001804', '5', '1805', 'text', '68% 精甲霜・锰锌水分散粒剂：1000 倍液，快速控制蔓延，配合代森锰锌（800 倍液）混用效果更佳。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001807', 'source-doc-4c784a84a66adf221597', 'source-node-001804', '5', '1806', 'text', '72% 霜脲・锰锌可湿性粉剂：800 倍液，持效期 10-15 天，适合中等发生果园。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001808', 'source-doc-4c784a84a66adf221597', 'source-node-001804', '5', '1807', 'text', '20%二氢·吡唑酯或苯醚甲环唑+氰霜唑+氟啶胺，', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001809', 'source-doc-4c784a84a66adf221597', 'source-node-001804', '5', '1808', 'text', '注意事项：雨后立即喷药，重点喷施茎基部和果实。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001810', 'source-doc-4c784a84a66adf221597', 'source-node-001755', '3', '1809', 'text', '百香果叶斑病（壳二孢菌）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001811', 'source-doc-4c784a84a66adf221597', 'source-node-001810', '4', '1810', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001812', 'source-doc-4c784a84a66adf221597', 'source-node-001811', '5', '1811', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001813', 'source-doc-4c784a84a66adf221597', 'source-node-001810', '4', '1812', 'text', '发病规律：叶片初生淡黄色小点，出现圆形至不规则形褐斑，边缘褐色，中央灰白色，边缘黄褐色、稍隆起，后期叶斑正面长小黑点。高温高湿（25-30℃）季节易发生，通风不良的果园发病率高，条件适宜时产生子囊孢子，借风雨、昆虫、人畜和枝条接触传播进行初侵染。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001814', 'source-doc-4c784a84a66adf221597', 'source-node-001810', '4', '1813', 'text', '预防措施：选育抗病品种、选栽无病种苗；加强田间管理，做好田间卫生（及时剪除并烧毁病枝病叶 ）、冬季清园减少越冬菌源；做好排水，防止果园积水（尤其水田、低洼地区 ）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001815', 'source-doc-4c784a84a66adf221597', 'source-node-001810', '4', '1814', 'text', '防治方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001816', 'source-doc-4c784a84a66adf221597', 'source-node-001815', '5', '1815', 'text', '喷施 75% 百菌清 800 倍液或 50% 腐霉利 1000 倍液，每隔 10 天喷一次，连续 2 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001817', 'source-doc-4c784a84a66adf221597', 'source-node-001815', '5', '1816', 'text', '发病后可选 50% 咪鲜胺锰盐可湿性粉剂 500 - 2000 倍液、25% 溴菌腈可湿性粉剂 800 倍液，或 10% 醚菌酯悬浮剂 500 - 600 倍液、15% 吡唑醚菌酯悬浮剂 1000 倍液、78% 波尔・锰锌可湿性粉剂 500 倍液、10% 苯醚甲环唑水分散粒剂 2000 - 2500 倍液 。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001818', 'source-doc-4c784a84a66adf221597', 'source-node-001755', '3', '1817', 'text', '百香果根腐病（腐霉菌）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001819', 'source-doc-4c784a84a66adf221597', 'source-node-001818', '4', '1818', 'text', '疫霉根腐', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001820', 'source-doc-4c784a84a66adf221597', 'source-node-001819', '5', '1819', 'text', '规律：根系呈黑色或褐色溃烂，根系上会形成脓斑，表面有病原孢子，周边侧根是好的中心部根系是坏的', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001821', 'source-doc-4c784a84a66adf221597', 'source-node-001819', '5', '1820', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001822', 'source-doc-4c784a84a66adf221597', 'source-node-001821', '6', '1821', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001823', 'source-doc-4c784a84a66adf221597', 'source-node-001819', '5', '1822', 'text', '防治：烯酰吗啉、氟马啉、磺菌胺、', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001824', 'source-doc-4c784a84a66adf221597', 'source-node-001818', '4', '1823', 'text', '腐霉根腐', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001825', 'source-doc-4c784a84a66adf221597', 'source-node-001824', '5', '1824', 'text', '规律：细菌引起的根腐病，受感染的根部会变瘪，根部送散，容易破裂，长菌毛', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001826', 'source-doc-4c784a84a66adf221597', 'source-node-001824', '5', '1825', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001827', 'source-doc-4c784a84a66adf221597', 'source-node-001826', '6', '1826', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001828', 'source-doc-4c784a84a66adf221597', 'source-node-001824', '5', '1827', 'text', '发病规律：根系腐烂，植株生长缓慢、黄化。土壤积水或连作地块易发生，低温高湿（15-20℃）季节为害加重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001829', 'source-doc-4c784a84a66adf221597', 'source-node-001824', '5', '1828', 'text', '防治方法：灌根使用 68% 精甲霜・锰锌 1000 倍液 + 生根剂，促进新根生长。链霉素、土消灵、恶霉灵、噻唑菌胺、', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001830', 'source-doc-4c784a84a66adf221597', 'source-node-001818', '4', '1829', 'text', '镰刀型根腐', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001831', 'source-doc-4c784a84a66adf221597', 'source-node-001830', '5', '1830', 'text', '规律：真菌性的（高等真菌），根系呈现黑色或褐色，逐渐腐烂，根部组织软化。不见长霉菌', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001832', 'source-doc-4c784a84a66adf221597', 'source-node-001830', '5', '1831', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001833', 'source-doc-4c784a84a66adf221597', 'source-node-001832', '6', '1832', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001834', 'source-doc-4c784a84a66adf221597', 'source-node-001830', '5', '1833', 'text', '防治：恶霉灵、多菌灵、甲基托布津', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001835', 'source-doc-4c784a84a66adf221597', 'source-node-001834', '6', '1834', 'text', '还可以选择松土，使用吲丁萘乙酸（吲哚丁酸钾和萘乙酸钠复配的）2%的一亩地滴灌到200-500g，配合其他防治根腐的药剂，30%精甲恶霉灵一亩1kg。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001836', 'source-doc-4c784a84a66adf221597', 'source-node-001755', '3', '1835', 'text', '百香果枯萎病', '[]');
