INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001853', 'source-doc-4c784a84a66adf221597', 'source-node-001719', '2', '1852', 'text', '病毒', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001854', 'source-doc-4c784a84a66adf221597', 'source-node-001853', '3', '1853', 'text', '百香果花叶病毒病（黄瓜花叶病毒 CMV）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001855', 'source-doc-4c784a84a66adf221597', 'source-node-001854', '4', '1854', 'text', '发病规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001856', 'source-doc-4c784a84a66adf221597', 'source-node-001855', '5', '1855', 'text', '为害特点：叶片呈现黄绿相间的花叶，新梢扭曲畸形，果实发育不良、果小味酸。全年均可发生，高温干旱（25-30℃）季节利于蚜虫传播病毒。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001857', 'source-doc-4c784a84a66adf221597', 'source-node-001855', '5', '1856', 'text', '传播途径：主要通过蚜虫、蓟马等刺吸式害虫传播，农事操作（如修剪）也可机械传播。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001858', 'source-doc-4c784a84a66adf221597', 'source-node-001854', '4', '1857', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001859', 'source-doc-4c784a84a66adf221597', 'source-node-001858', '5', '1858', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001860', 'source-doc-4c784a84a66adf221597', 'source-node-001854', '4', '1859', 'text', '预防方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001861', 'source-doc-4c784a84a66adf221597', 'source-node-001860', '5', '1860', 'text', '农业调控：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001862', 'source-doc-4c784a84a66adf221597', 'source-node-001861', '6', '1861', 'text', '选用无毒组培苗，定植前用 10% 磷酸三钠溶液浸根 10 分钟消毒。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001863', 'source-doc-4c784a84a66adf221597', 'source-node-001861', '6', '1862', 'text', '避免与茄科、瓜类作物套种，减少交叉感染。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001864', 'source-doc-4c784a84a66adf221597', 'source-node-001860', '5', '1863', 'text', '物理防控：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001865', 'source-doc-4c784a84a66adf221597', 'source-node-001864', '6', '1864', 'text', '果园周围设置 40 目防虫网，阻隔蚜虫迁飞。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001866', 'source-doc-4c784a84a66adf221597', 'source-node-001854', '4', '1865', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001867', 'source-doc-4c784a84a66adf221597', 'source-node-001866', '5', '1866', 'text', '叶面喷施药剂（按效果排序）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001868', 'source-doc-4c784a84a66adf221597', 'source-node-001867', '6', '1867', 'text', '20% 毒氟磷可湿性粉剂：800 倍液，抑制病毒复制，发病初期每隔 7 天喷一次，连续 2 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001869', 'source-doc-4c784a84a66adf221597', 'source-node-001867', '6', '1868', 'text', '0.5% 香菇多糖水剂：500 倍液，诱导植株产生抗病性，可与氨基寡糖素+锌肥交替使用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001870', 'source-doc-4c784a84a66adf221597', 'source-node-001867', '6', '1869', 'text', '2% 宁南霉素水剂：600 倍液，生物源抗病毒剂，配合锌肥（0.1% 硫酸锌）增强效果。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001871', 'source-doc-4c784a84a66adf221597', 'source-node-001866', '5', '1870', 'text', '传毒媒介防治：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001872', 'source-doc-4c784a84a66adf221597', 'source-node-001871', '6', '1871', 'text', '25% 噻虫嗪水分散粒剂：8000 倍液，内吸性强，持效期 15 天，防治蚜虫和蓟马，吡蚜酮交替。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001873', 'source-doc-4c784a84a66adf221597', 'source-node-001871', '6', '1872', 'text', '5% 啶虫脒乳油：2000 倍液，触杀 + 胃毒作用，快速降低虫口密度。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001874', 'source-doc-4c784a84a66adf221597', 'source-node-001871', '6', '1873', 'text', '控传毒媒介：悬挂黄板+喷 噻虫嗪+吡蚜酮 灭蚜', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001875', 'source-doc-4c784a84a66adf221597', 'source-node-001866', '5', '1874', 'text', '注意事项：重病株需及时拔除并销毁，周围植株预防性喷施抗病毒药剂', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001876', 'source-doc-4c784a84a66adf221597', 'source-node-001866', '5', '1875', 'text', '治疗限制：病毒病无法根治，显症后仅能缓解：喷 香菇多糖+芸苔素内酯+硫酸锌，延缓病毒复制', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001877', 'source-doc-4c784a84a66adf221597', 'source-node-001719', '2', '1876', 'text', '虫害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001878', 'source-doc-4c784a84a66adf221597', 'source-node-001877', '3', '1877', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001879', 'source-doc-4c784a84a66adf221597', 'source-node-001878', '4', '1878', 'text', '发病规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001880', 'source-doc-4c784a84a66adf221597', 'source-node-001878', '4', '1879', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001881', 'source-doc-4c784a84a66adf221597', 'source-node-001878', '4', '1880', 'text', '预防方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001882', 'source-doc-4c784a84a66adf221597', 'source-node-001878', '4', '1881', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001883', 'source-doc-4c784a84a66adf221597', 'source-node-000545', '1', '1882', 'text', '2.1.3 葡萄', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001884', 'source-doc-4c784a84a66adf221597', 'source-node-001883', '2', '1883', 'text', '细菌性病害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001885', 'source-doc-4c784a84a66adf221597', 'source-node-001884', '3', '1884', 'text', '葡萄根癌病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001886', 'source-doc-4c784a84a66adf221597', 'source-node-001885', '4', '1885', 'text', '发病规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001887', 'source-doc-4c784a84a66adf221597', 'source-node-001886', '5', '1886', 'text', '土壤杆菌属（Agrobacterium tumefaciens）。病菌通过伤口侵入，土壤带菌是主要侵染源，碱性土壤、机械损伤及冻害加重发病。潜育期数周至 1 年，5-8 月为发病高峰。根颈、侧根或嫁接口形成瘤状突起，初期乳白色，后期木质化呈褐色，表面龟裂，植株生长衰弱，叶片黄化，果穗松散。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001888', 'source-doc-4c784a84a66adf221597', 'source-node-001886', '5', '1887', 'text', '症状：主要为害根颈、主根和侧根，2年生以上的主蔓近地面处亦常受害。苗木则多发生在接穗和砧木愈合的地方。肿瘤从根的皮孔处突起。瘤的大小变化很大，直径0.5～10cm，球形，椭圆形或不规则形；幼嫩瘤淡褐色，表面旋卷，粗糙不平，柔软海绵状；如继续发展，瘤的外层细胞死亡，颜色逐年加深，内部组织木质化，成为坚硬的瘤', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001889', 'source-doc-4c784a84a66adf221597', 'source-node-001885', '4', '1888', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001890', 'source-doc-4c784a84a66adf221597', 'source-node-001885', '4', '1889', 'text', '预防方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001891', 'source-doc-4c784a84a66adf221597', 'source-node-001890', '5', '1890', 'text', '选用抗砧木（如 SO4、河岸 2 号），定植前用 1% 硫酸铜浸根 5 分钟，再用 2% 石灰水浸 1 分钟。避免连作，酸性土壤增施有机肥调节 pH 值，减少伤口感染。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001892', 'source-doc-4c784a84a66adf221597', 'source-node-001885', '4', '1891', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001893', 'source-doc-4c784a84a66adf221597', 'source-node-001892', '5', '1892', 'text', '病瘤切除后涂抹石硫合剂渣液或 50 倍菌毒清，严重病株拔除并对土壤消毒（1% 硫酸铜）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001894', 'source-doc-4c784a84a66adf221597', 'source-node-001892', '5', '1893', 'text', '生物防治：使用放射土壤杆菌 MI15 或 E76 生防菌素处理苗木。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001895', 'source-doc-4c784a84a66adf221597', 'source-node-001892', '5', '1894', 'text', '药剂防治：①苗木、种条栽植前严格消毒，用硫酸铜50～100倍液，或多效灵100倍液，或0.1%升汞液或菌毒清100倍液浸苗5分钟即可。②刮治部位后涂药保护伤口，用50倍硫酸铜或50倍多效灵加助渗剂，或50倍菌毒清加助渗剂，或100倍五氯酚钠加50倍多效灵水溶液，或21%复生水剂 400～500倍液。③用甲醇50份、冰醋酸25份、冰片12份混合均匀涂在癌瘤表面及周围3cm处，也可杀死肿瘤表层细菌。④在葡萄冬季压蔓或早春出土前后喷波美0.5度石硫合剂或72%农用链霉素可溶性粉剂 3 000倍液，有一定治疗效果', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001896', 'source-doc-4c784a84a66adf221597', 'source-node-001884', '3', '1895', 'text', '葡萄细菌性斑点病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001897', 'source-doc-4c784a84a66adf221597', 'source-node-001896', '4', '1896', 'text', '病原：假单胞菌属（Pseudomonas syringae）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001898', 'source-doc-4c784a84a66adf221597', 'source-node-001896', '4', '1897', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001899', 'source-doc-4c784a84a66adf221597', 'source-node-001898', '5', '1898', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001900', 'source-doc-4c784a84a66adf221597', 'source-node-001896', '4', '1899', 'text', '症状：叶片出现多角形水渍状斑点，后变为褐色，边缘有黄色晕圈，严重时穿孔；果粒出现褐色凹陷斑，易腐烂。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001901', 'source-doc-4c784a84a66adf221597', 'source-node-001896', '4', '1900', 'text', '发病规律：病菌在病残体越冬，借风雨传播，高温高湿（25-30℃，湿度＞85%）利于发病，多雨年份危害重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001902', 'source-doc-4c784a84a66adf221597', 'source-node-001896', '4', '1901', 'text', '预防方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001903', 'source-doc-4c784a84a66adf221597', 'source-node-001902', '5', '1902', 'text', '冬季清园，剪除病枝落叶，萌芽前喷 3-5 波美度石硫合剂。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001904', 'source-doc-4c784a84a66adf221597', 'source-node-001902', '5', '1903', 'text', '生长期避免过度密植，增强通风透光。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001905', 'source-doc-4c784a84a66adf221597', 'source-node-001896', '4', '1904', 'text', '防治方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001906', 'source-doc-4c784a84a66adf221597', 'source-node-001905', '5', '1905', 'text', '发病初期喷施 20% 噻菌铜悬浮剂 500 倍液或 47% 春雷・王铜可湿性粉剂 800 倍液，间隔 7-10 天，连续 2-3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001907', 'source-doc-4c784a84a66adf221597', 'source-node-001884', '3', '1906', 'text', '葡萄溃疡病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001908', 'source-doc-4c784a84a66adf221597', 'source-node-001907', '4', '1907', 'text', '病源：葡萄溃疡病是由葡萄座腔菌引起的、发生在葡萄的一种病害。该病主要为害部位为枝条、果实及穗轴。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001909', 'source-doc-4c784a84a66adf221597', 'source-node-001907', '4', '1908', 'text', '症状：葡萄溃疡病首先在当年生枝条上产生灰白色梭形病斑，或在往年生枝蔓上出现红褐色病斑，病斑上着生黑色小点，致使新梢生长受阻，发病枝条分枝处也常形成白褐色病斑；叶片呈现黄色或黄色条纹，叶缘内翅，呈杯状或破碎落花严重，有时整个花穗的花全落光，在木质部导管组织产生黑色溃疡是显著特征，溃疡从修剪留下的锯口开始，在横切开的枝蔓可见到黑色楔形的侵入溃疡面；果实染病，造成果实腐烂及果粒脱落；穗轴被害，穗轴上出现黑褐色斑，造成果梗干枯，及果实腐烂或脱落，或由于果梗干枯，造成果实不脱落但逐渐干缩；进而造成树势衰弱，最终造成死树，且病害发生严重时会造成毁园。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001910', 'source-doc-4c784a84a66adf221597', 'source-node-001907', '4', '1909', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001911', 'source-doc-4c784a84a66adf221597', 'source-node-001910', '5', '1910', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001912', 'source-doc-4c784a84a66adf221597', 'source-node-001907', '4', '1911', 'text', '防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001913', 'source-doc-4c784a84a66adf221597', 'source-node-001912', '5', '1912', 'text', '1. 检疫防控。严禁从疫区引进苗木和接穗，如已引进应进行隔离，栽植2年后确认无病时放开放行，否则就地烧毁。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001914', 'source-doc-4c784a84a66adf221597', 'source-node-001912', '5', '1913', 'text', '2. 人工防控。发现病株，及时清除，认真清园，集中彻底剪除烧毁病穗、病枝，消灭越冬菌源；棚室栽培的要及时覆盖薄膜，避免葡萄植株淋雨；拔除死树，对树体周围土壤进行消毒。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001915', 'source-doc-4c784a84a66adf221597', 'source-node-001912', '5', '1914', 'text', '3. 农业防控。加强栽培管理，合理施肥，旱时及时灌水，涝时及时排水，适当疏果，增强树势，控制产量，合理使用植物生长调节剂，用健康枝条留用种条，保证葡萄的健康生长，从而减轻溃疡病的发生。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001916', 'source-doc-4c784a84a66adf221597', 'source-node-001912', '5', '1915', 'text', '4. 药剂防控。在花前花后，喷洒50%福美双可湿性粉剂1500倍液；修剪期比较干燥地区喷洒波美5度石硫合剂；修剪期比较湿润地区，修剪后喷施50%福美双可湿性粉剂500倍液；套袋前用50%多菌灵600倍液或70%甲基硫菌灵800倍液浸穗；尤其是穗轴部分对剪除病穗、病枝后的剪口，立即用70%甲基硫菌灵800倍液消毒；喷施25%嘧菌酯悬浮剂或10%苯醚甲环唑水分散粒剂2000倍液或25%丙环唑乳油4000倍液也可预防葡萄溃疡病。春雷霉素+抑霉唑+甲基托布津，', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001917', 'source-doc-4c784a84a66adf221597', 'source-node-001912', '5', '1916', 'text', '5. 生物防治。葡萄溃疡病的生物防治主要是利用真菌之间拮抗和重寄生关系，以达到抑制病菌生长的目的。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001918', 'source-doc-4c784a84a66adf221597', 'source-node-001883', '2', '1917', 'text', '真菌性病害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001919', 'source-doc-4c784a84a66adf221597', 'source-node-001918', '3', '1918', 'text', '葡萄霜霉病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001920', 'source-doc-4c784a84a66adf221597', 'source-node-001919', '4', '1919', 'text', '病原：葡萄生单轴霉（Plasmopara viticola）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001921', 'source-doc-4c784a84a66adf221597', 'source-node-001919', '4', '1920', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001922', 'source-doc-4c784a84a66adf221597', 'source-node-001921', '5', '1921', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001923', 'source-doc-4c784a84a66adf221597', 'source-node-001919', '4', '1922', 'text', '症状：叶片背面出现白色霜状霉层，正面呈黄褐色不规则病斑，严重时叶片焦枯脱落；果粒受害后变软腐烂。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001924', 'source-doc-4c784a84a66adf221597', 'source-node-001919', '4', '1923', 'text', '发病规律：病菌以卵孢子在病残体越冬，借风雨传播，20-24℃、高湿（相对湿度＞85%）为发病适温，多雨季节易爆发。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001925', 'source-doc-4c784a84a66adf221597', 'source-node-001919', '4', '1924', 'text', '预防方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001926', 'source-doc-4c784a84a66adf221597', 'source-node-001925', '5', '1925', 'text', '避雨栽培降低湿度，萌芽前喷 3-5 波美度石硫合剂，展叶期喷波尔多液或代森锰锌保护', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001927', 'source-doc-4c784a84a66adf221597', 'source-node-001925', '5', '1926', 'text', '控制氮肥用量，增施磷钾肥。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001928', 'source-doc-4c784a84a66adf221597', 'source-node-001919', '4', '1927', 'text', '防治方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001929', 'source-doc-4c784a84a66adf221597', 'source-node-001928', '5', '1928', 'text', '发病初期喷施吡唑醚菌酯、氟噻唑吡乙酮或烯酰吗啉，保护剂与治疗剂交替使用，重点喷施叶背', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001930', 'source-doc-4c784a84a66adf221597', 'source-node-001918', '3', '1929', 'text', '葡萄白粉病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001931', 'source-doc-4c784a84a66adf221597', 'source-node-001930', '4', '1930', 'text', '病原：葡萄钩丝壳菌（Uncinula necator）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001932', 'source-doc-4c784a84a66adf221597', 'source-node-001931', '5', '1931', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001933', 'source-doc-4c784a84a66adf221597', 'source-node-001932', '6', '1932', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001934', 'source-doc-4c784a84a66adf221597', 'source-node-001930', '4', '1933', 'text', '症状：叶片、果粒覆盖白色粉状物，叶片卷曲皱缩，果粒表皮龟裂，失去商品价值。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001935', 'source-doc-4c784a84a66adf221597', 'source-node-001930', '4', '1934', 'text', '发病规律：病菌以菌丝在芽鳞越冬，5-6 月开始侵染，25-28℃、干旱与高温交替时易流行，设施栽培因通风差更严重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001936', 'source-doc-4c784a84a66adf221597', 'source-node-001930', '4', '1935', 'text', '预防方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001937', 'source-doc-4c784a84a66adf221597', 'source-node-001936', '5', '1936', 'text', '萌芽前喷 3-5 波美度石硫合剂，生长期及时摘心、绑蔓，增强透光。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001938', 'source-doc-4c784a84a66adf221597', 'source-node-001936', '5', '1937', 'text', '套袋前喷施苯醚甲环唑或戊唑醇，减少果粒感染', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001939', 'source-doc-4c784a84a66adf221597', 'source-node-001930', '4', '1938', 'text', '防治方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001940', 'source-doc-4c784a84a66adf221597', 'source-node-001939', '5', '1939', 'text', '发病初期喷施乙嘧酚、氟菌・肟菌酯或硫磺水分散粒剂，重点喷施果穗和叶正面', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001941', 'source-doc-4c784a84a66adf221597', 'source-node-001918', '3', '1940', 'text', '葡萄炭疽病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001942', 'source-doc-4c784a84a66adf221597', 'source-node-001941', '4', '1941', 'text', '病原：胶孢炭疽菌（Colletotrichum gloeosporioides）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001943', 'source-doc-4c784a84a66adf221597', 'source-node-001941', '4', '1942', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001944', 'source-doc-4c784a84a66adf221597', 'source-node-001943', '5', '1943', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001945', 'source-doc-4c784a84a66adf221597', 'source-node-001941', '4', '1944', 'text', '症状：果粒表面出现褐色凹陷斑，后期密生黑色小点，潮湿时溢出粉红色黏液，病果干缩成僵果。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001946', 'source-doc-4c784a84a66adf221597', 'source-node-001941', '4', '1945', 'text', '发病规律：病菌以菌丝在病枝、僵果越冬，6-8 月高温多雨期爆发，果实着色期加重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001947', 'source-doc-4c784a84a66adf221597', 'source-node-001941', '4', '1946', 'text', '预防方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001948', 'source-doc-4c784a84a66adf221597', 'source-node-001947', '5', '1947', 'text', '花后套袋，减少病菌侵染，套袋前喷苯醚甲环唑或嘧菌酯', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001949', 'source-doc-4c784a84a66adf221597', 'source-node-001947', '5', '1948', 'text', '增施钾肥，控制负载量，增强树势。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001950', 'source-doc-4c784a84a66adf221597', 'source-node-001941', '4', '1949', 'text', '防治方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001951', 'source-doc-4c784a84a66adf221597', 'source-node-001950', '5', '1950', 'text', '发病初期喷施咪鲜胺、苯醚甲环唑或啶氧菌酯，间隔 10-15 天，连续 2-3 次', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001952', 'source-doc-4c784a84a66adf221597', 'source-node-001918', '3', '1951', 'text', '葡萄黑痘病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001953', 'source-doc-4c784a84a66adf221597', 'source-node-001952', '4', '1952', 'text', '病原：痂圆孢属（Sphaceloma ampelinum）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001954', 'source-doc-4c784a84a66adf221597', 'source-node-001952', '4', '1953', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001955', 'source-doc-4c784a84a66adf221597', 'source-node-001954', '5', '1954', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001956', 'source-doc-4c784a84a66adf221597', 'source-node-001952', '4', '1955', 'text', '发病规律：病菌以菌丝在病枝越冬，4-6 月借风雨传播，多雨、低温（20-24℃）易流行，欧亚种葡萄易感', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001957', 'source-doc-4c784a84a66adf221597', 'source-node-001952', '4', '1956', 'text', '预防方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001958', 'source-doc-4c784a84a66adf221597', 'source-node-001957', '5', '1957', 'text', '萌芽前喷 3-5 波美度石硫合剂 + 0.3% 五氯酚钠，花前喷波尔多液保护', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001959', 'source-doc-4c784a84a66adf221597', 'source-node-001957', '5', '1958', 'text', '选用抗病品种（如巨峰），合理修剪增强通风。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001960', 'source-doc-4c784a84a66adf221597', 'source-node-001952', '4', '1959', 'text', '防治方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001961', 'source-doc-4c784a84a66adf221597', 'source-node-001960', '5', '1960', 'text', '发病初期喷施苯醚甲环唑、氟硅唑或戊唑醇，重点保护幼嫩组织', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001962', 'source-doc-4c784a84a66adf221597', 'source-node-001918', '3', '1961', 'text', '葡萄白腐病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001963', 'source-doc-4c784a84a66adf221597', 'source-node-001962', '4', '1962', 'text', '病原：白腐盾壳霉（Coniothyrium diplodiella）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001964', 'source-doc-4c784a84a66adf221597', 'source-node-001962', '4', '1963', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001965', 'source-doc-4c784a84a66adf221597', 'source-node-001964', '5', '1964', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001966', 'source-doc-4c784a84a66adf221597', 'source-node-001962', '4', '1965', 'text', '症状：果穗基部果粒先发病，出现褐色软腐，表面密生灰白色小点，病果易脱落或干缩成僵果。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001967', 'source-doc-4c784a84a66adf221597', 'source-node-001962', '4', '1966', 'text', '发病规律：病菌以分生孢子器在病残体越冬，6-8 月高温多雨期爆发，伤口（如雹伤）和近地面果穗易感。常引起大量果穗腐烂，靠近地面的果穗容易发病，受害果穗一般表现为有水浸状、淡褐色、不规则的病斑，呈腐烂状，发病1周后，果面密生一层灰白色的小粒点，病部渐逐失水干缩并向果粒蔓延，果蒂部分先变为淡褐色，后逐渐扩大呈软腐状，以后全粒变褐腐烂，但果粒形状不变，穗轴及果梗常干枯缢缩，严重时引起全穗腐烂；挂在树上的病果逐渐皱缩、干枯成为有明显棱角的僵果。果实在上浆前发病，病果糖分很低，易失水干枯，深褐色的僵果往往挂在树上长久不落，易与房枯病混淆；上浆后感病，病果不易干枯，在受到震动时，果粒甚至全穗极易脱落', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001968', 'source-doc-4c784a84a66adf221597', 'source-node-001962', '4', '1967', 'text', '预防方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001969', 'source-doc-4c784a84a66adf221597', 'source-node-001968', '5', '1968', 'text', '提高结果部位至 1.5 米以上，减少土壤飞溅，套袋前喷施福美双 + 多菌灵。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001970', 'source-doc-4c784a84a66adf221597', 'source-node-001968', '5', '1969', 'text', '雨季前地面撒施生石灰或 80% 代森锰锌粉剂。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001971', 'source-doc-4c784a84a66adf221597', 'source-node-001962', '4', '1970', 'text', '防治方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001972', 'source-doc-4c784a84a66adf221597', 'source-node-001971', '5', '1971', 'text', '发病初期喷施氟硅唑、丙环唑或戊唑醇，重点喷施果穗和基部叶片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001973', 'source-doc-4c784a84a66adf221597', 'source-node-001918', '3', '1972', 'text', '葡萄房枯病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001974', 'source-doc-4c784a84a66adf221597', 'source-node-001973', '4', '1973', 'text', '病原：葡萄座腔菌（Botryosphaeria dothidea）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001975', 'source-doc-4c784a84a66adf221597', 'source-node-001973', '4', '1974', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001976', 'source-doc-4c784a84a66adf221597', 'source-node-001975', '5', '1975', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001977', 'source-doc-4c784a84a66adf221597', 'source-node-001973', '4', '1976', 'text', '症状：果粒失水干枯，果梗变褐缢缩，后期果粒表面生小黑点，穗轴枯死。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001978', 'source-doc-4c784a84a66adf221597', 'source-node-001973', '4', '1977', 'text', '发病规律：病菌以菌丝在病果越冬，7-9 月高温干旱时流行，果实成熟期加重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001979', 'source-doc-4c784a84a66adf221597', 'source-node-001973', '4', '1978', 'text', '防治方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001980', 'source-doc-4c784a84a66adf221597', 'source-node-001979', '5', '1979', 'text', '萌芽前喷 3-5 波美度石硫合剂，生长期喷施多菌灵或甲基托布津，套袋前重点防治。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001981', 'source-doc-4c784a84a66adf221597', 'source-node-001883', '2', '1980', 'text', '生理病害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001982', 'source-doc-4c784a84a66adf221597', 'source-node-001981', '3', '1981', 'text', '葡萄日灼病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001983', 'source-doc-4c784a84a66adf221597', 'source-node-001982', '4', '1982', 'text', '病因：高温（＞30℃）、强光直射导致果实或叶片灼伤，土壤缺水、修剪过度加重危害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001984', 'source-doc-4c784a84a66adf221597', 'source-node-001982', '4', '1983', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001985', 'source-doc-4c784a84a66adf221597', 'source-node-001984', '5', '1984', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001986', 'source-doc-4c784a84a66adf221597', 'source-node-001982', '4', '1985', 'text', '症状：果粒向阳面出现水浸状淡褐色斑，后期干缩成褐色僵果；叶片出现黄褐色不规则枯斑', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001987', 'source-doc-4c784a84a66adf221597', 'source-node-001982', '4', '1986', 'text', '预防方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001988', 'source-doc-4c784a84a66adf221597', 'source-node-001987', '5', '1987', 'text', '果穗套袋（选用双层透气袋），果穗附近保留遮阴叶片，高温期覆盖遮阳网', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001989', 'source-doc-4c784a84a66adf221597', 'source-node-001987', '5', '1988', 'text', '地面覆盖秸秆或地膜，保持土壤湿润，避免突然干旱。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001990', 'source-doc-4c784a84a66adf221597', 'source-node-001982', '4', '1989', 'text', '防治方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001991', 'source-doc-4c784a84a66adf221597', 'source-node-001990', '5', '1990', 'text', '喷施含钙叶面肥（如氨基酸钙）增强果皮韧性，干旱时及时灌水调节小气候', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001992', 'source-doc-4c784a84a66adf221597', 'source-node-001981', '3', '1991', 'text', '葡萄缺素症', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001993', 'source-doc-4c784a84a66adf221597', 'source-node-001992', '4', '1992', 'text', '缺硼：新梢节间缩短，叶片皱缩畸形，花穗发育不良，落花落果严重。防治：花前喷施 0.2% 硼砂 + 0.3% 尿素，结合基施硼砂（每亩 1-2kg）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001994', 'source-doc-4c784a84a66adf221597', 'source-node-001993', '5', '1993', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001995', 'source-doc-4c784a84a66adf221597', 'source-node-001992', '4', '1994', 'text', '缺铁：新叶黄化，叶脉间失绿，严重时整叶白化。防治：叶面喷施 0.1%-0.3% 硫酸亚铁 + 0.1% 柠檬酸，改良土壤酸性（pH＜6.5）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001996', 'source-doc-4c784a84a66adf221597', 'source-node-001995', '5', '1995', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001997', 'source-doc-4c784a84a66adf221597', 'source-node-001992', '4', '1996', 'text', '缺钾：老叶叶缘黄化焦枯，果实小、含糖量低。防治：果实膨大期追施硫酸钾（每亩 15-20kg），叶面喷施 0.3% 磷酸二氢钾。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001998', 'source-doc-4c784a84a66adf221597', 'source-node-001997', '5', '1997', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-001999', 'source-doc-4c784a84a66adf221597', 'source-node-001981', '3', '1998', 'text', '水罐子病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002000', 'source-doc-4c784a84a66adf221597', 'source-node-001999', '4', '1999', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002001', 'source-doc-4c784a84a66adf221597', 'source-node-002000', '5', '2000', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002002', 'source-doc-4c784a84a66adf221597', 'source-node-001999', '4', '2001', 'text', '症状：水罐子病主要表现在果粒上， 一般在果粒着色后才表现症状。 发病后果穗先端果粒明显表现出着色不正常， 色泽浅，果粒呈水泡状， 病果糖度降低，变酸，果肉变软 ， 果肉与果皮极易分离， 成为一包酸水， 用手轻捏水滴成串溢出， 故有水罐子之称。 发病后果柄与果粒处易产生离层， 极易脱落', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002003', 'source-doc-4c784a84a66adf221597', 'source-node-001999', '4', '2002', 'text', '发病规律：葡萄水罐子病是由于营养失调或营养不良所导致的一种生理病害。 一般在树势衰弱、 摘心重、 负载量过多、 肥料不足和有效叶面积小时， 病害发生严重。 另外地下水位高或果实成熟期遇雨， 田间湿度大， 温度高， 影响养分的转化， 此病发生也', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002004', 'source-doc-4c784a84a66adf221597', 'source-node-001999', '4', '2003', 'text', '防治：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002005', 'source-doc-4c784a84a66adf221597', 'source-node-002004', '5', '2004', 'text', '1） 加强果园土、 肥、 水的管理： 增施含磷、 钾的有机肥，如鸡鸭粪、 草木灰等农家肥，适量施用氮肥。 在7～8月结合喷药喷施0.3%磷酸二氢钾溶液， 增加叶片和果实的含钾量，及时锄草， 勤松土。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002006', 'source-doc-4c784a84a66adf221597', 'source-node-002004', '5', '2005', 'text', '2） 合理控制树体负载量：在适当多留结果枝、 保证产量的前提下， 采用 “一枝留一穗” 的办法， 每个结果枝只留1 穗果， 尽量减少再次果。 1个果枝上留2个果穗时， 第一穗水罐子病比率高。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002007', 'source-doc-4c784a84a66adf221597', 'source-node-002004', '5', '2006', 'text', '3） 增大叶果比： 主梢叶片是一次果所需养分的主要来源，应适度多留； 在留多次果的情况下， 适当多留副梢叶片， 保证多次果的营养来源。 果枝上留5～7片叶， 天旱及时摘心， 以增大叶果比', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002008', 'source-doc-4c784a84a66adf221597', 'source-node-001981', '3', '2007', 'text', '葡萄裂果', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002009', 'source-doc-4c784a84a66adf221597', 'source-node-002008', '4', '2008', 'text', '病因：果实成熟期土壤水分剧烈变化（如久旱遇雨），果皮与果肉生长不协调，品种（如巨峰）特性易感。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002010', 'source-doc-4c784a84a66adf221597', 'source-node-002009', '5', '2009', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002011', 'source-doc-4c784a84a66adf221597', 'source-node-002008', '4', '2010', 'text', '预防方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002012', 'source-doc-4c784a84a66adf221597', 'source-node-002011', '5', '2011', 'text', '均衡供水，果实膨大期覆盖地膜保持土壤湿度稳定，增施钙肥（硝酸钙）增强果皮韧性。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002013', 'source-doc-4c784a84a66adf221597', 'source-node-002011', '5', '2012', 'text', '合理负载，疏除过密果粒，减少果穗压力。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002014', 'source-doc-4c784a84a66adf221597', 'source-node-002008', '4', '2013', 'text', '防治方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002015', 'source-doc-4c784a84a66adf221597', 'source-node-002014', '5', '2014', 'text', '喷施 5% 氯化钙溶液或植物生长调节剂（如赤霉素），减轻裂果程度。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002016', 'source-doc-4c784a84a66adf221597', 'source-node-001883', '2', '2015', 'text', '药害/肥害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002017', 'source-doc-4c784a84a66adf221597', 'source-node-002016', '3', '2016', 'text', '药害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002018', 'source-doc-4c784a84a66adf221597', 'source-node-002017', '4', '2017', 'text', '症状：急性药害表现为叶片灼伤、畸形、脱落，果实斑点或裂果；慢性药害导致生长缓慢、坐果率低。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002019', 'source-doc-4c784a84a66adf221597', 'source-node-002017', '4', '2018', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002020', 'source-doc-4c784a84a66adf221597', 'source-node-002019', '5', '2019', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002021', 'source-doc-4c784a84a66adf221597', 'source-node-002017', '4', '2020', 'text', '常见原因：浓度过高（如石硫合剂在幼果期使用）、混配不当（如波尔多液与碱性农药混用）、高温施药。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002022', 'source-doc-4c784a84a66adf221597', 'source-node-002017', '4', '2021', 'text', '预防方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002023', 'source-doc-4c784a84a66adf221597', 'source-node-002022', '5', '2022', 'text', '严格按说明书配药，避免中午高温施药，不同药剂间隔 7 天以上使用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002024', 'source-doc-4c784a84a66adf221597', 'source-node-002022', '5', '2023', 'text', '新药试用前进行小范围试验，避免敏感品种受害。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002025', 'source-doc-4c784a84a66adf221597', 'source-node-002017', '4', '2024', 'text', '补救措施：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002026', 'source-doc-4c784a84a66adf221597', 'source-node-002025', '5', '2025', 'text', '立即用清水冲洗植株，喷施叶面肥（0.3% 尿素 + 0.2% 磷酸二氢钾）缓解症状。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002027', 'source-doc-4c784a84a66adf221597', 'source-node-002025', '5', '2026', 'text', '石硫合剂药害可用 400-500 倍食醋中和，波尔多液药害喷施 0.5%-1% 石灰水。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002028', 'source-doc-4c784a84a66adf221597', 'source-node-002016', '3', '2027', 'text', '肥害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002029', 'source-doc-4c784a84a66adf221597', 'source-node-002028', '4', '2028', 'text', '症状：根系褐变腐烂，地上部叶片边缘焦枯，新梢生长停滞，严重时植株死亡。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002030', 'source-doc-4c784a84a66adf221597', 'source-node-002028', '4', '2029', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002031', 'source-doc-4c784a84a66adf221597', 'source-node-002030', '5', '2030', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002032', 'source-doc-4c784a84a66adf221597', 'source-node-002028', '4', '2031', 'text', '常见原因：过量施用化肥（尤其是氮肥）、未腐熟有机肥烧根、叶面肥浓度过高。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002033', 'source-doc-4c784a84a66adf221597', 'source-node-002028', '4', '2032', 'text', '预防方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002034', 'source-doc-4c784a84a66adf221597', 'source-node-002033', '5', '2033', 'text', '有机肥充分腐熟后施用，化肥少量多次，避免接触根系。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002035', 'source-doc-4c784a84a66adf221597', 'source-node-002033', '5', '2034', 'text', '叶面肥浓度控制在 0.2%-0.3%，高温期停止使用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002036', 'source-doc-4c784a84a66adf221597', 'source-node-002028', '4', '2035', 'text', '防治方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002037', 'source-doc-4c784a84a66adf221597', 'source-node-002036', '5', '2036', 'text', '发现肥害立即灌水稀释，严重时切除腐烂根系，灌施生根剂（如萘乙酸）促进新根生长。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002038', 'source-doc-4c784a84a66adf221597', 'source-node-001883', '2', '2037', 'text', '虫害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002039', 'source-doc-4c784a84a66adf221597', 'source-node-002038', '3', '2038', 'text', '葡萄根瘤蚜', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002040', 'source-doc-4c784a84a66adf221597', 'source-node-002039', '4', '2039', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002041', 'source-doc-4c784a84a66adf221597', 'source-node-002040', '5', '2040', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002042', 'source-doc-4c784a84a66adf221597', 'source-node-002039', '4', '2041', 'text', '危害：刺吸根系汁液，形成根瘤，导致根系腐烂，地上部生长衰弱，叶片黄化', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002043', 'source-doc-4c784a84a66adf221597', 'source-node-002039', '4', '2042', 'text', '发生规律：以卵在根际越冬，5 月孵化，孤雌生殖，砂土利于传播，远距离传播主要通过苗木', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002044', 'source-doc-4c784a84a66adf221597', 'source-node-002039', '4', '2043', 'text', '预防方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002045', 'source-doc-4c784a84a66adf221597', 'source-node-002044', '5', '2044', 'text', '严格检疫，选用抗砧木（如 5BB），定植前用 50% 辛硫磷 1500 倍液浸根 1-2 分钟', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002046', 'source-doc-4c784a84a66adf221597', 'source-node-002044', '5', '2045', 'text', '土壤改良：沙质土种植，酸性土壤增施石灰调节 pH 至 6.5-7.0', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002047', 'source-doc-4c784a84a66adf221597', 'source-node-002039', '4', '2046', 'text', '防治方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002048', 'source-doc-4c784a84a66adf221597', 'source-node-002047', '5', '2047', 'text', '春季萌芽前和秋季根系活动期，用噻虫嗪或吡丙醚淋根，每株用药液 2-3 升', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002049', 'source-doc-4c784a84a66adf221597', 'source-node-002047', '5', '2048', 'text', '零星发生时，拔除病株并对土壤消毒（溴甲烷熏蒸）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002050', 'source-doc-4c784a84a66adf221597', 'source-node-002038', '3', '2049', 'text', '葡萄叶蝉', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002051', 'source-doc-4c784a84a66adf221597', 'source-node-002050', '4', '2050', 'text', '危害：成虫、若虫刺吸叶片汁液，叶面出现白色斑点，严重时全叶失绿，光合作用下降。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002052', 'source-doc-4c784a84a66adf221597', 'source-node-002050', '4', '2051', 'text', '发生规律：1 年发生 3-5 代，以成虫在杂草、树皮越冬，5-8 月为危害高峰，高温干旱加重发生。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002053', 'source-doc-4c784a84a66adf221597', 'source-node-002050', '4', '2052', 'text', '防治方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002054', 'source-doc-4c784a84a66adf221597', 'source-node-002053', '5', '2053', 'text', '冬季清园，清除杂草和落叶，减少越冬虫源。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002055', 'source-doc-4c784a84a66adf221597', 'source-node-002053', '5', '2054', 'text', '发生期喷施吡虫啉、啶虫脒或高效氯氰菊酯，重点喷施叶背', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002056', 'source-doc-4c784a84a66adf221597', 'source-node-002038', '3', '2055', 'text', '葡萄透翅蛾', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002057', 'source-doc-4c784a84a66adf221597', 'source-node-002056', '4', '2056', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002058', 'source-doc-4c784a84a66adf221597', 'source-node-002057', '5', '2057', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002059', 'source-doc-4c784a84a66adf221597', 'source-node-002056', '4', '2058', 'text', '危害：幼虫蛀食新梢和老蔓，蛀孔外有虫粪，导致新梢枯死，树势衰弱。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002060', 'source-doc-4c784a84a66adf221597', 'source-node-002056', '4', '2059', 'text', '发生规律：1 年发生 1 代，以幼虫在枝蔓内越冬，6-7 月成虫产卵，孵化后蛀入嫩梢', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002061', 'source-doc-4c784a84a66adf221597', 'source-node-002056', '4', '2060', 'text', '防治方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002062', 'source-doc-4c784a84a66adf221597', 'source-node-002061', '5', '2061', 'text', '冬季修剪时剪除虫蛀枝，生长期发现虫孔后，用注射器注入 40% 毒死蜱（在蔬菜、果树、茶叶、中草药材上不得使用）乳油 50 倍液，并用泥封口', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002063', 'source-doc-4c784a84a66adf221597', 'source-node-002061', '5', '2062', 'text', '成虫期悬挂性诱捕器或糖醋液（糖：醋: 酒：水 = 3:1:3:2）诱杀', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002064', 'source-doc-4c784a84a66adf221597', 'source-node-002038', '3', '2063', 'text', '葡萄蚧壳虫（如康氏粉蚧）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002065', 'source-doc-4c784a84a66adf221597', 'source-node-002064', '4', '2064', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002066', 'source-doc-4c784a84a66adf221597', 'source-node-002065', '5', '2065', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002067', 'source-doc-4c784a84a66adf221597', 'source-node-002064', '4', '2066', 'text', '危害：刺吸枝蔓、叶片和果实汁液，分泌蜜露诱发煤污病，果粒受害后表面凹凸不平。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002068', 'source-doc-4c784a84a66adf221597', 'source-node-002064', '4', '2067', 'text', '发生规律：1 年发生 3-4 代，以卵在树皮裂缝越冬，5-9 月为危害期，设施栽培更严重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002069', 'source-doc-4c784a84a66adf221597', 'source-node-002064', '4', '2068', 'text', '防治方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002070', 'source-doc-4c784a84a66adf221597', 'source-node-002069', '5', '2069', 'text', '萌芽前喷 3-5 波美度石硫合剂，杀灭越冬卵。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002071', 'source-doc-4c784a84a66adf221597', 'source-node-002069', '5', '2070', 'text', '若虫孵化期喷施螺虫乙酯、噻嗪酮或毒死蜱（在蔬菜、果树、茶叶、中草药材上不得使用），重点喷施枝干和叶背', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002072', 'source-doc-4c784a84a66adf221597', 'source-node-002038', '3', '2071', 'text', '葡萄蓟马', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002073', 'source-doc-4c784a84a66adf221597', 'source-node-002072', '4', '2072', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002074', 'source-doc-4c784a84a66adf221597', 'source-node-002073', '5', '2073', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002075', 'source-doc-4c784a84a66adf221597', 'source-node-002072', '4', '2074', 'text', '危害：锉吸幼果和嫩叶汁液，果粒出现褐色斑点，叶片卷曲畸形。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002076', 'source-doc-4c784a84a66adf221597', 'source-node-002072', '4', '2075', 'text', '发生规律：1 年发生 5-6 代，以成虫在杂草越冬，4-6 月和 9-10 月为危害高峰，高温干旱利于发生。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002077', 'source-doc-4c784a84a66adf221597', 'source-node-002072', '4', '2076', 'text', '防治方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002078', 'source-doc-4c784a84a66adf221597', 'source-node-002077', '5', '2077', 'text', '覆盖地膜减少土壤虫源，悬挂蓝色粘虫板监测和诱杀', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002079', 'source-doc-4c784a84a66adf221597', 'source-node-002077', '5', '2078', 'text', '花前和谢花后喷施乙基多杀菌素、溴虫氟苯双酰胺或吡虫啉，重点喷施花穗和幼果。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002080', 'source-doc-4c784a84a66adf221597', 'source-node-001883', '2', '2079', 'text', '病毒', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002081', 'source-doc-4c784a84a66adf221597', 'source-node-002080', '3', '2080', 'text', '葡萄扇叶病毒（GFLV）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002082', 'source-doc-4c784a84a66adf221597', 'source-node-002081', '4', '2081', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002083', 'source-doc-4c784a84a66adf221597', 'source-node-002082', '5', '2082', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002084', 'source-doc-4c784a84a66adf221597', 'source-node-002081', '4', '2083', 'text', '症状：叶片畸形，呈扇形或鸡爪状，叶脉黄化，果穗松散，果粒大小不一，成熟期推迟。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002085', 'source-doc-4c784a84a66adf221597', 'source-node-002081', '4', '2084', 'text', '传播途径：主要通过带毒苗木和土壤中的剑线虫传播，嫁接和汁液摩擦也可传毒', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002086', 'source-doc-4c784a84a66adf221597', 'source-node-002081', '4', '2085', 'text', '预防方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002087', 'source-doc-4c784a84a66adf221597', 'source-node-002086', '5', '2086', 'text', '培育无病毒苗木，茎尖脱毒结合热处理（35℃，20 天）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002088', 'source-doc-4c784a84a66adf221597', 'source-node-002086', '5', '2087', 'text', '土壤消毒：种植前用二硫化碳或溴甲烷熏蒸，杀灭线虫。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002089', 'source-doc-4c784a84a66adf221597', 'source-node-002081', '4', '2088', 'text', '防治方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002090', 'source-doc-4c784a84a66adf221597', 'source-node-002089', '5', '2089', 'text', '发现病株立即拔除，周围土壤用杀线虫剂（如噻唑膦）处理。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002091', 'source-doc-4c784a84a66adf221597', 'source-node-002089', '5', '2090', 'text', '加强线虫防治，减少传播媒介。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002092', 'source-doc-4c784a84a66adf221597', 'source-node-002080', '3', '2091', 'text', '葡萄卷叶病毒（GLRaV）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002093', 'source-doc-4c784a84a66adf221597', 'source-node-002092', '4', '2092', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002094', 'source-doc-4c784a84a66adf221597', 'source-node-002093', '5', '2093', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002095', 'source-doc-4c784a84a66adf221597', 'source-node-002092', '4', '2094', 'text', '症状：秋季叶片向下卷曲，叶脉间黄化，呈 “V” 形褪绿，果实着色不均，含糖量降低。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002096', 'source-doc-4c784a84a66adf221597', 'source-node-002092', '4', '2095', 'text', '传播途径：通过嫁接和粉蚧传播，带毒苗木是主要侵染源', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002097', 'source-doc-4c784a84a66adf221597', 'source-node-002092', '4', '2096', 'text', '防治方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002098', 'source-doc-4c784a84a66adf221597', 'source-node-002097', '5', '2097', 'text', '选用脱毒苗木，定期检测，发现病株及时清除。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002099', 'source-doc-4c784a84a66adf221597', 'source-node-002097', '5', '2098', 'text', '防治粉蚧：用噻虫嗪或吡丙醚喷雾，减少病毒传播。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002100', 'source-doc-4c784a84a66adf221597', 'source-node-002080', '3', '2099', 'text', '葡萄栓皮病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002101', 'source-doc-4c784a84a66adf221597', 'source-node-002100', '4', '2100', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002102', 'source-doc-4c784a84a66adf221597', 'source-node-002101', '5', '2101', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002103', 'source-doc-4c784a84a66adf221597', 'source-node-002100', '4', '2102', 'text', '病原：葡萄病毒 A（GVA）及类似卷叶病毒复合侵染。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002104', 'source-doc-4c784a84a66adf221597', 'source-node-002100', '4', '2103', 'text', '症状：树皮开裂，呈鳞片状剥落，新梢生长缓慢，叶片变小，果实品质下降。症状主要表现在枝蔓和叶片上，枝蔓染病出现树皮纵裂。以沙地葡萄做砧木的病株在嫁接口上部产生组织增生，呈小脚状。病株老蔓表皮粗糙或纵裂，剥开树皮后可见接口上下木质部呈沟槽状。叶片上出现变色，春末夏初，病株上叶片变成黄褐色至红色，叶肉叶脉全部变红，别于卷叶病只是叶脉间变红，主叶脉仍保持绿色。该病严重影响产量，可减产76%，葡萄寿命缩短。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002105', 'source-doc-4c784a84a66adf221597', 'source-node-002100', '4', '2104', 'text', '传播途径：嫁接传播，粉蚧为主要媒介，带毒苗木是主要侵染源。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002106', 'source-doc-4c784a84a66adf221597', 'source-node-002100', '4', '2105', 'text', '防治方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002107', 'source-doc-4c784a84a66adf221597', 'source-node-002106', '5', '2106', 'text', '严格检疫，选用无病毒母株繁殖，脱毒处理（茎尖培养结合高温）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002108', 'source-doc-4c784a84a66adf221597', 'source-node-002106', '5', '2107', 'text', '防治粉蚧：生长期喷施螺虫乙酯或毒死蜱（在蔬菜、果树、茶叶、中草药材上不得使用），减少传播。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002109', 'source-doc-4c784a84a66adf221597', 'source-node-001883', '2', '2108', 'text', '综合防治策略', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002110', 'source-doc-4c784a84a66adf221597', 'source-node-002109', '3', '2109', 'text', '1. 农业防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002111', 'source-doc-4c784a84a66adf221597', 'source-node-002110', '4', '2110', 'text', '选用抗病品种与砧木：如巨峰（抗黑痘病）、5BB（抗根瘤蚜），减少病害发生。 合理修剪与负载：保持架面通风透光，结果枝与营养枝比例 1:1，控制产量（每亩 1500-2000kg）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002112', 'source-doc-4c784a84a66adf221597', 'source-node-002110', '4', '2111', 'text', '土壤管理：增施有机肥（每亩 3000-5000kg），改善土壤结构，酸性土壤增施石灰，碱性土壤增施硫磺调节 pH。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002113', 'source-doc-4c784a84a66adf221597', 'source-node-002110', '4', '2112', 'text', '清园与消毒：冬季剪除病枝、刮除老皮，萌芽前喷 3-5 波美度石硫合剂，杀灭越冬病菌和虫卵', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002114', 'source-doc-4c784a84a66adf221597', 'source-node-002109', '3', '2113', 'text', '2. 物理防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002115', 'source-doc-4c784a84a66adf221597', 'source-node-002114', '4', '2114', 'text', '灯光诱杀：悬挂频振式杀虫灯，诱杀蛾类、金龟子等成虫', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002116', 'source-doc-4c784a84a66adf221597', 'source-node-002114', '4', '2115', 'text', '色板诱杀：黄板诱杀蚜虫、叶蝉，蓝板诱杀蓟马，每亩悬挂 20-30 块', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002117', 'source-doc-4c784a84a66adf221597', 'source-node-002114', '4', '2116', 'text', '套袋保护：花后 15-20 天套袋，选用透气防水袋，减少果实病害和日灼', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002118', 'source-doc-4c784a84a66adf221597', 'source-node-002109', '3', '2117', 'text', '3. 生物防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002119', 'source-doc-4c784a84a66adf221597', 'source-node-002118', '4', '2118', 'text', '微生物制剂：用木霉菌、枯草芽孢杆菌防治灰霉病和白粉病，苏云金杆菌（Bt）防治鳞翅目害虫 天敌释放：释放蚜茧蜂防治蚜虫，捕食螨控制叶螨，保护瓢虫、草蛉等天敌', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002120', 'source-doc-4c784a84a66adf221597', 'source-node-002109', '3', '2119', 'text', '4. 化学防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002121', 'source-doc-4c784a84a66adf221597', 'source-node-002120', '4', '2120', 'text', '关键时期用药：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002122', 'source-doc-4c784a84a66adf221597', 'source-node-002121', '5', '2121', 'text', '萌芽期：3-5 波美度石硫合剂清园', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002123', 'source-doc-4c784a84a66adf221597', 'source-node-002121', '5', '2122', 'text', '花前：防治灰霉病（咯菌腈）、蓟马（乙基多杀菌素）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002124', 'source-doc-4c784a84a66adf221597', 'source-node-002121', '5', '2123', 'text', '套袋前：苯醚甲环唑 + 嘧菌酯保护果穗。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002125', 'source-doc-4c784a84a66adf221597', 'source-node-002121', '5', '2124', 'text', '转色期：防治炭疽病（咪鲜胺）和霜霉病（氟噻唑吡乙酮）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002126', 'source-doc-4c784a84a66adf221597', 'source-node-002120', '4', '2125', 'text', '注意事项：轮换使用不同作用机制药剂，避免抗药性（如霜霉病交替使用烯酰吗啉和氟噻唑吡乙酮） 严格遵守农药安全间隔期，采收前 20 天停止用药', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002127', 'source-doc-4c784a84a66adf221597', 'source-node-001883', '2', '2126', 'text', '不同栽培模式防治要点', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002128', 'source-doc-4c784a84a66adf221597', 'source-node-002127', '3', '2127', 'text', '1. 避雨栽培', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002129', 'source-doc-4c784a84a66adf221597', 'source-node-002128', '4', '2128', 'text', '优势：显著降低霜霉病、炭疽病等病害发生，减少农药使用量', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002130', 'source-doc-4c784a84a66adf221597', 'source-node-002128', '4', '2129', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002131', 'source-doc-4c784a84a66adf221597', 'source-node-002130', '5', '2130', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002132', 'source-doc-4c784a84a66adf221597', 'source-node-002128', '4', '2131', 'text', '技术要点：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002133', 'source-doc-4c784a84a66adf221597', 'source-node-002132', '5', '2132', 'text', '棚膜覆盖时间：开花前至果实转色期，雨季结束后揭膜。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002134', 'source-doc-4c784a84a66adf221597', 'source-node-002132', '5', '2133', 'text', '棚内温湿度管理：通风口开启，控制湿度在 70% 以下，温度不超过 35℃。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002135', 'source-doc-4c784a84a66adf221597', 'source-node-002132', '5', '2134', 'text', '重点防治：白粉病、蚧壳虫和蓟马，加强通风和药剂防治。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002136', 'source-doc-4c784a84a66adf221597', 'source-node-002127', '3', '2135', 'text', '2. 设施栽培（连栋大棚）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002137', 'source-doc-4c784a84a66adf221597', 'source-node-002136', '4', '2136', 'text', '管理要点：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002138', 'source-doc-4c784a84a66adf221597', 'source-node-002137', '5', '2137', 'text', '温湿度调控：花期温度 20-25℃，湿度 60%-70%；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002139', 'source-doc-4c784a84a66adf221597', 'source-node-002137', '5', '2138', 'text', '果实膨大期温度 25-30℃，湿度 70%-80%。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002140', 'source-doc-4c784a84a66adf221597', 'source-node-002137', '5', '2139', 'text', '二氧化碳补充：冬季晴天上午增施二氧化碳气肥，促进光合作用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002141', 'source-doc-4c784a84a66adf221597', 'source-node-002137', '5', '2140', 'text', '重点防治：灰霉病、白粉病和蚜虫，采用烟熏剂（如腐霉利）和黄板诱杀。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002142', 'source-doc-4c784a84a66adf221597', 'source-node-001883', '2', '2141', 'text', '深圳地区防治特色', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002143', 'source-doc-4c784a84a66adf221597', 'source-node-002142', '3', '2142', 'text', '1. 气候特点：亚热带海洋性气候，高温多雨，湿度大，利于真菌性病害（如霜霉病、白粉病）和虫害（如蓟马、蚧壳虫）发生。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002144', 'source-doc-4c784a84a66adf221597', 'source-node-002142', '3', '2143', 'text', '2. 栽培模式：以避雨栽培为主，设施内采用 “T” 形或 “H” 形架式，增强通风透光。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002145', 'source-doc-4c784a84a66adf221597', 'source-node-002142', '3', '2144', 'text', '3. 防治要点：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002146', 'source-doc-4c784a84a66adf221597', 'source-node-002145', '4', '2145', 'text', '重点防控灰霉病和霜霉病，花前和套袋前喷施唑醚・氟酰胺或嘧霉胺。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002147', 'source-doc-4c784a84a66adf221597', 'source-node-002145', '4', '2146', 'text', '蓟马防治：花前和谢花后用乙基多杀菌素或溴虫氟苯双酰胺，结合蓝色粘虫板。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002148', 'source-doc-4c784a84a66adf221597', 'source-node-002145', '4', '2147', 'text', '日灼病预防：6-8 月高温期覆盖遮阳网，果穗套袋选用遮光率 30% 的透气袋', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002149', 'source-doc-4c784a84a66adf221597', 'source-node-000545', '1', '2148', 'text', '2.1.4 桃树', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002150', 'source-doc-4c784a84a66adf221597', 'source-node-002149', '2', '2149', 'text', '一、桃树细菌性病害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002151', 'source-doc-4c784a84a66adf221597', 'source-node-002150', '3', '2150', 'text', '（一）桃树细菌性穿孔病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002152', 'source-doc-4c784a84a66adf221597', 'source-node-002151', '4', '2151', 'text', '症状表现：叶片初现 1-2mm 水渍状淡褐色小点，边缘有黄色晕圈，后期病斑中心脱落形成整齐穿孔；枝梢分春季溃疡型（老枝生暗褐色小疱疹，流黄色黏液）和夏季溃疡型（嫩枝生褐色病斑，边缘水渍状）；果实生褐色凹陷斑，后期龟裂。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002153', 'source-doc-4c784a84a66adf221597', 'source-node-002151', '4', '2152', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002154', 'source-doc-4c784a84a66adf221597', 'source-node-002153', '5', '2153', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002155', 'source-doc-4c784a84a66adf221597', 'source-node-002151', '4', '2154', 'text', '发病规律：病菌在病枝溃疡斑越冬，次年借风雨、昆虫传播，25-28℃、湿度＞90% 易发病，5 月显症，6-8 月高峰，低洼、通风差果园重发。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002156', 'source-doc-4c784a84a66adf221597', 'source-node-002151', '4', '2155', 'text', '预防方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002157', 'source-doc-4c784a84a66adf221597', 'source-node-002156', '5', '2156', 'text', '冬季清园烧毁病枝叶，早春喷 3-5 波美度石硫合剂；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002158', 'source-doc-4c784a84a66adf221597', 'source-node-002156', '5', '2157', 'text', '合理修剪保持通风，增施有机肥，雨季排水。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002159', 'source-doc-4c784a84a66adf221597', 'source-node-002151', '4', '2158', 'text', '防治药剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002160', 'source-doc-4c784a84a66adf221597', 'source-node-002159', '5', '2159', 'text', '预防：萌芽前喷 3-5 波美度石硫合剂，展叶后喷 80% 代森锰锌可湿性粉剂 600 倍液；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002161', 'source-doc-4c784a84a66adf221597', 'source-node-002159', '5', '2160', 'text', '治疗：发病初期喷 20% 噻唑锌悬浮剂 500 倍液、47% 春雷・王铜可湿性粉剂 800 倍液、3% 中生菌素水剂 600 倍液，间隔 7-10 天，连喷 2-3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002162', 'source-doc-4c784a84a66adf221597', 'source-node-002150', '3', '2161', 'text', '（二）桃树根癌病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002163', 'source-doc-4c784a84a66adf221597', 'source-node-002162', '4', '2162', 'text', '症状表现：根颈、主侧根生灰白色小瘤，渐膨大至褐色硬瘤，表面龟裂；地上部叶黄、枝弱，严重时整株枯死。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002164', 'source-doc-4c784a84a66adf221597', 'source-node-002162', '4', '2163', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002165', 'source-doc-4c784a84a66adf221597', 'source-node-002164', '5', '2164', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002166', 'source-doc-4c784a84a66adf221597', 'source-node-002162', '4', '2165', 'text', '发病规律：病菌在土壤或病瘤越冬，借雨水、农事操作从伤口侵入，中性至微碱性土壤、黏重排水差果园重发。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002167', 'source-doc-4c784a84a66adf221597', 'source-node-002162', '4', '2166', 'text', '预防方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002168', 'source-doc-4c784a84a66adf221597', 'source-node-002167', '5', '2167', 'text', '选无病苗，定植前用 1% 硫酸铜浸根 5 分钟 + 2% 石灰水浸 1 分钟；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002169', 'source-doc-4c784a84a66adf221597', 'source-node-002167', '5', '2168', 'text', '酸性土壤施生石灰调 pH 至 6.0-6.5，避免伤根。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002170', 'source-doc-4c784a84a66adf221597', 'source-node-002162', '4', '2169', 'text', '防治药剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002171', 'source-doc-4c784a84a66adf221597', 'source-node-002170', '5', '2170', 'text', '预防：定植时穴施 5% 噻唑锌颗粒剂（每亩 2-3kg）；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002172', 'source-doc-4c784a84a66adf221597', 'source-node-002170', '5', '2171', 'text', '治疗：切除病瘤后涂 50% 多菌灵可湿性粉剂 100 倍液，或灌根 20% 噻唑锌悬浮剂 300 倍液，每株灌 2-3L。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002173', 'source-doc-4c784a84a66adf221597', 'source-node-002149', '2', '2172', 'text', '二、桃树真菌性病害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002174', 'source-doc-4c784a84a66adf221597', 'source-node-002173', '3', '2173', 'text', '（一）桃褐腐病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002175', 'source-doc-4c784a84a66adf221597', 'source-node-002174', '4', '2174', 'text', '症状表现：果实生褐色软腐斑，表面生灰白色绒状霉层，后期干缩成僵果；花腐后变褐生灰霉；枝梢生褐色溃疡斑，流胶后枯死。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002176', 'source-doc-4c784a84a66adf221597', 'source-node-002174', '4', '2175', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002177', 'source-doc-4c784a84a66adf221597', 'source-node-002176', '5', '2176', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002178', 'source-doc-4c784a84a66adf221597', 'source-node-002174', '4', '2177', 'text', '发病规律：病菌在僵果、病枝越冬，20-25℃、湿度＞90% 易发病，花期、果实近成熟期重发，害虫多的果园加重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002179', 'source-doc-4c784a84a66adf221597', 'source-node-002174', '4', '2178', 'text', '预防方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002180', 'source-doc-4c784a84a66adf221597', 'source-node-002179', '5', '2179', 'text', '冬季清园烧毁僵果，果实膨大期套袋（套袋前喷药）；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002181', 'source-doc-4c784a84a66adf221597', 'source-node-002179', '5', '2180', 'text', '合理疏果，避免负载过重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002182', 'source-doc-4c784a84a66adf221597', 'source-node-002174', '4', '2181', 'text', '防治药剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002183', 'source-doc-4c784a84a66adf221597', 'source-node-002182', '5', '2182', 'text', '预防：花前喷 50% 异菌脲可湿性粉剂 1000 倍液，套袋前喷 70% 甲基硫菌灵可湿性粉剂 800 倍液；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002184', 'source-doc-4c784a84a66adf221597', 'source-node-002182', '5', '2183', 'text', '治疗：发病初期喷 40% 嘧霉胺悬浮剂 1000 倍液、25% 吡唑醚菌酯乳油 1500 倍液、50% 腐霉利可湿性粉剂 800 倍液。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002185', 'source-doc-4c784a84a66adf221597', 'source-node-002173', '3', '2184', 'text', '（二）桃流胶病（侵染性 + 非侵染性）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002186', 'source-doc-4c784a84a66adf221597', 'source-node-002185', '4', '2185', 'text', '症状表现：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002187', 'source-doc-4c784a84a66adf221597', 'source-node-002186', '5', '2186', 'text', '非侵染性：主干、主枝从皮孔 / 伤口流乳白色树脂，凝结后变红褐色硬胶，病部皮层腐朽，叶小黄化；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002188', 'source-doc-4c784a84a66adf221597', 'source-node-002186', '5', '2187', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002189', 'source-doc-4c784a84a66adf221597', 'source-node-002188', '6', '2188', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002190', 'source-doc-4c784a84a66adf221597', 'source-node-002186', '5', '2189', 'text', '侵染性：1 年生枝生 1-4mm 瘤状突起，翌年流胶，病斑下陷生小黑点，枝干坏死。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002191', 'source-doc-4c784a84a66adf221597', 'source-node-002185', '4', '2190', 'text', '发病规律：非侵染性与冻害、修剪伤、土壤黏重有关；侵染性病菌在病枝越冬，5-6 月、8-9 月为发病高峰，伤口多、树弱果园重发。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002192', 'source-doc-4c784a84a66adf221597', 'source-node-002185', '4', '2191', 'text', '预防方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002193', 'source-doc-4c784a84a66adf221597', 'source-node-002192', '5', '2192', 'text', '冬季树干涂白（生石灰 10 份 + 硫磺 1 份 + 食盐 0.5 份 + 水 40 份），避免修剪过重；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002194', 'source-doc-4c784a84a66adf221597', 'source-node-002192', '5', '2193', 'text', '增施有机肥，改良黏重土壤。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002195', 'source-doc-4c784a84a66adf221597', 'source-node-002185', '4', '2194', 'text', '防治药剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002196', 'source-doc-4c784a84a66adf221597', 'source-node-002195', '5', '2195', 'text', '预防：萌芽前喷 3-5 波美度石硫合剂，雨季前喷 80% 代森锰锌可湿性粉剂 600 倍液；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002197', 'source-doc-4c784a84a66adf221597', 'source-node-002195', '5', '2196', 'text', '治疗：刮除胶块后涂 70% 甲基硫菌灵可湿性粉剂 100 倍液，或喷 25% 苯醚甲环唑乳油 2000 倍液、40% 氟硅唑乳油 3000 倍液。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002198', 'source-doc-4c784a84a66adf221597', 'source-node-002173', '3', '2197', 'text', '（三）桃缩叶病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002199', 'source-doc-4c784a84a66adf221597', 'source-node-002198', '4', '2198', 'text', '症状表现：叶片展叶后卷曲皱缩，增厚变脆，初淡绿后紫红，表面生白色粉状物，后期干枯脱落；花腐后不结果，果实畸形龟裂。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002200', 'source-doc-4c784a84a66adf221597', 'source-node-002198', '4', '2199', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002201', 'source-doc-4c784a84a66adf221597', 'source-node-002200', '5', '2200', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002202', 'source-doc-4c784a84a66adf221597', 'source-node-002198', '4', '2201', 'text', '发病规律：病菌在芽鳞越冬，10-16℃、湿度＞80%（萌芽至展叶期）易侵染，早熟品种重发。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002203', 'source-doc-4c784a84a66adf221597', 'source-node-002198', '4', '2202', 'text', '预防方法：冬季清园烧毁病叶，萌芽前彻底喷药。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002204', 'source-doc-4c784a84a66adf221597', 'source-node-002198', '4', '2203', 'text', '防治药剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002205', 'source-doc-4c784a84a66adf221597', 'source-node-002204', '5', '2204', 'text', '预防：花芽露红前喷 3-5 波美度石硫合剂，或 12% 苯醚甲环唑悬浮剂 2000 倍液；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002206', 'source-doc-4c784a84a66adf221597', 'source-node-002204', '5', '2205', 'text', '治疗：展叶后发病喷 80% 代森锰锌可湿性粉剂 600 倍液、50% 多菌灵可湿性粉剂 800 倍液。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002207', 'source-doc-4c784a84a66adf221597', 'source-node-002173', '3', '2206', 'text', '（四）桃炭疽病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002208', 'source-doc-4c784a84a66adf221597', 'source-node-002207', '4', '2207', 'text', '症状表现：果实初现淡褐色圆形小斑，渐扩大为深褐色凹陷斑，表面生黑色小点（分生孢子盘），潮湿时溢出粉红色黏液；病果易脱落或干缩成僵果。枝梢受害生褐色椭圆形病斑，环绕枝条后致其枯死；嫩叶偶发病，生褐色斑后脱落形成穿孔。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002209', 'source-doc-4c784a84a66adf221597', 'source-node-002207', '4', '2208', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002210', 'source-doc-4c784a84a66adf221597', 'source-node-002209', '5', '2209', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002211', 'source-doc-4c784a84a66adf221597', 'source-node-002207', '4', '2210', 'text', '发病规律：病菌在病枝、僵果越冬，借风雨传播，22-27℃、湿度＞95% 易发病，果实硬核期后开始侵染，近成熟期（6-8 月）为发病高峰，低洼、通风差果园重发，早熟品种更易感病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002212', 'source-doc-4c784a84a66adf221597', 'source-node-002207', '4', '2211', 'text', '预防方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002213', 'source-doc-4c784a84a66adf221597', 'source-node-002212', '5', '2212', 'text', '冬季清园烧毁病枝僵果，春季萌芽前喷药；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002214', 'source-doc-4c784a84a66adf221597', 'source-node-002212', '5', '2213', 'text', '果实谢花后 15 天套袋（套袋前喷药），增施磷钾肥，控制负载量。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002215', 'source-doc-4c784a84a66adf221597', 'source-node-002207', '4', '2214', 'text', '防治药剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002216', 'source-doc-4c784a84a66adf221597', 'source-node-002215', '5', '2215', 'text', '预防：萌芽前喷 3-5 波美度石硫合剂，花后喷 80% 代森锰锌可湿性粉剂 600 倍液；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002217', 'source-doc-4c784a84a66adf221597', 'source-node-002215', '5', '2216', 'text', '治疗：发病初期喷 25% 苯醚甲环唑乳油 2000 倍液、40% 咪鲜胺乳油 1500 倍液、50% 啶氧菌酯水分散粒剂 3000 倍液，间隔 10-15 天，连喷 2-3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002218', 'source-doc-4c784a84a66adf221597', 'source-node-002173', '3', '2217', 'text', '（五）桃疮痂病（桃黑星病）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002219', 'source-doc-4c784a84a66adf221597', 'source-node-002218', '4', '2218', 'text', '症状表现：果实受害生暗绿色圆形小斑（直径 2-3mm），渐变为褐色至黑色，病斑周围组织隆起，中央凹陷呈 “鸟眼状”，多集中在果实肩部，严重时果面粗糙失商品性。叶片生淡绿色小斑，后变褐色，周围变黄，后期脱落形成穿孔；枝梢生褐色小斑，渐扩大为黑色隆起斑，表面粗糙。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002220', 'source-doc-4c784a84a66adf221597', 'source-node-002218', '4', '2219', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002221', 'source-doc-4c784a84a66adf221597', 'source-node-002220', '5', '2220', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002222', 'source-doc-4c784a84a66adf221597', 'source-node-002218', '4', '2221', 'text', '发病规律：病菌在病枝梢越冬，借风雨传播，20-25℃、湿度＞85% 易发病，谢花后开始侵染，果实膨大期（5-7 月）为发病高峰，毛桃比油桃抗病，通风差、湿度高果园重发。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002223', 'source-doc-4c784a84a66adf221597', 'source-node-002218', '4', '2222', 'text', '预防方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002224', 'source-doc-4c784a84a66adf221597', 'source-node-002223', '5', '2223', 'text', '冬季修剪清除病枝，早春喷 3-5 波美度石硫合剂；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002225', 'source-doc-4c784a84a66adf221597', 'source-node-002223', '5', '2224', 'text', '合理修剪保持树冠通风，雨季及时排水，果实谢花后 20 天套袋。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002226', 'source-doc-4c784a84a66adf221597', 'source-node-002218', '4', '2225', 'text', '防治药剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002227', 'source-doc-4c784a84a66adf221597', 'source-node-002226', '5', '2226', 'text', '预防：套袋前喷 70% 甲基硫菌灵可湿性粉剂 800 倍液、50% 多菌灵可湿性粉剂 800 倍液；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002228', 'source-doc-4c784a84a66adf221597', 'source-node-002226', '5', '2227', 'text', '治疗：发病初期喷 25% 戊唑醇水乳剂 2000 倍液、40% 氟硅唑乳油 3000 倍液、60% 唑醚・代森联水分散粒剂 1500 倍液，间隔 10 天，连喷 2 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002229', 'source-doc-4c784a84a66adf221597', 'source-node-002149', '2', '2228', 'text', '三、桃树生理病害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002230', 'source-doc-4c784a84a66adf221597', 'source-node-002229', '3', '2229', 'text', '（一）桃树裂果病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002231', 'source-doc-4c784a84a66adf221597', 'source-node-002230', '4', '2230', 'text', '症状表现：果实近成熟期生纵向 / 横向裂缝，裂缝处果肉外露，易感染病菌腐烂，不同品种裂果部位不同（顶端或侧面）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002232', 'source-doc-4c784a84a66adf221597', 'source-node-002230', '4', '2231', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002233', 'source-doc-4c784a84a66adf221597', 'source-node-002232', '5', '2232', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002234', 'source-doc-4c784a84a66adf221597', 'source-node-002230', '4', '2233', 'text', '发病规律：皮薄品种、果实期土壤水分骤变（久旱遇雨）、缺钙 / 硼、负载过重易发病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002235', 'source-doc-4c784a84a66adf221597', 'source-node-002230', '4', '2234', 'text', '预防方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002236', 'source-doc-4c784a84a66adf221597', 'source-node-002235', '5', '2235', 'text', '选抗裂品种（如金秋红蜜），果实膨大期覆盖地膜保墒；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002237', 'source-doc-4c784a84a66adf221597', 'source-node-002235', '5', '2236', 'text', '花后喷 0.3% 氯化钙溶液补钙。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002238', 'source-doc-4c784a84a66adf221597', 'source-node-002230', '4', '2237', 'text', '防治药剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002239', 'source-doc-4c784a84a66adf221597', 'source-node-002238', '5', '2238', 'text', '预防：果实膨大期每 10 天喷 1 次 0.2% 硼砂 + 0.3% 硝酸钙混合液；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002240', 'source-doc-4c784a84a66adf221597', 'source-node-002238', '5', '2239', 'text', '辅助：裂果初期喷 5% 丙二醇溶液，减少水分失衡。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002241', 'source-doc-4c784a84a66adf221597', 'source-node-002229', '3', '2240', 'text', '（二）桃树缺素症（常见类型）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002242', 'source-doc-4c784a84a66adf221597', 'source-node-002241', '4', '2241', 'text', '缺铁症：新叶叶脉间失绿呈黄白色，严重时全叶白化，叶缘焦枯。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002243', 'source-doc-4c784a84a66adf221597', 'source-node-002242', '5', '2242', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002244', 'source-doc-4c784a84a66adf221597', 'source-node-002243', '6', '2243', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002245', 'source-doc-4c784a84a66adf221597', 'source-node-002242', '5', '2244', 'text', '预防：酸性土壤施硫磺粉（每亩 10-15kg），增施有机肥；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002246', 'source-doc-4c784a84a66adf221597', 'source-node-002242', '5', '2245', 'text', '治疗：叶面喷 0.1% 硫酸亚铁 + 0.1% 柠檬酸混合液，连喷 2-3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002247', 'source-doc-4c784a84a66adf221597', 'source-node-002241', '4', '2246', 'text', '缺硼症：新梢顶芽坏死，叶尖卷曲，果实表皮凹陷、果肉木栓化（缩果病）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002248', 'source-doc-4c784a84a66adf221597', 'source-node-002247', '5', '2247', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002249', 'source-doc-4c784a84a66adf221597', 'source-node-002248', '6', '2248', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002250', 'source-doc-4c784a84a66adf221597', 'source-node-002247', '5', '2249', 'text', '预防：花前土施硼砂（每亩 0.5-1kg）；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002251', 'source-doc-4c784a84a66adf221597', 'source-node-002247', '5', '2250', 'text', '治疗：花期喷 0.2% 硼酸溶液，间隔 7 天喷 1 次，连喷 2 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002252', 'source-doc-4c784a84a66adf221597', 'source-node-002229', '3', '2251', 'text', '（三）桃树日灼病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002253', 'source-doc-4c784a84a66adf221597', 'source-node-002252', '4', '2252', 'text', '症状表现：果实向阳面先出现淡褐色水渍状斑，渐变为褐色至黑褐色硬斑，斑界清晰，受害果肉坏死、质地变硬，失去食用价值；叶片受害生黄褐色不规则枯斑，严重时叶片边缘焦枯脱落。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002254', 'source-doc-4c784a84a66adf221597', 'source-node-002252', '4', '2253', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002255', 'source-doc-4c784a84a66adf221597', 'source-node-002254', '5', '2254', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002256', 'source-doc-4c784a84a66adf221597', 'source-node-002252', '4', '2255', 'text', '发生规律：夏季高温强光（气温＞35℃、光照强度＞10 万 lux）引发，果实膨大期（6-8 月）重发；果皮薄、着色早的品种（如白凤桃）易感病，果园通风差、土壤缺水、果实暴露无遮阴时发病重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002257', 'source-doc-4c784a84a66adf221597', 'source-node-002252', '4', '2256', 'text', '预防方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002258', 'source-doc-4c784a84a66adf221597', 'source-node-002257', '5', '2257', 'text', '果实套袋（选用浅色透气袋），套袋前喷 0.3% 氯化钙溶液增强果皮韧性；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002259', 'source-doc-4c784a84a66adf221597', 'source-node-002257', '5', '2258', 'text', '夏季修剪时保留果穗附近叶片遮阴，高温期正午喷水降温（早 10 点前、晚 4 点后），地面覆盖秸秆保墒。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002260', 'source-doc-4c784a84a66adf221597', 'source-node-002252', '4', '2259', 'text', '防治药剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002261', 'source-doc-4c784a84a66adf221597', 'source-node-002260', '5', '2260', 'text', '预防：果实膨大期每 15 天喷 1 次 0.2% 磷酸二氢钾 + 0.1% 维生素 C 混合液，提高抗热能力；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002262', 'source-doc-4c784a84a66adf221597', 'source-node-002260', '5', '2261', 'text', '辅助：轻微日灼果喷 5% 丙二醇溶液，减少水分蒸发，缓解受害程度。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002263', 'source-doc-4c784a84a66adf221597', 'source-node-002229', '3', '2262', 'text', '（四）桃树冻害（生理型）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002264', 'source-doc-4c784a84a66adf221597', 'source-node-002263', '4', '2263', 'text', '症状表现：冬季冻害：枝干皮层变褐、开裂，严重时树皮剥落，木质部发黑；芽体变褐干瘪，春季不能萌发。早春冻害：花器受冻后花瓣变褐、柱头枯萎，不能授粉坐果；幼果冻害后变褐脱落，或果面生凹陷冻斑。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002265', 'source-doc-4c784a84a66adf221597', 'source-node-002263', '4', '2264', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002266', 'source-doc-4c784a84a66adf221597', 'source-node-002265', '5', '2265', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002267', 'source-doc-4c784a84a66adf221597', 'source-node-002263', '4', '2266', 'text', '发生规律：低温骤降（冬季气温＜-15℃、早春倒春寒＜0℃）引发，树势弱、养分积累不足的树体易感冻；砧木抗冻性差异大（山桃砧比毛桃砧抗冻），果园地势低洼、冷空气易沉积处发病重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002268', 'source-doc-4c784a84a66adf221597', 'source-node-002263', '4', '2267', 'text', '预防方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002269', 'source-doc-4c784a84a66adf221597', 'source-node-002268', '5', '2268', 'text', '冬季树干涂白（生石灰 12 份 + 硫磺 2 份 + 食盐 1 份 + 水 40 份），树干基部培土 30cm 防冻；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002270', 'source-doc-4c784a84a66adf221597', 'source-node-002268', '5', '2269', 'text', '秋季增施有机肥（避免晚施氮肥），提高树体抗冻性；早春寒流前果园熏烟（每亩放 5-8 个烟堆）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002271', 'source-doc-4c784a84a66adf221597', 'source-node-002263', '4', '2270', 'text', '防治药剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002272', 'source-doc-4c784a84a66adf221597', 'source-node-002271', '5', '2271', 'text', '预防：秋季落叶前喷 5% 丙二醇溶液，增强枝条抗冻性；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002273', 'source-doc-4c784a84a66adf221597', 'source-node-002271', '5', '2272', 'text', '补救：冻害后喷 0.3% 尿素 + 0.2% 磷酸二氢钾混合液，枝干冻裂处涂 50% 多菌灵可湿性粉剂 100 倍液 + 凡士林混合剂，促进伤口愈合。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002274', 'source-doc-4c784a84a66adf221597', 'source-node-002149', '2', '2273', 'text', '四、桃树药害与肥害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002275', 'source-doc-4c784a84a66adf221597', 'source-node-002274', '3', '2274', 'text', '（一）桃树药害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002276', 'source-doc-4c784a84a66adf221597', 'source-node-002275', '4', '2275', 'text', '症状表现：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002277', 'source-doc-4c784a84a66adf221597', 'source-node-002276', '5', '2276', 'text', '叶面药害：叶生斑点、黄化卷曲（如有机磷药害），或生褐色枯斑（如铜制剂药害）；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002278', 'source-doc-4c784a84a66adf221597', 'source-node-002276', '5', '2277', 'text', '果实药害：果面斑点、畸形（如乳油类农药），或裂果（如激素类药害）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002279', 'source-doc-4c784a84a66adf221597', 'source-node-002276', '5', '2278', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002280', 'source-doc-4c784a84a66adf221597', 'source-node-002279', '6', '2279', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002281', 'source-doc-4c784a84a66adf221597', 'source-node-002275', '4', '2280', 'text', '预防方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002282', 'source-doc-4c784a84a66adf221597', 'source-node-002281', '5', '2281', 'text', '新农药先小范围试喷，避免花期、幼果期喷高毒农药；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002283', 'source-doc-4c784a84a66adf221597', 'source-node-002281', '5', '2282', 'text', '严格按说明书配药，不随意混配（如波尔多液不与碱性药混用）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002284', 'source-doc-4c784a84a66adf221597', 'source-node-002275', '4', '2283', 'text', '补救措施：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002285', 'source-doc-4c784a84a66adf221597', 'source-node-002284', '5', '2284', 'text', '清水冲洗树体，叶面喷 0.3% 尿素 + 0.2% 磷酸二氢钾混合液；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002286', 'source-doc-4c784a84a66adf221597', 'source-node-002284', '5', '2285', 'text', '有机磷药害喷 0.05% 阿托品，铜制剂药害喷 0.5% 石灰水。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002287', 'source-doc-4c784a84a66adf221597', 'source-node-002274', '3', '2286', 'text', '（二）桃树肥害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002288', 'source-doc-4c784a84a66adf221597', 'source-node-002287', '4', '2287', 'text', '症状表现：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002289', 'source-doc-4c784a84a66adf221597', 'source-node-002288', '5', '2288', 'text', '根系肥害：根变褐腐烂，无新根；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002290', 'source-doc-4c784a84a66adf221597', 'source-node-002288', '5', '2289', 'text', '叶面肥害：叶尖焦枯、黄化（如过量施氮），或叶缘卷曲（如过量施钾）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002291', 'source-doc-4c784a84a66adf221597', 'source-node-002288', '5', '2290', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002292', 'source-doc-4c784a84a66adf221597', 'source-node-002291', '6', '2291', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002293', 'source-doc-4c784a84a66adf221597', 'source-node-002287', '4', '2292', 'text', '预防方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002294', 'source-doc-4c784a84a66adf221597', 'source-node-002293', '5', '2293', 'text', '有机肥充分腐熟，化肥沟施不接触根系；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002295', 'source-doc-4c784a84a66adf221597', 'source-node-002293', '5', '2294', 'text', '避免一次施过量氮肥（如尿素每亩不超过 20kg）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002296', 'source-doc-4c784a84a66adf221597', 'source-node-002287', '4', '2295', 'text', '补救措施：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002297', 'source-doc-4c784a84a66adf221597', 'source-node-002296', '5', '2296', 'text', '及时灌水稀释，中耕松土；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002298', 'source-doc-4c784a84a66adf221597', 'source-node-002296', '5', '2297', 'text', '叶面喷 0.3% 磷酸二氢钾溶液，促进根系恢复。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002299', 'source-doc-4c784a84a66adf221597', 'source-node-002149', '2', '2298', 'text', '五、桃树虫害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002300', 'source-doc-4c784a84a66adf221597', 'source-node-002299', '3', '2299', 'text', '（一）桃蚜', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002301', 'source-doc-4c784a84a66adf221597', 'source-node-002300', '4', '2300', 'text', '症状表现：成虫、若虫群集叶背、嫩梢吸汁，叶卷曲黄化，分泌蜜露诱发病煤病，新梢生长受阻。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002302', 'source-doc-4c784a84a66adf221597', 'source-node-002300', '4', '2301', 'text', '发生规律：一年 10-20 代，卵在芽鳞越冬，春季孵化危害，5-6 月高峰，夏季迁飞，秋季回桃树产卵。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002303', 'source-doc-4c784a84a66adf221597', 'source-node-002300', '4', '2302', 'text', '预防方法：冬季清园刮老皮，春季挂黄板（每亩 20 块）诱杀。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002304', 'source-doc-4c784a84a66adf221597', 'source-node-002300', '4', '2303', 'text', '防治药剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002305', 'source-doc-4c784a84a66adf221597', 'source-node-002304', '5', '2304', 'text', '预防：萌芽前喷 3-5 波美度石硫合剂；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002306', 'source-doc-4c784a84a66adf221597', 'source-node-002304', '5', '2305', 'text', '治疗：发病初期喷 10% 吡虫啉可湿性粉剂 2000 倍液、25% 噻虫嗪水分散粒剂 3000 倍液、5% 高效氯氟氰菊酯乳油 1500 倍液。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002307', 'source-doc-4c784a84a66adf221597', 'source-node-002300', '4', '2306', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002308', 'source-doc-4c784a84a66adf221597', 'source-node-002307', '5', '2307', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002309', 'source-doc-4c784a84a66adf221597', 'source-node-002300', '4', '2308', 'text', '桃瘤蚜', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002310', 'source-doc-4c784a84a66adf221597', 'source-node-002309', '5', '2309', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002311', 'source-doc-4c784a84a66adf221597', 'source-node-002299', '3', '2310', 'text', '（二）桃小食心虫', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002312', 'source-doc-4c784a84a66adf221597', 'source-node-002311', '4', '2311', 'text', '症状表现：幼虫蛀果，果面留针头大蛀孔，孔外排粪，果肉形成 “豆沙馅” 虫道，果实变畸形（猴头果），易脱落。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002313', 'source-doc-4c784a84a66adf221597', 'source-node-002311', '4', '2312', 'text', '发生规律：一年 1-2 代，老熟幼虫在土中结茧越冬，6-7 月、8-9 月为幼虫危害高峰。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002314', 'source-doc-4c784a84a66adf221597', 'source-node-002311', '4', '2313', 'text', '预防方法：冬季翻耕土壤，春季地面覆盖地膜（阻止幼虫出土），挂性诱剂（每亩 3 个）诱杀成虫。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002315', 'source-doc-4c784a84a66adf221597', 'source-node-002311', '4', '2314', 'text', '防治药剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002316', 'source-doc-4c784a84a66adf221597', 'source-node-002315', '5', '2315', 'text', '预防：地面喷 5% 辛硫磷颗粒剂（每亩 2kg）+ 细土拌匀撒施；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002317', 'source-doc-4c784a84a66adf221597', 'source-node-002315', '5', '2316', 'text', '治疗：幼虫孵化期喷 20% 氯虫苯甲酰胺悬浮剂 3000 倍液、5% 甲氨基阿维菌素苯甲酸盐微乳剂 2000 倍液。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002318', 'source-doc-4c784a84a66adf221597', 'source-node-002311', '4', '2317', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002319', 'source-doc-4c784a84a66adf221597', 'source-node-002318', '5', '2318', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002320', 'source-doc-4c784a84a66adf221597', 'source-node-002299', '3', '2319', 'text', '（三）红蜘蛛（叶螨）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002321', 'source-doc-4c784a84a66adf221597', 'source-node-002320', '4', '2320', 'text', '症状表现：成虫、若虫叶背吸汁，叶现黄白色小点，渐扩为斑块，严重时叶失绿脱落，树势衰弱。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002322', 'source-doc-4c784a84a66adf221597', 'source-node-002320', '4', '2321', 'text', '发生规律：一年 10-15 代，雌成虫在树皮缝越冬，25-30℃、湿度＜60% 易爆发，6-8 月危害重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002323', 'source-doc-4c784a84a66adf221597', 'source-node-002320', '4', '2322', 'text', '预防方法：冬季清园刮老皮，挂黄板诱杀，保护捕食螨（天敌）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002324', 'source-doc-4c784a84a66adf221597', 'source-node-002320', '4', '2323', 'text', '防治药剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002325', 'source-doc-4c784a84a66adf221597', 'source-node-002324', '5', '2324', 'text', '预防：萌芽前喷 3-5 波美度石硫合剂；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002326', 'source-doc-4c784a84a66adf221597', 'source-node-002324', '5', '2325', 'text', '治疗：发病初期喷 20% 螺螨酯悬浮剂 3000 倍液、1.8% 阿维菌素乳油 2000 倍液、5% 哒螨灵乳油 1500 倍液，重点喷叶背。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002327', 'source-doc-4c784a84a66adf221597', 'source-node-002320', '4', '2326', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002328', 'source-doc-4c784a84a66adf221597', 'source-node-002327', '5', '2327', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002329', 'source-doc-4c784a84a66adf221597', 'source-node-002299', '3', '2328', 'text', '（四）桃蛀螟', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002330', 'source-doc-4c784a84a66adf221597', 'source-node-002329', '4', '2329', 'text', '症状表现：幼虫蛀果危害，先在果面啃食成小坑，后蛀入果内取食果肉和种子，虫道内充满粪便，果面蛀孔外排黄褐色黏粪；受害果易腐烂脱落，严重时一个果内有多头幼虫。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002331', 'source-doc-4c784a84a66adf221597', 'source-node-002329', '4', '2330', 'text', '发生规律：一年 3-4 代，老熟幼虫在树皮缝、杂草、秸秆中越冬，成虫昼伏夜出，产卵于果实萼洼、梗洼处，5-9 月为幼虫危害期，早熟品种、果实套袋不及时果园重发。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002332', 'source-doc-4c784a84a66adf221597', 'source-node-002329', '4', '2331', 'text', '预防方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002333', 'source-doc-4c784a84a66adf221597', 'source-node-002332', '5', '2332', 'text', '冬季清园烧毁杂草秸秆，春季挂桃蛀螟性诱剂（每亩 5 个）诱杀成虫；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002334', 'source-doc-4c784a84a66adf221597', 'source-node-002332', '5', '2333', 'text', '果实膨大期及时套袋，套袋前喷药杀灭卵和初孵幼虫。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002335', 'source-doc-4c784a84a66adf221597', 'source-node-002329', '4', '2334', 'text', '防治药剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002336', 'source-doc-4c784a84a66adf221597', 'source-node-002335', '5', '2335', 'text', '预防：成虫产卵期喷 5% 高效氯氟氰菊酯乳油 1500 倍液、20% 甲氰菊酯乳油 2000 倍液；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002337', 'source-doc-4c784a84a66adf221597', 'source-node-002335', '5', '2336', 'text', '治疗：幼虫孵化期喷 20% 氯虫苯甲酰胺悬浮剂 3000 倍液、5% 甲氨基阿维菌素苯甲酸盐微乳剂 2000 倍液、40% 毒死蜱（在蔬菜、果树、茶叶、中草药材上不得使用）乳油 1000 倍液，间隔 7-10 天，连喷 2 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002338', 'source-doc-4c784a84a66adf221597', 'source-node-002329', '4', '2337', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002339', 'source-doc-4c784a84a66adf221597', 'source-node-002338', '5', '2338', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002340', 'source-doc-4c784a84a66adf221597', 'source-node-002299', '3', '2339', 'text', '（五）桑白蚧', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002341', 'source-doc-4c784a84a66adf221597', 'source-node-002340', '4', '2340', 'text', '症状表现：成虫、若虫群集枝干吸食汁液，雌虫介壳白色圆形，雄虫介壳白色长筒形；受害枝干被介壳覆盖，表面灰白，皮层萎缩，树势衰弱，叶片发黄，严重时枝干枯死。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002342', 'source-doc-4c784a84a66adf221597', 'source-node-002340', '4', '2341', 'text', '发生规律：一年 2-3 代，受精雌成虫在枝干上越冬，春季桃树萌芽时产卵，若虫孵化后爬行至枝干固定危害，分泌蜡质形成介壳，5-6 月、8-9 月为若虫危害高峰，管理粗放果园重发。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002343', 'source-doc-4c784a84a66adf221597', 'source-node-002340', '4', '2342', 'text', '预防方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002344', 'source-doc-4c784a84a66adf221597', 'source-node-002343', '5', '2343', 'text', '冬季人工刮除枝干上的介壳，早春喷 3-5 波美度石硫合剂；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002345', 'source-doc-4c784a84a66adf221597', 'source-node-002343', '5', '2344', 'text', '合理修剪，清除被害严重的枝条，保护瓢虫、寄生蜂等天敌。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002346', 'source-doc-4c784a84a66adf221597', 'source-node-002340', '4', '2345', 'text', '防治药剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002347', 'source-doc-4c784a84a66adf221597', 'source-node-002346', '5', '2346', 'text', '预防：萌芽前喷 45% 石硫合剂晶体 30 倍液，杀灭越冬雌虫；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002348', 'source-doc-4c784a84a66adf221597', 'source-node-002346', '5', '2347', 'text', '治疗：若虫孵化期（未形成介壳前）喷 25% 噻嗪酮可湿性粉剂 1500 倍液、40% 螺虫乙酯悬浮剂 4000 倍液、22% 噻虫・高氯氟微囊悬浮剂 2000 倍液，间隔 7 天，连喷 2 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002349', 'source-doc-4c784a84a66adf221597', 'source-node-002340', '4', '2348', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002350', 'source-doc-4c784a84a66adf221597', 'source-node-002349', '5', '2349', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002351', 'source-doc-4c784a84a66adf221597', 'source-node-002299', '3', '2350', 'text', '（六）梨小食心虫', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002352', 'source-doc-4c784a84a66adf221597', 'source-node-002351', '4', '2351', 'text', '症状表现：幼虫蛀食新梢时，梢顶枯萎下垂（“折梢”），蛀孔外排粪；蛀食果实多从萼洼、梗洼侵入，果肉内形成虫道，果面留小黑点，受害果易腐烂脱落。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002353', 'source-doc-4c784a84a66adf221597', 'source-node-002351', '4', '2352', 'text', '发生规律：一年 4-5 代，老熟幼虫在树皮缝、杂草中越冬，成虫昼伏夜出，产卵于新梢嫩叶或果实表面，春季（4-5 月）先危害新梢，夏季（6-8 月）转向果实，桃梨混栽园发病重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002354', 'source-doc-4c784a84a66adf221597', 'source-node-002351', '4', '2353', 'text', '预防方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002355', 'source-doc-4c784a84a66adf221597', 'source-node-002354', '5', '2354', 'text', '冬季清园刮老皮，春季及时剪除被害新梢并烧毁；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002356', 'source-doc-4c784a84a66adf221597', 'source-node-002354', '5', '2355', 'text', '挂梨小食心虫性诱剂（每亩 4 个）诱杀成虫，果实套袋阻隔幼虫蛀入。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002357', 'source-doc-4c784a84a66adf221597', 'source-node-002351', '4', '2356', 'text', '防治药剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002358', 'source-doc-4c784a84a66adf221597', 'source-node-002357', '5', '2357', 'text', '预防：新梢生长期喷 80% 敌敌畏乳油 1000 倍液，减少梢部虫源；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002359', 'source-doc-4c784a84a66adf221597', 'source-node-002357', '5', '2358', 'text', '治疗：幼虫孵化期喷 5% 甲氨基阿维菌素苯甲酸盐微乳剂 2000 倍液、20% 茚虫威悬浮剂 3000 倍液、10% 溴氰虫酰胺悬浮剂 2000 倍液，间隔 10 天，连喷 2 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002360', 'source-doc-4c784a84a66adf221597', 'source-node-002351', '4', '2359', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002361', 'source-doc-4c784a84a66adf221597', 'source-node-002360', '5', '2360', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002362', 'source-doc-4c784a84a66adf221597', 'source-node-002299', '3', '2361', 'text', '（七）桃红颈天牛', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002363', 'source-doc-4c784a84a66adf221597', 'source-node-002362', '4', '2362', 'text', '症状表现：幼虫蛀食主干、主枝木质部，形成弯曲虫道，虫道内充满木屑和粪便，从蛀孔外排出红褐色虫粪；受害枝干皮层开裂、流胶，树势衰弱，叶片发黄，严重时枝干中空枯死。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002364', 'source-doc-4c784a84a66adf221597', 'source-node-002362', '4', '2363', 'text', '发生规律：2-3 年发生 1 代，幼虫在枝干木质部越冬，成虫 5-6 月羽化，正午活动频繁，产卵于树干皮缝处；树龄大、树皮粗糙的桃树易感病，管理粗放、未及时防治的果园重发。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002365', 'source-doc-4c784a84a66adf221597', 'source-node-002362', '4', '2364', 'text', '预防方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002366', 'source-doc-4c784a84a66adf221597', 'source-node-002365', '5', '2365', 'text', '冬季人工钩杀幼虫（用铁丝伸入虫道），成虫羽化期人工捕捉（正午在树干上捉拿）；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002367', 'source-doc-4c784a84a66adf221597', 'source-node-002365', '5', '2366', 'text', '5 月成虫产卵前树干涂白（加入 40% 毒死蜱（在蔬菜、果树、茶叶、中草药材上不得使用）乳油 50 倍液），阻止产卵。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002368', 'source-doc-4c784a84a66adf221597', 'source-node-002362', '4', '2367', 'text', '防治药剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002369', 'source-doc-4c784a84a66adf221597', 'source-node-002368', '5', '2368', 'text', '预防：成虫羽化前在树干上喷 40% 毒死蜱（在蔬菜、果树、茶叶、中草药材上不得使用）乳油 500 倍液，杀灭产卵成虫；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002370', 'source-doc-4c784a84a66adf221597', 'source-node-002368', '5', '2369', 'text', '治疗：发现虫道后，用注射器向虫道内注入 40% 毒死蜱（在蔬菜、果树、茶叶、中草药材上不得使用）乳油 50 倍液，每虫道注 5-10ml，注后用泥土封口，杀灭幼虫。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002371', 'source-doc-4c784a84a66adf221597', 'source-node-002362', '4', '2370', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002372', 'source-doc-4c784a84a66adf221597', 'source-node-002371', '5', '2371', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002373', 'source-doc-4c784a84a66adf221597', 'source-node-002299', '3', '2372', 'text', '（八）金龟子（铜绿丽金龟、暗黑鳃金龟）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002374', 'source-doc-4c784a84a66adf221597', 'source-node-002373', '4', '2373', 'text', '症状表现：成虫啃食叶片，造成叶片缺刻、孔洞，严重时将叶片吃光；成虫也啃食果实，在果面形成不规则凹陷斑，引发果实腐烂；幼虫（蛴螬）在土壤中啃食根系，导致根系腐烂，树体生长衰弱。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002375', 'source-doc-4c784a84a66adf221597', 'source-node-002373', '4', '2374', 'text', '发生规律：一年 1 代，幼虫在土壤中越冬，成虫 5-7 月羽化，傍晚活动取食，趋光性强；果园周边有荒地、草丛时虫源多，沙质土壤、有机质丰富的果园幼虫危害重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002376', 'source-doc-4c784a84a66adf221597', 'source-node-002373', '4', '2375', 'text', '预防方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002377', 'source-doc-4c784a84a66adf221597', 'source-node-002376', '5', '2376', 'text', '冬季翻耕土壤，冻死越冬幼虫；成虫期安装黑光灯（每亩 1 盏）诱杀，或放置糖醋液（红糖 3 份 + 醋 6 份 + 白酒 1 份 + 水 10 份 + 敌百虫 0.5 份）诱杀；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002378', 'source-doc-4c784a84a66adf221597', 'source-node-002376', '5', '2377', 'text', '避免果园周边种植花生、大豆等易招金龟子的作物。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002379', 'source-doc-4c784a84a66adf221597', 'source-node-002373', '4', '2378', 'text', '防治药剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002380', 'source-doc-4c784a84a66adf221597', 'source-node-002379', '5', '2379', 'text', '幼虫防治：春季土壤解冻后，每亩撒施 5% 辛硫磷颗粒剂 2-3kg + 细土拌匀，翻耕入土；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002381', 'source-doc-4c784a84a66adf221597', 'source-node-002379', '5', '2380', 'text', '成虫防治：成虫危害期喷 5% 高效氯氟氰菊酯乳油 1500 倍液、20% 氰戊菊酯乳油 2000 倍液，傍晚喷施效果佳，间隔 7 天，连喷 2 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002382', 'source-doc-4c784a84a66adf221597', 'source-node-002373', '4', '2381', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002383', 'source-doc-4c784a84a66adf221597', 'source-node-002382', '5', '2382', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002384', 'source-doc-4c784a84a66adf221597', 'source-node-002149', '2', '2383', 'text', '六、桃树病毒病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002385', 'source-doc-4c784a84a66adf221597', 'source-node-002384', '3', '2384', 'text', '（一）桃红叶病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002386', 'source-doc-4c784a84a66adf221597', 'source-node-002384', '3', '2385', 'text', '症状表现：叶初现不规则黄色斑点，渐变为红色斑块，叶质脆易落；新梢细弱，结果少且小，病树分布呈集中性（区别于缺素）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002387', 'source-doc-4c784a84a66adf221597', 'source-node-002384', '3', '2386', 'text', '发生规律：病毒借嫁接、蚜虫 / 叶蝉传播，大久保、早丰等品种敏感，树弱、肥力差果园重发。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002388', 'source-doc-4c784a84a66adf221597', 'source-node-002384', '3', '2387', 'text', '预防方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002389', 'source-doc-4c784a84a66adf221597', 'source-node-002388', '4', '2388', 'text', '选无病毒苗（茎尖脱毒苗），嫁接工具用 75% 酒精消毒；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002390', 'source-doc-4c784a84a66adf221597', 'source-node-002388', '4', '2389', 'text', '及时防治蚜虫、叶蝉，增施有机肥增强树势。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002391', 'source-doc-4c784a84a66adf221597', 'source-node-002384', '3', '2390', 'text', '防治药剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002392', 'source-doc-4c784a84a66adf221597', 'source-node-002391', '4', '2391', 'text', '预防：萌芽前喷 2% 宁南霉素水剂 500 倍液；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002393', 'source-doc-4c784a84a66adf221597', 'source-node-002391', '4', '2392', 'text', '治疗：发病初期喷 10% 盐酸吗啉胍可湿性粉剂 500 倍液、85% 三氯异氰尿酸可溶性粉剂 2000 倍液，间隔 10 天喷 1 次，连喷 3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002394', 'source-doc-4c784a84a66adf221597', 'source-node-002384', '3', '2393', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002395', 'source-doc-4c784a84a66adf221597', 'source-node-002394', '4', '2394', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002396', 'source-doc-4c784a84a66adf221597', 'source-node-002384', '3', '2395', 'text', '（二）桃潜隐花叶病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002397', 'source-doc-4c784a84a66adf221597', 'source-node-002396', '4', '2396', 'text', '症状表现：叶现黄绿相间斑驳，或沿叶脉生黄色条带，严重时叶变形、早落；树势弱，果实小、着色差。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002398', 'source-doc-4c784a84a66adf221597', 'source-node-002396', '4', '2397', 'text', '发生规律：病毒借嫁接传播，无明显昆虫媒介，温暖地区全年可发病，树势弱加重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002399', 'source-doc-4c784a84a66adf221597', 'source-node-002396', '4', '2398', 'text', '预防方法：用无病毒接穗，病树及时挖除烧毁。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002400', 'source-doc-4c784a84a66adf221597', 'source-node-002396', '4', '2399', 'text', '防治药剂：发病初期喷 0.5% 菇类蛋白多糖水剂 300 倍液、20% 吗胍・乙酸铜可湿性粉剂 500 倍液，连喷 2-3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002401', 'source-doc-4c784a84a66adf221597', 'source-node-002396', '4', '2400', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002402', 'source-doc-4c784a84a66adf221597', 'source-node-002401', '5', '2401', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002403', 'source-doc-4c784a84a66adf221597', 'source-node-002384', '3', '2402', 'text', '（三）桃环斑病毒病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002404', 'source-doc-4c784a84a66adf221597', 'source-node-002403', '4', '2403', 'text', '症状表现：叶片生黄绿相间的环状斑，或不规则形褪绿斑，严重时叶片变形、卷曲，叶肉变薄；果实表面生环状凹陷斑，果肉木质化，品质下降；树势衰弱，新梢生长缓慢，结果量减少。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002405', 'source-doc-4c784a84a66adf221597', 'source-node-002403', '4', '2404', 'text', '发生规律：病毒借嫁接、蚜虫（桃蚜、棉蚜）传播，带毒苗木是主要初侵染源，温暖干燥气候利于发病，树势弱、土壤贫瘠果园重发，不同品种抗性差异大（水蜜桃较易感病）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002406', 'source-doc-4c784a84a66adf221597', 'source-node-002403', '4', '2405', 'text', '预防方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002407', 'source-doc-4c784a84a66adf221597', 'source-node-002406', '5', '2406', 'text', '选用无病毒苗木（通过茎尖脱毒培育），嫁接时用 75% 酒精消毒工具；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002408', 'source-doc-4c784a84a66adf221597', 'source-node-002406', '5', '2407', 'text', '及时防治蚜虫，避免病毒传播，增施有机肥 + 磷钾肥，增强树势。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002409', 'source-doc-4c784a84a66adf221597', 'source-node-002403', '4', '2408', 'text', '防治药剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002410', 'source-doc-4c784a84a66adf221597', 'source-node-002409', '5', '2409', 'text', '预防：萌芽前喷 2% 宁南霉素水剂 500 倍液，蚜虫发生期喷 25% 噻虫嗪水分散粒剂 3000 倍液；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002411', 'source-doc-4c784a84a66adf221597', 'source-node-002409', '5', '2410', 'text', '治疗：发病初期喷 10% 盐酸吗啉胍可湿性粉剂 500 倍液、0.5% 菇类蛋白多糖水剂 300 倍液、20% 吗胍・乙酸铜可湿性粉剂 500 倍液，间隔 10 天，连喷 3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002412', 'source-doc-4c784a84a66adf221597', 'source-node-002403', '4', '2411', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002413', 'source-doc-4c784a84a66adf221597', 'source-node-002412', '5', '2412', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002414', 'source-doc-4c784a84a66adf221597', 'source-node-002384', '3', '2413', 'text', '（四）桃矮缩病毒病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002415', 'source-doc-4c784a84a66adf221597', 'source-node-002414', '4', '2414', 'text', '症状表现：病树整体矮化，新梢节间缩短，叶片变小、增厚，叶色浓绿且皱缩；花器发育不良，落花落果严重，果实小、畸形，着色差；根系发育受阻，须根少，树势逐年衰弱，严重时 3-5 年枯死。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002416', 'source-doc-4c784a84a66adf221597', 'source-node-002414', '4', '2415', 'text', '发生规律：病毒主要借嫁接传播，无昆虫传播记录，带毒接穗是主要传播途径，高温环境（30℃以上）会加重症状，幼树比成年树易感病，管理粗放、肥水不足果园发病重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002417', 'source-doc-4c784a84a66adf221597', 'source-node-002414', '4', '2416', 'text', '预防方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002418', 'source-doc-4c784a84a66adf221597', 'source-node-002417', '5', '2417', 'text', '严格选用无病毒接穗和苗木，禁止从病园采集接穗；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002419', 'source-doc-4c784a84a66adf221597', 'source-node-002417', '5', '2418', 'text', '加强肥水管理，每年施有机肥（每亩 3000kg）+ 复合肥（每亩 50kg），避免树体衰弱。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002420', 'source-doc-4c784a84a66adf221597', 'source-node-002414', '4', '2419', 'text', '防治药剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002421', 'source-doc-4c784a84a66adf221597', 'source-node-002420', '5', '2420', 'text', '预防：新梢生长期喷 0.3% 磷酸二氢钾 + 0.2% 氨基酸叶面肥混合液，增强树体抗逆性；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002422', 'source-doc-4c784a84a66adf221597', 'source-node-002420', '5', '2421', 'text', '治疗：发病初期喷 2% 宁南霉素水剂 500 倍液、10% 盐酸吗啉胍可湿性粉剂 500 倍液，间隔 15 天，连喷 2-3 次，配合根部灌施 0.5% 腐殖酸溶液，促进根系恢复。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002423', 'source-doc-4c784a84a66adf221597', 'source-node-002414', '4', '2422', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002424', 'source-doc-4c784a84a66adf221597', 'source-node-002423', '5', '2423', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002425', 'source-doc-4c784a84a66adf221597', 'source-node-000545', '1', '2424', 'text', '2.1.5 梨树/秋月梨/鸭梨', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002426', 'source-doc-4c784a84a66adf221597', 'source-node-000545', '1', '2425', 'text', '2.1.6 芒果', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002427', 'source-doc-4c784a84a66adf221597', 'source-node-000545', '1', '2426', 'text', '2.1.7 荔枝', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002428', 'source-doc-4c784a84a66adf221597', 'source-node-000545', '1', '2427', 'text', '2.1.8 龙眼', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002429', 'source-doc-4c784a84a66adf221597', 'source-node-000545', '1', '2428', 'text', '2.1.9 槟榔', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002430', 'source-doc-4c784a84a66adf221597', 'source-node-002429', '2', '2429', 'text', '槟榔芽腐/芯腐病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002431', 'source-doc-4c784a84a66adf221597', 'source-node-002430', '3', '2430', 'text', '真菌性（无臭味）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002432', 'source-doc-4c784a84a66adf221597', 'source-node-002431', '4', '2431', 'text', '防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002433', 'source-doc-4c784a84a66adf221597', 'source-node-002432', '5', '2432', 'text', '灌药药剂：50% 多菌灵可湿性粉剂 500 倍液、70% 甲基托布津可湿性粉剂 600 倍液（二选一即可）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002434', 'source-doc-4c784a84a66adf221597', 'source-node-002432', '5', '2433', 'text', '操作方式：用注射器抽取稀释后的药剂，缓慢注入烂芯内部，确保药剂渗透到深层腐烂部位，避免遗漏。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002435', 'source-doc-4c784a84a66adf221597', 'source-node-002432', '5', '2434', 'text', '用量：根据烂芯深度调整，一般每株每次灌注 200-500ml，以芯部组织充分浸润为准。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002436', 'source-doc-4c784a84a66adf221597', 'source-node-002431', '4', '2435', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002437', 'source-doc-4c784a84a66adf221597', 'source-node-002436', '5', '2436', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002438', 'source-doc-4c784a84a66adf221597', 'source-node-002430', '3', '2437', 'text', '细菌性（有臭味）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002439', 'source-doc-4c784a84a66adf221597', 'source-node-002438', '4', '2438', 'text', '防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002440', 'source-doc-4c784a84a66adf221597', 'source-node-002439', '5', '2439', 'text', '灌药药剂：20% 噻菌铜悬浮剂 500 倍液、72% 农用硫酸链霉素可溶性粉剂 3000 倍液（二选一）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002441', 'source-doc-4c784a84a66adf221597', 'source-node-002439', '5', '2440', 'text', '操作方式：同真菌性灌药，若芯部有孔洞，可在灌注后用无菌棉花轻轻堵塞洞口，延长药剂停留时间。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002442', 'source-doc-4c784a84a66adf221597', 'source-node-002439', '5', '2441', 'text', '用量：每株每次 150-400ml，视烂芯范围灵活调整。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002443', 'source-doc-4c784a84a66adf221597', 'source-node-002430', '3', '2442', 'text', '虫害型烂芯（钻心虫、象鼻虫幼虫等）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002444', 'source-doc-4c784a84a66adf221597', 'source-node-002443', '4', '2443', 'text', '防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002445', 'source-doc-4c784a84a66adf221597', 'source-node-002444', '5', '2444', 'text', '灌药药剂：40% 氧化乐果乳油 500 倍液、2.5% 溴氰菊酯乳油 1000 倍液（二选一）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002446', 'source-doc-4c784a84a66adf221597', 'source-node-002444', '5', '2445', 'text', '操作方式：找到蛀孔后，将注射器针头插入蛀孔内部，缓慢注入药剂，直至药剂从孔洞边缘溢出，随后用黏土或棉花封堵蛀孔，防止幼虫逃逸和药剂挥发。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002447', 'source-doc-4c784a84a66adf221597', 'source-node-002444', '5', '2446', 'text', '用量：每个蛀孔灌注 10-20ml，若有多个蛀孔，逐一灌注，确保覆盖所有虫体活动区域。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002448', 'source-doc-4c784a84a66adf221597', 'source-node-002430', '3', '2447', 'text', '后续维护：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002449', 'source-doc-4c784a84a66adf221597', 'source-node-002448', '4', '2448', 'text', '病害型烂芯后续用药', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002450', 'source-doc-4c784a84a66adf221597', 'source-node-002449', '5', '2449', 'text', '药剂交替喷施（防抗药性）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002451', 'source-doc-4c784a84a66adf221597', 'source-node-002450', '6', '2450', 'text', '第 1 次巩固：灌药后 7 天，全株喷施对应类型杀菌剂（与灌药剂交替使用，如灌了多菌灵，喷施甲基托布津），重点喷洒心叶、茎干伤口及周围枝叶，浓度同灌药稀释比例。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002452', 'source-doc-4c784a84a66adf221597', 'source-node-002450', '6', '2451', 'text', '第 2 次巩固：第 1 次喷施后 10 天，再次喷施，若心叶恢复良好，可改为保护性杀菌剂（如波尔多液，按 1:1:200 比例稀释），增强植株表面防护。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002453', 'source-doc-4c784a84a66adf221597', 'source-node-002450', '6', '2452', 'text', '长期预防：雨季来临前，每 15 天喷施 1 次保护性杀菌剂，连续 2-3 次，减少病菌侵染风险。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002454', 'source-doc-4c784a84a66adf221597', 'source-node-002449', '5', '2453', 'text', '伤口辅助防护', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002455', 'source-doc-4c784a84a66adf221597', 'source-node-002454', '6', '2454', 'text', '灌药后待药剂晾干，及时用凡士林或专用树木伤口愈合剂涂抹芯部伤口，后续每次喷施药剂后，若伤口未愈合，需补涂 1 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002456', 'source-doc-4c784a84a66adf221597', 'source-node-002448', '4', '2455', 'text', '（二）虫害型烂芯后续用药', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002457', 'source-doc-4c784a84a66adf221597', 'source-node-002456', '5', '2456', 'text', '叶面杀虫喷雾', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002458', 'source-doc-4c784a84a66adf221597', 'source-node-002457', '6', '2457', 'text', '第 1 次补杀：灌药封堵后 7 天，全株喷施对应杀虫剂（与灌药剂交替，如灌了氧化乐果，喷施溴氰菊酯），重点喷洒心叶、茎干及下部枝叶，杀灭残留虫卵和成虫。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002459', 'source-doc-4c784a84a66adf221597', 'source-node-002457', '6', '2458', 'text', '第 2 次补杀：第 1 次喷雾后 7 天，再次喷施 1 次，确保虫害彻底清除。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002460', 'source-doc-4c784a84a66adf221597', 'source-node-002457', '6', '2459', 'text', '长期预防：每月巡查 1 次，发现虫害迹象及时喷施杀虫剂，雨季前可增喷 1 次，强化防护。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002461', 'source-doc-4c784a84a66adf221597', 'source-node-002429', '2', '2460', 'text', '槟榔细菌性条班病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002462', 'source-doc-4c784a84a66adf221597', 'source-node-002461', '3', '2461', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002463', 'source-doc-4c784a84a66adf221597', 'source-node-002462', '4', '2462', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002464', 'source-doc-4c784a84a66adf221597', 'source-node-002461', '3', '2463', 'text', '鉴别：叶片病斑初为暗绿色至黑色椭圆形小斑点，或形成1-4毫米宽的短条斑，病斑穿透叶片两面；后期病斑宽度可扩大至1厘米以上，长度不一，有的病斑可延伸至整个叶片的长度，一张叶片上可出现多条病斑，后期合成不规则大病块。潮湿条件下，病斑变褐色破裂干枯。西军性调班病也可危害叶柄，病斑呈褐色、灰黄色，形状长条形或不规则形，病斑深度可达2-5毫米。槟榔危害叶鞘时，病斑呈褐色、灰黄色，凸起，单个病斑近圆形，后期可合成不规则大病块，病斑可连续穿透三片叶鞘。病情严重时，叶片枯死。病菌的来源：带病种苗、田间病株残体。病菌主要靠雨水传播和水流传播，尤其是台风雨，能使病菌远距离传播，是此病流行的主导因素。昆虫咬食、人工田间劳动操作留下的伤口，也能传染病菌。细菌性调班病周年可发生，但以下半年高温多雨、又是台风发生季节时，病害发展较快。发病的高峰期通常出现在10-12月份，1-2月份因温度干燥而减弱', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002465', 'source-doc-4c784a84a66adf221597', 'source-node-002461', '3', '2464', 'text', '防治：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002466', 'source-doc-4c784a84a66adf221597', 'source-node-002465', '4', '2465', 'text', '1. 种苗必须严格检查，选用健康壮苗，淘汰病苗，以防病害传入新区；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002467', 'source-doc-4c784a84a66adf221597', 'source-node-002465', '4', '2466', 'text', '2. 建立完整的防护林网，防止台风雨的迅速传播；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002468', 'source-doc-4c784a84a66adf221597', 'source-node-002465', '4', '2467', 'text', '3. 加强田间管理，合理施肥，防止田间积水，及时排除积水，清除病叶、病株残体；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002469', 'source-doc-4c784a84a66adf221597', 'source-node-002465', '4', '2468', 'text', '4. 化学防治：发病前期可选用以下药剂：噻唑锌、春雷霉素、噻菌铜、噻森铜等七天一次，连打三次；单用氢氧化铜也可以；发病中后期可复配使用，比如噻唑锌加噻菌铜、噻唑锌加春雷霉素等', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002470', 'source-doc-4c784a84a66adf221597', 'source-node-002429', '2', '2469', 'text', '下方槟榔病害统一用唑醚·戊唑醇（斑点类真菌）+春蕾·喹啉铜（细菌），可以再配合一个咪鲜胺', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002471', 'source-doc-4c784a84a66adf221597', 'source-node-002429', '2', '2470', 'text', '槟榔炭疽病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002472', 'source-doc-4c784a84a66adf221597', 'source-node-002471', '3', '2471', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002473', 'source-doc-4c784a84a66adf221597', 'source-node-002472', '4', '2472', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002474', 'source-doc-4c784a84a66adf221597', 'source-node-002471', '3', '2473', 'text', '鉴别：病菌可为害叶片、花絮和果实。感病叶片初期呈现暗绿色水渍状小病斑，随后变褐色。感病中后期病斑逐渐扩大，干枯有云纹状。病斑多时可像麻点斑遍及整张叶片，后期叶片逐渐干枯开裂，造成树体衰弱，影响光合作用，甚至导致植株死亡。炭疽病还可危害花絮，开始时花枝变黄，然后变成褐色，丝花脱落，最后花脆枯死。槟榔炭疽病也可以感病果实，绿果感病后出现圆形或椭圆形病斑，约凹陷，失去商品价值。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002475', 'source-doc-4c784a84a66adf221597', 'source-node-002471', '3', '2474', 'text', '防治，除了上面的方案，还有可选用咪鲜胺、嘧菌酯、苯甲嘧菌酯等等', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002476', 'source-doc-4c784a84a66adf221597', 'source-node-002429', '2', '2475', 'text', '槟榔褐斑病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002477', 'source-doc-4c784a84a66adf221597', 'source-node-002476', '3', '2476', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002478', 'source-doc-4c784a84a66adf221597', 'source-node-002477', '4', '2477', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002479', 'source-doc-4c784a84a66adf221597', 'source-node-002476', '3', '2478', 'text', '鉴别症状：后期有黄晕，一般先从下部叶片开始发病。发病初期叶片上先出现圆形黑褐色小点病斑，逐渐扩大，病斑中央灰白色或灰褐色。发病严重时幼苗长时衰弱，叶片发黄，主要在下半年发生，危害气温低、湿度高发生严重', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002480', 'source-doc-4c784a84a66adf221597', 'source-node-002429', '2', '2479', 'text', '槟榔大茎点霉叶斑病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002481', 'source-doc-4c784a84a66adf221597', 'source-node-002480', '3', '2480', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002482', 'source-doc-4c784a84a66adf221597', 'source-node-002481', '4', '2481', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002483', 'source-doc-4c784a84a66adf221597', 'source-node-002480', '3', '2482', 'text', '鉴别症状：黑斑不规则花瓣状，发病初期叶片先出现褪绿色小黄点病斑，扩大后外围有明显的黄圈，这是鉴别此病的主要特征', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002484', 'source-doc-4c784a84a66adf221597', 'source-node-002429', '2', '2483', 'text', '槟榔色二孢叶斑病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002485', 'source-doc-4c784a84a66adf221597', 'source-node-002484', '3', '2484', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002486', 'source-doc-4c784a84a66adf221597', 'source-node-002484', '3', '2485', 'text', '兼备：主要危害佛焰苞外围和内侧，病斑中央有明显小黑点，', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002487', 'source-doc-4c784a84a66adf221597', 'source-node-000545', '1', '2486', 'text', '2.1.10 椰子', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002488', 'source-doc-4c784a84a66adf221597', 'source-node-000545', '1', '2487', 'text', '2.1.11 冬枣', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002489', 'source-doc-4c784a84a66adf221597', 'source-node-000545', '1', '2488', 'text', '2.1.12 蓝莓', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002490', 'source-doc-4c784a84a66adf221597', 'source-node-002489', '2', '2489', 'text', '蓝莓灰霉病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002491', 'source-doc-4c784a84a66adf221597', 'source-node-002490', '3', '2490', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002492', 'source-doc-4c784a84a66adf221597', 'source-node-002491', '4', '2491', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002493', 'source-doc-4c784a84a66adf221597', 'source-node-002490', '3', '2492', 'text', '一、症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002494', 'source-doc-4c784a84a66adf221597', 'source-node-002493', '4', '2493', 'text', '为害果实、叶片及果柄，初期多从叶尖形成V斑，逐渐向叶内扩展，形成灰褐色病斑。后期病斑生霉层，花和果实发育期最容易感染。被感染的果实水渍状，软化腐烂。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002495', 'source-doc-4c784a84a66adf221597', 'source-node-002490', '3', '2494', 'text', '二、病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002496', 'source-doc-4c784a84a66adf221597', 'source-node-002495', '4', '2495', 'text', '灰葡萄孢，半知菌亚门', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002497', 'source-doc-4c784a84a66adf221597', 'source-node-002490', '3', '2496', 'text', '三、发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002498', 'source-doc-4c784a84a66adf221597', 'source-node-002497', '4', '2497', 'text', '莓灰霉病喜低温潮湿，多发生于阴冷多雨的天气和管理不当的温室中。一般低温高湿的环境下灰霉病容易大面积流行。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002499', 'source-doc-4c784a84a66adf221597', 'source-node-002490', '3', '2498', 'text', '四、防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002500', 'source-doc-4c784a84a66adf221597', 'source-node-002499', '4', '2499', 'text', '农业防治核心要点：清园彻底；生长季及时摘除病叶、病果并喷药。控制温湿度，阴雨天不浇水，温室加强通风排湿，湿度控制在 65%以下。加强树体管理，通过抹芽、摘心增加通风透光，及时清除或震落残花。合理施肥，不偏施氮肥，避免树势徒长，增强植株抗病力。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002501', 'source-doc-4c784a84a66adf221597', 'source-node-002499', '4', '2500', 'text', '药剂防治核心要点：花期开始喷药，可选 40%嘧霉胺可湿性粉剂 750～1000倍液，或50%腐霉利可湿性粉剂 1200～1500倍液。果期禁止喷药，防止农药残留。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002502', 'source-doc-4c784a84a66adf221597', 'source-node-002489', '2', '2501', 'text', '蓝莓锈病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002503', 'source-doc-4c784a84a66adf221597', 'source-node-002502', '3', '2502', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002504', 'source-doc-4c784a84a66adf221597', 'source-node-002503', '4', '2503', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002505', 'source-doc-4c784a84a66adf221597', 'source-node-002502', '3', '2504', 'text', '一、症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002506', 'source-doc-4c784a84a66adf221597', 'source-node-002505', '4', '2505', 'text', '受害叶片出现棕红色锈斑，背面形成红褐色夏孢子堆；病叶变黄、落叶早，导致树木生长势下降，影响花芽形成数量，降低产量。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002507', 'source-doc-4c784a84a66adf221597', 'source-node-002502', '3', '2506', 'text', '二、病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002508', 'source-doc-4c784a84a66adf221597', 'source-node-002507', '4', '2507', 'text', '病原为Pucciniastrum uaccinii，膨痂锈菌属，具有全循环型转主寄生生活史，转主寄主为冷杉属、铁杉属、云杉属等针叶树，锈孢子阶段寄生在转主寄主上，夏孢子和冬孢子寄生在蓝莓上', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002509', 'source-doc-4c784a84a66adf221597', 'source-node-002502', '3', '2508', 'text', '三、发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002510', 'source-doc-4c784a84a66adf221597', 'source-node-002509', '4', '2509', 'text', '病菌具有转主寄生特性，需在转主寄主针叶树木上越冬才能完成生活史；若蓝莓种植园周围半径 5km 范围内无转主寄主，一般不会发生；蓝莓旺盛生长期遇长时间阴雨天气，发病较重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002511', 'source-doc-4c784a84a66adf221597', 'source-node-002502', '3', '2510', 'text', '四、防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002512', 'source-doc-4c784a84a66adf221597', 'source-node-002511', '4', '2511', 'text', '农业防治：清除蓝莓种植园周围半径 5km内的冷杉属、铁杉属、云杉属等转主寄主针叶树；新建蓝莓园时需排查附近转主寄主，若数量多且无法清除，不宜作为蓝莓园。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002513', 'source-doc-4c784a84a66adf221597', 'source-node-002511', '4', '2512', 'text', '药剂防治：转主寄主无法清除时，4月上中旬（蓝莓树发芽前）向转主寄主喷施石硫合剂、波尔多液等；蓝莓叶片发病时，喷施20%三唑酮乳油 600 倍液，花期禁止喷药。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002514', 'source-doc-4c784a84a66adf221597', 'source-node-002489', '2', '2513', 'text', '蓝莓炭疽病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002515', 'source-doc-4c784a84a66adf221597', 'source-node-002514', '3', '2514', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002516', 'source-doc-4c784a84a66adf221597', 'source-node-002515', '4', '2515', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002517', 'source-doc-4c784a84a66adf221597', 'source-node-002514', '3', '2516', 'text', '一、症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002518', 'source-doc-4c784a84a66adf221597', 'source-node-002517', '4', '2517', 'text', '花期至果期发病，枝叶生棕褐/ 红褐色病斑，果实成熟后软化皱缩，凹陷处现橙黄色孢子堆', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002519', 'source-doc-4c784a84a66adf221597', 'source-node-002514', '3', '2518', 'text', '二、病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002520', 'source-doc-4c784a84a66adf221597', 'source-node-002519', '4', '2519', 'text', '尖孢炭疽菌（Colletotrichum acutatum）和胶孢炭疽菌（C.gloeosporioides）引起', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002521', 'source-doc-4c784a84a66adf221597', 'source-node-002514', '3', '2520', 'text', '三、发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002522', 'source-doc-4c784a84a66adf221597', 'source-node-002521', '4', '2521', 'text', '病原菌在受害枝条、病组织上越冬，次年春季和初夏产生分生孢子，遇雨水随风雨传播，侵染花器或幼嫩组织；25℃为分生孢子最适侵染温度，高温潮湿环境利于病害发生。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002523', 'source-doc-4c784a84a66adf221597', 'source-node-002514', '3', '2522', 'text', '四、防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002524', 'source-doc-4c784a84a66adf221597', 'source-node-002523', '4', '2523', 'text', '农业防治：修剪清除感病枝条、叶片及果实，清除田间杂草；采用滴灌减少分生孢子传播；加强田间通风透湿，适当修剪防止植株郁闭；及时采收果实，采收后放置冷凉处，条件允许采后2小时内预冷。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002525', 'source-doc-4c784a84a66adf221597', 'source-node-002523', '4', '2524', 'text', '药剂防治：秋季落叶后或春季花芽萌动前喷施石硫合剂；花期至果实未成熟前，每隔10～15天喷施一次75%百菌清可湿性粉剂600倍液或50%多菌灵可湿性粉剂800倍液，连续喷施2～3次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002526', 'source-doc-4c784a84a66adf221597', 'source-node-002489', '2', '2525', 'text', '蓝莓僵果病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002527', 'source-doc-4c784a84a66adf221597', 'source-node-002526', '3', '2526', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002528', 'source-doc-4c784a84a66adf221597', 'source-node-002527', '4', '2527', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002529', 'source-doc-4c784a84a66adf221597', 'source-node-002526', '3', '2528', 'text', '一、症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002530', 'source-doc-4c784a84a66adf221597', 'source-node-002529', '4', '2529', 'text', '主要为害幼嫩枝条和果实，枝条枯萎，果实干瘪皱缩成僵果。侵染初期新叶、新梢、花序萎蔫变褐，潮湿时叶基、花梗现孢子堆；果实初期内部有白色菌丝，成熟后萎蔫失水、色粉红至淡褐，质地先软后硬，采收前大量掉落。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002531', 'source-doc-4c784a84a66adf221597', 'source-node-002526', '3', '2530', 'text', '二、病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002532', 'source-doc-4c784a84a66adf221597', 'source-node-002531', '4', '2531', 'text', '链核盘菌属真菌Monilinia vacciniicorymbosi', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002533', 'source-doc-4c784a84a66adf221597', 'source-node-002526', '3', '2532', 'text', '三、发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002534', 'source-doc-4c784a84a66adf221597', 'source-node-002533', '4', '2533', 'text', '病菌以僵果或假菌核越冬，早春10℃左右假菌核萌发形成子囊盘，子囊孢子随风进行初级侵染（为害新梢），后产生分生孢子经风、雨、昆虫进行次级侵染（为害花果）。早春多雨高湿、冬季低温时间长的地区发病重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002535', 'source-doc-4c784a84a66adf221597', 'source-node-002526', '3', '2534', 'text', '四、防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002536', 'source-doc-4c784a84a66adf221597', 'source-node-002535', '4', '2535', 'text', '农业防治：秋季清除并烧毁/ 掩埋病残体、落果；早春行间耕作、土壤粗筛或喷施0.5%尿素破坏子实体。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002537', 'source-doc-4c784a84a66adf221597', 'source-node-002535', '4', '2536', 'text', '药剂防治：开花前喷施 70%代森锰锌500倍液、50%多菌灵 800倍液或70%甲基硫菌灵1000倍液。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002538', 'source-doc-4c784a84a66adf221597', 'source-node-002489', '2', '2537', 'text', '蓝莓拟茎点枝枯病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002539', 'source-doc-4c784a84a66adf221597', 'source-node-002538', '3', '2538', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002540', 'source-doc-4c784a84a66adf221597', 'source-node-002539', '4', '2539', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002541', 'source-doc-4c784a84a66adf221597', 'source-node-002538', '3', '2540', 'text', '一、症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002542', 'source-doc-4c784a84a66adf221597', 'source-node-002541', '4', '2541', 'text', '主要为害嫩枝、芽，严重时整株死亡：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002543', 'source-doc-4c784a84a66adf221597', 'source-node-002541', '4', '2542', 'text', '嫩枝：形成褐色病斑并扩展，导致嫩枝枯死，后期嫩枝褪色变白；病斑处产生大量分生孢子器，潮湿时溢出分生孢子角；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002544', 'source-doc-4c784a84a66adf221597', 'source-node-002541', '4', '2543', 'text', '芽：受侵染后变褐坏死；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002545', 'source-doc-4c784a84a66adf221597', 'source-node-002541', '4', '2544', 'text', '内部组织：剖开受害组织，皮层稍变黄，维管束、木质部和髓部组成的中柱部分变为褐色，且褐色从外向内逐渐变淡', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002546', 'source-doc-4c784a84a66adf221597', 'source-node-002538', '3', '2545', 'text', '二、病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002547', 'source-doc-4c784a84a66adf221597', 'source-node-002546', '4', '2546', 'text', '病原菌为乌饭树拟茎点霉（Phomopsis vaccinii），是越橘间座壳（Diaporthe vaccinii）的无性阶段，属子囊菌门间座壳科；分生孢子器产生两种孢子：甲型无色单胞卵圆形（有油球可萌发），乙型无色单胞线形（钩状无油球不可萌发', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002548', 'source-doc-4c784a84a66adf221597', 'source-node-002538', '3', '2547', 'text', '三、发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002549', 'source-doc-4c784a84a66adf221597', 'source-node-002548', '4', '2548', 'text', '传播途径：主要通过雨水传播，由花芽侵入植株；枝条有伤口时，可与导致蓝莓枝干溃疡的葡萄座腔菌复合侵染；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002550', 'source-doc-4c784a84a66adf221597', 'source-node-002548', '4', '2549', 'text', '侵染周期：周期长，连续侵染下蓝莓可整株死亡；还可能侵染果实和叶片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002551', 'source-doc-4c784a84a66adf221597', 'source-node-002538', '3', '2550', 'text', '四、防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002552', 'source-doc-4c784a84a66adf221597', 'source-node-002551', '4', '2551', 'text', '农业防治：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002553', 'source-doc-4c784a84a66adf221597', 'source-node-002552', '5', '2552', 'text', '冬季彻底清除病枝落叶，减少越冬菌源；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002554', 'source-doc-4c784a84a66adf221597', 'source-node-002552', '5', '2553', 'text', '花芽开放前清除病枝，喷洒波尔多液预防；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002555', 'source-doc-4c784a84a66adf221597', 'source-node-002552', '5', '2554', 'text', '生长季及时清除病残体，防治刺吸式口器害虫；喷施钙肥2-3次，合理灌溉施肥；冬季防寒减少冻伤；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002556', 'source-doc-4c784a84a66adf221597', 'source-node-002551', '4', '2555', 'text', '药剂防治：喷施25%吡唑醚菌酯乳油1800倍液或24%腈苯唑悬浮剂1500倍液', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002557', 'source-doc-4c784a84a66adf221597', 'source-node-002489', '2', '2556', 'text', '蓝莓根癌病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002558', 'source-doc-4c784a84a66adf221597', 'source-node-002557', '3', '2557', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002559', 'source-doc-4c784a84a66adf221597', 'source-node-002558', '4', '2558', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002560', 'source-doc-4c784a84a66adf221597', 'source-node-002557', '3', '2559', 'text', '一、症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002561', 'source-doc-4c784a84a66adf221597', 'source-node-002560', '4', '2560', 'text', '早期根部出现白色 / 肉色瘤状隆起，后增大变褐至黑色，根系枯死；植株生长缓慢，叶黄干枯，最终全株死亡', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002562', 'source-doc-4c784a84a66adf221597', 'source-node-002557', '3', '2561', 'text', '二、病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002563', 'source-doc-4c784a84a66adf221597', 'source-node-002562', '4', '2562', 'text', '根癌土壤杆菌（Agrobacterium tumefaciens），革兰氏阴性杆状菌，无芽孢，具鞭毛，菌落白色至奶油色', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002564', 'source-doc-4c784a84a66adf221597', 'source-node-002557', '3', '2563', 'text', '三、发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002565', 'source-doc-4c784a84a66adf221597', 'source-node-002564', '4', '2564', 'text', '5 月下旬发病重，生长旺季植株抗性增强；病菌通过伤口侵入，土壤中逐年累加，发病趋势逐年加重', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002566', 'source-doc-4c784a84a66adf221597', 'source-node-002557', '3', '2565', 'text', '四、防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002567', 'source-doc-4c784a84a66adf221597', 'source-node-002566', '4', '2566', 'text', '农业防治：选健苗，避免伤根，及时防地下害虫；挖除病株，土壤用 1%波尔多液或链霉素消毒', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002568', 'source-doc-4c784a84a66adf221597', 'source-node-002566', '4', '2567', 'text', '化学防治：0.2% 硫酸铜或 0.2%-0.5% 链霉素灌根（每10-15天1次，连2-3次）；K84菌悬液浸苗或浇根', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002569', 'source-doc-4c784a84a66adf221597', 'source-node-002489', '2', '2568', 'text', '蓝莓病毒病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002570', 'source-doc-4c784a84a66adf221597', 'source-node-002569', '3', '2569', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002571', 'source-doc-4c784a84a66adf221597', 'source-node-002489', '2', '2570', 'text', '蓝莓溃疡病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002572', 'source-doc-4c784a84a66adf221597', 'source-node-002571', '3', '2571', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002573', 'source-doc-4c784a84a66adf221597', 'source-node-002489', '2', '2572', 'text', '红色轮状斑点病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002574', 'source-doc-4c784a84a66adf221597', 'source-node-002573', '3', '2573', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002575', 'source-doc-4c784a84a66adf221597', 'source-node-002489', '2', '2574', 'text', '蓝莓其他病害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002576', 'source-doc-4c784a84a66adf221597', 'source-node-002575', '3', '2575', 'text', '缺钙', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002577', 'source-doc-4c784a84a66adf221597', 'source-node-002576', '4', '2576', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002578', 'source-doc-4c784a84a66adf221597', 'source-node-002575', '3', '2577', 'text', '其他', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002579', 'source-doc-4c784a84a66adf221597', 'source-node-002578', '4', '2578', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002580', 'source-doc-4c784a84a66adf221597', 'source-node-000545', '1', '2579', 'text', '2.1.13 番石榴', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002581', 'source-doc-4c784a84a66adf221597', 'source-node-002580', '2', '2580', 'text', '番石榴炭疽病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002582', 'source-doc-4c784a84a66adf221597', 'source-node-002581', '3', '2581', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002583', 'source-doc-4c784a84a66adf221597', 'source-node-002582', '4', '2582', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002584', 'source-doc-4c784a84a66adf221597', 'source-node-002581', '3', '2583', 'text', '一、症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002585', 'source-doc-4c784a84a66adf221597', 'source-node-002584', '4', '2584', 'text', '果实：幼果干枯脱落或干果挂树；成熟果实表面出现圆形 / 近圆形凹陷斑（褐至暗褐），上生粉红至橘红色小点；或外表软化水渍状雀斑（成熟果特有），病斑中央黑、稍凹陷，有粉色黏液（分生孢子堆），内部中央呈粉色淡紫色，外部褪色水渍状。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002586', 'source-doc-4c784a84a66adf221597', 'source-node-002584', '4', '2585', 'text', '枝叶：新梢嫩叶叶尖、叶缘焦枯脱落，严重枝梢变褐枯死，病部生黑色小点（分生孢子器）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002587', 'source-doc-4c784a84a66adf221597', 'source-node-002581', '3', '2586', 'text', '二、病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002588', 'source-doc-4c784a84a66adf221597', 'source-node-002587', '4', '2587', 'text', '有性阶段为Glomerella cingulata（围小丛壳），无性阶段为Colletotrichum gloeosporioides（盘长孢状刺盘孢）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002589', 'source-doc-4c784a84a66adf221597', 'source-node-002581', '3', '2588', 'text', '三、发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002590', 'source-doc-4c784a84a66adf221597', 'source-node-002589', '4', '2589', 'text', '分生孢子随雨水传播再侵染；成熟果易发病；采摘后病斑可继续扩展', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002591', 'source-doc-4c784a84a66adf221597', 'source-node-002581', '3', '2590', 'text', '四、防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002592', 'source-doc-4c784a84a66adf221597', 'source-node-002591', '4', '2591', 'text', '农业防治：剪除病枝、病果并烧毁，增施钾肥增强树势；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002593', 'source-doc-4c784a84a66adf221597', 'source-node-002591', '4', '2592', 'text', '化学防治：发病初期用70%甲基托布津500～1000倍液、或代森锰锌70%可湿性粉剂400～600倍液、或50%多菌灵500倍液、或用炭持灵600倍液、或80%炭疽福美800倍液、或75%百菌清500～800倍液或25%丙环唑2500 倍液等；发病初期/雨后喷施50%咪鲜胺、50%退菌特等药剂；果实套袋前需消毒处理', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002594', 'source-doc-4c784a84a66adf221597', 'source-node-002580', '2', '2593', 'text', '番石榴褐斑病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002595', 'source-doc-4c784a84a66adf221597', 'source-node-002594', '3', '2594', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002596', 'source-doc-4c784a84a66adf221597', 'source-node-002595', '4', '2595', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002597', 'source-doc-4c784a84a66adf221597', 'source-node-002594', '3', '2596', 'text', '一、症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002598', 'source-doc-4c784a84a66adf221597', 'source-node-002597', '4', '2597', 'text', '叶片受害：先出现暗褐色至红褐色、无边缘或边缘不明显的病斑，多发生在叶缘；病斑背面生灰色霉状物（子实体）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002599', 'source-doc-4c784a84a66adf221597', 'source-node-002597', '4', '2598', 'text', '果实受害：果面呈暗褐色，边缘红褐色，中央凹陷，并生黑色小点；潮湿时长出灰色霉状物', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002600', 'source-doc-4c784a84a66adf221597', 'source-node-002594', '3', '2599', 'text', '二、病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002601', 'source-doc-4c784a84a66adf221597', 'source-node-002600', '4', '2600', 'text', '拟盘多毛孢（Pestalotiopis disseminatum (Thuem.)Stey.），属半知菌亚门拟盘多毛孢属真菌', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002602', 'source-doc-4c784a84a66adf221597', 'source-node-002594', '3', '2601', 'text', '三、发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002603', 'source-doc-4c784a84a66adf221597', 'source-node-002602', '4', '2602', 'text', '病菌以分生孢子盘或菌丝体在病部组织中或随病残体入土越冬；翌春温湿度适宜时，分生孢子借风雨传播，从伤口侵入引发初侵染，逐步蔓延；气温25~28℃、相对湿度80%~85%或遇雨易发病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002604', 'source-doc-4c784a84a66adf221597', 'source-node-002594', '3', '2603', 'text', '四、防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002605', 'source-doc-4c784a84a66adf221597', 'source-node-002604', '4', '2604', 'text', '农业措施：增施有机肥增强树势；雨季及时排水；冬季清除枯枝落叶和烂果并烧毁，减少菌源。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002606', 'source-doc-4c784a84a66adf221597', 'source-node-002604', '4', '2605', 'text', '药剂防治：发病初期喷施77%可杀得可湿性粉剂600倍液、50%多菌灵可湿性粉剂1000倍液或50%甲基硫菌灵可湿性粉剂1500倍液等。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002607', 'source-doc-4c784a84a66adf221597', 'source-node-002580', '2', '2606', 'text', '番石榴溃疡病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002608', 'source-doc-4c784a84a66adf221597', 'source-node-002607', '3', '2607', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002609', 'source-doc-4c784a84a66adf221597', 'source-node-002608', '4', '2608', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002610', 'source-doc-4c784a84a66adf221597', 'source-node-002607', '3', '2609', 'text', '一、症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002611', 'source-doc-4c784a84a66adf221597', 'source-node-002610', '4', '2610', 'text', '叶片：初期出现水渍状小斑点，逐渐扩大为近圆形或不规则形的溃疡斑，病斑边缘隆起、中央凹陷，后期易破裂，表面常有淡黄色菌脓溢出。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002612', 'source-doc-4c784a84a66adf221597', 'source-node-002610', '4', '2611', 'text', '果实：病斑呈凹陷的溃疡状，初期为水渍状，后变为褐色至黑褐色，严重时果实畸形、腐烂。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002613', 'source-doc-4c784a84a66adf221597', 'source-node-002610', '4', '2612', 'text', '枝条：形成稍隆起的溃疡斑，伴有流胶，病斑环绕枝条时可导致枝条枯死。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002614', 'source-doc-4c784a84a66adf221597', 'source-node-002607', '3', '2613', 'text', '二、病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002615', 'source-doc-4c784a84a66adf221597', 'source-node-002614', '4', '2614', 'text', '由细菌（如黄单胞菌属）引起的细菌性病害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002616', 'source-doc-4c784a84a66adf221597', 'source-node-002607', '3', '2615', 'text', '三、发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002617', 'source-doc-4c784a84a66adf221597', 'source-node-002616', '4', '2616', 'text', '高温高湿（温度 25~30℃、湿度80%以上）利于发病，雨季、雾天、露水重时传播迅速。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002618', 'source-doc-4c784a84a66adf221597', 'source-node-002616', '4', '2617', 'text', '病原菌通过风雨、昆虫传播，从伤口（如虫害伤口、农事操作伤口）或自然孔口（气孔、皮孔）侵入。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002619', 'source-doc-4c784a84a66adf221597', 'source-node-002616', '4', '2618', 'text', '果园通风透光差、树势衰弱时发病较重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002620', 'source-doc-4c784a84a66adf221597', 'source-node-002607', '3', '2619', 'text', '四、防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002621', 'source-doc-4c784a84a66adf221597', 'source-node-002620', '4', '2620', 'text', '1. 农业防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002622', 'source-doc-4c784a84a66adf221597', 'source-node-002621', '5', '2621', 'text', '及时清除病叶、病果、病枝，集中烧毁，减少病原菌积累。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002623', 'source-doc-4c784a84a66adf221597', 'source-node-002621', '5', '2622', 'text', '合理修剪，改善果园通风透光条件；增施有机肥，增强树势，提高植株抗病能力。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002624', 'source-doc-4c784a84a66adf221597', 'source-node-002621', '5', '2623', 'text', '避免在雨天或露水未干时进行修剪、采摘等农事操作，减少伤口感染风险。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002625', 'source-doc-4c784a84a66adf221597', 'source-node-002620', '4', '2624', 'text', '2. 化学防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002626', 'source-doc-4c784a84a66adf221597', 'source-node-002625', '5', '2625', 'text', '发病初期，可喷施3% 中生菌素可湿性粉剂800 倍液、20% 噻菌铜悬浮剂500 倍液或77% 氢氧化铜可湿性粉剂600 倍液，每隔7~10天喷1次，连续防治2~3次。若病害严重，可轮换使用春雷・王铜可湿性粉剂（春雷霉素+王铜），增强杀菌效果并延缓抗药性。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002627', 'source-doc-4c784a84a66adf221597', 'source-node-002580', '2', '2626', 'text', '番石榴藻斑病（荔枝、龙眼通用）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002628', 'source-doc-4c784a84a66adf221597', 'source-node-002627', '3', '2627', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002629', 'source-doc-4c784a84a66adf221597', 'source-node-002628', '4', '2628', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002630', 'source-doc-4c784a84a66adf221597', 'source-node-002627', '3', '2629', 'text', '一、症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002631', 'source-doc-4c784a84a66adf221597', 'source-node-002630', '4', '2630', 'text', '叶片上出现黄褐色或暗绿色的圆形、椭圆形斑点，后期斑点表面会形成毛毡状的藻类丝状体，颜色逐渐变为暗褐色或黑色。严重时斑点连片，阻碍叶片光合作用，导致叶片变黄、脱落。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002632', 'source-doc-4c784a84a66adf221597', 'source-node-002627', '3', '2631', 'text', '二、病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002633', 'source-doc-4c784a84a66adf221597', 'source-node-002632', '4', '2632', 'text', '主要由绿色头孢藻等藻类引起；或参考假尾孢菌（Pseudocercospora psidi）（具体病原可参考荔枝、龙眼藻斑病）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002634', 'source-doc-4c784a84a66adf221597', 'source-node-002627', '3', '2633', 'text', '三、发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002635', 'source-doc-4c784a84a66adf221597', 'source-node-002634', '4', '2634', 'text', '高湿度（多雾、多露、阴雨天气）、果园通风透光性差的环境易诱发。藻类以雨水、露水为媒介传播，附着于叶片表面后侵染。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002636', 'source-doc-4c784a84a66adf221597', 'source-node-002627', '3', '2635', 'text', '四、防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002637', 'source-doc-4c784a84a66adf221597', 'source-node-002636', '4', '2636', 'text', '化学防治：合理修剪枝条，改善果园通风透光条件；及时清除病叶并集中销毁，减少侵染源；避免果园过度荫蔽，合理控制种植密度。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002638', 'source-doc-4c784a84a66adf221597', 'source-node-002636', '4', '2637', 'text', '药剂防治：使用含铜药剂（如波尔多液、氢氧化铜），或喷施10%世高水分散粒剂 1500 倍液、25% 咪鲜胺乳油 2000倍液等。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002639', 'source-doc-4c784a84a66adf221597', 'source-node-002580', '2', '2638', 'text', '番石榴干枯病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002640', 'source-doc-4c784a84a66adf221597', 'source-node-002639', '3', '2639', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002641', 'source-doc-4c784a84a66adf221597', 'source-node-002580', '2', '2640', 'text', '番石榴灰斑病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002642', 'source-doc-4c784a84a66adf221597', 'source-node-002641', '3', '2641', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002643', 'source-doc-4c784a84a66adf221597', 'source-node-002580', '2', '2642', 'text', '番石榴盲蝽', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002644', 'source-doc-4c784a84a66adf221597', 'source-node-002643', '3', '2643', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002645', 'source-doc-4c784a84a66adf221597', 'source-node-002580', '2', '2644', 'text', '番石榴蓟马为害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002646', 'source-doc-4c784a84a66adf221597', 'source-node-002645', '3', '2645', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002647', 'source-doc-4c784a84a66adf221597', 'source-node-000545', '1', '2646', 'text', '2.1.14 桑树', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002648', 'source-doc-4c784a84a66adf221597', 'source-node-000545', '1', '2647', 'text', '2.1.15 李树/杏树', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002649', 'source-doc-4c784a84a66adf221597', 'source-node-000545', '1', '2648', 'text', '2.1.16 苹果', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002650', 'source-doc-4c784a84a66adf221597', 'source-node-002649', '2', '2649', 'text', '轮纹病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002651', 'source-doc-4c784a84a66adf221597', 'source-node-002650', '3', '2650', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002652', 'source-doc-4c784a84a66adf221597', 'source-node-002651', '4', '2651', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002653', 'source-doc-4c784a84a66adf221597', 'source-node-002650', '3', '2652', 'text', '预防措施', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002654', 'source-doc-4c784a84a66adf221597', 'source-node-002653', '4', '2653', 'text', '套袋前后使用代森锰锌+苯醚甲环唑', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002655', 'source-doc-4c784a84a66adf221597', 'source-node-002649', '2', '2654', 'text', '炭疽叶枯病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002656', 'source-doc-4c784a84a66adf221597', 'source-node-002655', '3', '2655', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002657', 'source-doc-4c784a84a66adf221597', 'source-node-002656', '4', '2656', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002658', 'source-doc-4c784a84a66adf221597', 'source-node-002655', '3', '2657', 'text', '发病特征：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002659', 'source-doc-4c784a84a66adf221597', 'source-node-002658', '4', '2658', 'text', '叶片：初期为不规则形、边缘模糊的黑色坏死病斑（直径 3~5 mm）；高温高湿时病斑快速扩展（1~2 天内蔓延至整张叶片），叶片焦枯脱落（“叶枯型”）；干旱时病斑扩展缓慢，形成褐色枯死斑，周围变黄（“叶斑型”）。保湿后病斑上会产生橘黄色分生孢子堆。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002660', 'source-doc-4c784a84a66adf221597', 'source-node-002658', '4', '2659', 'text', '果实：仅形成直径 1~2 mm 的圆形凹陷斑，周围有红色晕圈，自然条件下极少产孢（与典型炭疽病不同）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002661', 'source-doc-4c784a84a66adf221597', 'source-node-002658', '4', '2660', 'text', '品种差异', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002662', 'source-doc-4c784a84a66adf221597', 'source-node-002661', '5', '2661', 'text', '主要危害嘎啦、金冠、乔纳金、秦冠等品种，富士、红星、元帅等高度抗病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002663', 'source-doc-4c784a84a66adf221597', 'source-node-002658', '4', '2662', 'text', '流行规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002664', 'source-doc-4c784a84a66adf221597', 'source-node-002663', '5', '2663', 'text', '病菌以菌丝体在病僵果、干枝、果台越冬，5 月产生分生孢子，借雨水 / 昆虫传播，经皮孔 / 伤口侵入，潜育期短（仅需 2 小时保湿即可侵染）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002665', 'source-doc-4c784a84a66adf221597', 'source-node-002663', '5', '2664', 'text', '发病高峰在 7~8 月连续阴雨期，高温（28~32℃）高湿条件下易暴发，可多次侵染。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002666', 'source-doc-4c784a84a66adf221597', 'source-node-002655', '3', '2665', 'text', '农业防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002667', 'source-doc-4c784a84a66adf221597', 'source-node-002666', '4', '2666', 'text', '清园：秋季落叶后及春季萌芽前，彻底清扫病叶、病果，刮除枝干病斑并销毁，减少越冬菌源。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002668', 'source-doc-4c784a84a66adf221597', 'source-node-002666', '4', '2667', 'text', '果园管理：起垄栽培、生草覆盖（改良环境），雨季及时排水，避免积水；合理修剪，改善通风透光。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002669', 'source-doc-4c784a84a66adf221597', 'source-node-002666', '4', '2668', 'text', '抗病品种：新建果园优先选择富士等抗病品种。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002670', 'source-doc-4c784a84a66adf221597', 'source-node-002655', '3', '2669', 'text', '化学防治：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002671', 'source-doc-4c784a84a66adf221597', 'source-node-002670', '4', '2670', 'text', '唑醚·氟唑菌酰胺最有效，其次吡唑醚菌酯或克菌丹+亚磷酸钾', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002672', 'source-doc-4c784a84a66adf221597', 'source-node-002670', '4', '2671', 'text', '关键时期：6 月雨季前至 9 月，每月喷施 1 次波尔多液（持效期 15 天以上，雨季首选）；两次波尔多液之间可穿插吡唑醚菌酯（1500 倍液，兼具保护和内吸治疗作用）、代森锰锌（500 倍液）等药剂。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002673', 'source-doc-4c784a84a66adf221597', 'source-node-002670', '4', '2672', 'text', '具体节点：萌芽前：喷施 3~5 波美度石硫合剂或 100~200 倍硫酸铜液，铲除越冬病菌。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002674', 'source-doc-4c784a84a66adf221597', 'source-node-002670', '4', '2673', 'text', '雨季来临前：提前喷施波尔多液，确保每次阴雨期叶片和果实有药剂保护。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002675', 'source-doc-4c784a84a66adf221597', 'source-node-002670', '4', '2674', 'text', '发病初期：若错过波尔多液，可选用吡唑醚菌酯（24 小时内用药，治疗效果 70%）或咪鲜胺（60%）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002676', 'source-doc-4c784a84a66adf221597', 'source-node-002655', '3', '2675', 'text', '注意事项', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002677', 'source-doc-4c784a84a66adf221597', 'source-node-002676', '4', '2676', 'text', '三唑类药剂（如戊唑醇、氟硅唑）对该病无效，需避免使用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002678', 'source-doc-4c784a84a66adf221597', 'source-node-002676', '4', '2677', 'text', '喷药时需细致周到，确保叶片正反两面、树冠内膛均匀着药，雨前优先用保护性杀菌剂，雨后用内吸治疗剂。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002679', 'source-doc-4c784a84a66adf221597', 'source-node-000545', '1', '2678', 'text', '2.1.17榴莲密', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002680', 'source-doc-4c784a84a66adf221597', 'source-node-002679', '2', '2679', 'text', '细菌性褐斑病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002681', 'source-doc-4c784a84a66adf221597', 'source-node-002680', '3', '2680', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002682', 'source-doc-4c784a84a66adf221597', 'source-node-002680', '3', '2681', 'text', '氟吡菌酰胺、春雷溴菌腈、芸苔素', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002683', 'source-doc-4c784a84a66adf221597', 'source-node-000545', '1', '2682', 'text', '2.1.18杨梅', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002684', 'source-doc-4c784a84a66adf221597', 'source-node-002683', '2', '2683', 'text', '杨梅凋萎病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002685', 'source-doc-4c784a84a66adf221597', 'source-node-002684', '3', '2684', 'text', '病症', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002686', 'source-doc-4c784a84a66adf221597', 'source-node-002685', '4', '2685', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002687', 'source-doc-4c784a84a66adf221597', 'source-node-002684', '3', '2686', 'text', '一、典型病症', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002688', 'source-doc-4c784a84a66adf221597', 'source-node-002687', '4', '2687', 'text', '初期：枝梢少量叶片失水青枯、无光泽，逐步转为红褐色干枯，病叶多紧贴枝条不易脱落，常单侧枝梢先发病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002689', 'source-doc-4c784a84a66adf221597', 'source-node-002687', '4', '2688', 'text', '中期：病害沿枝条蔓延，整根新梢 / 结果枝枯死，剥开皮层可见木质部维管束变褐，有褐色条斑。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002690', 'source-doc-4c784a84a66adf221597', 'source-node-002687', '4', '2689', 'text', '后期：病枝向大枝、主干扩展，局部枝组或整株枯死，高湿环境下病部可产生白色霉状病菌孢子。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002691', 'source-doc-4c784a84a66adf221597', 'source-node-002684', '3', '2690', 'text', '二、发生原因', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002692', 'source-doc-4c784a84a66adf221597', 'source-node-002691', '4', '2691', 'text', '病原：核心为拟盘多毛孢类真菌，病菌在病枝、病落叶中越冬，是初次侵染源。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002693', 'source-doc-4c784a84a66adf221597', 'source-node-002691', '4', '2692', 'text', '传播：借风雨、昆虫、修剪工具扩散，从剪口、虫口、冻裂伤口等侵入，堵塞枝梢输导组织，导致水分养分输送中断。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002694', 'source-doc-4c784a84a66adf221597', 'source-node-002691', '4', '2693', 'text', '诱发条件：挂果过量、养分不足致树势衰弱；土壤积水黏重、根系腐烂；土壤严重酸化；修剪过重伤口多；偏施氮肥。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002695', 'source-doc-4c784a84a66adf221597', 'source-node-002684', '3', '2694', 'text', '三、预防措施', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002696', 'source-doc-4c784a84a66adf221597', 'source-node-002695', '4', '2695', 'text', '强健树势：合理疏果控产，增施有机肥与磷钾肥，补充硼、锌中微量元素，忌偏施氮肥。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002697', 'source-doc-4c784a84a66adf221597', 'source-node-002695', '4', '2696', 'text', '减少菌源：冬季彻底清园，剪除病弱枝、枯死枝并集中烧毁，喷施 3-5 波美度石硫合剂封园。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002698', 'source-doc-4c784a84a66adf221597', 'source-node-002695', '4', '2697', 'text', '田间管护：疏通排水沟避免积水，树盘覆草调温保湿；修剪工具及时消毒，大剪口涂抹杀菌剂保护。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002699', 'source-doc-4c784a84a66adf221597', 'source-node-002695', '4', '2698', 'text', '调酸改土：土壤 pH＜5.5 时，适量撒施生石灰调节土壤酸度，提升根系活力与抗病性。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002700', 'source-doc-4c784a84a66adf221597', 'source-node-002684', '3', '2699', 'text', '四、防治方案', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002701', 'source-doc-4c784a84a66adf221597', 'source-node-002700', '4', '2700', 'text', '彻底清病梢：发现病梢立即剪除，剪口需延伸至病部下方 20cm 的健康枝条处，病枝全部带出果园销毁。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002702', 'source-doc-4c784a84a66adf221597', 'source-node-002700', '4', '2701', 'text', '药剂防控：发病初期全树均匀喷雾，可选 30% 苯甲・丙环唑 2000 倍液、75% 肟菌・戊唑醇 3000 倍液或 70% 甲基硫菌灵 800 倍液，或使用井冈霉素+噻呋酰胺，间隔 7-10 天 1 次，连喷 2-3 次，枝梢、叶片正反面均需喷透。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002703', 'source-doc-4c784a84a66adf221597', 'source-node-002700', '4', '2702', 'text', '根部辅助：根部淋施恶霉灵 + 生根剂，修复根系活力，增强树体抗病能力。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002704', 'source-doc-4c784a84a66adf221597', 'source-node-002700', '4', '2703', 'text', '大枝处理：主干 / 大枝发病时，刮除病部皮层，涂抹咪鲜胺或噻霉酮药剂封闭伤口。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002705', 'source-doc-4c784a84a66adf221597', 'source-node-000545', '1', '2704', 'text', '2.1.19甘蔗', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002706', 'source-doc-4c784a84a66adf221597', 'source-node-002705', '2', '2705', 'text', '甘蔗红壳病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002707', 'source-doc-4c784a84a66adf221597', 'source-node-002706', '3', '2706', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002708', 'source-doc-4c784a84a66adf221597', 'source-node-002707', '4', '2707', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002709', 'source-doc-4c784a84a66adf221597', 'source-node-002706', '3', '2708', 'text', '症状鉴别', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002710', 'source-doc-4c784a84a66adf221597', 'source-node-002709', '4', '2709', 'text', '甘蔗的其他一些病虫害也可能表现出类似的症状。关键在于观察红色病部中是否有白色斑点的存在。红壳病则不同，其红色病部中常常夹杂着长圆形横向的白色斑点，这是红壳病特有的症状之一。通过这一特征，我们可以较为准确地判断出甘蔗是否感染了红壳病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002711', 'source-doc-4c784a84a66adf221597', 'source-node-002706', '3', '2710', 'text', '成因与防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002712', 'source-doc-4c784a84a66adf221597', 'source-node-002711', '4', '2711', 'text', '甘蔗红壳病成因', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002713', 'source-doc-4c784a84a66adf221597', 'source-node-002712', '5', '2712', 'text', '偏爱高温且潮湿的环境，因为这样的条件更利于病菌的滋生与传播。当甘蔗茎部受到机械损伤或生理性裂口时，病菌便趁虚而入，进而引发红壳病。甘蔗红壳病易发生于高温潮湿的环境，病菌容易通过伤口进入甘蔗。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002714', 'source-doc-4c784a84a66adf221597', 'source-node-002711', '4', '2713', 'text', '甘蔗红壳病的防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002715', 'source-doc-4c784a84a66adf221597', 'source-node-002714', '5', '2714', 'text', '蔗田排灌系统要建立起来，及时排除多余积水，以降低田间的湿度，并及时剥除病叶、老叶并集中烧毁,减少侵染源。注意氮、磷、钾肥的配合施用，防止单施过量氮肥。病区在雨季前多施钾肥，以增强甘蔗的抗病力。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002716', 'source-doc-4c784a84a66adf221597', 'source-node-002714', '5', '2715', 'text', '更主要的是，当发现甘蔗发生红壳病之后，蔗农要及时用药处理，排除隐患，及时止损。方法是使用啶氧菌酯+丙环唑。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002717', 'source-doc-4c784a84a66adf221597', 'source-node-002714', '5', '2716', 'text', '为了预防甘蔗红壳病，我们需要建立蔗田的排灌系统，确保能及时排除多余的积水，从而降低田间的湿度。同时，定期剥除病叶和老叶，并将其集中烧毁，以减少病菌的传播源。在施肥时，应注意氮、磷、钾肥的均衡施用，避免过量施用单一的氮肥。特别是在病区，建议在雨季前增加钾肥的施用，以提升甘蔗的抗病能力。一旦发现甘蔗出现红壳病症状，蔗农应立即采取药物治疗，以消除隐患并减少损失。可选的药物组合包括啶氧菌酯与丙环唑，或吡唑醚菌脂与苯醚甲环唑等。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002718', 'source-doc-4c784a84a66adf221597', NULL, '0', '2717', 'text', '2.2 蔬菜', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002719', 'source-doc-4c784a84a66adf221597', 'source-node-002718', '1', '2718', 'text', '2.2.1 辣椒', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002720', 'source-doc-4c784a84a66adf221597', 'source-node-002719', '2', '2719', 'text', '细菌性病害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002721', 'source-doc-4c784a84a66adf221597', 'source-node-002720', '3', '2720', 'text', '细菌性叶斑病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002722', 'source-doc-4c784a84a66adf221597', 'source-node-002721', '4', '2721', 'text', '发病规律：病原菌为丁香假单胞杆菌适合致病变种 （Pseudomonas syringae pv. aptata Young. Dye & Wilkie. ）， 属假单胞杆菌属细菌。病原菌在种子、病残体及土壤中越冬，借助风雨、灌溉水、农事操作等传播，从气孔、水孔或伤口侵入。高温高湿（25 - 30℃，相对湿度 85% 以上）、连作、种植过密、通风透光差时易发病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002723', 'source-doc-4c784a84a66adf221597', 'source-node-002721', '4', '2722', 'text', '症状：害叶片。 常见的病斑类型有两种， 一种是先从叶缘附近出现黄绿色近圆形水渍状小斑点， 扩大后变为大小不等的褐色至锈红色病 ， 干燥时病斑多呈褐色； 另一类症状多从叶缘开始出现水浸状黄化 ， 最后扩展至整个叶', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002724', 'source-doc-4c784a84a66adf221597', 'source-node-002721', '4', '2723', 'text', '预防方法：选用无病种子，进行种子消毒（如 55℃温水浸种 15 分钟），实行轮作，避免连作，合理密植，加强田间通风透光管理，及时清除病残体。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002725', 'source-doc-4c784a84a66adf221597', 'source-node-002721', '4', '2724', 'text', '防治方法：发病初期，可选用 72% 农用链霉素可溶性粉剂 3000 - 4000 倍液、3% 中生菌素可湿性粉剂 600 - 800 倍液等喷雾，间隔 7 - 10 天喷 1 次，连喷 2 - 3 次。春雷·喹啉铜、春雷·溴菌腈', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002726', 'source-doc-4c784a84a66adf221597', 'source-node-002721', '4', '2725', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002727', 'source-doc-4c784a84a66adf221597', 'source-node-002726', '5', '2726', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002728', 'source-doc-4c784a84a66adf221597', 'source-node-002720', '3', '2727', 'text', '辣椒青枯病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002729', 'source-doc-4c784a84a66adf221597', 'source-node-002728', '4', '2728', 'text', '症状：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002730', 'source-doc-4c784a84a66adf221597', 'source-node-002729', '5', '2729', 'text', '植株叶片先在中午温度高时出现萎蔫， 早上及傍晚温度低时还可恢复， 几天后萎蔫叶片不能够再恢复， 整株叶片枯死， 但短期内叶片仍保持青绿色且不脱落。 割开茎部可见维管束变褐， 用手挤压切口可见白色菌脓', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002731', 'source-doc-4c784a84a66adf221597', 'source-node-002728', '4', '2730', 'text', '发病规律：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002732', 'source-doc-4c784a84a66adf221597', 'source-node-002731', '5', '2731', 'text', '病原菌为茄科劳尔氏菌（Ralstonia solanacearum），是一种细菌。病原菌主要在土壤中及病残体上越冬，能在土壤中存活 1 - 6 年。该病菌从辣椒植株根部或茎基部的伤口侵入，在田间主要通过雨水、灌溉水、农具、农事操作等传播。当土温在 20 - 25℃、土壤湿度较大、pH 值在 6 - 7 时，有利于病原菌的繁殖和侵染。辣椒在生长旺盛期，尤其是在高温高湿的环境条件下（气温 30 - 37℃，相对湿度 90% 以上），发病迅速。连作、地势低洼、排水不畅、植株生长不良等情况会加重病害的发生。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002733', 'source-doc-4c784a84a66adf221597', 'source-node-002728', '4', '2732', 'text', '预防方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002734', 'source-doc-4c784a84a66adf221597', 'source-node-002733', '5', '2733', 'text', '轮作换茬：实行与非茄科作物轮作，轮作年限至少 3 - 5 年，减少病原菌在土壤中的积累。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002735', 'source-doc-4c784a84a66adf221597', 'source-node-002733', '5', '2734', 'text', '品种选择：选用抗（耐）青枯病的辣椒品种，从品种本身降低发病风险。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002736', 'source-doc-4c784a84a66adf221597', 'source-node-002733', '5', '2735', 'text', '土壤改良：对酸性土壤，适量施用石灰调节土壤酸碱度，使 pH 值保持在 7 左右，抑制病原菌的生长。同时，增施有机肥和生物菌肥，改善土壤结构和微生物环境，增强土壤的保水保肥和透气性能。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002737', 'source-doc-4c784a84a66adf221597', 'source-node-002733', '5', '2736', 'text', '栽培管理：采用高畦种植，确保良好的排水系统，避免田间积水。合理密植，保证植株间通风透光良好。在农事操作过程中，尽量避免对植株造成机械损伤，减少病原菌的入侵途径。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002738', 'source-doc-4c784a84a66adf221597', 'source-node-002733', '5', '2737', 'text', '清洁田园：及时清除病株和病残体，带出田外深埋或烧毁，防止病原菌在田间传播。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002739', 'source-doc-4c784a84a66adf221597', 'source-node-002728', '4', '2738', 'text', '防治方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002740', 'source-doc-4c784a84a66adf221597', 'source-node-002739', '5', '2739', 'text', '药剂防治：发病初期，可选用 72% 农用链霉素可溶性粉剂 4000 倍液、新植霉素 4000 - 5000 倍液、3% 中生菌素可湿性粉剂 600 - 800 倍液等进行灌根，每株灌药量 200 - 300 毫升，7 - 10 天灌 1 次，连续灌 2 - 3 次。也可以选择有机铜制剂，尤克龙（喹啉铜）或噻菌铜进行灌根。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002741', 'source-doc-4c784a84a66adf221597', 'source-node-002739', '5', '2740', 'text', '生物防治：利用有益微生物来拮抗病原菌，如芽孢杆菌、假单胞菌等。这些微生物可以通过竞争营养、分泌抗菌物质等方式抑制青枯病菌的生长和繁殖。可按照产品说明，将微生物制剂施用于土壤或灌根，增强植株的抗病能力。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002742', 'source-doc-4c784a84a66adf221597', 'source-node-002728', '4', '2741', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002743', 'source-doc-4c784a84a66adf221597', 'source-node-002742', '5', '2742', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002744', 'source-doc-4c784a84a66adf221597', 'source-node-002719', '2', '2743', 'text', '真菌性病害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002745', 'source-doc-4c784a84a66adf221597', 'source-node-002744', '3', '2744', 'text', '炭疽病（Colletotrichum spp.）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002746', 'source-doc-4c784a84a66adf221597', 'source-node-002745', '4', '2745', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002747', 'source-doc-4c784a84a66adf221597', 'source-node-002746', '5', '2746', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002748', 'source-doc-4c784a84a66adf221597', 'source-node-002745', '4', '2747', 'text', '发病规律：主要以菌丝体潜伏在种子内，或以分生孢子附着在种子表面，或以拟菌核和分生孢子盘在病残体上越冬。翌年，在 27℃左右、相对湿度 95% 以上时，分生孢子借风雨、昆虫传播，从伤口或直接穿透表皮侵入，高温多雨、田间郁闭、植株生长衰弱或过于密集发病重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002749', 'source-doc-4c784a84a66adf221597', 'source-node-002745', '4', '2748', 'text', '预防方法：种子处理（播种前，用 55℃温水浸种 10 分钟，或用 50% 多菌灵可湿性粉剂 500 倍液浸种 1 小时，然后洗净催芽），合理施肥，增施磷、钾肥，增强植株抗病能力，及时摘除病果、病叶。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002750', 'source-doc-4c784a84a66adf221597', 'source-node-002745', '4', '2749', 'text', '防治方法：发病初期，可选用 70% 甲基托布津可湿性粉剂 800 倍液、80% 炭疽福美可湿性粉剂 800 倍液等喷雾，80% 代森锰锌可湿性粉剂 600 - 800 倍液，75% 百菌清可湿性粉剂 600 - 700 倍液等，每 7 - 10 天喷 1 次，连续喷 2 - 3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002751', 'source-doc-4c784a84a66adf221597', 'source-node-002750', '5', '2750', 'text', '发病初期药剂防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002752', 'source-doc-4c784a84a66adf221597', 'source-node-002751', '6', '2751', 'text', '- 可选用70%甲基托布津可湿性粉剂800倍液、80%炭疽福美可湿性粉剂800倍液、80%代森锰锌可湿性粉剂600-800倍液、75%百菌清可湿性粉剂600-700倍液等喷雾，每7-10天喷1次，连续喷2-3次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002753', 'source-doc-4c784a84a66adf221597', 'source-node-002750', '5', '2752', 'text', '苯并咪唑类杀菌剂', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002754', 'source-doc-4c784a84a66adf221597', 'source-node-002753', '6', '2753', 'text', '- 如70%甲基托布津（甲基硫菌灵）可湿性粉剂800-1000倍液。甲基托布津能够干扰病原菌的细胞分裂和生长，抑制病原菌的活性。在发病初期开始使用，每隔7-10天喷一次，连续喷2-3次，重点喷施叶片正反两面和果实。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002755', 'source-doc-4c784a84a66adf221597', 'source-node-002750', '5', '2754', 'text', '三唑类杀菌剂', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002756', 'source-doc-4c784a84a66adf221597', 'source-node-002755', '6', '2755', 'text', '- 10%苯醚甲环唑水分散粒剂800-1000倍液。苯醚甲环唑具有内吸性，能够被辣椒植株吸收并在体内传导，对炭疽病病原菌的菌丝生长和孢子形成有很强的抑制作用。使用时，注意按照推荐剂量，避免超量使用导致药害。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002757', 'source-doc-4c784a84a66adf221597', 'source-node-002750', '5', '2756', 'text', '复配杀菌剂', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002758', 'source-doc-4c784a84a66adf221597', 'source-node-002757', '6', '2757', 'text', '- 50%咪鲜胺锰盐可湿性粉剂1000-1500倍液。咪鲜胺锰盐是一种广谱杀菌剂，对炭疽病有很好的防治效果。它可以抑制病原菌的细胞膜合成，从而达到杀菌的目的。在发病初期，将药剂均匀喷洒在辣椒植株上，尤其是发病部位周围，每隔7-10天喷一次，视病情连续喷2-3次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002759', 'source-doc-4c784a84a66adf221597', 'source-node-002750', '5', '2758', 'text', '轮换用药：若发现辣椒炭疽病，可选用炭疽病用苯甲·吡唑酯、啶氧菌酯、咪鲜胺、吡唑·代森联、（露娜森）肟菌酯·戊唑醇等药剂防治，注意轮换用药', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002760', 'source-doc-4c784a84a66adf221597', 'source-node-002750', '5', '2759', 'text', '药剂防治：发病初期及时用药剂防治，药剂可用50％苯菌特可湿性粉剂1000倍液，或50％多菌灵可湿性粉剂500倍液，或80％大生可湿性粉剂800倍液，或77％可杀得可湿性微粒粉剂500～800倍液，或80％炭疽福美可湿性粉剂800倍液喷洒。雨前用325 克 / 升苯甲・嘧菌酯（阿米妙收）30 - 50ml / 亩，雨后用500 克 / 升氟啶胺（农割）30 - 35ml / 亩，交替喷雾防治，兼防叶斑类病害。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002761', 'source-doc-4c784a84a66adf221597', 'source-node-002750', '5', '2760', 'text', '拮抗微生物利用', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002762', 'source-doc-4c784a84a66adf221597', 'source-node-002761', '6', '2761', 'text', '- 一些有益微生物如芽孢杆菌（Bacillus spp.）、木霉菌（Trichoderma spp.）等对辣椒炭疽病病原菌有拮抗作用。例如，枯草芽孢杆菌可以在辣椒植株表面或根际周围定殖，通过竞争营养、分泌抗菌物质等方式抑制炭疽病病原菌的生长。可以将含有有益微生物的生物制剂按照产品说明进行土壤处理或叶面喷施，在辣椒生长的关键时期使用，如苗期、初花期等，能够起到一定的预防和减轻病害的作用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002763', 'source-doc-4c784a84a66adf221597', 'source-node-002750', '5', '2762', 'text', '植物源杀菌剂应用', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002764', 'source-doc-4c784a84a66adf221597', 'source-node-002763', '6', '2763', 'text', '- 从植物中提取的一些天然物质也具有一定的杀菌活性。例如，印楝素是从印楝树中提取的一种生物活性物质，对辣椒炭疽病病原菌有抑制作用。可以将印楝素制剂按照推荐浓度稀释后进行喷雾，在发病初期使用，间隔7-10天左右再喷一次，有助于控制病害的发展。同时，植物源杀菌剂对环境友好，不会像化学杀菌剂那样容易导致病原菌产生抗药性。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002765', 'source-doc-4c784a84a66adf221597', 'source-node-002750', '5', '2764', 'text', '加强田间管理：及时清除病残体，包括病叶、病果和病株，带出田外深埋或烧毁。在辣椒生长期间，定期巡查田间，发现病叶、病果应立即摘除。收获后，对田园进行彻底清理，清除所有的辣椒残株和落叶，减少病原菌的越冬场所，从而降低来年炭疽病的发生风险。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002766', 'source-doc-4c784a84a66adf221597', 'source-node-002744', '3', '2765', 'text', '辣椒白星病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002767', 'source-doc-4c784a84a66adf221597', 'source-node-002766', '4', '2766', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002768', 'source-doc-4c784a84a66adf221597', 'source-node-002767', '5', '2767', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002769', 'source-doc-4c784a84a66adf221597', 'source-node-002766', '4', '2768', 'text', '症状：该病主要为害叶片。 病斑呈圆形或近圆形， 边缘呈黑褐色或深色， 中央呈灰白色或白色 病斑背面与正面症状相差不大， 中间有时穿孔。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002770', 'source-doc-4c784a84a66adf221597', 'source-node-002766', '4', '2769', 'text', '发病规律：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002771', 'source-doc-4c784a84a66adf221597', 'source-node-002770', '5', '2770', 'text', '病原菌为辣椒叶点霉（Phyllosticta capsici），主要以分生孢子器在病残体上、混在种子间或潜伏在种子内部越冬。当温度处于 25 - 30℃、相对湿度高于 80% 时，分生孢子器吸水，分生孢子逸出，借风雨传播，从辣椒植株的伤口或气孔侵入，完成初侵染。此后，病部产生新分生孢子，持续借助风雨、昆虫等媒介传播，反复进行再侵染。种植过密致使通风透光不佳、田间湿度长时间偏高，以及偏施氮肥造成植株生长过旺、组织柔弱、抗性降低的情况，再结合温暖潮湿的气候环境，会显著加剧病害发生与蔓延，发病高峰期多在辣椒生长中后期。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002772', 'source-doc-4c784a84a66adf221597', 'source-node-002766', '4', '2771', 'text', '预防方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002773', 'source-doc-4c784a84a66adf221597', 'source-node-002772', '5', '2772', 'text', '品种选择：依据当地气候特点、病害流行状况，精心挑选对白星病抗性优良的辣椒品种，从根源增强植株抗病潜能。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002774', 'source-doc-4c784a84a66adf221597', 'source-node-002772', '5', '2773', 'text', '种植管理：按照品种特性与土壤肥力，科学规划种植密度，保证每亩种植 3000 - 4000 株，优化田间通风透光条件，降低湿度；秉持平衡施肥理念，增施有机肥、磷钾肥，严格把控氮肥施用量，强化植株自身抵御病害能力。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002775', 'source-doc-4c784a84a66adf221597', 'source-node-002772', '5', '2774', 'text', '田园清理：定期巡查田园，及时摘除并清理病叶、病果、病株，带出田外集中深埋或烧毁，最大程度减少病原菌越冬和初侵染源头；收获结束后，全面深耕翻土，深埋病原菌，削弱其存活能力。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002776', 'source-doc-4c784a84a66adf221597', 'source-node-002766', '4', '2775', 'text', '防治方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002777', 'source-doc-4c784a84a66adf221597', 'source-node-002776', '5', '2776', 'text', '种子处理：播种前，可运用 55℃温水浸种 15 - 20 分钟，或采用种子重量 0.3% 的 50% 多菌灵可湿性粉剂拌种操作，有效杀灭种子内外可能潜藏的病原菌，保障种子 “健康” 下种。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002778', 'source-doc-4c784a84a66adf221597', 'source-node-002776', '5', '2777', 'text', '药剂喷雾：发病伊始，抓紧选用 70% 甲基硫菌灵可湿性粉剂 800 - 1000 倍液、50% 多菌灵可湿性粉剂 600 - 800 倍液、80% 代森锰锌可湿性粉剂 600 - 800 倍液等杀菌剂开展喷雾作业，着重喷施叶片正反两面、茎秆等部位，每隔 7 - 10 天喷施 1 次，接连喷施 2 - 3 次，且注意交替轮换用药，规避病原菌产生抗药性问题。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002779', 'source-doc-4c784a84a66adf221597', 'source-node-002778', '6', '2778', 'text', '茬口轮作：提倡与非茄科蔬菜隔年轮作，以减少田间病菌来源。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002780', 'source-doc-4c784a84a66adf221597', 'source-node-002778', '6', '2779', 'text', '加强田间管理：合理密植，深沟高畦栽培，雨后及时排水，降低地下水位，适当增施磷钾肥，促使植株健壮，提高植株抗病能力。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002781', 'source-doc-4c784a84a66adf221597', 'source-node-002778', '6', '2780', 'text', '清洁田园：及时摘除病、老叶，收获后清除病残体，带出田外深埋或烧毁，深翻土壤，加速病残体的腐烂分解。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002782', 'source-doc-4c784a84a66adf221597', 'source-node-002778', '6', '2781', 'text', '化学防治措施：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002783', 'source-doc-4c784a84a66adf221597', 'source-node-002778', '6', '2782', 'text', '药剂喷雾防治：在发病初期开始喷药，每隔7-10天喷1次，连续喷2-3次。可选用以下药剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002784', 'source-doc-4c784a84a66adf221597', 'source-node-002783', '7', '2783', 'text', '80%新万生（代森锰锌）可湿性粉剂800倍液', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002785', 'source-doc-4c784a84a66adf221597', 'source-node-002783', '7', '2784', 'text', '80%山德生（丙森锌）可湿性粉剂600-800倍液', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002786', 'source-doc-4c784a84a66adf221597', 'source-node-002783', '7', '2785', 'text', '50%托布津（多菌灵）可湿性粉剂1000倍液', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002787', 'source-doc-4c784a84a66adf221597', 'source-node-002783', '7', '2786', 'text', '77%可杀得（氢氧化铜）可湿性粉剂1000倍液', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002788', 'source-doc-4c784a84a66adf221597', 'source-node-002783', '7', '2787', 'text', '75%百菌清可湿性粉剂600倍液', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002789', 'source-doc-4c784a84a66adf221597', 'source-node-002783', '7', '2788', 'text', '50%琥胶肥酸铜可湿性粉剂500倍液', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002790', 'source-doc-4c784a84a66adf221597', 'source-node-002783', '7', '2789', 'text', '25%阿米西达（丙环唑）悬浮液1500倍液', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002791', 'source-doc-4c784a84a66adf221597', 'source-node-002783', '7', '2790', 'text', '25%啶氧菌酯悬浮剂1000倍液', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002792', 'source-doc-4c784a84a66adf221597', 'source-node-002783', '7', '2791', 'text', '50%消菌灵（异菌脲）可湿性粉剂1500-2000倍液', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002793', 'source-doc-4c784a84a66adf221597', 'source-node-002783', '7', '2792', 'text', '50%异菌脲悬浮剂1000倍液', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002794', 'source-doc-4c784a84a66adf221597', 'source-node-002778', '6', '2793', 'text', '熏烟防治：保护地密闭时可用烟剂一号熏烟，每亩350克。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002795', 'source-doc-4c784a84a66adf221597', 'source-node-002744', '3', '2794', 'text', '白粉病（Leveillula taurica）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002796', 'source-doc-4c784a84a66adf221597', 'source-node-002795', '4', '2795', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002797', 'source-doc-4c784a84a66adf221597', 'source-node-002796', '5', '2796', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002798', 'source-doc-4c784a84a66adf221597', 'source-node-002795', '4', '2797', 'text', '发病规律：以菌丝体或闭囊壳在病残体上越冬，适宜温度（20 - 25℃）、相对湿度 70% 左右且田间通风透光不良时，分生孢子借气流传播，反复侵染。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002799', 'source-doc-4c784a84a66adf221597', 'source-node-002795', '4', '2798', 'text', '预防方法：选用抗病品种，合理密植，保持良好通风透光条件，增施有机肥及磷钾肥，增强植株抗性，及时清理病残株。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002800', 'source-doc-4c784a84a66adf221597', 'source-node-002795', '4', '2799', 'text', '防治方法：发病初期，用 25% 粉锈宁（三唑酮）可湿性粉剂 1500 - 2000 倍液、10% 苯醚甲环唑水分散粒剂 800 - 1000 倍液等喷雾，7 - 10 天 1 次，连喷 2 - 3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002801', 'source-doc-4c784a84a66adf221597', 'source-node-002800', '5', '2800', 'text', '品种选择：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002802', 'source-doc-4c784a84a66adf221597', 'source-node-002801', '6', '2801', 'text', '不同辣椒品种对白粉病抗性各异，应依据当地实际种植情形与病害发生态势，审慎挑选抗病、耐病品种，像壮椒 2008、满丰二号等，以此从根源处降低发病风险，筑牢防病 “第一道防线”。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002803', 'source-doc-4c784a84a66adf221597', 'source-node-002800', '5', '2802', 'text', '合理密植：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002804', 'source-doc-4c784a84a66adf221597', 'source-node-002803', '6', '2803', 'text', '按科学规划，建议亩栽苗 2000 - 2200 颗，采用 1.2 米畦面实施单垄栽培，株距把控在 20 - 25 公分，优先选取高垄栽培模式。鉴于根系生长对温室环境、光照、氧气、水分等条件要求严苛，高垄栽培在浇水后可保障土壤具备优良通透性，强化保温效能，优化植株生长根基条件，削减因种植过密、通风透光不佳滋生白粉病的隐患。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002805', 'source-doc-4c784a84a66adf221597', 'source-node-002800', '5', '2804', 'text', '合理给水给肥：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002806', 'source-doc-4c784a84a66adf221597', 'source-node-002805', '6', '2805', 'text', '白粉病病原菌滋生繁衍与环境温湿度紧密关联，高温高湿是发病 “温床”，且干湿交替恰是其孢子萌发、再侵染的 “便利契机”。故而在水分管理上，不可盲目过度控水，特别是秋季高温阶段，不能单纯为抑制秧苗旺长而克扣水分，应维持土壤 “见干见湿” 状态，同步把控棚室内空气湿度处于合理区间，规避湿度大幅波动助长病害。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002807', 'source-doc-4c784a84a66adf221597', 'source-node-002800', '5', '2806', 'text', '清洁田园：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002808', 'source-doc-4c784a84a66adf221597', 'source-node-002807', '6', '2807', 'text', '在辣椒生长全程，需强化田园巡查管护，及时摘除病叶、老叶，减少病原菌栖息繁衍 “据点”。待收获完毕，彻底清除田间病残体，严谨带出田外并深埋或付之一炬，同时对土壤开展深翻作业，加速病残体腐解，破坏病原菌越冬、潜藏 “避风港”，最大程度压低来年发病 “基数”。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002809', 'source-doc-4c784a84a66adf221597', 'source-node-002800', '5', '2808', 'text', '化学防治措施：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002810', 'source-doc-4c784a84a66adf221597', 'source-node-002809', '6', '2809', 'text', '药剂喷雾防治：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002811', 'source-doc-4c784a84a66adf221597', 'source-node-002810', '7', '2810', 'text', '病害防治关键在 “早”，发病初期就得火速行动，启动药剂喷雾作业，以 7 - 10 天为间隔周期，连贯喷施 2 - 3 次。可按需选用下列高效药剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002812', 'source-doc-4c784a84a66adf221597', 'source-node-002811', '8', '2811', 'text', '三唑类杀菌剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002813', 'source-doc-4c784a84a66adf221597', 'source-node-002812', '9', '2812', 'text', '25% 粉锈宁（三唑酮）可湿性粉剂 1000 - 1500 倍液，有效成分三唑酮通过抑制病原菌麦角甾醇合成，干扰其细胞膜构建，遏制菌丝生长与孢子形成，直击病害 “要害”。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002814', 'source-doc-4c784a84a66adf221597', 'source-node-002812', '9', '2813', 'text', '10% 苯醚甲环唑水分散粒剂 800 - 1000 倍液，核心成分苯醚甲环唑抑制真菌细胞色素 P450 酶活性，阻断麦角甾醇合成路径，致使细胞膜结构崩坏，强效抑菌杀菌。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002815', 'source-doc-4c784a84a66adf221597', 'source-node-002812', '9', '2814', 'text', '25% 吡唑嘧菌酯乳油 2500 倍液，吡唑嘧菌酯属甲氧基丙烯酸酯类，作用于病原菌呼吸链，抑制线粒体呼吸进程，“釜底抽薪” 式阻碍病原菌能量代谢与繁衍。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002816', 'source-doc-4c784a84a66adf221597', 'source-node-002811', '8', '2815', 'text', '其他高效杀菌剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002817', 'source-doc-4c784a84a66adf221597', 'source-node-002816', '9', '2816', 'text', '30% 特富灵（氟菌唑）可湿性粉剂 1500 - 2000 倍液，主要成分氟菌唑为咪唑类，借抑制麦角甾醇合成，让病原菌 “失能”，防控病害蔓延。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002818', 'source-doc-4c784a84a66adf221597', 'source-node-002816', '9', '2817', 'text', '40% 多硫悬浮剂 500 倍液，主含多硫化钡与硫磺，施药后释放硫元素，以其氧化性与腐蚀性破坏病原菌细胞结构，施展杀菌威力。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002819', 'source-doc-4c784a84a66adf221597', 'source-node-002816', '9', '2818', 'text', '42.8% 肟菌酯・氟吡菌酰胺 1500 - 3000 倍液，肟菌酯（甲氧基丙烯酸酯类）作用呼吸链，氟吡菌酰胺作为琥珀酸脱氢酶抑制剂，二者 “强强联手”，兼具防护、治疗、铲除多重功效，瓦解病原菌生理机能。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002820', 'source-doc-4c784a84a66adf221597', 'source-node-002816', '9', '2819', 'text', '70% 代森锰锌可湿性粉剂 800 倍液，主要成分代森锰锌于植株表面 “披覆” 防护膜，恰似 “盾牌” 阻挡病原菌侵入。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002821', 'source-doc-4c784a84a66adf221597', 'source-node-002816', '9', '2820', 'text', '75% 百菌清可湿性粉剂 600 倍液，核心成分百菌清与病原菌细胞酶结合，搅乱其代谢流程，广谱抵御病害侵袭。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002822', 'source-doc-4c784a84a66adf221597', 'source-node-002809', '6', '2821', 'text', '熏烟防治：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002823', 'source-doc-4c784a84a66adf221597', 'source-node-002822', '7', '2822', 'text', '处于保护地栽培场景且环境密闭时，可启用熏烟处置，如霜霉威、百菌清等烟雾剂，按每亩 350 克用量规范操作，借烟雾弥漫均匀覆盖，高效触杀病原菌，强化防治成效，尤适用于病害初现或局部发生阶段。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002824', 'source-doc-4c784a84a66adf221597', 'source-node-002800', '5', '2823', 'text', '生物防治措施：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002825', 'source-doc-4c784a84a66adf221597', 'source-node-002824', '6', '2824', 'text', '拮抗微生物利用：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002826', 'source-doc-4c784a84a66adf221597', 'source-node-002825', '7', '2825', 'text', '发病伊始，可调配 2% 武夷菌素水剂 200 倍液开展喷雾防治，凭借其中有益微生物拮抗机制，抑制白粉病病原菌生长繁衍，按 7 天间隔规律施药，持续作业 2～3 次，以温和、环保手段 “制衡” 病害。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002827', 'source-doc-4c784a84a66adf221597', 'source-node-002824', '6', '2826', 'text', '植物源杀菌剂应用：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002828', 'source-doc-4c784a84a66adf221597', 'source-node-002827', '7', '2827', 'text', '在苗期精准喷施碧护 3 克 + 碧欧 30 克，借助植物源制剂营养调节与抑菌功效，稳固幼苗生长态势、强化抗性，间隔 20 天再次喷施，防范秧苗徒长同时，赋予植株抵御白粉病 “底气”，为辣椒健康生长全程 “护航”。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002829', 'source-doc-4c784a84a66adf221597', 'source-node-002744', '3', '2828', 'text', '灰霉病（Botrytis cinerea）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002830', 'source-doc-4c784a84a66adf221597', 'source-node-002829', '4', '2829', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002831', 'source-doc-4c784a84a66adf221597', 'source-node-002830', '5', '2830', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002832', 'source-doc-4c784a84a66adf221597', 'source-node-002829', '4', '2831', 'text', '发病规律：病原菌以菌核在土壤中或病残体上越冬，在 20 - 23℃、相对湿度 90% 以上，菌核萌发产生分生孢子，通过气流、雨水、农事操作等传播到植株上，从伤口、衰弱或死亡组织侵入，花期侵染风险高。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002833', 'source-doc-4c784a84a66adf221597', 'source-node-002829', '4', '2832', 'text', '预防方法：加强通风透光，降低田间湿度，合理浇水，避免大水漫灌，及时摘除病花、病果、病叶，带出田外深埋或烧毁。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002834', 'source-doc-4c784a84a66adf221597', 'source-node-002829', '4', '2833', 'text', '防治方法：花期，可选用 40% 嘧霉胺悬浮剂 800 - 1000 倍液、50% 异菌脲可湿性粉剂 1000 - 1500 倍液等喷雾，重点喷花和幼果，每隔 7 - 10 天喷 1 次，连续喷 2 - 3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002835', 'source-doc-4c784a84a66adf221597', 'source-node-002744', '3', '2834', 'text', '疫病（Phytophthora capsici）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002836', 'source-doc-4c784a84a66adf221597', 'source-node-002835', '4', '2835', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002837', 'source-doc-4c784a84a66adf221597', 'source-node-002836', '5', '2836', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002838', 'source-doc-4c784a84a66adf221597', 'source-node-002835', '4', '2837', 'text', '发病规律：病原菌以卵孢子或厚垣孢子在病残体或土壤中越冬，在 28 - 30℃、相对湿度 90% 以上，卵孢子萌发产生游动孢子，借助雨水、灌溉水等传播到植株上，从气孔、伤口或表皮直接侵入，种植过密、地势低洼、排水不畅发病重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002839', 'source-doc-4c784a84a66adf221597', 'source-node-002835', '4', '2838', 'text', '预防方法：选用抗病品种，实行轮作，合理密植，改善通风透光，及时清除病残体。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002840', 'source-doc-4c784a84a66adf221597', 'source-node-002839', '5', '2839', 'text', '遇到高温多雨：雨前用170 克 / 升氟噻・嘧菌酯（傲蜜）30 - 50ml / 亩或68% 精甲霜・锰锌（金雷）100 - 120g / 亩喷雾；雨后立即补喷30% 氟吗啉（傲朗达）30 - 40ml / 亩，重点喷淋茎基部和叶片背面，连续 2 次（间隔 5 - 7 天）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002841', 'source-doc-4c784a84a66adf221597', 'source-node-002835', '4', '2840', 'text', '防治方法：发病初期，可选用 64% 杀毒矾可湿性粉剂 500 倍液、72.2% 普力克水剂 800 倍液等喷雾，7 - 10 天 1 次，连喷 2 - 3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002842', 'source-doc-4c784a84a66adf221597', 'source-node-002841', '5', '2841', 'text', '土壤处理：定植前结合深耕细作，一方面可撒施生石灰调节土壤酸碱度，抑制部分病原菌；另一方面，喷洒新高脂膜 800 倍液，形成保护膜，隔绝土壤中残留病菌与植株根系接触，降低侵染几率。同时，像前文提及的用杀毒矾、甲霜灵可湿性粉剂等拌土撒施或灌穴处理，也能高效净化土壤。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002843', 'source-doc-4c784a84a66adf221597', 'source-node-002841', '5', '2842', 'text', '灌根处理：采用 58% 精甲霜・锰锌可湿性粉剂 600 倍液灌根操作，精甲霜灵的内吸杀菌与锰锌的保护助力，精准 “围剿” 根部周围病原菌，强化植株根系防护，提升整体防效。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002844', 'source-doc-4c784a84a66adf221597', 'source-node-002841', '5', '2843', 'text', '生物防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002845', 'source-doc-4c784a84a66adf221597', 'source-node-002844', '6', '2844', 'text', '借助多粘类芽孢杆菌制剂等生物制剂开展防控。多粘类芽孢杆菌在定殖于辣椒根际等区域后，能够产生多种抗菌物质，如多肽类、多糖类等，这些物质有的可破坏病原菌细胞膜，有的干扰其代谢进程，以此 “制衡” 疫病病原菌，实现绿色、长效防治目标。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002846', 'source-doc-4c784a84a66adf221597', 'source-node-002841', '5', '2845', 'text', '药剂喷雾防治：抓住发病初期 “黄金节点” 火速开展喷药作业，以 7 - 10 天为间隔周期，连贯喷施 2 - 3 次。可按需选用以下高效药剂：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002847', 'source-doc-4c784a84a66adf221597', 'source-node-002846', '6', '2846', 'text', '68% 精甲霜・锰锌（精甲霜灵 + 锰锌）可湿性粉剂 600 - 800 倍液：精甲霜灵作为内吸性杀菌剂，对卵菌纲病害特效，主攻病原菌菌丝生长与侵染；锰锌成分发挥保护功效，协同构筑防护与治疗 “双重防线”。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002848', 'source-doc-4c784a84a66adf221597', 'source-node-002846', '6', '2847', 'text', '77% 硫酸铜钙可湿性粉剂 500 倍液：硫酸铜钙兼具铜离子杀菌毒性与钙元素对植株生长辅助作用，铜离子可破坏病原菌细胞结构、酶活性，抑制疫病病菌繁衍。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002849', 'source-doc-4c784a84a66adf221597', 'source-node-002846', '6', '2848', 'text', '25% 甲霜灵可湿性粉剂 600 倍液：甲霜灵专克卵菌纲病原菌，内吸传导至植株各部位，干扰病菌 RNA 合成，遏制疫病发展。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002850', 'source-doc-4c784a84a66adf221597', 'source-node-002846', '6', '2849', 'text', '77% 氢氧化铜可湿性粉剂 600 倍液加 70% 甲基硫菌灵可湿性粉剂 1000 倍液：氢氧化铜靠铜离子杀菌，破坏病菌细胞蛋白；甲基硫菌灵干扰病原菌细胞分裂，抑制菌丝生长，二者 “强强联合”，拓宽杀菌谱、增强防治效能。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002851', 'source-doc-4c784a84a66adf221597', 'source-node-002846', '6', '2850', 'text', '25% 嘧菌酯悬浮剂 1000 倍液：嘧菌酯属甲氧基丙烯酸酯类，靶向病菌呼吸链，阻断能量代谢，集保护、治疗、铲除功效于一体，防控疫病效果突出。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002852', 'source-doc-4c784a84a66adf221597', 'source-node-002846', '6', '2851', 'text', '3% 中生菌素可湿性粉剂 800 倍液：中生菌素作为农用抗生素，凭借抑制病原菌蛋白质合成等机制，抑菌杀菌，且环境友好，契合绿色防控理念。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002853', 'source-doc-4c784a84a66adf221597', 'source-node-002846', '6', '2852', 'text', '70% 丙森锌可湿性粉剂 600 倍液：丙森锌在植株表面 “编织” 防护 “网膜”，阻挡病菌侵入，是优良的保护性杀菌剂，防患于未然。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002854', 'source-doc-4c784a84a66adf221597', 'source-node-002846', '6', '2853', 'text', '25% 烯肟菌酯乳油 900 倍液：烯肟菌酯作用于病菌线粒体呼吸链，干扰能量代谢，抑制菌丝生长与孢子萌发，有力抗击疫病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002855', 'source-doc-4c784a84a66adf221597', 'source-node-002846', '6', '2854', 'text', '50% 烯酰吗啉可湿性粉剂 2000 倍液（用于浸种 3 小时）：烯酰吗啉特异性针对卵菌纲，阻碍病菌孢子囊形成与游动孢子释放，浸种可提前为种子 “穿上防护衣”，抵御病原菌侵染。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002856', 'source-doc-4c784a84a66adf221597', 'source-node-002846', '6', '2855', 'text', '20% 氟吗啉可湿性粉剂 1000 倍液（用于浸种 3 小时）：氟吗啉同样聚焦卵菌纲，抑制病菌细胞壁合成，浸种阶段保障种子健康，降低苗期染病风险。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002857', 'source-doc-4c784a84a66adf221597', 'source-node-002846', '6', '2856', 'text', '69% 烯酰・锰锌可湿性粉剂（用于苗床土壤消毒）：烯酰成分抗击疫病病菌，锰锌强化保护，用于苗床消毒，净化土壤环境，筑牢种苗 “安全岛”。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002858', 'source-doc-4c784a84a66adf221597', 'source-node-002846', '6', '2857', 'text', '52.5%啞酮·霜脲氰，对霜霉病、疫病、早疫病、晚疫病均有效', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002859', 'source-doc-4c784a84a66adf221597', 'source-node-002744', '3', '2858', 'text', '根腐病（Fusarium solani）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002860', 'source-doc-4c784a84a66adf221597', 'source-node-002859', '4', '2859', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002861', 'source-doc-4c784a84a66adf221597', 'source-node-002860', '5', '2860', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002862', 'source-doc-4c784a84a66adf221597', 'source-node-002859', '4', '2861', 'text', '根腐分为三种：腐霉根腐、疫霉根腐、镰刀根腐三种', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002863', 'source-doc-4c784a84a66adf221597', 'source-node-002862', '5', '2862', 'text', '其中镰刀根腐引起根系褐变，病原是腐皮镰孢 [Fusarium solani （Mart. ） App. et Wollenw]，属半知菌门真菌', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002864', 'source-doc-4c784a84a66adf221597', 'source-node-002859', '4', '2863', 'text', '发病规律：病原菌在土壤中存活，随流水、农事操作等传播，从根部伤口侵入，土壤黏重、排水不良、连作地块，在 25 - 30℃易发病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002865', 'source-doc-4c784a84a66adf221597', 'source-node-002859', '4', '2864', 'text', '预防方法：与非茄科蔬菜轮作，改良土壤，增施有机肥和生物菌肥，高垄栽培，利于排水。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002866', 'source-doc-4c784a84a66adf221597', 'source-node-002859', '4', '2865', 'text', '防治方法：发病初期，用 50% 多菌灵可湿性粉剂 500 倍液灌根，每株灌药液 200 - 300 毫升，或用甲霜灵・锰锌可湿性粉剂 600 - 800 倍液灌根。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002867', 'source-doc-4c784a84a66adf221597', 'source-node-002866', '5', '2866', 'text', '轮作换茬：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002868', 'source-doc-4c784a84a66adf221597', 'source-node-002867', '6', '2867', 'text', '极力避免与瓜类、茄果类蔬菜连作，积极提倡与十字花科、豆科等蔬菜开展轮作安排。鉴于根腐病病原菌易在土壤中长期存活、积累，轮作能有效打破其生存循环，稀释病原菌 “浓度”，降低发病风险。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002869', 'source-doc-4c784a84a66adf221597', 'source-node-002866', '5', '2868', 'text', '加强田间管理：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002870', 'source-doc-4c784a84a66adf221597', 'source-node-002869', '6', '2869', 'text', '践行配方施肥策略，施足腐熟有机肥，筑牢土壤肥力根基。把控氮肥用量，防止偏施 “催长” 氮肥致植株虚胖、抗性下滑，适当增施磷钾肥，强化植株 “筋骨”。苗期稳施氮肥 “助长”，开花结果期侧重追施磷钾肥，并适时补充叶面肥，保障植株营养均衡、茁壮抵御病害。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002871', 'source-doc-4c784a84a66adf221597', 'source-node-002866', '5', '2870', 'text', '化学防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002872', 'source-doc-4c784a84a66adf221597', 'source-node-002871', '6', '2871', 'text', '种子处理：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002873', 'source-doc-4c784a84a66adf221597', 'source-node-002872', '7', '2872', 'text', '播种前借助 “三步曲” 净化种子。先是温汤浸种，将水温调至 55 - 60℃，浸泡 15 分钟，给种子来场 “热浴杀菌”；接着用 10% 磷酸三钠浸种 30 分钟，深度 “消杀” 种表病菌；再用 72.2% 普力克水剂（霜霉威盐酸盐） 600 - 800 倍液浸种 12 小时，多管齐下，洗净催芽播种，最大程度剔除种表病菌及病毒 “隐患”。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002874', 'source-doc-4c784a84a66adf221597', 'source-node-002871', '6', '2873', 'text', '苗床与土壤处理：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002875', 'source-doc-4c784a84a66adf221597', 'source-node-002874', '7', '2874', 'text', '育苗前精心筹备 “净土” 苗床，优先选用 2 年未种过茄果类的大田土或葱蒜地土，按每平方米 10 克用量撒施 120 抗菌剂或多菌灵开展消毒作业，播种时讲究药土 “上下呵护”，即下铺、上盖。亦或每平方米用 5% 丙烯酸・恶霉・甲霜灵水剂 2 - 3 毫升稀释至 1000 - 1500 倍喷洒苗床，密织 “防护网”，严防幼苗 “带病上岗”。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002876', 'source-doc-4c784a84a66adf221597', 'source-node-002871', '6', '2875', 'text', '药剂防治：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002877', 'source-doc-4c784a84a66adf221597', 'source-node-002876', '7', '2876', 'text', '秉持 “预防为先” 理念，带药定植。一旦发现中心病株，果断拔除，火速启动 “喷施、灌根、熏蒸” 组合拳。可选用 50% 瑞毒铜 （有效成分主要是甲霜灵与琥胶肥酸铜复配，甲霜灵针对卵菌纲，琥胶肥酸铜有广谱杀菌特性）1000 倍液或绿乳铜 800 - 1000 倍液喷雾防控；也能用 50% 甲霜铜 500 倍液、64% 瑞毒铝铜 250 倍液开展防治作业，每 7 - 10 天施药 1 次，连施 2 - 3 次。同时，优先考虑烟熏法（用 45% 百菌清烟雾剂 250 - 300 克 / 亩）或粉尘法（5% 百菌清粉尘剂 1 千克 / 亩），7 天左右操作 1 次，持续 2 - 3 次，借烟雾、粉尘弥漫全方位 “围剿” 病菌。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002878', 'source-doc-4c784a84a66adf221597', 'source-node-002871', '6', '2877', 'text', '灌根预防：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002879', 'source-doc-4c784a84a66adf221597', 'source-node-002878', '7', '2878', 'text', '辣椒定植后，瞅准坐果前时机 “主动出击” 预防病害。选阳光满溢的晴天上午，将硫酸铜晶体或 120 抗菌剂按每亩 1 - 2 千克用量随水浇灌，若添入活性生根剂，恰似 “如虎添翼”，强化根系活力与防病能力。把控水量，不超垄高 2/3，浇灌后及时通风换气，谨防叶部病害 “趁乱作祟”。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002880', 'source-doc-4c784a84a66adf221597', 'source-node-002866', '5', '2879', 'text', '生物防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002881', 'source-doc-4c784a84a66adf221597', 'source-node-002880', '6', '2880', 'text', '善用多粘类芽孢杆菌制剂等生物制剂，这类有益微生物入驻土壤或根际周边后，宛如 “微观卫士”，凭借自身代谢产出多种抗菌物质，有的能 “破壁” 病原菌细胞，有的干扰其代谢路径，多维度制衡辣椒根腐病病原菌，践行绿色、长效防治之道。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002882', 'source-doc-4c784a84a66adf221597', 'source-node-002744', '3', '2881', 'text', '菌核病（Sclerotinia sclerotiorum）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002883', 'source-doc-4c784a84a66adf221597', 'source-node-002882', '4', '2882', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002884', 'source-doc-4c784a84a66adf221597', 'source-node-002883', '5', '2883', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002885', 'source-doc-4c784a84a66adf221597', 'source-node-002882', '4', '2884', 'text', '发病规律：菌核在土壤或病残体越冬，15 - 20℃、湿度大时，菌核萌发产生子囊盘和子囊孢子，借气流、雨水传播，从衰弱组织或伤口侵入。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002886', 'source-doc-4c784a84a66adf221597', 'source-node-002882', '4', '2885', 'text', '预防方法：深翻土壤，使菌核埋深，轮作倒茬，及时清除病残体，保持田间清洁。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002887', 'source-doc-4c784a84a66adf221597', 'source-node-002886', '5', '2886', 'text', '土壤消毒', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002888', 'source-doc-4c784a84a66adf221597', 'source-node-002887', '6', '2887', 'text', '在种植前，对土壤进行消毒处理。可以使用 40% 五氯硝基苯粉剂与福美双可湿性粉剂按照 1:1 混合，每平方米用药 8 - 10 克，拌细土撒施；或者用 70% 甲基硫菌灵可湿性粉剂或 50% 多菌灵可湿性粉剂，每平方米 8 - 10 克，与细土混合后撒施，能有效减少土壤中的菌核数量。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002889', 'source-doc-4c784a84a66adf221597', 'source-node-002886', '5', '2888', 'text', '药剂喷雾防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002890', 'source-doc-4c784a84a66adf221597', 'source-node-002889', '6', '2889', 'text', '在发病初期，可选用以下药剂进行喷雾防治，每隔 7 - 10 天喷 1 次，连续喷 2 - 3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002891', 'source-doc-4c784a84a66adf221597', 'source-node-002889', '6', '2890', 'text', '40% 菌核净可湿性粉剂 1000 - 1500 倍液：菌核净主要成分是 N - （3,5 - 二氯苯基）丁二酰亚胺，它能干扰病原菌的细胞分裂和呼吸作用，抑制菌核的萌发和菌丝生长。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002892', 'source-doc-4c784a84a66adf221597', 'source-node-002889', '6', '2891', 'text', '50% 异菌脲可湿性粉剂 1000 - 1500 倍液：异菌脲的主要成分是 3 - （3,5 - 二氯苯基） - 1 - 异丙基氨基甲酰基乙内酰脲，可抑制病原菌的蛋白激酶，阻止病菌孢子萌发和菌丝生长。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002893', 'source-doc-4c784a84a66adf221597', 'source-node-002889', '6', '2892', 'text', '50% 腐霉利可湿性粉剂 1000 - 1500 倍液：腐霉利主要成分是 N - （3,5 - 二氯苯基） - 1,2 - 二甲基环丙烷 - 1,2 - 二甲酰亚胺，通过抑制病原菌的有丝分裂，对菌核病有良好的防治效果。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002894', 'source-doc-4c784a84a66adf221597', 'source-node-002889', '6', '2893', 'text', '25% 啶菌恶唑乳油 1000 - 1500 倍液：啶菌恶唑主要成分是啶菌恶唑，它能抑制病原菌的甾醇合成，破坏细胞膜结构，从而达到杀菌的目的。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002895', 'source-doc-4c784a84a66adf221597', 'source-node-002889', '6', '2894', 'text', '70% 甲基硫菌灵可湿性粉剂 800 - 1000 倍液：甲基硫菌灵主要成分是甲基 - 2 - 苯并咪唑氨基甲酸酯，干扰病原菌的细胞分裂，抑制菌丝生长。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002896', 'source-doc-4c784a84a66adf221597', 'source-node-002889', '6', '2895', 'text', '50% 多菌灵可湿性粉剂 600 - 800 倍液：多菌灵主要成分是苯并咪唑类化合物，能抑制病原菌的细胞分裂和生长，具有内吸性，可被植株吸收传导。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002897', 'source-doc-4c784a84a66adf221597', 'source-node-002886', '5', '2896', 'text', '烟雾剂防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002898', 'source-doc-4c784a84a66adf221597', 'source-node-002897', '6', '2897', 'text', '在保护地栽培中，可选用 10% 腐霉利烟剂或 15% 菌核净烟剂、异丙威烟剂，每亩用量 250 - 300 克，进行熏烟防治。这些烟雾剂在保护地密闭环境中释放有效成分，能均匀地分布在空间内，通过抑制病原菌的生长和繁殖来防治菌核病，同时减少喷雾带来的湿度增加问题。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002899', 'source-doc-4c784a84a66adf221597', 'source-node-002886', '5', '2898', 'text', '生物防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002900', 'source-doc-4c784a84a66adf221597', 'source-node-002899', '6', '2899', 'text', '植物源药剂防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002901', 'source-doc-4c784a84a66adf221597', 'source-node-002900', '7', '2900', 'text', '有些植物源药剂如大蒜素，从大蒜中提取。将大蒜素制剂按照推荐浓度稀释后进行喷雾，它可以破坏病原菌的细胞膜等结构，干扰其生理功能，对菌核病有一定的防治作用，并且对环境友好，不易使病原菌产生抗药性。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002902', 'source-doc-4c784a84a66adf221597', 'source-node-002899', '6', '2901', 'text', '微生物制剂应用', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002903', 'source-doc-4c784a84a66adf221597', 'source-node-002902', '7', '2902', 'text', '利用木霉菌（Trichoderma spp.）制剂进行防治。木霉菌能在土壤和植株表面定殖，与菌核病菌竞争营养和空间，并且可以分泌几丁质酶等抗菌物质分解病原菌的细胞壁，从而抑制菌核病的发生。按照产品说明将木霉菌制剂施用于土壤或植株表面。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002904', 'source-doc-4c784a84a66adf221597', 'source-node-002882', '4', '2903', 'text', '防治方法：发病初期，可选用 40% 菌核净可湿性粉剂 1000 - 1500 倍液、50% 腐霉利可湿性粉剂 1000 - 1500 倍液喷雾或灌根。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002905', 'source-doc-4c784a84a66adf221597', 'source-node-002744', '3', '2904', 'text', '辣椒枯萎病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002906', 'source-doc-4c784a84a66adf221597', 'source-node-002905', '4', '2905', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002907', 'source-doc-4c784a84a66adf221597', 'source-node-002906', '5', '2906', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002908', 'source-doc-4c784a84a66adf221597', 'source-node-002905', '4', '2907', 'text', '发病规律：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002909', 'source-doc-4c784a84a66adf221597', 'source-node-002908', '5', '2908', 'text', '病原菌为尖孢镰刀菌（Fusarium oxysporum f. sp. capsici），主要以厚垣孢子在土壤中或病残体上越冬，能在土壤中存活多年。翌年环境条件适宜时，厚垣孢子萌发产生菌丝体和分生孢子，从辣椒植株的根部伤口或根尖侵入，通过根部的维管束向上蔓延扩展。在土温 24 - 28℃、土壤湿度较大的情况下，病原菌生长繁殖迅速。连作地、地势低洼、排水不良、土壤偏酸、线虫为害严重等因素会导致辣椒植株生长势弱，增加枯萎病的发病几率。另外，病原菌还可通过灌溉水、农事操作工具等传播，在辣椒的开花结果期发病较重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002910', 'source-doc-4c784a84a66adf221597', 'source-node-002905', '4', '2909', 'text', '预防方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002911', 'source-doc-4c784a84a66adf221597', 'source-node-002910', '5', '2910', 'text', '轮作倒茬：实行 3 - 5 年的轮作，避免与茄科蔬菜连作，可与十字花科、豆科等作物轮作，减少土壤中病原菌的积累。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002912', 'source-doc-4c784a84a66adf221597', 'source-node-002910', '5', '2911', 'text', '土壤改良：调节土壤酸碱度，在酸性土壤中适量施用石灰，使土壤 pH 值保持在 7 - 7.5 左右。增施有机肥和生物菌肥，改善土壤结构和微生物群落，提高土壤的保水保肥能力和透气性。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002913', 'source-doc-4c784a84a66adf221597', 'source-node-002910', '5', '2912', 'text', '种子和苗床处理：选用无病种子，必要时进行种子消毒，如用 0.1% 硫酸铜溶液浸种 5 分钟，或 50% 多菌灵可湿性粉剂 500 倍液浸种 1 小时，然后用清水冲洗干净后播种。对苗床进行消毒，可用福尔马林或多菌灵等药剂处理土壤。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002914', 'source-doc-4c784a84a66adf221597', 'source-node-002910', '5', '2913', 'text', '栽培管理：采用高畦栽培，合理灌溉，避免大水漫灌，雨后及时排水。及时清除病残体，减少病原菌传播。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002915', 'source-doc-4c784a84a66adf221597', 'source-node-002905', '4', '2914', 'text', '防治方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002916', 'source-doc-4c784a84a66adf221597', 'source-node-002915', '5', '2915', 'text', '药剂灌根：在发病初期，可选用 50% 多菌灵可湿性粉剂 500 倍液、10% 双效灵水剂 200 - 300 倍液、40% 瓜枯宁可湿性粉剂 800 - 1000 倍液等药剂进行灌根，每株灌药液 200 - 300 毫升，每隔 7 - 10 天灌 1 次，连续灌 2 - 3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002917', 'source-doc-4c784a84a66adf221597', 'source-node-002915', '5', '2916', 'text', '生物防治：利用一些有益微生物来抑制病原菌的生长，如木霉菌、芽孢杆菌等生物制剂，按照产品说明进行土壤处理或灌根，可在一定程度上减轻枯萎病的发生。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002918', 'source-doc-4c784a84a66adf221597', 'source-node-002744', '3', '2917', 'text', '辣椒白绢病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002919', 'source-doc-4c784a84a66adf221597', 'source-node-002918', '4', '2918', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002920', 'source-doc-4c784a84a66adf221597', 'source-node-002919', '5', '2919', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002921', 'source-doc-4c784a84a66adf221597', 'source-node-002918', '4', '2920', 'text', '一、发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002922', 'source-doc-4c784a84a66adf221597', 'source-node-002921', '5', '2921', 'text', '发病条件', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002923', 'source-doc-4c784a84a66adf221597', 'source-node-002922', '6', '2922', 'text', '温度在 25 - 35℃、土壤湿度较大（相对湿度 85% 以上）且土壤呈酸性（pH 值 5 - 7）时，有利于病原菌的生长和繁殖。连作地、地势低洼、排水不良、田间郁闭通风透光差的辣椒田发病较重。此外，偏施氮肥，导致植株生长过旺、组织柔嫩，也会增加植株的感病性。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002924', 'source-doc-4c784a84a66adf221597', 'source-node-002921', '5', '2923', 'text', '病原菌存活与传播', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002925', 'source-doc-4c784a84a66adf221597', 'source-node-002924', '6', '2924', 'text', '辣椒白绢病病原菌是齐整小核菌（Sclerotium rolfsii），主要以菌核在土壤中或病残体上越冬。菌核在适宜的环境条件下可存活多年，是次年发病的主要初侵染源。菌核可以通过雨水冲刷、灌溉水流动、农事操作时的农具和人员携带等方式在田间传播。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002926', 'source-doc-4c784a84a66adf221597', 'source-node-002918', '4', '2925', 'text', '二、预防方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002927', 'source-doc-4c784a84a66adf221597', 'source-node-002926', '5', '2926', 'text', '品种选择', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002928', 'source-doc-4c784a84a66adf221597', 'source-node-002927', '6', '2927', 'text', '选用对白绢病抗性较强的辣椒品种。在种植前，可以参考当地的种植经验和品种抗性试验结果来挑选品种。一些具有发达根系和较厚叶片角质层的品种可能具有更好的抗性。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002929', 'source-doc-4c784a84a66adf221597', 'source-node-002926', '5', '2928', 'text', '栽培管理', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002930', 'source-doc-4c784a84a66adf221597', 'source-node-002929', '6', '2929', 'text', '采用高畦栽培，畦高 20 - 30 厘米，便于排水，降低田间湿度。合理密植，根据辣椒品种特性，保持适当的株行距，保证植株间通风透光良好。避免偏施氮肥，注重增施磷、钾肥，如磷酸二氢钾等，增强植株的抗病能力。及时清除田间杂草和病残体，收获后要彻底清理田园，将病残株带出田外深埋或烧毁。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002931', 'source-doc-4c784a84a66adf221597', 'source-node-002926', '5', '2930', 'text', '土壤改良', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002932', 'source-doc-4c784a84a66adf221597', 'source-node-002931', '6', '2931', 'text', '对于酸性土壤，可适量施用石灰调节土壤酸碱度，使土壤 pH 值保持在 7 - 7.5。增施有机肥和生物菌肥，如腐熟的农家肥、堆肥以及含有芽孢杆菌等有益微生物的生物菌肥，改善土壤结构，增加土壤通气性和保水保肥能力，抑制病原菌的生长。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002933', 'source-doc-4c784a84a66adf221597', 'source-node-002926', '5', '2932', 'text', '轮作倒茬', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002934', 'source-doc-4c784a84a66adf221597', 'source-node-002933', '6', '2933', 'text', '实行与非茄科作物（如禾本科、豆科植物等）轮作，轮作周期 3 - 4 年。例如与玉米、大豆等作物轮作，可有效减少土壤中病原菌的积累，打破病原菌的生存周期。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002935', 'source-doc-4c784a84a66adf221597', 'source-node-002918', '4', '2934', 'text', '三、防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002936', 'source-doc-4c784a84a66adf221597', 'source-node-002935', '5', '2935', 'text', '土壤消毒', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002937', 'source-doc-4c784a84a66adf221597', 'source-node-002936', '6', '2936', 'text', '在种植前，对土壤进行消毒处理。可以用 50% 多菌灵可湿性粉剂或 70% 甲基硫菌灵可湿性粉剂，每平方米 8 - 10 克，与细土混合后撒施，然后翻耕入土；也可以使用 40% 五氯硝基苯粉剂与福美双可湿性粉剂按照 1:1 混合，每平方米用药 8 - 10 克，拌细土撒施，能有效杀灭土壤中的病原菌。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002938', 'source-doc-4c784a84a66adf221597', 'source-node-002935', '5', '2937', 'text', '药剂喷雾防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002939', 'source-doc-4c784a84a66adf221597', 'source-node-002938', '6', '2938', 'text', '在发病初期，可选用以下药剂进行喷雾防治，每隔 7 - 10 天喷 1 次，连续喷 2 - 3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002940', 'source-doc-4c784a84a66adf221597', 'source-node-002938', '6', '2939', 'text', '20% 三唑酮乳油 1000 - 1500 倍液：主要成分三唑酮是一种高效、低毒、低残留的杀菌剂，能抑制病原菌的麦角甾醇合成，从而破坏病原菌的细胞膜结构，抑制其生长。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002941', 'source-doc-4c784a84a66adf221597', 'source-node-002938', '6', '2940', 'text', '50% 苯菌灵可湿性粉剂 1000 - 1500 倍液：苯菌灵主要成分是苯并咪唑类化合物，能干扰病原菌的细胞分裂和生长，具有内吸性，可被植株吸收传导，抑制菌丝生长。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002942', 'source-doc-4c784a84a66adf221597', 'source-node-002938', '6', '2941', 'text', '50% 多菌灵可湿性粉剂 600 - 800 倍液：主要成分多菌灵是一种广谱杀菌剂，通过抑制病原菌的细胞分裂和生长来发挥杀菌作用，对辣椒白绢病有较好的防治效果。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002943', 'source-doc-4c784a84a66adf221597', 'source-node-002938', '6', '2942', 'text', '70% 甲基硫菌灵可湿性粉剂 800 - 1000 倍液：甲基硫菌灵主要成分是甲基 - 2 - 苯并咪唑氨基甲酸酯，干扰病原菌的细胞分裂，抑制菌丝生长，可有效防治白绢病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002944', 'source-doc-4c784a84a66adf221597', 'source-node-002938', '6', '2943', 'text', '43% 戊唑醇悬浮剂 2000 - 3000 倍液：戊唑醇主要成分戊唑醇是一种三唑类杀菌剂，能抑制病原菌的麦角甾醇合成，影响细胞膜的完整性，从而达到杀菌的目的。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002945', 'source-doc-4c784a84a66adf221597', 'source-node-002935', '5', '2944', 'text', '灌根防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002946', 'source-doc-4c784a84a66adf221597', 'source-node-002945', '6', '2945', 'text', '发病较重时，可采用药剂灌根。用 50% 甲基立枯磷乳油 1000 - 1500 倍液或 40% 五氯硝基苯粉剂 500 - 800 倍液灌根，每株灌药液 200 - 300 毫升，每隔 7 - 10 天灌 1 次，连续灌 2 - 3 次。甲基立枯磷主要成分甲基立枯磷能抑制病原菌的生长，五氯硝基苯主要成分五氯硝基苯对病原菌有较强的毒杀作用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002947', 'source-doc-4c784a84a66adf221597', 'source-node-002935', '5', '2946', 'text', '生物防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002948', 'source-doc-4c784a84a66adf221597', 'source-node-002947', '6', '2947', 'text', '拮抗微生物利用：利用有益微生物如哈茨木霉菌（Trichoderma harzianum）来防治白绢病。哈茨木霉菌可以在土壤和植株根部定殖，与病原菌竞争营养和空间，并且能够分泌几丁质酶等抗菌物质分解病原菌的细胞壁。按照产品说明将哈茨木霉菌制剂施用于土壤或灌根，可在一定程度上减轻病害。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002949', 'source-doc-4c784a84a66adf221597', 'source-node-002947', '6', '2948', 'text', '植物源杀菌剂应用：使用植物源杀菌剂，如印楝素。印楝素是从印楝树中提取的天然生物活性物质，按照推荐浓度稀释后进行喷雾或灌根，它可以干扰病原菌的生理功能，对辣椒白绢病有一定的防治作用，并且对环境友好，不易使病原菌产生抗药性。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002950', 'source-doc-4c784a84a66adf221597', 'source-node-002744', '3', '2949', 'text', '猝倒病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002951', 'source-doc-4c784a84a66adf221597', 'source-node-002950', '4', '2950', 'text', '猝倒病 / 立枯病：用68% 恶霉灵・代森锰锌可湿性粉剂 500 倍液或10 亿 CFU / 克多粘类芽孢杆菌可湿性粉剂 800 倍液灌根 + 喷雾，重点保护茎基，每 7 天 1 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002952', 'source-doc-4c784a84a66adf221597', 'source-node-002719', '2', '2951', 'text', '生理病害：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002953', 'source-doc-4c784a84a66adf221597', 'source-node-002952', '3', '2952', 'text', '生理性沤根：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002954', 'source-doc-4c784a84a66adf221597', 'source-node-002953', '4', '2953', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002955', 'source-doc-4c784a84a66adf221597', 'source-node-002954', '5', '2954', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002956', 'source-doc-4c784a84a66adf221597', 'source-node-002953', '4', '2955', 'text', '发病规律：多因土壤湿度过大、透气性差，地温过低（低于 12℃），根系长期处于缺氧、低温环境，呼吸受抑制，导致根系变褐腐烂，植株生长不良。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002957', 'source-doc-4c784a84a66adf221597', 'source-node-002953', '4', '2956', 'text', '预防方法：选择地势高、排水好的地块，改良土壤结构，增施有机肥，提高土壤透气性，合理浇水，避免积水，保持适宜地温（15 - 20℃）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002958', 'source-doc-4c784a84a66adf221597', 'source-node-002953', '4', '2957', 'text', '防治方法：发生后及时中耕松土，排水降湿，提高地温，可撒施草木灰等吸湿增温物质，促进根系恢复。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002959', 'source-doc-4c784a84a66adf221597', 'source-node-002952', '3', '2958', 'text', '日灼病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002960', 'source-doc-4c784a84a66adf221597', 'source-node-002959', '4', '2959', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002961', 'source-doc-4c784a84a66adf221597', 'source-node-002960', '5', '2960', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002962', 'source-doc-4c784a84a66adf221597', 'source-node-002959', '4', '2961', 'text', '症状表现', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002963', 'source-doc-4c784a84a66adf221597', 'source-node-002962', '5', '2962', 'text', '主要发生在果实上。在果实向阳面出现褪绿、变白的病斑，病斑形状不规则，后期病斑会变为淡黄色或灰白色，组织坏死，质地变硬。严重时，病斑会扩展至半个果实以上，甚至整个果实干枯。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002964', 'source-doc-4c784a84a66adf221597', 'source-node-002959', '4', '2963', 'text', '发病原因', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002965', 'source-doc-4c784a84a66adf221597', 'source-node-002964', '5', '2964', 'text', '强光直射和高温是主要原因。在夏季高温强光时期，辣椒果实没有叶片等遮挡，长时间暴露在阳光下，果实表面温度过高，导致局部组织灼伤。另外，土壤缺水、植株生长势弱也会加重日灼病的发生。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002966', 'source-doc-4c784a84a66adf221597', 'source-node-002959', '4', '2965', 'text', '防治措施', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002967', 'source-doc-4c784a84a66adf221597', 'source-node-002966', '5', '2966', 'text', '合理密植与整枝：通过合理密植，保证植株间有良好的枝叶覆盖，避免果实直接暴露在阳光下。同时，合理进行整枝打杈，保留足够的叶片为果实遮阳，但要注意避免枝叶过密影响通风透光。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002968', 'source-doc-4c784a84a66adf221597', 'source-node-002966', '5', '2967', 'text', '调节土壤水分：保持土壤湿润，避免在高温强光时土壤过度干旱。适时浇水，可采用滴灌或小水勤浇的方式，保证植株水分供应，提高植株抗逆性。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002969', 'source-doc-4c784a84a66adf221597', 'source-node-002966', '5', '2968', 'text', '覆盖遮阳网：在夏季高温强光时期，可在辣椒种植区域上方覆盖遮阳网，降低光照强度和温度，减少日灼病的发生。遮阳网的覆盖时间要根据天气情况灵活掌握，一般在晴天上午 10 点至下午 4 点覆盖即可。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002970', 'source-doc-4c784a84a66adf221597', 'source-node-002952', '3', '2969', 'text', '脐腐病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002971', 'source-doc-4c784a84a66adf221597', 'source-node-002970', '4', '2970', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002972', 'source-doc-4c784a84a66adf221597', 'source-node-002971', '5', '2971', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002973', 'source-doc-4c784a84a66adf221597', 'source-node-002970', '4', '2972', 'text', '症状表现', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002974', 'source-doc-4c784a84a66adf221597', 'source-node-002973', '5', '2973', 'text', '主要危害果实。发病初期，果实脐部（花器残余部分）出现暗绿色水渍状斑点，随后病斑逐渐扩大，颜色变为深褐色或黑色，病部组织凹陷、干缩，呈革质状。湿度大时，病斑上可能会出现黑色或红色霉层。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002975', 'source-doc-4c784a84a66adf221597', 'source-node-002970', '4', '2974', 'text', '发病原因', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002976', 'source-doc-4c784a84a66adf221597', 'source-node-002975', '5', '2975', 'text', '主要是由于缺钙引起的。土壤中钙素不足，或者植株吸收钙的过程受到阻碍，如土壤干旱、氮肥施用过多等情况，都会导致植株缺钙。另外，高温、干旱等环境因素也会影响植株对钙的吸收和运输。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002977', 'source-doc-4c784a84a66adf221597', 'source-node-002970', '4', '2976', 'text', '防治措施', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002978', 'source-doc-4c784a84a66adf221597', 'source-node-002977', '5', '2977', 'text', '土壤改良：检测土壤酸碱度，对于酸性土壤，可适量施用石灰等钙肥，提高土壤 pH 值，增加土壤中钙的有效性。同时，增施有机肥，改善土壤结构，提高土壤保水保肥能力，促进植株对钙的吸收。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002979', 'source-doc-4c784a84a66adf221597', 'source-node-002977', '5', '2978', 'text', '合理施肥：避免偏施氮肥，注意氮、磷、钾及微量元素的平衡施肥。在结果期，适量增施钙肥，如硝酸钙、氯化钙等，可采用叶面喷施或根部追施的方式。叶面喷施时，一般用 0.3% - 0.5% 的硝酸钙溶液，每隔 7 - 10 天喷一次，连喷 2 - 3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002980', 'source-doc-4c784a84a66adf221597', 'source-node-002977', '5', '2979', 'text', '水分管理：保持土壤湿润，避免土壤忽干忽湿。干旱时及时浇水，浇水要均匀，防止土壤干旱影响植株对钙的吸收。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002981', 'source-doc-4c784a84a66adf221597', 'source-node-002952', '3', '2980', 'text', '畸形果', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002982', 'source-doc-4c784a84a66adf221597', 'source-node-002981', '4', '2981', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002983', 'source-doc-4c784a84a66adf221597', 'source-node-002982', '5', '2982', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002984', 'source-doc-4c784a84a66adf221597', 'source-node-002981', '4', '2983', 'text', '症状表现', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002985', 'source-doc-4c784a84a66adf221597', 'source-node-002984', '5', '2984', 'text', '果实形状不规则，常见的有扭曲果、扁果、多心果、僵果等。扭曲果表现为果实呈螺旋状或弯曲状；扁果的果实横径明显大于纵径；多心果是指果实内部有多个心室；僵果则是果实较小，质地硬，不膨大。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002986', 'source-doc-4c784a84a66adf221597', 'source-node-002981', '4', '2985', 'text', '发病原因', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002987', 'source-doc-4c784a84a66adf221597', 'source-node-002986', '5', '2986', 'text', '花芽分化不良：在花芽分化期，温度过高或过低、光照不足、营养失调等因素，会影响花芽分化的质量，导致形成畸形花芽，进而发育成畸形果。例如，夜间温度低于 15℃或高于 20℃，都可能对花芽分化产生不利影响。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002988', 'source-doc-4c784a84a66adf221597', 'source-node-002986', '5', '2987', 'text', '授粉受精不良：在开花授粉期，遇到不良天气，如低温、高温、干旱、暴雨等，会影响花粉的活力和授粉受精过程，导致果实发育异常。另外，缺乏硼等微量元素也会影响花粉的萌发和花粉管的伸长，引起授粉受精不良。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002989', 'source-doc-4c784a84a66adf221597', 'source-node-002986', '5', '2988', 'text', '生长调节剂使用不当：如果在辣椒生长过程中，使用生长调节剂的浓度过高或时间不当，也会导致果实畸形。例如，使用生长素类调节剂促进坐果时，浓度过高会使果实发育异常。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002990', 'source-doc-4c784a84a66adf221597', 'source-node-002981', '4', '2989', 'text', '防治措施', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002991', 'source-doc-4c784a84a66adf221597', 'source-node-002990', '5', '2990', 'text', '优化花芽分化环境：在花芽分化期，控制好温度和光照条件。白天温度保持在 20 - 25℃，夜间温度控制在 15 - 18℃，保证充足的光照时间和强度，促进花芽分化正常进行。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002992', 'source-doc-4c784a84a66adf221597', 'source-node-002990', '5', '2991', 'text', '加强授粉管理：在花期，可通过放养蜜蜂等昆虫辅助授粉，提高授粉受精率。遇到不良天气时，可适当进行人工授粉。同时，注意补充硼肥等微量元素，在开花前可喷施 0.1% - 0.2% 的硼砂溶液，提高花粉质量。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002993', 'source-doc-4c784a84a66adf221597', 'source-node-002990', '5', '2992', 'text', '正确使用生长调节剂：严格按照说明书使用生长调节剂，掌握好使用浓度、时间和方法。在使用前，最好先进行小面积试验，确定合适的使用剂量和方法后再大面积应用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002994', 'source-doc-4c784a84a66adf221597', 'source-node-002952', '3', '2993', 'text', '落花落果', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002995', 'source-doc-4c784a84a66adf221597', 'source-node-002994', '4', '2994', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002996', 'source-doc-4c784a84a66adf221597', 'source-node-002995', '5', '2995', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002997', 'source-doc-4c784a84a66adf221597', 'source-node-002994', '4', '2996', 'text', '症状表现', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002998', 'source-doc-4c784a84a66adf221597', 'source-node-002997', '5', '2997', 'text', '辣椒在开花结果期，花朵或幼果大量脱落。落花主要表现为花朵在开放后不久就枯萎脱落，落果则是幼果长到一定大小后脱落，严重影响辣椒的产量。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-002999', 'source-doc-4c784a84a66adf221597', 'source-node-002994', '4', '2998', 'text', '发病原因', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003000', 'source-doc-4c784a84a66adf221597', 'source-node-002999', '5', '2999', 'text', '温度不适：辣椒花期对温度较为敏感。温度过高（高于 35℃）或过低（低于 15℃）都会影响花粉的活力和花芽的正常发育，导致落花落果。例如，在高温环境下，花粉会迅速失去活力，无法完成授粉受精过程。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003001', 'source-doc-4c784a84a66adf221597', 'source-node-002999', '5', '3000', 'text', '光照不足：辣椒是喜光植物，在生长过程中需要充足的光照。如果种植密度过大、枝叶过密或者遇到连续的阴雨天，光照不足，会影响光合作用，导致植株营养供应不足，引起落花落果。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003002', 'source-doc-4c784a84a66adf221597', 'source-node-002999', '5', '3001', 'text', '水分失调：土壤干旱或积水都会导致落花落果。干旱时，植株缺水，会使花朵和幼果因缺水而脱落；积水会影响根系的呼吸和吸收功能，导致植株生长不良，也会引起落花落果。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003003', 'source-doc-4c784a84a66adf221597', 'source-node-002999', '5', '3002', 'text', '营养不足或失调：在辣椒生长过程中，如果缺乏氮、磷、钾等大量元素或硼、锌等微量元素，或者施肥比例不当，会影响植株的生长和生殖发育，导致落花落果。例如，氮肥不足会使植株生长瘦弱，磷肥不足会影响花芽分化，硼肥不足会影响授粉受精。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003004', 'source-doc-4c784a84a66adf221597', 'source-node-002994', '4', '3003', 'text', '防治措施', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003005', 'source-doc-4c784a84a66adf221597', 'source-node-003004', '5', '3004', 'text', '温度调控：在花期，通过设施栽培的温度调控设备，如遮阳网、通风设备、保温设施等，将温度控制在适宜的范围内，白天温度保持在 20 - 28℃，夜间温度控制在 15 - 20℃。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003006', 'source-doc-4c784a84a66adf221597', 'source-node-003004', '5', '3005', 'text', '光照管理：合理密植，保证植株间有良好的通风透光条件。及时进行整枝打杈，去除过密的枝叶。在遇到阴雨天时，可采用人工补光的方式，增加光照时间和强度。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003007', 'source-doc-4c784a84a66adf221597', 'source-node-003004', '5', '3006', 'text', '水分管理：保持土壤湿润，采用科学的浇水方法，如滴灌、小水勤浇等。避免土壤干旱或积水，在雨季要及时排水，防止田间积水。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003008', 'source-doc-4c784a84a66adf221597', 'source-node-003004', '5', '3007', 'text', '合理施肥：根据辣椒的生长阶段和土壤肥力状况，合理施肥。基肥要施足有机肥和磷、钾肥，追肥要注意氮、磷、钾及微量元素的平衡。在花期和结果期，可适当增施磷、钾肥和硼、锌等微量元素肥料，促进花芽分化和果实发育。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003009', 'source-doc-4c784a84a66adf221597', 'source-node-002952', '3', '3008', 'text', '缺素症', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003010', 'source-doc-4c784a84a66adf221597', 'source-node-003009', '4', '3009', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003011', 'source-doc-4c784a84a66adf221597', 'source-node-003010', '5', '3010', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003012', 'source-doc-4c784a84a66adf221597', 'source-node-003009', '4', '3011', 'text', '症状表现及原因', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003013', 'source-doc-4c784a84a66adf221597', 'source-node-003012', '5', '3012', 'text', '缺氮：植株生长缓慢，叶片淡绿色或黄绿色，叶片变小，薄而软。严重缺氮时，叶片发黄脱落，植株矮小。主要是因为土壤中氮素不足，或者施肥不当，如基肥中氮肥不足、追肥不及时等。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003014', 'source-doc-4c784a84a66adf221597', 'source-node-003013', '6', '3013', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003015', 'source-doc-4c784a84a66adf221597', 'source-node-003012', '5', '3014', 'text', '缺磷：植株矮小，叶片深绿色，无光泽，有时叶片出现紫红色斑点或条纹。磷在植物体内的移动性较强，缺磷会影响植株的能量代谢和光合作用。土壤中有效磷含量低、低温等因素会影响植株对磷的吸收。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003016', 'source-doc-4c784a84a66adf221597', 'source-node-003015', '6', '3015', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003017', 'source-doc-4c784a84a66adf221597', 'source-node-003012', '5', '3016', 'text', '缺镁：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003018', 'source-doc-4c784a84a66adf221597', 'source-node-003017', '6', '3017', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003019', 'source-doc-4c784a84a66adf221597', 'source-node-003012', '5', '3018', 'text', '缺铁：新叶发黄，叶脉仍为绿色，叶片呈典型的 “黄化” 现象。铁是植物体内叶绿素合成所必需的元素，土壤碱性过强、土壤中有效铁含量低等情况会导致植株缺铁。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003020', 'source-doc-4c784a84a66adf221597', 'source-node-003019', '6', '3019', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003021', 'source-doc-4c784a84a66adf221597', 'source-node-003012', '5', '3020', 'text', '缺硼：植株生长点受抑制，顶部新叶皱缩、变形，叶脉间出现不规则的褪绿斑。硼对植物的生殖生长有重要作用，土壤中硼素不足、干旱等因素会影响植株对硼的吸收，导致缺硼。果实基部木栓化', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003022', 'source-doc-4c784a84a66adf221597', 'source-node-003021', '6', '3021', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003023', 'source-doc-4c784a84a66adf221597', 'source-node-003012', '5', '3022', 'text', '缺锌：叶片变小，节间缩短，植株矮化。新叶出现黄斑，叶脉绿色，叶边缘向上卷曲。锌参与植物体内生长素的合成，土壤中锌含量低、土壤 pH 值过高或过低等因素会导致植株缺锌。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003024', 'source-doc-4c784a84a66adf221597', 'source-node-003023', '6', '3023', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003025', 'source-doc-4c784a84a66adf221597', 'source-node-003009', '4', '3024', 'text', '防治措施', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003026', 'source-doc-4c784a84a66adf221597', 'source-node-003025', '5', '3025', 'text', '土壤检测与施肥调整：定期对土壤进行检测，了解土壤中各种营养元素的含量。根据检测结果，合理调整施肥方案，补充缺乏的营养元素。例如，对于缺氮的土壤，可适量增施氮肥，如尿素、碳酸氢铵等；对于缺磷的土壤，可施用过磷酸钙等磷肥。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003027', 'source-doc-4c784a84a66adf221597', 'source-node-003025', '5', '3026', 'text', '叶面喷施：在发现植株出现缺素症状时，可采用叶面喷施的方式快速补充营养元素。如缺铁时，可用 0.1% - 0.2% 的硫酸亚铁溶液叶面喷施；缺硼时，用 0.1% - 0.2% 的硼砂溶液叶面喷施；缺锌时，用 0.1% - 0.2% 的硫酸锌溶液叶面喷施。叶面喷施的时间最好选择在晴天的傍晚，以提高叶片的吸收效率。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003028', 'source-doc-4c784a84a66adf221597', 'source-node-002719', '2', '3027', 'text', '虫害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003029', 'source-doc-4c784a84a66adf221597', 'source-node-003028', '3', '3028', 'text', '烟青虫：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003030', 'source-doc-4c784a84a66adf221597', 'source-node-003029', '4', '3029', 'text', '发病规律：以蛹在土壤中越冬，成虫昼伏夜出，趋化性，将卵产在辣椒叶片、嫩茎、花蕾和果实上，幼虫孵化后蛀食果实，在 25 - 28℃、相对湿度 70% 左右繁殖快，7 - 9 月为害重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003031', 'source-doc-4c784a84a66adf221597', 'source-node-003029', '4', '3030', 'text', '预防方法：及时清除田间杂草和残株，减少栖息场所，采用糖醋液诱捕成虫（糖：醋：酒：水 = 3:4:1:2）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003032', 'source-doc-4c784a84a66adf221597', 'source-node-003029', '4', '3031', 'text', '防治方法：幼虫初孵期，可选用苏云金芽孢杆菌（Bt）制剂、1.8% 阿维菌素乳油 1000 - 1500 倍液等喷雾。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003033', 'source-doc-4c784a84a66adf221597', 'source-node-003028', '3', '3032', 'text', '棉铃虫：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003034', 'source-doc-4c784a84a66adf221597', 'source-node-003033', '4', '3033', 'text', '发病规律：以蛹在土壤中越冬，成虫趋光性强，夜间活动，产卵于嫩叶、花蕾、果实等部位，幼虫先取食嫩叶后蛀食果实，在温度 25 - 28℃、相对湿度 70% 左右繁殖迅速，为害严重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003035', 'source-doc-4c784a84a66adf221597', 'source-node-003033', '4', '3034', 'text', '预防方法：利用黑光灯诱捕成虫，清理田园周边杂草等隐蔽场所。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003036', 'source-doc-4c784a84a66adf221597', 'source-node-003033', '4', '3035', 'text', '防治方法：幼虫孵化盛期，可选用 2.5% 溴氰菊酯乳油 2000 - 3000 倍液、5% 高效氯氟氰菊酯乳油 1500 - 2000 倍液等喷雾。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003037', 'source-doc-4c784a84a66adf221597', 'source-node-003028', '3', '3036', 'text', '蚜虫：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003038', 'source-doc-4c784a84a66adf221597', 'source-node-003037', '4', '3037', 'text', '发病规律：在适宜温度（16 - 22℃）和湿度下繁殖力强，以卵在花椒、木槿等寄主植物上越冬，春季孵化后迁飞到辣椒上，聚集在叶片背面、嫩茎、花蕾吸食汁液。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003039', 'source-doc-4c784a84a66adf221597', 'source-node-003037', '4', '3038', 'text', '预防方法：在田间悬挂黄色粘虫板诱杀有翅蚜，保护利用瓢虫、草蛉等天敌。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003040', 'source-doc-4c784a84a66adf221597', 'source-node-003037', '4', '3039', 'text', '防治方法：可选用 10% 吡虫啉可湿性粉剂 1500 - 2000 倍液、50% 抗蚜威可湿性粉剂 2000 - 3000 倍液等喷雾。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003041', 'source-doc-4c784a84a66adf221597', 'source-node-003040', '5', '3040', 'text', '（一）农业防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003042', 'source-doc-4c784a84a66adf221597', 'source-node-003041', '6', '3041', 'text', '清洁田园', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003043', 'source-doc-4c784a84a66adf221597', 'source-node-003042', '7', '3042', 'text', '及时清除田间及周边杂草、残株和病叶，减少蚜虫的栖息地和繁殖场所。辣椒收获后，彻底清理田园，破坏蚜虫的生存环境。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003044', 'source-doc-4c784a84a66adf221597', 'source-node-003041', '6', '3043', 'text', '合理布局', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003045', 'source-doc-4c784a84a66adf221597', 'source-node-003044', '7', '3044', 'text', '辣椒种植地应与十字花科等蚜虫易聚集的作物保持一定距离，避免蚜虫的迁移和传播。在田间规划时，可考虑间作或轮作一些对蚜虫有驱避作用的植物。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003046', 'source-doc-4c784a84a66adf221597', 'source-node-003040', '5', '3045', 'text', '（二）物理防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003047', 'source-doc-4c784a84a66adf221597', 'source-node-003046', '6', '3046', 'text', '防虫网覆盖', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003048', 'source-doc-4c784a84a66adf221597', 'source-node-003047', '7', '3047', 'text', '在辣椒种植区域覆盖防虫网，网目以40 - 60目为宜。防虫网能有效阻止蚜虫进入田间，减少虫源。在育苗期和定植初期使用防虫网，效果更佳。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003049', 'source-doc-4c784a84a66adf221597', 'source-node-003046', '6', '3048', 'text', '色板诱捕', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003050', 'source-doc-4c784a84a66adf221597', 'source-node-003049', '7', '3049', 'text', '悬挂黄色粘虫板诱捕蚜虫。黄色对蚜虫有很强的吸引力，每亩可悬挂20 - 30块，悬挂高度以粘虫板底部高出植株顶部10 - 20厘米为宜。定期更换粘虫板，保证诱捕效果。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003051', 'source-doc-4c784a84a66adf221597', 'source-node-003040', '5', '3050', 'text', '（三）生物防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003052', 'source-doc-4c784a84a66adf221597', 'source-node-003051', '6', '3051', 'text', '释放天敌', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003053', 'source-doc-4c784a84a66adf221597', 'source-node-003052', '7', '3052', 'text', '释放瓢虫、草蛉、食蚜蝇等蚜虫天敌。例如，每平方米释放1 - 2头七星瓢虫成虫或幼虫，这些天敌可以捕食蚜虫，有效控制蚜虫种群数量。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003054', 'source-doc-4c784a84a66adf221597', 'source-node-003051', '6', '3053', 'text', '使用生物制剂', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003055', 'source-doc-4c784a84a66adf221597', 'source-node-003054', '7', '3054', 'text', '喷施植物源杀虫剂，如鱼藤酮、苦参碱等。鱼藤酮主要成分是鱼藤酮类化合物，能抑制蚜虫的呼吸作用；苦参碱主要成分是苦参碱和氧化苦参碱，对蚜虫有触杀和胃毒作用。使用时按照产品说明进行稀释喷雾。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003056', 'source-doc-4c784a84a66adf221597', 'source-node-003040', '5', '3055', 'text', '（四）化学防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003057', 'source-doc-4c784a84a66adf221597', 'source-node-003056', '6', '3056', 'text', '药剂喷雾', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003058', 'source-doc-4c784a84a66adf221597', 'source-node-003057', '7', '3057', 'text', '选用10%吡虫啉可湿性粉剂1000 - 1500倍液（主要成分吡虫啉是烟碱类杀虫剂，作用于蚜虫的神经系统）、3%啶虫脒乳油1000 - 1500倍液（啶虫脒主要成分是啶虫脒，通过与蚜虫乙酰胆碱受体结合发挥作用）、50%抗蚜威可湿性粉剂2000 - 3000倍液（抗蚜威主要成分是抗蚜威，抑制蚜虫的胆碱酯酶活性）进行喷雾。重点喷施蚜虫聚集的叶片背面和嫩梢。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003059', 'source-doc-4c784a84a66adf221597', 'source-node-003028', '3', '3058', 'text', '白粉虱：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003060', 'source-doc-4c784a84a66adf221597', 'source-node-003059', '4', '3059', 'text', '发病规律：温室可周年发生，露地在杂草等寄主越冬，成虫趋黄性、趋嫩性，在叶片背面吸食，分泌蜜露引发煤污病，温暖干燥利于繁殖，春秋季为害重。在适宜的环境条件下（温度 20 - 28℃、相对湿度 70% 左右），从卵发育到成虫仅需 19 - 27 天。雌虫一次可产卵 100 - 200 粒，卵多产于叶片背面，呈不规则的散产', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003061', 'source-doc-4c784a84a66adf221597', 'source-node-003059', '4', '3060', 'text', '预防方法：悬挂黄色粘虫板，保护释放丽蚜小蜂等天敌。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003062', 'source-doc-4c784a84a66adf221597', 'source-node-003061', '5', '3061', 'text', '农业防治：合理轮作或间作非茄科蔬菜，收获后清洁田园、清除杂草残株，育苗时用防虫网防成虫飞入、消毒基质育无虫苗。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003063', 'source-doc-4c784a84a66adf221597', 'source-node-003061', '5', '3062', 'text', '物理防治：覆盖 40 - 60 目防虫网与银灰色地膜，悬挂黄色粘虫板（每亩 30 - 40 块，底部高出植株顶部 10 - 20 厘米）诱捕成虫。网目一般为 40 - 60 目，可有效阻止白粉虱进入田间', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003064', 'source-doc-4c784a84a66adf221597', 'source-node-003061', '5', '3063', 'text', '生物防治：释放丽蚜小蜂（每株 2 - 3 头，7 - 10 天释放一次，连放 3 - 4 次）、中华草蛉幼虫（每亩 1 - 2 头）；使用印楝素、除虫菊酯等按说明稀释喷雾。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003065', 'source-doc-4c784a84a66adf221597', 'source-node-003061', '5', '3064', 'text', '化学防治：初期用 25% 噻虫嗪水分散粒剂 2000 - 3000 倍液、10% 烯啶虫胺水剂 1000 - 1500 倍液喷雾，严重时选 40% 啶虫・毒死蜱（在蔬菜、果树、茶叶、中草药材上不得使用）乳油 1000 - 1500 倍液，喷雾重喷叶背与植株中下部，轮换用药并遵说明施药。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003066', 'source-doc-4c784a84a66adf221597', 'source-node-003059', '4', '3065', 'text', '防治方法：可选用 25% 噻虫嗪水分散粒剂 3000 - 5000 倍液、10% 烯啶虫胺水剂 1000 - 1500 倍液等喷雾。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003067', 'source-doc-4c784a84a66adf221597', 'source-node-003028', '3', '3066', 'text', '茶黄螨：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003068', 'source-doc-4c784a84a66adf221597', 'source-node-003067', '4', '3067', 'text', '发病规律：雌成螨在避风场所越冬，在 16 - 23℃、湿度适宜时，于嫩叶、嫩茎、花和果实吸食，受害叶片变厚变小，背面呈茶褐色。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003069', 'source-doc-4c784a84a66adf221597', 'source-node-003067', '4', '3068', 'text', '预防方法：清除田间杂草和残株，减少虫源。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003070', 'source-doc-4c784a84a66adf221597', 'source-node-003067', '4', '3069', 'text', '防治方法：发生初期，可选用 73% 克螨特乳油 1000 - 1500 倍液、10% 浏阳霉素乳油 1000 - 1500 倍液等喷雾，重点喷植株上部。联苯肼酯', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003071', 'source-doc-4c784a84a66adf221597', 'source-node-003070', '5', '3070', 'text', '农业防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003072', 'source-doc-4c784a84a66adf221597', 'source-node-003071', '6', '3071', 'text', '田园清洁：辣椒采收完毕，残株、落叶、杂草即刻清理，集中焚毁或深埋，断其 “越冬后路”、减虫源基数。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003073', 'source-doc-4c784a84a66adf221597', 'source-node-003071', '6', '3072', 'text', '合理轮作：规避连作 “陷阱”，与十字花科、豆科等非茄科蔬菜轮作，压制种群繁衍。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003074', 'source-doc-4c784a84a66adf221597', 'source-node-003071', '6', '3073', 'text', '精细管理：有机肥打底，磷、钾肥适量添补，控氮肥防徒长，植株健壮抗螨；整枝打杈及时，通风透光良好，不给茶黄螨 “藏身之所”。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003075', 'source-doc-4c784a84a66adf221597', 'source-node-003070', '5', '3074', 'text', '物理防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003076', 'source-doc-4c784a84a66adf221597', 'source-node-003075', '6', '3075', 'text', '高温闷棚：温室大棚种植前，选晴天正午密闭棚室，升温至 50 - 60℃并维持 2 - 3 小时，“一锅端” 螨虫全家。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003077', 'source-doc-4c784a84a66adf221597', 'source-node-003075', '6', '3076', 'text', '地膜覆盖：铺地膜阻螨于土壤外，稳温保湿促辣椒生长。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003078', 'source-doc-4c784a84a66adf221597', 'source-node-003070', '5', '3077', 'text', '生物防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003079', 'source-doc-4c784a84a66adf221597', 'source-node-003078', '6', '3078', 'text', '以螨治螨：投放智利小植绥螨，每平方米 10 - 20 头，趁螨害初起 “出击”，精准捕食。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003080', 'source-doc-4c784a84a66adf221597', 'source-node-003078', '6', '3079', 'text', '生物药剂：印楝素按说明稀释喷雾，凭其活性成分干扰螨生理活动，抑制为害。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003081', 'source-doc-4c784a84a66adf221597', 'source-node-003070', '5', '3080', 'text', '化学防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003082', 'source-doc-4c784a84a66adf221597', 'source-node-003081', '6', '3081', 'text', '药剂精选：1.8% 阿维菌素乳油 1000 - 1500 倍液（干扰神经传导）、73% 克螨特乳油 2000 - 3000 倍液（触杀与胃毒兼具）、20% 哒螨灵可湿性粉剂 1000 - 1500 倍液（抑制线粒体呼吸）为常用 “利器”。爱卡螨（联苯肼酯）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003083', 'source-doc-4c784a84a66adf221597', 'source-node-003081', '6', '3082', 'text', '喷雾要点：瞄准嫩叶、嫩茎、花与幼果着重喷，喷雾均匀、无死角，确保药剂覆盖。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003084', 'source-doc-4c784a84a66adf221597', 'source-node-003081', '6', '3083', 'text', '注意事项：鉴于其繁殖快、易抗药，防治中轮换用药，严守剂量与安全间隔期规定。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003085', 'source-doc-4c784a84a66adf221597', 'source-node-003028', '3', '3084', 'text', '蓟马：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003086', 'source-doc-4c784a84a66adf221597', 'source-node-003085', '4', '3085', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003087', 'source-doc-4c784a84a66adf221597', 'source-node-003086', '5', '3086', 'text', '生活习性：蓟马体型微小却极为活跃，喜隐匿于辣椒叶片背面、花器内、幼果萼片下等隐蔽处，且具趋蓝、趋嫩习性，晴天多在上午 9 点前与下午 4 点后频繁活动，阴天、傍晚全天活跃，稍受惊扰便迅速逃窜藏匿。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003088', 'source-doc-4c784a84a66adf221597', 'source-node-003086', '5', '3087', 'text', '发生规律：成虫或若虫在叶片、花、果实吸食，以成虫在杂草、土缝越冬，趋蓝性，温暖干燥繁殖快，受害叶片有白斑，花和果实品质受影响。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003089', 'source-doc-4c784a84a66adf221597', 'source-node-003086', '5', '3088', 'text', '繁殖特性：繁殖力惊人，在适宜温度（25 - 30℃）、湿度（相对湿度 40% - 70%）条件下，从卵至成虫仅需 14 - 18 天，雌虫可行孤雌生殖，产卵量多，卵多产于植株幼嫩组织表皮下、叶脉间等细微处。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003090', 'source-doc-4c784a84a66adf221597', 'source-node-003085', '4', '3089', 'text', '预防方法：悬挂蓝色粘虫板，释放小花蝽等天敌。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003091', 'source-doc-4c784a84a66adf221597', 'source-node-003085', '4', '3090', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003092', 'source-doc-4c784a84a66adf221597', 'source-node-003091', '5', '3091', 'text', '农业防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003093', 'source-doc-4c784a84a66adf221597', 'source-node-003092', '6', '3092', 'text', '田园清理：辣椒收获后，即刻清除田间残株、杂草、落叶，集中深埋或烧毁，破坏蓟马越冬、越夏栖息与繁殖场所，减少虫源基数。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003094', 'source-doc-4c784a84a66adf221597', 'source-node-003092', '6', '3093', 'text', '合理轮作：避免连作，与十字花科、豆科等非茄科作物轮作，打乱蓟马生活周期，抑制种群繁衍。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003095', 'source-doc-4c784a84a66adf221597', 'source-node-003092', '6', '3094', 'text', '科学管理：增施有机肥、磷钾肥，控氮肥防植株徒长，促使辣椒植株生长健壮、组织坚实，增强抗虫能力；合理密植，保证通风透光良好，降低田间湿度，营造不适宜蓟马生存环境。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003096', 'source-doc-4c784a84a66adf221597', 'source-node-003091', '5', '3095', 'text', '物理防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003097', 'source-doc-4c784a84a66adf221597', 'source-node-003096', '6', '3096', 'text', '蓝色粘板诱捕：利用蓟马趋蓝特性，田间每亩悬挂 30 - 40 块蓝色粘虫板，板高于辣椒植株顶部或持平，定期清理、更换粘板，确保诱捕效果。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003098', 'source-doc-4c784a84a66adf221597', 'source-node-003096', '6', '3097', 'text', '防虫网隔离：育苗及定植期，在辣椒田覆盖 40 - 60 目防虫网，阻挡蓟马侵入，在设施栽培中防护效果尤佳。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003099', 'source-doc-4c784a84a66adf221597', 'source-node-003091', '5', '3098', 'text', '生物防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003100', 'source-doc-4c784a84a66adf221597', 'source-node-003099', '6', '3099', 'text', '天敌制衡：释放捕食螨（如胡瓜钝绥螨，每平方米 10 - 20 头）、小花蝽（每亩 500 - 1000 头）等天敌昆虫，于蓟马发生初期投放，借天敌捕食控制蓟马数量。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003101', 'source-doc-4c784a84a66adf221597', 'source-node-003099', '6', '3100', 'text', '生物药剂：选用球孢白僵菌、绿僵菌等微生物制剂，按产品说明稀释喷雾，借助真菌寄生蓟马，致其染病死亡，绿色环保且防效持久。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003102', 'source-doc-4c784a84a66adf221597', 'source-node-003091', '5', '3101', 'text', '化学防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003103', 'source-doc-4c784a84a66adf221597', 'source-node-003102', '6', '3102', 'text', '药剂选择：可选用 2.5% 多杀霉素悬浮剂 1000 - 1500 倍液（作用于蓟马神经系统，麻痹致死）、10% 溴虫氟苯双酰胺悬浮剂 1000 - 1500 倍液（干扰蓟马肌肉收缩功能）、6% 乙基多杀菌素悬浮剂 1000 - 1500 倍液（刺激蓟马神经细胞致麻痹）、10% 吡虫啉可湿性粉剂 1500 - 2000 倍液等喷雾，重点喷花和幼果等。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003104', 'source-doc-4c784a84a66adf221597', 'source-node-003102', '6', '3103', 'text', '施药要点：选在蓟马活动高峰期（清晨或傍晚）施药，加助剂，重点喷施花朵、幼果、新梢等蓟马聚集部位，确保药剂覆盖均匀、细致，喷雾压力适中，以免蓟马受惊逃脱。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003105', 'source-doc-4c784a84a66adf221597', 'source-node-003102', '6', '3104', 'text', '轮换用药：为防蓟马产生抗药性，不同作用机制药剂交替使用，且严格遵循药剂安全间隔期，保障辣椒质量安全与防治效果。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003106', 'source-doc-4c784a84a66adf221597', 'source-node-002719', '2', '3105', 'text', '辣椒番茄病毒', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003107', 'source-doc-4c784a84a66adf221597', 'source-node-003106', '3', '3106', 'text', '病毒病（黄瓜花叶病毒、烟草花叶病毒等多种）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003108', 'source-doc-4c784a84a66adf221597', 'source-node-003107', '4', '3107', 'text', '病原类型', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003109', 'source-doc-4c784a84a66adf221597', 'source-node-003108', '5', '3108', 'text', '黄瓜花叶病毒（CMV）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003110', 'source-doc-4c784a84a66adf221597', 'source-node-003109', '6', '3109', 'text', '病毒粒体呈球状，寄主范围广泛，能侵染包括辣椒在内的众多蔬菜、花卉等植物。该病毒主要依赖蚜虫以非持久性方式传播，蚜虫在染病植株上短时间取食后，即可携带病毒并迅速传播至健康植株，病毒在寄主体内增殖迅速，可致使辣椒出现花叶、畸形等症状，新叶常黄绿斑驳、皱缩卷曲，植株生长受抑，果实发育不良、变小且品质变差。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003111', 'source-doc-4c784a84a66adf221597', 'source-node-003109', '6', '3110', 'text', '症状表现：多在植株顶部新叶发病，叶片出现深绿和浅绿相间的斑驳，叶片变小、变窄，呈蕨叶状，边缘卷曲。植株矮化，分枝增多，开花结果减少，果实小且僵硬，表面有瘤状突起。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003112', 'source-doc-4c784a84a66adf221597', 'source-node-003109', '6', '3111', 'text', '识别要点：蕨叶状叶片是显著特征，新叶症状尤为明显。病毒可通过蚜虫等刺吸式口器害虫传播，田间有蚜虫活动且植株出现上述症状时，应重点考虑黄瓜花叶病毒。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003113', 'source-doc-4c784a84a66adf221597', 'source-node-003109', '6', '3112', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003114', 'source-doc-4c784a84a66adf221597', 'source-node-003113', '7', '3113', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003115', 'source-doc-4c784a84a66adf221597', 'source-node-003108', '5', '3114', 'text', '烟草花叶病毒（TMV）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003116', 'source-doc-4c784a84a66adf221597', 'source-node-003115', '6', '3115', 'text', '病毒粒体为杆状，是稳定性强、存活能力出众的病毒。传播多通过汁液接触途径，像农事操作里的整枝打杈、植株间摩擦碰撞等，不经意间就能让病毒从病株沾染到健康株。受其侵染的辣椒，初期叶片呈现深浅绿相间花叶，之后可能发展为疱斑，严重时叶片呈线状或蕨叶状，植株生长点受阻，茎蔓扭曲、节间缩短，果实表面凹凸且有瘤状突起，商品价值严重受损。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003117', 'source-doc-4c784a84a66adf221597', 'source-node-003115', '6', '3116', 'text', '症状表现：感染初期，番茄叶片上出现明脉现象，即叶脉颜色变浅、透明度增加，如同被水浸泡。随着病情发展，叶片逐渐出现黄绿相间的斑驳，叶片皱缩、扭曲，严重时叶片变小、畸形，植株生长缓慢，节间缩短，呈丛生状。果实发病时，表面出现花斑，品质下降，失去商品价值。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003118', 'source-doc-4c784a84a66adf221597', 'source-node-003115', '6', '3117', 'text', '识别要点：明脉是其早期典型症状，黄绿斑驳较为规则，病叶质地变脆，与健康叶片对比，颜色差异明显。且在高温干旱条件下发病较重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003119', 'source-doc-4c784a84a66adf221597', 'source-node-003115', '6', '3118', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003120', 'source-doc-4c784a84a66adf221597', 'source-node-003119', '7', '3119', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003121', 'source-doc-4c784a84a66adf221597', 'source-node-003108', '5', '3120', 'text', '马铃薯 Y 病毒（PVY）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003122', 'source-doc-4c784a84a66adf221597', 'source-node-003121', '6', '3121', 'text', '病毒粒体呈线状，借助蚜虫传播，在茄科植物间 “横行”，对辣椒危害显著。感染后辣椒会出现花叶、坏死与畸形复合症状，先是叶片斑驳、花叶显现，后续叶与茎出现褐色坏死斑、条纹，坏死区域扩张致叶片枯萎、茎部坏死，植株上部萎蔫，果实也难逃厄运，表面产生坏死点，整体植株生长扭曲变形。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003123', 'source-doc-4c784a84a66adf221597', 'source-node-003121', '6', '3122', 'text', '症状表现：叶片上出现斑驳、花叶，叶脉坏死，形成褐色坏死条斑。茎部也会出现坏死条斑，严重时植株萎蔫、枯死。果实发病时，表面产生褐色坏死斑点，果肉组织坏死，影响果实品质和食用价值。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003124', 'source-doc-4c784a84a66adf221597', 'source-node-003121', '6', '3123', 'text', '识别要点：叶片和茎部的坏死条斑是关键识别特征，坏死条斑颜色较深，与健康组织界限清晰。在种植过马铃薯或周边有马铃薯种植的区域，番茄易受马铃薯Y病毒感染。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003125', 'source-doc-4c784a84a66adf221597', 'source-node-003121', '6', '3124', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003126', 'source-doc-4c784a84a66adf221597', 'source-node-003125', '7', '3125', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003127', 'source-doc-4c784a84a66adf221597', 'source-node-003108', '5', '3126', 'text', '番茄黄化曲叶病毒（TYLCV）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003128', 'source-doc-4c784a84a66adf221597', 'source-node-003127', '6', '3127', 'text', '症状表现：植株生长受阻，矮化明显。顶部叶片黄化、变小，叶片边缘上卷，严重时全株叶片黄化卷曲。下部老叶逐渐枯黄脱落，开花结果期延迟，坐果率低，果实发育不良，多为小果、僵果。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003129', 'source-doc-4c784a84a66adf221597', 'source-node-003127', '6', '3128', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003130', 'source-doc-4c784a84a66adf221597', 'source-node-003129', '7', '3129', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003131', 'source-doc-4c784a84a66adf221597', 'source-node-003127', '6', '3130', 'text', '识别要点：以叶片黄化曲叶和植株矮化为主要识别依据。该病毒由烟粉虱传播，在烟粉虱高发地区，番茄出现此类症状需警惕番茄黄化曲叶病毒。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003132', 'source-doc-4c784a84a66adf221597', 'source-node-003108', '5', '3131', 'text', '辣椒斑驳病毒（PepMoV）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003133', 'source-doc-4c784a84a66adf221597', 'source-node-003132', '6', '3132', 'text', '归属于马铃薯 Y 病毒属，同样仰仗蚜虫 “助力” 传播，在辣椒产区广泛分布。主要引发辣椒花叶与果实斑驳症状，叶片黄绿相间，果实外观斑驳杂乱，植株生长速率放缓，产量与品质皆受波及。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003134', 'source-doc-4c784a84a66adf221597', 'source-node-003132', '6', '3133', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003135', 'source-doc-4c784a84a66adf221597', 'source-node-003134', '7', '3134', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003136', 'source-doc-4c784a84a66adf221597', 'source-node-003108', '5', '3135', 'text', '条斑病毒（从症状分类）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003137', 'source-doc-4c784a84a66adf221597', 'source-node-003136', '6', '3136', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003138', 'source-doc-4c784a84a66adf221597', 'source-node-003108', '5', '3137', 'text', '班委病毒（从症状分类）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003139', 'source-doc-4c784a84a66adf221597', 'source-node-003138', '6', '3138', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003140', 'source-doc-4c784a84a66adf221597', 'source-node-003108', '5', '3139', 'text', '褐果皱纹病毒（从症状分类）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003141', 'source-doc-4c784a84a66adf221597', 'source-node-003140', '6', '3140', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003142', 'source-doc-4c784a84a66adf221597', 'source-node-003107', '4', '3141', 'text', '发病规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003143', 'source-doc-4c784a84a66adf221597', 'source-node-003142', '5', '3142', 'text', '发病条件：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003144', 'source-doc-4c784a84a66adf221597', 'source-node-003143', '6', '3143', 'text', '温度：20 - 30℃堪称病毒 “活跃温区”，此温度下病毒复制、侵染效率高，传毒昆虫活跃度、活动范围也随之增大，利于病害流行。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003145', 'source-doc-4c784a84a66adf221597', 'source-node-003143', '6', '3144', 'text', '湿度：高湿环境好似 “催化剂”，刺激蚜虫、粉虱大量滋生繁殖，它们在田间频繁穿梭、肆意传毒，大大增加辣椒染病几率。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003146', 'source-doc-4c784a84a66adf221597', 'source-node-003143', '6', '3145', 'text', '栽培管理：连作会使土壤里病毒逐年 “囤积”，种植密度过大造成田间郁闭，通风透光受阻、湿度 “爆表”，再加上田间管理粗放，像施肥失衡（氮肥过量、磷钾不足）、排水不畅积水、病残体清理拖沓等，致使植株抗性滑坡，极易被病毒 “乘虚而入”。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003147', 'source-doc-4c784a84a66adf221597', 'source-node-003142', '5', '3146', 'text', '传播途径：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003148', 'source-doc-4c784a84a66adf221597', 'source-node-003147', '6', '3147', 'text', '首要传播 “帮凶” 是蚜虫、粉虱、蓟马等刺吸式口器昆虫，它们在病株吸食带毒汁液后，转移至健康株继续取食，病毒借此跨株传播。虽说种子带毒比例不高，但仍存隐患，不可小觑种子这一潜在初侵染源。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003149', 'source-doc-4c784a84a66adf221597', 'source-node-003107', '4', '3148', 'text', '预防措施', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003150', 'source-doc-4c784a84a66adf221597', 'source-node-003149', '5', '3149', 'text', '种子处理：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003151', 'source-doc-4c784a84a66adf221597', 'source-node-003150', '6', '3150', 'text', '消毒：一是用 10% 磷酸三钠溶液浸种 20 - 30 分钟，磷酸三钠可促使病毒蛋白外壳变性失活，随后以清水洗净残留药剂；二是播前晒种 1 天，再用 55°C 温水浸种 20 分钟，凭借高温物理作用 “涤荡” 种子表面病毒，力保种子 “健康无虞”。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003152', 'source-doc-4c784a84a66adf221597', 'source-node-003150', '6', '3151', 'text', '拌种：按种子重量 0.3% 取用 50% 多菌灵可湿性粉剂拌种，在防控病毒之余，对其他病菌也有一定抵御功效，减轻种苗期病害压力。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003153', 'source-doc-4c784a84a66adf221597', 'source-node-003149', '5', '3152', 'text', '选用抗病品种：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003154', 'source-doc-4c784a84a66adf221597', 'source-node-003153', '6', '3153', 'text', '优先择取如长剑、迅驰、37 - 76、辽椒 18、辽椒 19、红英达、红罗丹、奥黛丽等经实践验证、对病毒病抗性卓越的辣椒品种，从种植根基处强化防病 “壁垒”。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003155', 'source-doc-4c784a84a66adf221597', 'source-node-003149', '5', '3154', 'text', '栽培管理：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003156', 'source-doc-4c784a84a66adf221597', 'source-node-003155', '6', '3155', 'text', '密度调控：依照辣椒品种特性，科学规划种植密度，保障田间通风透光优良，植株拥有适宜生长空间，抑制湿度攀升、病菌滋生。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003157', 'source-doc-4c784a84a66adf221597', 'source-node-003155', '6', '3156', 'text', '排水优化：完善田间排水体系，逢雨及时排水，杜绝积水引发根系缺氧、植株抗性衰败，不给病毒 “可乘之机”。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003158', 'source-doc-4c784a84a66adf221597', 'source-node-003155', '6', '3157', 'text', '合理轮作：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003159', 'source-doc-4c784a84a66adf221597', 'source-node-003158', '7', '3158', 'text', '坚决规避连作，与非茄科作物开展 3 年及以上轮作、间作，以此打破病毒在土壤里的 “盘踞” 格局，削减病毒源头与传播链路，降低发病风险。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003160', 'source-doc-4c784a84a66adf221597', 'source-node-003155', '6', '3159', 'text', '施肥平衡：以有机肥作为基肥 “主力军”，适度增施磷钾肥，筑牢植株 “抗病根基”、提升整体抗性，严控氮肥用量防止徒长，护航植株稳健生长。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003161', 'source-doc-4c784a84a66adf221597', 'source-node-003155', '6', '3160', 'text', '病残体清理：辣椒生长全程，见病株即刻拔除，带出田外妥善深埋；生产季收官之际，全面清田，销毁病残体，断了病毒 “越冬潜藏” 后路。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003162', 'source-doc-4c784a84a66adf221597', 'source-node-003107', '4', '3161', 'text', '化学防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003163', 'source-doc-4c784a84a66adf221597', 'source-node-003162', '5', '3162', 'text', '防治传毒昆虫：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003164', 'source-doc-4c784a84a66adf221597', 'source-node-003163', '6', '3163', 'text', '张挂 60 目防虫网，物理隔绝蚜虫、粉虱 “进犯”；合理布设黄篮板、蓝板，监测兼诱捕虫体；虫害汹涌时，选用化学药剂 “剿灭”，如 10% 吡虫啉可湿性粉剂 1000 - 1500 倍液（吡虫啉干扰昆虫神经系统致麻痹死亡）、3% 啶虫脒乳油 1000 - 1500 倍液（啶虫脒作用于昆虫乙酰胆碱受体令其麻痹）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003165', 'source-doc-4c784a84a66adf221597', 'source-node-003162', '5', '3164', 'text', '注意要点：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003166', 'source-doc-4c784a84a66adf221597', 'source-node-003165', '6', '3165', 'text', '交替用药：为规避抗药性 “滋生”，定期轮换不同作用机制药剂，稳固药效、保障防治长效性。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003167', 'source-doc-4c784a84a66adf221597', 'source-node-003165', '6', '3166', 'text', '严守间隔期：严格依药剂说明书把控施药间隔、收获前停药时长，确保农药残留合规、辣椒产品质量安全。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003168', 'source-doc-4c784a84a66adf221597', 'source-node-003162', '5', '3167', 'text', '药剂选择与使用：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003169', 'source-doc-4c784a84a66adf221597', 'source-node-003168', '6', '3168', 'text', '病毒钝化剂：烷醇・硫酸铜、琥铜・吗啉胍等，凭借所含成分特殊理化性质，干扰病毒在植株细胞内增殖环节，筑起阻止病毒扩散 “防线”。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003170', 'source-doc-4c784a84a66adf221597', 'source-node-003168', '6', '3169', 'text', '病毒抑制剂：吗呱・乙酸酮、宁南霉素、氯溴异氰尿酸、辛菌胺醋酸盐等，从抑制病毒复制酶活性、阻断复制流程等多维度发力，“降速” 病毒繁衍，激活植株自身 “防御系统”。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003171', 'source-doc-4c784a84a66adf221597', 'source-node-003168', '6', '3170', 'text', '植物增抗剂：香菇多糖、氨基寡糖素、低聚糖素等，恰似 “免疫激发剂”，唤醒植株内在防御潜能，强化抵御病毒 “侵袭” 效能。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003172', 'source-doc-4c784a84a66adf221597', 'source-node-003168', '6', '3171', 'text', '具体药剂及配比：可选 6% 寡糖・链蛋白可湿性粉剂、1.5% 植病灵水乳剂（含三十烷醇助生长、硫酸铜抑病毒）、20% 丁香酚水乳剂、2% 几丁聚糖水剂、20% 病毒 A 可湿性粉剂（主要成分盐酸吗啉胍）等，按 7 - 10 天间隔，喷雾 2 - 3 次；也可采用 5% 菌毒清水剂 300 倍 + 1.5% 植病灵水剂 1000 倍液 + 硫酸锌 1000 倍喷施，或用 8% 宁南霉素水剂 1200 倍液、30% 毒氟磷可湿性粉剂 1200 倍液精准防控。对根部发病严重植株，适配药剂灌根 “补救”。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003173', 'source-doc-4c784a84a66adf221597', 'source-node-003107', '4', '3172', 'text', '生物防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003174', 'source-doc-4c784a84a66adf221597', 'source-node-003173', '5', '3173', 'text', '拮抗菌利用：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003175', 'source-doc-4c784a84a66adf221597', 'source-node-003174', '6', '3174', 'text', '引入枯草芽孢杆菌、木霉菌等有益微生物制剂，它们在植株表面或根际 “安营扎寨”，分泌抗菌、抗病毒物质，“制衡” 病毒肆虐，优化植株微生态，拔高抗病 “段位”。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003176', 'source-doc-4c784a84a66adf221597', 'source-node-003173', '5', '3175', 'text', '植物提取物应用：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003177', 'source-doc-4c784a84a66adf221597', 'source-node-003176', '6', '3176', 'text', '启用大蒜素、苦参碱等植物提取物喷雾，这类天然物质借独特化学结构 “干扰” 病毒生理进程、抑制活性，兼具环保、低毒 “绿色” 优势。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003178', 'source-doc-4c784a84a66adf221597', 'source-node-003107', '4', '3177', 'text', '物理防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003179', 'source-doc-4c784a84a66adf221597', 'source-node-003178', '5', '3178', 'text', '温汤浸种：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003180', 'source-doc-4c784a84a66adf221597', 'source-node-003179', '6', '3179', 'text', '启用 50℃温水浸种 15 分钟，借助热水 “消杀” 种子携带病毒，是简便高效净化种子 “妙招”。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003181', 'source-doc-4c784a84a66adf221597', 'source-node-003178', '5', '3180', 'text', '覆盖地膜：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003182', 'source-doc-4c784a84a66adf221597', 'source-node-003181', '6', '3181', 'text', '铺透明地膜提温，优化土壤温湿度环境，抑制部分病原菌滋生繁衍，间接削减病毒病诱发 “因子”。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003183', 'source-doc-4c784a84a66adf221597', 'source-node-003178', '5', '3182', 'text', '趋避害虫手段：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003184', 'source-doc-4c784a84a66adf221597', 'source-node-003183', '6', '3183', 'text', '安置杀虫灯 “光诱”、性诱剂 “色诱”、黄篮板及蓝板 “粘捕” 蚜虫与白粉虱，截断病毒传播 “中介”，防范病害扩散。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003185', 'source-doc-4c784a84a66adf221597', 'source-node-003107', '4', '3184', 'text', '综合防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003186', 'source-doc-4c784a84a66adf221597', 'source-node-003185', '5', '3185', 'text', '监测预警：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003187', 'source-doc-4c784a84a66adf221597', 'source-node-003186', '6', '3186', 'text', '定期 “巡田查岗”，敏锐捕捉病害 “蛛丝马迹”，依发病态势及时优化调整防治策略，实现精准高效防控。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003188', 'source-doc-4c784a84a66adf221597', 'source-node-003185', '5', '3187', 'text', '综合管理：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003189', 'source-doc-4c784a84a66adf221597', 'source-node-003188', '6', '3188', 'text', '融合农业、化学、生物、物理防治手段，依据田间实时状况灵活调配施策，编织全方位、立体式防病 “安全网”。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003190', 'source-doc-4c784a84a66adf221597', 'source-node-002718', '1', '3189', 'text', '2.2.2 番茄', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003191', 'source-doc-4c784a84a66adf221597', 'source-node-003190', '2', '3190', 'text', '细菌性病害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003192', 'source-doc-4c784a84a66adf221597', 'source-node-003191', '3', '3191', 'text', '番茄青枯病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003193', 'source-doc-4c784a84a66adf221597', 'source-node-003192', '4', '3192', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003194', 'source-doc-4c784a84a66adf221597', 'source-node-003193', '5', '3193', 'text', '成株期发病，叶片突然萎蔫，中午加重，傍晚恢复，数日后枯死；茎基部横剖，维管束变褐，挤压有乳白色菌脓溢出。自上而下萎蔫不黄化，青青的萎蔫。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003195', 'source-doc-4c784a84a66adf221597', 'source-node-003192', '4', '3194', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003196', 'source-doc-4c784a84a66adf221597', 'source-node-003195', '5', '3195', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003197', 'source-doc-4c784a84a66adf221597', 'source-node-003192', '4', '3196', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003198', 'source-doc-4c784a84a66adf221597', 'source-node-003197', '5', '3197', 'text', '青枯雷尔氏菌（Ralstoniasolanacearum），属于薄壁菌门雷尔氏菌属。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003199', 'source-doc-4c784a84a66adf221597', 'source-node-003192', '4', '3198', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003200', 'source-doc-4c784a84a66adf221597', 'source-node-003199', '5', '3199', 'text', '高温高湿（25-30℃、土壤含水量高）利于发病，土传病害，连作、酸性土壤、排水不良田块病重，通过雨水、灌溉水传播。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003201', 'source-doc-4c784a84a66adf221597', 'source-node-003192', '4', '3200', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003202', 'source-doc-4c784a84a66adf221597', 'source-node-003201', '5', '3201', 'text', '农业防治：轮作3年以上（与禾本科作物），改良土壤（施生石灰调pH值），高垄栽培，避免大水漫灌。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003203', 'source-doc-4c784a84a66adf221597', 'source-node-003201', '5', '3202', 'text', '化学防治：发病初期用噻唑锌、氢氧化铜等药剂灌根，每株灌0.5-1升，7-10天1次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003204', 'source-doc-4c784a84a66adf221597', 'source-node-003201', '5', '3203', 'text', '生物防治：施用荧光假单胞杆菌、枯草芽孢杆菌等生防菌拌土或灌根。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003205', 'source-doc-4c784a84a66adf221597', 'source-node-003191', '3', '3204', 'text', '细菌性髓部坏死病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003206', 'source-doc-4c784a84a66adf221597', 'source-node-003205', '4', '3205', 'text', '一、病害简介', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003207', 'source-doc-4c784a84a66adf221597', 'source-node-003206', '5', '3206', 'text', '番茄细菌性髓部坏死病是一种由细菌引起的严重病害，病原菌为番茄髓部坏死病假单胞菌（Pseudomonas corrugata）或菊欧文氏菌（Erwinia chrysanthemi）。这种病害主要危害番茄的茎部和分枝，发病后会导致植株迅速枯萎死亡，给番茄种植带来巨大损失。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003208', 'source-doc-4c784a84a66adf221597', 'source-node-003205', '4', '3207', 'text', '二、图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003209', 'source-doc-4c784a84a66adf221597', 'source-node-003208', '5', '3208', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003210', 'source-doc-4c784a84a66adf221597', 'source-node-003205', '4', '3209', 'text', '三、症状表现', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003211', 'source-doc-4c784a84a66adf221597', 'source-node-003210', '5', '3210', 'text', '植株初期症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003212', 'source-doc-4c784a84a66adf221597', 'source-node-003211', '6', '3211', 'text', '发病初期，植株的上部叶片开始出现萎蔫，在白天阳光充足、气温较高时，萎蔫现象更为明显，而在傍晚或阴天时，叶片可能会恢复部分挺立状态。这种情况很容易被误诊为缺水，但随着病情发展，即使浇水也无法恢复叶片正常状态。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003213', 'source-doc-4c784a84a66adf221597', 'source-node-003210', '5', '3212', 'text', '茎部症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003214', 'source-doc-4c784a84a66adf221597', 'source-node-003213', '6', '3213', 'text', '外部表现：茎部是该病的主要受害部位。发病初期，茎基部或分枝处出现褐色至黑褐色的不规则病斑，病斑形状多为长条状，长度可达数厘米。茎部肿胀，内部髓部褐色坏死，具恶臭味，挤压有菌脓溢出；叶片萎蔫，果实小而畸形。随着病情加重，病斑逐渐向上、向下扩展，环绕茎部，导致茎部表皮粗糙，颜色加深，并且常常伴有裂缝。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003215', 'source-doc-4c784a84a66adf221597', 'source-node-003213', '6', '3214', 'text', '内部变化：纵剖病茎，可以看到茎内部的髓部变为褐色或黑褐色，髓部组织坏死、腐烂，且有明显的臭味。病情严重时，髓部空洞化，仅剩下维管束组织，这会严重影响植株的水分和养分运输。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003216', 'source-doc-4c784a84a66adf221597', 'source-node-003210', '5', '3215', 'text', '叶片及果实症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003217', 'source-doc-4c784a84a66adf221597', 'source-node-003216', '6', '3216', 'text', '叶片除了初期的萎蔫症状外，随着病情的发展，会逐渐变黄、干枯，但脱落相对较晚。果实一般在发病后期才会受到影响，表现为果实变小、发育不良，部分果实表面会出现褐色斑点，严重时果实腐烂。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003218', 'source-doc-4c784a84a66adf221597', 'source-node-003205', '4', '3217', 'text', '四、发病规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003219', 'source-doc-4c784a84a66adf221597', 'source-node-003218', '5', '3218', 'text', '病原菌来源与传播', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003220', 'source-doc-4c784a84a66adf221597', 'source-node-003219', '6', '3219', 'text', '病原菌主要在病残体、土壤和种子中越冬。种子带菌是远距离传播的重要途径，在种子发芽和幼苗生长过程中，病原菌会侵染植株。土壤中的病原菌可以通过灌溉水、雨水飞溅、农事操作（如整枝、打杈等）等方式传播到健康植株上，从植株的伤口（如机械伤口、虫咬伤口等）或自然孔口（如气孔、水孔等）侵入。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003221', 'source-doc-4c784a84a66adf221597', 'source-node-003218', '5', '3220', 'text', '发病条件', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003222', 'source-doc-4c784a84a66adf221597', 'source-node-003221', '6', '3221', 'text', '温度和湿度：该病害在温暖潮湿的环境下容易发生。病原菌生长适宜温度为 25 - 30℃，相对湿度在 80% 以上有利于病害的传播和侵染。在高湿度环境下，植株表面的露水、雨水等为病原菌的侵入提供了有利条件。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003223', 'source-doc-4c784a84a66adf221597', 'source-node-003221', '6', '3222', 'text', '植株生长状况：种植密度过大、植株徒长、通风不良、施肥不当（如偏施氮肥导致植株抗性降低）等情况都会增加植株的感病性。此外，番茄生长中后期，植株生长旺盛，茎部组织较为幼嫩，也更容易受到病原菌的侵害。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003224', 'source-doc-4c784a84a66adf221597', 'source-node-003205', '4', '3223', 'text', '五、防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003225', 'source-doc-4c784a84a66adf221597', 'source-node-003205', '4', '3224', 'text', '（一）农业防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003226', 'source-doc-4c784a84a66adf221597', 'source-node-003225', '5', '3225', 'text', '种子处理', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003227', 'source-doc-4c784a84a66adf221597', 'source-node-003226', '6', '3226', 'text', '选用无病种子是预防该病的关键。如果种子来源不确定，可进行种子处理。常用的方法是温汤浸种，将种子放入 55 - 60℃的温水浸泡 15 - 20 分钟，期间不断搅拌，然后让种子在温水中浸泡一段时间后捞出，用清水冲洗干净，晾干后播种。这种方法可以杀死种子表面携带的病原菌。另外，也可以用 1.05% 次氯酸钠溶液浸种 20 - 30 分钟，次氯酸钠具有强氧化性，能够有效杀灭病原菌，浸种后用清水冲洗干净再播种。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003228', 'source-doc-4c784a84a66adf221597', 'source-node-003225', '5', '3227', 'text', '轮作倒茬', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003229', 'source-doc-4c784a84a66adf221597', 'source-node-003228', '6', '3228', 'text', '实行与非茄科作物轮作，轮作周期以 3 - 4 年为宜。通过轮作可以减少土壤中病原菌的积累，降低发病风险。例如，可以与豆科、十字花科等作物轮作。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003230', 'source-doc-4c784a84a66adf221597', 'source-node-003225', '5', '3229', 'text', '栽培管理', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003231', 'source-doc-4c784a84a66adf221597', 'source-node-003230', '6', '3230', 'text', '合理密植：根据番茄品种的特性和土壤肥力，合理确定种植密度。一般每亩种植 2000 - 3000 株，保证植株间有良好的通风透光条件，降低田间湿度，减少病害发生。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003232', 'source-doc-4c784a84a66adf221597', 'source-node-003230', '6', '3231', 'text', '整枝打杈：及时进行整枝打杈，但要注意操作工具的消毒，避免病原菌通过伤口传播。在整枝打杈后，可以用 75% 酒精或 0.1% 高锰酸钾溶液对伤口进行消毒。同时，及时清除田间的病叶、病枝和病果，带出田外集中销毁，减少病原菌的传播源。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003233', 'source-doc-4c784a84a66adf221597', 'source-node-003230', '6', '3232', 'text', '平衡施肥：施足基肥，增施有机肥和磷、钾肥，提高植株的抗病能力。避免偏施氮肥，防止植株徒长。例如，基肥可以每亩施用腐熟农家肥 3000 - 5000 千克、过磷酸钙 50 - 100 千克、硫酸钾 15 - 20 千克。在番茄生长过程中，根据植株生长阶段适时追肥，注重氮、磷、钾的合理配比。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003234', 'source-doc-4c784a84a66adf221597', 'source-node-003230', '6', '3233', 'text', '土壤改良：对于酸性土壤，可以适量施用石灰调节土壤酸碱度，提高土壤的 pH 值，改善土壤环境，抑制病原菌的生长。一般每亩施用石灰 100 - 150 千克。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003235', 'source-doc-4c784a84a66adf221597', 'source-node-003205', '4', '3234', 'text', '（二）化学防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003236', 'source-doc-4c784a84a66adf221597', 'source-node-003235', '5', '3235', 'text', '药剂喷雾防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003237', 'source-doc-4c784a84a66adf221597', 'source-node-003236', '6', '3236', 'text', '在发病初期，可以选用以下药剂进行喷雾防治。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003238', 'source-doc-4c784a84a66adf221597', 'source-node-003236', '6', '3237', 'text', '72% 农用链霉素可溶性粉剂 3000 - 4000 倍液：农用链霉素主要成分是链霉素，它能够抑制细菌蛋白质的合成，从而起到杀菌作用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003239', 'source-doc-4c784a84a66adf221597', 'source-node-003236', '6', '3238', 'text', '新植霉素 4000 - 5000 倍液：新植霉素的主要成分也是一种抗生素，对番茄细菌性髓部坏死病有较好的防治效果，通过干扰细菌的生长代谢来抑制病原菌。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003240', 'source-doc-4c784a84a66adf221597', 'source-node-003236', '6', '3239', 'text', '20% 噻菌铜悬浮剂 500 - 700 倍液：噻菌铜主要成分是噻菌铜，它能与病原菌的蛋白质结合，使蛋白质变性，进而杀死细菌。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003241', 'source-doc-4c784a84a66adf221597', 'source-node-003236', '6', '3240', 'text', '50% 氯溴异氰尿酸可溶性粉剂 1000 - 1500 倍液：氯溴异氰尿酸主要成分能够在水中分解形成次氯酸和次溴酸，这些物质具有强氧化性，能够快速杀灭病原菌。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003242', 'source-doc-4c784a84a66adf221597', 'source-node-003236', '6', '3241', 'text', '喷雾时要注意均匀周到，重点喷施植株的茎部和叶片背面，每隔 7 - 10 天喷一次，连续喷 3 - 4 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003243', 'source-doc-4c784a84a66adf221597', 'source-node-003236', '6', '3242', 'text', '3% 中生菌素可湿性粉剂 800 - 1000 倍液、72% 农用链霉素可溶性粉剂 4000 倍液灌根或喷雾，7 - 10 天 1 次，连施 2 - 3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003244', 'source-doc-4c784a84a66adf221597', 'source-node-003236', '6', '3243', 'text', '发病初期喷施氢氧化铜、噻唑锌等药剂，配合灌根。但是氢氧化铜没有内吸性，噻唑锌有一定内吸性。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003245', 'source-doc-4c784a84a66adf221597', 'source-node-003235', '5', '3244', 'text', '药剂灌根防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003246', 'source-doc-4c784a84a66adf221597', 'source-node-003245', '6', '3245', 'text', '对于病情较重的植株，可以采用药剂灌根的方法。可选用 3% 中生菌素可湿性粉剂 600 - 800 倍液（中生菌素主要成分是一种抗生素，能抑制细菌细胞壁的合成）或 5% 菌毒清水剂 300 - 400 倍液（菌毒清主要成分是一种氨基酸类化合物，对细菌有抑制作用）进行灌根。每株灌药量为 200 - 300 毫升，每隔 10 - 15 天灌一次，连续灌 2 - 3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003247', 'source-doc-4c784a84a66adf221597', 'source-node-003205', '4', '3246', 'text', '（三）生物防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003248', 'source-doc-4c784a84a66adf221597', 'source-node-003247', '5', '3247', 'text', '有益微生物利用', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003249', 'source-doc-4c784a84a66adf221597', 'source-node-003248', '6', '3248', 'text', '利用芽孢杆菌（Bacillus spp.）等有益微生物来防治番茄细菌性髓部坏死病。例如，枯草芽孢杆菌可以在植株根际周围定殖，与病原菌竞争营养和空间，并且能够分泌抗菌物质，如脂肽类抗生素等，抑制病原菌的生长。将含有芽孢杆菌的生物制剂按照产品说明进行稀释后灌根或喷雾，可以在一定程度上减轻病害。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003250', 'source-doc-4c784a84a66adf221597', 'source-node-003247', '5', '3249', 'text', '植物源提取物应用', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003251', 'source-doc-4c784a84a66adf221597', 'source-node-003250', '6', '3250', 'text', '一些植物源提取物如大蒜素、黄连素等对番茄细菌性髓部坏死病也有一定的防治作用。大蒜素从大蒜中提取，它可以破坏病原菌的细胞膜结构，干扰细菌的生理功能。黄连素主要从黄连等植物中提取，对细菌有抑制作用。将这些植物源提取物按照推荐浓度稀释后进行喷雾或灌根，对病害有一定的防控效果，同时具有环境友好的特点。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003252', 'source-doc-4c784a84a66adf221597', 'source-node-003191', '3', '3251', 'text', '细菌性斑疹病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003253', 'source-doc-4c784a84a66adf221597', 'source-node-003252', '4', '3252', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003254', 'source-doc-4c784a84a66adf221597', 'source-node-003253', '5', '3253', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003255', 'source-doc-4c784a84a66adf221597', 'source-node-003252', '4', '3254', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003256', 'source-doc-4c784a84a66adf221597', 'source-node-003255', '5', '3255', 'text', '叶片生暗褐色小斑点，圆形或多角形，无明显黄晕；果实病斑小，凹陷，黑色，周围无晕圈。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003257', 'source-doc-4c784a84a66adf221597', 'source-node-003252', '4', '3256', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003258', 'source-doc-4c784a84a66adf221597', 'source-node-003257', '5', '3257', 'text', '丁香假单胞菌番茄致病变种（Pseudomonassyringaepv.tomato），属于薄壁菌门假单胞菌属。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003259', 'source-doc-4c784a84a66adf221597', 'source-node-003252', '4', '3258', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003260', 'source-doc-4c784a84a66adf221597', 'source-node-003259', '5', '3259', 'text', '低温高湿（18-24℃、多雨）易发病，种子、病残体带菌，通过风雨、农事操作传播，棚室通风差时病重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003261', 'source-doc-4c784a84a66adf221597', 'source-node-003252', '4', '3260', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003262', 'source-doc-4c784a84a66adf221597', 'source-node-003261', '5', '3261', 'text', '农业防治：种子消毒（1%盐酸浸种10分钟），轮作2年以上，清洁田园。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003263', 'source-doc-4c784a84a66adf221597', 'source-node-003261', '5', '3262', 'text', '化学防治：发病初期喷施春雷霉素、氢氧化铜等药剂。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003264', 'source-doc-4c784a84a66adf221597', 'source-node-003191', '3', '3263', 'text', '细菌性叶斑病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003265', 'source-doc-4c784a84a66adf221597', 'source-node-003264', '4', '3264', 'text', '图片', '[]');
