INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003267', 'source-doc-4c784a84a66adf221597', 'source-node-003191', '3', '3266', 'text', '番茄溃疡病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003268', 'source-doc-4c784a84a66adf221597', 'source-node-003267', '4', '3267', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003269', 'source-doc-4c784a84a66adf221597', 'source-node-003268', '5', '3268', 'text', '叶片呈V字形黄化枯萎，茎部隆起开裂，溢出白色菌脓；果实表面生圆形白色斑点，中心褐色，呈“鸟眼状”；植株上部呈青枯状，湿度大时，有褐色菌脓溢出。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003270', 'source-doc-4c784a84a66adf221597', 'source-node-003267', '4', '3269', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003271', 'source-doc-4c784a84a66adf221597', 'source-node-003270', '5', '3270', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003272', 'source-doc-4c784a84a66adf221597', 'source-node-003267', '4', '3271', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003273', 'source-doc-4c784a84a66adf221597', 'source-node-003272', '5', '3272', 'text', '密执安棒杆菌番茄溃疡病亚种（Clavibactermichiganensissubsp.michiganensis），属于厚壁菌门棒杆菌属。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003274', 'source-doc-4c784a84a66adf221597', 'source-node-003267', '4', '3273', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003275', 'source-doc-4c784a84a66adf221597', 'source-node-003274', '5', '3274', 'text', '高温高湿（25-28℃、多雨）易发病，种子、病残体带菌，通过风雨、昆虫及农事操作传播，连作田发病重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003276', 'source-doc-4c784a84a66adf221597', 'source-node-003267', '4', '3275', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003277', 'source-doc-4c784a84a66adf221597', 'source-node-003276', '5', '3276', 'text', '农业防治：种子消毒（55℃浸种30分钟），轮作3年以上，严格检疫，清除病株深埋。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003278', 'source-doc-4c784a84a66adf221597', 'source-node-003276', '5', '3277', 'text', '化学防治：发病初期喷施氢氧化铜、噻唑锌等药剂，连喷2-3次，间隔7天。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003279', 'source-doc-4c784a84a66adf221597', 'source-node-003191', '3', '3278', 'text', '番茄软腐病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003280', 'source-doc-4c784a84a66adf221597', 'source-node-003279', '4', '3279', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003281', 'source-doc-4c784a84a66adf221597', 'source-node-003280', '5', '3280', 'text', '主要危害果实，初为水浸状暗绿色斑，迅速扩大，果肉腐烂变软，具恶臭味；病果易脱落，后期果皮破裂。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003282', 'source-doc-4c784a84a66adf221597', 'source-node-003279', '4', '3281', 'text', '图片', '[]');
