INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003284', 'source-doc-4c784a84a66adf221597', 'source-node-003279', '4', '3283', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003285', 'source-doc-4c784a84a66adf221597', 'source-node-003284', '5', '3284', 'text', '胡萝卜软腐欧文氏菌胡萝卜软腐亚种（Erwiniacarotovorasubsp.carotovora），属于薄壁菌门欧文氏菌属。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003286', 'source-doc-4c784a84a66adf221597', 'source-node-003279', '4', '3285', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003287', 'source-doc-4c784a84a66adf221597', 'source-node-003286', '5', '3286', 'text', '高温高湿（25-30℃、多雨）利于发病，通过伤口侵入，风雨、昆虫传播，果实成熟后期及贮藏期易发病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003288', 'source-doc-4c784a84a66adf221597', 'source-node-003279', '4', '3287', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003289', 'source-doc-4c784a84a66adf221597', 'source-node-003288', '5', '3288', 'text', '农业防治：避免果实损伤，及时防治害虫，雨后排水，合理密植。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003290', 'source-doc-4c784a84a66adf221597', 'source-node-003288', '5', '3289', 'text', '化学防治：发病初期喷施春雷霉素、中生菌素等药剂，重点喷洒果实及下部叶片。', '[]');
