INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003304', 'source-doc-4c784a84a66adf221597', 'source-node-003295', '4', '3303', 'text', '发病规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003305', 'source-doc-4c784a84a66adf221597', 'source-node-003304', '5', '3304', 'text', '低温高湿（18-22℃、相对湿度>90%）易爆发，通过风雨、灌溉水传播，连作田发病重', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003306', 'source-doc-4c784a84a66adf221597', 'source-node-003295', '4', '3305', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003307', 'source-doc-4c784a84a66adf221597', 'source-node-003306', '5', '3306', 'text', '（一）农业防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003308', 'source-doc-4c784a84a66adf221597', 'source-node-003307', '6', '3307', 'text', '品种选择', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003309', 'source-doc-4c784a84a66adf221597', 'source-node-003308', '7', '3308', 'text', '选用抗病品种是防治番茄晚疫病最经济有效的方法。如‘中蔬 4 号’、‘佳粉 15 号’、‘强丰’等品种对晚疫病有一定的抗性。在种植前，可根据当地的气候条件和病害发生情况选择合适的抗病品种。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003310', 'source-doc-4c784a84a66adf221597', 'source-node-003307', '6', '3309', 'text', '轮作倒茬', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003311', 'source-doc-4c784a84a66adf221597', 'source-node-003310', '7', '3310', 'text', '实行与非茄科作物轮作，轮作周期一般为 3 - 4 年。避免连作，可减少病原菌在土壤中的积累，降低发病风险。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003312', 'source-doc-4c784a84a66adf221597', 'source-node-003307', '6', '3311', 'text', '栽培管理', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003313', 'source-doc-4c784a84a66adf221597', 'source-node-003312', '7', '3312', 'text', '合理密植：根据品种特性和土壤肥力，合理确定种植密度，保证植株间通风透光良好。一般早熟品种每亩种植 3000 - 3500 株，中晚熟品种每亩种植 2500 - 3000 株。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003314', 'source-doc-4c784a84a66adf221597', 'source-node-003312', '7', '3313', 'text', '整枝打杈：及时进行整枝打杈，去除病叶、病枝和老叶，改善植株通风透光条件，降低田间湿度，减少病原菌滋生的机会。同时，整枝打杈后的病残体要带出田外集中销毁，防止病原菌传播。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003315', 'source-doc-4c784a84a66adf221597', 'source-node-003312', '7', '3314', 'text', '合理施肥：施足基肥，增施有机肥和磷、钾肥，提高植株的抗病能力。避免偏施氮肥，防止植株徒长。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003316', 'source-doc-4c784a84a66adf221597', 'source-node-003312', '7', '3315', 'text', '排水降湿：高垄栽培，保持田间排水良好，避免田间积水。在雨季来临前，要清理沟渠，确保雨水能够及时排出。在设施栽培中，要注意通风换气，降低空气湿度。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003317', 'source-doc-4c784a84a66adf221597', 'source-node-003306', '5', '3316', 'text', '（二）化学防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003318', 'source-doc-4c784a84a66adf221597', 'source-node-003317', '6', '3317', 'text', '预防用药', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003319', 'source-doc-4c784a84a66adf221597', 'source-node-003318', '7', '3318', 'text', '在病害常发区或发病初期，可选用保护性杀菌剂进行预防。如 75% 百菌清可湿性粉剂 600 - 800 倍液（主要成分百菌清，能抑制病原菌的孢子萌发和菌丝生长）、80% 代森锰锌可湿性粉剂 600 - 800 倍液（代森锰锌主要成分是乙撑双二硫代氨基甲酸锰和锌盐，通过与病原菌的含硫基团反应，抑制其酶活性）。每隔 7 - 10 天喷一次，连续喷 2 - 3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003320', 'source-doc-4c784a84a66adf221597', 'source-node-003317', '6', '3319', 'text', '治疗用药', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003321', 'source-doc-4c784a84a66adf221597', 'source-node-003320', '7', '3320', 'text', '当发现病斑后，要及时选用治疗性杀菌剂进行防治。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003322', 'source-doc-4c784a84a66adf221597', 'source-node-003320', '7', '3321', 'text', '发病初期喷施霜霉威盐酸盐、嘧菌酯等药剂，7-10天1次，连喷2-3次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003323', 'source-doc-4c784a84a66adf221597', 'source-node-003320', '7', '3322', 'text', '68.75% 氟菌・霜霉威悬浮剂 600 - 800 倍液：主要成分是氟吡菌胺和霜霉威，氟吡菌胺能抑制病原菌的细胞壁合成，霜霉威则干扰病原菌的细胞膜功能，两者协同作用，对晚疫病有良好的防治效果。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003324', 'source-doc-4c784a84a66adf221597', 'source-node-003320', '7', '3323', 'text', '52.5% 恶唑菌酮・霜脲氰水分散粒剂 1500 - 2000 倍液：恶唑菌酮主要通过抑制病原菌的线粒体呼吸作用来发挥杀菌功能，霜脲氰能阻止病原菌的孢子萌发和菌丝生长，这种复配药剂杀菌谱广、效果好。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003325', 'source-doc-4c784a84a66adf221597', 'source-node-003320', '7', '3324', 'text', '72% 霜脲・锰锌可湿性粉剂 600 - 800 倍液：含有霜脲氰和代森锰锌，霜脲氰具有内吸性，能快速进入植物体内发挥杀菌作用，代森锰锌则在植物表面形成保护膜，防止病原菌侵入，两者配合可有效控制病害。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003326', 'source-doc-4c784a84a66adf221597', 'source-node-003320', '7', '3325', 'text', '64% 噁霜・锰锌可湿性粉剂 400 - 500 倍液：噁霜灵主要成分能抑制病原菌的 RNA 合成，代森锰锌起保护作用，对晚疫病有较好的治疗和保护双重作用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003327', 'source-doc-4c784a84a66adf221597', 'source-node-003306', '5', '3326', 'text', '（三）生物防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003328', 'source-doc-4c784a84a66adf221597', 'source-node-003327', '6', '3327', 'text', '拮抗微生物利用', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003329', 'source-doc-4c784a84a66adf221597', 'source-node-003328', '7', '3328', 'text', '利用芽孢杆菌（Bacillus spp.），哈茨木霉菌等有益微生物来防治番茄晚疫病。芽孢杆菌可以在植株表面定殖，与病原菌竞争营养和空间，并且能够分泌抗菌物质抑制病原菌的生长。例如，将枯草芽孢杆菌制剂按照产品说明稀释后进行喷雾或灌根，可以在一定程度上减轻病害。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003330', 'source-doc-4c784a84a66adf221597', 'source-node-003327', '6', '3329', 'text', '植物源杀菌剂应用', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003331', 'source-doc-4c784a84a66adf221597', 'source-node-003330', '7', '3330', 'text', '有些植物源药剂如大蒜素，从大蒜中提取。将大蒜素制剂按照推荐浓度稀释后进行喷雾，它可以破坏病原菌的细胞膜等结构，干扰其生理功能，对番茄晚疫病有一定的防治作用，并且对环境友好，不易使病原菌产生抗药性。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003332', 'source-doc-4c784a84a66adf221597', 'source-node-003294', '3', '3331', 'text', '番茄猝倒病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003333', 'source-doc-4c784a84a66adf221597', 'source-node-003332', '4', '3332', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003334', 'source-doc-4c784a84a66adf221597', 'source-node-003333', '5', '3333', 'text', '苗期发病，茎基部近地面处出现水浸状缢缩，幼苗突然倒伏，叶片仍保持绿色；湿度大时，病部及周围土壤生白色棉絮状菌丝。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003335', 'source-doc-4c784a84a66adf221597', 'source-node-003332', '4', '3334', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003336', 'source-doc-4c784a84a66adf221597', 'source-node-003335', '5', '3335', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003337', 'source-doc-4c784a84a66adf221597', 'source-node-003332', '4', '3336', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003338', 'source-doc-4c784a84a66adf221597', 'source-node-003337', '5', '3337', 'text', '瓜果腐霉（Pythiumaphanidermatum），属于假菌界卵菌门腐霉属。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003339', 'source-doc-4c784a84a66adf221597', 'source-node-003332', '4', '3338', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003340', 'source-doc-4c784a84a66adf221597', 'source-node-003339', '5', '3339', 'text', '低温高湿（15-20℃、土壤含水量高）为高发条件，种子或土壤带菌，通过雨水、灌溉水传播，苗床通风差、密度过大时病重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003341', 'source-doc-4c784a84a66adf221597', 'source-node-003332', '4', '3340', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003342', 'source-doc-4c784a84a66adf221597', 'source-node-003341', '5', '3341', 'text', '农业防治：苗床消毒（撒施多菌灵+福美双混合剂），控制浇水，加强通风，合理密植。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003343', 'source-doc-4c784a84a66adf221597', 'source-node-003341', '5', '3342', 'text', '化学防治：发病初期喷施恶霉灵、甲霜・噁霉灵等药剂，喷淋幼苗基部及土壤。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003344', 'source-doc-4c784a84a66adf221597', 'source-node-003294', '3', '3343', 'text', '番茄茎基腐病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003345', 'source-doc-4c784a84a66adf221597', 'source-node-003344', '4', '3344', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003346', 'source-doc-4c784a84a66adf221597', 'source-node-003345', '5', '3345', 'text', '茎基部近地面处出现水浸状褐色腐烂，皮层脱落，露出木质部；植株萎蔫枯死，湿度大时病部生白色霉层。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003347', 'source-doc-4c784a84a66adf221597', 'source-node-003344', '4', '3346', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003348', 'source-doc-4c784a84a66adf221597', 'source-node-003347', '5', '3347', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003349', 'source-doc-4c784a84a66adf221597', 'source-node-003344', '4', '3348', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003350', 'source-doc-4c784a84a66adf221597', 'source-node-003349', '5', '3349', 'text', '疫霉属（Phytophthoracrownandrootrot），主要为寄生疫霉等。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003351', 'source-doc-4c784a84a66adf221597', 'source-node-003344', '4', '3350', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003352', 'source-doc-4c784a84a66adf221597', 'source-node-003351', '5', '3351', 'text', '高温高湿（25-30℃、土壤含水量高）利于发病，土传病害，连作、低洼积水田块病重，通过灌溉水传播。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003353', 'source-doc-4c784a84a66adf221597', 'source-node-003344', '4', '3352', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003354', 'source-doc-4c784a84a66adf221597', 'source-node-003353', '5', '3353', 'text', '农业防治：高垄栽培，避免大水漫灌，及时排水，轮作3年以上。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003355', 'source-doc-4c784a84a66adf221597', 'source-node-003353', '5', '3354', 'text', '化学防治：发病初期用霜霉威盐酸盐、甲霜・噁霉灵灌根或喷淋茎基部。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003356', 'source-doc-4c784a84a66adf221597', 'source-node-003294', '3', '3355', 'text', '番茄根腐病（Fusarium solani）（腐霉和疫霉）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003357', 'source-doc-4c784a84a66adf221597', 'source-node-003356', '4', '3356', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003358', 'source-doc-4c784a84a66adf221597', 'source-node-003357', '5', '3357', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003359', 'source-doc-4c784a84a66adf221597', 'source-node-003356', '4', '3358', 'text', '根腐的鉴别', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003360', 'source-doc-4c784a84a66adf221597', 'source-node-003359', '5', '3359', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003361', 'source-doc-4c784a84a66adf221597', 'source-node-003356', '4', '3360', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003362', 'source-doc-4c784a84a66adf221597', 'source-node-003361', '5', '3361', 'text', '症状表现', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003363', 'source-doc-4c784a84a66adf221597', 'source-node-003362', '6', '3362', 'text', '根部症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003364', 'source-doc-4c784a84a66adf221597', 'source-node-003363', '7', '3363', 'text', '疫霉根腐病：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003365', 'source-doc-4c784a84a66adf221597', 'source-node-003364', '8', '3364', 'text', '发病初期，根系可能出现褐色至黑褐色的病斑，病斑通常从根尖或侧根开始，逐渐向上蔓延。根部皮层组织坏死，病健交界处比较明显，有时会看到根部表面有一层稀疏的白色霉层（病原菌的菌丝体）。随着病情加重，整个根系会变黑腐烂，主根也会受到严重影响。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003366', 'source-doc-4c784a84a66adf221597', 'source-node-003364', '8', '3365', 'text', '例如，在番茄疫霉根腐病严重的植株上，根系几乎完全腐烂，只剩下中心的木质部，形似 “黑根”。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003367', 'source-doc-4c784a84a66adf221597', 'source-node-003363', '7', '3366', 'text', '腐霉根腐病：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003368', 'source-doc-4c784a84a66adf221597', 'source-node-003367', '8', '3367', 'text', '根部发病初期，根组织呈现水渍状软腐，颜色变浅，一般为淡褐色。病斑形状不规则，没有明显的边缘，腐烂的速度相对较快。随着病情发展，根部皮层会大量脱落，仅剩下中柱部分，根系逐渐萎缩。在湿度高的情况下，根部表面也会出现白色至灰白色的霉层，这是腐霉菌的菌丝体和孢子囊。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003369', 'source-doc-4c784a84a66adf221597', 'source-node-003362', '6', '3368', 'text', '地上部分症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003370', 'source-doc-4c784a84a66adf221597', 'source-node-003369', '7', '3369', 'text', '疫霉根腐病：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003371', 'source-doc-4c784a84a66adf221597', 'source-node-003370', '8', '3370', 'text', '地上部分的叶片在发病初期可能会出现萎蔫，尤其是在中午阳光强烈时，植株表现为暂时性的缺水状萎蔫，早晚可能会恢复部分。随着根部病情的恶化，叶片逐渐变黄、枯萎，从下部叶片向上蔓延。植株生长缓慢，严重时整株死亡。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003372', 'source-doc-4c784a84a66adf221597', 'source-node-003369', '7', '3371', 'text', '腐霉根腐病：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003373', 'source-doc-4c784a84a66adf221597', 'source-node-003372', '8', '3372', 'text', '地上部分的症状与疫霉根腐病类似，但发病速度可能更快。叶片迅速变黄、萎蔫，并且可能伴有坏死斑点。植株在短时间内就会出现生长停滞，随后枯萎死亡。由于腐霉根腐病对根系的破坏较为严重，地上部分的症状往往比疫霉根腐病出现得更早且更严重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003374', 'source-doc-4c784a84a66adf221597', 'source-node-003361', '5', '3373', 'text', '疫霉根腐病发病初期植株在中午高温期间表现萎蔫症，随病情加重，顶部叶片萎蔫严重，下部叶片也出现病。发病后根系先变为浅褐，后颜色加深为黑褐色，严重时靠近根部的维管束也变为褐色。土壤浇水过多发病重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003375', 'source-doc-4c784a84a66adf221597', 'source-node-003361', '5', '3374', 'text', '枯萎病虽然也造成番茄的维管束变为褐色，但番茄根部表面一般不变为褐色。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003376', 'source-doc-4c784a84a66adf221597', 'source-node-003356', '4', '3375', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003377', 'source-doc-4c784a84a66adf221597', 'source-node-003376', '5', '3376', 'text', '病原菌一般为鞭毛菌门的真菌PhytophthoraparasitcaDast.（寄生疫霉）和P.capsiciLeonian（辣椒疫霉）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003378', 'source-doc-4c784a84a66adf221597', 'source-node-003376', '5', '3377', 'text', '多种病原菌引起的根部病害，主要包括腐皮镰孢菌（Fusarium solani）、疫霉属（Phytophthora）真菌等。这种病害在番茄的整个生育期都可能发生，是导致番茄植株生长衰弱、产量降低的重要原因之一。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003379', 'source-doc-4c784a84a66adf221597', 'source-node-003356', '4', '3378', 'text', '发病规律：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003380', 'source-doc-4c784a84a66adf221597', 'source-node-003379', '5', '3379', 'text', '土壤带菌，随流水、农事操作侵入根部，土壤黏重、排水不良、连作且温度 25 - 30℃易发病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003381', 'source-doc-4c784a84a66adf221597', 'source-node-003379', '5', '3380', 'text', '病原菌主要以菌丝体、厚垣孢子或卵孢子在土壤中或病残体上越冬。这些病原菌可以在土壤中存活多年，成为主要的初侵染源。病原菌通过雨水、灌溉水、农事操作（如移栽、中耕等）在田间传播，从番茄植株的根部伤口（如机械损伤、虫咬伤口等）或幼嫩的根尖侵入。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003382', 'source-doc-4c784a84a66adf221597', 'source-node-003379', '5', '3381', 'text', '土壤条件：土壤湿度大、排水不良的地块容易发病。例如，在连阴雨天气或浇水过多后，土壤积水，会为病原菌的生长和侵染提供有利条件。另外，土壤质地黏重、透气性差也会增加发病几率。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003383', 'source-doc-4c784a84a66adf221597', 'source-node-003379', '5', '3382', 'text', '温度因素：不同病原菌适宜的温度范围有所差异。腐皮镰孢菌在 25 - 30℃左右发病较重，疫霉属真菌在 20 - 25℃较为活跃。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003384', 'source-doc-4c784a84a66adf221597', 'source-node-003379', '5', '3383', 'text', '栽培管理：连作会使土壤中的病原菌积累增多，增加发病风险。此外，种植密度过大、施肥不当（如偏施氮肥导致植株徒长，根系发育不良）等情况也会使植株更容易受到根腐病的侵害。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003385', 'source-doc-4c784a84a66adf221597', 'source-node-003356', '4', '3384', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003386', 'source-doc-4c784a84a66adf221597', 'source-node-003385', '5', '3385', 'text', '（一）农业防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003387', 'source-doc-4c784a84a66adf221597', 'source-node-003386', '6', '3386', 'text', '轮作倒茬', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003388', 'source-doc-4c784a84a66adf221597', 'source-node-003387', '7', '3387', 'text', '实行与非茄科作物轮作，轮作周期 3 - 4 年。例如与豆科、十字花科等作物轮作，可减少土壤中病原菌的积累，降低发病风险。合理灌溉；避开高温浇水；高垄栽培；调节PH', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003389', 'source-doc-4c784a84a66adf221597', 'source-node-003386', '6', '3388', 'text', '土壤改良', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003390', 'source-doc-4c784a84a66adf221597', 'source-node-003389', '7', '3389', 'text', '改善土壤结构，增加土壤透气性。可以通过增施有机肥（如腐熟农家肥、绿肥等）、进行深翻晒垡等措施来实现。例如，每亩施用腐熟农家肥 3000 - 5000 千克，在种植前对土壤进行深翻，深度达到 30 - 40 厘米左右，然后晾晒一段时间，使土壤疏松，减少病原菌的滋生。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003391', 'source-doc-4c784a84a66adf221597', 'source-node-003386', '6', '3390', 'text', '栽培管理', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003392', 'source-doc-4c784a84a66adf221597', 'source-node-003391', '7', '3391', 'text', '合理密植：根据番茄品种和土壤肥力合理确定种植密度，一般每亩种植 2000 - 3000 株。保证植株间通风透光良好，避免种植过密导致田间湿度增加。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003393', 'source-doc-4c784a84a66adf221597', 'source-node-003391', '7', '3392', 'text', '科学施肥：施足基肥，增施磷、钾肥，促进根系发育。例如，基肥可以每亩施用过磷酸钙 50 - 100 千克、硫酸钾 15 - 20 千克。在番茄生长过程中，要注意控制氮肥用量，避免植株徒长，使根系健壮，增强植株的抗病能力。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003394', 'source-doc-4c784a84a66adf221597', 'source-node-003391', '7', '3393', 'text', '水分管理：采用滴灌或沟灌等合理的灌溉方式，避免大水漫灌。注意及时排水，防止田间积水。在雨后要及时检查田间排水情况，如有积水，要及时疏通沟渠。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003395', 'source-doc-4c784a84a66adf221597', 'source-node-003385', '5', '3394', 'text', '（二）化学防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003396', 'source-doc-4c784a84a66adf221597', 'source-node-003395', '6', '3395', 'text', '土壤消毒', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003397', 'source-doc-4c784a84a66adf221597', 'source-node-003396', '7', '3396', 'text', '在种植前，可以对土壤进行消毒处理。常用的药剂有 50% 多菌灵可湿性粉剂，按照每亩 3 - 5 千克的用量与细土拌匀，撒施在土壤表面，然后进行翻耕。或者用 40% 五氯硝基苯粉剂，每亩用量 1 - 2 千克，同样与细土混合后撒施。这些药剂可以杀死土壤中的部分病原菌。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003398', 'source-doc-4c784a84a66adf221597', 'source-node-003395', '6', '3397', 'text', '药剂灌根', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003399', 'source-doc-4c784a84a66adf221597', 'source-node-003398', '7', '3398', 'text', '当发现植株出现根腐病症状时，可采用药剂灌根的方法进行防治。可选用 30% 甲霜・恶霉灵水剂 1000 - 1500 倍液（甲霜灵主要成分能抑制病原菌的 RNA 合成，恶霉灵主要成分可以抑制病原菌的菌丝生长）、50% 氯溴异氰尿酸可溶性粉剂 1000 - 1500 倍液（氯溴异氰尿酸主要成分分解产生的次氯酸和次溴酸具有强氧化性，能杀灭病原菌）。还有多菌灵、甲霜灵・锰锌，每株灌药量为 200 - 300 毫升，每隔 7 - 10 天灌一次，连续灌 2 - 3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003400', 'source-doc-4c784a84a66adf221597', 'source-node-003398', '7', '3399', 'text', '喷施三乙膦酸铝、杀毒矾、霜霉威，土壤干燥可以灌', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003401', 'source-doc-4c784a84a66adf221597', 'source-node-003294', '3', '3400', 'text', '番茄绵腐病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003402', 'source-doc-4c784a84a66adf221597', 'source-node-003401', '4', '3401', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003403', 'source-doc-4c784a84a66adf221597', 'source-node-003402', '5', '3402', 'text', '果实发病为主，初为水浸状暗绿色斑，迅速扩大，果肉腐烂变软，表面生白色棉絮状霉层；叶片病斑暗绿色，水渍状，易脱落。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003404', 'source-doc-4c784a84a66adf221597', 'source-node-003401', '4', '3403', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003405', 'source-doc-4c784a84a66adf221597', 'source-node-003404', '5', '3404', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003406', 'source-doc-4c784a84a66adf221597', 'source-node-003401', '4', '3405', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003407', 'source-doc-4c784a84a66adf221597', 'source-node-003406', '5', '3406', 'text', '烟草疫霉（Phytophthoranicotianae），属于卵菌门疫霉属。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003408', 'source-doc-4c784a84a66adf221597', 'source-node-003401', '4', '3407', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003409', 'source-doc-4c784a84a66adf221597', 'source-node-003408', '5', '3408', 'text', '高温高湿（25-30℃、多雨）易爆发，通过风雨、灌溉水传播，果实成熟后期、低洼积水田块病重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003410', 'source-doc-4c784a84a66adf221597', 'source-node-003401', '4', '3409', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003411', 'source-doc-4c784a84a66adf221597', 'source-node-003410', '5', '3410', 'text', '农业防治：高垄栽培，及时摘除下部老叶，避免果实接触地面，雨后排水。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003412', 'source-doc-4c784a84a66adf221597', 'source-node-003410', '5', '3411', 'text', '化学防治：发病初期喷施嘧菌酯、霜脲・锰锌等药剂，重点喷洒果实。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003413', 'source-doc-4c784a84a66adf221597', 'source-node-003190', '2', '3412', 'text', '真菌性病害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003414', 'source-doc-4c784a84a66adf221597', 'source-node-003413', '3', '3413', 'text', '番茄早疫病（Alternaria solani）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003415', 'source-doc-4c784a84a66adf221597', 'source-node-003414', '4', '3414', 'text', '症状：叶片病斑圆形，褐色至黑褐色，具同心轮纹，边缘黄褐色；茎部病斑椭圆形，凹陷；果实病斑多在蒂部，圆形黑褐色，轮纹明显', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003416', 'source-doc-4c784a84a66adf221597', 'source-node-003415', '5', '3415', 'text', '叶片症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003417', 'source-doc-4c784a84a66adf221597', 'source-node-003416', '6', '3416', 'text', '发病初期，叶片上出现针尖大小的黑褐色圆形斑点，随后病斑逐渐扩大，直径可达 1 - 2 厘米。病斑边缘呈深褐色，中间为灰褐色，有同心轮纹，这是早疫病的典型特征。湿度大时，病斑上会生出黑色霉状物，这是病原菌的分生孢子梗和分生孢子。随着病情发展，病斑会相互连接，导致叶片枯黄、脱落。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003418', 'source-doc-4c784a84a66adf221597', 'source-node-003415', '5', '3417', 'text', '茎部症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003419', 'source-doc-4c784a84a66adf221597', 'source-node-003418', '6', '3418', 'text', '茎部受害时，病斑多发生在分枝处或茎节附近。最初为暗褐色的椭圆形或梭形病斑，稍凹陷。病斑扩大后，会环绕茎部，使茎部缢缩，导致上部植株枯萎。病斑上也会出现黑色霉层。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003420', 'source-doc-4c784a84a66adf221597', 'source-node-003415', '5', '3419', 'text', '果实症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003421', 'source-doc-4c784a84a66adf221597', 'source-node-003420', '6', '3420', 'text', '果实发病多从果蒂附近开始，初期为黑色圆形病斑，随后病斑扩大，可达果面的 1/3 - 1/2。病斑凹陷，质地变硬，有同心轮纹，上面同样会生出黑色霉状物。病果易脱落，严重影响果实的商品价值。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003422', 'source-doc-4c784a84a66adf221597', 'source-node-003414', '4', '3421', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003423', 'source-doc-4c784a84a66adf221597', 'source-node-003422', '5', '3422', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003424', 'source-doc-4c784a84a66adf221597', 'source-node-003414', '4', '3423', 'text', '病原：番茄早疫病又称轮纹病，是一种由链格孢属（Alternaria solani）真菌引起的常见番茄病害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003425', 'source-doc-4c784a84a66adf221597', 'source-node-003414', '4', '3424', 'text', '发病规律：病原菌以菌丝体或分生孢子在病残体或种子上越冬，在 20 - 25℃、湿度适宜时，分生孢子借气流、雨水传播，从气孔、皮孔或表皮侵入，植株生长衰弱、连作、偏施氮肥发病重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003426', 'source-doc-4c784a84a66adf221597', 'source-node-003425', '5', '3425', 'text', '病原菌来源与传播', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003427', 'source-doc-4c784a84a66adf221597', 'source-node-003426', '6', '3426', 'text', '在适宜的环境条件下，分生孢子通过气流、雨水飞溅等方式传播到番茄植株上，从气孔、伤口或直接穿透表皮侵入。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003428', 'source-doc-4c784a84a66adf221597', 'source-node-003425', '5', '3427', 'text', '发病条件', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003429', 'source-doc-4c784a84a66adf221597', 'source-node-003428', '6', '3428', 'text', '温度和湿度：早疫病适宜在温暖湿润的环境中发生。病原菌生长的适宜温度为 26 - 28℃，分生孢子萌发需要较高的湿度，相对湿度在 80% 以上有利于病害的发生。在连续阴雨天气、通风不良、植株茂密的情况下，病害容易流行。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003430', 'source-doc-4c784a84a66adf221597', 'source-node-003428', '6', '3429', 'text', '植株生长状况：种植密度过大、植株生长衰弱、缺肥等情况会增加植株的感病性。另外，番茄生长中后期，随着果实的生长发育，植株营养消耗较大，此时如果管理不当，也容易感染早疫病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003431', 'source-doc-4c784a84a66adf221597', 'source-node-003414', '4', '3430', 'text', '防治方法：发病初期，可选用 70% 代森锰锌可湿性粉剂 500 - 600 倍液、10% 苯醚甲环唑水分散粒剂 800 - 1000 倍液、戊唑醇等防治每 7 - 10 天喷 1 次，连续喷 2 - 3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003432', 'source-doc-4c784a84a66adf221597', 'source-node-003431', '5', '3431', 'text', '（一）农业防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003433', 'source-doc-4c784a84a66adf221597', 'source-node-003432', '6', '3432', 'text', '品种选择', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003434', 'source-doc-4c784a84a66adf221597', 'source-node-003433', '7', '3433', 'text', '选用抗病品种是防治番茄早疫病的有效措施。如 “佳粉 17 号”、“中蔬 4 号” 等品种对早疫病有一定的抗性。在种植前，可根据当地的病害发生情况和种植经验选择合适的品种。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003435', 'source-doc-4c784a84a66adf221597', 'source-node-003432', '6', '3434', 'text', '种子处理', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003436', 'source-doc-4c784a84a66adf221597', 'source-node-003435', '7', '3435', 'text', '种子可能携带病原菌，因此要进行种子处理。可以用 52℃温水浸种 30 分钟，或者用 0.3% - 0.5% 的硫酸铜溶液浸种 5 - 10 分钟，浸种后用清水冲洗干净，晾干后播种。这些方法可以杀死种子表面的病原菌。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003437', 'source-doc-4c784a84a66adf221597', 'source-node-003432', '6', '3436', 'text', '轮作倒茬', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003438', 'source-doc-4c784a84a66adf221597', 'source-node-003437', '7', '3437', 'text', '实行与非茄科作物轮作，轮作周期 3 - 4 年。例如与豆科、十字花科等作物轮作，可减少土壤中病原菌的积累，降低发病风险。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003439', 'source-doc-4c784a84a66adf221597', 'source-node-003432', '6', '3438', 'text', '栽培管理', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003440', 'source-doc-4c784a84a66adf221597', 'source-node-003439', '7', '3439', 'text', '合理密植：根据品种特性和土壤肥力合理确定种植密度。一般早熟品种每亩种植 3000 - 3500 株，中晚熟品种每亩种植 2500 - 3000 株，保证植株间通风透光良好。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003441', 'source-doc-4c784a84a66adf221597', 'source-node-003439', '7', '3440', 'text', '整枝打杈：及时进行整枝打杈，去除病叶、病枝和老叶，改善植株通风透光条件，减少病原菌滋生的机会。整枝打杈后的病残体要带出田外集中销毁。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003442', 'source-doc-4c784a84a66adf221597', 'source-node-003439', '7', '3441', 'text', '合理施肥：施足基肥，增施有机肥和磷、钾肥，提高植株的抗病能力。避免偏施氮肥，防止植株徒长。例如，基肥可以每亩施用腐熟农家肥 3000 - 5000 千克、过磷酸钙 50 - 100 千克、硫酸钾 15 - 20 千克。在番茄生长过程中，根据植株生长阶段适时追肥。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003443', 'source-doc-4c784a84a66adf221597', 'source-node-003439', '7', '3442', 'text', '土壤改良：保持土壤疏松、透气，排水良好。对于酸性土壤，可以适量施用石灰调节土壤酸碱度，抑制病原菌的生长。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003444', 'source-doc-4c784a84a66adf221597', 'source-node-003431', '5', '3443', 'text', '（二）化学防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003445', 'source-doc-4c784a84a66adf221597', 'source-node-003444', '6', '3444', 'text', '预防用药', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003446', 'source-doc-4c784a84a66adf221597', 'source-node-003445', '7', '3445', 'text', '在病害常发区或发病初期，可选用保护性杀菌剂进行预防。如 75% 百菌清可湿性粉剂 600 - 800 倍液（百菌清主要成分能抑制病原菌的孢子萌发和菌丝生长）、80% 代森锰锌可湿性粉剂 600 - 800 倍液（代森锰锌主要成分通过与病原菌反应，抑制其酶活性）。每隔 7 - 10 天喷一次，连续喷 2 - 3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003447', 'source-doc-4c784a84a66adf221597', 'source-node-003444', '6', '3446', 'text', '治疗用药', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003448', 'source-doc-4c784a84a66adf221597', 'source-node-003447', '7', '3447', 'text', '当发现病斑后，要及时选用治疗性杀菌剂进行防治。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003449', 'source-doc-4c784a84a66adf221597', 'source-node-003447', '7', '3448', 'text', '10% 苯醚甲环唑水分散粒剂 1000 - 1500 倍液：苯醚甲环唑主要成分能抑制病原菌的细胞色素 P450 酶活性，从而阻止病原菌的麦角甾醇合成，达到杀菌效果。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003450', 'source-doc-4c784a84a66adf221597', 'source-node-003447', '7', '3449', 'text', '50% 异菌脲可湿性粉剂 1000 - 1500 倍液：异菌脲主要成分是一种广谱杀菌剂，它可以抑制病原菌的蛋白质合成，对早疫病有良好的防治效果。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003451', 'source-doc-4c784a84a66adf221597', 'source-node-003447', '7', '3450', 'text', '70% 甲基硫菌灵可湿性粉剂 800 - 1000 倍液：甲基硫菌灵主要成分能干扰病原菌的细胞分裂，抑制菌丝生长。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003452', 'source-doc-4c784a84a66adf221597', 'source-node-003447', '7', '3451', 'text', '43% 戊唑醇悬浮剂 2000 - 3000 倍液：戊唑醇主要成分是一种三唑类杀菌剂，能抑制病原菌的麦角甾醇合成，影响细胞膜的完整性，从而达到杀菌的目的。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003453', 'source-doc-4c784a84a66adf221597', 'source-node-003431', '5', '3452', 'text', '（三）生物防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003454', 'source-doc-4c784a84a66adf221597', 'source-node-003453', '6', '3453', 'text', '拮抗微生物利用', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003455', 'source-doc-4c784a84a66adf221597', 'source-node-003454', '7', '3454', 'text', '利用木霉菌（Trichoderma spp.）来防治番茄早疫病。木霉菌可以在土壤和植株表面定殖，与病原菌竞争营养和空间，并且能够分泌几丁质酶等抗菌物质分解病原菌的细胞壁。按照产品说明将木霉菌制剂施用于土壤或植株表面，可以减轻病害。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003456', 'source-doc-4c784a84a66adf221597', 'source-node-003453', '6', '3455', 'text', '植物源杀菌剂应用', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003457', 'source-doc-4c784a84a66adf221597', 'source-node-003456', '7', '3456', 'text', '有些植物源药剂如印楝素，从印楝树中提取。将印楝素制剂按照推荐浓度稀释后进行喷雾，它可以干扰病原菌的生理功能，对番茄早疫病有一定的防治作用，并且对环境友好，不易使病原菌产生抗药性。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003458', 'source-doc-4c784a84a66adf221597', 'source-node-003413', '3', '3457', 'text', '番茄灰霉病（Botrytis cinerea）：同辣椒灰霉病规律、防治方法类似。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003459', 'source-doc-4c784a84a66adf221597', 'source-node-003458', '4', '3458', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003460', 'source-doc-4c784a84a66adf221597', 'source-node-003459', '5', '3459', 'text', '花器受害症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003461', 'source-doc-4c784a84a66adf221597', 'source-node-003460', '6', '3460', 'text', '病害通常先从残留的花瓣、柱头或花托侵染，发病初期，这些部位出现水渍状淡褐色病斑。随着病情发展，病斑逐渐扩大，变为褐色，表面长出一层鼠灰色霉层，这是病原菌的分生孢子梗和分生孢子。花朵受害后，花瓣腐烂、枯萎，进而向果实和茎部蔓延。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003462', 'source-doc-4c784a84a66adf221597', 'source-node-003459', '5', '3461', 'text', '果实受害症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003463', 'source-doc-4c784a84a66adf221597', 'source-node-003462', '6', '3462', 'text', '幼果染病多从果蒂开始，最初为水渍状、淡褐色小斑点，随后病斑迅速扩展，可环绕果蒂一周。果实稍大时发病，病斑多在果脐、果柄或果面出现，病斑圆形或椭圆形，颜色加深为褐色至暗褐色，病部组织软腐，果皮易破裂。湿度大时，病果表面长满灰色霉层，病果最后脱落或失水僵化。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003464', 'source-doc-4c784a84a66adf221597', 'source-node-003459', '5', '3463', 'text', '叶片受害症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003465', 'source-doc-4c784a84a66adf221597', 'source-node-003464', '6', '3464', 'text', '叶片发病多从叶尖或叶缘开始，初期为水渍状、浅褐色病斑，病斑呈 “V” 字形向内扩展，这是因为叶尖和叶缘的水分和养分比较充足，有利于病原菌的生长。后期病斑颜色变深，呈褐色至暗褐色，边缘有深浅相间的轮纹。湿度高时，病斑表面产生灰色霉层。严重时，多个病斑相连，导致叶片干枯、坏死。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003466', 'source-doc-4c784a84a66adf221597', 'source-node-003459', '5', '3465', 'text', '茎部受害症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003467', 'source-doc-4c784a84a66adf221597', 'source-node-003466', '6', '3466', 'text', '茎部染病初期，出现水渍状小斑点，随后病斑扩展成长椭圆形或长条形，颜色为淡褐色至褐色。病斑可环绕茎部，使茎部缢缩，上部叶片因水分和养分运输受阻而枯萎。在病斑表面也会产生灰色霉层，严重时茎部腐烂、折断。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003468', 'source-doc-4c784a84a66adf221597', 'source-node-003458', '4', '3467', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003469', 'source-doc-4c784a84a66adf221597', 'source-node-003468', '5', '3468', 'text', '番茄灰霉病是由灰葡萄孢菌（Botrytis cinerea）引起的一种真菌性病害。这种病害在全球番茄种植区广泛分布，是保护地番茄生产中的主要病害之一，对番茄的产量和品质造成严重的损害。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003470', 'source-doc-4c784a84a66adf221597', 'source-node-003458', '4', '3469', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003471', 'source-doc-4c784a84a66adf221597', 'source-node-003470', '5', '3470', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003472', 'source-doc-4c784a84a66adf221597', 'source-node-003458', '4', '3471', 'text', '发病规律：以菌核在土壤或病残体越冬，20 - 23℃、相对湿度 90% 以上发病，花期侵染风险高。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003473', 'source-doc-4c784a84a66adf221597', 'source-node-003472', '5', '3472', 'text', '病原菌存活与传播', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003474', 'source-doc-4c784a84a66adf221597', 'source-node-003473', '6', '3473', 'text', '病原菌主要以菌核在土壤中或病残体上越冬，也可以菌丝体及分生孢子在病残体和其他有机物上存活。在适宜的环境条件下，菌核萌发产生菌丝体和分生孢子，分生孢子通过气流、雨水、灌溉水、农事操作（如整枝、打杈、采摘等）等方式传播到番茄植株上，成为初侵染源。病原菌可以从植株的伤口（如机械损伤、虫咬伤口等）、自然孔口（如气孔、皮孔等）或衰弱的组织部位侵入。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003475', 'source-doc-4c784a84a66adf221597', 'source-node-003472', '5', '3474', 'text', '发病条件', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003476', 'source-doc-4c784a84a66adf221597', 'source-node-003475', '6', '3475', 'text', '温度和湿度：灰霉病是一种典型的低温高湿型病害。病原菌生长和孢子萌发的适宜温度为 18 - 23℃，相对湿度在 90% 以上。在这种环境下，病原菌繁殖迅速，病害容易发生和流行。因此，在冬春季节的温室大棚内，由于温度较低、湿度较大，以及通风不良等因素，灰霉病容易大面积爆发。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003477', 'source-doc-4c784a84a66adf221597', 'source-node-003475', '6', '3476', 'text', '植株生长状况：种植密度过大、植株生长茂密、通风透光差、植株生长衰弱（如营养不良、受冻害等）等情况都有利于病害的发生。此外，番茄开花期和幼果期是灰霉病的侵染高峰期，因为这两个时期花器和幼果的组织比较幼嫩，抵抗力较弱。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003478', 'source-doc-4c784a84a66adf221597', 'source-node-003458', '4', '3477', 'text', '防治方法：花期选 40% 嘧霉胺悬浮剂等喷雾，重点喷花和幼果。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003479', 'source-doc-4c784a84a66adf221597', 'source-node-003478', '5', '3478', 'text', '（一）农业防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003480', 'source-doc-4c784a84a66adf221597', 'source-node-003479', '6', '3479', 'text', '品种选择', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003481', 'source-doc-4c784a84a66adf221597', 'source-node-003480', '7', '3480', 'text', '选用抗病品种是防治灰霉病的重要措施之一。一些抗灰霉病的番茄品种在种植过程中发病相对较轻，例如 “仙客 1 号”、“佳粉 15 号” 等。在种植前，可以根据当地的种植环境和病害发生情况，选择合适的抗病品种。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003482', 'source-doc-4c784a84a66adf221597', 'source-node-003479', '6', '3481', 'text', '轮作倒茬', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003483', 'source-doc-4c784a84a66adf221597', 'source-node-003482', '7', '3482', 'text', '实行与非茄科作物轮作，轮作周期 3 - 4 年。通过轮作可以减少土壤中病原菌的积累，降低发病风险。例如与禾本科、豆科等作物轮作，打破病原菌的生存环境。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003484', 'source-doc-4c784a84a66adf221597', 'source-node-003479', '6', '3483', 'text', '栽培管理', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003485', 'source-doc-4c784a84a66adf221597', 'source-node-003484', '7', '3484', 'text', '合理密植：根据番茄品种和土壤肥力合理确定种植密度，一般每亩种植 2000 - 3000 株。保证植株间通风透光良好，降低田间湿度，减少病原菌滋生的机会。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003486', 'source-doc-4c784a84a66adf221597', 'source-node-003484', '7', '3485', 'text', '整枝打杈：及时进行整枝打杈，去除病叶、病枝、残花和病果，带出田外集中销毁。整枝打杈操作应在晴天进行，避免在阴雨天操作，防止病原菌传播。同时，在整枝打杈后，可以用 70% 甲基硫菌灵可湿性粉剂 500 - 800 倍液或 50% 多菌灵可湿性粉剂 400 - 600 倍液涂抹伤口，预防病原菌侵染。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003487', 'source-doc-4c784a84a66adf221597', 'source-node-003484', '7', '3486', 'text', '调节温湿度：在设施栽培中，要注意控制温湿度。白天温度保持在 25 - 28℃，夜间温度控制在 15 - 18℃，相对湿度控制在 70% - 80%。通过合理通风、覆盖地膜、控制浇水等措施来调节温湿度。例如，在晴天中午适当通风，降低空气湿度；采用滴灌或膜下暗灌的方式浇水，避免大水漫灌。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003488', 'source-doc-4c784a84a66adf221597', 'source-node-003484', '7', '3487', 'text', '合理施肥：施足基肥，增施有机肥和磷、钾肥，提高植株的抗病能力。避免偏施氮肥，防止植株徒长。例如，基肥可以每亩施用腐熟农家肥 3000 - 5000 千克、过磷酸钙 50 - 100 千克、硫酸钾 15 - 20 千克。在番茄生长过程中，根据植株生长阶段适时追肥，保证植株营养均衡。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003489', 'source-doc-4c784a84a66adf221597', 'source-node-003478', '5', '3488', 'text', '（二）化学防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003490', 'source-doc-4c784a84a66adf221597', 'source-node-003489', '6', '3489', 'text', '预防用药', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003491', 'source-doc-4c784a84a66adf221597', 'source-node-003490', '7', '3490', 'text', '在病害常发区或发病初期，可选用保护性杀菌剂进行预防。如 50% 福美双可湿性粉剂 600 - 800 倍液（福美双主要成分能抑制病原菌的酶活性，阻止其生长）、75% 百菌清可湿性粉剂 600 - 800 倍液（百菌清主要成分可抑制病原菌的孢子萌发和菌丝生长）。每隔 7 - 10 天喷一次，连续喷 2 - 3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003492', 'source-doc-4c784a84a66adf221597', 'source-node-003489', '6', '3491', 'text', '治疗用药', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003493', 'source-doc-4c784a84a66adf221597', 'source-node-003492', '7', '3492', 'text', '当发现病斑后，要及时选用治疗性杀菌剂进行防治。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003494', 'source-doc-4c784a84a66adf221597', 'source-node-003492', '7', '3493', 'text', '40% 嘧霉胺悬浮剂 800 - 1000 倍液：嘧霉胺主要成分是一种新型杀菌剂，它能抑制病原菌的蛋白质合成，对灰霉病有很好的防治效果。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003495', 'source-doc-4c784a84a66adf221597', 'source-node-003492', '7', '3494', 'text', '50% 异菌脲可湿性粉剂 1000 - 1500 倍液：异菌脲主要成分是一种广谱杀菌剂，通过抑制病原菌的细胞分裂和蛋白质合成来发挥作用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003496', 'source-doc-4c784a84a66adf221597', 'source-node-003492', '7', '3495', 'text', '50% 腐霉利可湿性粉剂 1000 - 1500 倍液：腐霉利主要成分能够干扰病原菌的细胞膜和细胞壁的合成，抑制其生长和繁殖。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003497', 'source-doc-4c784a84a66adf221597', 'source-node-003492', '7', '3496', 'text', '2.5% 咯菌腈悬浮剂 1000 - 1500 倍液：咯菌腈主要成分可以抑制病原菌的线粒体呼吸作用，从而达到杀菌的目的。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003498', 'source-doc-4c784a84a66adf221597', 'source-node-003478', '5', '3497', 'text', '（三）生物防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003499', 'source-doc-4c784a84a66adf221597', 'source-node-003498', '6', '3498', 'text', '拮抗微生物利用', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003500', 'source-doc-4c784a84a66adf221597', 'source-node-003499', '7', '3499', 'text', '利用木霉菌（Trichoderma spp.）防治番茄灰霉病。木霉菌可以在土壤和植株表面定殖，与病原菌竞争营养和空间，并且能够分泌几丁质酶等抗菌物质分解病原菌的细胞壁。例如，哈茨木霉菌制剂按照产品说明进行土壤处理或喷雾，可以有效抑制灰霉病的发生。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003501', 'source-doc-4c784a84a66adf221597', 'source-node-003498', '6', '3500', 'text', '植物源杀菌剂应用', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003502', 'source-doc-4c784a84a66adf221597', 'source-node-003501', '7', '3501', 'text', '应用植物源杀菌剂，如大蒜素。大蒜素是从大蒜中提取的天然抗菌物质，将其制剂按照推荐浓度稀释后进行喷雾，它可以破坏病原菌的细胞膜，干扰其生理功能，对灰霉病有一定的防治作用，并且对环境友好，不易使病原菌产生抗药性。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003503', 'source-doc-4c784a84a66adf221597', 'source-node-003498', '6', '3502', 'text', '如何有效防治番茄灰霉病？', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003504', 'source-doc-4c784a84a66adf221597', 'source-node-003503', '7', '3503', 'text', '预防用药', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003505', 'source-doc-4c784a84a66adf221597', 'source-node-003504', '8', '3504', 'text', '在病害常发区或发病初期，用保护性杀菌剂预防。如 50% 福美双可湿性粉剂 600 - 800 倍液（福美双主要成分抑制病原菌的酶活性）、75% 百菌清可湿性粉剂 600 - 800 倍液（百菌清主要成分抑制孢子萌发和菌丝生长）。每隔 7 - 10 天喷一次，连续喷 2 - 3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003506', 'source-doc-4c784a84a66adf221597', 'source-node-003503', '7', '3505', 'text', '治疗用药', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003507', 'source-doc-4c784a84a66adf221597', 'source-node-003506', '8', '3506', 'text', '发现病斑后，及时用治疗性杀菌剂防治。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003508', 'source-doc-4c784a84a66adf221597', 'source-node-003506', '8', '3507', 'text', '40% 嘧霉胺悬浮剂 800 - 1000 倍液：嘧霉胺主要成分抑制病原菌蛋白质合成，对灰霉病防治效果好。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003509', 'source-doc-4c784a84a66adf221597', 'source-node-003506', '8', '3508', 'text', '50% 异菌脲可湿性粉剂 1000 - 1500 倍液：异菌脲主要成分是广谱杀菌剂，抑制细胞分裂和蛋白质合成。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003510', 'source-doc-4c784a84a66adf221597', 'source-node-003506', '8', '3509', 'text', '50% 腐霉利可湿性粉剂 1000 - 1500 倍液：腐霉利主要成分干扰病原菌细胞膜和细胞壁合成。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003511', 'source-doc-4c784a84a66adf221597', 'source-node-003506', '8', '3510', 'text', '2.5% 咯菌腈悬浮剂 1000 - 1500 倍液：咯菌腈主要成分抑制病原菌线粒体呼吸作用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003512', 'source-doc-4c784a84a66adf221597', 'source-node-003498', '6', '3511', 'text', '番茄灰霉病和晚疫病的症状有哪些区别？', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003513', 'source-doc-4c784a84a66adf221597', 'source-node-003512', '7', '3512', 'text', '（一）叶片症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003514', 'source-doc-4c784a84a66adf221597', 'source-node-003513', '8', '3513', 'text', '灰霉病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003515', 'source-doc-4c784a84a66adf221597', 'source-node-003514', '9', '3514', 'text', '叶片发病多从叶尖或叶缘开始，初期为水渍状、浅褐色病斑，呈 “V” 字形向内扩展。后期病斑颜色变深，呈褐色至暗褐色，边缘有深浅相间的轮纹。湿度高时，病斑表面产生灰色霉层。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003516', 'source-doc-4c784a84a66adf221597', 'source-node-003513', '8', '3515', 'text', '晚疫病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003517', 'source-doc-4c784a84a66adf221597', 'source-node-003516', '9', '3516', 'text', '发病初期，叶片边缘或尖端出现不规则的暗绿色水渍状病斑，病斑迅速扩大，颜色逐渐变为褐色。湿度大时，病斑背面边缘会产生一圈白色霉层，这是病原菌的孢囊梗和孢子囊。病情发展后，病叶会逐渐枯萎、腐烂，最终脱落。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003518', 'source-doc-4c784a84a66adf221597', 'source-node-003512', '7', '3517', 'text', '（二）果实症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003519', 'source-doc-4c784a84a66adf221597', 'source-node-003518', '8', '3518', 'text', '灰霉病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003520', 'source-doc-4c784a84a66adf221597', 'source-node-003519', '9', '3519', 'text', '幼果染病多从果蒂开始，最初为水渍状、淡褐色小斑点，随后病斑迅速扩展，可环绕果蒂一周。果实稍大时发病，病斑多在果脐、果柄或果面出现，病斑圆形或椭圆形，颜色加深为褐色至暗褐色，病部组织软腐，果皮易破裂。湿度大时，病果表面长满灰色霉层，病果最后脱落或失水僵化。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003521', 'source-doc-4c784a84a66adf221597', 'source-node-003518', '8', '3520', 'text', '晚疫病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003522', 'source-doc-4c784a84a66adf221597', 'source-node-003521', '9', '3521', 'text', '果实染病多从青果近果柄处开始，初期为油渍状暗绿色病斑，后变为暗褐色至棕褐色，病斑稍凹陷，边缘不明显。在湿度高的环境下，病果表面也会产生白色霉层。病果后期会逐渐腐烂，失去商品价值。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003523', 'source-doc-4c784a84a66adf221597', 'source-node-003512', '7', '3522', 'text', '（三）茎部症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003524', 'source-doc-4c784a84a66adf221597', 'source-node-003523', '8', '3523', 'text', '灰霉病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003525', 'source-doc-4c784a84a66adf221597', 'source-node-003524', '9', '3524', 'text', '茎部染病初期，出现水渍状小斑点，随后病斑扩展成长椭圆形或长条形，颜色为淡褐色至褐色。病斑可环绕茎部，使茎部缢缩，上部叶片因水分和养分运输受阻而枯萎。在病斑表面也会产生灰色霉层，严重时茎部腐烂、折断。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003526', 'source-doc-4c784a84a66adf221597', 'source-node-003523', '8', '3525', 'text', '晚疫病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003527', 'source-doc-4c784a84a66adf221597', 'source-node-003526', '9', '3526', 'text', '茎部受害时，最初出现暗绿色或褐色的水渍状斑点，随后病斑会环绕茎部扩展。病斑稍凹陷，质地变软，严重时会导致茎部缢缩、折断，影响植株的水分和养分运输，使植株上部枯萎。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003528', 'source-doc-4c784a84a66adf221597', 'source-node-003498', '6', '3527', 'text', '番茄早疫病的传播途径是什么？', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003529', 'source-doc-4c784a84a66adf221597', 'source-node-003528', '7', '3528', 'text', '病原菌来源', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003530', 'source-doc-4c784a84a66adf221597', 'source-node-003529', '8', '3529', 'text', '病原菌主要以菌丝体和分生孢子在病残体或种子上越冬。种子带菌是病害远距离传播的一个重要途径，在种子发芽和幼苗生长过程中，病原菌会侵染植株。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003531', 'source-doc-4c784a84a66adf221597', 'source-node-003528', '7', '3530', 'text', '传播方式', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003532', 'source-doc-4c784a84a66adf221597', 'source-node-003531', '8', '3531', 'text', '分生孢子通过气流、雨水飞溅等方式传播到番茄植株上，从气孔、伤口或直接穿透表皮侵入。例如，在风雨天气后，植株上的水滴携带分生孢子，在植株间传播，或者农事操作造成的伤口也为病原菌的侵入提供了通道。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003533', 'source-doc-4c784a84a66adf221597', 'source-node-003413', '3', '3532', 'text', '番茄立枯病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003534', 'source-doc-4c784a84a66adf221597', 'source-node-003533', '4', '3533', 'text', '症状：苗期发病，茎基部产生椭圆形暗褐色病斑，逐渐凹陷、缢缩，植株直立枯死；湿度大时，病部生淡褐色蛛丝状霉层。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003535', 'source-doc-4c784a84a66adf221597', 'source-node-003533', '4', '3534', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003536', 'source-doc-4c784a84a66adf221597', 'source-node-003535', '5', '3535', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003537', 'source-doc-4c784a84a66adf221597', 'source-node-003533', '4', '3536', 'text', '病原：立枯丝核菌（Rhizoctoniasolani），属于半知菌门丝核菌属。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003538', 'source-doc-4c784a84a66adf221597', 'source-node-003533', '4', '3537', 'text', '发生规律：高温高湿（20-25℃、土壤潮湿）利于发病，土传病害，苗床连作、管理粗放时病重，通过农事操作、灌溉水传播。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003539', 'source-doc-4c784a84a66adf221597', 'source-node-003533', '4', '3538', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003540', 'source-doc-4c784a84a66adf221597', 'source-node-003539', '5', '3539', 'text', '农业防治：选用无病土育苗，苗床通风降湿，避免低温高湿环境。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003541', 'source-doc-4c784a84a66adf221597', 'source-node-003539', '5', '3540', 'text', '化学防治：播种前土壤拌施五氯硝基苯，发病后喷施井冈霉素、噻呋酰胺、甲基立枯磷等药剂。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003542', 'source-doc-4c784a84a66adf221597', 'source-node-003413', '3', '3541', 'text', '番茄镰刀根腐', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003543', 'source-doc-4c784a84a66adf221597', 'source-node-003542', '4', '3542', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003544', 'source-doc-4c784a84a66adf221597', 'source-node-003543', '5', '3543', 'text', '根部变黑腐烂，须根减少，植株萎蔫，叶片变黄脱落；茎基部无明显病变，维管束不变色。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003545', 'source-doc-4c784a84a66adf221597', 'source-node-003542', '4', '3544', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003546', 'source-doc-4c784a84a66adf221597', 'source-node-003545', '5', '3545', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003547', 'source-doc-4c784a84a66adf221597', 'source-node-003542', '4', '3546', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003548', 'source-doc-4c784a84a66adf221597', 'source-node-003547', '5', '3547', 'text', '茄镰孢（Fusariumsolani），属于半知菌门镰刀菌属。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003549', 'source-doc-4c784a84a66adf221597', 'source-node-003542', '4', '3548', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003550', 'source-doc-4c784a84a66adf221597', 'source-node-003549', '5', '3549', 'text', '土传病害，20-25℃、土壤潮湿或板结时发病重，连作、农事操作伤根后易诱发。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003551', 'source-doc-4c784a84a66adf221597', 'source-node-003542', '4', '3550', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003552', 'source-doc-4c784a84a66adf221597', 'source-node-003551', '5', '3551', 'text', '1）种子消毒。可用种子重量0.5%的2.5%咯菌腈悬浮剂拌种。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003553', 'source-doc-4c784a84a66adf221597', 'source-node-003551', '5', '3552', 'text', '2）加强栽培管理。及时放风降湿，地温低需及时松土，以提高地温，适当浇水，不易大水漫灌。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003554', 'source-doc-4c784a84a66adf221597', 'source-node-003551', '5', '3553', 'text', '3）合理施肥。基肥一般每亩用45%的三元复合肥50kg加腐熟有机肥1000kg。盛果期适时追肥，保持植株旺盛生长。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003555', 'source-doc-4c784a84a66adf221597', 'source-node-003551', '5', '3554', 'text', '4）药剂防治。幼苗定植时可用70%的噁霉灵可湿性粉剂2000倍液泡根15min。定植后发现病株可及时用20%的甲基立枯磷乳油1200倍液或30%的噁霉灵水剂500倍液进行喷淋或灌根，每穴用药液量200mL左右，连用3次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003556', 'source-doc-4c784a84a66adf221597', 'source-node-003413', '3', '3555', 'text', '番茄白绢病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003557', 'source-doc-4c784a84a66adf221597', 'source-node-003556', '4', '3556', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003558', 'source-doc-4c784a84a66adf221597', 'source-node-003557', '5', '3557', 'text', '茎基部现水渍状暗褐病斑，生白色绢状菌丝及黄褐色菌核，植株逐渐萎蔫枯死。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003559', 'source-doc-4c784a84a66adf221597', 'source-node-003556', '4', '3558', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003560', 'source-doc-4c784a84a66adf221597', 'source-node-003559', '5', '3559', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003561', 'source-doc-4c784a84a66adf221597', 'source-node-003556', '4', '3560', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003562', 'source-doc-4c784a84a66adf221597', 'source-node-003561', '5', '3561', 'text', '半知菌亚门齐整小核菌，以菌核在土壤/病残体越冬，存活5-6年，抗逆性强。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003563', 'source-doc-4c784a84a66adf221597', 'source-node-003556', '4', '3562', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003564', 'source-doc-4c784a84a66adf221597', 'source-node-003563', '5', '3563', 'text', '适宜温度25-30℃、高湿，酸性沙质土、连作田、通风差地块高发，借土壤、雨水传播，花期至结果期集中发病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003565', 'source-doc-4c784a84a66adf221597', 'source-node-003556', '4', '3564', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003566', 'source-doc-4c784a84a66adf221597', 'source-node-003565', '5', '3565', 'text', '轮作3年以上，生石灰调土pH7.0-7.5；清除病残体；定植前土壤消毒，发病初期用多菌灵等灌根；施用木霉菌、枯草芽孢杆菌。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003567', 'source-doc-4c784a84a66adf221597', 'source-node-003413', '3', '3566', 'text', '番茄枯萎病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003568', 'source-doc-4c784a84a66adf221597', 'source-node-003567', '4', '3567', 'text', '症状：苗期至成株期均可发病，植株萎蔫，叶片变黄脱落；茎基部纵剖，维管束呈褐色坏死；湿度大时茎基部生粉红色霉层。自下而上萎蔫黄化。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003569', 'source-doc-4c784a84a66adf221597', 'source-node-003567', '4', '3568', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003570', 'source-doc-4c784a84a66adf221597', 'source-node-003569', '5', '3569', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003571', 'source-doc-4c784a84a66adf221597', 'source-node-003567', '4', '3570', 'text', '病原：尖孢镰刀菌番茄专化型（Fusariumoxysporumf.sp.lycopersici），属于半知菌门镰刀菌属。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003572', 'source-doc-4c784a84a66adf221597', 'source-node-003567', '4', '3571', 'text', '发生规律：土传病害，25-30℃、土壤潮湿时发病重，连作、酸性土壤、线虫危害后易诱发，通过灌溉水、农事操作传播；枯萎病在成苗至成熟期发病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003573', 'source-doc-4c784a84a66adf221597', 'source-node-003567', '4', '3572', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003574', 'source-doc-4c784a84a66adf221597', 'source-node-003573', '5', '3573', 'text', '农业防治：与非茄科作物轮作4-5年，选用抗病品种，嫁接育苗（用野生番茄作砧木）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003575', 'source-doc-4c784a84a66adf221597', 'source-node-003573', '5', '3574', 'text', '化学防治：播种前土壤消毒（施多菌灵、甲基硫菌灵），发病初期用恶霉灵+中生菌素灌根。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003576', 'source-doc-4c784a84a66adf221597', 'source-node-003413', '3', '3575', 'text', '番茄黄萎病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003577', 'source-doc-4c784a84a66adf221597', 'source-node-003576', '4', '3576', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003578', 'source-doc-4c784a84a66adf221597', 'source-node-003577', '5', '3577', 'text', '成株期发病，叶片从下部开始变黄，逐渐向上蔓延，叶脉间黄化明显，后期叶片枯死；茎部纵剖，维管束呈黄褐色；植株矮化，结果减少。俗称半边疯。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003579', 'source-doc-4c784a84a66adf221597', 'source-node-003576', '4', '3578', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003580', 'source-doc-4c784a84a66adf221597', 'source-node-003579', '5', '3579', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003581', 'source-doc-4c784a84a66adf221597', 'source-node-003576', '4', '3580', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003582', 'source-doc-4c784a84a66adf221597', 'source-node-003581', '5', '3581', 'text', '大丽轮枝菌（Verticilliumdahliae），属于半知菌门轮枝菌属。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003583', 'source-doc-4c784a84a66adf221597', 'source-node-003576', '4', '3582', 'text', '发生规律：土传病害，20-25℃、土壤潮湿时发病重，连作、酸性土壤、线虫危害后易诱发，通过灌溉水、农事操作传播', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003584', 'source-doc-4c784a84a66adf221597', 'source-node-003576', '4', '3583', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003585', 'source-doc-4c784a84a66adf221597', 'source-node-003584', '5', '3584', 'text', '农业防治：与禾本科作物轮作4-5年，选用抗病品种，嫁接育苗。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003586', 'source-doc-4c784a84a66adf221597', 'source-node-003584', '5', '3585', 'text', '化学防治：播种前土壤消毒（施甲基硫菌灵），发病初期用恶霉灵+多菌灵灌根。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003587', 'source-doc-4c784a84a66adf221597', 'source-node-003413', '3', '3586', 'text', '番茄叶霉病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003588', 'source-doc-4c784a84a66adf221597', 'source-node-003587', '4', '3587', 'text', '症状：主要危害叶片，叶面出现淡黄色不规则斑，叶背生淡褐色至紫黑色致密霉层；严重时叶片卷曲脱落，果实表面生黑色霉斑。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003589', 'source-doc-4c784a84a66adf221597', 'source-node-003587', '4', '3588', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003590', 'source-doc-4c784a84a66adf221597', 'source-node-003589', '5', '3589', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003591', 'source-doc-4c784a84a66adf221597', 'source-node-003587', '4', '3590', 'text', '病原：黄褐孢霉菌（Fulviafulva），属于半知菌门褐孢霉属。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003592', 'source-doc-4c784a84a66adf221597', 'source-node-003587', '4', '3591', 'text', '发生规律：高温高湿（20-25℃、相对湿度>90%）易爆发，通过气流、农事操作传播，棚室栽培通风差时发病重', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003593', 'source-doc-4c784a84a66adf221597', 'source-node-003587', '4', '3592', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003594', 'source-doc-4c784a84a66adf221597', 'source-node-003593', '5', '3593', 'text', '农业防治：选用抗病品种，棚室及时通风降湿，清洁田园，摘除下部老叶。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003595', 'source-doc-4c784a84a66adf221597', 'source-node-003593', '5', '3594', 'text', '化学防治：发病初期喷施嘧菌酯、醚菌酯、氟喹唑、苯醚甲环唑、多·霉威、烯唑醇、噻菌灵等药剂，连喷2-3次，间隔7-10天。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003596', 'source-doc-4c784a84a66adf221597', 'source-node-003413', '3', '3595', 'text', '番茄煤污病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003597', 'source-doc-4c784a84a66adf221597', 'source-node-003596', '4', '3596', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003598', 'source-doc-4c784a84a66adf221597', 'source-node-003597', '5', '3597', 'text', '叶片生暗褐色至黑色霉层，初期叶面零星分布，后期布满全叶；叶片变黄干枯，影响光合作用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003599', 'source-doc-4c784a84a66adf221597', 'source-node-003596', '4', '3598', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003600', 'source-doc-4c784a84a66adf221597', 'source-node-003599', '5', '3599', 'text', '枝孢属真菌（Cladosporiumspp.）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003601', 'source-doc-4c784a84a66adf221597', 'source-node-003596', '4', '3600', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003602', 'source-doc-4c784a84a66adf221597', 'source-node-003601', '5', '3601', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003603', 'source-doc-4c784a84a66adf221597', 'source-node-003596', '4', '3602', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003604', 'source-doc-4c784a84a66adf221597', 'source-node-003603', '5', '3603', 'text', '高温高湿（25-30℃、相对湿度>90%）利于发病，通过气流传播，棚室通风差、植株徒长时病重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003605', 'source-doc-4c784a84a66adf221597', 'source-node-003596', '4', '3604', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003606', 'source-doc-4c784a84a66adf221597', 'source-node-003605', '5', '3605', 'text', '农业防治：通风降湿，合理密植，避免偏施氮肥，清洁田园。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003607', 'source-doc-4c784a84a66adf221597', 'source-node-003605', '5', '3606', 'text', '化学防治：发病初期喷施多菌灵、甲基硫菌灵等药剂，叶片正反面均匀喷雾。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003608', 'source-doc-4c784a84a66adf221597', 'source-node-003413', '3', '3607', 'text', '番茄白粉病（Leveillula taurica）：同辣椒白粉病防治思路相近。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003609', 'source-doc-4c784a84a66adf221597', 'source-node-003608', '4', '3608', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003610', 'source-doc-4c784a84a66adf221597', 'source-node-003609', '5', '3609', 'text', '叶片症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003611', 'source-doc-4c784a84a66adf221597', 'source-node-003610', '6', '3610', 'text', '发病初期，叶片正面或背面出现白色小粉点，这些粉点逐渐扩大，形成边缘不明显的白色粉斑。随着病情的发展，粉斑会布满整个叶片，使叶片表面好像覆盖了一层白色粉末。严重时，叶片会变脆、变硬，失去光泽，并且从叶尖或叶缘开始逐渐变黄、干枯，但一般不会脱落。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003612', 'source-doc-4c784a84a66adf221597', 'source-node-003609', '5', '3611', 'text', '茎部症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003613', 'source-doc-4c784a84a66adf221597', 'source-node-003612', '6', '3612', 'text', '茎部发病时，表面也会出现白色粉状霉层，通常在茎的节间和叶柄基部较为明显。白粉层下的茎组织初期无明显变化，随着病害的加重，茎部可能会出现褐色的坏死斑点或条纹，影响植株的生长和养分运输。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003614', 'source-doc-4c784a84a66adf221597', 'source-node-003609', '5', '3613', 'text', '果实症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003615', 'source-doc-4c784a84a66adf221597', 'source-node-003614', '6', '3614', 'text', '果实受害相对较晚，主要在果面出现白色粉斑，粉斑扩大后会覆盖部分或整个果实表面。病果的生长会受到抑制，变得瘦小，而且果实的口感和品质也会下降。在湿度较高的情况下，白粉病斑上可能会出现黑色的小颗粒，这是病原菌的闭囊壳。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003616', 'source-doc-4c784a84a66adf221597', 'source-node-003608', '4', '3615', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003617', 'source-doc-4c784a84a66adf221597', 'source-node-003616', '5', '3616', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003618', 'source-doc-4c784a84a66adf221597', 'source-node-003608', '4', '3617', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003619', 'source-doc-4c784a84a66adf221597', 'source-node-003618', '5', '3618', 'text', '鞑靼内丝白粉菌（Leveillulataurica），属于子囊菌门内丝白粉菌属。番茄白粉病是由真菌中的鞑靼内丝白粉菌（Leveillula taurica）和新番茄粉孢菌（Oidium neolycopersici）引起的一种常见病害。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003620', 'source-doc-4c784a84a66adf221597', 'source-node-003608', '4', '3619', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003621', 'source-doc-4c784a84a66adf221597', 'source-node-003620', '5', '3620', 'text', '这种病害在番茄生长的各个阶段都可能发生，尤其在温室栽培和植株生长中后期较为严重，会对番茄的产量和品质造成显著影响，高温干旱（25-30℃、相对湿度40%-60%）利于发病，通过气流传播，植株徒长、通风差时病重。病原菌以菌丝体或闭囊壳在病残体、温室大棚的骨架及墙壁上越冬。在适宜的环境条件下，闭囊壳释放出子囊孢子，菌丝体也会产生分生孢子，这些孢子通过气流传播到番茄植株上，成为初侵染源。一旦在植株上成功侵染，病原菌会在植株上不断产生分生孢子进行再侵染。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003622', 'source-doc-4c784a84a66adf221597', 'source-node-003620', '5', '3621', 'text', '温度和湿度：白粉病在相对湿度 25% - 85% 都能发生，一般在温暖、干燥的气候条件下发病较重。适宜的温度范围是 20 - 25℃，在这个温度区间内，病原菌的分生孢子萌发和菌丝生长较为旺盛。不过，在湿度较低时，虽然白粉病仍能发生，但高湿度环境会使病情发展更为迅速。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003623', 'source-doc-4c784a84a66adf221597', 'source-node-003620', '5', '3622', 'text', '植株生长状况：种植密度过大、通风不良、光照不足、植株生长衰弱等情况会增加植株的感病性。此外，氮肥施用过多导致植株徒长，也会使植株更容易受到白粉病的侵害。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003624', 'source-doc-4c784a84a66adf221597', 'source-node-003608', '4', '3623', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003625', 'source-doc-4c784a84a66adf221597', 'source-node-003624', '5', '3624', 'text', '预防方法：抗病品种，合理密植，增施有机肥和磷钾肥，清理病残株。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003626', 'source-doc-4c784a84a66adf221597', 'source-node-003625', '6', '3625', 'text', '环境控制：规避高温干燥，必要时增加湿度，减少叶片损伤。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003627', 'source-doc-4c784a84a66adf221597', 'source-node-003625', '6', '3626', 'text', '营养调节：通过 S - 诱抗素、氟唑菌酰羟胺、氟唑菌酰胺、增产胺、氨基酸、谷氨酸、脯氨酸及含锰微量元素等，防止叶片早衰。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003628', 'source-doc-4c784a84a66adf221597', 'source-node-003625', '6', '3627', 'text', '合理密植：根据番茄品种的特性和土壤肥力合理确定种植密度，一般每亩种植 2000 - 3000 株。保证植株间通风透光良好，降低田间湿度，减少病原菌滋生的机会。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003629', 'source-doc-4c784a84a66adf221597', 'source-node-003625', '6', '3628', 'text', '整枝打杈：及时进行整枝打杈，去除病叶、病枝和老叶，改善植株的通风透光条件。整枝打杈后的病残体要带出田外集中销毁，防止病原菌传播。同时，注意操作工具的消毒，避免在操作过程中传播病原菌。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003630', 'source-doc-4c784a84a66adf221597', 'source-node-003625', '6', '3629', 'text', '合理施肥：施足基肥，增施有机肥和磷、钾肥，避免偏施氮肥，使植株生长健壮，增强植株的抗病能力。例如，基肥可以每亩施用腐熟农家肥 3000 - 5000 千克、过磷酸钙 50 - 100 千克、硫酸钾 15 - 20 千克。在番茄生长过程中，根据植株生长阶段适时追肥。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003631', 'source-doc-4c784a84a66adf221597', 'source-node-003625', '6', '3630', 'text', '清洁田园：在番茄收获后，及时清除田间的病残体、杂草等，对温室大棚进行彻底的清洁和消毒，包括清扫墙壁、骨架和地面，减少病原菌的越冬场所。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003632', 'source-doc-4c784a84a66adf221597', 'source-node-003624', '5', '3631', 'text', '化学防治：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003633', 'source-doc-4c784a84a66adf221597', 'source-node-003632', '6', '3632', 'text', '预防用药：在病害常发区或发病初期，可选用保护性杀菌剂进行预防。如 75% 百菌清可湿性粉剂 600 - 800 倍液（主要成分百菌清能抑制病原菌的孢子萌发和菌丝生长）、80% 代森锰锌可湿性粉剂 600 - 800 倍液（代森锰锌主要成分通过与病原菌反应，抑制其酶活性）。每隔 7 - 10 天喷一次，连续喷 2 - 3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003634', 'source-doc-4c784a84a66adf221597', 'source-node-003632', '6', '3633', 'text', '治疗用药：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003635', 'source-doc-4c784a84a66adf221597', 'source-node-003634', '7', '3634', 'text', '发病初期选用醚菌酯、吡唑醚菌酯、乙嘧酚磺酸酯、四氟醚唑、苯醚甲环唑、苯菌酮等杀菌剂、苯菌酮、乙醚酚等，其中吡唑醚菌酯兼具预防和辅助治疗作用，需配合其他药剂快速杀菌，也可复配使用。注意叶片正反面均匀喷雾。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003636', 'source-doc-4c784a84a66adf221597', 'source-node-003634', '7', '3635', 'text', '吡唑醚菌酯 + 氟唑菌酰羟胺 + 增产胺 + 复合微量元素（或单喷含锰的）+ 谷氨酸 / 脯氨酸，配合 S - 诱抗素。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003637', 'source-doc-4c784a84a66adf221597', 'source-node-003634', '7', '3636', 'text', '10% 苯醚甲环唑水分散粒剂 1000 - 1500 倍液：苯醚甲环唑主要成分能抑制病原菌的细胞色素 P450 酶活性，阻止病原菌的麦角甾醇合成，达到杀菌效果。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003638', 'source-doc-4c784a84a66adf221597', 'source-node-003634', '7', '3637', 'text', '25% 乙嘧酚悬浮剂 1000 - 1500 倍液：乙嘧酚主要成分是一种高效的杀菌剂，它可以抑制病原菌的蛋白质合成，对番茄白粉病有良好的防治效果。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003639', 'source-doc-4c784a84a66adf221597', 'source-node-003634', '7', '3638', 'text', '40% 氟硅唑乳油 8000 - 10000 倍液：氟硅唑主要成分能干扰病原菌的细胞膜合成，抑制菌丝生长，从而控制病害。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003640', 'source-doc-4c784a84a66adf221597', 'source-node-003634', '7', '3639', 'text', '50% 醚菌酯干悬浮剂 3000 - 4000 倍液：醚菌酯主要成分可以抑制病原菌的呼吸作用，对防治白粉病有很好的效果。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003641', 'source-doc-4c784a84a66adf221597', 'source-node-003413', '3', '3640', 'text', '番茄炭疽病（Colletotrichum spp.）：与辣椒炭疽病类似。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003642', 'source-doc-4c784a84a66adf221597', 'source-node-003641', '4', '3641', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003643', 'source-doc-4c784a84a66adf221597', 'source-node-003642', '5', '3642', 'text', '果实症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003644', 'source-doc-4c784a84a66adf221597', 'source-node-003643', '6', '3643', 'text', '果实发病为主，表面生圆形淡褐色病斑，逐渐扩大并凹陷，具同心轮纹，湿度大时病斑上生粉红色黏质小点；叶片病斑圆形，褐色，边缘黄晕。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003645', 'source-doc-4c784a84a66adf221597', 'source-node-003643', '6', '3644', 'text', '果实症状，发病初期，果实表面出现水渍状、褐色小斑点，这些小斑点会逐渐扩大成圆形或近圆形的病斑。病斑直径一般在 1 - 2 厘米左右，稍凹陷，颜色变为深褐色至黑色，边缘有明显的同心轮纹。在病斑中央，常出现黑色的小点，这是病原菌的分生孢子盘。随着病情的发展，病果的果肉会逐渐腐烂，湿度大时，病斑上会产生粉红色的黏质物，这是病原菌的分生孢子团。病果最后会干缩、僵化，挂在植株上或脱落。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003646', 'source-doc-4c784a84a66adf221597', 'source-node-003642', '5', '3645', 'text', '叶片症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003647', 'source-doc-4c784a84a66adf221597', 'source-node-003646', '6', '3646', 'text', '叶片染病相对较少，一般在叶尖或叶缘出现褐色病斑，病斑形状不规则，大小不一。病斑有时会呈现出 “V” 字形扩展，与番茄早疫病的叶片症状有些相似，但炭疽病的病斑颜色更深，且在湿度大时，病斑上也会出现黑色小点和粉红色黏质物。严重时，叶片会枯萎、脱落。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003648', 'source-doc-4c784a84a66adf221597', 'source-node-003642', '5', '3647', 'text', '茎部症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003649', 'source-doc-4c784a84a66adf221597', 'source-node-003648', '6', '3648', 'text', '茎部发病时，会出现椭圆形或长条形的褐色病斑，病斑稍凹陷。病情较重时，病斑会环绕茎部，导致茎部缢缩，影响植株的水分和养分运输，使上部植株出现萎蔫现象。在病斑表面同样会出现黑色小点。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003650', 'source-doc-4c784a84a66adf221597', 'source-node-003641', '4', '3649', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003651', 'source-doc-4c784a84a66adf221597', 'source-node-003650', '5', '3650', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003652', 'source-doc-4c784a84a66adf221597', 'source-node-003641', '4', '3651', 'text', '病原：由果腐刺盘孢菌（Colletotrichum phomoides）和辣椒炭疽菌（Colletotrichum capsici）、胶孢炭疽菌（Colletotrichumgloeosporioides），属于半知菌门炭疽菌属。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003653', 'source-doc-4c784a84a66adf221597', 'source-node-003641', '4', '3652', 'text', '发病规律：种子、病残体带菌越冬，27℃左右、高湿时，分生孢子传播侵染，高温多雨、田间郁闭加重，可以通过风雨、昆虫传播，果实成熟前后发病重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003654', 'source-doc-4c784a84a66adf221597', 'source-node-003653', '5', '3653', 'text', '病原菌来源与传播', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003655', 'source-doc-4c784a84a66adf221597', 'source-node-003654', '6', '3654', 'text', '病原菌主要以菌丝体和分生孢子盘在病残体上越冬，也可以在种子上潜伏。在适宜的环境条件下，分生孢子盘产生分生孢子，通过雨水飞溅、灌溉水、昆虫活动以及农事操作等方式传播到番茄植株上。病原菌从果实的伤口（如机械损伤、日灼伤口等）或自然孔口（如气孔、皮孔等）侵入，引起初次侵染。发病后的病果、病叶和病茎上产生的分生孢子又可进行再次侵染。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003656', 'source-doc-4c784a84a66adf221597', 'source-node-003653', '5', '3655', 'text', '发病条件', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003657', 'source-doc-4c784a84a66adf221597', 'source-node-003656', '6', '3656', 'text', '温度和湿度：番茄炭疽病是一种高温高湿型病害。病原菌生长和孢子萌发的适宜温度为 24 - 29℃，相对湿度在 95% 以上时最有利于病害的发生和发展。在多雨潮湿的季节、种植密度过大、通风不良的环境中，病害容易流行。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003658', 'source-doc-4c784a84a66adf221597', 'source-node-003656', '6', '3657', 'text', '植株生长状况：植株生长衰弱、果实发育不良、施肥不当（如氮肥过多、磷钾肥不足）等情况会增加植株的感病性。此外，果实接近成熟时，由于糖分积累，组织变软，更容易受到病原菌的侵染。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003659', 'source-doc-4c784a84a66adf221597', 'source-node-003641', '4', '3658', 'text', '防治方法：发病初期选甲基托布津、炭疽福美等喷雾。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003660', 'source-doc-4c784a84a66adf221597', 'source-node-003659', '5', '3659', 'text', '农业防治：种子处理，合理施肥，摘除病果病叶。轮作2年以上，及时清除病果，避免果实损伤。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003661', 'source-doc-4c784a84a66adf221597', 'source-node-003659', '5', '3660', 'text', '化学防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003662', 'source-doc-4c784a84a66adf221597', 'source-node-003661', '6', '3661', 'text', '预防用药', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003663', 'source-doc-4c784a84a66adf221597', 'source-node-003662', '7', '3662', 'text', '在病害常发区或发病初期，可选用保护性杀菌剂进行预防。如 75% 百菌清可湿性粉剂 600 - 800 倍液（百菌清主要成分能抑制病原菌的孢子萌发和菌丝生长）、80% 代森锰锌可湿性粉剂 600 - 800 倍液（代森锰锌主要成分通过与病原菌反应，抑制其酶活性）。每隔 7 - 10 天喷一次，连续喷 2 - 3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003664', 'source-doc-4c784a84a66adf221597', 'source-node-003662', '7', '3663', 'text', '发病前喷施代森锰锌预防，发病后用苯醚甲环唑、咪鲜胺等药剂防治。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003665', 'source-doc-4c784a84a66adf221597', 'source-node-003661', '6', '3664', 'text', '治疗用药', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003666', 'source-doc-4c784a84a66adf221597', 'source-node-003665', '7', '3665', 'text', '当发现病斑后，要及时选用治疗性杀菌剂进行防治。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003667', 'source-doc-4c784a84a66adf221597', 'source-node-003665', '7', '3666', 'text', '25% 咪鲜胺乳油 1000 - 1500 倍液：咪鲜胺主要成分是一种广谱杀菌剂，它可以抑制病原菌的麦角甾醇合成，对番茄炭疽病有良好的防治效果。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003668', 'source-doc-4c784a84a66adf221597', 'source-node-003665', '7', '3667', 'text', '50% 多菌灵可湿性粉剂 500 - 800 倍液：多菌灵主要成分能干扰病原菌的细胞分裂，抑制菌丝生长。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003669', 'source-doc-4c784a84a66adf221597', 'source-node-003665', '7', '3668', 'text', '70% 甲基硫菌灵可湿性粉剂 800 - 1000 倍液：甲基硫菌灵主要成分可以抑制病原菌的细胞分裂和蛋白质合成。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003670', 'source-doc-4c784a84a66adf221597', 'source-node-003665', '7', '3669', 'text', '40% 炭疽福美可湿性粉剂 600 - 800 倍液：炭疽福美主要成分对病原菌有抑制和杀菌作用，能有效控制炭疽病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003671', 'source-doc-4c784a84a66adf221597', 'source-node-003413', '3', '3670', 'text', '番茄菌核病（Sclerotinia sclerotiorum）：同辣椒菌核病规律、防治相近。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003672', 'source-doc-4c784a84a66adf221597', 'source-node-003671', '4', '3671', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003673', 'source-doc-4c784a84a66adf221597', 'source-node-003672', '5', '3672', 'text', '茎基部、叶柄或果实发病，初为水浸状褐色斑，后长出白色棉絮状菌丝，逐渐形成黑色鼠粪状菌核；植株萎蔫枯死，果实腐烂。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003674', 'source-doc-4c784a84a66adf221597', 'source-node-003671', '4', '3673', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003675', 'source-doc-4c784a84a66adf221597', 'source-node-003674', '5', '3674', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003676', 'source-doc-4c784a84a66adf221597', 'source-node-003671', '4', '3675', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003677', 'source-doc-4c784a84a66adf221597', 'source-node-003676', '5', '3676', 'text', '核盘菌（Sclerotiniasclerotiorum），属于子囊菌门核盘菌属。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003678', 'source-doc-4c784a84a66adf221597', 'source-node-003671', '4', '3677', 'text', '发病规律：菌核越冬，15 - 20℃、湿度大时萌发侵染。通过气流、灌溉水传播，棚室通风差、连作田病重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003679', 'source-doc-4c784a84a66adf221597', 'source-node-003671', '4', '3678', 'text', '预防方法：深翻土壤，轮作，清理病残体，棚室通风降湿。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003680', 'source-doc-4c784a84a66adf221597', 'source-node-003671', '4', '3679', 'text', '防治方法：发病初期用菌核净、腐霉利喷雾或灌根。菌核病（Sclerotinia sclerotiorum）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003681', 'source-doc-4c784a84a66adf221597', 'source-node-003680', '5', '3680', 'text', '农业防治：轮作2-3年，深翻土壤，清除病残体，', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003682', 'source-doc-4c784a84a66adf221597', 'source-node-003680', '5', '3681', 'text', '化学防治：发病初期喷施腐霉利、菌核净等药剂，重点喷洒茎基部和地面。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003683', 'source-doc-4c784a84a66adf221597', 'source-node-003413', '3', '3682', 'text', '番茄斑枯病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003684', 'source-doc-4c784a84a66adf221597', 'source-node-003683', '4', '3683', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003685', 'source-doc-4c784a84a66adf221597', 'source-node-003684', '5', '3684', 'text', '叶片生圆形或近圆形小斑点，中央灰白色，边缘褐色，具黑色小点（分生孢子器）；严重时叶片布满病斑，干枯脱落。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003686', 'source-doc-4c784a84a66adf221597', 'source-node-003683', '4', '3685', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003687', 'source-doc-4c784a84a66adf221597', 'source-node-003686', '5', '3686', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003688', 'source-doc-4c784a84a66adf221597', 'source-node-003683', '4', '3687', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003689', 'source-doc-4c784a84a66adf221597', 'source-node-003688', '5', '3688', 'text', '番茄壳针孢（Septorialycopersici），属于半知菌门壳针孢属。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003690', 'source-doc-4c784a84a66adf221597', 'source-node-003683', '4', '3689', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003691', 'source-doc-4c784a84a66adf221597', 'source-node-003690', '5', '3690', 'text', '高温高湿（20-25℃、多雨）易发病，病残体带菌，通过风雨、农事操作传播，植株长势弱、通风差时病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003692', 'source-doc-4c784a84a66adf221597', 'source-node-003683', '4', '3691', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003693', 'source-doc-4c784a84a66adf221597', 'source-node-003692', '5', '3692', 'text', '农业防治：轮作2年以上，及时清除病叶，合理密植，增施磷钾肥。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003694', 'source-doc-4c784a84a66adf221597', 'source-node-003692', '5', '3693', 'text', '化学防治：发病前喷施代森锰锌预防，发病后用苯醚甲环唑、异菌脲等防治。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003695', 'source-doc-4c784a84a66adf221597', 'source-node-003413', '3', '3694', 'text', '番茄灰叶斑病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003696', 'source-doc-4c784a84a66adf221597', 'source-node-003695', '4', '3695', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003697', 'source-doc-4c784a84a66adf221597', 'source-node-003696', '5', '3696', 'text', '叶片生圆形或不规则形灰褐色病斑，边缘清晰，中央灰白色，易破裂；严重时叶片大量脱落，影响光合作用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003698', 'source-doc-4c784a84a66adf221597', 'source-node-003695', '4', '3697', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003699', 'source-doc-4c784a84a66adf221597', 'source-node-003698', '5', '3698', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003700', 'source-doc-4c784a84a66adf221597', 'source-node-003695', '4', '3699', 'text', '病原：茄匍柄霉（Stemphyliumsolani），属于半知菌门匍柄霉属。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003701', 'source-doc-4c784a84a66adf221597', 'source-node-003695', '4', '3700', 'text', '发生规律：高温高湿（25-30℃、相对湿度>80%）利于发病，病残体带菌，通过风雨传播，连作、通风差田块发病重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003702', 'source-doc-4c784a84a66adf221597', 'source-node-003695', '4', '3701', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003703', 'source-doc-4c784a84a66adf221597', 'source-node-003702', '5', '3702', 'text', '农业防治：清洁田园，及时摘除病叶，合理密植，避免大水漫灌。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003704', 'source-doc-4c784a84a66adf221597', 'source-node-003702', '5', '3703', 'text', '化学防治：发病初期喷施嘧菌酯、戊唑醇等药剂，连喷2-3次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003705', 'source-doc-4c784a84a66adf221597', 'source-node-003413', '3', '3704', 'text', '番茄黑斑病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003706', 'source-doc-4c784a84a66adf221597', 'source-node-003705', '4', '3705', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003707', 'source-doc-4c784a84a66adf221597', 'source-node-003706', '5', '3706', 'text', '果实发病为主，表面生圆形黑褐色病斑，具同心轮纹，湿度大时生黑色霉层；叶片病斑圆形，褐色，边缘黄晕。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003708', 'source-doc-4c784a84a66adf221597', 'source-node-003705', '4', '3707', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003709', 'source-doc-4c784a84a66adf221597', 'source-node-003708', '5', '3708', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003710', 'source-doc-4c784a84a66adf221597', 'source-node-003705', '4', '3709', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003711', 'source-doc-4c784a84a66adf221597', 'source-node-003710', '5', '3710', 'text', '链格孢（Alternariaalternata），属于半知菌门链格孢属。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003712', 'source-doc-4c784a84a66adf221597', 'source-node-003705', '4', '3711', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003713', 'source-doc-4c784a84a66adf221597', 'source-node-003712', '5', '3712', 'text', '高温多雨（25-30℃、多雨）易发病，病残体、种子带菌，通过风雨传播，果实成熟后期及贮藏期病重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003714', 'source-doc-4c784a84a66adf221597', 'source-node-003705', '4', '3713', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003715', 'source-doc-4c784a84a66adf221597', 'source-node-003714', '5', '3714', 'text', '农业防治：种子消毒（55℃浸种15分钟），及时清除病果，避免果实损伤。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003716', 'source-doc-4c784a84a66adf221597', 'source-node-003714', '5', '3715', 'text', '化学防治：发病前喷施代森锰锌，发病后用异菌脲、咪鲜胺等药剂。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003717', 'source-doc-4c784a84a66adf221597', 'source-node-003413', '3', '3716', 'text', '番茄褐斑病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003718', 'source-doc-4c784a84a66adf221597', 'source-node-003717', '4', '3717', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003719', 'source-doc-4c784a84a66adf221597', 'source-node-003718', '5', '3718', 'text', '叶片生圆形或椭圆形褐色病斑，边缘清晰，中央颜色稍浅，具轮纹；严重时叶片干枯脱落。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003720', 'source-doc-4c784a84a66adf221597', 'source-node-003717', '4', '3719', 'text', '图片', '[]');
