INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003724', 'source-doc-4c784a84a66adf221597', 'source-node-003717', '4', '3723', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003725', 'source-doc-4c784a84a66adf221597', 'source-node-003724', '5', '3724', 'text', '高温高湿（25-30℃、多雨）易发病，病残体带菌，通过风雨传播，植株长势弱时病重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003726', 'source-doc-4c784a84a66adf221597', 'source-node-003717', '4', '3725', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003727', 'source-doc-4c784a84a66adf221597', 'source-node-003726', '5', '3726', 'text', '农业防治：及时清除病叶，增施磷钾肥，提高植株抗病性。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003728', 'source-doc-4c784a84a66adf221597', 'source-node-003726', '5', '3727', 'text', '化学防治：发病初期喷施苯醚甲环唑、嘧菌酯等药剂。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003729', 'source-doc-4c784a84a66adf221597', 'source-node-003413', '3', '3728', 'text', '番茄茄匐柄霉斑点病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003730', 'source-doc-4c784a84a66adf221597', 'source-node-003729', '4', '3729', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003731', 'source-doc-4c784a84a66adf221597', 'source-node-003730', '5', '3730', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003732', 'source-doc-4c784a84a66adf221597', 'source-node-003190', '2', '3731', 'text', '生理病害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003733', 'source-doc-4c784a84a66adf221597', 'source-node-003732', '3', '3732', 'text', '番茄脐腐病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003734', 'source-doc-4c784a84a66adf221597', 'source-node-003733', '4', '3733', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003735', 'source-doc-4c784a84a66adf221597', 'source-node-003734', '5', '3734', 'text', '果实膨大期，脐部出现水浸状暗绿色斑，后变为褐色至黑色，凹陷变硬，果肉干腐，无霉层。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003736', 'source-doc-4c784a84a66adf221597', 'source-node-003733', '4', '3735', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003737', 'source-doc-4c784a84a66adf221597', 'source-node-003736', '5', '3736', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003738', 'source-doc-4c784a84a66adf221597', 'source-node-003733', '4', '3737', 'text', '发病规律：土壤缺钙或水分供应失调，在果实膨大期，遇高温干旱，植株蒸腾量大，钙吸收运输受阻，导致果实脐部细胞生理紊乱，坏死形成脐腐。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003739', 'source-doc-4c784a84a66adf221597', 'source-node-003733', '4', '3738', 'text', '预防方法：合理施肥，增施钙肥，改良土壤，保持土壤水分均匀供应，避免忽干忽湿，覆盖地膜保墒。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003740', 'source-doc-4c784a84a66adf221597', 'source-node-003733', '4', '3739', 'text', '防治方法：发病初期，及时喷施 0.3% 氯化钙溶液或 1% 过磷酸钙浸出液，重点喷果实脐部，7 - 10 天 1 次，连喷 2 - 3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003741', 'source-doc-4c784a84a66adf221597', 'source-node-003732', '3', '3740', 'text', '番茄煤霉病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003742', 'source-doc-4c784a84a66adf221597', 'source-node-003741', '4', '3741', 'text', '发病规律：高温多湿（25 - 30℃，相对湿度 85% 以上），种植过密、通风透光不良，利于病原菌滋生蔓延，从叶片气孔或伤口侵入。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003743', 'source-doc-4c784a84a66adf221597', 'source-node-003741', '4', '3742', 'text', '预防方法：合理密植，及时整枝打杈，加强通风透光，控制田间湿度，雨后排涝。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003744', 'source-doc-4c784a84a66adf221597', 'source-node-003741', '4', '3743', 'text', '防治方法：发病初期，用 50% 多菌灵可湿性粉剂 600 - 800 倍液、75% 百菌清可湿性粉剂 600 倍液喷雾，7 - 10 天 1 次，连喷 2 - 3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003745', 'source-doc-4c784a84a66adf221597', 'source-node-003732', '3', '3744', 'text', '番茄日灼', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003746', 'source-doc-4c784a84a66adf221597', 'source-node-003745', '4', '3745', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003747', 'source-doc-4c784a84a66adf221597', 'source-node-003732', '3', '3746', 'text', '番茄裂果病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003748', 'source-doc-4c784a84a66adf221597', 'source-node-003747', '4', '3747', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003749', 'source-doc-4c784a84a66adf221597', 'source-node-003748', '5', '3748', 'text', '果实表面出现纵向或横向裂纹，裂纹处果肉外露，易感染病菌腐烂。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003750', 'source-doc-4c784a84a66adf221597', 'source-node-003747', '4', '3749', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003751', 'source-doc-4c784a84a66adf221597', 'source-node-003750', '5', '3750', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003752', 'source-doc-4c784a84a66adf221597', 'source-node-003747', '4', '3751', 'text', '病因', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003753', 'source-doc-4c784a84a66adf221597', 'source-node-003752', '5', '3752', 'text', '生理性病害，土壤水分骤变（干旱后大水漫灌）、温度剧烈变化、缺钙缺硼导致果实表皮与果肉生长失衡。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003754', 'source-doc-4c784a84a66adf221597', 'source-node-003747', '4', '3753', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003755', 'source-doc-4c784a84a66adf221597', 'source-node-003754', '5', '3754', 'text', '果实膨大期高发，露地栽培雨后易发病，品种果皮薄时更易发生。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003756', 'source-doc-4c784a84a66adf221597', 'source-node-003747', '4', '3755', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003757', 'source-doc-4c784a84a66adf221597', 'source-node-003756', '5', '3756', 'text', '农业防治：均衡浇水，避免忽干忽湿，增施钙肥、硼肥，选用抗裂品种。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003758', 'source-doc-4c784a84a66adf221597', 'source-node-003756', '5', '3757', 'text', '田间管理：果实膨大期覆盖地膜，调节田间温湿度。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003759', 'source-doc-4c784a84a66adf221597', 'source-node-003732', '3', '3758', 'text', '番茄筋腐病（褐变型）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003760', 'source-doc-4c784a84a66adf221597', 'source-node-003759', '4', '3759', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003761', 'source-doc-4c784a84a66adf221597', 'source-node-003760', '5', '3760', 'text', '果实表面无明显异常，果肉内部出现褐色条状或块状坏死，僵硬，口感差；严重时果实表面出现褐色斑。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003762', 'source-doc-4c784a84a66adf221597', 'source-node-003759', '4', '3761', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003763', 'source-doc-4c784a84a66adf221597', 'source-node-003762', '5', '3762', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003764', 'source-doc-4c784a84a66adf221597', 'source-node-003759', '4', '3763', 'text', '病因', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003765', 'source-doc-4c784a84a66adf221597', 'source-node-003764', '5', '3764', 'text', '生理性病害，土壤缺钾、氮肥过多、光照不足、温度偏低导致养分运输受阻。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003766', 'source-doc-4c784a84a66adf221597', 'source-node-003759', '4', '3765', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003767', 'source-doc-4c784a84a66adf221597', 'source-node-003766', '5', '3766', 'text', '结果期高发，棚室栽培光照不足、通风差时病重，偏施氮肥田块发病重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003768', 'source-doc-4c784a84a66adf221597', 'source-node-003759', '4', '3767', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003769', 'source-doc-4c784a84a66adf221597', 'source-node-003768', '5', '3768', 'text', '农业防治：合理搭配氮磷钾肥，增施钾肥和有机肥，保证充足光照，棚室及时通风增温。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003770', 'source-doc-4c784a84a66adf221597', 'source-node-003768', '5', '3769', 'text', '叶面补肥：坐果后喷施0.2%磷酸二氢钾溶液，7-10天1次，连喷2-3次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003771', 'source-doc-4c784a84a66adf221597', 'source-node-003732', '3', '3770', 'text', '番茄畸形果', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003772', 'source-doc-4c784a84a66adf221597', 'source-node-003771', '4', '3771', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003773', 'source-doc-4c784a84a66adf221597', 'source-node-003772', '5', '3772', 'text', '果实形状异常，常见瘤状果、尖顶果、多心室果等，果肉发育不均，商品价值低。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003774', 'source-doc-4c784a84a66adf221597', 'source-node-003771', '4', '3773', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003775', 'source-doc-4c784a84a66adf221597', 'source-node-003774', '5', '3774', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003776', 'source-doc-4c784a84a66adf221597', 'source-node-003771', '4', '3775', 'text', '病因', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003777', 'source-doc-4c784a84a66adf221597', 'source-node-003776', '5', '3776', 'text', '生理性病害，花芽分化期（2-4片真叶期）温度过低（<15℃）、光照不足、激素使用不当导致花芽分化异常。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003778', 'source-doc-4c784a84a66adf221597', 'source-node-003771', '4', '3777', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003779', 'source-doc-4c784a84a66adf221597', 'source-node-003778', '5', '3778', 'text', '苗期低温高湿、氮肥过多时高发，棚室早春栽培易出现。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003780', 'source-doc-4c784a84a66adf221597', 'source-node-003771', '4', '3779', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003781', 'source-doc-4c784a84a66adf221597', 'source-node-003780', '5', '3780', 'text', '农业防治：苗期控制温度（白天20-25℃、夜间15-18℃），保证光照，合理施肥，避免苗期徒长。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003782', 'source-doc-4c784a84a66adf221597', 'source-node-003780', '5', '3781', 'text', '激素管理：严格控制蘸花激素浓度，避免重复蘸花。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003783', 'source-doc-4c784a84a66adf221597', 'source-node-003732', '3', '3782', 'text', '番茄空洞果', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003784', 'source-doc-4c784a84a66adf221597', 'source-node-003783', '4', '3783', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003785', 'source-doc-4c784a84a66adf221597', 'source-node-003784', '5', '3784', 'text', '果实内部果肉不饱满，形成空心腔室，果皮与果肉分离；果实重量轻，品质差。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003786', 'source-doc-4c784a84a66adf221597', 'source-node-003783', '4', '3785', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003787', 'source-doc-4c784a84a66adf221597', 'source-node-003786', '5', '3786', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003788', 'source-doc-4c784a84a66adf221597', 'source-node-003783', '4', '3787', 'text', '病因', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003789', 'source-doc-4c784a84a66adf221597', 'source-node-003788', '5', '3788', 'text', '生理性病害，授粉不良、水肥失衡（氮肥过多、钾肥不足）、温度过高或过低导致果实发育不均。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003790', 'source-doc-4c784a84a66adf221597', 'source-node-003783', '4', '3789', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003791', 'source-doc-4c784a84a66adf221597', 'source-node-003790', '5', '3790', 'text', '结果期高发，棚室栽培通风差、光照不足时病重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003792', 'source-doc-4c784a84a66adf221597', 'source-node-003783', '4', '3791', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003793', 'source-doc-4c784a84a66adf221597', 'source-node-003792', '5', '3792', 'text', '农业防治：合理调控温湿度（结果期白天25-28℃、夜间15-18℃），保证充足光照，均衡施用氮磷钾肥。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003794', 'source-doc-4c784a84a66adf221597', 'source-node-003792', '5', '3793', 'text', '栽培管理：人工辅助授粉或蜜蜂授粉，避免花期低温或高温胁迫。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003795', 'source-doc-4c784a84a66adf221597', 'source-node-003732', '3', '3794', 'text', '番茄低温障碍', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003796', 'source-doc-4c784a84a66adf221597', 'source-node-003795', '4', '3795', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003797', 'source-doc-4c784a84a66adf221597', 'source-node-003796', '5', '3796', 'text', '叶片黄化、卷曲，边缘焦枯；植株生长停滞，花芽分化异常，落花落果；果实畸形，着色不均。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003798', 'source-doc-4c784a84a66adf221597', 'source-node-003795', '4', '3797', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003799', 'source-doc-4c784a84a66adf221597', 'source-node-003798', '5', '3798', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003800', 'source-doc-4c784a84a66adf221597', 'source-node-003795', '4', '3799', 'text', '病因', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003801', 'source-doc-4c784a84a66adf221597', 'source-node-003800', '5', '3800', 'text', '气温低于10℃（苗期低于15℃），细胞结冰或代谢紊乱。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003802', 'source-doc-4c784a84a66adf221597', 'source-node-003795', '4', '3801', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003803', 'source-doc-4c784a84a66adf221597', 'source-node-003802', '5', '3802', 'text', '早春、晚秋或棚室保温不良时高发，低温持续时间越长，危害越重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003804', 'source-doc-4c784a84a66adf221597', 'source-node-003795', '4', '3803', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003805', 'source-doc-4c784a84a66adf221597', 'source-node-003804', '5', '3804', 'text', '农业防治：棚室覆盖保温膜、草帘，苗期炼苗，选用耐寒品种。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003806', 'source-doc-4c784a84a66adf221597', 'source-node-003804', '5', '3805', 'text', '应急措施：低温来临前喷施抗寒剂（如磷酸二氢钾+芸苔素内酯），棚内加温。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003807', 'source-doc-4c784a84a66adf221597', 'source-node-003732', '3', '3806', 'text', '番茄高温障碍', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003808', 'source-doc-4c784a84a66adf221597', 'source-node-003807', '4', '3807', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003809', 'source-doc-4c784a84a66adf221597', 'source-node-003808', '5', '3808', 'text', '叶片灼伤，出现黄白色斑点或焦枯；落花落果严重，果实日灼病高发；植株徒长，花芽分化不良。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003810', 'source-doc-4c784a84a66adf221597', 'source-node-003807', '4', '3809', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003811', 'source-doc-4c784a84a66adf221597', 'source-node-003810', '5', '3810', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003812', 'source-doc-4c784a84a66adf221597', 'source-node-003807', '4', '3811', 'text', '病因', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003813', 'source-doc-4c784a84a66adf221597', 'source-node-003812', '5', '3812', 'text', '气温高于35℃，光照过强导致植株代谢紊乱。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003814', 'source-doc-4c784a84a66adf221597', 'source-node-003807', '4', '3813', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003815', 'source-doc-4c784a84a66adf221597', 'source-node-003814', '5', '3814', 'text', '夏季露天栽培或棚室通风差时高发，持续高温天气危害加重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003816', 'source-doc-4c784a84a66adf221597', 'source-node-003807', '4', '3815', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003817', 'source-doc-4c784a84a66adf221597', 'source-node-003816', '5', '3816', 'text', '农业防治：露天栽培覆盖遮阳网，棚室及时通风降温，均衡浇水。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003818', 'source-doc-4c784a84a66adf221597', 'source-node-003816', '5', '3817', 'text', '田间管理：喷施叶面肥（如氨基酸肥），增强植株抗热性。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003819', 'source-doc-4c784a84a66adf221597', 'source-node-003732', '3', '3818', 'text', '番茄涝害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003820', 'source-doc-4c784a84a66adf221597', 'source-node-003819', '4', '3819', 'text', '图片（下方以辣椒为例）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003821', 'source-doc-4c784a84a66adf221597', 'source-node-003819', '4', '3820', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003822', 'source-doc-4c784a84a66adf221597', 'source-node-003821', '5', '3821', 'text', '根部缺氧变黑腐烂，植株萎蔫，叶片黄化脱落；果实腐烂，易感染病菌。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003823', 'source-doc-4c784a84a66adf221597', 'source-node-003819', '4', '3822', 'text', '病因', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003824', 'source-doc-4c784a84a66adf221597', 'source-node-003823', '5', '3823', 'text', '土壤积水，根系呼吸受阻。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003825', 'source-doc-4c784a84a66adf221597', 'source-node-003819', '4', '3824', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003826', 'source-doc-4c784a84a66adf221597', 'source-node-003825', '5', '3825', 'text', '多雨季节、低洼积水田块高发，积水时间越长，危害越重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003827', 'source-doc-4c784a84a66adf221597', 'source-node-003819', '4', '3826', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003828', 'source-doc-4c784a84a66adf221597', 'source-node-003827', '5', '3827', 'text', '农业防治：高垄栽培，挖排水沟，避免大水漫灌。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003829', 'source-doc-4c784a84a66adf221597', 'source-node-003827', '5', '3828', 'text', '应急措施：及时排水，松土增氧，喷施叶面肥（如磷酸二氢钾）恢复长势。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003830', 'source-doc-4c784a84a66adf221597', 'source-node-003732', '3', '3829', 'text', '番茄肥害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003831', 'source-doc-4c784a84a66adf221597', 'source-node-003830', '4', '3830', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003832', 'source-doc-4c784a84a66adf221597', 'source-node-003831', '5', '3831', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003833', 'source-doc-4c784a84a66adf221597', 'source-node-003830', '4', '3832', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003834', 'source-doc-4c784a84a66adf221597', 'source-node-003833', '5', '3833', 'text', '叶片焦枯、黄化，根部烧伤变黑；植株生长停滞，落花落果。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003835', 'source-doc-4c784a84a66adf221597', 'source-node-003830', '4', '3834', 'text', '病因', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003836', 'source-doc-4c784a84a66adf221597', 'source-node-003835', '5', '3835', 'text', '施肥过量、肥料浓度过高、未腐熟有机肥施用后发酵放热。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003837', 'source-doc-4c784a84a66adf221597', 'source-node-003830', '4', '3836', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003838', 'source-doc-4c784a84a66adf221597', 'source-node-003837', '5', '3837', 'text', '定植后追肥不当、土壤干旱时施肥易发生。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003839', 'source-doc-4c784a84a66adf221597', 'source-node-003830', '4', '3838', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003840', 'source-doc-4c784a84a66adf221597', 'source-node-003839', '5', '3839', 'text', '预防：合理施肥，有机肥充分腐熟，追肥后及时浇水。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003841', 'source-doc-4c784a84a66adf221597', 'source-node-003839', '5', '3840', 'text', '补救：土壤积水时排水，过量施肥后浇水稀释，喷施叶面肥缓解。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003842', 'source-doc-4c784a84a66adf221597', 'source-node-003732', '3', '3841', 'text', '番茄药害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003843', 'source-doc-4c784a84a66adf221597', 'source-node-003842', '4', '3842', 'text', '番茄2-4,D药害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003844', 'source-doc-4c784a84a66adf221597', 'source-node-003843', '5', '3843', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003845', 'source-doc-4c784a84a66adf221597', 'source-node-003844', '6', '3844', 'text', '叶片出现斑点、焦枯、卷曲，果实畸形、斑点；严重时植株枯死。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003846', 'source-doc-4c784a84a66adf221597', 'source-node-003843', '5', '3845', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003847', 'source-doc-4c784a84a66adf221597', 'source-node-003846', '6', '3846', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003848', 'source-doc-4c784a84a66adf221597', 'source-node-003843', '5', '3847', 'text', '病因', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003849', 'source-doc-4c784a84a66adf221597', 'source-node-003848', '6', '3848', 'text', '农药浓度过高、用药时期不当、药剂混用不当。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003850', 'source-doc-4c784a84a66adf221597', 'source-node-003843', '5', '3849', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003851', 'source-doc-4c784a84a66adf221597', 'source-node-003850', '6', '3850', 'text', '苗期、花期对药剂敏感，高温强光下用药易发生药害。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003852', 'source-doc-4c784a84a66adf221597', 'source-node-003843', '5', '3851', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003853', 'source-doc-4c784a84a66adf221597', 'source-node-003852', '6', '3852', 'text', '预防：严格按说明书稀释药剂，避免花期、高温时用药，不盲目混用药剂。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003854', 'source-doc-4c784a84a66adf221597', 'source-node-003852', '6', '3853', 'text', '补救：及时喷水冲洗叶片，喷施芸苔素内酯+氨基酸肥缓解药害。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003855', 'source-doc-4c784a84a66adf221597', 'source-node-003842', '4', '3854', 'text', '其他药害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003856', 'source-doc-4c784a84a66adf221597', 'source-node-003190', '2', '3855', 'text', '缺素', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003857', 'source-doc-4c784a84a66adf221597', 'source-node-003856', '3', '3856', 'text', '番茄缺硝态氮', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003858', 'source-doc-4c784a84a66adf221597', 'source-node-003857', '4', '3857', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003859', 'source-doc-4c784a84a66adf221597', 'source-node-003856', '3', '3858', 'text', '番茄缺钙', '[]');
