INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003870', 'source-doc-4c784a84a66adf221597', 'source-node-003869', '4', '3869', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003871', 'source-doc-4c784a84a66adf221597', 'source-node-003856', '3', '3870', 'text', '番茄缺锌', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003872', 'source-doc-4c784a84a66adf221597', 'source-node-003871', '4', '3871', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003873', 'source-doc-4c784a84a66adf221597', 'source-node-003856', '3', '3872', 'text', '番茄缺锰', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003874', 'source-doc-4c784a84a66adf221597', 'source-node-003873', '4', '3873', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003875', 'source-doc-4c784a84a66adf221597', 'source-node-003856', '3', '3874', 'text', '番茄缺钼', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003876', 'source-doc-4c784a84a66adf221597', 'source-node-003875', '4', '3875', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003877', 'source-doc-4c784a84a66adf221597', 'source-node-003190', '2', '3876', 'text', '番茄根结线虫', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003878', 'source-doc-4c784a84a66adf221597', 'source-node-003877', '3', '3877', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003879', 'source-doc-4c784a84a66adf221597', 'source-node-003878', '4', '3878', 'text', '根部形成大小不等的瘤状根结，须根减少；植株矮化，叶片黄化，萎蔫，结果少且小。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003880', 'source-doc-4c784a84a66adf221597', 'source-node-003877', '3', '3879', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003881', 'source-doc-4c784a84a66adf221597', 'source-node-003880', '4', '3880', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003882', 'source-doc-4c784a84a66adf221597', 'source-node-003877', '3', '3881', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003883', 'source-doc-4c784a84a66adf221597', 'source-node-003882', '4', '3882', 'text', '根结线虫属（Meloidogynespp.），主要为南方根结线虫、爪哇根结线虫。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003884', 'source-doc-4c784a84a66adf221597', 'source-node-003877', '3', '3883', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003885', 'source-doc-4c784a84a66adf221597', 'source-node-003884', '4', '3884', 'text', '土传病害，25-30℃、砂质土壤利于线虫繁殖，连作田发病重，通过土壤、灌溉水传播。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003886', 'source-doc-4c784a84a66adf221597', 'source-node-003877', '3', '3885', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003887', 'source-doc-4c784a84a66adf221597', 'source-node-003886', '4', '3886', 'text', '农业防治：与禾本科作物轮作4-5年，深翻土壤，增施有机肥，种植诱虫植物（如万寿菊）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003888', 'source-doc-4c784a84a66adf221597', 'source-node-003886', '4', '3887', 'text', '化学防治：播种前土壤施线虫剂（如噻唑膦），发病初期用阿维菌素灌根。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003889', 'source-doc-4c784a84a66adf221597', 'source-node-003190', '2', '3888', 'text', '番茄病毒', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003890', 'source-doc-4c784a84a66adf221597', 'source-node-003889', '3', '3889', 'text', '番茄烟草花叶病毒病（TMV）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003891', 'source-doc-4c784a84a66adf221597', 'source-node-003890', '4', '3890', 'text', '（一）病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003892', 'source-doc-4c784a84a66adf221597', 'source-node-003891', '5', '3891', 'text', '烟草花叶病毒（Tobaccomosaicvirus，TMV），属于烟草花叶病毒属，为单链 RNA 病毒。病毒粒体呈杆状，大小为 300nm×18nm，具有极强的稳定性，在干燥病组织中可存活多年，汁液中稀释至 100 万倍仍保持致病力。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003893', 'source-doc-4c784a84a66adf221597', 'source-node-003890', '4', '3892', 'text', '（二）图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003894', 'source-doc-4c784a84a66adf221597', 'source-node-003893', '5', '3893', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003895', 'source-doc-4c784a84a66adf221597', 'source-node-003890', '4', '3894', 'text', '（三）症状表现', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003896', 'source-doc-4c784a84a66adf221597', 'source-node-003895', '5', '3895', 'text', '花叶型：叶片出现黄绿相间或深绿、浅绿相间的斑驳花叶，叶面皱缩、变形，植株生长受抑，果实变小、品质下降。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003897', 'source-doc-4c784a84a66adf221597', 'source-node-003895', '5', '3896', 'text', '蕨叶型：植株不同程度矮化，上部叶片细长呈线状，叶肉组织退化，叶片皱缩扭曲，形似蕨类植物叶片。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003898', 'source-doc-4c784a84a66adf221597', 'source-node-003895', '5', '3897', 'text', '条斑型：可发生于叶片、茎蔓和果实。叶片上出现褐色或黑褐色坏死条纹；茎蔓上形成黑褐色长条形凹陷坏死斑；果实表面出现圆形或不规则形褐色凹陷斑，凹凸不平、僵化，完全失去商品价值。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003899', 'source-doc-4c784a84a66adf221597', 'source-node-003890', '4', '3898', 'text', '（四）发病规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003900', 'source-doc-4c784a84a66adf221597', 'source-node-003899', '5', '3899', 'text', '侵染源：主要在病残体、种子、土壤及多年生杂草上越冬，种子带毒是病毒远距离传播的重要途径。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003901', 'source-doc-4c784a84a66adf221597', 'source-node-003899', '5', '3900', 'text', '传播途径：主要通过汁液接触、农事操作（如整枝、打杈）传播，蚜虫、粉虱可辅助传播。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003902', 'source-doc-4c784a84a66adf221597', 'source-node-003899', '5', '3901', 'text', '发病条件：高温干旱环境利于病毒增殖和传播；植株生长衰弱、田间管理粗放、连作、土壤带毒等情况会加重病情。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003903', 'source-doc-4c784a84a66adf221597', 'source-node-003890', '4', '3902', 'text', '（五）预防和防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003904', 'source-doc-4c784a84a66adf221597', 'source-node-003903', '5', '3903', 'text', '农业防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003905', 'source-doc-4c784a84a66adf221597', 'source-node-003904', '6', '3904', 'text', '选用抗（耐）病品种，如 “佳粉 15 号” 等。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003906', 'source-doc-4c784a84a66adf221597', 'source-node-003904', '6', '3905', 'text', '种子处理：用 10% 磷酸三钠溶液浸种 20-30 分钟，清水冲洗干净后播种，可钝化种子表面病毒。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003907', 'source-doc-4c784a84a66adf221597', 'source-node-003904', '6', '3906', 'text', '实行轮作：与非茄科作物轮作 2-3 年，减少土壤中病毒残留。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003908', 'source-doc-4c784a84a66adf221597', 'source-node-003904', '6', '3907', 'text', '加强田间管理：合理施肥，增施有机肥和磷、钾肥，补充锌元素，提高植株抗病力；及时清除田间杂草、病株及病残体，减少侵染源；增加田间空气湿度、适当降温，创造不利于病毒增殖的环境。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003909', 'source-doc-4c784a84a66adf221597', 'source-node-003903', '5', '3908', 'text', '物理防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003910', 'source-doc-4c784a84a66adf221597', 'source-node-003909', '6', '3909', 'text', '采用防虫网覆盖栽培，防止蚜虫、粉虱等传毒媒介进入田间。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003911', 'source-doc-4c784a84a66adf221597', 'source-node-003903', '5', '3910', 'text', '化学防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003912', 'source-doc-4c784a84a66adf221597', 'source-node-003911', '6', '3911', 'text', '防治传毒媒介：蚜虫发生期，选用 10% 吡虫啉可湿性粉剂 1000-1500 倍液喷雾防治。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003913', 'source-doc-4c784a84a66adf221597', 'source-node-003911', '6', '3912', 'text', '病毒病防治：发病初期，选用 20% 病毒 A 可湿性粉剂 500-700 倍液、1.5% 植病灵乳剂 1000 倍液、宁南霉素制剂、吗啉胍・乙酸铜制剂等喷雾，每隔 7-10 天喷 1 次，连喷 3-4 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003914', 'source-doc-4c784a84a66adf221597', 'source-node-003903', '5', '3913', 'text', '生物防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003915', 'source-doc-4c784a84a66adf221597', 'source-node-003914', '6', '3914', 'text', '喷施香菇多糖、氨基寡糖素等生物制剂，诱导植株产生抗逆性，减轻病害症状。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003916', 'source-doc-4c784a84a66adf221597', 'source-node-003889', '3', '3915', 'text', '番茄黄化曲叶病毒病（TYLCV）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003917', 'source-doc-4c784a84a66adf221597', 'source-node-003916', '4', '3916', 'text', '（0）图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003918', 'source-doc-4c784a84a66adf221597', 'source-node-003917', '5', '3917', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003919', 'source-doc-4c784a84a66adf221597', 'source-node-003916', '4', '3918', 'text', '（一）病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003920', 'source-doc-4c784a84a66adf221597', 'source-node-003919', '5', '3919', 'text', '番茄黄化曲叶病毒（Tomato yellow leaf curl virus，TYLCV），属于双生病毒科菜豆金色花叶病毒属，为单链 DNA 病毒。病毒粒体呈双联体结构，大小约 18-20nm。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003921', 'source-doc-4c784a84a66adf221597', 'source-node-003916', '4', '3920', 'text', '（二）症状表现', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003922', 'source-doc-4c784a84a66adf221597', 'source-node-003921', '5', '3921', 'text', '植株整体症状：感染后生长迟缓，明显矮化，长势衰弱；开花结果延迟，花朵变小，坐果率显著降低，产量锐减。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003923', 'source-doc-4c784a84a66adf221597', 'source-node-003921', '5', '3922', 'text', '叶片症状：顶部叶片先发黄、变小，叶片边缘向上卷曲，叶肉增厚、质地变硬，随后叶片卷曲呈杯状或球状；叶背叶脉凸起，叶片整体黄化均匀，无明显花叶斑驳。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003924', 'source-doc-4c784a84a66adf221597', 'source-node-003921', '5', '3923', 'text', '果实症状：果实变小、质地偏硬，商品性差，成熟果实的品质和产量均受严重影响。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003925', 'source-doc-4c784a84a66adf221597', 'source-node-003916', '4', '3924', 'text', '（三）发病规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003926', 'source-doc-4c784a84a66adf221597', 'source-node-003925', '5', '3925', 'text', '侵染源：主要在病株、田间杂草及烟粉虱体内越冬，带毒烟粉虱是核心初侵染源，病毒可在烟粉虱体内持久增殖并终身传毒。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003927', 'source-doc-4c784a84a66adf221597', 'source-node-003925', '5', '3926', 'text', '传播途径：仅由烟粉虱（B 型、Q 型为主）持久性传播，不能通过种子、汁液摩擦等方式传播。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003928', 'source-doc-4c784a84a66adf221597', 'source-node-003925', '5', '3927', 'text', '发病条件：高温干旱环境（25-30℃）利于烟粉虱繁殖和活动，加速病毒传播；连作地块、棚室通风不良、田间杂草丛生时发病重；夏秋季为高发期，植株苗期至开花坐果期易感病；种植抗（耐）病性差的品种会加重病情。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003929', 'source-doc-4c784a84a66adf221597', 'source-node-003916', '4', '3928', 'text', '（四）预防和防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003930', 'source-doc-4c784a84a66adf221597', 'source-node-003929', '5', '3929', 'text', '农业防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003931', 'source-doc-4c784a84a66adf221597', 'source-node-003930', '6', '3930', 'text', '选用抗（耐）病品种，如 “迪芬尼”“硬粉 8 号”“中杂 105” 等。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003932', 'source-doc-4c784a84a66adf221597', 'source-node-003930', '6', '3931', 'text', '实行轮作：与非茄科作物轮作 3-4 年，减少田间病毒残留和侵染源。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003933', 'source-doc-4c784a84a66adf221597', 'source-node-003930', '6', '3932', 'text', '加强田间管理：合理施肥，增施有机肥和磷、钾肥，培育健壮植株，增强抗病力；及时清除田间及棚室周围杂草，切断病毒越冬和传播链条。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003934', 'source-doc-4c784a84a66adf221597', 'source-node-003929', '5', '3933', 'text', '物理防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003935', 'source-doc-4c784a84a66adf221597', 'source-node-003934', '6', '3934', 'text', '棚室栽培时，覆盖 40-60 目防虫网，彻底阻断烟粉虱进入田间。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003936', 'source-doc-4c784a84a66adf221597', 'source-node-003934', '6', '3935', 'text', '田间悬挂蓝色粘虫板（每亩 20-30 块），针对性诱捕烟粉虱成虫。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003937', 'source-doc-4c784a84a66adf221597', 'source-node-003934', '6', '3936', 'text', '定植前对棚室进行彻底消毒（如高温闷棚），杀灭残留烟粉虱及虫卵。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003938', 'source-doc-4c784a84a66adf221597', 'source-node-003929', '5', '3937', 'text', '生物防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003939', 'source-doc-4c784a84a66adf221597', 'source-node-003938', '6', '3938', 'text', '释放丽蚜小蜂、桨角蚜小蜂等烟粉虱天敌，自然控制烟粉虱种群数量，减少病毒传播。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003940', 'source-doc-4c784a84a66adf221597', 'source-node-003929', '5', '3939', 'text', '化学防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003941', 'source-doc-4c784a84a66adf221597', 'source-node-003940', '6', '3940', 'text', '防治传毒媒介：烟粉虱发生初期，选用 25% 噻虫嗪水分散粒剂 2000-3000 倍液、10% 吡虫啉可湿性粉剂 1000-1500 倍液或 10% 烯啶虫胺水剂 1000-1500 倍液喷雾，重点喷洒叶片背面；每隔 7-10 天喷 1 次，连喷 2-3 次，轮换用药避免抗药性产生。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003942', 'source-doc-4c784a84a66adf221597', 'source-node-003940', '6', '3941', 'text', '病毒病防治：发病初期，喷施 2% 氨基寡糖素水剂 300-500 倍液、2.95% 病毒必克可湿性粉剂 500-700 倍液或宁南霉素制剂等，每隔 7-10 天喷 1 次，连喷 3-4 次，配合叶面肥补充营养，减轻发病症状。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003943', 'source-doc-4c784a84a66adf221597', 'source-node-003889', '3', '3942', 'text', '番茄斑萎病毒病（TSWV）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003944', 'source-doc-4c784a84a66adf221597', 'source-node-003943', '4', '3943', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003945', 'source-doc-4c784a84a66adf221597', 'source-node-003944', '5', '3944', 'text', '叶片出现黄绿相间的斑驳，具褐色坏死斑；果实表面生圆形或不规则形黄白色斑，凹陷，具轮纹。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003946', 'source-doc-4c784a84a66adf221597', 'source-node-003943', '4', '3945', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003947', 'source-doc-4c784a84a66adf221597', 'source-node-003946', '5', '3946', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003948', 'source-doc-4c784a84a66adf221597', 'source-node-003943', '4', '3947', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003949', 'source-doc-4c784a84a66adf221597', 'source-node-003948', '5', '3948', 'text', '番茄斑萎病毒（Tomatospottedwiltvirus，TSWV），属于布尼亚病毒科番茄斑萎病毒属。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003950', 'source-doc-4c784a84a66adf221597', 'source-node-003943', '4', '3949', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003951', 'source-doc-4c784a84a66adf221597', 'source-node-003950', '5', '3950', 'text', '由蓟马传播，高温干旱利于蓟马活动，连作、杂草多的田块发病重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003952', 'source-doc-4c784a84a66adf221597', 'source-node-003943', '4', '3951', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003953', 'source-doc-4c784a84a66adf221597', 'source-node-003952', '5', '3952', 'text', '农业防治：棚室覆盖防虫网，清除田间杂草，及时防治蓟马。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003954', 'source-doc-4c784a84a66adf221597', 'source-node-003952', '5', '3953', 'text', '化学防治：喷施噻虫嗪、乙基多杀菌素防治蓟马，发病后喷施宁南霉素。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003955', 'source-doc-4c784a84a66adf221597', 'source-node-003889', '3', '3954', 'text', '番茄黄瓜花叶病毒病（CMV）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003956', 'source-doc-4c784a84a66adf221597', 'source-node-003955', '4', '3955', 'text', '（0）图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003957', 'source-doc-4c784a84a66adf221597', 'source-node-003956', '5', '3956', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003958', 'source-doc-4c784a84a66adf221597', 'source-node-003955', '4', '3957', 'text', '（一）病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003959', 'source-doc-4c784a84a66adf221597', 'source-node-003958', '5', '3958', 'text', '黄瓜花叶病毒（Cucumber mosaic virus，CMV），属于黄瓜花叶病毒属，为单链 RNA 病毒。病毒粒体呈球状，直径约 28-30nm，寄主范围极广，可侵染多种蔬菜、花卉及杂草。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003960', 'source-doc-4c784a84a66adf221597', 'source-node-003955', '4', '3959', 'text', '（二）症状表现', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003961', 'source-doc-4c784a84a66adf221597', 'source-node-003960', '5', '3960', 'text', '叶片症状：初期新叶出现黄绿相间的花叶斑驳，随后叶片变小、皱缩扭曲，部分叶片叶脉皱缩呈鸡爪状，有时会出现不规则疱斑；植株整体明显矮化，生长受抑。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003962', 'source-doc-4c784a84a66adf221597', 'source-node-003960', '5', '3961', 'text', '果实症状：果实变小、畸形，果面出现黄绿相间的花斑，果肉质地变差，品质显著下降。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003963', 'source-doc-4c784a84a66adf221597', 'source-node-003955', '4', '3962', 'text', '（三）发病规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003964', 'source-doc-4c784a84a66adf221597', 'source-node-003963', '5', '3963', 'text', '侵染源：主要在宿根杂草（如车前草、蒲公英）、病残体及带毒种子上越冬。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003965', 'source-doc-4c784a84a66adf221597', 'source-node-003963', '5', '3964', 'text', '传播途径：主要通过蚜虫（桃蚜、棉蚜为主）、粉虱传播，也可通过汁液摩擦（农事操作）传播。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003966', 'source-doc-4c784a84a66adf221597', 'source-node-003963', '5', '3965', 'text', '发病条件：高温干旱环境利于传毒昆虫（蚜虫、粉虱）活动，加速病毒传播；温暖湿润环境（20-25℃）利于病毒增殖；植株苗期和生长前期较易感病，田间管理粗放、连作、植株长势弱时病情加重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003967', 'source-doc-4c784a84a66adf221597', 'source-node-003955', '4', '3966', 'text', '（四）预防和防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003968', 'source-doc-4c784a84a66adf221597', 'source-node-003967', '5', '3967', 'text', '农业防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003969', 'source-doc-4c784a84a66adf221597', 'source-node-003968', '6', '3968', 'text', '选用抗（耐）病品种，如 “中蔬 4 号” 等。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003970', 'source-doc-4c784a84a66adf221597', 'source-node-003968', '6', '3969', 'text', '种子处理：用 10% 磷酸三钠溶液浸种 20-30 分钟，清水冲洗干净后播种，钝化种子表面病毒。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003971', 'source-doc-4c784a84a66adf221597', 'source-node-003968', '6', '3970', 'text', '轮作倒茬：与非茄科、葫芦科作物轮作 2-3 年，减少土壤中病毒残留。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003972', 'source-doc-4c784a84a66adf221597', 'source-node-003968', '6', '3971', 'text', '田间管理：合理密植，保证通风透光；科学施肥，增施有机肥和磷、钾肥，提高植株抗病力；及时清除病株、病残体及田间杂草，减少侵染源；可在田间种植大蒜、薄荷等驱蚜植物，阻断传毒媒介。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003973', 'source-doc-4c784a84a66adf221597', 'source-node-003967', '5', '3972', 'text', '物理防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003974', 'source-doc-4c784a84a66adf221597', 'source-node-003973', '6', '3973', 'text', '利用蚜虫对银灰色的驱避性，田间覆盖银灰色地膜。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003975', 'source-doc-4c784a84a66adf221597', 'source-node-003973', '6', '3974', 'text', '悬挂黄色粘虫板（每亩 20-30 块），诱捕蚜虫、粉虱成虫。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003976', 'source-doc-4c784a84a66adf221597', 'source-node-003973', '6', '3975', 'text', '棚室栽培时，覆盖 40-60 目防虫网，阻断传毒昆虫进入。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003977', 'source-doc-4c784a84a66adf221597', 'source-node-003967', '5', '3976', 'text', '化学防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003978', 'source-doc-4c784a84a66adf221597', 'source-node-003977', '6', '3977', 'text', '防治传毒媒介：蚜虫、粉虱发生初期，选用 2.5% 溴氰菊酯乳油 2000-3000 倍液、10% 吡虫啉可湿性粉剂 1000-1500 倍液或 25% 噻虫嗪水分散粒剂 2000-3000 倍液喷雾，重点喷洒叶片背面，轮换用药避免抗药性。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003979', 'source-doc-4c784a84a66adf221597', 'source-node-003977', '6', '3978', 'text', '病毒病防治：发病初期，用 20% 病毒 A 可湿性粉剂 500-700 倍液、宁南霉素 300-400 倍液或病毒克 500-800 倍液喷雾，每隔 7-10 天喷 1 次，连喷 3-4 次，可配合香菇多糖、氨基寡糖素等生物制剂，诱导植株产生抗逆性，减轻症状。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003980', 'source-doc-4c784a84a66adf221597', 'source-node-003889', '3', '3979', 'text', '番茄褪绿病毒病（ToCV）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003981', 'source-doc-4c784a84a66adf221597', 'source-node-003980', '4', '3980', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003982', 'source-doc-4c784a84a66adf221597', 'source-node-003981', '5', '3981', 'text', '植株上部叶片黄化，叶脉保持绿色，呈斑驳状；果实成熟延迟，色泽不均，产量下降。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003983', 'source-doc-4c784a84a66adf221597', 'source-node-003980', '4', '3982', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003984', 'source-doc-4c784a84a66adf221597', 'source-node-003983', '5', '3983', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003985', 'source-doc-4c784a84a66adf221597', 'source-node-003980', '4', '3984', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003986', 'source-doc-4c784a84a66adf221597', 'source-node-003985', '5', '3985', 'text', '番茄褪绿病毒（Tomatochlorosisvirus，），属于长线形病毒科毛形病毒属。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003987', 'source-doc-4c784a84a66adf221597', 'source-node-003980', '4', '3986', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003988', 'source-doc-4c784a84a66adf221597', 'source-node-003987', '5', '3987', 'text', '由烟粉虱传播，高温干旱（25-30℃）利于传毒，棚室栽培发病重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003989', 'source-doc-4c784a84a66adf221597', 'source-node-003980', '4', '3988', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003990', 'source-doc-4c784a84a66adf221597', 'source-node-003989', '5', '3989', 'text', '农业防治：覆盖防虫网，培育无病毒苗，清除杂草。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003991', 'source-doc-4c784a84a66adf221597', 'source-node-003989', '5', '3990', 'text', '化学防治：重点防治烟粉虱，喷施吡虫啉、螺虫乙酯，发病后喷施病毒抑制剂。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003992', 'source-doc-4c784a84a66adf221597', 'source-node-003980', '4', '3991', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003993', 'source-doc-4c784a84a66adf221597', 'source-node-003980', '4', '3992', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003994', 'source-doc-4c784a84a66adf221597', 'source-node-003889', '3', '3993', 'text', '番茄马铃薯Y病毒', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003995', 'source-doc-4c784a84a66adf221597', 'source-node-003994', '4', '3994', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003996', 'source-doc-4c784a84a66adf221597', 'source-node-003995', '5', '3995', 'text', '叶片卷曲，叶脉坏死，植株矮化；果实表面生褐色坏死斑，畸形，品质下降。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003997', 'source-doc-4c784a84a66adf221597', 'source-node-003994', '4', '3996', 'text', '', '[]');
