INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-003999', 'source-doc-4c784a84a66adf221597', 'source-node-003998', '5', '3998', 'text', '马铃薯Y病毒（PotatovirusY，PVY），属于马铃薯Y病毒科马铃薯Y病毒属。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004000', 'source-doc-4c784a84a66adf221597', 'source-node-003994', '4', '3999', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004001', 'source-doc-4c784a84a66adf221597', 'source-node-004000', '5', '4000', 'text', '由蚜虫传播，高温干旱利于蚜虫活动，连作、杂草多的田块发病重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004002', 'source-doc-4c784a84a66adf221597', 'source-node-003994', '4', '4001', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004003', 'source-doc-4c784a84a66adf221597', 'source-node-004002', '5', '4002', 'text', '农业防治：种植驱蚜植物，清除杂草，及时防治蚜虫。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004004', 'source-doc-4c784a84a66adf221597', 'source-node-004002', '5', '4003', 'text', '化学防治：喷施吡虫啉、噻虫嗪防治蚜虫，发病后喷施病毒A。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004005', 'source-doc-4c784a84a66adf221597', 'source-node-003889', '3', '4004', 'text', '番茄曲顶病毒病（ToCSV）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004006', 'source-doc-4c784a84a66adf221597', 'source-node-004005', '4', '4005', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004007', 'source-doc-4c784a84a66adf221597', 'source-node-004006', '5', '4006', 'text', '植株矮化，叶片卷曲，叶脉凸起，叶色浓绿；果实小而硬，畸形。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004008', 'source-doc-4c784a84a66adf221597', 'source-node-004005', '4', '4007', 'text', '图片', '[]');
