INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004010', 'source-doc-4c784a84a66adf221597', 'source-node-004005', '4', '4009', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004011', 'source-doc-4c784a84a66adf221597', 'source-node-004010', '5', '4010', 'text', '番茄曲顶病毒（Tomatocurlyshootvirus，ToCSV），属于双生病毒科菜豆金色花叶病毒属。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004012', 'source-doc-4c784a84a66adf221597', 'source-node-004005', '4', '4011', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004013', 'source-doc-4c784a84a66adf221597', 'source-node-004012', '5', '4012', 'text', '由叶蝉传播，高温干旱利于传毒，连作田发病重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004014', 'source-doc-4c784a84a66adf221597', 'source-node-004005', '4', '4013', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004015', 'source-doc-4c784a84a66adf221597', 'source-node-004014', '5', '4014', 'text', '农业防治：覆盖防虫网，清除杂草，防治叶蝉。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004016', 'source-doc-4c784a84a66adf221597', 'source-node-004014', '5', '4015', 'text', '化学防治：喷施噻虫嗪、吡蚜酮防治叶蝉，发病后喷施病毒抑制剂。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004017', 'source-doc-4c784a84a66adf221597', 'source-node-003889', '3', '4016', 'text', '番茄褐色皱纹果病毒病（ToBRFV）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004018', 'source-doc-4c784a84a66adf221597', 'source-node-004017', '4', '4017', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004019', 'source-doc-4c784a84a66adf221597', 'source-node-004018', '5', '4018', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004020', 'source-doc-4c784a84a66adf221597', 'source-node-004017', '4', '4019', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004021', 'source-doc-4c784a84a66adf221597', 'source-node-004020', '5', '4020', 'text', '叶片轻微花叶或无明显症状；果实表面出现褐色皱纹、凹陷斑，畸形严重，商品价值丧失。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004022', 'source-doc-4c784a84a66adf221597', 'source-node-004017', '4', '4021', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004023', 'source-doc-4c784a84a66adf221597', 'source-node-004022', '5', '4022', 'text', '番茄褐色皱纹果病毒（Tomatobrownrugosefruitvirus，ToBRFV），属于烟草花叶病毒属。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004024', 'source-doc-4c784a84a66adf221597', 'source-node-004017', '4', '4023', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004025', 'source-doc-4c784a84a66adf221597', 'source-node-004024', '5', '4024', 'text', '通过汁液、农事操作传播，种子带毒，高温干旱发病重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004026', 'source-doc-4c784a84a66adf221597', 'source-node-004017', '4', '4025', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004027', 'source-doc-4c784a84a66adf221597', 'source-node-004026', '5', '4026', 'text', '农业防治：严格检疫，选用无病毒种子，种子消毒，清洁田园。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004028', 'source-doc-4c784a84a66adf221597', 'source-node-004026', '5', '4027', 'text', '化学防治：发病初期喷施宁南霉素、吗啉胍・乙酸铜。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004029', 'source-doc-4c784a84a66adf221597', 'source-node-003889', '3', '4028', 'text', '番茄环斑病毒病（ToRSV）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004030', 'source-doc-4c784a84a66adf221597', 'source-node-004029', '4', '4029', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004031', 'source-doc-4c784a84a66adf221597', 'source-node-004030', '5', '4030', 'text', '叶片出现黄色环斑或坏死斑，植株矮化；果实表面生褐色环斑，畸形。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004032', 'source-doc-4c784a84a66adf221597', 'source-node-004029', '4', '4031', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004033', 'source-doc-4c784a84a66adf221597', 'source-node-004032', '5', '4032', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004034', 'source-doc-4c784a84a66adf221597', 'source-node-004032', '5', '4033', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004035', 'source-doc-4c784a84a66adf221597', 'source-node-004029', '4', '4034', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004036', 'source-doc-4c784a84a66adf221597', 'source-node-004035', '5', '4035', 'text', '番茄环斑病毒（Tomatoringspotvirus，ToRSV），属于线虫传多面体病毒科线虫传多面体病毒属。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004037', 'source-doc-4c784a84a66adf221597', 'source-node-004029', '4', '4036', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004038', 'source-doc-4c784a84a66adf221597', 'source-node-004037', '5', '4037', 'text', '由线虫传播，土传病毒，连作、砂质土壤田块发病重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004039', 'source-doc-4c784a84a66adf221597', 'source-node-004029', '4', '4038', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004040', 'source-doc-4c784a84a66adf221597', 'source-node-004039', '5', '4039', 'text', '农业防治：轮作3年以上，土壤消毒杀线虫，选用抗病品种。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004041', 'source-doc-4c784a84a66adf221597', 'source-node-004039', '5', '4040', 'text', '化学防治：发病后喷施病毒抑制剂，配合防治线虫。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004042', 'source-doc-4c784a84a66adf221597', 'source-node-004029', '4', '4041', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004043', 'source-doc-4c784a84a66adf221597', 'source-node-003889', '3', '4042', 'text', '番茄斑萎病毒病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004044', 'source-doc-4c784a84a66adf221597', 'source-node-004043', '4', '4043', 'text', '一、病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004045', 'source-doc-4c784a84a66adf221597', 'source-node-004044', '5', '4044', 'text', '番茄斑萎病毒（Tomato Spotted Wilt Virus，TSWV），属于布尼亚病毒科正番茄斑萎病毒属（Orthotospovirus），是一种单链 RNA 病毒。病毒粒体呈球形，直径约 80-120nm，具有脂质包膜，表面有糖蛋白突起。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004046', 'source-doc-4c784a84a66adf221597', 'source-node-004044', '5', '4045', 'text', '特性：病毒稳定性中等，在室温下可存活数天，不耐高温和强酸碱，在干燥病组织中可存活数月。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004047', 'source-doc-4c784a84a66adf221597', 'source-node-004043', '4', '4046', 'text', '二、症状表现', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004048', 'source-doc-4c784a84a66adf221597', 'source-node-004047', '5', '4047', 'text', '1. 叶片症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004049', 'source-doc-4c784a84a66adf221597', 'source-node-004048', '6', '4048', 'text', '初期：顶部幼叶出现青铜色（铜色）光泽，叶面向上卷曲Clemson University', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004050', 'source-doc-4c784a84a66adf221597', 'source-node-004048', '6', '4049', 'text', '中期：叶片出现褐色或黄色环斑，呈同心轮纹状（靶标状），严重时叶片布满斑点呈 "网纹状"UF/IFAS Department of Plant Pathology', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004051', 'source-doc-4c784a84a66adf221597', 'source-node-004048', '6', '4050', 'text', '后期：叶片皱缩、扭曲，叶背沿叶脉呈紫色，部分叶片尖端坏死，整株矮化', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004052', 'source-doc-4c784a84a66adf221597', 'source-node-004047', '5', '4051', 'text', '2. 茎秆症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004053', 'source-doc-4c784a84a66adf221597', 'source-node-004052', '6', '4052', 'text', '茎秆和叶柄上形成暗褐色条纹（坏死条斑），严重时导致茎部扭曲、生长受阻', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004054', 'source-doc-4c784a84a66adf221597', 'source-node-004047', '5', '4053', 'text', '3. 果实症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004055', 'source-doc-4c784a84a66adf221597', 'source-node-004054', '6', '4054', 'text', '幼果表面产生浅色环斑，未成熟果实出现白色至黄色同心环纹，环中心突起使果面局部隆起', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004056', 'source-doc-4c784a84a66adf221597', 'source-node-004054', '6', '4055', 'text', '成熟果实出现橘黄色和红色环纹斑，部分果实呈肿瘤状畸形，品质严重下降，失去商品价值', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004057', 'source-doc-4c784a84a66adf221597', 'source-node-004047', '5', '4056', 'text', '4. 整株表现', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004058', 'source-doc-4c784a84a66adf221597', 'source-node-004057', '6', '4057', 'text', '植株严重矮化，生长迟缓，开花结果延迟，坐果率降低，产量锐减', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004059', 'source-doc-4c784a84a66adf221597', 'source-node-004057', '6', '4058', 'text', '早期感染（苗期）常导致植株 "shepherd''s crook"（牧羊杖状）畸形，甚至死亡，不能结果', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004060', 'source-doc-4c784a84a66adf221597', 'source-node-004043', '4', '4059', 'text', '三、发病规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004061', 'source-doc-4c784a84a66adf221597', 'source-node-004060', '5', '4060', 'text', '1. 侵染源', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004062', 'source-doc-4c784a84a66adf221597', 'source-node-004061', '6', '4061', 'text', '主要在病残体、杂草（如苦苣菜、野大丽花）和带毒种苗上越冬，成为次年主要初侵染源', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004063', 'source-doc-4c784a84a66adf221597', 'source-node-004061', '6', '4062', 'text', '病毒寄主范围极广，可侵染85 科 1000 多种植物，包括番茄、辣椒、茄子、马铃薯、莴苣、西瓜等蔬菜，以及多种花卉和杂草', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004064', 'source-doc-4c784a84a66adf221597', 'source-node-004060', '5', '4063', 'text', '2. 传播途径', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004065', 'source-doc-4c784a84a66adf221597', 'source-node-004064', '6', '4064', 'text', '唯一自然传播媒介：蓟马（Thrips），包括西花蓟马（Frankliniella occidentalis）、烟蓟马（Thrips tabaci）等至少 10 种蓟马', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004066', 'source-doc-4c784a84a66adf221597', 'source-node-004064', '6', '4065', 'text', '传毒特性：持久性传毒，即蓟马只能在幼虫期（1 龄若虫）获取病毒，病毒在蓟马体内增殖后才能传毒，成虫可终身带毒（约 20 天）Tomato Spotted Wilt Virus', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004067', 'source-doc-4c784a84a66adf221597', 'source-node-004064', '6', '4066', 'text', '蓟马获毒时间：烟蓟马最短15-30 分钟，豆蓟马约30 分钟，时间越长传毒效率越高', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004068', 'source-doc-4c784a84a66adf221597', 'source-node-004064', '6', '4067', 'text', '人为传播：通过汁液摩擦（农事操作如整枝、打杈）和带毒种苗调运进行远距离传播', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004069', 'source-doc-4c784a84a66adf221597', 'source-node-004060', '5', '4068', 'text', '3. 发病条件', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004070', 'source-doc-4c784a84a66adf221597', 'source-node-004069', '6', '4069', 'text', '温度：28-32℃高温干旱环境最有利于病毒增殖和蓟马活动，加速传播', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004071', 'source-doc-4c784a84a66adf221597', 'source-node-004069', '6', '4070', 'text', '湿度：干旱条件下发病重，高湿环境抑制蓟马活动，减缓传播', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004072', 'source-doc-4c784a84a66adf221597', 'source-node-004069', '6', '4071', 'text', '植株状态：苗期和生长前期最易感病，植株长势弱、田间管理粗放时发病加重', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004073', 'source-doc-4c784a84a66adf221597', 'source-node-004069', '6', '4072', 'text', '栽培因素：连作地块、杂草丛生、与茄科作物邻作时发病风险高', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004074', 'source-doc-4c784a84a66adf221597', 'source-node-004069', '6', '4073', 'text', '流行规律：露地栽培（4 月定植）番茄，5 月开始零星发病，7 月进入发病高峰，病株以点带面逐渐扩展', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004075', 'source-doc-4c784a84a66adf221597', 'source-node-004043', '4', '4074', 'text', '四、预防和防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004076', 'source-doc-4c784a84a66adf221597', 'source-node-004075', '5', '4075', 'text', '1. 农业防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004077', 'source-doc-4c784a84a66adf221597', 'source-node-004076', '6', '4076', 'text', '选用抗病品种：选择含Sw-5 基因的番茄品种（如 '' 抗 TY-1'' 系列），注意部分地区已出现抗性突破株系', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004078', 'source-doc-4c784a84a66adf221597', 'source-node-004076', '6', '4077', 'text', '种子处理：10% 磷酸三钠溶液浸种20-30 分钟，清水冲洗后播种，钝化种子表面病毒，55℃温水浸种15 分钟（温汤浸种），冷却后继续浸种 6-8 小时', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004079', 'source-doc-4c784a84a66adf221597', 'source-node-004076', '6', '4078', 'text', '轮作倒茬：与非茄科作物（如十字花科、禾本科）轮作3-4 年，减少土壤中病毒积累', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004080', 'source-doc-4c784a84a66adf221597', 'source-node-004076', '6', '4079', 'text', '清除侵染源：定植前彻底清除田间及周边杂草（特别是苦苣菜、野大丽花等病毒寄主），及时拔除病株并销毁，减少田间病毒扩散', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004081', 'source-doc-4c784a84a66adf221597', 'source-node-004076', '6', '4080', 'text', '科学栽培：培育健壮植株，增强抗病力，避免干旱和高温环境，小水勤浇，', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004082', 'source-doc-4c784a84a66adf221597', 'source-node-004076', '6', '4081', 'text', '农具人员消毒：农事操作前消毒工具和手，避免人为传播', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004083', 'source-doc-4c784a84a66adf221597', 'source-node-004076', '6', '4082', 'text', '避免与辣椒、茄子等 TSWV 寄主作物邻作或套种', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004084', 'source-doc-4c784a84a66adf221597', 'source-node-004075', '5', '4083', 'text', '2. 物理防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004085', 'source-doc-4c784a84a66adf221597', 'source-node-004084', '6', '4084', 'text', '防虫网隔离：在棚室通风口、入口安装40-60 目防虫网，阻止蓟马进入', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004086', 'source-doc-4c784a84a66adf221597', 'source-node-004084', '6', '4085', 'text', '色板诱杀：田间悬挂蓝色粘虫板（蓟马对蓝色有强趋性），每亩20-30 块（20cm×25cm），监测和诱杀成虫，也可配合使用黄色粘虫板，监测其他害虫', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004087', 'source-doc-4c784a84a66adf221597', 'source-node-004084', '6', '4086', 'text', '银灰地膜覆盖：利用银灰色对蓟马的驱避作用，减少蓟马着落，降低传毒风险', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004088', 'source-doc-4c784a84a66adf221597', 'source-node-004084', '6', '4087', 'text', '遮阳降温：高温季节覆盖遮阳网，降低田间温度，减轻发病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004089', 'source-doc-4c784a84a66adf221597', 'source-node-004075', '5', '4088', 'text', '3. 生物防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004090', 'source-doc-4c784a84a66adf221597', 'source-node-004089', '6', '4089', 'text', '释放天敌：在蓟马发生初期释放捕食性天敌如小花蝽（Orius spp.）、捕食螨或寄生蜂（如捕食螨）控制蓟马种群', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004091', 'source-doc-4c784a84a66adf221597', 'source-node-004089', '6', '4090', 'text', '生物农药：喷施球孢白僵菌或绿僵菌等微生物杀虫剂，对蓟马有良好防治效果', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004092', 'source-doc-4c784a84a66adf221597', 'source-node-004089', '6', '4091', 'text', '植物源农药如印楝素、除虫菊素等，对蓟马有一定驱避和毒杀作用，且对环境友好', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004093', 'source-doc-4c784a84a66adf221597', 'source-node-004075', '5', '4092', 'text', '4. 化学防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004094', 'source-doc-4c784a84a66adf221597', 'source-node-004093', '6', '4093', 'text', '（1）防治蓟马（关键措施）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004095', 'source-doc-4c784a84a66adf221597', 'source-node-004094', '7', '4094', 'text', '定植前处理：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004096', 'source-doc-4c784a84a66adf221597', 'source-node-004095', '8', '4095', 'text', '穴施噻虫嗪颗粒剂（如 25% 噻虫嗪水分散粒剂），持效期可达 30 天，预防早期蓟马传毒', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004097', 'source-doc-4c784a84a66adf221597', 'source-node-004095', '8', '4096', 'text', '移栽前1-2 天，对幼苗喷施吡虫啉（10% 可湿性粉剂 1000-1500 倍液）或噻虫嗪（25% 水分散粒剂 3000-5000 倍液），可降低 TSWV 发生率 50% 以上', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004098', 'source-doc-4c784a84a66adf221597', 'source-node-004094', '7', '4097', 'text', '生长期防治：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004099', 'source-doc-4c784a84a66adf221597', 'source-node-004098', '8', '4098', 'text', '2.5% 多杀霉素悬浮剂1000-1500 倍液（菜喜），对蓟马特效且对天敌安全', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004100', 'source-doc-4c784a84a66adf221597', 'source-node-004098', '8', '4099', 'text', '10% 虫螨腈乳油2000 倍液或 5% 氟虫腈悬浮剂1500 倍液，具有触杀和胃毒作用', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004101', 'source-doc-4c784a84a66adf221597', 'source-node-004098', '8', '4100', 'text', '10% 吡虫啉可湿性粉剂1000-2000 倍液或 25% 噻虫嗪水分散粒剂3000 倍液，内吸性强，持效期长', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004102', 'source-doc-4c784a84a66adf221597', 'source-node-004098', '8', '4101', 'text', '5% 甲维盐・啶虫脒乳油1500 倍液，兼具胃毒和触杀作用，对蓟马效果好', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004103', 'source-doc-4c784a84a66adf221597', 'source-node-004094', '7', '4102', 'text', '注意：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004104', 'source-doc-4c784a84a66adf221597', 'source-node-004103', '8', '4103', 'text', '喷药时间宜在早晨或傍晚，此时蓟马活动较频繁，效果更好', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004105', 'source-doc-4c784a84a66adf221597', 'source-node-004103', '8', '4104', 'text', '重点喷洒叶背和茎基部（蓟马藏匿处），并注意轮换用药，避免抗药性产生', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004106', 'source-doc-4c784a84a66adf221597', 'source-node-004103', '8', '4105', 'text', '每7-10 天喷一次，连续2-3 次，可有效控制蓟马种群', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004107', 'source-doc-4c784a84a66adf221597', 'source-node-004093', '6', '4106', 'text', '（2）防治病毒病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004108', 'source-doc-4c784a84a66adf221597', 'source-node-004107', '7', '4107', 'text', '发病初期（病毒尚未系统侵染前）及时用药：2% 宁南霉素水剂200-300 倍液或 8% 宁南霉素・吗啉胍水剂500-800 倍液，抑制病毒复制', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004109', 'source-doc-4c784a84a66adf221597', 'source-node-004107', '7', '4108', 'text', '20% 盐酸吗啉胍・乙酮可湿性粉剂500 倍液或 32% 核苷・溴・吗啉胍水剂1000 倍液，干扰病毒核酸合成', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004110', 'source-doc-4c784a84a66adf221597', 'source-node-004107', '7', '4109', 'text', '2% 氨基寡糖素水剂300-500 倍液或寡糖・链蛋白，诱导植物产生抗性，减轻症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004111', 'source-doc-4c784a84a66adf221597', 'source-node-004107', '7', '4110', 'text', '辛菌胺 + 盐酸吗啉胍 + 氨基寡糖素 + 喹啉铜（或烯・羟・吗啉胍）组合使用，可提高防治效果', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004112', 'source-doc-4c784a84a66adf221597', 'source-node-004107', '7', '4111', 'text', '防治策略总结：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004113', 'source-doc-4c784a84a66adf221597', 'source-node-004112', '8', '4112', 'text', '采用 "预防为主，综合防治"方针，重点是 " 切断毒源、治虫防病 "', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004114', 'source-doc-4c784a84a66adf221597', 'source-node-004112', '8', '4113', 'text', '关键措施：种植抗病品种 + 彻底防治蓟马 + 清除杂草 + 物理隔离 + 发病前预防用药', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004115', 'source-doc-4c784a84a66adf221597', 'source-node-004112', '8', '4114', 'text', '单一防治措施效果有限，必须采取综合防控策略才能有效控制 TSWV 危害Tomato Spotted Wilt Virus', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004116', 'source-doc-4c784a84a66adf221597', 'source-node-004043', '4', '4115', 'text', '五、特别提示', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004117', 'source-doc-4c784a84a66adf221597', 'source-node-004116', '5', '4116', 'text', '早期识别：发现顶部叶片出现青铜色光泽和环斑症状，应立即检测确认，及时拔除病株并销毁', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004118', 'source-doc-4c784a84a66adf221597', 'source-node-004116', '5', '4117', 'text', '抗性管理：含 Sw-5 基因的抗性品种仍是目前最有效防治手段，但需注意抗性监测，发现抗性失效应及时更换品种', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004119', 'source-doc-4c784a84a66adf221597', 'source-node-004116', '5', '4118', 'text', '季节防控：高温干旱季节（6-8 月）是防控关键期，应加密监测和防治频次，特别注意蓟马防控', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004120', 'source-doc-4c784a84a66adf221597', 'source-node-004116', '5', '4119', 'text', '药剂混用：病毒病防治药剂可与叶面肥（如磷酸二氢钾）和植物生长调节剂混用，增强植株抗逆性，减轻症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004121', 'source-doc-4c784a84a66adf221597', 'source-node-003190', '2', '4120', 'text', '番茄虫害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004122', 'source-doc-4c784a84a66adf221597', 'source-node-004121', '3', '4121', 'text', '番茄白粉虱', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004123', 'source-doc-4c784a84a66adf221597', 'source-node-004122', '4', '4122', 'text', '发病规律：在温室可周年繁衍，露地借杂草等寄主越冬，成虫趋黄性、喜聚集在叶片背面吸食汁液、产卵，繁殖适温20 - 28℃，温暖干燥环境下种群数量剧增，春秋季为害猖獗，其分泌蜜露引发煤污病，影响光合作用。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004124', 'source-doc-4c784a84a66adf221597', 'source-node-004122', '4', '4123', 'text', '预防方法：温室通风口设防虫网，田间悬挂黄色粘虫板诱杀，种植前清理田园周边杂草残株，释放丽蚜小蜂等天敌昆虫抑制种群。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004125', 'source-doc-4c784a84a66adf221597', 'source-node-004122', '4', '4124', 'text', '防治方法：可选用25%噻虫嗪水分散粒剂3000 - 5000倍液、10%烯啶虫胺水剂1000 - 1500倍液等喷雾，注意叶片正反两面均匀喷施，5 - 7天1次，连喷2 - 3次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004126', 'source-doc-4c784a84a66adf221597', 'source-node-004121', '3', '4125', 'text', '番茄蚜虫', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004127', 'source-doc-4c784a84a66adf221597', 'source-node-004126', '4', '4126', 'text', '发病规律：多以卵在木槿、花椒等越冬寄主上越冬，春天气温回升孵化，有翅蚜迁飞至番茄田，16 - 22℃、湿度适宜时繁殖迅猛，常群集于嫩梢、叶片背面、花蕾吸食，致叶片卷曲畸形、生长受阻，还传播多种病毒病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004128', 'source-doc-4c784a84a66adf221597', 'source-node-004126', '4', '4127', 'text', '预防方法：田园周边避免种植越冬寄主，悬挂黄色粘虫板，保护和助迁瓢虫、草蛉等天敌。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004129', 'source-doc-4c784a84a66adf221597', 'source-node-004126', '4', '4128', 'text', '防治方法：选用10%吡虫啉可湿性粉剂1500 - 2000倍液、50%抗蚜威可湿性粉剂2000 - 3000倍液等喷雾，重点喷有蚜部位，7 - 10天1次，视虫情喷2 - 3次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004130', 'source-doc-4c784a84a66adf221597', 'source-node-004121', '3', '4129', 'text', '番茄棉铃虫', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004131', 'source-doc-4c784a84a66adf221597', 'source-node-004130', '4', '4130', 'text', '发病规律：以蛹在土壤中蛰伏越冬，成虫具趋光性、趋化性，夜间活跃，产卵于番茄嫩叶、花蕾、果实处，幼虫孵化先啃食嫩叶，后蛀食果实，25 - 28℃、相对湿度70%左右繁殖和为害达高峰，7 - 9月为害集中。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004132', 'source-doc-4c784a84a66adf221597', 'source-node-004130', '4', '4131', 'text', '预防方法：秋末冬初深耕翻土，破坏蛹室，利用黑光灯、糖醋液（糖:醋:酒:水 = 4:3:1:2）诱捕成虫，及时摘除虫果、清理残株减少虫源。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004133', 'source-doc-4c784a84a66adf221597', 'source-node-004130', '4', '4132', 'text', '防治方法：幼虫3龄前，用2.5%溴氰菊酯乳油2000 - 3000倍液、5%高效氯氟氰菊酯乳油1500 - 2000倍液等喷雾，确保药剂覆盖果实、叶片等部位，7 - 10天1次，依虫情喷2 - 3次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004134', 'source-doc-4c784a84a66adf221597', 'source-node-004121', '3', '4133', 'text', '番茄甜菜夜蛾，斜纹夜蛾', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004135', 'source-doc-4c784a84a66adf221597', 'source-node-004134', '4', '4134', 'text', '昼伏夜出，1-2龄叶片背面取食叶肉，留下表皮，3龄吃花苞叶片孔洞或缺刻或钻蛀果穗，4龄以后大量取食叶肉吃光留下叶柄叶脉。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004136', 'source-doc-4c784a84a66adf221597', 'source-node-004134', '4', '4135', 'text', '防治：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004137', 'source-doc-4c784a84a66adf221597', 'source-node-004121', '3', '4136', 'text', '番茄烟青虫', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004138', 'source-doc-4c784a84a66adf221597', 'source-node-004137', '4', '4137', 'text', '发病规律：与棉铃虫习性相似，以蛹在土中越冬，成虫昼伏夜出，产卵于番茄植株各部位，幼虫蛀食果实，偏爱甜椒、辣椒类，25 - 28℃、湿度适宜时繁殖活跃，夏季为害重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004139', 'source-doc-4c784a84a66adf221597', 'source-node-004137', '4', '4138', 'text', '预防方法：及时清除杂草、残株，破坏栖息产卵环境，糖醋液诱捕成虫，人工摘除卵块。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004140', 'source-doc-4c784a84a66adf221597', 'source-node-004137', '4', '4139', 'text', '防治方法：幼虫初孵期，用苏云金芽孢杆菌（Bt）制剂按产品说明稀释、1.8%阿维菌素乳油1000 - 1500倍液喷雾，重点保护果实，7 - 10天1次，喷2 - 3次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004141', 'source-doc-4c784a84a66adf221597', 'source-node-004121', '3', '4140', 'text', '番茄茶黄螨', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004142', 'source-doc-4c784a84a66adf221597', 'source-node-004141', '4', '4141', 'text', '发病规律：雌成螨在避风隐蔽处如枯枝落叶、杂草根部越冬，16 - 23℃、湿度适宜时，迁移至番茄植株，聚集于嫩梢、叶片、花、果实吸食，受害部位呈油渍状、畸形，生长受阻。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004143', 'source-doc-4c784a84a66adf221597', 'source-node-004141', '4', '4142', 'text', '预防方法：田园清洁，清除杂草、残株，减少越冬场所，合理轮作，避免连作加重为害。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004144', 'source-doc-4c784a84a66adf221597', 'source-node-004141', '4', '4143', 'text', '防治方法：发生初期，用73%克螨特乳油1000 - 1500倍液、10%浏阳霉素乳油1000 - 1500倍液等喷雾，着重喷植株上部幼嫩组织，5 - 7天1次，连喷2 - 3次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004145', 'source-doc-4c784a84a66adf221597', 'source-node-004121', '3', '4144', 'text', '番茄蓟马', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004146', 'source-doc-4c784a84a66adf221597', 'source-node-004145', '4', '4145', 'text', '发病规律：成虫在杂草、土缝等隐蔽处越冬，具趋蓝性，喜温暖干燥，常活动于番茄花、叶片，以锉吸式口器吸食汁液，造成白斑、畸形，传播病毒病，20 - 28℃繁殖快，花期为害突出。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004147', 'source-doc-4c784a84a66adf221597', 'source-node-004145', '4', '4146', 'text', '预防方法：田间悬挂蓝色粘虫板，种植前清除周边杂草，释放捕食螨、小花蝽等天敌。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004148', 'source-doc-4c784a84a66adf221597', 'source-node-004145', '4', '4147', 'text', '防治方法：选用2.5%多杀霉素悬浮剂1000 - 1500倍液、10%吡虫啉可湿性粉剂1500 - 2000倍液等喷雾，乙基多杀菌素也很好用。花期重点喷花，兼顾叶片，7 - 10天1次，喷2 - 3次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004149', 'source-doc-4c784a84a66adf221597', 'source-node-004121', '3', '4148', 'text', '其他害虫：蛴螬，蝼蛄、地老虎，', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004150', 'source-doc-4c784a84a66adf221597', 'source-node-002718', '1', '4149', 'text', '2.2.3 茄子', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004151', 'source-doc-4c784a84a66adf221597', 'source-node-004150', '2', '4150', 'text', '病害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004152', 'source-doc-4c784a84a66adf221597', 'source-node-004151', '3', '4151', 'text', '猝倒病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004153', 'source-doc-4c784a84a66adf221597', 'source-node-004152', '4', '4152', 'text', '病原：主要由瓜果腐霉菌侵染所致。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004154', 'source-doc-4c784a84a66adf221597', 'source-node-004152', '4', '4153', 'text', '症状表现：多发生在早春育苗床或育苗盘上，种子出土前发病会造成烂种；出土后的幼苗发病，茎基部呈水渍状病斑，随后病部变黄褐色，缢缩成线状，在子叶尚未凋萎之前，幼苗便倒伏。湿度大时，病部附近长出白色棉絮状菌丝。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004155', 'source-doc-4c784a84a66adf221597', 'source-node-004152', '4', '4154', 'text', '发病规律：病菌以卵孢子在土壤中越冬，在适宜的温度（15 - 16℃）和湿度条件下，孢子萌发产生芽管，从根部或茎基部侵入。苗床温度过低、湿度过大、光照不足、通风不良等条件均有利于发病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004156', 'source-doc-4c784a84a66adf221597', 'source-node-004152', '4', '4155', 'text', '防治方法：选用疏松、肥沃、排水良好的土壤作苗床，播种前进行土壤消毒，如用 50% 多菌灵可湿性粉剂或 50% 福美双可湿性粉剂与适量细土拌匀撒施。控制苗床湿度，避免浇水过多，保持良好的通风透光条件。发病初期，可选用 72.2% 普力克水剂 800 倍液、58% 甲霜灵・锰锌可湿性粉剂 500 倍液等药剂喷雾防治。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004157', 'source-doc-4c784a84a66adf221597', 'source-node-004151', '3', '4156', 'text', '立枯病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004158', 'source-doc-4c784a84a66adf221597', 'source-node-004157', '4', '4157', 'text', '病原：由立枯丝核菌引起。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004159', 'source-doc-4c784a84a66adf221597', 'source-node-004157', '4', '4158', 'text', '症状表现：主要危害幼苗茎基部或地下根部，初为椭圆形或不规则形暗褐色病斑，病苗早期白天萎蔫，夜间恢复，病斑逐渐凹陷，扩大后绕茎一周，最后病部收缩干枯，整株死亡。湿度大时，病部可见淡褐色蛛丝状霉。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004160', 'source-doc-4c784a84a66adf221597', 'source-node-004157', '4', '4159', 'text', '发病规律：病菌以菌丝体或菌核在土壤中或病残体上越冬，在温度 17 - 28℃、湿度较大的条件下容易发病。重茬地、土壤黏重、排水不良、光照不足等均有利于该病的发生。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004161', 'source-doc-4c784a84a66adf221597', 'source-node-004157', '4', '4160', 'text', '防治方法：加强苗床管理，注意通风透光，降低湿度。进行种子和苗床消毒，可用种子重量 0.3% 的 50% 福美双可湿性粉剂拌种，或用 50% 多菌灵可湿性粉剂与 50% 福美双可湿性粉剂按 1:1 混合，每平方米用药 8 - 10 克与适量细土拌匀撒施苗床。发病初期，可选用 75% 百菌清可湿性粉剂 600 倍液、50% 甲基立枯磷乳油 1200 倍液等药剂喷雾防治。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004162', 'source-doc-4c784a84a66adf221597', 'source-node-004151', '3', '4161', 'text', '黄萎病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004163', 'source-doc-4c784a84a66adf221597', 'source-node-004162', '4', '4162', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004164', 'source-doc-4c784a84a66adf221597', 'source-node-004163', '5', '4163', 'text', '由大丽花轮枝孢菌（Verticillium dahliae Kleb.）引起，是一种土传性维管束病害。病菌以分生孢子和菌丝体在土壤中的病残体等位置越冬，其生命力顽强，在土壤里可以存活 6 - 8 年以上，有的甚至能存活 10 年。在温度 18 - 24℃时，病菌开始活跃。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004165', 'source-doc-4c784a84a66adf221597', 'source-node-004162', '4', '4164', 'text', '症状表现', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004166', 'source-doc-4c784a84a66adf221597', 'source-node-004165', '5', '4165', 'text', '主要在结果后期发病，叶片是最直观的表现部位。初期近叶柄的叶缘部叶脉间褪绿，晴天高温时萎蔫，夜间或天气转阴时恢复正常。随着病情发展，萎蔫状态不能再恢复，褪绿部分变为黄白色至褐色，叶缘稍稍向上卷曲，且多由半边叶开始发病，这也是 “半边疯” 名称的由来。当病斑扩展到整片叶子之后，病叶干枯脱落，病害一般自下向上逐渐发展。病株的茎基部和根部维管束变为褐色，严重时全株叶片枯黄、植株萎缩。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004167', 'source-doc-4c784a84a66adf221597', 'source-node-004162', '4', '4166', 'text', '发病规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004168', 'source-doc-4c784a84a66adf221597', 'source-node-004167', '5', '4167', 'text', '病原菌以分生孢子和菌丝体通过茄子植株的根部侵入。土壤是主要的传染源，连作地、土壤湿度较大的地块容易发病。病菌在土壤中积累，遇到适宜的温度和湿度条件，就会对茄子植株造成侵染。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004169', 'source-doc-4c784a84a66adf221597', 'source-node-004162', '4', '4168', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004170', 'source-doc-4c784a84a66adf221597', 'source-node-004169', '5', '4169', 'text', '品种选择：选用抗病品种，如快星、紫月、茄杂 2 号和茄杂 9 号等。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004171', 'source-doc-4c784a84a66adf221597', 'source-node-004169', '5', '4170', 'text', '生态防治：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004172', 'source-doc-4c784a84a66adf221597', 'source-node-004171', '6', '4171', 'text', '采用营养钵育苗，营养土应消毒，减少病原菌侵染。例如，用高温蒸汽消毒或化学药剂如 40% 五氯硝基苯粉剂与营养土混合消毒。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004173', 'source-doc-4c784a84a66adf221597', 'source-node-004171', '6', '4172', 'text', '对苗床或大棚土壤进行处理，种植前深翻土壤、晒垡，也可使用棉隆等土壤熏蒸剂消毒。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004174', 'source-doc-4c784a84a66adf221597', 'source-node-004171', '6', '4173', 'text', '加强田间管理，适当增施生物菌肥和磷钾肥，促进植株健壮生长。采用合理的灌溉方式，如滴灌或膜下暗灌，避免大水漫灌，降低湿度。及时整枝打杈，增强通风透光。收获后及时清除病残体，并用 50% 多菌灵可湿性粉剂与适量细土拌匀撒施消毒。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004175', 'source-doc-4c784a84a66adf221597', 'source-node-004169', '5', '4174', 'text', '嫁接防病：以野生茄子作砧木与茄子嫁接换根，能有效防治因重茬、土壤带菌严重引起的黄萎病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004176', 'source-doc-4c784a84a66adf221597', 'source-node-004169', '5', '4175', 'text', '种子包衣防病：使用 2.5% 适乐时悬浮种衣剂和 35% 金普隆乳化种衣剂进行种子杀菌。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004177', 'source-doc-4c784a84a66adf221597', 'source-node-004169', '5', '4176', 'text', '定植时生物农药处理：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004178', 'source-doc-4c784a84a66adf221597', 'source-node-004177', '6', '4177', 'text', '撒药土，将药土比为 1：50 倍的萎菌净与细土混合好，每穴每株 50 克，穴施后定植。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004179', 'source-doc-4c784a84a66adf221597', 'source-node-004177', '6', '4178', 'text', '也可用 1000 倍药液每穴 250 毫升灌坑。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004180', 'source-doc-4c784a84a66adf221597', 'source-node-004169', '5', '4179', 'text', '药剂救治：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004181', 'source-doc-4c784a84a66adf221597', 'source-node-004180', '6', '4180', 'text', '发病前或发病初期用 10 亿活孢子 / 克枯草芽孢杆菌可湿性粉剂灌根处理。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004182', 'source-doc-4c784a84a66adf221597', 'source-node-004180', '6', '4181', 'text', '还可使用化学药剂如 2.5％适乐时悬浮剂、75％达科宁可湿性粉剂、80％大生可湿性粉剂、甲基托布津可湿性粉剂、50％多菌灵可湿性粉剂等灌根，每株灌药量 200 - 300 毫升，每隔 7 - 10 天灌一次，连续灌 2 - 3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004183', 'source-doc-4c784a84a66adf221597', 'source-node-004180', '6', '4182', 'text', '定植后药剂灌根：苗期和定植前后用90%恶霉灵可湿性粉剂稀释2000-3000倍液或50%琥胶肥酸铜可湿性粉剂500倍液进行灌根，每株灌60-100毫升药，也可用600-700倍液50%多菌灵可湿性粉剂或70%甲基托布津800-1000倍液灌根，每株灌约100毫升药，以上均5-7天灌根1次，连续灌根2-3次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004184', 'source-doc-4c784a84a66adf221597', 'source-node-004180', '6', '4183', 'text', '药剂喷施：茄子黄萎病在发病初期，及时选用77%可杀得可湿性粉剂800-1000倍液、50%多菌灵600-800倍液或70%甲基托布津600-800倍液喷施茎部，7-10天左右喷施1次，连续防治2-3次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004185', 'source-doc-4c784a84a66adf221597', 'source-node-004151', '3', '4184', 'text', '褐纹病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004186', 'source-doc-4c784a84a66adf221597', 'source-node-004185', '4', '4185', 'text', '病原：由茄褐纹拟茎点霉引起。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004187', 'source-doc-4c784a84a66adf221597', 'source-node-004185', '4', '4186', 'text', '症状表现：从苗期到成株期均可发病，主要危害叶片、茎和果实。叶片发病，初为水渍状白色小点，后扩大为圆形或近圆形褐色病斑，病斑中央灰白色，边缘深褐色，上生许多小黑点。茎部发病，多在基部，病斑梭形，边缘深褐色，中央灰白色，上生小黑点，严重时茎部病斑凹陷、干缩，易折断。果实发病，初为浅褐色圆形病斑，后变为黑褐色，稍凹陷，上生许多小黑点，后期病果腐烂、脱落。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004188', 'source-doc-4c784a84a66adf221597', 'source-node-004185', '4', '4187', 'text', '发病规律：病菌以菌丝体、分生孢子器在病残体上越冬，翌年产生分生孢子，借风雨、昆虫传播，从伤口或表皮侵入。高温高湿、通风不良、植株生长衰弱等条件有利于发病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004189', 'source-doc-4c784a84a66adf221597', 'source-node-004185', '4', '4188', 'text', '防治方法：选用抗病品种，实行轮作，避免连作。种子消毒，可用 55℃温水浸种 15 - 20 分钟，或用种子重量 0.3% 的 50% 多菌灵可湿性粉剂拌种。加强田间管理，合理密植，及时清除病残体，保持通风透光。发病初期，可选用 75% 百菌清可湿性粉剂 600 倍液、50% 多菌灵可湿性粉剂 500 倍液、64% 杀毒矾可湿性粉剂 500 倍液等药剂喷雾防治。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004190', 'source-doc-4c784a84a66adf221597', 'source-node-004151', '3', '4189', 'text', '枯萎病：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004191', 'source-doc-4c784a84a66adf221597', 'source-node-004190', '4', '4190', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004192', 'source-doc-4c784a84a66adf221597', 'source-node-004191', '5', '4191', 'text', '由尖镰孢菌茄子专化型（Fusarium oxysporum f. sp. melongenae）引起，同样是维管束病害。菌丝体有隔，无色，分生孢子有大型分生孢子（镰刀形，多胞）和小型分生孢子（椭圆形，单胞）。病原菌以菌丝体、厚垣孢子在土壤、病残体或种子上越冬。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004193', 'source-doc-4c784a84a66adf221597', 'source-node-004190', '4', '4192', 'text', '症状表现', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004194', 'source-doc-4c784a84a66adf221597', 'source-node-004193', '5', '4193', 'text', '一般从下部叶片开始发黄，逐渐向上发展，叶片萎蔫下垂，后期叶片干枯脱落。病株的茎基部维管束变为褐色。病情严重时，全株枯萎死亡。有时病株一侧的枝叶先枯萎，另一侧的枝叶后枯萎，呈现出 “半边枯” 的现象，但与黄萎病的 “半边疯” 在发病过程等方面有所不同。枯萎病主要是植株整体的枯萎过程，从下往上叶片逐渐黄化、枯萎，且叶片一般不脱落，而黄萎病有明显的叶片褪绿、恢复再到不能恢复的过程，并且叶片有向上卷曲的情况。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004195', 'source-doc-4c784a84a66adf221597', 'source-node-004190', '4', '4194', 'text', '发病规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004196', 'source-doc-4c784a84a66adf221597', 'source-node-004195', '5', '4195', 'text', '通过土壤、灌溉水、农事操作等传播。在适宜的温度（24 - 28℃）和湿度条件下，病原菌从根部伤口或直接侵入根系，进入维管束系统，在植株体内繁殖，堵塞导管，导致植株枯萎。连作、土壤黏重、排水不良、施肥不当等情况容易引发枯萎病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004197', 'source-doc-4c784a84a66adf221597', 'source-node-004190', '4', '4196', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004198', 'source-doc-4c784a84a66adf221597', 'source-node-004197', '5', '4197', 'text', '农业防治：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004199', 'source-doc-4c784a84a66adf221597', 'source-node-004198', '6', '4198', 'text', '实行轮作，与非茄科作物轮作 3 - 4 年。选用抗病品种，如 “茄杂 2 号” 等。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004200', 'source-doc-4c784a84a66adf221597', 'source-node-004198', '6', '4199', 'text', '种子处理，用 55℃温水浸种 15 - 20 分钟，或用种子重量 0.3% - 0.5% 的 50% 福美双可湿性粉剂拌种。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004201', 'source-doc-4c784a84a66adf221597', 'source-node-004198', '6', '4200', 'text', '加强田间管理，增施有机肥和磷、钾肥，改善土壤结构，促进根系发育。合理浇水，避免田间积水。及时清除病株和病残体。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004202', 'source-doc-4c784a84a66adf221597', 'source-node-004197', '5', '4201', 'text', '化学防治：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004203', 'source-doc-4c784a84a66adf221597', 'source-node-004202', '6', '4202', 'text', '土壤消毒，在种植前，可用 40% 甲醛溶液（福尔马林）对土壤进行消毒，每平方米用福尔马林 50 - 100 毫升，加水稀释后，均匀喷洒在土壤表面，然后用塑料薄膜覆盖，密封 2 - 3 天后揭开，晾晒 1 - 2 周后再种植。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004204', 'source-doc-4c784a84a66adf221597', 'source-node-004202', '6', '4203', 'text', '发病初期，可用 30% 甲霜・恶霉灵水剂 1000 - 1500 倍液或 50% 氯溴异氰尿酸可溶性粉剂 1000 - 1500 倍液进行灌根，每株灌药量 200 - 300 毫升，每隔 7 - 10 天灌 1 次，连续灌 2 - 3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004205', 'source-doc-4c784a84a66adf221597', 'source-node-004151', '3', '4204', 'text', '绵疫病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004206', 'source-doc-4c784a84a66adf221597', 'source-node-004205', '4', '4205', 'text', '病原：由寄生疫霉引起。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004207', 'source-doc-4c784a84a66adf221597', 'source-node-004205', '4', '4206', 'text', '症状表现：主要危害果实，也可危害叶片和茎。果实发病，初为水渍状圆形斑点，迅速扩展后病斑变为褐色或暗褐色，病部凹陷，湿度大时病斑上生有白色棉絮状菌丝。叶片发病，初为水渍状暗绿色斑点，后扩大为圆形或不规则形褐色病斑，严重时叶片腐烂。茎部发病，初为水渍状缢缩，后变黑褐色，病部以上枝叶萎蔫。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004208', 'source-doc-4c784a84a66adf221597', 'source-node-004205', '4', '4207', 'text', '发病规律：病菌以卵孢子在土壤中越冬，借雨水、灌溉水传播，在高温高湿（温度 25 - 30℃，相对湿度 85% 以上）条件下容易发病。地势低洼、排水不良、种植过密、通风透光差的地块发病重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004209', 'source-doc-4c784a84a66adf221597', 'source-node-004205', '4', '4208', 'text', '防治方法：选用抗病品种，实行高畦栽培，合理密植，及时整枝打杈，保持通风透光。加强田间管理，避免田间积水，降低湿度。发病初期，可选用 64% 杀毒矾可湿性粉剂 500 倍液、58% 甲霜灵・锰锌可湿性粉剂 500 倍液、72% 克露可湿性粉剂 600 倍液等药剂喷雾防治。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004210', 'source-doc-4c784a84a66adf221597', 'source-node-004151', '3', '4209', 'text', '青枯病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004211', 'source-doc-4c784a84a66adf221597', 'source-node-004210', '4', '4210', 'text', '病原：由茄科劳尔氏菌引起。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004212', 'source-doc-4c784a84a66adf221597', 'source-node-004210', '4', '4211', 'text', '症状表现：一般在开花结果期发病，初时植株叶片白天萎蔫，早晚恢复正常，随后叶片逐渐变黄，枯萎下垂，最后全株死亡。病株茎基部表皮粗糙，常产生不定根，纵切病茎可见维管束变为褐色，用手挤压有白色菌液流出。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004213', 'source-doc-4c784a84a66adf221597', 'source-node-004210', '4', '4212', 'text', '发病规律：病菌随病残体在土壤中越冬，可存活多年。主要通过雨水、灌溉水、农事操作等传播，从根部或茎基部伤口侵入。高温高湿、连作、土壤偏酸等条件有利于发病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004214', 'source-doc-4c784a84a66adf221597', 'source-node-004210', '4', '4213', 'text', '防治方法：实行轮作，与非茄科作物轮作 3 - 4 年。选用抗病品种，如抗青 19 号等。加强田间管理，增施有机肥和钾肥，调节土壤酸碱度，使土壤呈微碱性。发现病株及时拔除，并用生石灰对病穴进行消毒。发病初期，可选用 72% 农用硫酸链霉素可溶性粉剂 4000 倍液、50% 琥胶肥酸铜可湿性粉剂 500 倍液等药剂灌根防治。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004215', 'source-doc-4c784a84a66adf221597', 'source-node-004151', '3', '4214', 'text', '炭疽病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004216', 'source-doc-4c784a84a66adf221597', 'source-node-004215', '4', '4215', 'text', '病原：由胶孢炭疽菌引起。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004217', 'source-doc-4c784a84a66adf221597', 'source-node-004215', '4', '4216', 'text', '症状表现：主要危害叶片和果实。叶片发病，初为褪绿水渍状斑点，后扩大为圆形或近圆形褐色病斑，病斑中央灰白色，边缘深褐色，上生许多小黑点。果实发病，初为褐色圆形病斑，后扩大为黑褐色，病斑凹陷，上生许多小黑点，严重时果实腐烂。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004218', 'source-doc-4c784a84a66adf221597', 'source-node-004215', '4', '4217', 'text', '发病规律：病菌以菌丝体、分生孢子盘在病残体上越冬，翌年产生分生孢子，借风雨、昆虫传播，从伤口或表皮侵入。高温高湿、通风不良、植株生长衰弱等条件有利于发病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004219', 'source-doc-4c784a84a66adf221597', 'source-node-004215', '4', '4218', 'text', '防治方法：选用抗病品种，种子消毒，可用 55℃温水浸种 15 - 20 分钟。加强田间管理，合理密植，及时清除病残体，保持通风透光。发病初期，可选用 75% 百菌清可湿性粉剂 600 倍液、50% 多菌灵可湿性粉剂 500 倍液、80% 炭疽福美可湿性粉剂 800 倍液等药剂喷雾防治。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004220', 'source-doc-4c784a84a66adf221597', 'source-node-004151', '3', '4219', 'text', '灰霉病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004221', 'source-doc-4c784a84a66adf221597', 'source-node-004220', '4', '4220', 'text', '病原：由灰葡萄孢菌引起。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004222', 'source-doc-4c784a84a66adf221597', 'source-node-004220', '4', '4221', 'text', '症状表现：主要危害叶片、茎和果实。叶片发病，初为水渍状褐色斑点，后扩大为近圆形或不规则形褐色病斑，病斑上有明显的轮纹，湿度大时病斑上生有灰色霉层。茎部发病，初为水渍状褐色斑点，后变为褐色长条斑，严重时茎部腐烂。果实发病，初为水渍状灰白色病斑，后变为褐色，病部软腐，湿度大时病斑上生有灰色霉层。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004223', 'source-doc-4c784a84a66adf221597', 'source-node-004220', '4', '4222', 'text', '发病规律：病菌以菌丝体、分生孢子及菌核在病残体上越冬，翌年产生分生孢子，借风雨、气流传播，从伤口或衰弱部位侵入。低温高湿（温度 15 - 25℃，相对湿度 90% 以上）条件有利于发病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004224', 'source-doc-4c784a84a66adf221597', 'source-node-004220', '4', '4223', 'text', '防治方法：加强通风透光，降低湿度，控制浇水，避免偏施氮肥。及时清除病残体，减少病菌来源。发病初期，可选用 50% 速克灵可湿性粉剂 1500 倍液、50% 扑海因可湿性粉剂 1000 倍液、40% 施佳乐悬浮剂 800 倍液等药剂喷雾防治。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004225', 'source-doc-4c784a84a66adf221597', 'source-node-004151', '3', '4224', 'text', '菌核病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004226', 'source-doc-4c784a84a66adf221597', 'source-node-004225', '4', '4225', 'text', '病原：由核盘菌引起。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004227', 'source-doc-4c784a84a66adf221597', 'source-node-004225', '4', '4226', 'text', '症状表现：主要危害茎基部和果实。茎基部发病，初为水渍状褐色病斑，后变为灰白色，病部软腐，表面生有白色棉絮状菌丝，后期在菌丝上形成黑色鼠粪状菌核。果实发病，初为水渍状褐色病斑，后变为灰白色，病部软腐，表面生有白色棉絮状菌丝，后期在菌丝上形成黑色菌核。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004228', 'source-doc-4c784a84a66adf221597', 'source-node-004225', '4', '4227', 'text', '发病规律：病菌以菌核在土壤中或病残体上越冬，翌年菌核萌发产生子囊盘，释放子囊孢子，借风雨、气流传播，从伤口或衰弱部位侵入。低温高湿（温度 15 - 20℃，相对湿度 85% 以上）条件有利于发病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004229', 'source-doc-4c784a84a66adf221597', 'source-node-004225', '4', '4228', 'text', '防治方法：实行轮作，与非茄科作物轮作 3 - 4 年。加强田间管理，及时清除病残体，保持通风透光，降低湿度。发病初期，可选用 50% 速克灵可湿性粉剂 1000 倍液、50% 扑海因可湿性粉剂 1000 倍液、40% 菌核净可湿性粉剂 1000 倍液等药剂喷雾防治，并及时清除病株，带出田间深埋或烧毁。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004230', 'source-doc-4c784a84a66adf221597', 'source-node-004150', '2', '4229', 'text', '虫害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004231', 'source-doc-4c784a84a66adf221597', 'source-node-004230', '3', '4230', 'text', '蚜虫128 ：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004232', 'source-doc-4c784a84a66adf221597', 'source-node-004231', '4', '4231', 'text', '种类及习性：常见的有桃蚜、瓜蚜等。蚜虫繁殖能力强，一年可繁殖多代，以卵在越冬寄主上或以成蚜、若蚜在温室内蔬菜上越冬，翌年春季温度适宜时开始活动，群集在茄子的叶片、嫩茎、花蕾等部位吸食汁液。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004233', 'source-doc-4c784a84a66adf221597', 'source-node-004231', '4', '4232', 'text', '危害症状：叶片受害后，叶片卷曲、皱缩，生长不良；嫩茎、花蕾受害后，生长受阻，花朵不能正常开放，影响茄子的坐果率。此外，蚜虫还可传播多种病毒病，加重茄子的病情。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004234', 'source-doc-4c784a84a66adf221597', 'source-node-004231', '4', '4233', 'text', '防治方法：可采用物理防治，如悬挂黄色诱虫板诱杀蚜虫；生物防治，释放瓢虫、草蛉等天敌昆虫；化学防治，可选用 10% 吡虫啉可湿性粉剂 2000 - 3000 倍液、3% 啶虫脒乳油 1500 - 2000 倍液等药剂喷雾防治。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004235', 'source-doc-4c784a84a66adf221597', 'source-node-004230', '3', '4234', 'text', '红蜘蛛128 ：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004236', 'source-doc-4c784a84a66adf221597', 'source-node-004235', '4', '4235', 'text', '种类及习性：主要有朱砂叶螨、二斑叶螨等。红蜘蛛以成螨、若螨在茄子叶片背面吐丝结网，吸食叶片汁液。在高温干旱的条件下繁殖迅速，一般在 7 - 8 月高温季节发生较重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004237', 'source-doc-4c784a84a66adf221597', 'source-node-004235', '4', '4236', 'text', '危害症状：叶片受害后，出现黄白色斑点，严重时叶片干枯脱落，影响茄子的光合作用，导致植株生长衰弱，产量降低。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004238', 'source-doc-4c784a84a66adf221597', 'source-node-004235', '4', '4237', 'text', '防治方法：农业防治上，及时清除田间杂草和病残体，减少红蜘蛛的越冬场所。生物防治可释放捕食螨等天敌。化学防治可选用 1.8% 阿维菌素乳油 3000 - 4000 倍液、20% 哒螨灵乳油 1500 - 2000 倍液等药剂喷雾防治，注意叶片背面要喷匀喷透。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004239', 'source-doc-4c784a84a66adf221597', 'source-node-004230', '3', '4238', 'text', '蓟马123 ：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004240', 'source-doc-4c784a84a66adf221597', 'source-node-004239', '4', '4239', 'text', '种类及习性：常见的有西花蓟马、瓜蓟马等。蓟马体型微小，锉吸式口器，多在茄子的嫩梢、嫩叶、花和幼果等部位取食。蓟马喜欢温暖干旱的环境，一般在春季和秋季发生较重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004241', 'source-doc-4c784a84a66adf221597', 'source-node-004239', '4', '4240', 'text', '危害症状：叶片受害后，出现白色斑点，严重时叶片变小、变硬、卷曲；幼果受害后，表面出现锈褐色斑点，果实畸形，生长缓慢。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004242', 'source-doc-4c784a84a66adf221597', 'source-node-004239', '4', '4241', 'text', '防治方法：物理防治可悬挂蓝色诱虫板诱杀蓟马。化学防治可选用 2.5% 多杀霉素悬浮剂 1000 - 1500 倍液、10% 溴虫氟苯双酰胺悬浮剂 2000 - 3000 倍液等药剂喷雾防治，注意在早晨或傍晚蓟马活动高峰期施药效果较好。杀蓟马卵用吡丙醚或唑虫酰胺', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004243', 'source-doc-4c784a84a66adf221597', 'source-node-004230', '3', '4242', 'text', '茄螟13 ：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004244', 'source-doc-4c784a84a66adf221597', 'source-node-004243', '4', '4243', 'text', '种类及习性：又称茄黄斑螟，以幼虫蛀食茄子的花蕾、花蕊、子房、果实等部位，造成落花、落果及果实腐烂。幼虫老熟后在茄子的茎秆、残枝落叶等处结茧化蛹越冬。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004245', 'source-doc-4c784a84a66adf221597', 'source-node-004243', '4', '4244', 'text', '危害症状：花蕾受害后，不能正常开放；果实受害后，内部被蛀食，形成孔洞，严重影响茄子的品质和产量。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004246', 'source-doc-4c784a84a66adf221597', 'source-node-004243', '4', '4245', 'text', '防治方法：及时清除田间的落花、落果及残枝落叶，减少虫源。在幼虫孵化高峰期，可选用 2.5% 溴氰菊酯乳油 2000 - 3000 倍液、5% 高效氯氟氰菊酯乳油 2000 - 3000 倍液等药剂喷雾防治，重点喷施茄子的花蕾、幼果等部位。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004247', 'source-doc-4c784a84a66adf221597', 'source-node-004230', '3', '4246', 'text', '茄二十八星瓢虫1310 ：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004248', 'source-doc-4c784a84a66adf221597', 'source-node-004247', '4', '4247', 'text', '种类及习性：主要危害茄子的叶片，以成虫和幼虫取食叶片的叶肉，仅留表皮，形成许多不规则的透明斑。成虫具有假死性，受惊后会落地装死。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004249', 'source-doc-4c784a84a66adf221597', 'source-node-004247', '4', '4248', 'text', '危害症状：叶片受害严重时，叶片干枯、破碎，影响茄子的光合作用，导致植株生长不良。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004250', 'source-doc-4c784a84a66adf221597', 'source-node-004247', '4', '4249', 'text', '防治方法：人工捕捉成虫，利用其假死性，在清晨或傍晚进行捕杀。及时清除田间杂草和残株，减少瓢虫的栖息场所。化学防治可选用 2.5% 溴氰菊酯乳油 2000 - 3000 倍液、4.5% 高效氯氰菊酯乳油 1500 - 2000 倍液等药剂喷雾防治。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004251', 'source-doc-4c784a84a66adf221597', 'source-node-004230', '3', '4250', 'text', '斑潜蝇168 ：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004252', 'source-doc-4c784a84a66adf221597', 'source-node-004251', '4', '4251', 'text', '种类及习性：常见的有美洲斑潜蝇、南美斑潜蝇等。斑潜蝇的成虫和幼虫均可危害茄子，成虫用产卵器刺伤叶片产卵，幼虫在叶片内潜食叶肉，形成不规则的蛇形白色虫道。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004253', 'source-doc-4c784a84a66adf221597', 'source-node-004251', '4', '4252', 'text', '危害症状：叶片受害后，光合作用受到影响，导致叶片早衰、脱落，严重影响茄子的生长和产量。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004254', 'source-doc-4c784a84a66adf221597', 'source-node-004251', '4', '4253', 'text', '防治方法：农业防治上，合理轮作，与非豆科、茄科蔬菜轮作。物理防治可悬挂黄色诱虫板诱杀成虫。化学防治可选用 1.8% 阿维菌素乳油 3000 倍液、75% 灭蝇胺可湿性粉剂 5000 倍液等药剂喷雾防治，重点喷施叶片背面。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004255', 'source-doc-4c784a84a66adf221597', 'source-node-004230', '3', '4254', 'text', '白粉虱123 ：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004256', 'source-doc-4c784a84a66adf221597', 'source-node-004255', '4', '4255', 'text', '种类及习性：又称小白蛾子，以成虫和若虫群集在茄子叶片背面吸食汁液，分泌蜜露，诱发煤污病。白粉虱繁殖速度快，世代重叠严重，在温室和露地均可发生。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004257', 'source-doc-4c784a84a66adf221597', 'source-node-004255', '4', '4256', 'text', '危害症状：叶片受害后，出现褪绿变黄、萎蔫，严重时叶片干枯脱落。同时，蜜露污染叶片和果实，影响茄子的外观品质。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004258', 'source-doc-4c784a84a66adf221597', 'source-node-004255', '4', '4257', 'text', '防治方法：物理防治可悬挂黄色诱虫板诱杀成虫，或安装防虫网防止白粉虱进入田间。生物防治可释放丽蚜小蜂等天敌昆虫。化学防治可选用 25% 噻虫嗪水分散粒剂 3000 - 4000 倍液、10% 吡丙醚乳油 1000 - 1500 倍液等药剂喷雾防治，注意叶片背面要喷匀喷透。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004259', 'source-doc-4c784a84a66adf221597', 'source-node-004230', '3', '4258', 'text', '茶黄螨11012 ：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004260', 'source-doc-4c784a84a66adf221597', 'source-node-004259', '4', '4259', 'text', '种类及习性：成螨和幼螨集中在茄子的幼嫩部位，如嫩叶、嫩茎、花和幼果等，用口器刺入植物组织吸食汁液。茶黄螨喜欢温暖潮湿的环境，一般在夏季高温多雨季节发生较重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004261', 'source-doc-4c784a84a66adf221597', 'source-node-004259', '4', '4260', 'text', '危害症状：叶片受害后，叶片变厚变小、变硬，叶背呈茶锈色，油渍状，叶缘向下卷曲；嫩茎受害后，呈黄褐色，扭曲畸形；花和幼果受害后，不开花或开花异常，果实变小、变硬，表面粗糙，失去光泽，严重影响茄子的产量和品质。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004262', 'source-doc-4c784a84a66adf221597', 'source-node-004259', '4', '4261', 'text', '防治方法：及时清除田间杂草和病残体，减少虫源。化学防治可选用 1.8% 阿维菌素乳油 3000 - 4000 倍液、20% 哒螨灵乳油 1500 - 2000 倍液等药剂喷雾防治，重点喷施茄子的幼嫩部位，每隔 7', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004263', 'source-doc-4c784a84a66adf221597', 'source-node-004230', '3', '4262', 'text', '根结线虫', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004264', 'source-doc-4c784a84a66adf221597', 'source-node-004263', '4', '4263', 'text', '病原及习性：主要是南方根结线虫、北方根结线虫等。根结线虫以卵和二龄幼虫在土壤和病根残体中越冬。条件适宜时，卵孵化出二龄幼虫，侵入茄子根部。线虫在土壤中活动范围较小，主要靠农事操作、灌溉水、病土等传播。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004265', 'source-doc-4c784a84a66adf221597', 'source-node-004263', '4', '4264', 'text', '症状表现：主要危害茄子根部。发病初期，地上部分植株生长缓慢，叶片发黄。地下部分根系产生大小不等的根结，根结初期为白色，后变为褐色，严重时多个根结连接在一起，使根系肿胀、畸形。根结上可生出细弱新根，再次被侵染后又形成根结。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004266', 'source-doc-4c784a84a66adf221597', 'source-node-004263', '4', '4265', 'text', '防治方法：实行轮作，与非寄主植物如禾本科作物轮作 3 - 5 年。在种植前对土壤进行消毒，可使用棉隆等杀线虫剂处理土壤。生物防治可施用含有淡紫拟青霉的生物制剂，这种真菌可以寄生根结线虫。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004267', 'source-doc-4c784a84a66adf221597', 'source-node-004230', '3', '4266', 'text', '地老虎', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004268', 'source-doc-4c784a84a66adf221597', 'source-node-004267', '4', '4267', 'text', '种类及习性：常见的有小地老虎、黄地老虎等。地老虎是一种地下害虫，以幼虫为害茄子幼苗。成虫具有趋光性和趋化性，喜欢在杂草丛生的地方产卵。幼虫白天潜伏在土中，夜晚出土活动，咬断茄子幼苗的茎基部，造成缺苗断垄。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004269', 'source-doc-4c784a84a66adf221597', 'source-node-004267', '4', '4268', 'text', '症状表现：幼苗茎基部被咬断，造成幼苗死亡。在受害植株周围的土壤表面可以发现明显的断苗痕迹。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004270', 'source-doc-4c784a84a66adf221597', 'source-node-004267', '4', '4269', 'text', '防治方法：农业防治包括清除田间杂草，减少地老虎的产卵场所。物理防治可采用黑光灯诱捕成虫。化学防治可在幼虫期用 90% 晶体敌百虫 800 - 1000 倍液灌根，或者用毒饵诱杀，如用炒香的麦麸或豆饼等与敌百虫混合后撒在田间。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004271', 'source-doc-4c784a84a66adf221597', 'source-node-004230', '3', '4270', 'text', '蛴螬', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004272', 'source-doc-4c784a84a66adf221597', 'source-node-004271', '4', '4271', 'text', '种类及习性：蛴螬是金龟子的幼虫，种类繁多。它们生活在土壤中，主要取食植物的根系。蛴螬有假死性，喜欢在富含有机质的土壤中生存。一般在春季和秋季活动较为频繁。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004273', 'source-doc-4c784a84a66adf221597', 'source-node-004271', '4', '4272', 'text', '症状表现：主要危害茄子根部，咬断或咬伤根系，使植株生长不良，叶片发黄、枯萎。严重时导致植株死亡。在受害植株根部周围的土壤中可以发现蛴螬。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004274', 'source-doc-4c784a84a66adf221597', 'source-node-004271', '4', '4273', 'text', '防治方法：农业防治包括合理施肥，避免施用未腐熟的有机肥，因为这些肥料会吸引金龟子产卵。生物防治可利用天敌昆虫如步行虫、寄生蜂等来控制蛴螬数量。化学防治可在播种或定植前，用 50% 辛硫磷乳油拌种，或者用辛硫磷颗粒剂撒施在土壤中进行土壤处理。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004275', 'source-doc-4c784a84a66adf221597', 'source-node-004230', '3', '4274', 'text', '金针虫', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004276', 'source-doc-4c784a84a66adf221597', 'source-node-004275', '4', '4275', 'text', '种类及习性：金针虫是叩头虫的幼虫，主要在土壤中生活。它们具有趋湿性，喜欢在潮湿的土壤中活动。金针虫的活动能力较强，能够在土壤中上下移动，主要危害植物的根系和地下茎。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004277', 'source-doc-4c784a84a66adf221597', 'source-node-004275', '4', '4276', 'text', '症状表现：主要危害茄子的根部和地下茎，蛀食后造成植株生长衰弱，叶片发黄、萎蔫。在受害部位可以发现针状小孔。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004278', 'source-doc-4c784a84a66adf221597', 'source-node-004275', '4', '4277', 'text', '防治方法：农业防治包括合理轮作、深耕土地，破坏金针虫的生存环境。化学防治可选用 40% 辛硫磷乳油 1000 - 1500 倍液灌根，或者在播种前用辛硫磷颗粒剂处理土壤。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004279', 'source-doc-4c784a84a66adf221597', 'source-node-002718', '1', '4278', 'text', '2.2.4 生菜', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004280', 'source-doc-4c784a84a66adf221597', 'source-node-004279', '2', '4279', 'text', '细菌性病害：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004281', 'source-doc-4c784a84a66adf221597', 'source-node-004280', '3', '4280', 'text', '暂无典型细菌性病害详述（如有生菜软腐病菌中的欧文氏菌归类争议，其兼具细菌病害特点，发病规律等类似十字花科软腐病）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004282', 'source-doc-4c784a84a66adf221597', 'source-node-004281', '4', '4281', 'text', '发病规律（以类似软腐病参考）：病原菌在病残体、土壤及害虫体内越冬，借助雨水、灌溉水、昆虫等传播，从植株伤口（如农事操作、虫咬伤口）侵入，高温高湿（25 - 30℃、相对湿度90%以上）、植株生长衰弱、田间积水易发病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004283', 'source-doc-4c784a84a66adf221597', 'source-node-004281', '4', '4282', 'text', '预防方法：合理轮作，避免连作，精细农事操作减少伤口，及时排水防涝，收获后清园，清除病残体。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004284', 'source-doc-4c784a84a66adf221597', 'source-node-004281', '4', '4283', 'text', '防治方法：发病初期，用72%农用链霉素可溶性粉剂3000 - 4000倍液、新植霉素4000 - 5000倍液等喷雾或灌根，重点针对发病植株基部及周边，7 - 10天1次，连施2 - 3次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004285', 'source-doc-4c784a84a66adf221597', 'source-node-004279', '2', '4284', 'text', '真菌性病害：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004286', 'source-doc-4c784a84a66adf221597', 'source-node-004285', '3', '4285', 'text', '霜霉病（Peronospora farinosa）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004287', 'source-doc-4c784a84a66adf221597', 'source-node-004286', '4', '4286', 'text', '发病规律：病原菌以卵孢子在病残体或土壤中越冬，15 - 20℃、相对湿度90%以上，卵孢子萌发产生游动孢子囊，借风雨传播到生菜叶片，从气孔或表皮侵入，种植过密、通风透光不良、湿度大环境发病重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004288', 'source-doc-4c784a84a66adf221597', 'source-node-004286', '4', '4287', 'text', '预防方法：选用抗病品种，合理密植，加强田间通风透光，及时清除病残体，高垄栽培利于排水降湿。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004289', 'source-doc-4c784a84a66adf221597', 'source-node-004286', '4', '4288', 'text', '防治方法：发病初期，可选用72%霜脲·锰锌可湿性粉剂600 - 800倍液、69%烯酰·锰锌可湿性粉剂800 - 1000倍液等喷雾，7 - 10天1次，连喷2 - 3次。霜霉威安全性高一些、甲霜灵，在黄瓜上一喷雾器100g霜霉为盐酸盐也很安全；氟菌·霜霉威+烯酰·氰霜唑；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004290', 'source-doc-4c784a84a66adf221597', 'source-node-004285', '3', '4289', 'text', '灰霉病（Botrytis cinerea）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004291', 'source-doc-4c784a84a66adf221597', 'source-node-004290', '4', '4290', 'text', '发病规律：以菌核在土壤或病残体越冬，20 - 25℃、相对湿度90%以上，菌核萌发产分生孢子，借气流、雨水、农事操作传至植株，从伤口、衰弱组织侵入，生菜生长后期，植株茂密、通风差、湿度大易发病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004292', 'source-doc-4c784a84a66adf221597', 'source-node-004290', '4', '4291', 'text', '预防方法：加强通风，合理浇水，避免大水漫灌，及时摘除病叶、病株。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004293', 'source-doc-4c784a84a66adf221597', 'source-node-004290', '4', '4292', 'text', '防治方法：发病初期，用40%嘧霉胺悬浮剂800 - 1000倍液、50%异菌脲可湿性粉剂1000 - 1500倍液等喷雾，7 - 10天1次，连喷2 - 3次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004294', 'source-doc-4c784a84a66adf221597', 'source-node-004285', '3', '4293', 'text', '菌核病（Sclerotinia sclerotiorum）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004295', 'source-doc-4c784a84a66adf221597', 'source-node-004294', '4', '4294', 'text', '发病规律：菌核在土壤或病残体蛰伏越冬，15 - 20℃、湿度适宜时，萌发产生子囊盘和子囊孢子，借气流、雨水传播，从衰弱或损伤组织侵入，连作、排水不良地块发病风险高。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004296', 'source-doc-4c784a84a66adf221597', 'source-node-004294', '4', '4295', 'text', '预防方法：深翻土壤深埋菌核，轮作倒茬，清理病残体，保持田间卫生。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004297', 'source-doc-4c784a84a66adf221597', 'source-node-004294', '4', '4296', 'text', '防治方法：发病初期，可选用40%菌核净可湿性粉剂1000 - 1500倍液、50%腐霉利可湿性粉剂1000 - 1500倍液喷雾或灌根，7 - 10天1次，连施2 - 3次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004298', 'source-doc-4c784a84a66adf221597', 'source-node-004285', '3', '4297', 'text', '白粉病（Erysiphe cichoracearum）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004299', 'source-doc-4c784a84a66adf221597', 'source-node-004298', '4', '4298', 'text', '发病规律：以菌丝体或闭囊壳在病残体越冬，20 - 25℃、相对湿度70%左右，分生孢子借气流传播，反复侵染，田间郁闭、通风透光差利于发病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004300', 'source-doc-4c784a84a66adf221597', 'source-node-004298', '4', '4299', 'text', '预防方法：选抗病品种，合理密植，增施有机肥和磷钾肥，定期清理病残株，改善通风条件。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004301', 'source-doc-4c784a84a66adf221597', 'source-node-004298', '4', '4300', 'text', '防治方法：发病初期，用25%粉锈宁（三唑酮）可湿性粉剂1500 - 2000倍液、10%苯醚甲环唑水分散粒剂800 - 1000倍液等喷雾，7 - 10天1次，连喷2 - 3次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004302', 'source-doc-4c784a84a66adf221597', 'source-node-004298', '4', '4301', 'text', '生理病害：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004303', 'source-doc-4c784a84a66adf221597', 'source-node-004285', '3', '4302', 'text', '暂无典型单一详述生理病害（生菜生长常遇叶片黄化等，多与营养失衡、环境不良关联）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004304', 'source-doc-4c784a84a66adf221597', 'source-node-004303', '4', '4303', 'text', '发病规律（以叶片黄化为例）：土壤肥力不足，缺乏氮、铁、镁等元素，或土壤酸碱度不适宜，水分供应失调（干旱或积水），光照过强或不足，导致叶片光合作用、呼吸作用等生理过程紊乱，出现黄化、生长缓慢等症状。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004305', 'source-doc-4c784a84a66adf221597', 'source-node-004303', '4', '4304', 'text', '预防方法：测土配方施肥，依据生菜需肥规律补施肥料，改良土壤，保持适宜酸碱度，合理灌溉，避免强光直晒，可遮阳网调控光照。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004306', 'source-doc-4c784a84a66adf221597', 'source-node-004303', '4', '4305', 'text', '防治方法：针对缺素，缺氮可追施尿素，缺铁喷施0.1% - 0.2%硫酸亚铁溶液，缺镁喷施0.5%硫酸镁溶液，调节水分、光照等环境因素，促进恢复。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004307', 'source-doc-4c784a84a66adf221597', 'source-node-004303', '4', '4306', 'text', '病毒：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004308', 'source-doc-4c784a84a66adf221597', 'source-node-004285', '3', '4307', 'text', '暂无典型严重病毒病害详述（生菜可能感染黄瓜花叶病毒等）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004309', 'source-doc-4c784a84a66adf221597', 'source-node-004308', '4', '4308', 'text', '发病规律（以黄瓜花叶病毒参考）：病毒在多年生杂草、种子、土壤等越冬，通过蚜虫等刺吸式害虫传毒，高温干旱（28 - 32℃）、生菜幼苗期至莲座期，植株抗性弱时易感染，田间杂草多、蚜虫防治不力易流行。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004310', 'source-doc-4c784a84a66adf221597', 'source-node-004308', '4', '4309', 'text', '预防方法：选用抗病品种，种子消毒（温水浸种等），清除田间杂草，防虫网防蚜虫迁入，悬挂黄色粘虫板诱杀蚜虫，培育壮苗。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004311', 'source-doc-4c784a84a66adf221597', 'source-node-004308', '4', '4310', 'text', '防治方法：发病初期，用20%病毒A可湿性粉剂500倍液、1.5%植病灵乳剂1000倍液等喷雾，结合防治蚜虫药剂如10%吡虫啉可湿性粉剂1500 - 2000倍液，7 - 10天1次，连喷3 - 4次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004312', 'source-doc-4c784a84a66adf221597', 'source-node-004279', '2', '4311', 'text', '虫害：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004313', 'source-doc-4c784a84a66adf221597', 'source-node-004312', '3', '4312', 'text', '蚜虫（Aphididae）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004314', 'source-doc-4c784a84a66adf221597', 'source-node-004313', '4', '4313', 'text', '发病规律：以卵在杂草等寄主越冬，春天气温回升孵化，迁移至生菜，16 - 22℃、湿度适宜时繁殖快，群集叶片背面、嫩茎吸食，致叶片卷曲、畸形，传播病毒病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004315', 'source-doc-4c784a84a66adf221597', 'source-node-004313', '4', '4314', 'text', '预防方法：田园周边除草，悬挂黄色粘虫板，保护利用瓢虫、草蛉等天敌。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004316', 'source-doc-4c784a84a66adf221597', 'source-node-004313', '4', '4315', 'text', '防治方法：用10%吡虫啉可湿性粉剂1500 - 2000倍液、50%抗蚜威可湿性粉剂2000 - 3000倍液等喷雾，7 - 10天1次，视虫情喷2 - 3次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004317', 'source-doc-4c784a84a66adf221597', 'source-node-004312', '3', '4316', 'text', '潜叶蝇（Liriomyza spp.）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004318', 'source-doc-4c784a84a66adf221597', 'source-node-004317', '4', '4317', 'text', '发病规律：以蛹在土壤越冬，成虫产卵于生菜叶片表皮下，20 - 30℃时，幼虫孵化后在叶肉潜食，形成弯曲虫道，影响光合作用和品质，高温干旱利于繁殖。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004319', 'source-doc-4c784a84a66adf221597', 'source-node-004317', '4', '4318', 'text', '预防方法：田园清洁，清除杂草残株，悬挂蓝色粘虫板诱杀成虫，合理轮作。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004320', 'source-doc-4c784a84a66adf221597', 'source-node-004317', '4', '4319', 'text', '防治方法：幼虫初发期，用1.8%阿维菌素乳油1000 - 1500倍液、40%灭蝇胺可湿性粉剂1500 - 2000倍液等喷雾，重点喷叶片，7 - 10天1次，连喷2 - 3次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004321', 'source-doc-4c784a84a66adf221597', 'source-node-004312', '3', '4320', 'text', '蓟马（Thrips spp.）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004322', 'source-doc-4c784a84a66adf221597', 'source-node-004321', '4', '4321', 'text', '发病规律：成虫在杂草、土缝越冬，趋蓝性，20 - 28℃活跃，在生菜叶片、花吸食，造成白斑、畸形，传播病毒，温暖干燥繁殖快。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004323', 'source-doc-4c784a84a66adf221597', 'source-node-004321', '4', '4322', 'text', '预防方法：悬挂蓝色粘虫板，种植前清杂草，释放捕食螨等天敌。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004324', 'source-doc-4c784a84a66adf221597', 'source-node-004321', '4', '4323', 'text', '防治方法：用2.5%多杀霉素悬浮剂1000 - 1500倍液、10%吡虫啉可湿性粉剂1500 - 2000倍液等喷雾，重点喷花和幼叶，7 - 10天1次，喷2 - 3次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004325', 'source-doc-4c784a84a66adf221597', 'source-node-004312', '3', '4324', 'text', '跳甲（Phyllotreta spp.）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004326', 'source-doc-4c784a84a66adf221597', 'source-node-004325', '4', '4325', 'text', '发病规律：成虫在田边杂草、残株及土缝越冬，春季温度回升（10℃以上）活动，趋嫩性、趋化性，跳跃至生菜，啃食叶片成孔洞，产卵于根部附近土壤，幼虫啃食根部，高温干旱时为害重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004327', 'source-doc-4c784a84a66adf221597', 'source-node-004325', '4', '4326', 'text', '预防方法：田园清洁，深耕晒土，破坏越冬场所，覆盖地膜防成虫产卵，间作防虫植物（如大蒜等有驱虫作用）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004328', 'source-doc-4c784a84a66adf221597', 'source-node-004325', '4', '4327', 'text', '防治方法：成虫期，用5%高效氯氟氰菊酯乳油2000 - 3000倍液喷雾，幼虫期用40%辛硫磷乳油1000倍液灌根，7 - 10天1次，依虫态防治2 - 3次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004329', 'source-doc-4c784a84a66adf221597', 'source-node-002718', '1', '4328', 'text', '2.2.5玉米挪去主粮作物了', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004330', 'source-doc-4c784a84a66adf221597', 'source-node-002718', '1', '4329', 'text', '2.2.5 草莓', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004331', 'source-doc-4c784a84a66adf221597', 'source-node-004330', '2', '4330', 'text', '细菌性病害：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004332', 'source-doc-4c784a84a66adf221597', 'source-node-004331', '3', '4331', 'text', '草莓黏菌病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004333', 'source-doc-4c784a84a66adf221597', 'source-node-004332', '4', '4332', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004334', 'source-doc-4c784a84a66adf221597', 'source-node-004333', '5', '4333', 'text', '初期病部布满胶黏状浅黄色液体，后期长出浅黄色圆柱形孢子囊（周围蓝黑色带白色短柄），覆盖叶片、叶柄和茎；近地面嫩叶、嫩心受害重，影响光合与呼吸，叶不能正常伸展，严重时植株枯死、果实腐烂', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004335', 'source-doc-4c784a84a66adf221597', 'source-node-004332', '4', '4334', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004336', 'source-doc-4c784a84a66adf221597', 'source-node-004335', '5', '4335', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004337', 'source-doc-4c784a84a66adf221597', 'source-node-004332', '4', '4336', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004338', 'source-doc-4c784a84a66adf221597', 'source-node-004337', '5', '4337', 'text', '半圆双皮菌（Didermahemisphaericum）和白柄菌（Diachealeucopodia），属原生动物界黏菌门', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004339', 'source-doc-4c784a84a66adf221597', 'source-node-004332', '4', '4338', 'text', '发病规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004340', 'source-doc-4c784a84a66adf221597', 'source-node-004339', '5', '4339', 'text', '黏菌分布广泛，凡有植物或残体处，温湿度适宜即生存；栽植过密、田间潮湿、杂草多利于发病蔓延', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004341', 'source-doc-4c784a84a66adf221597', 'source-node-004332', '4', '4340', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004342', 'source-doc-4c784a84a66adf221597', 'source-node-004341', '5', '4341', 'text', '农业措施：选高燥平坦沙性土栽植；雨后及时排水，避免大水漫灌；清除杂草残体，合理密植。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004343', 'source-doc-4c784a84a66adf221597', 'source-node-004341', '5', '4342', 'text', '药剂防治：发病初期喷50%多菌灵悬浮剂600倍液或45%噻菌灵悬浮剂1000-1500倍液，采收前7天停药。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004344', 'source-doc-4c784a84a66adf221597', 'source-node-004331', '3', '4343', 'text', '暂无典型严重细菌性病害详述（草莓可能受欧文氏菌等引发软腐类似情况）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004345', 'source-doc-4c784a84a66adf221597', 'source-node-004344', '4', '4344', 'text', '发病规律（参考软腐特点）：病原菌在病残体、土壤及害虫体内越冬，借助雨水、灌溉水、昆虫等传播，从植株伤口（采摘、机械损伤、虫咬等）侵入，高温高湿（25 - 30℃、相对湿度90%以上）、植株生长后期、果实成熟期易发病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004346', 'source-doc-4c784a84a66adf221597', 'source-node-004344', '4', '4345', 'text', '预防方法：合理轮作，避免连作，精细农事操作减少伤口，及时排水防涝，收获后清园，清除病残体，种植前土壤消毒（如用石灰氮等处理）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004347', 'source-doc-4c784a84a66adf221597', 'source-node-004344', '4', '4346', 'text', '防治方法：发病初期，用72%农用链霉素可溶性粉剂3000 - 4000倍液、新植霉素4000 - 5000倍液等喷雾或灌根，重点针对发病植株基部及周边，7 - 10天1次，连施2 - 3次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004348', 'source-doc-4c784a84a66adf221597', 'source-node-004330', '2', '4347', 'text', '真菌性病害：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004349', 'source-doc-4c784a84a66adf221597', 'source-node-004348', '3', '4348', 'text', '草莓白粉病（Sphaerotheca macularis）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004350', 'source-doc-4c784a84a66adf221597', 'source-node-004349', '4', '4349', 'text', '发病规律：以菌丝体或闭囊壳在病残体及草莓植株上越冬，15 - 25℃、相对湿度80%左右，分生孢子借气流传播，反复侵染，在草莓生长中后期，植株郁闭、通风透光差、湿度大时发病重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004351', 'source-doc-4c784a84a66adf221597', 'source-node-004349', '4', '4350', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004352', 'source-doc-4c784a84a66adf221597', 'source-node-004351', '5', '4351', 'text', '白粉病主要为害草莓的叶、叶柄、花、花梗和果实', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004353', 'source-doc-4c784a84a66adf221597', 'source-node-004349', '4', '4352', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004354', 'source-doc-4c784a84a66adf221597', 'source-node-004353', '5', '4353', 'text', 'Podosphaeraaphanis（滇赤才叉丝单囊壳），属子囊菌门', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004355', 'source-doc-4c784a84a66adf221597', 'source-node-004349', '4', '4354', 'text', '防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004356', 'source-doc-4c784a84a66adf221597', 'source-node-004355', '5', '4355', 'text', '预防方法：选用抗病品种，合理密植，及时整枝打杈，改善通风透光，增施有机肥和磷钾肥，控制氮肥用量，定期清理病残株。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004357', 'source-doc-4c784a84a66adf221597', 'source-node-004355', '5', '4356', 'text', '农业防治：选抗病品种（如杜克拉、甜查理）；清洁园地，摘除病残叶；合理施肥，避免偏氮；高畦栽培，通风降湿。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004358', 'source-doc-4c784a84a66adf221597', 'source-node-004355', '5', '4357', 'text', '生物防治：用100亿活芽孢/克枯草芽孢杆菌可湿性粉剂防治。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004359', 'source-doc-4c784a84a66adf221597', 'source-node-004355', '5', '4358', 'text', '化学防治：发病初期喷42.5%吡唑醚菌酯・氟唑菌酰胺悬浮剂2000倍液、50%醚菌酯水分散粒剂1000倍液；硫黄熏蒸预防保护地白粉病，发病期每天熏蒸8h，连用7～10次；发病初期可选50%翠贝干悬浮剂5000倍液、42.8%露娜森2000倍液、40%福星乳油8000倍液喷雾，7～10天喷1次，连续防治3次', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004360', 'source-doc-4c784a84a66adf221597', 'source-node-004359', '6', '4359', 'text', '防治方法：发病初期，用25%粉锈宁（三唑酮）可湿性粉剂1500 - 2000倍液、10%苯醚甲环唑水分散粒剂800 - 1000倍液等喷雾，7 - 10天1次，连喷2 - 3次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004361', 'source-doc-4c784a84a66adf221597', 'source-node-004349', '4', '4360', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004362', 'source-doc-4c784a84a66adf221597', 'source-node-004361', '5', '4361', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004363', 'source-doc-4c784a84a66adf221597', 'source-node-004348', '3', '4362', 'text', '草莓灰霉病（Botrytis cinerea）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004364', 'source-doc-4c784a84a66adf221597', 'source-node-004363', '4', '4363', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004365', 'source-doc-4c784a84a66adf221597', 'source-node-004364', '5', '4364', 'text', '主要为害叶、花、果柄、花蕾及果实：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004366', 'source-doc-4c784a84a66adf221597', 'source-node-004364', '5', '4365', 'text', '叶片：叶缘处腐烂，田间湿度大时病部产生灰色霉层，严重时病叶枯死；花器：花萼初生水渍状小点，后扩展为病斑并侵入子房及幼果，呈湿腐状，湿度大时产生厚密灰色霉层；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004367', 'source-doc-4c784a84a66adf221597', 'source-node-004364', '5', '4366', 'text', '果实：未成熟果初现浅褐色干枯病斑，后期干腐；已转色果实湿腐软化，病部生灰褐色霉状物，易脱落', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004368', 'source-doc-4c784a84a66adf221597', 'source-node-004363', '4', '4367', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004369', 'source-doc-4c784a84a66adf221597', 'source-node-004368', '5', '4368', 'text', 'BotrytiscinereaPers.exFr.，称灰葡萄孢，属半知菌类真菌', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004370', 'source-doc-4c784a84a66adf221597', 'source-node-004363', '4', '4369', 'text', '发病规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004371', 'source-doc-4c784a84a66adf221597', 'source-node-004370', '5', '4370', 'text', '以菌核在土壤或病残体越冬，18 - 23℃、相对湿度9；可半腐生；孢子借风雨、农事操作传播；病果相互接触及分生孢子可引发再侵染', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004372', 'source-doc-4c784a84a66adf221597', 'source-node-004363', '4', '4371', 'text', '四、防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004373', 'source-doc-4c784a84a66adf221597', 'source-node-004372', '5', '4372', 'text', '农业措施：通风、轮作；深沟高畦、地膜覆盖及膜下灌溉，通风降湿；及时摘除病果、老叶及感病花序。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004374', 'source-doc-4c784a84a66adf221597', 'source-node-004372', '5', '4373', 'text', '药剂防治：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004375', 'source-doc-4c784a84a66adf221597', 'source-node-004374', '6', '4374', 'text', '开花前用10%腐霉利烟剂或45%百菌清烟剂烟熏，每亩300~400g，傍晚点燃密闭一夜；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004376', 'source-doc-4c784a84a66adf221597', 'source-node-004374', '6', '4375', 'text', '发病初期40%嘧霉胺悬浮剂1200倍液或50%腐霉利可湿性粉剂1500~2000倍液，7~10天一次，连续2~3次；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004377', 'source-doc-4c784a84a66adf221597', 'source-node-004348', '3', '4376', 'text', '草莓疫霉果腐病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004378', 'source-doc-4c784a84a66adf221597', 'source-node-004377', '4', '4377', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004379', 'source-doc-4c784a84a66adf221597', 'source-node-004378', '5', '4378', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004380', 'source-doc-4c784a84a66adf221597', 'source-node-004377', '4', '4379', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004381', 'source-doc-4c784a84a66adf221597', 'source-node-004380', '5', '4380', 'text', '主要为害果实、花、根部及匍匐茎：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004382', 'source-doc-4c784a84a66adf221597', 'source-node-004380', '5', '4381', 'text', '根部：由外向里变黑，呈革腐状，湿度大时病根生白霉；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004383', 'source-doc-4c784a84a66adf221597', 'source-node-004380', '5', '4382', 'text', '花穗/果实：花期阴雨天花穗、果实呈开水烫状，1~2天变褐枯死；青果染病现浅褐色水渍斑，迅速蔓延全果，变黑褐色干腐硬化；成熟果病部褪色失去光泽，病健交界处有变色带，水渍状腐烂，湿度大时生稀疏白色霉状物，果肉腐烂有腥臭味，干燥时成僵果；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004384', 'source-doc-4c784a84a66adf221597', 'source-node-004380', '5', '4383', 'text', '匍匐茎：发干萎蔫，最终干死', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004385', 'source-doc-4c784a84a66adf221597', 'source-node-004377', '4', '4384', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004386', 'source-doc-4c784a84a66adf221597', 'source-node-004385', '5', '4385', 'text', '病原为恶疫霉、杜橘腐疫霉、柑橘生疫霉等，属假菌界卵菌门。菌丝分枝少，孢子囊卵形或近球形，易产生卵孢子（球形），生长适温25~28℃', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004387', 'source-doc-4c784a84a66adf221597', 'source-node-004377', '4', '4386', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004388', 'source-doc-4c784a84a66adf221597', 'source-node-004387', '5', '4387', 'text', '病菌以卵孢子在病残体或土壤中越冬，翌春产生孢子囊释放游动孢子，借风雨、流水、农具传播。高湿、强光照是发病重要条件，降雨多发病率高；土壤黏重、地势低洼、偏施氮肥、连作地发病重', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004389', 'source-doc-4c784a84a66adf221597', 'source-node-004377', '4', '4388', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004390', 'source-doc-4c784a84a66adf221597', 'source-node-004389', '5', '4389', 'text', '农业防治：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004391', 'source-doc-4c784a84a66adf221597', 'source-node-004390', '6', '4390', 'text', '选用无病苗，实行洁净栽培；高畦栽培防积水，合理施肥忌偏施氮肥；低洼地及时排水；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004392', 'source-doc-4c784a84a66adf221597', 'source-node-004390', '6', '4391', 'text', '保护地采用高畦低灌，避免大水漫灌；园内铺谷壳减少病原菌传播；及时清除病果病株。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004393', 'source-doc-4c784a84a66adf221597', 'source-node-004389', '5', '4392', 'text', '药剂防治：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004394', 'source-doc-4c784a84a66adf221597', 'source-node-004393', '6', '4393', 'text', '定植前：用30%恶霉灵1500倍液土壤处理；秋季定植时用53%精甲霜・锰锌800倍液浸根；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004395', 'source-doc-4c784a84a66adf221597', 'source-node-004393', '6', '4394', 'text', '花期开始：喷70%锰锌・乙铝500倍液、53%精甲霜・锰锌500倍液等，隔10天1次，连续3~4次；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004396', 'source-doc-4c784a84a66adf221597', 'source-node-004393', '6', '4395', 'text', '生长期：喷淋68%精甲霜・锰锌600倍液、47%春雷・王铜700倍液等', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004397', 'source-doc-4c784a84a66adf221597', 'source-node-004348', '3', '4396', 'text', '草莓灰霉病（Botrytis cinerea）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004398', 'source-doc-4c784a84a66adf221597', 'source-node-004397', '4', '4397', 'text', '发病规律：以菌核在土壤或病残体越冬，18 - 23℃、相对湿度 90% 以上时，菌核萌发产生分生孢子，借助气流、雨水、农事操作在草莓园内传播，多从残花、柱头及伤口等部位侵入，花期、果实膨大期遇连阴天、高湿环境发病严重，常造成花腐、果腐。可半腐生；孢子借风雨、农事操作传播；病果相互接触及分生孢子可引发再侵染', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004399', 'source-doc-4c784a84a66adf221597', 'source-node-004397', '4', '4398', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004400', 'source-doc-4c784a84a66adf221597', 'source-node-004399', '5', '4399', 'text', '主要为害叶、花、果柄、花蕾及果实：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004401', 'source-doc-4c784a84a66adf221597', 'source-node-004399', '5', '4400', 'text', '叶片：叶缘处腐烂，田间湿度大时病部产生灰色霉层，严重时病叶枯死；花器：花萼初生水渍状小点，后扩展为病斑并侵入子房及幼果，呈湿腐状，湿度大时产生厚密灰色霉层；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004402', 'source-doc-4c784a84a66adf221597', 'source-node-004399', '5', '4401', 'text', '果实：未成熟果初现浅褐色干枯病斑，后期干腐；已转色果实湿腐软化，病部生灰褐色霉状物，易脱落', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004403', 'source-doc-4c784a84a66adf221597', 'source-node-004397', '4', '4402', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004404', 'source-doc-4c784a84a66adf221597', 'source-node-004403', '5', '4403', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004405', 'source-doc-4c784a84a66adf221597', 'source-node-004397', '4', '4404', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004406', 'source-doc-4c784a84a66adf221597', 'source-node-004405', '5', '4405', 'text', 'BotrytiscinereaPers.exFr.，称灰葡萄孢，属半知菌类真菌', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004407', 'source-doc-4c784a84a66adf221597', 'source-node-004397', '4', '4406', 'text', '防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004408', 'source-doc-4c784a84a66adf221597', 'source-node-004407', '5', '4407', 'text', '防治方法：发病初期，可选用 40% 嘧霉胺悬浮剂 800 - 1000 倍液、50% 异菌脲可湿性粉剂 1000 - 1500 倍液、50% 腐霉利可湿性粉剂 1000 - 1500 倍液等喷雾，重点喷施花朵、幼果及发病部位周边，7 - 10 天喷 1 次，连续喷 2 - 3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004409', 'source-doc-4c784a84a66adf221597', 'source-node-004408', '6', '4408', 'text', '农业措施：通风、轮作；深沟高畦、地膜覆盖及膜下灌溉，通风降湿；及时摘除病果、老叶及感病花序。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004410', 'source-doc-4c784a84a66adf221597', 'source-node-004408', '6', '4409', 'text', '药剂防治：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004411', 'source-doc-4c784a84a66adf221597', 'source-node-004410', '7', '4410', 'text', '发病初期40%嘧霉胺悬浮剂1200倍液或50%腐霉利可湿性粉剂1500~2000倍液，7~10天一次，连续2~3次；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004412', 'source-doc-4c784a84a66adf221597', 'source-node-004410', '7', '4411', 'text', '开花前用10%腐霉利烟剂或45%百菌清烟剂烟熏，每亩300~400g，傍晚点燃密闭一夜；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004413', 'source-doc-4c784a84a66adf221597', 'source-node-004407', '5', '4412', 'text', '预防方法：采用高畦栽培、地膜覆盖，合理控制种植密度，保证良好通风透光条件；花期、果期严格控制浇水频次与浇水量，避免田间积水、湿度过大；及时摘除病花、病果、病叶，带出田外集中深埋或烧毁，减少病原菌基数。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004414', 'source-doc-4c784a84a66adf221597', 'source-node-004348', '3', '4413', 'text', '草莓黑腐病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004415', 'source-doc-4c784a84a66adf221597', 'source-node-004414', '4', '4414', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004416', 'source-doc-4c784a84a66adf221597', 'source-node-004415', '5', '4415', 'text', '主要为害果实，被害果实初为浅褐色水渍状病斑，继而迅速软化腐烂流汤，切开果肉变黑，果实上生颗粒状黑霉，很快腐烂并波及相邻果实。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004417', 'source-doc-4c784a84a66adf221597', 'source-node-004414', '4', '4416', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004418', 'source-doc-4c784a84a66adf221597', 'source-node-004417', '5', '4417', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004419', 'source-doc-4c784a84a66adf221597', 'source-node-004414', '4', '4418', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004420', 'source-doc-4c784a84a66adf221597', 'source-node-004419', '5', '4419', 'text', '农业防治：避免草莓连作，确需连作时，定植前利用太阳能+石灰氮（50kg/亩）+秸秆（750kg/亩）高温闷棚进行土壤消毒，消毒揭膜后晾3～5天再栽植；加强肥水管理，培育健壮秧苗，及时摘除老叶和病果。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004421', 'source-doc-4c784a84a66adf221597', 'source-node-004419', '5', '4420', 'text', '药剂防治：采收前喷50%多菌灵可湿性粉剂600倍液、70%代森锰锌可湿性粉剂500倍液、50%苯菌灵可湿性粉剂1500倍液、2%农抗120或2%武夷霉素（阿司米星）水剂200倍液、27%高脂膜乳剂80～100倍液（重点喷洒果实）；另外，采前喷0.1%高锰酸钾溶液也有一定防治效果', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004422', 'source-doc-4c784a84a66adf221597', 'source-node-004348', '3', '4421', 'text', '草莓炭疽病（Colletotrichum acutatum）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004423', 'source-doc-4c784a84a66adf221597', 'source-node-004422', '4', '4422', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004424', 'source-doc-4c784a84a66adf221597', 'source-node-004423', '5', '4423', 'text', '发病规律：病原菌主要在病残体、土壤及种苗上越冬，翌年温湿度适宜（25 - 30℃，相对湿度 85% 以上）时，产生分生孢子，借雨水、灌溉水、农事操作及昆虫等传播，从草莓植株的伤口、气孔或直接穿透表皮侵入，高温高湿、连续降雨、植株生长过密、通风不良等情况利于发病，尤其在匍匐茎抽生期、育苗期及定植初期危害较重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004425', 'source-doc-4c784a84a66adf221597', 'source-node-004423', '5', '4424', 'text', '病菌在病残体/土壤越冬，借雨水传播；4-6月发病（5-6月高峰）；适温28-32℃，高温多雨、通风差易流行', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004426', 'source-doc-4c784a84a66adf221597', 'source-node-004422', '4', '4425', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004427', 'source-doc-4c784a84a66adf221597', 'source-node-004426', '5', '4426', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004428', 'source-doc-4c784a84a66adf221597', 'source-node-004422', '4', '4427', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004429', 'source-doc-4c784a84a66adf221597', 'source-node-004428', '5', '4428', 'text', '胶孢炭疽菌、尖孢炭疽菌、草莓炭疽菌，属真菌界无性型子囊菌炭疽菌属', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004430', 'source-doc-4c784a84a66adf221597', 'source-node-004422', '4', '4429', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004431', 'source-doc-4c784a84a66adf221597', 'source-node-004430', '5', '4430', 'text', '危害部位：匍匐茎、叶柄、叶片、果实、根茎部。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004432', 'source-doc-4c784a84a66adf221597', 'source-node-004430', '5', '4431', 'text', '具体表现：叶片有圆形/不规则病斑（0.5-1.5mm，黑或浅灰）；叶柄/匍匐茎呈纺锤形凹陷斑（中央棕褐、边缘紫红）；根茎部新叶高温时萎蔫；果实有近圆形凹陷软腐斑，后期生肉红色黏质孢子团', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004433', 'source-doc-4c784a84a66adf221597', 'source-node-004430', '5', '4432', 'text', '根茎部染病，最初症状是病株最新的2～3个叶片在一天最热的时候出现萎蔫，然后傍晚恢复过来', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004434', 'source-doc-4c784a84a66adf221597', 'source-node-004422', '4', '4433', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004435', 'source-doc-4c784a84a66adf221597', 'source-node-004434', '5', '4434', 'text', '预防方法：选用无病健壮种苗，进行种苗消毒（如用咪鲜胺锰盐等药剂浸种、浸苗）；避免连作，与非蔷薇科作物实行轮作或间作；合理密植，及时摘除老叶、病叶，改善田间通风透光；加强田间排水系统建设，避免积水。栽培：选抗病品种（森格纳、甜查理等），合理密植，增施磷钾肥，清除病残体', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004436', 'source-doc-4c784a84a66adf221597', 'source-node-004434', '5', '4435', 'text', '防治方法：发病前可定期喷施保护性杀菌剂，如代森锰锌、百菌清等；发病初期，选用 25% 咪鲜胺乳油 1000 - 1500 倍液、10% 苯醚甲环唑水分散粒剂 800 - 1000 倍液、20% 唑菌胺酯水分散粒剂 1000 - 1500 倍液等喷雾，7 - 10 天 1 次，连续喷 2 - 3 次，确保药剂均匀覆盖植株。苗期用25%嘧菌酯1500倍液、80%代森锰锌700倍液交替喷施；发病初期用25%溴菌腈500倍液、50%咪鲜胺1500倍液等', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004437', 'source-doc-4c784a84a66adf221597', 'source-node-004348', '3', '4436', 'text', '草莓根腐病（Phytophthora cactorum）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004438', 'source-doc-4c784a84a66adf221597', 'source-node-004437', '4', '4437', 'text', '发病规律：病原菌以卵孢子、厚垣孢子等在土壤及病残体中越冬，在土壤温度 10 - 25℃、湿度大且持续时间长、土壤透气性差的环境下，孢子萌发产生游动孢子，通过雨水、灌溉水及农事操作等传播，从草莓根系伤口或幼嫩组织侵入，连作地、地势低洼、土壤黏重、排水不良地块发病严重，草莓生长前期根系受损后更易被侵染。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004439', 'source-doc-4c784a84a66adf221597', 'source-node-004437', '4', '4438', 'text', '预防方法：选择地势高、排水良好、土质疏松的地块种植；实行轮作倒茬，与水稻等进行水旱轮作效果更佳；种植前对土壤进行消毒处理，可选用棉隆、威百亩等熏蒸剂，改善土壤微生物环境；合理施肥，增施有机肥、生物菌肥，增强根系活力与抗病性。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004440', 'source-doc-4c784a84a66adf221597', 'source-node-004437', '4', '4439', 'text', '防治方法：发病初期，用 58% 甲霜灵・锰锌可湿性粉剂 500 - 600 倍液、64% 杀毒矾可湿性粉剂 500 倍液、72.2% 普力克水剂 800 倍液等灌根，每株灌药量 200 - 300 毫升，7 - 10 天灌 1 次，连续灌 2 - 3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004441', 'source-doc-4c784a84a66adf221597', 'source-node-004348', '3', '4440', 'text', '草莓红中柱根腐', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004442', 'source-doc-4c784a84a66adf221597', 'source-node-004441', '4', '4441', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004443', 'source-doc-4c784a84a66adf221597', 'source-node-004442', '5', '4442', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004444', 'source-doc-4c784a84a66adf221597', 'source-node-004441', '4', '4443', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004445', 'source-doc-4c784a84a66adf221597', 'source-node-004444', '5', '4444', 'text', '地上部：植株矮化或停止发育，嫩叶呈蓝绿色，老叶变黄或红色；分为急性萎蔫型（春夏突然萎蔫青枯）和慢性萎缩型（植株萎缩）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004446', 'source-doc-4c784a84a66adf221597', 'source-node-004444', '5', '4445', 'text', '根部：侧根腐败，不定根从尖端向上腐烂（末端呈鼠尾状），剖开未腐烂处可见中柱由白色变为紫红色至砖红色（又称 “红心病”）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004447', 'source-doc-4c784a84a66adf221597', 'source-node-004441', '4', '4446', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004448', 'source-doc-4c784a84a66adf221597', 'source-node-004447', '5', '4447', 'text', 'Phytophthora fragariae var.fragariae（草莓红心病菌），属假菌界卵菌门疫霉属；还可分离到丝核菌和拟盘多毛孢属真菌。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004449', 'source-doc-4c784a84a66adf221597', 'source-node-004441', '4', '4448', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004450', 'source-doc-4c784a84a66adf221597', 'source-node-004449', '5', '4449', 'text', '病菌以卵孢子在土壤中存活，通过土壤或种子传染；晚秋初冬产生孢子囊，释放游动孢子侵入根部；土壤低温高湿（地温 10℃为适温，高于 25℃不发病）、春秋多雨、低洼排水不良或大水漫灌时易发病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004451', 'source-doc-4c784a84a66adf221597', 'source-node-004441', '4', '4450', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004452', 'source-doc-4c784a84a66adf221597', 'source-node-004451', '5', '4451', 'text', '栽培管理：选用无病地育苗，实行 4 年以上轮作，土壤消毒（每 667m² 用石灰氮 20kg），使用脱毒母株；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004453', 'source-doc-4c784a84a66adf221597', 'source-node-004451', '5', '4452', 'text', '阻断传播：分苗地选高地块防积水，雨后喷施百菌清等药剂，母株定植时用甲基托布津或恶霉灵混土沟施；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004454', 'source-doc-4c784a84a66adf221597', 'source-node-004451', '5', '4453', 'text', '养根壮株：喷淋甲基托布津混养根素或灌根；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004455', 'source-doc-4c784a84a66adf221597', 'source-node-004451', '5', '4454', 'text', '药剂防治：定植后及时拔除病株，用 50% 甲霜灵 1000-1500 倍液、70% 代森锰锌 500 倍液喷雾，或 64% 杀毒矾 500 倍液、72% 霜脲・锰锌 800 倍液等灌根消毒土壤。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004456', 'source-doc-4c784a84a66adf221597', 'source-node-004348', '3', '4455', 'text', '草莓终极腐霉烂果', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004457', 'source-doc-4c784a84a66adf221597', 'source-node-004456', '4', '4456', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004458', 'source-doc-4c784a84a66adf221597', 'source-node-004457', '5', '4457', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004459', 'source-doc-4c784a84a66adf221597', 'source-node-004456', '4', '4458', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004460', 'source-doc-4c784a84a66adf221597', 'source-node-004459', '5', '4459', 'text', '主要侵害根和果实：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004461', 'source-doc-4c784a84a66adf221597', 'source-node-004459', '5', '4460', 'text', '根部：染病初呈水渍状，很快变黑腐烂，轻则地上部植株萎蔫，重则全株枯死；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004462', 'source-doc-4c784a84a66adf221597', 'source-node-004459', '5', '4461', 'text', '果实：贴近地面或贴地果实易发病，病部呈水渍状，熟果略呈褐色至微紫色，软腐且略有弹性，果面长满浓密白色棉状菌丝；叶柄、果梗也会变黑干枯。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004463', 'source-doc-4c784a84a66adf221597', 'source-node-004456', '4', '4462', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004464', 'source-doc-4c784a84a66adf221597', 'source-node-004463', '5', '4463', 'text', 'Pythium ultimum Trow（终极腐霉），属假菌界卵菌门腐霉属。菌丝多分枝，孢子囊多间生（近球形），藏卵器球形（大多顶生），卵孢子球形（壁平滑），菌丝生长适温 28~36℃。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004465', 'source-doc-4c784a84a66adf221597', 'source-node-004456', '4', '4464', 'text', '发病规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004466', 'source-doc-4c784a84a66adf221597', 'source-node-004465', '5', '4465', 'text', '病菌在土壤、植株残体及未腐熟有机肥中存活越冬；条件适宜时，孢子囊释放游动孢子，借灌溉水或雨水传播，从根部侵入；高温高湿持续时间长、高温频繁浇水、重茬黏土地发病重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004467', 'source-doc-4c784a84a66adf221597', 'source-node-004456', '4', '4466', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004468', 'source-doc-4c784a84a66adf221597', 'source-node-004467', '5', '4467', 'text', '农业防治：选避风向阳高燥地块；苗床或定植前太阳能土壤消毒；高畦栽培防积水，忌漫灌；合理施肥不偏施氮肥；地膜栽培或垫果。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004469', 'source-doc-4c784a84a66adf221597', 'source-node-004467', '5', '4468', 'text', '药剂防治：秋季定植时用 30% 恶霉灵水剂 600 倍液浸根；生长期喷淋 68% 精甲霜・锰锌水分散粒剂 600 倍液、47% 春雷・王铜可湿性粉剂 700 倍液等；发病初期可用 25% 甲霜灵可湿性粉剂。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004470', 'source-doc-4c784a84a66adf221597', 'source-node-004348', '3', '4469', 'text', '草莓芽枯病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004471', 'source-doc-4c784a84a66adf221597', 'source-node-004470', '4', '4470', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004472', 'source-doc-4c784a84a66adf221597', 'source-node-004471', '5', '4471', 'text', '主要为害花蕾、幼芽、托叶、新叶，成熟叶片、果梗、果实也可感病：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004473', 'source-doc-4c784a84a66adf221597', 'source-node-004471', '5', '4472', 'text', '花序 / 幼芽：青枯并逐渐枯萎呈灰褐色；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004474', 'source-doc-4c784a84a66adf221597', 'source-node-004471', '5', '4473', 'text', '托叶 / 叶柄基部：黑褐色病变，叶正面颜色深于背面，脆且易碎；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004475', 'source-doc-4c784a84a66adf221597', 'source-node-004471', '5', '4474', 'text', '植株：最终猝倒状或变褐枯死，茎基部和根皮层腐烂，地上部易拔起；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004476', 'source-doc-4c784a84a66adf221597', 'source-node-004471', '5', '4475', 'text', '果实：病部暗褐色不规则斑块、僵硬，最终全果干腐（又称干腐病）；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004477', 'source-doc-4c784a84a66adf221597', 'source-node-004471', '5', '4476', 'text', '丝核菌芽枯病：蕾和新芽萎蔫青枯猝倒，变黑褐色枯死，表面产生白色至浅褐色蛛丝状霉（区别于灰霉病）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004478', 'source-doc-4c784a84a66adf221597', 'source-node-004470', '4', '4477', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004479', 'source-doc-4c784a84a66adf221597', 'source-node-004478', '5', '4478', 'text', 'Rhizoctonia solani（丝核菌），属真菌界担子菌门无性型丝核菌属；有性型为 Thanatephorus cucumeris（瓜亡革菌）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004480', 'source-doc-4c784a84a66adf221597', 'source-node-004470', '4', '4479', 'text', '发病规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004481', 'source-doc-4c784a84a66adf221597', 'source-node-004480', '5', '4480', 'text', '病菌以菌丝体或菌核随病残体在土壤越冬；栽植带病苗易侵染；气温低、连阴雨、寒流侵袭或湿度过高发病重；冬春棚室放风时病情扩展迅速，密闭时间长发病早且重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004482', 'source-doc-4c784a84a66adf221597', 'source-node-004470', '4', '4481', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004483', 'source-doc-4c784a84a66adf221597', 'source-node-004482', '5', '4482', 'text', '栽培管理：施用酵素菌腐熟堆肥或有机肥；不在病田育苗采苗；适度密植；棚室适时适量放风；合理灌溉（上午浇水后迅速放风降湿）；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004484', 'source-doc-4c784a84a66adf221597', 'source-node-004482', '5', '4483', 'text', '药剂防治：现蕾后喷淋 1% 申嗪霉素悬浮剂 600 倍液或 30% 苯醚甲・丙环乳油 3000 倍液，7 天 1 次共 2-3 次；与灰霉病混发时，喷洒 50% 腐霉利可湿性粉剂 1500 倍液等。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004485', 'source-doc-4c784a84a66adf221597', 'source-node-004470', '4', '4484', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004486', 'source-doc-4c784a84a66adf221597', 'source-node-004485', '5', '4485', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004487', 'source-doc-4c784a84a66adf221597', 'source-node-004348', '3', '4486', 'text', '草莓褐色轮纹病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004488', 'source-doc-4c784a84a66adf221597', 'source-node-004487', '4', '4487', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004489', 'source-doc-4c784a84a66adf221597', 'source-node-004488', '5', '4488', 'text', '主要为害草莓叶片、果梗、叶柄、匍匐茎及果实：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004490', 'source-doc-4c784a84a66adf221597', 'source-node-004488', '5', '4489', 'text', '叶片：初期出现红褐色小点，逐渐扩大为圆形或近椭圆形斑块，中央褐色，外围紫褐色，最外缘紫红色，病健交界明显；后期病斑上形成褐色小点（病菌分生孢子器），多呈不规则轮状排列，病斑融合可导致叶组织大片枯死、干燥破碎。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004491', 'source-doc-4c784a84a66adf221597', 'source-node-004488', '5', '4490', 'text', '叶柄、果梗、匍匐茎：产生黑褐色稍凹陷病斑，组织变脆易折断。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004492', 'source-doc-4c784a84a66adf221597', 'source-node-004488', '5', '4491', 'text', '果实：成熟期受害，病部褐色软腐、略凹陷。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004493', 'source-doc-4c784a84a66adf221597', 'source-node-004487', '4', '4492', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004494', 'source-doc-4c784a84a66adf221597', 'source-node-004493', '5', '4493', 'text', 'Phomopsis obscurans（昏暗拟茎点霉），属真菌界无性型子囊菌。分生孢子器球形至扁球形，壁薄膜质；分生孢子圆筒形，无色透明，含 1~2 个油点。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004495', 'source-doc-4c784a84a66adf221597', 'source-node-004487', '4', '4494', 'text', '发病规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004496', 'source-doc-4c784a84a66adf221597', 'source-node-004495', '5', '4495', 'text', '病菌以菌丝体或分生孢子器在病残体中越冬，翌年条件适宜时产生分生孢子，借雨水溅射传播进行初侵染和多次再侵染。南方多在 12 月～翌年 4 月发生，北方 6~7 月发病并延续至 9 月底；温暖多湿、时晴时雨的天气易加重病情。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004497', 'source-doc-4c784a84a66adf221597', 'source-node-004487', '4', '4496', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004498', 'source-doc-4c784a84a66adf221597', 'source-node-004497', '5', '4497', 'text', '农业防治：选用抗病品种（如戈雷拉、因都卡、明宝等）；地膜覆盖栽培减少初侵染；定植前清除病残体及病叶集中烧毁；适量浇水，雨后及时排水。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004499', 'source-doc-4c784a84a66adf221597', 'source-node-004497', '5', '4498', 'text', '药剂防治：发病初期喷淋 50% 琥胶肥酸铜可湿性粉剂 500 倍液、10% 苯醚甲环唑微乳剂 2000 倍液或 62.25% 代・腈菌可湿性粉剂 600 倍液，隔 7~10 天 1 次，共喷 3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004500', 'source-doc-4c784a84a66adf221597', 'source-node-004487', '4', '4499', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004501', 'source-doc-4c784a84a66adf221597', 'source-node-004500', '5', '4500', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004502', 'source-doc-4c784a84a66adf221597', 'source-node-004348', '3', '4501', 'text', '草莓“V”形褐斑病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004503', 'source-doc-4c784a84a66adf221597', 'source-node-004502', '4', '4502', 'text', '症状：嫩叶从叶顶沿主脉呈 “V”/“U” 形褐色斑，边缘深褐；老叶初为紫褐色小斑，扩展成不规则斑（周围有黄绿晕圈）；严重时病斑现轮纹、生黑褐色小粒点，全叶枯死。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004504', 'source-doc-4c784a84a66adf221597', 'source-node-004502', '4', '4503', 'text', '病原：Phomopsis obscurans（昏暗拟茎点霉），属真菌界无性型子囊菌。分生孢子器球形 / 扁球形，壁薄膜质；分生孢子圆筒形，无色透明含 1-2 个油点。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004505', 'source-doc-4c784a84a66adf221597', 'source-node-004502', '4', '4504', 'text', '发生规律：病残体越冬，4-5 月分生孢子借雨水传播，多次再侵染；湖南 4 下旬发病，5-6 月盛发，温暖多湿（时晴时雨）病情加重，品种抗病性有差异。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004506', 'source-doc-4c784a84a66adf221597', 'source-node-004502', '4', '4505', 'text', '防治方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004507', 'source-doc-4c784a84a66adf221597', 'source-node-004506', '5', '4506', 'text', '农业：选抗病品种（上海早、华东 5/10 号）；通风透光，不偏施氮肥，摘除病叶深埋。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004508', 'source-doc-4c784a84a66adf221597', 'source-node-004506', '5', '4507', 'text', '药剂：植前 50% 多菌灵 500 倍液浸苗 15-20 分钟晾干后栽植；发病初期喷 30% 苯醚甲・丙环乳油 3000 倍液等，隔 10 天 2-3 次。62.25% 代・腈菌可湿性粉剂 600 倍液、40% 多・硫悬浮剂 500 倍液或 50% 多・福悬浮剂 500 倍液，隔 10 天左右 1 次，连续防治 2~3 次；或喷施 50% 甲基托布津可湿性粉剂 600~800 倍液、75% 百菌清可湿性粉剂 500~700 倍液等，7~10 天喷 1 次，连喷 2~3 次，农药交替使用', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004509', 'source-doc-4c784a84a66adf221597', 'source-node-004502', '4', '4508', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004510', 'source-doc-4c784a84a66adf221597', 'source-node-004509', '5', '4509', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004511', 'source-doc-4c784a84a66adf221597', 'source-node-004348', '3', '4510', 'text', '草莓蛇眼病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004512', 'source-doc-4c784a84a66adf221597', 'source-node-004511', '4', '4511', 'text', '症状：又称白斑病 / 叶斑病，主要为害老叶。叶斑初期为暗紫红色小斑点，扩大成 2~5mm 圆形病斑，边缘紫红色、中心灰白色，具细轮纹（酷似蛇眼）；病斑表面生白色粉状霉层，后生小黑点；病斑多融合成大斑致叶片褐枯，浆果种子受害后周围果肉变黑。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004513', 'source-doc-4c784a84a66adf221597', 'source-node-004511', '4', '4512', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004514', 'source-doc-4c784a84a66adf221597', 'source-node-004513', '5', '4513', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004515', 'source-doc-4c784a84a66adf221597', 'source-node-004511', '4', '4514', 'text', '病原：有性态为草莓蛇眼球腔菌（Mycosphaerella fragariae），无性态为杜拉柱隔孢（Ramularia tulasnei），属真菌界子囊菌门 / 无性真菌类。分生孢子圆筒形，无色单胞或 1~2 隔膜；子囊孢子卵形无色有隔膜。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004516', 'source-doc-4c784a84a66adf221597', 'source-node-004511', '4', '4515', 'text', '发生规律：病菌以菌丝在枯叶病斑越冬，翌春分生孢子初侵染，再侵染。适温 18~22℃，低于 7℃或高于 23℃发育迟缓；秋季春季光照不足、阴湿，重茬田、管理粗放、排水不良地块发病重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004517', 'source-doc-4c784a84a66adf221597', 'source-node-004511', '4', '4516', 'text', '防治方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004518', 'source-doc-4c784a84a66adf221597', 'source-node-004517', '5', '4517', 'text', '农业：选抗病品种（戈雷拉、因都卡、明宝等）；清理病叶烧毁，摘除病残老叶；合理密植通风透光，避免重茬。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004519', 'source-doc-4c784a84a66adf221597', 'source-node-004517', '5', '4518', 'text', '化学：发病初期喷 2% 农抗 120 / 武夷菌素 200 倍（隔 6-7 天 1 次）、27% 高脂膜乳剂 80-100 倍（5-6 天 1 次连喷 3-4 次）；或用 25% 三唑酮 2000 倍、多氧霉素 1000 倍等；大棚用 45% 百菌清烟熏剂 200-250 克。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004520', 'source-doc-4c784a84a66adf221597', 'source-node-004348', '3', '4519', 'text', '草莓细菌性叶斑病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004521', 'source-doc-4c784a84a66adf221597', 'source-node-004520', '4', '4520', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004522', 'source-doc-4c784a84a66adf221597', 'source-node-004521', '5', '4521', 'text', '主要为害叶片，初现水浸状红褐色不规则斑，扩大融合后变浅红褐色干枯；湿度大时叶背有菌脓，干燥成薄膜，叶尖叶缘处病斑易致叶片干缩破碎，严重时生长点枯死，叶柄、匍匐茎、花也可受害。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004523', 'source-doc-4c784a84a66adf221597', 'source-node-004520', '4', '4522', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004524', 'source-doc-4c784a84a66adf221597', 'source-node-004523', '5', '4523', 'text', '草莓黄单胞菌（Xanthomonas fragariae），属细菌，菌体杆状，极生 1 鞭毛，革兰阴性，菌落圆形黄色有黏性。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004525', 'source-doc-4c784a84a66adf221597', 'source-node-004520', '4', '4524', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004526', 'source-doc-4c784a84a66adf221597', 'source-node-004525', '5', '4525', 'text', '病菌在种子、病残体或土壤越冬，借雨水、灌溉水、伤口传播，从水孔或伤口侵入；高温多雨、连作、低洼积水、伤口多等易发病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004527', 'source-doc-4c784a84a66adf221597', 'source-node-004520', '4', '4526', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004528', 'source-doc-4c784a84a66adf221597', 'source-node-004527', '5', '4527', 'text', '农业防治：检疫防传播，清除病残，减少伤口，合理水肥，雨后排水；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004529', 'source-doc-4c784a84a66adf221597', 'source-node-004527', '5', '4528', 'text', '药剂防治：定植前土壤消毒，发病初期用72% 农用链霉素可湿性粉剂3000～4000 倍液、春雷霉素等药剂喷雾，隔 7-10 天 1 次，连防 3-4 次。或30% 碱式硫酸铜悬浮剂500 倍液，或1% 新植霉素可湿性粉剂3000～5000倍液，或2% 春雷霉素水剂400～500 倍液，或2% 武夷霉素水剂150～200 倍液喷雾，隔7～10 天喷1 次，连续防治3～4 次。采收前7 天停止用', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004530', 'source-doc-4c784a84a66adf221597', 'source-node-004520', '4', '4529', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004531', 'source-doc-4c784a84a66adf221597', 'source-node-004530', '5', '4530', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004532', 'source-doc-4c784a84a66adf221597', 'source-node-004348', '3', '4531', 'text', '草莓病毒病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004533', 'source-doc-4c784a84a66adf221597', 'source-node-004532', '4', '4532', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004534', 'source-doc-4c784a84a66adf221597', 'source-node-004533', '5', '4533', 'text', '草莓病毒病由多种病毒单独或复合侵染引起，常见症状包括植株矮化、叶片花叶（浓淡不均斑驳）、黄边、皱缩畸形，果实变小、产量降低；复合侵染时症状更严重，如叶片扭曲变形、植株严重矮化甚至死亡；部分病毒（如绿瓣病毒）可导致花瓣变绿、花序畸形。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004535', 'source-doc-4c784a84a66adf221597', 'source-node-004532', '4', '4534', 'text', '病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004536', 'source-doc-4c784a84a66adf221597', 'source-node-004535', '5', '4535', 'text', '主要病原包括草莓斑驳病毒（SMoV）、轻型黄边病毒（SMYEV）、皱缩病毒（SCV）、镶脉病毒（SVBV）等，分属不同病毒科（如 SMoV 属伴生豇豆病毒科、SMYEV 属甲型线形病毒科），病毒粒子形态有球形、线形等。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004537', 'source-doc-4c784a84a66adf221597', 'source-node-004532', '4', '4536', 'text', '发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004538', 'source-doc-4c784a84a66adf221597', 'source-node-004537', '5', '4537', 'text', '传播途径：主要通过带病毒的无性繁殖材料（母株）远距离传播；田间通过介体蚜虫（草莓钉毛蚜等）取食迁飞传毒。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004539', 'source-doc-4c784a84a66adf221597', 'source-node-004537', '5', '4538', 'text', '发病条件：同一地块连年种植、偏施氮肥抗病性弱时发病重；病毒具潜伏侵染特性，复合侵染加重危害。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004540', 'source-doc-4c784a84a66adf221597', 'source-node-004532', '4', '4539', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004541', 'source-doc-4c784a84a66adf221597', 'source-node-004532', '4', '4540', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004542', 'source-doc-4c784a84a66adf221597', 'source-node-004541', '5', '4541', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004543', 'source-doc-4c784a84a66adf221597', 'source-node-004348', '3', '4542', 'text', '草莓线虫病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004544', 'source-doc-4c784a84a66adf221597', 'source-node-004543', '4', '4543', 'text', '草莓线虫病概括', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004545', 'source-doc-4c784a84a66adf221597', 'source-node-004543', '4', '4544', 'text', '1. 症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004546', 'source-doc-4c784a84a66adf221597', 'source-node-004545', '5', '4545', 'text', '芽线虫：为害芽和匍匐茎，轻者新叶发育不良、皱缩畸形、深绿有光泽；重者整株萎蔫，芽 / 叶柄变黄红，花蕾花萼畸形，花芽无法发育致不结果（减产 30%-60%）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004547', 'source-doc-4c784a84a66adf221597', 'source-node-004545', '5', '4546', 'text', '根结线虫：根部形成大小不等根结，剖开可见乳白色线虫，地上部发育不良或死亡', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004548', 'source-doc-4c784a84a66adf221597', 'source-node-004545', '5', '4547', 'text', '茎线虫：叶柄隆起、叶片扭曲，花和果实形成虫瘿，植株矮化', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004549', 'source-doc-4c784a84a66adf221597', 'source-node-004543', '4', '4548', 'text', '2. 病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004550', 'source-doc-4c784a84a66adf221597', 'source-node-004549', '5', '4549', 'text', '主要为草莓芽线虫（Aphelenchoides fragariae）、根结线虫（Meloidogyne incognita等）、茎线虫（Ditylenchus dipsaci），还包括水稻干尖线虫、咖啡短体线虫等', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004551', 'source-doc-4c784a84a66adf221597', 'source-node-004543', '4', '4550', 'text', '3. 发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004552', 'source-doc-4c784a84a66adf221597', 'source-node-004551', '5', '4551', 'text', '芽线虫：种苗携带初侵染，连作地土壤残留；靠雨水 / 灌溉水传播，28-32℃夏秋季严重', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004553', 'source-doc-4c784a84a66adf221597', 'source-node-004551', '5', '4552', 'text', '根结线虫：卵 / 2 龄幼虫越冬，病土 / 病苗 / 灌溉水传播；25-30℃最适，55℃10 分钟致死', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004554', 'source-doc-4c784a84a66adf221597', 'source-node-004551', '5', '4553', 'text', '茎线虫：随寄主种子 / 鳞茎传播，水旱轮作可减轻为害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004555', 'source-doc-4c784a84a66adf221597', 'source-node-004543', '4', '4554', 'text', '4. 防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004556', 'source-doc-4c784a84a66adf221597', 'source-node-004555', '5', '4555', 'text', '培育无虫苗：不从被害园繁苗，发现病苗立即拔除烧毁，必要时检疫', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004557', 'source-doc-4c784a84a66adf221597', 'source-node-004555', '5', '4556', 'text', '轮作：与禾本科等非寄主作物轮作，水旱轮作效果更佳', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004558', 'source-doc-4c784a84a66adf221597', 'source-node-004555', '5', '4557', 'text', '高温处理种苗：35℃温水预热 10 分钟，再用 45-46℃热水浸 10 分钟，冷却后栽植', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004559', 'source-doc-4c784a84a66adf221597', 'source-node-004555', '5', '4558', 'text', '药剂防治：定植前用 1.8% 阿维菌素乳油 1500 倍液或 20% 辣根素土壤处理；土壤消毒可用克线丹、石灰氮', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004560', 'source-doc-4c784a84a66adf221597', 'source-node-004555', '5', '4559', 'text', '加强田间管理：重点加强夏季苗圃管理，防止线虫密度升高', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004561', 'source-doc-4c784a84a66adf221597', 'source-node-004543', '4', '4560', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004562', 'source-doc-4c784a84a66adf221597', 'source-node-004561', '5', '4561', 'text', '', '[]');
