INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004564', 'source-doc-4c784a84a66adf221597', 'source-node-004563', '3', '4563', 'text', '草莓日灼', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004565', 'source-doc-4c784a84a66adf221597', 'source-node-004564', '4', '4564', 'text', '', '[]');
