INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004567', 'source-doc-4c784a84a66adf221597', 'source-node-004566', '4', '4566', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004568', 'source-doc-4c784a84a66adf221597', 'source-node-004563', '3', '4567', 'text', '草莓生理性白果', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004569', 'source-doc-4c784a84a66adf221597', 'source-node-004568', '4', '4568', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004570', 'source-doc-4c784a84a66adf221597', 'source-node-004563', '3', '4569', 'text', '草莓肥害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004571', 'source-doc-4c784a84a66adf221597', 'source-node-004570', '4', '4570', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004572', 'source-doc-4c784a84a66adf221597', 'source-node-004563', '3', '4571', 'text', '草莓激素药害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004573', 'source-doc-4c784a84a66adf221597', 'source-node-004572', '4', '4572', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004574', 'source-doc-4c784a84a66adf221597', 'source-node-004563', '3', '4573', 'text', '草莓低温症', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004575', 'source-doc-4c784a84a66adf221597', 'source-node-004574', '4', '4574', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004576', 'source-doc-4c784a84a66adf221597', 'source-node-004575', '5', '4575', 'text', '叶片部分冻死而干', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004577', 'source-doc-4c784a84a66adf221597', 'source-node-004575', '5', '4576', 'text', '花蕊受冻后变为黑褐色且死亡', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004578', 'source-doc-4c784a84a66adf221597', 'source-node-004575', '5', '4577', 'text', '冻害发生时，有的叶片部分冻死而干枯；有的花蕊和柱头受冻后柱头向上隆起干缩，花蕊变成黑褐色且死亡，花瓣变成红色或紫红色；幼果受冻时停止发育，变成暗红色，干枯且僵死，大果受冻后变褐', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004579', 'source-doc-4c784a84a66adf221597', 'source-node-004574', '4', '4578', 'text', '防治方法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004580', 'source-doc-4c784a84a66adf221597', 'source-node-004579', '5', '4579', 'text', '选用适宜的品种，适时定植；晚秋控制植株徒长，冬前浇冻水，', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004581', 'source-doc-4c784a84a66adf221597', 'source-node-004579', '5', '4580', 'text', '越冬及时覆盖防寒物；早春不要过早去除覆盖物，在初花期于寒流来临之前要及时加盖地膜防寒；冷空气来临前为园地灌水，增加土壤湿度，提高抗寒能力；及时对叶片喷施1.8% 复硝酚钠水剂3000～5000 倍液；保护地栽培应进行人工加温。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004582', 'source-doc-4c784a84a66adf221597', 'source-node-004574', '4', '4581', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004583', 'source-doc-4c784a84a66adf221597', 'source-node-004582', '5', '4582', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004584', 'source-doc-4c784a84a66adf221597', 'source-node-004563', '3', '4583', 'text', '草莓畸形果', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004585', 'source-doc-4c784a84a66adf221597', 'source-node-004584', '4', '4584', 'text', '防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004586', 'source-doc-4c784a84a66adf221597', 'source-node-004585', '5', '4585', 'text', '选用畸形果少的品种；配置授粉品种10%～20%；合理调控棚室内的温度和湿度，通过适时放风，白天应控制在22～28℃，夜间保持在5℃以上以30%～50% 的湿度为宜；疏花疏果，疏除易出现雌性不育的高级次花，摘除病果和过多的幼果；减少用药次数，尽量不用或少用农药，若需使用药剂防治，一定要避开花期；合理施肥；重视有机肥作为基肥，控制氮肥用量，补施磷、钾肥和微量元素肥料；合理密植，加强植株管理，注意通风透光。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004587', 'source-doc-4c784a84a66adf221597', 'source-node-004584', '4', '4586', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004588', 'source-doc-4c784a84a66adf221597', 'source-node-004587', '5', '4587', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004589', 'source-doc-4c784a84a66adf221597', 'source-node-004563', '3', '4588', 'text', '草莓缺磷', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004590', 'source-doc-4c784a84a66adf221597', 'source-node-004589', '4', '4589', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004591', 'source-doc-4c784a84a66adf221597', 'source-node-004563', '3', '4590', 'text', '草莓缺氮', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004592', 'source-doc-4c784a84a66adf221597', 'source-node-004591', '4', '4591', 'text', '', '[]');
