INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004600', 'source-doc-4c784a84a66adf221597', 'source-node-004599', '4', '4599', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004601', 'source-doc-4c784a84a66adf221597', 'source-node-004563', '3', '4600', 'text', '草莓缺锰', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004602', 'source-doc-4c784a84a66adf221597', 'source-node-004601', '4', '4601', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004603', 'source-doc-4c784a84a66adf221597', 'source-node-004563', '3', '4602', 'text', '草莓缺硫', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004604', 'source-doc-4c784a84a66adf221597', 'source-node-004603', '4', '4603', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004605', 'source-doc-4c784a84a66adf221597', 'source-node-004330', '2', '4604', 'text', '虫害：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004606', 'source-doc-4c784a84a66adf221597', 'source-node-004605', '3', '4605', 'text', '草莓蚜虫（Aphididae）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004607', 'source-doc-4c784a84a66adf221597', 'source-node-004606', '4', '4606', 'text', '发病规律：在草莓田附近的杂草、蔬菜等寄主植物上以卵越冬，翌年春季气温回升至 10℃以上时开始孵化，产生有翅蚜或无翅蚜，借助风力、农事操作等扩散到草莓植株上，聚集在嫩叶、嫩茎、花及果实上吸食汁液，15 - 25℃、相对湿度 70% - 80% 时繁殖迅速，蚜虫分泌蜜露还会引发煤污病，影响草莓光合作用与果实品质，同时传播多种病毒病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004608', 'source-doc-4c784a84a66adf221597', 'source-node-004606', '4', '4607', 'text', '预防方法：草莓园选址尽量远离蚜虫高发的十字花科蔬菜等种植区；种植前清除周边杂草，破坏蚜虫越冬栖息场所；园内悬挂黄色粘虫板，利用蚜虫趋黄性诱杀；合理间作驱虫植物，如薄荷、大蒜等，趋避蚜虫。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004609', 'source-doc-4c784a84a66adf221597', 'source-node-004606', '4', '4608', 'text', '防治方法：选用 10% 吡虫啉可湿性粉剂 1500 - 2000 倍液、50% 抗蚜威可湿性粉剂 2000 - 3000 倍液、25% 噻虫嗪水分散粒剂 3000 - 5000 倍液等喷雾，重点喷施蚜虫聚集部位，7 - 10 天 1 次，视虫情连续喷 2 - 3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004610', 'source-doc-4c784a84a66adf221597', 'source-node-004605', '3', '4609', 'text', '草莓红蜘蛛（Tetranychus urticae）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004611', 'source-doc-4c784a84a66adf221597', 'source-node-004610', '4', '4610', 'text', '发病规律：以雌成螨在草莓田杂草、枯枝落叶、土缝及草莓老叶背面等隐蔽处越冬，春季气温达 10℃以上时开始活动、繁殖，在 25 - 30℃、相对湿度 40% - 60% 干燥、高温环境下繁殖力极强，世代重叠严重，靠爬行、吐丝随风飘散扩散，多聚集在草莓叶片背面，用刺吸式口器吸食叶肉汁液，致使叶片出现黄白色斑点，严重时叶片干枯脱落，影响植株光合作用与生长。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004612', 'source-doc-4c784a84a66adf221597', 'source-node-004610', '4', '4611', 'text', '预防方法：及时清理草莓田间杂草、残株，减少红蜘蛛越冬场所与滋生地；合理灌溉，避免田间过于干旱，保持适宜湿度，抑制红蜘蛛繁殖；定期巡查，发现少量红蜘蛛时，及时摘除受害叶片，防止扩散。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004613', 'source-doc-4c784a84a66adf221597', 'source-node-004610', '4', '4612', 'text', '防治方法：发病初期，可选用 1.8% 阿维菌素乳油 1000 - 1500 倍液、20% 哒螨灵可湿性粉剂 1000 - 1500 倍液、73% 克螨特乳油 1000 - 1500 倍液等喷雾，重点喷叶片背面，确保药剂覆盖均匀，5 - 7 天 1 次，连续喷 2 - 3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004614', 'source-doc-4c784a84a66adf221597', 'source-node-004605', '3', '4613', 'text', '草莓蓟马（Thrips spp.）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004615', 'source-doc-4c784a84a66adf221597', 'source-node-004614', '4', '4614', 'text', '发病规律：成虫在草莓园周边杂草、土缝中越冬，翌年春天气温升高后活跃，具趋蓝性、趋嫩性，喜欢在温暖（20 - 28℃）、干燥环境下繁殖，常聚集在草莓花朵、嫩叶、幼果上，用锉吸式口器锉破表皮吸食汁液，造成花器受损、花朵畸形、叶片出现银灰色斑点、幼果表面粗糙、生长受阻，还传播病毒病，花期危害最为严重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004616', 'source-doc-4c784a84a66adf221597', 'source-node-004614', '4', '4615', 'text', '预防方法：草莓园周边除草，破坏蓟马越冬栖息场所；园内悬挂蓝色粘虫板诱杀成虫；种植前对土壤进行深耕翻晒，减少虫源；释放捕食螨、小花蝽等天敌昆虫，控制蓟马种群数量。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004617', 'source-doc-4c784a84a66adf221597', 'source-node-004614', '4', '4616', 'text', '防治方法：选用 2.5% 多杀霉素悬浮剂 1000 - 1500 倍液、10% 吡虫啉可湿性粉剂 1500 - 2000 倍液、5% 高效氯氟氰菊酯乳油 1500 - 2000 倍液等喷雾，花期重点喷花，兼顾叶片，7 - 10 天 1 次，连续喷 2 - 3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004618', 'source-doc-4c784a84a66adf221597', 'source-node-004605', '3', '4617', 'text', '草莓潜叶蝇（Liriomyza spp.）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004619', 'source-doc-4c784a84a66adf221597', 'source-node-004618', '4', '4618', 'text', '发病规律：以蛹在土壤中越冬，春季气温适宜时，成虫羽化后在草莓叶片边缘产卵，卵孵化后幼虫即在叶片内潜食叶肉，形成不规则弯曲虫道，影响叶片光合作用，20 - 30℃时繁殖快、为害重，高温干旱环境利于其种群增长，田间杂草丛生、通风透光不良地块发病较多。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004620', 'source-doc-4c784a84a66adf221597', 'source-node-004618', '4', '4619', 'text', '预防方法：及时清理草莓田杂草、残株，减少潜叶蝇滋生地；合理密植，加强田间通风透光；悬挂蓝色粘虫板诱杀成虫。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004621', 'source-doc-4c784a84a66adf221597', 'source-node-004618', '4', '4620', 'text', '防治方法：幼虫初发期，用 1.8% 阿维菌素乳油 1000 - 1500 倍液、40% 灭蝇胺可湿性粉剂 1500 - 2000 倍液、20% 阿维・杀单微乳剂 1000 - 1500 倍液等喷雾，重点喷施叶片，7 - 10 天 1 次，连续喷 2 - 3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004622', 'source-doc-4c784a84a66adf221597', 'source-node-002718', '1', '4621', 'text', '2.2.7 韭菜/大蒜', '[]');
