INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004624', 'source-doc-4c784a84a66adf221597', 'source-node-004623', '3', '4623', 'text', '方案一：氟吡菌胺·精甲霜灵', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004625', 'source-doc-4c784a84a66adf221597', 'source-node-004623', '3', '4624', 'text', '方案二：精甲霜灵·烯酰吗啉', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004626', 'source-doc-4c784a84a66adf221597', 'source-node-004623', '3', '4625', 'text', '方案三：吡唑醚菌酯·氰霜唑', '[]');
