INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004631', 'source-doc-4c784a84a66adf221597', 'source-node-004627', '3', '4630', 'text', '腐霉利、异菌脲、啶酰菌胺、啶菌恶唑交替使用', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004632', 'source-doc-4c784a84a66adf221597', 'source-node-004627', '3', '4631', 'text', '嘧霉胺·乙霉威、啶酰菌胺·异菌脲、异菌脲·腐霉利、', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004633', 'source-doc-4c784a84a66adf221597', 'source-node-004622', '2', '4632', 'text', '细菌软腐', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004634', 'source-doc-4c784a84a66adf221597', 'source-node-004633', '3', '4633', 'text', '有臭味，用噻菌铜、喹啉铜、春雷酶素', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004635', 'source-doc-4c784a84a66adf221597', 'source-node-004622', '2', '4634', 'text', '白腐病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004636', 'source-doc-4c784a84a66adf221597', 'source-node-004635', '3', '4635', 'text', '用异菌脲、嘧霉胺', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004637', 'source-doc-4c784a84a66adf221597', 'source-node-002718', '1', '4636', 'text', '2.2.8 姜', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004638', 'source-doc-4c784a84a66adf221597', 'source-node-004637', '2', '4637', 'text', '姜瘟病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004639', 'source-doc-4c784a84a66adf221597', 'source-node-004638', '3', '4638', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004640', 'source-doc-4c784a84a66adf221597', 'source-node-004639', '4', '4639', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004641', 'source-doc-4c784a84a66adf221597', 'source-node-004638', '3', '4640', 'text', '发病症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004642', 'source-doc-4c784a84a66adf221597', 'source-node-004641', '4', '4641', 'text', '大姜一般从茎基部发病，初期病斑暗紫色，后成黄褐色水渍状，病姜内部腐烂，挤压流白色汁液、有臭味，剖开病姜维管束为褐色', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004643', 'source-doc-4c784a84a66adf221597', 'source-node-004638', '3', '4642', 'text', '可以使用喹啉铜、噻菌铜、春雷王铜、硫酸铜、锌硫酸铜、氢氧化铜、噻唑锌等滴灌冲施，对于严重的地块进行氯溴异氰尿酸清园消毒，覆盖薄膜利于阳光高温炙烤', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004644', 'source-doc-4c784a84a66adf221597', 'source-node-004638', '3', '4643', 'text', '药剂可选水合霉素、农用链霉素、中生菌素、噻唑锌 + 松脂酸铜、琥胶肥酸铜等，每隔 7 - 10 天用药', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004645', 'source-doc-4c784a84a66adf221597', 'source-node-004637', '2', '4644', 'text', '白绢病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004646', 'source-doc-4c784a84a66adf221597', 'source-node-004645', '3', '4645', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004647', 'source-doc-4c784a84a66adf221597', 'source-node-004645', '3', '4646', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004648', 'source-doc-4c784a84a66adf221597', 'source-node-004637', '2', '4647', 'text', '腐霉根腐', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004649', 'source-doc-4c784a84a66adf221597', 'source-node-004648', '3', '4648', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004650', 'source-doc-4c784a84a66adf221597', 'source-node-004649', '4', '4649', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004651', 'source-doc-4c784a84a66adf221597', 'source-node-004648', '3', '4650', 'text', '近地面茎叶处出现黄褐色病斑，后软化腐烂，导致地上叶片黄化凋萎，大姜靠近地皮处茎秆出现腐烂，几天后枯死', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004652', 'source-doc-4c784a84a66adf221597', 'source-node-004648', '3', '4651', 'text', '药剂选择：霜霉威盐酸盐、丙森锌、三乙膦酸铝、二氯异氰尿酸、氢氧化铜等，每隔 7~10 天灌根一次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004653', 'source-doc-4c784a84a66adf221597', 'source-node-004637', '2', '4652', 'text', '姜叶斑病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004654', 'source-doc-4c784a84a66adf221597', 'source-node-004653', '3', '4653', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004655', 'source-doc-4c784a84a66adf221597', 'source-node-004654', '4', '4654', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004656', 'source-doc-4c784a84a66adf221597', 'source-node-004653', '3', '4655', 'text', '发病规律：病斑不规则，中间灰白、边缘褐色，严重时病斑融合致叶片干枯死亡 。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004657', 'source-doc-4c784a84a66adf221597', 'source-node-004653', '3', '4656', 'text', '防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004658', 'source-doc-4c784a84a66adf221597', 'source-node-004657', '4', '4657', 'text', '药剂可选克菌丹、福美锌、异菌脲、多菌灵、代森锰锌、苯醚甲环唑等，每隔 7 - 10 天用药一次 。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004659', 'source-doc-4c784a84a66adf221597', 'source-node-004657', '4', '4658', 'text', '属于农业生产中植物病害识别与防治的知识，实体是植物病害的症状描述和对应的防治药剂、方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004660', 'source-doc-4c784a84a66adf221597', 'source-node-004637', '2', '4659', 'text', '姜炭疽病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004661', 'source-doc-4c784a84a66adf221597', 'source-node-004660', '3', '4660', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004662', 'source-doc-4c784a84a66adf221597', 'source-node-004661', '4', '4661', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004663', 'source-doc-4c784a84a66adf221597', 'source-node-004660', '3', '4662', 'text', '发病规律：发病初期叶尖或叶缘现褐色水渍状小斑，后扩展成圆形至梭形、带轮纹病斑，严重时多个病斑连成大病斑致叶片干枯', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004664', 'source-doc-4c784a84a66adf221597', 'source-node-004660', '3', '4663', 'text', '防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004665', 'source-doc-4c784a84a66adf221597', 'source-node-004664', '4', '4664', 'text', '药剂可选唑菌胺酯、硅唑・咪鲜胺、多・福・溴菌清，5-7天一次', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004666', 'source-doc-4c784a84a66adf221597', 'source-node-004637', '2', '4665', 'text', '叶枯病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004667', 'source-doc-4c784a84a66adf221597', 'source-node-004666', '3', '4666', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004668', 'source-doc-4c784a84a66adf221597', 'source-node-004667', '4', '4667', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004669', 'source-doc-4c784a84a66adf221597', 'source-node-004666', '3', '4668', 'text', '规律：叶片上有黄褐色小斑点病斑，易穿孔，严重时叶片枯死', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004670', 'source-doc-4c784a84a66adf221597', 'source-node-004666', '3', '4669', 'text', '防治药剂可选异菌脲、多菌灵、苯醚甲环唑、代森锰锌等，每隔 7 - 10 天用药一次', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004671', 'source-doc-4c784a84a66adf221597', 'source-node-004637', '2', '4670', 'text', '细菌性叶枯病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004672', 'source-doc-4c784a84a66adf221597', 'source-node-004671', '3', '4671', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004673', 'source-doc-4c784a84a66adf221597', 'source-node-004672', '4', '4672', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004674', 'source-doc-4c784a84a66adf221597', 'source-node-004671', '3', '4673', 'text', '规律：叶片病斑初期是褐色略透明水渍状斑点，后变深褐色，边缘清晰，沿叶缘、叶脉扩展；根部被侵染后，初期出现黄褐色水渍状斑块，后从外向内软化腐烂。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004675', 'source-doc-4c784a84a66adf221597', 'source-node-004671', '3', '4674', 'text', '防治：药剂可选噻菌铜、喹菌酮、氯溴异氰尿酸、噻唑锌、中生菌素等，每隔 5 - 7 天用药一次 。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004676', 'source-doc-4c784a84a66adf221597', 'source-node-002718', '1', '4675', 'text', '2.2.9 四季豆/荷兰豆/豇豆/青豆', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004677', 'source-doc-4c784a84a66adf221597', 'source-node-004676', '2', '4676', 'text', '真菌性病害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004678', 'source-doc-4c784a84a66adf221597', 'source-node-004677', '3', '4677', 'text', '叶斑病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004679', 'source-doc-4c784a84a66adf221597', 'source-node-004678', '4', '4678', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004680', 'source-doc-4c784a84a66adf221597', 'source-node-004679', '5', '4679', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004681', 'source-doc-4c784a84a66adf221597', 'source-node-004678', '4', '4680', 'text', '防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004682', 'source-doc-4c784a84a66adf221597', 'source-node-004681', '5', '4681', 'text', '苯醚甲环唑、腈菌唑、溴菌腈、咪鲜胺、噻唑锌。不要用丙环唑、戊唑醇、苯醚甲环唑', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004683', 'source-doc-4c784a84a66adf221597', 'source-node-004677', '3', '4682', 'text', '锈病', '[]');
