INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004687', 'source-doc-4c784a84a66adf221597', 'source-node-004677', '3', '4686', 'text', '疫病', '[]');
