INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004706', 'source-doc-4c784a84a66adf221597', 'source-node-004676', '2', '4705', 'text', '细菌性病害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004707', 'source-doc-4c784a84a66adf221597', 'source-node-004676', '2', '4706', 'text', '病毒性病害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004708', 'source-doc-4c784a84a66adf221597', 'source-node-002718', '1', '4707', 'text', '2.2.10 黄瓜', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004709', 'source-doc-4c784a84a66adf221597', 'source-node-004708', '2', '4708', 'text', '细菌性角斑病：中生菌素、春雷霉素，严重的使用喹啉铜或春雷喹啉铜或氢氧化铜', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004710', 'source-doc-4c784a84a66adf221597', 'source-node-004709', '3', '4709', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004711', 'source-doc-4c784a84a66adf221597', 'source-node-004708', '2', '4710', 'text', '真菌靶斑病：包括广谱杀菌剂代森锰锌、多菌灵、甲基硫菌灵、百菌清；三唑类药剂丙环唑、苯醚甲环唑、氟硅唑、戊唑醇，咪唑类杀菌剂咪鲜胺、氟菌唑，甲氧基丙烯酸酯类药剂醚菌酯、吡唑醚菌酯；二甲酰亚胺类药剂异菌脲以及喹啉铜、阿米西达等。同时要尽可能减少用药次数，轮换使用不同类型的药剂和使用复配药剂。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004712', 'source-doc-4c784a84a66adf221597', 'source-node-004711', '3', '4711', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004713', 'source-doc-4c784a84a66adf221597', 'source-node-002718', '1', '4712', 'text', '2.2.11 丝瓜/苦瓜/瓠瓜/西葫芦/南瓜', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004714', 'source-doc-4c784a84a66adf221597', 'source-node-004713', '2', '4713', 'text', '白粉病：霜霉威+苯甲嘧菌酯、噻森铜', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004715', 'source-doc-4c784a84a66adf221597', 'source-node-004714', '3', '4714', 'text', '', '[]');
