INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004751', 'source-doc-4c784a84a66adf221597', 'source-node-004750', '2', '4750', 'text', '一、症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004752', 'source-doc-4c784a84a66adf221597', 'source-node-004751', '3', '4751', 'text', '叶片：初为暗绿色水渍小点，后扩大为灰褐色、圆形病斑（直径 2-4mm），边缘褐色隆起，中央凹陷，外观极似铁锈。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004753', 'source-doc-4c784a84a66adf221597', 'source-node-004751', '3', '4752', 'text', '茎部：出现褐色、长椭圆形、略凹陷的病斑，严重时植株倒伏。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004754', 'source-doc-4c784a84a66adf221597', 'source-node-004751', '3', '4753', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004755', 'source-doc-4c784a84a66adf221597', 'source-node-004750', '2', '4754', 'text', '二、发病原因', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004756', 'source-doc-4c784a84a66adf221597', 'source-node-004755', '3', '4755', 'text', '病原：溃突刺盘孢菌（真菌）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004757', 'source-doc-4c784a84a66adf221597', 'source-node-004755', '3', '4756', 'text', '传播：病菌在病残体、种子上越冬，借雨水飞溅传播。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004758', 'source-doc-4c784a84a66adf221597', 'source-node-004755', '3', '4757', 'text', '条件：高温高湿（28-32℃、多雨）、种植过密、偏施氮肥、通风差是主因。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004759', 'source-doc-4c784a84a66adf221597', 'source-node-004750', '2', '4758', 'text', '三、综合防治方案', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004760', 'source-doc-4c784a84a66adf221597', 'source-node-004759', '3', '4759', 'text', '1. 农业防治（预防为主）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004761', 'source-doc-4c784a84a66adf221597', 'source-node-004760', '4', '4760', 'text', '清理病残：及时摘除并烧毁病叶，收获后彻底清园。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004762', 'source-doc-4c784a84a66adf221597', 'source-node-004760', '4', '4761', 'text', '合理密植：保证通风透光，避免郁闭高湿。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004763', 'source-doc-4c784a84a66adf221597', 'source-node-004760', '4', '4762', 'text', '控湿排水：高畦栽培，雨后立即排水，降低田间湿度。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004764', 'source-doc-4c784a84a66adf221597', 'source-node-004760', '4', '4763', 'text', '科学施肥：增施磷钾肥，避免偏施氮肥，增强抗性。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004765', 'source-doc-4c784a84a66adf221597', 'source-node-004760', '4', '4764', 'text', '种子处理：播种前用55℃温水浸种 15 分钟消毒。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004766', 'source-doc-4c784a84a66adf221597', 'source-node-004759', '3', '4765', 'text', '2. 药剂防治（发病初期）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004767', 'source-doc-4c784a84a66adf221597', 'source-node-004766', '4', '4766', 'text', '推荐配方（任选其一）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004768', 'source-doc-4c784a84a66adf221597', 'source-node-004766', '4', '4767', 'text', '70% 多菌灵 500 倍液', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004769', 'source-doc-4c784a84a66adf221597', 'source-node-004766', '4', '4768', 'text', '36% 甲基硫菌灵 500 倍液', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004770', 'source-doc-4c784a84a66adf221597', 'source-node-004766', '4', '4769', 'text', '80% 炭疽福美 800 倍液', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004771', 'source-doc-4c784a84a66adf221597', 'source-node-004766', '4', '4770', 'text', '10% 苯醚甲环唑 1500 倍液', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004772', 'source-doc-4c784a84a66adf221597', 'source-node-004766', '4', '4771', 'text', '用法：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004773', 'source-doc-4c784a84a66adf221597', 'source-node-004766', '4', '4772', 'text', '发病初期开始喷施，隔 7-10 天 1 次，连喷 2-3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004774', 'source-doc-4c784a84a66adf221597', 'source-node-004766', '4', '4773', 'text', '采收前 7 天停止用药，确保安全。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004775', 'source-doc-4c784a84a66adf221597', 'source-node-004750', '2', '4774', 'text', '四、管理要点', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004776', 'source-doc-4c784a84a66adf221597', 'source-node-004775', '3', '4775', 'text', '控湿 + 通风 + 控氮 + 早喷药，四管齐下', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004777', 'source-doc-4c784a84a66adf221597', NULL, '0', '4776', 'text', '2.3 主粮作物', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004778', 'source-doc-4c784a84a66adf221597', 'source-node-004777', '1', '4777', 'text', '2.3.1 花生', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004779', 'source-doc-4c784a84a66adf221597', 'source-node-004777', '1', '4778', 'text', '2.2.6 玉米（已编辑，未贴图）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004780', 'source-doc-4c784a84a66adf221597', 'source-node-004779', '2', '4779', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004781', 'source-doc-4c784a84a66adf221597', 'source-node-004779', '2', '4780', 'text', '细菌性病害：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004782', 'source-doc-4c784a84a66adf221597', 'source-node-004781', '3', '4781', 'text', '暂无典型严重细菌性病害详述（玉米偶见细菌性茎腐病等）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004783', 'source-doc-4c784a84a66adf221597', 'source-node-004782', '4', '4782', 'text', '发病规律（以细菌性茎腐病参考）：病原菌在病残体、土壤及种子表面越冬，借助雨水、灌溉水、昆虫及农事操作等传播，从玉米植株的伤口（如机械损伤、虫咬伤口、气生根断裂处）、气孔等部位侵入，在高温高湿（28 - 32℃、相对湿度 85% 以上）、种植密度大、田间通风透光差、氮肥施用过多导致植株徒长、抗性降低的情况下，易发病，尤其在玉米生长中后期（大喇叭口期 - 成熟期）危害突出。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004784', 'source-doc-4c784a84a66adf221597', 'source-node-004782', '4', '4783', 'text', '预防方法：选用抗病品种，进行种子处理（如用咯菌腈、精甲霜灵等拌种）；合理密植，改善田间通风透光条件；科学施肥，控制氮肥用量，增施磷钾肥、有机肥，增强植株抗性；及时清除病残体，深耕翻土，减少病原菌越冬基数。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004785', 'source-doc-4c784a84a66adf221597', 'source-node-004782', '4', '4784', 'text', '防治方法：发病初期，用 3% 中生菌素可湿性粉剂 800 - 1000 倍液、72% 农用链霉素可溶性粉剂 4000 倍液等喷雾或灌根，重点针对发病植株基部及周边，7 - 10 天 1 次，连施 2 - 3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004786', 'source-doc-4c784a84a66adf221597', 'source-node-004779', '2', '4785', 'text', '真菌性病害：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004787', 'source-doc-4c784a84a66adf221597', 'source-node-004786', '3', '4786', 'text', '玉米锈病（Puccinia sorghi）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004788', 'source-doc-4c784a84a66adf221597', 'source-node-004787', '4', '4787', 'text', '一、症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004789', 'source-doc-4c784a84a66adf221597', 'source-node-004788', '5', '4788', 'text', '含普通锈病和南方锈病两类：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004790', 'source-doc-4c784a84a66adf221597', 'source-node-004788', '5', '4789', 'text', '普通锈病：主要为害叶片、叶鞘，初现褪绿斑，后成深褐色椭圆形夏孢子堆（叶片正面较多），表皮破裂散黄褐色夏孢子，后期生黑色冬孢子堆', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004791', 'source-doc-4c784a84a66adf221597', 'source-node-004788', '5', '4790', 'text', '南方锈病：集中侵染叶片，初为褪绿小斑，后成橙黄色至黄褐色圆形小夏孢子堆（密集叶片正面，表皮开裂不明显），抗病品种夏孢子堆周围组织坏死 / 褪绿，后期近堆处生黑色冬孢子堆', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004792', 'source-doc-4c784a84a66adf221597', 'source-node-004787', '4', '4791', 'text', '二、病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004793', 'source-doc-4c784a84a66adf221597', 'source-node-004792', '5', '4792', 'text', '普通锈病：高粱柄锈菌（Puccinia sorghi）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004794', 'source-doc-4c784a84a66adf221597', 'source-node-004792', '5', '4793', 'text', '南方锈病：多堆柄锈菌（Puccinia polysora）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004795', 'source-doc-4c784a84a66adf221597', 'source-node-004787', '4', '4794', 'text', '三、发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004796', 'source-doc-4c784a84a66adf221597', 'source-node-004795', '5', '4795', 'text', '越冬与初侵染：病原菌以冬孢子在病残体或土壤中越冬，翌年 20-30℃、相对湿度 80% 以上且有充足露水时，冬孢子萌发产生担孢子，借气流传播侵染叶片；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004797', 'source-doc-4c784a84a66adf221597', 'source-node-004795', '5', '4796', 'text', '流行条件：玉米生长中后期，植株高大致田间郁闭、通风差，遇连阴雨利于流行；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004798', 'source-doc-4c784a84a66adf221597', 'source-node-004795', '5', '4797', 'text', '差异特征：南方地区发病重，感病品种发病早、病情发展快', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004799', 'source-doc-4c784a84a66adf221597', 'source-node-004787', '4', '4798', 'text', '四、防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004800', 'source-doc-4c784a84a66adf221597', 'source-node-004799', '5', '4799', 'text', '预防：选用抗病品种；合理密植改善通风；及时清病残体减少越冬菌源；玉米大喇叭口期喷含锌、硼微量元素叶面肥增强抗性；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004801', 'source-doc-4c784a84a66adf221597', 'source-node-004799', '5', '4800', 'text', '药剂防治：发病初期，用 25% 三唑酮可湿性粉剂 1500-2000 倍液、12.5% 烯唑醇可湿性粉剂 1000-1500 倍液或 43% 戊唑醇悬浮剂 3000-4000 倍液喷雾，重点喷叶片正反两面，7-10 天 1 次，连喷 2-3 次；也可选用丙环唑、苯醚甲环唑・丙环唑等，注意药剂交替使用', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004802', 'source-doc-4c784a84a66adf221597', 'source-node-004786', '3', '4801', 'text', '玉米大斑病（大斑病凸脐蠕孢Exserohilum turcicum）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004803', 'source-doc-4c784a84a66adf221597', 'source-node-004802', '4', '4802', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004804', 'source-doc-4c784a84a66adf221597', 'source-node-004802', '4', '4803', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004805', 'source-doc-4c784a84a66adf221597', 'source-node-004804', '5', '4804', 'text', '1. 主要为害叶片，严重时为害叶鞘和苞叶；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004806', 'source-doc-4c784a84a66adf221597', 'source-node-004804', '5', '4805', 'text', '2. 叶片初生青绿色浸润状病斑，后发展为褐色梭形大斑，长 5~10cm、宽 1~2cm，部分病斑纵贯叶片，具不规则轮纹；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004807', 'source-doc-4c784a84a66adf221597', 'source-node-004804', '5', '4806', 'text', '3. 高湿时病斑表面生灰黑色霉层（分生孢子梗和分生孢子）；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004808', 'source-doc-4c784a84a66adf221597', 'source-node-004804', '5', '4807', 'text', '4. 叶鞘、苞叶上生条形或不规则褐色斑块。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004809', 'source-doc-4c784a84a66adf221597', 'source-node-004802', '4', '4808', 'text', '发病规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004810', 'source-doc-4c784a84a66adf221597', 'source-node-004809', '5', '4809', 'text', '环境条件：高湿、多雨、田间通风透光差是共同有利条件，温度偏好有差异 —— 大斑病喜凉爽高湿，小斑病喜温暖高湿；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004811', 'source-doc-4c784a84a66adf221597', 'source-node-004809', '5', '4810', 'text', '田间管理：连作田病残体多、病原菌基数大，发病更重；玉米后期脱肥、植株衰弱会加重病情；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004812', 'source-doc-4c784a84a66adf221597', 'source-node-004809', '5', '4811', 'text', '品种抗性：种植感病品种是病害流行的主要因素，抗病性差易引发大面积发病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004813', 'source-doc-4c784a84a66adf221597', 'source-node-004809', '5', '4812', 'text', '病原菌特性：以菌丝体和分生孢子在病残体越冬，20-25℃、相对湿度 90% 以上时，孢子借风雨 / 气流传播，从叶片气孔或表皮侵入；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004814', 'source-doc-4c784a84a66adf221597', 'source-node-004809', '5', '4813', 'text', '关键发病场景：玉米生长中后期植株高大、田间郁闭，通风透光差，发病风险高；低洼地（高湿）、连作地（高病原菌基数）发病更重，若种植感病品种，易因 “环境适宜 + 品种抗性差” 叠加导致大面积发病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004815', 'source-doc-4c784a84a66adf221597', 'source-node-004802', '4', '4814', 'text', '防治', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004816', 'source-doc-4c784a84a66adf221597', 'source-node-004815', '5', '4815', 'text', '1. 品种防控：种植抗病杂交种，合理布局品种；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004817', 'source-doc-4c784a84a66adf221597', 'source-node-004815', '5', '4816', 'text', '2. 农业防控：轮作倒茬，深耕清除病残体；合理密植、间作套种改善通风；施足底肥，分期追肥防后期脱肥；及时摘除底部 2~3 片病叶并销毁；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004818', 'source-doc-4c784a84a66adf221597', 'source-node-004815', '5', '4817', 'text', '3. 药剂防控：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004819', 'source-doc-4c784a84a66adf221597', 'source-node-004818', '6', '4818', 'text', '大斑病：发病初期喷百菌清、甲基硫菌灵、多菌灵、丙环唑、嘧菌酯・丙环唑等；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004820', 'source-doc-4c784a84a66adf221597', 'source-node-004818', '6', '4819', 'text', '小斑病：发病初期喷代森锰锌、异菌脲、苯醚甲环唑等，注意轮换药剂（部分地区病菌对甲基硫菌灵、多菌灵已产生抗药性）。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004821', 'source-doc-4c784a84a66adf221597', 'source-node-004786', '3', '4820', 'text', '玉米小斑病（玉蜀黍平脐蠕孢Bipolaris maydis）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004822', 'source-doc-4c784a84a66adf221597', 'source-node-004821', '4', '4821', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004823', 'source-doc-4c784a84a66adf221597', 'source-node-004821', '4', '4822', 'text', '症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004824', 'source-doc-4c784a84a66adf221597', 'source-node-004823', '5', '4823', 'text', '1. 主要为害叶片，病斑呈梭形或椭圆形，两端圆 / 尖，黄褐色至褐色，边缘深褐至紫褐色，长 5~10mm、宽 3~4mm，受叶脉限制；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004825', 'source-doc-4c784a84a66adf221597', 'source-node-004823', '5', '4824', 'text', '2. 高湿时病斑生黑色霉层；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004826', 'source-doc-4c784a84a66adf221597', 'source-node-004823', '5', '4825', 'text', '3. 高感品种叶片生大型椭圆形浸润状病斑，不受叶脉限制，局部萎蔫；抗病品种生黄褐色坏死小斑点，周围具黄绿色晕圈。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004827', 'source-doc-4c784a84a66adf221597', 'source-node-004821', '4', '4826', 'text', '发病规律：病原菌主要以菌丝体在病残体上越冬，也可以分生孢子附着在种子表面越冬。翌年，在温度 25 - 30℃和湿度适宜时，分生孢子通过风雨传播，从叶片气孔或表皮侵入。种植密度过大、施肥不合理（偏施氮肥）、连作等因素会加重病害发生。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004828', 'source-doc-4c784a84a66adf221597', 'source-node-004821', '4', '4827', 'text', '预防方法：种子处理，用 50% 福美双可湿性粉剂按种子重量的 0.2% 拌种；合理密植，增施有机肥和磷、钾肥；及时清除病残体，减少病原菌传播。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004829', 'source-doc-4c784a84a66adf221597', 'source-node-004821', '4', '4828', 'text', '防治方法：发病初期，可选用 75% 百菌清可湿性粉剂 600 - 800 倍液、25% 丙环唑乳油 1000 - 1500 倍液等进行喷雾，每 7 - 10 天喷 1 次，连续喷 2 - 3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004830', 'source-doc-4c784a84a66adf221597', 'source-node-004786', '3', '4829', 'text', '玉米纹枯病（Rhizoctonia solani）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004831', 'source-doc-4c784a84a66adf221597', 'source-node-004830', '4', '4830', 'text', '一、症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004832', 'source-doc-4c784a84a66adf221597', 'source-node-004831', '5', '4831', 'text', '从植株底部 1-2 节叶鞘开始发病并向上扩展，叶鞘初现椭圆形至不规则形浅褐或浅黄色病斑，汇合后形成大型云纹状斑块（中部枯黄 / 枯白，边缘深褐 / 紫褐），可包围整个叶鞘；叶片、果穗苞叶也生类似云纹状病斑；高湿时病部生稀疏白色菌丝体和褐色小菌核；病株茎秆松软、组织解体，穗轴与籽粒变褐腐烂', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004833', 'source-doc-4c784a84a66adf221597', 'source-node-004830', '4', '4832', 'text', '二、病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004834', 'source-doc-4c784a84a66adf221597', 'source-node-004833', '5', '4833', 'text', '主要为立枯丝核菌（Rhizoctonia solani），其次为玉米丝核菌（R. zeae）、禾谷丝核菌（R. cerealis）等真菌', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004835', 'source-doc-4c784a84a66adf221597', 'source-node-004830', '4', '4834', 'text', '三、发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004836', 'source-doc-4c784a84a66adf221597', 'source-node-004835', '5', '4835', 'text', '越冬与传播：病原菌以菌丝体或菌核在土壤及病残体上越冬；温度 25-30℃、相对湿度 85% 以上时，菌核萌发产生菌丝，借雨水、灌溉水、农事操作传播，从基部叶鞘、茎秆的气孔或伤口侵入；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004837', 'source-doc-4c784a84a66adf221597', 'source-node-004835', '5', '4836', 'text', '发病诱因：种植密度大、氮肥施用过多、田间通风透光差、地势低洼排水不良，发病严重；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004838', 'source-doc-4c784a84a66adf221597', 'source-node-004835', '5', '4837', 'text', '发病时期：玉米生长中后期病情加剧，连作（尤其与高粱、水稻、麦类等禾本科作物接茬）会增加病原菌积累，加重发病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004839', 'source-doc-4c784a84a66adf221597', 'source-node-004830', '4', '4838', 'text', '四、防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004840', 'source-doc-4c784a84a66adf221597', 'source-node-004839', '5', '4839', 'text', '预防：选用抗病或耐病品种；合理密植改善通风；科学施肥（控氮肥、增磷钾肥与有机肥）；及时清除病残体并深耕，减少越冬菌源；实行轮作，与水稻等水旱轮作效果佳，避免与禾本科作物接茬；合理排灌防田间积水', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004841', 'source-doc-4c784a84a66adf221597', 'source-node-004839', '5', '4840', 'text', '药剂防治：发病初期，用 5% 井冈霉素水剂 1000-1500 倍液、30% 苯醚甲环唑・丙环唑乳油 2000-3000 倍液或菌核净喷雾 / 灌根，重点针对植株基部；也可将药剂制成药土施入玉米喇叭口，7-10 天 1 次，连施 2-3 次', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004842', 'source-doc-4c784a84a66adf221597', 'source-node-004786', '3', '4841', 'text', '玉米茎腐病（Fusarium moniliforme）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004843', 'source-doc-4c784a84a66adf221597', 'source-node-004842', '4', '4842', 'text', '一、症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004844', 'source-doc-4c784a84a66adf221597', 'source-node-004843', '5', '4843', 'text', '病株根部和茎基部腐烂变色，茎基部生不规则褐色病斑；高湿时病部表面生白色或粉色霉状物，后期产生蓝黑色小粒点（镰刀菌子囊壳）；茎秆内髓部腐烂消解，仅残留游离丝状维管束形成空腔；叶片自下而上变色枯萎，易倒伏，环境适宜时病株快速青枯，一般情况逐渐黄枯', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004845', 'source-doc-4c784a84a66adf221597', 'source-node-004842', '4', '4844', 'text', '二、病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004846', 'source-doc-4c784a84a66adf221597', 'source-node-004845', '5', '4845', 'text', '由镰刀菌和腐霉菌复合侵染引起，以镰刀菌为主；主要镰刀菌种类包括禾谷镰刀菌（Fusarium graminearum）、轮枝状镰刀菌（Fusarium verticillioides）、胶孢镰刀菌（F. subglutinans）和层生镰刀菌（F. proliferatum）等', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004847', 'source-doc-4c784a84a66adf221597', 'source-node-004842', '4', '4846', 'text', '三、发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004848', 'source-doc-4c784a84a66adf221597', 'source-node-004847', '5', '4847', 'text', '越冬与传播：病原菌在土壤、病残体及种子上越冬，可存活多年；借雨水、灌溉水、昆虫及农事操作传播，从根部或茎基部伤口侵入；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004849', 'source-doc-4c784a84a66adf221597', 'source-node-004847', '5', '4848', 'text', '适宜条件：高温（28-32℃）、高湿（相对湿度 85% 以上）环境，尤其暴雨后遇高温闷热天气，利于发病；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004850', 'source-doc-4c784a84a66adf221597', 'source-node-004847', '5', '4849', 'text', '栽培影响：连作地、土壤贫瘠、种植密度过大、偏施氮肥少施钾肥，导致植株生长不良、根系弱、抗性差，病害更易流行；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004851', 'source-doc-4c784a84a66adf221597', 'source-node-004847', '5', '4850', 'text', '发病时期：常于玉米灌浆期至成熟期大面积发生，造成茎秆变软、倒伏，果穗下垂腐烂', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004852', 'source-doc-4c784a84a66adf221597', 'source-node-004842', '4', '4851', 'text', '四、防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004853', 'source-doc-4c784a84a66adf221597', 'source-node-004852', '5', '4852', 'text', '预防：选用抗病品种；与豆类、薯类等非禾本科作物轮作 2-3 年，减少病原菌积累；播前用咯菌腈、福美双或福・克悬浮种衣剂、咯菌・精甲霜悬浮种衣剂拌种 / 包衣；合理密植保通风，增施有机肥与钾肥、配施氮磷肥，增强抗逆性；做好田间排水，避免积水', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004854', 'source-doc-4c784a84a66adf221597', 'source-node-004852', '5', '4853', 'text', '药剂防治：发病初期，用 50% 多菌灵可湿性粉剂 500 倍液、70% 甲基托布津可湿性粉剂 800 倍液灌根（每株 200-300 毫升），或 25% 戊唑醇水乳剂 1000-1500 倍液、30% 苯醚甲环唑・丙环唑乳油 2000-3000 倍液喷雾（重点喷茎基部），7-10 天 1 次，连喷 2-3 次', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004855', 'source-doc-4c784a84a66adf221597', 'source-node-004786', '3', '4854', 'text', '玉米穗腐病（Aspergillus flavus等多种病原菌引发）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004856', 'source-doc-4c784a84a66adf221597', 'source-node-004855', '4', '4855', 'text', '一、症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004857', 'source-doc-4c784a84a66adf221597', 'source-node-004856', '5', '4856', 'text', '轮枝状镰刀菌侵染时，籽粒顶部生粉红或白色粉状物，籽粒间有白色絮状菌丝，后期果皮生粉白色条斑；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004858', 'source-doc-4c784a84a66adf221597', 'source-node-004856', '5', '4857', 'text', '禾谷镰刀菌侵染多从果穗顶端开始，布满紫红色霉层，籽粒及间隙生棉絮状红或白色菌丝；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004859', 'source-doc-4c784a84a66adf221597', 'source-node-004856', '5', '4858', 'text', '青霉菌侵染时，穗轴和籽粒间生蓝绿色霉层，病粒苍白色；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004860', 'source-doc-4c784a84a66adf221597', 'source-node-004856', '5', '4859', 'text', '粉红单端孢侵染后，果穗覆盖橙红色粉状物；同一果穗可能受多种真菌复合侵染', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004861', 'source-doc-4c784a84a66adf221597', 'source-node-004855', '4', '4860', 'text', '二、病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004862', 'source-doc-4c784a84a66adf221597', 'source-node-004861', '5', '4861', 'text', '由 30 余种病原真菌单独或复合侵染引起，优势种类为镰刀菌（含轮枝状镰刀菌Fusarium verticillioides、禾谷镰刀菌F. graminearum等），此外还有青霉菌、粉红单端孢、灰霉菌、黑孢霉、枝孢霉等', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004863', 'source-doc-4c784a84a66adf221597', 'source-node-004855', '4', '4862', 'text', '三、发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004864', 'source-doc-4c784a84a66adf221597', 'source-node-004863', '5', '4863', 'text', '越冬与传播：病原菌主要以菌丝体、分生孢子在病残体、土壤、种子表面越冬；玉米收获期遇潮湿天气，病原菌田间侵染果穗；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004865', 'source-doc-4c784a84a66adf221597', 'source-node-004863', '5', '4864', 'text', '流行条件：仓储阶段湿度超 80%、温度 25-30℃时，残留病原菌再次侵染蔓延；果穗受虫咬、机械损伤，或未及时收获、晾晒不充分、存储条件差，均利于病原菌侵染；', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004866', 'source-doc-4c784a84a66adf221597', 'source-node-004863', '5', '4865', 'text', '特定菌条件：黄曲霉在高温高湿、偏酸性土壤及果穗含水量高时滋生迅猛；镰刀菌在土壤湿度大、温度适宜时，借风雨传播至果穗', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004867', 'source-doc-4c784a84a66adf221597', 'source-node-004855', '4', '4866', 'text', '四、防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004868', 'source-doc-4c784a84a66adf221597', 'source-node-004867', '5', '4867', 'text', '预防：种植抗病品种；合理密植保证通风透光，降低田间湿度；及时防治玉米螟等害虫，减少果穗伤口；适期收获，收获后快速晾晒至果穗含水量 14% 左右，妥善仓储（保持仓库干燥通风），定期检查清除霉变果穗', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004869', 'source-doc-4c784a84a66adf221597', 'source-node-004867', '5', '4868', 'text', '药剂防治：田间发病初期，用 40% 多菌灵・福美双可湿性粉剂 800 倍液、50% 甲基硫菌灵可湿性粉剂 600 倍液喷雾果穗，7-10 天 1 次，连喷 2-3 次；仓储期发现霉变，及时挑出病穗，用环氧乙烷等熏蒸剂按规程消毒仓库。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004870', 'source-doc-4c784a84a66adf221597', 'source-node-004786', '3', '4869', 'text', '玉米黑穗病（Ustilago maydis）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004871', 'source-doc-4c784a84a66adf221597', 'source-node-004870', '4', '4870', 'text', '发病规律：病原菌以冬孢子在土壤、病残体及种子表面越冬，冬孢子存活期长。翌年春季，在适宜温湿度（土壤温度12 - 25℃、含水量20% - 25%）下，冬孢子萌发产生担孢子，借风雨、气流传播，从玉米幼芽鞘、幼苗叶片、花丝等幼嫩组织侵入，在玉米生长前期侵染，潜伏至抽穗期显症。连作地、土壤带菌量大、播种过深、出苗慢、低温干旱或春雨连绵致土壤湿度大且温度不稳定，均利于发病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004872', 'source-doc-4c784a84a66adf221597', 'source-node-004870', '4', '4871', 'text', '预防方法：选用抗病品种，实行轮作，与高粱等轮作3 - 5年；种子处理，用20%三唑酮乳油按种子重量的0.4%拌种，或用戊唑醇、咯菌腈等拌种；适期播种，控制播种深度（3 - 5厘米），保证出苗整齐、健壮；及时拔除田间病株，带出田外深埋或烧毁，减少病原菌传播。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004873', 'source-doc-4c784a84a66adf221597', 'source-node-004870', '4', '4872', 'text', '防治方法：发现病株及时处理，在未大面积扩散前，周边植株可用12.5%烯唑醇可湿性粉剂1000 - 1500倍液喷雾预防，重点喷幼苗、叶片及雌、雄穗部位，7 - 10天1次，连喷2 - 3次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004874', 'source-doc-4c784a84a66adf221597', 'source-node-004779', '2', '4873', 'text', '病毒（常见玉米粗缩病、玉米矮花叶病）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004875', 'source-doc-4c784a84a66adf221597', 'source-node-004874', '3', '4874', 'text', '一、玉米粗缩病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004876', 'source-doc-4c784a84a66adf221597', 'source-node-004875', '4', '4875', 'text', '（一）症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004877', 'source-doc-4c784a84a66adf221597', 'source-node-004876', '5', '4876', 'text', '病株节间缩短、异常矮小（株高常不及健株 1/2），多不能抽穗结实；幼苗 5-6 叶期显症，上部节间粗肿、叶片对生，心叶基部和中脉两侧现褪绿条点并连成细线，后期叶片发黄枯死；部分病株顶部叶片簇生、僵直宽短，雄穗发育不良或不能抽出，雌穗畸形、花丝少；叶背、叶鞘和苞叶的叶脉上有蜡白色隆起（脉突）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004878', 'source-doc-4c784a84a66adf221597', 'source-node-004875', '4', '4877', 'text', '（二）病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004879', 'source-doc-4c784a84a66adf221597', 'source-node-004878', '5', '4878', 'text', '水稻黑条矮缩病毒（Rice black streak dwarf virus）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004880', 'source-doc-4c784a84a66adf221597', 'source-node-004875', '4', '4879', 'text', '（三）发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004881', 'source-doc-4c784a84a66adf221597', 'source-node-004880', '5', '4880', 'text', '由灰飞虱持久性传毒，灰飞虱在小麦、杂草等寄主上越冬繁殖；春季带毒灰飞虱迁飞至玉米田，在玉米 3-5 叶期，若虫、成虫刺吸汁液传毒；病毒在 20-30℃、相对湿度 70%-80% 环境下迅速繁殖扩散；玉米生长前期感染，症状明显（植株矮化、叶片浓绿宽短僵直呈对生状），后期抽穗困难、结实率极低。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004882', 'source-doc-4c784a84a66adf221597', 'source-node-004875', '4', '4881', 'text', '（四）防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004883', 'source-doc-4c784a84a66adf221597', 'source-node-004882', '5', '4882', 'text', '预防：选用抗病品种；调整播期（春玉米晚播、秋玉米早播），避开灰飞虱迁飞与传毒高峰期；清除田间及周边杂草，减少灰飞虱越冬场所与病毒寄主；玉米田设防虫网阻灰飞虱迁入，挂蓝色粘虫板诱杀；做好小麦等前茬作物灰飞虱防治，切断传播链', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004884', 'source-doc-4c784a84a66adf221597', 'source-node-004882', '5', '4883', 'text', '药剂防治：玉米 3-5 叶期，见灰飞虱活动即喷 2.5% 溴氰菊酯乳油 2000-3000 倍液、10% 吡虫啉可湿性粉剂 1500-2000 倍液防灰飞虱，同时喷 20% 病毒 A 可湿性粉剂 500 倍液、8% 宁南霉素・吗啉胍水剂 500-800 倍液防病毒，7-10 天 1 次，连喷 2-3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004885', 'source-doc-4c784a84a66adf221597', 'source-node-004874', '3', '4884', 'text', '二、玉米矮花叶病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004886', 'source-doc-4c784a84a66adf221597', 'source-node-004885', '4', '4885', 'text', '（一）症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004887', 'source-doc-4c784a84a66adf221597', 'source-node-004886', '5', '4886', 'text', '病株矮小，叶片生黄绿相间条纹；初期新叶基部叶脉间现褪绿斑点、斑纹，沿叶脉形成断续黄色条点（叶脉保持绿色），后期扩展为宽褪绿条纹并覆盖全叶；病叶变黄、质硬脆易折断，部分品种叶尖 / 叶缘现紫红色条纹；叶鞘和苞叶也现花叶症状', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004888', 'source-doc-4c784a84a66adf221597', 'source-node-004885', '4', '4887', 'text', '（二）病原', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004889', 'source-doc-4c784a84a66adf221597', 'source-node-004888', '5', '4888', 'text', '玉米矮花叶病毒（Maize dwarf mosaic virus）', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004890', 'source-doc-4c784a84a66adf221597', 'source-node-004885', '4', '4889', 'text', '（三）发生规律', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004891', 'source-doc-4c784a84a66adf221597', 'source-node-004890', '5', '4890', 'text', '由蚜虫非持久性传毒，蚜虫在多种寄主上越冬繁殖；春季有翅蚜迁飞至玉米田，在玉米苗期至拔节期频繁刺吸汁液传毒；病毒在 25-30℃、相对湿度 70%-80% 时传播迅速；受害玉米叶片沿叶脉现黄绿条纹，植株矮化、生长缓慢，严重影响产量。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004892', 'source-doc-4c784a84a66adf221597', 'source-node-004885', '4', '4891', 'text', '（四）防治方法', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004893', 'source-doc-4c784a84a66adf221597', 'source-node-004892', '5', '4892', 'text', '预防：选用抗病高产杂交种；种植前清除田间及周边杂草，减少蚜虫越冬场所与病毒寄主；玉米田挂黄色粘虫板诱杀蚜虫；加强田间管理，培育壮苗提高植株抗病毒能力', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004894', 'source-doc-4c784a84a66adf221597', 'source-node-004892', '5', '4893', 'text', '药剂防治：玉米苗期至拔节期，见蚜虫即喷 10% 吡虫啉可湿性粉剂 1500-2000 倍液、25% 噻虫嗪水分散粒剂 3000-5000 倍液防蚜虫，同时喷 20% 病毒 A 可湿性粉剂 500 倍液、1.5% 植病灵乳剂 1000 倍液防病毒，7-10 天 1 次，连喷 3-4 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004895', 'source-doc-4c784a84a66adf221597', 'source-node-004874', '3', '4894', 'text', '虫害：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004896', 'source-doc-4c784a84a66adf221597', 'source-node-004895', '4', '4895', 'text', '玉米螟（Ostrinia nubilalis）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004897', 'source-doc-4c784a84a66adf221597', 'source-node-004896', '5', '4896', 'text', '发病规律：以老熟幼虫在玉米秸秆、穗轴等寄主植物残体中越冬。翌年春季化蛹，成虫羽化后，具有趋光性，夜间活动，将卵产在玉米叶片背面，多呈鱼鳞状排列。幼虫孵化后，先在叶片上取食，形成排孔，然后蛀入茎秆、雌雄穗等部位为害，咬食髓部，影响养分运输与水分传导，导致茎秆折断、果穗发育不良，在温度25 - 30℃、相对湿度70%左右时，繁殖速度快，为害严重，一般在玉米生长中后期集中为害。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004898', 'source-doc-4c784a84a66adf221597', 'source-node-004896', '5', '4897', 'text', '预防方法：秋末冬初，及时处理玉米秸秆、穗轴，粉碎还田或集中烧毁、深埋，减少越冬虫源；利用黑光灯诱捕成虫，在玉米田每隔30 - 50米设置一盏，每天日落开启，日出关闭；释放赤眼蜂，在玉米螟产卵初期，每亩释放1 - 2万头，每隔7 - 10天释放一次，连续释放2 - 3次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004899', 'source-doc-4c784a84a66adf221597', 'source-node-004896', '5', '4898', 'text', '防治方法：在幼虫孵化盛期，可选用1.5%辛硫磷颗粒剂，每亩1 - 2千克，加细土5 - 6千克，撒于心叶内；或用20%氯虫苯甲酰胺悬浮剂3000 - 4000倍液喷雾，重点喷心叶、雄穗、雌穗等部位，7 - 10天1次，依虫情喷2 - 3次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004900', 'source-doc-4c784a84a66adf221597', 'source-node-004895', '4', '4899', 'text', '玉米蚜（Rhopalosiphum maidis）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004901', 'source-doc-4c784a84a66adf221597', 'source-node-004900', '5', '4900', 'text', '发病规律：以卵在杂草等寄主上越冬。春季孵化后，产生有翅蚜或无翅蚜，在玉米叶片背面、嫩茎等部位吸食汁液。繁殖速度快，在适宜的温度（20 - 25℃）和湿度条件下，数天即可繁殖一代。玉米生长中后期，尤其是抽穗期，植株营养丰富，蚜虫聚集量剧增，分泌的蜜露会引发煤污病，影响玉米光合作用，严重时导致植株生长不良，穗部发育受阻。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004902', 'source-doc-4c784a84a66adf221597', 'source-node-004900', '5', '4901', 'text', '预防方法：清除田间杂草和残株，减少蚜虫越冬场所与滋生地；在玉米田悬挂黄色粘虫板，利用蚜虫趋黄性诱杀；合理密植，保证田间通风透光，避免植株过密助长蚜虫繁殖。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004903', 'source-doc-4c784a84a66adf221597', 'source-node-004900', '5', '4902', 'text', '防治方法：可选用10%吡虫啉可湿性粉剂1500 - 2000倍液、50%抗蚜威可湿性粉剂2000 - 3000倍液等进行喷雾，重点喷叶片背面、嫩茎及穗部，7 - 10天1次，视虫情喷2 - 3次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004904', 'source-doc-4c784a84a66adf221597', 'source-node-004895', '4', '4903', 'text', '玉米叶蝉（Cicadellidae）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004905', 'source-doc-4c784a84a66adf221597', 'source-node-004904', '5', '4904', 'text', '发病规律：多以成虫在田边杂草、树林等隐蔽处越冬，春季气温回升后，陆续迁入玉米田，趋光性、趋嫩性明显，喜欢在玉米新叶、嫩梢吸食汁液，通过刺吸式口器损伤细胞，传播病毒病，在温度22 - 28℃、相对湿度70% - 80%时活动频繁，繁殖较快，玉米生长前期受害，影响叶片生长与光合作用，导致叶片发黄、卷曲，生长迟缓。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004906', 'source-doc-4c784a84a66adf221597', 'source-node-004904', '5', '4905', 'text', '预防方法：清除田边杂草、杂树，破坏叶蝉越冬栖息场所；在玉米田四周设置防虫网，阻止叶蝉迁入；利用黑光灯诱捕成虫，减少田间虫口密度；加强田间管理，培育壮苗，提高植株抗虫能力。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004907', 'source-doc-4c784a84a66adf221597', 'source-node-004904', '5', '4906', 'text', '防治方法：发现叶蝉活动时，可用2.5%溴氰菊酯乳油2000 - 3000倍液、10%吡虫啉可湿性粉剂1500 - 2000倍液喷雾，重点喷新叶、嫩梢部位，7 - 10天1次，连喷2 - 3次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004908', 'source-doc-4c784a84a66adf221597', 'source-node-004895', '4', '4907', 'text', '玉米夜蛾（Spodoptera frugiperda）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004909', 'source-doc-4c784a84a66adf221597', 'source-node-004908', '5', '4908', 'text', '发病规律：是一种迁飞性害虫，在热带、亚热带地区可终年繁殖，北方以幼虫或蛹在杂草、麦田等场所越冬。成虫具有趋光性和趋化性，夜间活动，将卵产在玉米叶片尖端或枯黄叶片上，卵块覆盖绒毛。幼虫孵化后，群集取食叶片，呈半透明薄膜状，长大后分散为害，食量增大，可将叶片吃光，还会蛀食茎秆、果穗，在温度25 - 30℃、相对湿度70% - 80%时，繁殖和为害较重，尤其在玉米生长中后期对产量威胁大。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004910', 'source-doc-4c784a84a66adf221597', 'source-node-004908', '5', '4909', 'text', '预防方法：利用糖醋液（糖:醋:酒:水 = 3:4:1:2）诱捕成虫，在玉米田周边每隔10 - 15米放置一盆；利用黑光灯诱捕成虫，减少田间产卵量；及时清除田间杂草、残株，减少幼虫越冬场所与食物来源。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004911', 'source-doc-4c784a84a66adf221597', 'source-node-004908', '5', '4910', 'text', '防治方法：在幼虫3龄前，可选用5%高效氯氟氰菊酯乳油1500 - 2000倍液、20%氯虫苯甲酰胺悬浮剂3000 - 4000倍液等进行喷雾，重点喷叶片、茎秆、果穗等部位，7 - 10天1次，依虫情喷2 - 3次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004912', 'source-doc-4c784a84a66adf221597', 'source-node-004895', '4', '4911', 'text', '玉米象（Sitophilus zeamais）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004913', 'source-doc-4c784a84a66adf221597', 'source-node-004912', '5', '4912', 'text', '发病规律：主要在仓库中为害玉米种子及收获后的玉米粒，成虫在仓库墙壁、梁柱、包装材料等缝隙处越冬，翌年春天气温回升后，活动取食、交配产卵，将卵产在玉米粒内，幼虫在粒内蛀食，造成玉米粒破碎、营养流失、发霉变质，成虫善爬行、能飞，喜阴暗、潮湿、温暖环境，在温度25 - 30℃、相对湿度70% - 80%时繁殖迅速，仓储条件差、玉米含水量高时为害严重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004914', 'source-doc-4c784a84a66adf221597', 'source-node-004912', '5', '4913', 'text', '预防方法：仓库清洁消毒，在玉米入库前，彻底清扫仓库，用敌百虫、磷化铝等药剂熏蒸消毒；玉米晾晒干燥，使含水量降至14%以下再入库；改善仓储条件，保持仓库通风、干燥、低温，定期检查，翻动玉米，防止局部发热、发霉。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004915', 'source-doc-4c784a84a66adf221597', 'source-node-004912', '5', '4914', 'text', '防治方法：发现玉米象为害，及时用磷化铝按每立方米3 - 5片（根据虫口密度调整）进行熏蒸处理，熏蒸时间7 - 10天，处理后通风散气，确保', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004916', 'source-doc-4c784a84a66adf221597', 'source-node-004895', '4', '4915', 'text', '玉米跳甲（Chaetocnema pulicaria）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004917', 'source-doc-4c784a84a66adf221597', 'source-node-004916', '5', '4916', 'text', '发病规律：以成虫在田边杂草、残株及土缝内越冬，春季气温回升到 10℃左右时开始活动，先在杂草上取食、繁殖，待玉米出苗后，凭借其较强的跳跃能力转移至玉米田为害。成虫具有趋嫩性和趋光性，喜欢聚集在玉米幼苗叶片上啃食叶肉，形成许多细密的小孔，严重时叶片呈筛网状，影响光合作用和幼苗生长。幼虫则生活在土壤中，啃食玉米根部，造成根系损伤，导致植株生长衰弱、发黄，甚至死亡。在高温干旱的环境下，玉米跳甲繁殖速度加快，为害程度加重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004918', 'source-doc-4c784a84a66adf221597', 'source-node-004916', '5', '4917', 'text', '预防方法：秋收后及时清理田间及周边杂草、残株，深耕土地，破坏其越冬场所，减少虫源基数；合理轮作，避免连作，可与豆类、薯类等作物轮作；在玉米播种前，对土壤进行药剂处理，如用辛硫磷颗粒剂撒施后翻耕，毒杀土壤中的幼虫。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004919', 'source-doc-4c784a84a66adf221597', 'source-node-004916', '5', '4918', 'text', '防治方法：成虫发生初期，可选用 5% 高效氯氟氰菊酯乳油 2000 - 3000 倍液、2.5% 溴氰菊酯乳油 2000 - 3000 倍液等进行喷雾防治，重点喷施玉米幼苗叶片，确保药剂覆盖均匀，7 - 10 天喷施 1 次，连续喷施 2 - 3 次；针对幼虫为害根部情况，可用 40% 辛硫磷乳油 1000 倍液灌根处理，每株灌药量约 200 毫升，以毒杀幼虫，保护根系。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004920', 'source-doc-4c784a84a66adf221597', 'source-node-004895', '4', '4919', 'text', '玉米螨（Tetranychus urticae）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004921', 'source-doc-4c784a84a66adf221597', 'source-node-004920', '5', '4920', 'text', '发病规律：多以雌成螨在玉米田的杂草根部、枯枝落叶下以及土缝等隐蔽处越冬，春季气温达 10℃以上时开始复苏活动、繁殖。玉米螨喜高温干旱环境，在 25 - 30℃、相对湿度 40% - 60% 条件下，繁殖力极强，10 天左右便可完成一代。其靠爬行和吐丝结网随风飘散扩散，初期多聚集在玉米叶片背面，用刺吸式口器吸食叶肉汁液，致使叶片出现黄白色斑点，随着为害加重，斑点连片，叶片干枯、卷曲，严重影响玉米植株的光合作用和正常生长，尤其在玉米生长中后期，田间郁闭、通风透光不良时，更易暴发成灾。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004922', 'source-doc-4c784a84a66adf221597', 'source-node-004920', '5', '4921', 'text', '预防方法：及时清除田间杂草、残株，减少玉米螨的越冬场所和滋生地；合理灌溉，避免田间过于干旱，保持适宜湿度，破坏其适宜生存环境；定期巡查玉米田，发现少量玉米螨时，及时摘除受害叶片，并带出田外集中销毁，防止其扩散蔓延。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004923', 'source-doc-4c784a84a66adf221597', 'source-node-004920', '5', '4922', 'text', '防治方法：发病初期，可选用 1.8% 阿维菌素乳油 1000 - 1500 倍液、20% 哒螨灵可湿性粉剂 1000 - 1500 倍液、73% 克螨特乳油 1000 - 1500 倍液等喷雾防治，重点喷施叶片背面，要喷匀喷透，保证药剂覆盖，5 - 7 天喷施 1 次，连续喷施 2 - 3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004924', 'source-doc-4c784a84a66adf221597', 'source-node-004895', '4', '4923', 'text', '玉米蝽（Euschistus servus）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004925', 'source-doc-4c784a84a66adf221597', 'source-node-004924', '5', '4924', 'text', '发病规律：以成虫在田边的草丛、树林、篱笆及田间残株等隐蔽处越冬，春季气温回升到 15℃以上时，开始外出活动、觅食、交配产卵。成虫具有趋嫩性和趋化性，喜欢吸食玉米植株的嫩茎、嫩叶、幼穗汁液，造成叶片出现枯黄斑点、嫩茎扭曲变形、幼穗发育不良等症状。卵多产在叶片背面或嫩茎上，呈块状排列，幼虫孵化后，群集在卵块附近为害，稍大后分散活动，继续吸食玉米汁液，在温度 25 - 30℃、相对湿度 70% - 80% 且玉米处于生长旺盛期时，为害最为严重，可导致玉米减产、品质下降。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004926', 'source-doc-4c784a84a66adf221597', 'source-node-004924', '5', '4925', 'text', '预防方法：冬季清理田间及周边杂草、残株，铲除田边灌木丛等隐蔽场所，破坏其越冬环境，减少越冬虫源；在玉米田四周设置防虫网，阻止成虫迁入；合理密植，加强田间通风透光，增强玉米植株抗性；结合农事操作，人工摘除卵块，集中销毁，降低虫口密度。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004927', 'source-doc-4c784a84a66adf221597', 'source-node-004924', '5', '4926', 'text', '防治方法：成虫和若虫发生期，可选用 4% 高氯・甲维盐乳油 1000 - 1500 倍液、2.5% 三氟氯氰菊酯乳油 2000 - 3000 倍液等进行喷雾防治，重点喷施玉米的嫩茎、嫩叶、幼穗等部位，7 - 10 天喷施 1 次，连续喷施 2 - 3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004928', 'source-doc-4c784a84a66adf221597', 'source-node-004779', '2', '4927', 'text', '生理病害：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004929', 'source-doc-4c784a84a66adf221597', 'source-node-004928', '3', '4928', 'text', '玉米缺素症（常见氮、磷、钾、锌等多种元素缺乏）：', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004930', 'source-doc-4c784a84a66adf221597', 'source-node-004929', '4', '4929', 'text', '发病规律（以缺氮为例）：土壤本身肥力低、贫瘠，含氮量少；前茬作物耗氮量大，未及时补充；玉米生长中后期，需氮量剧增，追肥不及时，导致植株缺氮。初期叶片淡绿至黄绿，从下部老叶开始，沿叶片中脉向叶尖发展，严重时叶片枯黄、早衰，影响光合作用与产量。缺磷时，幼苗根系发育不良、生长缓慢，叶片呈紫红色；缺钾，叶片边缘发黄、焦枯，呈“V”字形，从下部叶向上发展，因钾参与植株体内物质运输、渗透调节等，缺钾阻碍植株正常代谢。缺锌则新叶中脉两侧出现白化条纹，叶片窄小、节间缩短，影响植株生长与生殖发育。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004931', 'source-doc-4c784a84a66adf221597', 'source-node-004929', '4', '4930', 'text', '预防方法：测土配方施肥，依据土壤养分含量与玉米需肥特性，精准补肥；增施有机肥，改善土壤结构，提高土壤肥力与保肥供肥能力；合理轮作，避免过度消耗土壤养分。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004932', 'source-doc-4c784a84a66adf221597', 'source-node-004929', '4', '4931', 'text', '防治方法：缺氮，及时追施尿素等氮肥，每亩施用量根据生长阶段与缺素程度调整（如大喇叭口期可追施15 - 20公斤/亩）；缺磷，追施过磷酸钙或喷施磷酸二氢钾溶液；缺钾，叶面喷施0.5% - 1%硫酸钾溶液或追施氯化钾；缺锌，用0.1% - 0.2%硫酸锌溶液叶面喷施，7 - 10天1次，连喷2 - 3次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004933', 'source-doc-4c784a84a66adf221597', 'source-node-004928', '3', '4932', 'text', '玉米涝害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004934', 'source-doc-4c784a84a66adf221597', 'source-node-004933', '4', '4933', 'text', '发病规律（涝害）：玉米生长期间，遭遇暴雨、连阴雨天气，田间积水，土壤透气性变差，根系缺氧，呼吸受阻，无氧呼吸产生酒精等有害物质，毒害根系，导致根系变黑、腐烂，植株生长不良，叶片发黄、萎蔫，严重时整株死亡。尤其在苗期、大喇叭口期，根系发育不完善或需水量大时，涝害影响更甚。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004935', 'source-doc-4c784a84a66adf221597', 'source-node-004933', '4', '4934', 'text', '预防方法（涝害）：选地势高、排水良好地块种植；完善田间排水系统，挖排水沟、设排水渠，确保雨停田干；起垄种植，提高土壤透气性与排水能力。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004936', 'source-doc-4c784a84a66adf221597', 'source-node-004933', '4', '4935', 'text', '防治方法（涝害）：雨后及时排水，中耕松土，破除板结，增加土壤透气性；追施少量氮肥、叶面喷施生根剂与多元复合肥，促进根系恢复生长，如每亩追施尿素5 - 10公斤，叶面喷施0.2%尿素 + 0.2%磷酸二氢钾 + 生根剂溶液。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004937', 'source-doc-4c784a84a66adf221597', 'source-node-004928', '3', '4936', 'text', '玉米旱害', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004938', 'source-doc-4c784a84a66adf221597', 'source-node-004937', '4', '4937', 'text', '发病规律（旱害）：长时间无雨、高温干旱，土壤水分严重不足，玉米植株蒸腾失水大于吸水，叶片气孔关闭，光合作用受抑制，生长缓慢，植株矮小，叶片卷曲、干枯，抽穗期干旱，会使雄穗抽出困难、雌穗发育不良，影响授粉受精，导致结实率降低。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004939', 'source-doc-4c784a84a66adf221597', 'source-node-004937', '4', '4938', 'text', '预防方法（旱害）：选择耐旱品种；采用地膜覆盖、秸秆覆盖等保墒措施，减少土壤水分蒸发；合理灌溉，根据玉米需水规律，苗期适当控水，大喇叭口期至灌浆期及时浇水，满足生长需求。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004940', 'source-doc-4c784a84a66adf221597', 'source-node-004937', '4', '4939', 'text', '防治方法（旱害）：干旱发生时，及时灌溉，优先采用滴灌、喷灌等节水灌溉方式，避免大水漫灌浪费水资源；结合灌溉，追施尿素等氮肥，补充营养，提高抗旱能力，每亩追施尿素8 - 12公斤。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004941', 'source-doc-4c784a84a66adf221597', 'source-node-004777', '1', '4940', 'text', '2.3.3 大豆/毛豆', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004942', 'source-doc-4c784a84a66adf221597', 'source-node-004941', '2', '4941', 'text', '菌核病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004943', 'source-doc-4c784a84a66adf221597', 'source-node-004942', '3', '4942', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004944', 'source-doc-4c784a84a66adf221597', 'source-node-004943', '4', '4943', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004945', 'source-doc-4c784a84a66adf221597', 'source-node-004942', '3', '4944', 'text', '防治：戊唑·咪鲜胺、嘧菌环胺·咯菌腈+氟啶胺、腐霉利、异菌脲、菌核净', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004946', 'source-doc-4c784a84a66adf221597', NULL, '0', '4945', 'text', '2.4 药材', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004947', 'source-doc-4c784a84a66adf221597', 'source-node-004946', '1', '4946', 'text', '牛大力', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004948', 'source-doc-4c784a84a66adf221597', 'source-node-004946', '1', '4947', 'text', '淫羊藿', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004949', 'source-doc-4c784a84a66adf221597', 'source-node-004948', '2', '4948', 'text', '淫羊藿叶褐斑枯病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004950', 'source-doc-4c784a84a66adf221597', 'source-node-004949', '3', '4949', 'text', '症状：此病为害叶片。患病叶病斑，初期为褐色斑点，周围有黄色晕圈。扩展后病斑呈不规则状，边缘红褐色至褐色，中部呈灰褐色；后期病斑灰褐色，收缩，出现黑色粒状物，此为病菌的分生孢子器。病菌在淫羊藿苗期和成株期均有发生，以幼苗期发生较多危害重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004951', 'source-doc-4c784a84a66adf221597', 'source-node-004949', '3', '4950', 'text', '病原：病原学检测为大茎点霉属真菌。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004952', 'source-doc-4c784a84a66adf221597', 'source-node-004949', '3', '4951', 'text', '发病特点：该病病原菌以菌丝体或分生孢子器在病残体中越冬，能存活8-9个月。翌年春天遇雨或潮湿天气，从孢子器的孔口涌出大量的分生孢子，通过风雨、昆虫媒介传播进行初侵染。以后在适宜的条件下不断进行再侵染。多雨高温季节发病严重，暴风雨过后常导致流行。组织幼嫩，有利于病害感染。病菌发育温度15-38℃，最适25℃，雷山县同济堂淫羊藿药材基地一般4月下旬开始发病，危害严重期6-9月。赤水市2011年4月下旬在野生淫羊藿上发现此病发生。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004953', 'source-doc-4c784a84a66adf221597', 'source-node-004949', '3', '4952', 'text', '防治方法：①及时清除病残体并销毁，减少浸染源。②发病初期可施药防治，常用药剂有50%代森锌可湿性粉剂600倍，50%退菌特可湿性粉剂800倍液，1:1:160波尔多液，30%氧氯化铜600-800倍液，50%多菌灵可湿性粉剂500-600倍液，70%甲基托布津可湿性粉剂800-1000倍液，75%百菌清可湿性粉剂500-600倍液。上述药剂应交替使用，以免产生抗药性。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004954', 'source-doc-4c784a84a66adf221597', 'source-node-004948', '2', '4953', 'text', '淫羊藿皱缩病毒病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004955', 'source-doc-4c784a84a66adf221597', 'source-node-004954', '3', '4954', 'text', '症状：苗床幼苗期。染病叶常表现为叶组织皱缩，不平，增厚，畸形呈反卷状，成苗期，田间常有2种症状：花叶斑驳状：病叶扭曲畸变皱缩不平增厚呈浓淡绿色不均匀的斑驳花叶状。黄色斑驳花叶状：染病叶组织退绿呈黄色花叶斑状。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004956', 'source-doc-4c784a84a66adf221597', 'source-node-004954', '3', '4955', 'text', '病原：淫羊藿皱缩病毒病由病毒感染引起。该病害可通过虫媒、摩擦等方式传播。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004957', 'source-doc-4c784a84a66adf221597', 'source-node-004954', '3', '4956', 'text', '发病特点：2010-2011年在雷山、修文等地发现。在淫羊藿生长期此病均有发生。苗床育苗期此病多发生较重。成苗期此病田间发生分散，危害较轻。病毒病通常是通过蚜虫、叶蝉、蓟马、飞虱等虫媒或摩擦等方式传播。染病株叶部叶绿素受阻，正常光合作用受到影响，影响产量、质量。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004958', 'source-doc-4c784a84a66adf221597', 'source-node-004954', '3', '4957', 'text', '防治方法：①选用无病毒病的种苗留种。②在续断生长期，及时灭杀传毒虫媒。③发病症状出现时，若需施药防治，可选用磷酸二氢钾或20%毒克星可湿性粉剂500倍液，或0.5%抗毒剂1号水剂250-300倍液，或20%病毒宁水溶性粉剂500倍液等喷洒，隔7天1次，连用3次。促叶片转绿、舒展，减轻为害。采收前20天停止用药。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004959', 'source-doc-4c784a84a66adf221597', 'source-node-004948', '2', '4958', 'text', '淫羊藿锈病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004960', 'source-doc-4c784a84a66adf221597', 'source-node-004959', '3', '4959', 'text', '症状：病菌为害淫羊藿叶片，果实等。患病叶，初期叶片上出现不明显的小点，后期叶背面变成橙黄色微突起的小疮斑，即为夏孢子堆。病斑破裂后散发锈黄色的夏孢子，严重时叶片枯死；患病果实出现橙黄色微突起的小疮斑，严重时患病果实成僵果。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004961', 'source-doc-4c784a84a66adf221597', 'source-node-004959', '3', '4960', 'text', '病原：淫羊藿锈病病源为双胞锈菌属，淫羊藿锈病夏孢子椭圆形、单胞。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004962', 'source-doc-4c784a84a66adf221597', 'source-node-004959', '3', '4961', 'text', '发病条件：2008-2012年在贵州雷山县调查，淫羊藿野生抚育基地每年4-5月有锈病发生，但危害不严重。病菌转主寄生及生活史不详。以冬孢子在病残体上越冬，以夏孢子辗转传播蔓延。高温、高湿条件易诱发该病。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004963', 'source-doc-4c784a84a66adf221597', 'source-node-004959', '3', '4962', 'text', '防治方法：①清洁田园，加强管理。②清除转主寄主。③发病期，可选用15%粉锈宁可湿性粉剂1000-1500倍液，', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004964', 'source-doc-4c784a84a66adf221597', 'source-node-004948', '2', '4963', 'text', '淫羊藿白粉病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004965', 'source-doc-4c784a84a66adf221597', 'source-node-004964', '3', '4964', 'text', '症状：危害淫羊藿的叶片。发病初期，叶片正面或背面产生白色近圆形的小粉斑，逐渐扩大成边缘不明显的大片白粉区，布满叶面，好像撒了层白粉。抹去白粉，可见叶面褪绿，枯黄变脆。发病严重时，叶面布满白粉，变成灰白色，直至整个叶片枯死。发病后无臭味，白粉是其明显病征。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004966', 'source-doc-4c784a84a66adf221597', 'source-node-004964', '3', '4965', 'text', '病原：淫羊藿白粉病为粉孢属真菌。分生孢子被风传播到幼嫩组织上，在适宜的环境条件下萌发，并通过角质层和表皮细胞壁进入表皮细胞进行危害。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004967', 'source-doc-4c784a84a66adf221597', 'source-node-004964', '3', '4966', 'text', '发病特点：白粉病一般在温暖、干燥或潮湿的环境易发病，降雨则不利于病害发生。施氮肥过多，土壤缺少钙或钾肥时易发该病，植株过密，通风透光不良，发病严重。温度变化剧烈，土壤过干等，都将减弱植物的抗病能力，而有利于病害的发生。2011年7月在贵州雷山县调查，淫羊藿野生抚育基地有此病发生，但危害不重。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004968', 'source-doc-4c784a84a66adf221597', 'source-node-004964', '3', '4967', 'text', '防治方法：①清洁田园，加强管理。②发病期，可选用50%多菌灵500倍液或75%甲基硫菌灵1000倍液喷雾。病害盛发时，可喷15%粉锈宁1000倍液等药剂喷施防治。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004969', 'source-doc-4c784a84a66adf221597', 'source-node-004948', '2', '4968', 'text', '淫羊藿生理性红叶病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004970', 'source-doc-4c784a84a66adf221597', 'source-node-004969', '3', '4969', 'text', '症状：此病通常在无遮荫的暴露地出现。叶部退绿变色呈红色状，植株生长受阻，矮小。苗床期受害严重者植株可出现早死亡。成苗期受害植株变色后虽然一般不死亡但新生芽较少，影响生物产量，减产显著。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004971', 'source-doc-4c784a84a66adf221597', 'source-node-004969', '3', '4970', 'text', '病原：生理性病害，在无遮荫的暴露地出现。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004972', 'source-doc-4c784a84a66adf221597', 'source-node-004969', '3', '4971', 'text', '发病特点：在雷山淫羊藿基地2010年调查，只要在无遮荫的暴露地种植淫羊藿，此病全年均出现，但育苗期受害较重，一些长势差苗受害会被致枯死亡。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004973', 'source-doc-4c784a84a66adf221597', 'source-node-004969', '3', '4972', 'text', '防治方法：①遮阴育苗。②基地种植，选择在杨梅树，松树等乔木下遮荫栽种。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-004974', 'source-doc-4c784a84a66adf221597', NULL, '0', '4973', 'text', '2.6 盆景/景观/苗木/花卉/山茶/茶树', '[]');
