INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-005005', 'source-doc-4c784a84a66adf221597', 'source-node-005004', '2', '5004', 'text', '炭疽病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-005006', 'source-doc-4c784a84a66adf221597', 'source-node-005005', '3', '5005', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-005007', 'source-doc-4c784a84a66adf221597', 'source-node-005006', '4', '5006', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-005008', 'source-doc-4c784a84a66adf221597', 'source-node-005005', '3', '5007', 'text', '病症多出现于叶缘、叶尖和叶脉两侧，初现暗绿色斑纹，后逐渐扩大成不规则大斑，颜色由褐色变为黑色，严重时扩散到整个叶片，引起大量落叶', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-005009', 'source-doc-4c784a84a66adf221597', 'source-node-005005', '3', '5008', 'text', '解决方法：清除病叶，每周用苯甲吡唑酯喷洒一次，连续喷 3 - 4 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-005010', 'source-doc-4c784a84a66adf221597', 'source-node-005004', '2', '5009', 'text', '灰斑病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-005011', 'source-doc-4c784a84a66adf221597', 'source-node-005010', '3', '5010', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-005012', 'source-doc-4c784a84a66adf221597', 'source-node-005011', '4', '5011', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-005013', 'source-doc-4c784a84a66adf221597', 'source-node-005010', '3', '5012', 'text', '新梢受害初期出现长形病斑，浅褐色、水渍状，后逐渐凹陷、缢缩，出现不连续的小纵裂而成溃疡斑。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-005014', 'source-doc-4c784a84a66adf221597', 'source-node-005010', '3', '5013', 'text', '解决方法：强培育管理、合理施肥、及时修剪，避免茶花林地过于荫蔽，做到通风透光。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-005015', 'source-doc-4c784a84a66adf221597', 'source-node-005004', '2', '5014', 'text', '枯枝病', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-005016', 'source-doc-4c784a84a66adf221597', 'source-node-005015', '3', '5015', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-005017', 'source-doc-4c784a84a66adf221597', 'source-node-005016', '4', '5016', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-005018', 'source-doc-4c784a84a66adf221597', 'source-node-005015', '3', '5017', 'text', '受害枝条坏死，叶片由绿变为淡黄，从顶部向下逐渐干枯脱落，最后整个枝梢干枯死亡。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-005019', 'source-doc-4c784a84a66adf221597', 'source-node-005015', '3', '5018', 'text', '解决方法：剪除病枝、并喷施苯甲吡唑酯或苯甲醚菌酯。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-005020', 'source-doc-4c784a84a66adf221597', 'source-node-005004', '2', '5019', 'text', '蚜虫', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-005021', 'source-doc-4c784a84a66adf221597', 'source-node-005020', '3', '5020', 'text', '吸取嫩芽里面的营养和水分，导致新芽水分营养不足，停止生长，甚至出现严重的卷曲变形现象。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-005022', 'source-doc-4c784a84a66adf221597', 'source-node-005020', '3', '5021', 'text', '解决方法：喷洒杀虫 1 号，3 - 5 天一次，连续喷洒 3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-005023', 'source-doc-4c784a84a66adf221597', 'source-node-005004', '2', '5022', 'text', '蚧壳虫', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-005024', 'source-doc-4c784a84a66adf221597', 'source-node-005023', '3', '5023', 'text', '蚧壳虫的成虫在叶背或茎秆处出现大量白色不动的小虫。当介壳虫较多时还会造成煤污病，即叶面或嫩茎上出现大片黑色的污迹。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-005025', 'source-doc-4c784a84a66adf221597', 'source-node-005023', '3', '5024', 'text', '解决方法：阳台种植的先用湿纸巾擦干净，喷洒杀虫 1 号，3 - 5 天一次，连续喷洒 3 次。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-005026', 'source-doc-4c784a84a66adf221597', 'source-node-005004', '2', '5025', 'text', '红蜘蛛', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-005027', 'source-doc-4c784a84a66adf221597', 'source-node-005026', '3', '5026', 'text', '被红蜘蛛所害叶子发黄，出现许多小白点，不久枯黄脱落。常在高温低湿的环境中滋生。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-005028', 'source-doc-4c784a84a66adf221597', 'source-node-005026', '3', '5027', 'text', '解决方法：阳台种植的用清水冲洗叶片，使用乙螨唑对着叶片喷施，3 天一次，连续使用 3 次左右。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-005029', 'source-doc-4c784a84a66adf221597', 'source-node-005004', '2', '5028', 'text', '锈壁虱', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-005030', 'source-doc-4c784a84a66adf221597', 'source-node-005029', '3', '5029', 'text', '图片', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-005031', 'source-doc-4c784a84a66adf221597', 'source-node-005030', '4', '5030', 'text', '', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-005032', 'source-doc-4c784a84a66adf221597', 'source-node-005029', '3', '5031', 'text', '幼龄茶花叶片表面发黄，背面出现赤褐色斑点的时候，很可能是感染了锈壁虱。', '[]');
INSERT INTO source_document_nodes (id, document_id, parent_id, depth, sort_order, node_type, text_content, image_urls_json) VALUES ('source-node-005033', 'source-doc-4c784a84a66adf221597', 'source-node-005029', '3', '5032', 'text', '解决方法：阳台栽培的加强环境通风、避免盆土长期处于干燥状态、及时清理病枝并用阿维菌素等杀虫药喷施除虫。', '[]');
